globalThis.ANDE_CHUNKS["fd8c6da268fcdf0bced370451fcbdb7b86fb9e575e3c30e3d52b7f5f8c7e45ab"] = [{"id":"meituan_social:4639967033","sourceKey":"meituan_social","company":"美团","title":"沙特配送策略分析","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4639967033&jobShareType=1","duty":"1、承接周报、月报相关指标异动分析工作，总结业务规律，发现业务问题，提出解决策略，推进业务问题改善；\n2、制定和跟进业务目标，拆解目标达成路径，持续跟进及复盘；\n3、根据业务发展和分析需求，推动相关数据基建，搭建和迭代监控看板及指标体系；\n4、进行市场研究，深入了解配送行业规则和市场态势，紧跟市场动向，为业务管理者提供行业预判。","requirements":"1、3年以上工作经验，有互联网/即时配送物流等相关行业商业分析经验优先；\n2、项目管理和跨部门合作能力，能够完成项目的规划和执行； \n3、逻辑清晰，思维框架完整，具备优秀的数据分析能力，熟悉常用统计理论与分析方法，从数据中发现业务痛点并提出应对策略； \n4、自我驱动力极强，韧性极强，积极主动，且善于团队合作;\n5、善于独立思考，喜欢钻研，拥有较强的学习兴趣，能快速熟悉陌生工作领域； \n6、具备较好的口头和书面沟通能力。","description":"部门介绍\nKeeta是全球领先外卖平台美团旗下的独立品牌，肩负着“帮大家吃得更好，生活更好”的使命。依托美团深耕中国市场15年的技术与运营积淀，我们正引领全球餐饮与商品即时配送服务的创新与发展。\n\n自2023年成立以来，Keeta始终扎根社区并创造价值。我们为用户提供可靠的外卖体验，以智慧技术助餐厅提升经营效率，在为骑手拓宽收入来源的同时，也充分提供安全保障措施。基于这份多方共赢、共同成长的理念，我们的业务已从中国香港稳步拓展至中东及巴西，并持续向世界迈进。\n\n岗位职责\n1、承接周报、月报相关指标异动分析工作，总结业务规律，发现业务问题，提出解决策略，推进业务问题改善；\n2、制定和跟进业务目标，拆解目标达成路径，持续跟进及复盘；\n3、根据业务发展和分析需求，推动相关数据基建，搭建和迭代监控看板及指标体系；\n4、进行市场研究，深入了解配送行业规则和市场态势，紧跟市场动向，为业务管理者提供行业预判。\n\n岗位基本要求\n1、3年以上工作经验，有互联网/即时配送物流等相关行业商业分析经验优先；\n2、项目管理和跨部门合作能力，能够完成项目的规划和执行； \n3、逻辑清晰，思维框架完整，具备优秀的数据分析能力，熟悉常用统计理论与分析方法，从数据中发现业务痛点并提出应对策略； \n4、自我驱动力极强，韧性极强，积极主动，且善于团队合作;\n5、善于独立思考，喜欢钻研，拥有较强的学习兴趣，能快速熟悉陌生工作领域； \n6、具备较好的口头和书面沟通能力。\n\n岗位亮点\n境外业务为美团探索境外市场的先锋力量，配送商业分析组主要负责境外外卖配送业务的商业分析工作。在这里既可以快速学习到国内先进外卖配送经验、经历新业务从0到1的过程，还可以积累宝贵的境外业务经验。个人能力积累方向更为全面，且未来职业发展的机会更多。欢迎对外卖配送、O2O、境外业务感兴趣的人才加入~","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4600985708","sourceKey":"meituan_social","company":"美团","title":"Keeta-阿联酋商业分析专家","city":"北京市/迪拜","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4600985708&jobShareType=1","duty":"1）建设并完善经营管理体系，覆盖指标体系搭建、目标管理、数据监控、结果复盘、专题分析等；\n2）支持国家进行用户增长分析和讨论，结合数据分析及物理世界用户、商家调研，识别机会和风险，沉淀业务认知，并形成关键判断；\n3）针对业务经营的重点、难点展开专题研究，输出有洞察力的分析结论，推动关键策略落地及效果衡量，以业务价值创造为导向开展工作","requirements":"1）大学本科以上学历，有大型互联网企业工作经验，英文可作为工作语言者优先考虑。\n2）至少3年以上商业分析领域工作经验，交易类业务、用户分析、数据科学经验者优先\n3）具备很强的商业认知和跨团队协同能力，丰富的团队管理经验和问题解决能力","description":"部门介绍\nKeeta是全球领先外卖平台美团旗下的独立品牌，肩负着“帮大家吃得更好，生活更好”的使命。依托美团深耕中国市场15年的技术与运营积淀，我们正引领全球餐饮与商品即时配送服务的创新与发展。\n\n自2023年成立以来，Keeta始终扎根社区并创造价值。我们为用户提供可靠的外卖体验，以智慧技术助餐厅提升经营效率，在为骑手拓宽收入来源的同时，也充分提供安全保障措施。基于这份多方共赢、共同成长的理念，我们的业务已从中国香港稳步拓展至中东及巴西，并持续向世界迈进。\n\n岗位职责\n1）建设并完善经营管理体系，覆盖指标体系搭建、目标管理、数据监控、结果复盘、专题分析等；\n2）支持国家进行用户增长分析和讨论，结合数据分析及物理世界用户、商家调研，识别机会和风险，沉淀业务认知，并形成关键判断；\n3）针对业务经营的重点、难点展开专题研究，输出有洞察力的分析结论，推动关键策略落地及效果衡量，以业务价值创造为导向开展工作\n\n岗位基本要求\n1）大学本科以上学历，有大型互联网企业工作经验，英文可作为工作语言者优先考虑。\n2）至少3年以上商业分析领域工作经验，交易类业务、用户分析、数据科学经验者优先\n3）具备很强的商业认知和跨团队协同能力，丰富的团队管理经验和问题解决能力\n\n岗位亮点\n1） 境外业务发展快，空间大\n2） 核心岗位影响力大，直接参与到业务目标策略制定，贴近业务，落地性强\n3） 深度了解外卖业务运作机制，跨部门协同作战，提升综合能力","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4669381387","sourceKey":"meituan_social","company":"美团","title":"美团骑行-电单秩序管理策略","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4669381387&jobShareType=1","duty":"负责推进电单业务在秩序方面的问题监控、诊断、策略和能力建设，提升治理者满意度\n1、负责电单业务在秩序清摆&防扣方面的预算、管理、考核等规划，逐步提升秩序成本使用效率；\n2、负责推进电单业务在秩序清淤、摆车、防扣和治理者响应等方面的线上化能力建设，提高各类经营指标；\n3、从指标异常入手，定期走访一线，了解业务真实痛点并输出解决方案。联动发展部等部门获取治理者满意度并反馈至策略及考核。\n4、运用AI工具提升治理效率，把个人洞察能力沉淀用可复制的AI能力。","requirements":"本科及以上学历，3年以上互联网运营或数据分析相关工作经验\n• 能独立做数据分析，从数据中识别异常并做多层归因拆解\n• 有策略落地的完整闭环经验——从\"发现问题\"到\"设计方案\"到\"推动执行\"到\"验证效果","description":"部门介绍\n美团骑行事业部在全国各个城市开展美团单车、电单车业务，提供绿色、便捷的共享出行服务，是美团出行板块重要的组成部分。我们力求为城市可持续发展提供低碳智能的解决方案，通过技术创新和硬件升级，不断优化全流程骑行体验，为低碳出行提供更好的服务。其中，美团单车旨在为城市居民提供通勤接驳服务，满足用户短途接驳出行需求；美团电单车则满足用户中短途多场景低碳出行需求。\n我们有开放的工作氛围，也有充满韧劲和创造力，心系低碳出行的伙伴。加入我们，一起为用户创造更好的出行体验。\n\n岗位职责\n负责推进电单业务在秩序方面的问题监控、诊断、策略和能力建设，提升治理者满意度\n1、负责电单业务在秩序清摆&防扣方面的预算、管理、考核等规划，逐步提升秩序成本使用效率；\n2、负责推进电单业务在秩序清淤、摆车、防扣和治理者响应等方面的线上化能力建设，提高各类经营指标；\n3、从指标异常入手，定期走访一线，了解业务真实痛点并输出解决方案。联动发展部等部门获取治理者满意度并反馈至策略及考核。\n4、运用AI工具提升治理效率，把个人洞察能力沉淀用可复制的AI能力。\n\n岗位基本要求\n本科及以上学历，3年以上互联网运营或数据分析相关工作经验\n• 能独立做数据分析，从数据中识别异常并做多层归因拆解\n• 有策略落地的完整闭环经验——从\"发现问题\"到\"设计方案\"到\"推动执行\"到\"验证效果\n\n具备以下条件优先\n有AI工具使用经验优先，愿意在治理场景中探索AI应用，用技术手段提升工作效率\n\n岗位亮点\n1、能够深入参与业务关键环节，直接为业务结果负责。\n2、面临复杂问题各类特殊场景，快速沉淀个人能力","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4428189649","sourceKey":"meituan_social","company":"美团","title":"Agent 开发工程师","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4428189649&jobShareType=1","duty":"1. 负责 AI Agent 系统的架构设计与核心模块开发，包括任务规划、工具调用（Tool Use / MCP）、记忆管理、多 Agent 协同等能力建设\n2. 深度参与 LLM 集成与推理链路优化，研究 Prompt Engineering、Function Calling、RAG 等关键技术在生产环境的落地\n3. 设计并实现 Agent 框架的核心组件（Planner、Executor、Evaluator），保障系统的稳定性、可观测性和可扩展性\n4. 与业务团队密切合作，将 Agent 能力落地到具体场景，推动从 demo 到生产环境的全流程工程化\n5. 持续跟踪 AI Agent 领域前沿进展，将有价值的技术方案引入团队任职要求","requirements":"1. 本科及以上学历，计算机相关专业，3年以上后端或 AI 工程开发经验\n2. 扎实的工程基础，熟悉 Python / Java / Go 至少一门，能写出高质量、可维护的代码\n3. 有 LLM 应用开发实际经验，熟悉 OpenAI / Anthropic / 主流开源模型的 API 使用，了解 Function Calling、Tool Use 机制\n4. 有 Agent 框架开发或使用经验（LangGraph、AutoGen、CrewAI、或自研框架），理解 ReAct / Plan-and-Execute 等 Agent 范式\n5. 熟悉 RAG 系统设计，包括向量检索、知识库构建、上下文管理等\n6. 有生产级 AI 系统落地经验，了解 Prompt 版本管理、Trace/Log 可观测性、评估体系建设等工程实践","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n1. 负责 AI Agent 系统的架构设计与核心模块开发，包括任务规划、工具调用（Tool Use / MCP）、记忆管理、多 Agent 协同等能力建设\n2. 深度参与 LLM 集成与推理链路优化，研究 Prompt Engineering、Function Calling、RAG 等关键技术在生产环境的落地\n3. 设计并实现 Agent 框架的核心组件（Planner、Executor、Evaluator），保障系统的稳定性、可观测性和可扩展性\n4. 与业务团队密切合作，将 Agent 能力落地到具体场景，推动从 demo 到生产环境的全流程工程化\n5. 持续跟踪 AI Agent 领域前沿进展，将有价值的技术方案引入团队任职要求\n\n岗位基本要求\n1. 本科及以上学历，计算机相关专业，3年以上后端或 AI 工程开发经验\n2. 扎实的工程基础，熟悉 Python / Java / Go 至少一门，能写出高质量、可维护的代码\n3. 有 LLM 应用开发实际经验，熟悉 OpenAI / Anthropic / 主流开源模型的 API 使用，了解 Function Calling、Tool Use 机制\n4. 有 Agent 框架开发或使用经验（LangGraph、AutoGen、CrewAI、或自研框架），理解 ReAct / Plan-and-Execute 等 Agent 范式\n5. 熟悉 RAG 系统设计，包括向量检索、知识库构建、上下文管理等\n6. 有生产级 AI 系统落地经验，了解 Prompt 版本管理、Trace/Log 可观测性、评估体系建设等工程实践\n\n具备以下条件优先\n• 有 MCP（Model Context Protocol）协议开发或集成经验\n• 有多 Agent 协同、Agent 编排系统设计经验\n• 对大数据或数据开发工具链有了解（了解即可，非必要）\n• 参与过开源 Agent 项目，或有自己的相关作品\n\n岗位亮点\n1. 参与前沿AI Agent技术研发，推动智能化应用落地。  \n2. 与高水平团队共同成长，提供广阔的技术发展空间。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4711626275","sourceKey":"meituan_social","company":"美团","title":"闪电仓CKA商家运营-东部","city":"上海市/杭州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4711626275&jobShareType=1","duty":"1.经营分析诊断。能够识别品牌优劣势，并以货盘-品类-商品的视角洞察机会点与问题点；\n2.业务策略制定。擅长品类运营，以商品为最小策略单元，共建品牌策略方案，驱动品牌GMV增长与经营改善；\n3.多方资源整合。清晰了解品牌、门店、上游厂商、平台的资源空间，并依托业务策略及产品工具整合营销方案。\n4.项目管理能力。基于经营目标及业务策略，以项目制形式拆解、推进、复盘，并识别风险、及时应对。\n\n能力要求：\n1. 品类诊断与策略制定：基于商家分品类盈利逻辑，对商家运营能力在结果层（店单产/利润/周转）+和过程层（哪些行为差异导致了结果差异）做两层解构，识别商家的优势类目，并以共建的形式输出差异化策略。\n2.商品运营：结合热搜词趋势、季节/场景变化，指导商家选品上新与货盘结构优化，并推动策略落地，追踪ROI和转化效果。\n3.流量运营与营销资源整合：体系化使用平台流量工具（神券/神价/广告/首页推荐等），以及自营销工具（折扣品/爆品），能够诊断流量机会点并整合多方资源形成合力。\n4.经营目标共识与落地闭环：以服务报告作为沟通载体，与商家共识经营目标（增长/增收/降本/提效等），测算收益空间，并结合业务策略建立常态化追踪复盘机制。","requirements":"1.本科及以上学历，3年以上零售行业经验。\n2.懂经营：能讲清楚不同品类的毛利结构、周转逻辑、定价策略等；\n3.懂数据：熟练使用BI工具进行经营分析，能独立完成从数据-洞察-策略全链路工作；\n4.懂商家：服务过连锁品牌或区域头部商家，知道怎么跟商家\"谈生意\"而不是\"传通知\"；\n5.优先项：①.有前置仓/便利店/闪电仓等近场零售业态的品类运营/商品经验；②.快消品类（食品饮料/日百/个护）的选品或采购背景；③.有大客户BD或KA管理经验，能独立推进跨部门协作。","description":"部门介绍\n美团闪购是美团旗下的即时零售平台，依托即时配送能力，连接本地零售供给，满足消费者30分钟万物到家的即时需求。美团闪购涵盖超市便利、食材、水果、鲜花绿植、休闲零食、酒水饮料、数码家电、美妆个护、母婴玩具、日用百货、服饰鞋帽、宠物等诸多品类，业务覆盖全国近3,000个县市区旗，每日百万级在岗骑手，以高效的配送、丰富的品类和广泛的覆盖，为美团数亿用户带来便捷的生活体验，积极助力实体零售线上化转型，提升本地商业活力。\n\n岗位职责\n1.经营分析诊断。能够识别品牌优劣势，并以货盘-品类-商品的视角洞察机会点与问题点；\n2.业务策略制定。擅长品类运营，以商品为最小策略单元，共建品牌策略方案，驱动品牌GMV增长与经营改善；\n3.多方资源整合。清晰了解品牌、门店、上游厂商、平台的资源空间，并依托业务策略及产品工具整合营销方案。\n4.项目管理能力。基于经营目标及业务策略，以项目制形式拆解、推进、复盘，并识别风险、及时应对。\n\n能力要求：\n1. 品类诊断与策略制定：基于商家分品类盈利逻辑，对商家运营能力在结果层（店单产/利润/周转）+和过程层（哪些行为差异导致了结果差异）做两层解构，识别商家的优势类目，并以共建的形式输出差异化策略。\n2.商品运营：结合热搜词趋势、季节/场景变化，指导商家选品上新与货盘结构优化，并推动策略落地，追踪ROI和转化效果。\n3.流量运营与营销资源整合：体系化使用平台流量工具（神券/神价/广告/首页推荐等），以及自营销工具（折扣品/爆品），能够诊断流量机会点并整合多方资源形成合力。\n4.经营目标共识与落地闭环：以服务报告作为沟通载体，与商家共识经营目标（增长/增收/降本/提效等），测算收益空间，并结合业务策略建立常态化追踪复盘机制。\n\n岗位基本要求\n1.本科及以上学历，3年以上零售行业经验。\n2.懂经营：能讲清楚不同品类的毛利结构、周转逻辑、定价策略等；\n3.懂数据：熟练使用BI工具进行经营分析，能独立完成从数据-洞察-策略全链路工作；\n4.懂商家：服务过连锁品牌或区域头部商家，知道怎么跟商家\"谈生意\"而不是\"传通知\"；\n5.优先项：①.有前置仓/便利店/闪电仓等近场零售业态的品类运营/商品经验；②.快消品类（食品饮料/日百/个护）的选品或采购背景；③.有大客户BD或KA管理经验，能独立推进跨部门协作。\n\n具备以下条件优先\n有品类/商品运营、中台供给运营相关能力的优先\n\n岗位亮点\n闪电仓是美团即时零售战略的核心业态，行业年增速超30%，正处于从\"跑马圈地\"到\"精细化运营\"的黄金窗口期","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4703276025","sourceKey":"meituan_social","company":"美团","title":"鲜蛋和蛋制品-招商采购","city":"西安市/重庆市/南宁市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4703276025&jobShareType=1","duty":"1. 负责鲜蛋及蛋制品类商品的招商工作，开发并维护优质供应商资源。  \n2. 根据市场需求和采购计划，执行商品采购、价格谈判及合同签订。  \n3. 监控商品库存、销售数据及市场动态，优化采购策略与供应链效率。  \n4. 协同品控、物流等团队，确保商品质量与交付时效符合公司标准。","requirements":"1. 大学专科及以上学历，专业不限，有生鲜或快消品行业背景优先。  \n2. 具备3年以上采购或招商相关工作经验，熟悉鲜蛋及蛋制品供应链。  \n3. 具备良好的商务谈判能力、数据分析能力和跨部门沟通协作能力。  \n4. 能适应在西安、重庆、南宁等城市灵活办公或出差。","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1. 负责鲜蛋及蛋制品类商品的招商工作，开发并维护优质供应商资源。  \n2. 根据市场需求和采购计划，执行商品采购、价格谈判及合同签订。  \n3. 监控商品库存、销售数据及市场动态，优化采购策略与供应链效率。  \n4. 协同品控、物流等团队，确保商品质量与交付时效符合公司标准。\n\n岗位基本要求\n1. 大学专科及以上学历，专业不限，有生鲜或快消品行业背景优先。  \n2. 具备3年以上采购或招商相关工作经验，熟悉鲜蛋及蛋制品供应链。  \n3. 具备良好的商务谈判能力、数据分析能力和跨部门沟通协作能力。  \n4. 能适应在西安、重庆、南宁等城市灵活办公或出差。\n\n具备以下条件优先\n具有美菜,盒马，京东等平台经验优先。\n\n岗位亮点\n1. 加入快速发展的生鲜零售平台，参与核心品类供应链建设。  \n2. 提供完善的培训体系与清晰的职业发展路径。  \n3. 团队氛围开放，鼓励创新与结果导向的工作方式。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4724097702","sourceKey":"meituan_social","company":"美团","title":"小象超市-体验优化专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4724097702&jobShareType=1","duty":"1、洞察用户体验的痛点和需求，诊断问题并提出系统性的解决方案，通过优化规则、流程和产品功能等方式，提升用户体验；\n2、基于对业务和用户的理解，针对核心问题开展体验专项，结合走查、调研、分析等形式，完成深入洞察和优化建议，并推动优化策略落地；\n3、与业务建立良好的合作关系，通过建立有效的运营机制，驱动上下游改善体验问题；\n4、主动探索AI在体验优化领域的应用场景（如智能NPS分析、评论情感挖掘、用户行为预测等），推动团队AI工具的应用和效率提升，建立AI赋能的体验优化方法论；\n5、运用AI工具（NPS分析、文本挖掘、用户行为建模等）系统性诊断用户体验痛点与机会点，构建量化评估指标体系，实现体验问题的自动发现与优先级排序。","requirements":"1、5年以上用户体验、零售运营、服务管理相关经验，有即时零售/同城电商/O2O背景优先。具备多项目并行管理并有效落地的能力；\n2、具备数据驱动思维，能借助AI工具（NPS分析、文本挖掘、用户行为建模等）发现规律、量化问题，有实际AI应用经验者优先；\n3、系统性思维与破局能力，能识别复杂业务中体验与效率的平衡点，找到可落地的优化路径；\n4、优秀的跨部门协作能力，推动力强，能从全局最优出发驱动跨团队合作与策略落地；\n5、具备AI提效意识，主动将AI工具融入日常工作，持续探索用技术手段提升体验运营效率；\n6、精通NPS分析、文本挖掘、用户行为建模等AI工具，有实际AI应用经验，能够独立完成从数据采集到洞察输出的全流程工作。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1、洞察用户体验的痛点和需求，诊断问题并提出系统性的解决方案，通过优化规则、流程和产品功能等方式，提升用户体验；\n2、基于对业务和用户的理解，针对核心问题开展体验专项，结合走查、调研、分析等形式，完成深入洞察和优化建议，并推动优化策略落地；\n3、与业务建立良好的合作关系，通过建立有效的运营机制，驱动上下游改善体验问题；\n4、主动探索AI在体验优化领域的应用场景（如智能NPS分析、评论情感挖掘、用户行为预测等），推动团队AI工具的应用和效率提升，建立AI赋能的体验优化方法论；\n5、运用AI工具（NPS分析、文本挖掘、用户行为建模等）系统性诊断用户体验痛点与机会点，构建量化评估指标体系，实现体验问题的自动发现与优先级排序。\n\n岗位基本要求\n1、5年以上用户体验、零售运营、服务管理相关经验，有即时零售/同城电商/O2O背景优先。具备多项目并行管理并有效落地的能力；\n2、具备数据驱动思维，能借助AI工具（NPS分析、文本挖掘、用户行为建模等）发现规律、量化问题，有实际AI应用经验者优先；\n3、系统性思维与破局能力，能识别复杂业务中体验与效率的平衡点，找到可落地的优化路径；\n4、优秀的跨部门协作能力，推动力强，能从全局最优出发驱动跨团队合作与策略落地；\n5、具备AI提效意识，主动将AI工具融入日常工作，持续探索用技术手段提升体验运营效率；\n6、精通NPS分析、文本挖掘、用户行为建模等AI工具，有实际AI应用经验，能够独立完成从数据采集到洞察输出的全流程工作。\n\n具备以下条件优先\n用户体验、零售运营、服务管理相关经验，有即时零售/同城电商/O2O背景优先。有AI工具（如Python数据分析、NLP文本处理、机器学习建模）的实际应用经验优先。\n\n岗位亮点\n1、机遇挑战：深度参与业务核心链路的关键环节；\n2、团队氛围：开放和直接的沟通环境，结果导向，强调合作共赢；\n3、个人成长：不设限的工作空间，开放的学习平台。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4474257706","sourceKey":"meituan_social","company":"美团","title":"收单线上渠道经理","city":"成都市/北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4474257706&jobShareType=1","duty":"1. 负责收单业务渠道（线上or线下）线索的拓展，并驱动线索端到端转化。\n2. 制定渠道合作策略，并落地拿到结果，推动业务落地与增长。  \n3.了解AI at work的基本模式和底层逻辑，能够利用AI 工具提效。","requirements":"1. 大学本科及以上学历，有AI应用经验优先。  \n2. 具备3年渠道拓展如地推、电销等相关工作经验。  \n3. 熟悉收单业务模式及行业生态，拥有良好的商务谈判与资源整合能力。  \n4. 具备较强的数据分析能力与跨部门协作能力，能独立推动项目落地。","description":"部门介绍\n美团餐饮系统为餐饮企业提供一站式IT解决方案，帮助餐饮商户实现从供应链管理、生产管理、前厅管理到外卖的数字化经营。美团餐饮系统不仅打通了餐厅和平台，更帮助餐厅连接客人，让商户更了解顾客需求，在帮助商户做商业决策的同时给顾客带来更好的消费体验。\n我们持续建设和提升产研、销售、服务的核心能力，通过全新升级的美团餐饮系统一体化软硬件产品，助力餐饮商户进行线上化经营，帮助商户在推广新店、提升效率、降低成本、会员营销、流量扶持、智慧选址、供应链管理等方面强化经营能力。团队汇集了餐饮和SaaS领域的优秀人才，秉持着“以客户为中心”的初心和“长期有耐心”的耕耘精神，求真、敬畏、敢于自我否定、善于快速学习。期待同样愿意长期致力于餐饮产业数字化、智能化的你加入我们的团队，共同进步共同成长！\n\n岗位职责\n1. 负责收单业务渠道（线上or线下）线索的拓展，并驱动线索端到端转化。\n2. 制定渠道合作策略，并落地拿到结果，推动业务落地与增长。  \n3.了解AI at work的基本模式和底层逻辑，能够利用AI 工具提效。\n\n岗位基本要求\n1. 大学本科及以上学历，有AI应用经验优先。  \n2. 具备3年渠道拓展如地推、电销等相关工作经验。  \n3. 熟悉收单业务模式及行业生态，拥有良好的商务谈判与资源整合能力。  \n4. 具备较强的数据分析能力与跨部门协作能力，能独立推动项目落地。\n\n具备以下条件优先\n有借助AI agent 驱动线索运营自动化实践者优先\n\n岗位亮点\n1. 参与公司核心支付业务，成长空间广阔。  \n2. 工作地点覆盖成都、北京，灵活性强。  \n3. 团队氛围开放，注重创新与结果导向。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4707466438","sourceKey":"meituan_social","company":"美团","title":"供应计划-数据专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4707466438&jobShareType=1","duty":"1、搭建供应链计划相关指标体系，深入供应链各环节，梳理需求及指标口径，包括计划、库存、履约等模块；\n2、业务分析与洞察：深入理解供应链业务流程，协同城市计划和品类计划对全盘计划进行统筹，制定和运营库存指标。通过日常监控、归因分析，联动协同方解决问题，并提出改进方案和有效措施，不断挖掘数据产品的潜在应用场景；\n3、看板开发与流程优化：针对数据相关需求，承接需求梳理->上线->运营的交付相关工作；\n4、项目支持，供应计划相关项目支持，挖掘有价值的业务建议；\n5、跨团队协作，与部门内外部协同方密切合作，推动数据能力的落地。","requirements":"1、本科及以上学历，3年以上供应链计划领域相关经验，熟练使用SQL、Python等工具优先；\n2、具备电商、快消行业从业经历者优先，掌握端到端的供应链管理方法；\n3、具备业务敏感度、结构化思维与数据分析能力；\n4、具备项目管理经验，能基于计划执行推动相关方完成相关动作的落地；\n5、出色的跨团队沟通能力，能清晰传递分析结论，并推动项目落地。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1、搭建供应链计划相关指标体系，深入供应链各环节，梳理需求及指标口径，包括计划、库存、履约等模块；\n2、业务分析与洞察：深入理解供应链业务流程，协同城市计划和品类计划对全盘计划进行统筹，制定和运营库存指标。通过日常监控、归因分析，联动协同方解决问题，并提出改进方案和有效措施，不断挖掘数据产品的潜在应用场景；\n3、看板开发与流程优化：针对数据相关需求，承接需求梳理->上线->运营的交付相关工作；\n4、项目支持，供应计划相关项目支持，挖掘有价值的业务建议；\n5、跨团队协作，与部门内外部协同方密切合作，推动数据能力的落地。\n\n岗位基本要求\n1、本科及以上学历，3年以上供应链计划领域相关经验，熟练使用SQL、Python等工具优先；\n2、具备电商、快消行业从业经历者优先，掌握端到端的供应链管理方法；\n3、具备业务敏感度、结构化思维与数据分析能力；\n4、具备项目管理经验，能基于计划执行推动相关方完成相关动作的落地；\n5、出色的跨团队沟通能力，能清晰传递分析结论，并推动项目落地。\n\n岗位亮点\n具有挑战性的业务场景，利于专业沉淀；有机会完成0-1的新能力建设。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4707496370","sourceKey":"meituan_social","company":"美团","title":"供应链计划规划专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4707496370&jobShareType=1","duty":"1、计划管理体系的迭代及运营：长期及短期的进销存计划制定，协同物流和计划，对计划偏差进行分析，持续改善计划的可执行性，提升全链路的运营效率；\n2、需求管理和产品协同：负责供应计划业务逻辑和产品逻辑迭代，承接相关的项目需求并协同各方进行进行需求梳理、可行性分析、上线验收及落地运营等；\n3、建立监测指标体系，及时发现并联动物流解决问题，提出改进方案和措施；\n4、协同城市计划和品类计划对全盘计划进行统筹，制定和运营库存指标；\n5、产品和流程优化：承接需求预测、库存策略、库存仿真、订货系统等计划相关产品/数据/应用需求，并承接需求梳理->上线->运营的相关工作；通过流程优化、专题项目、系统构建等方式提高链路的协同效率；\n5、上下游拉通，拉通算法、产品、计划运营、业务等各方共识，类项目管理的方式推进需求落地和产品功能上线。","requirements":"1、供应链计划产品实施经验，熟悉需求计划、库存计划、供应计划、s&op流程并具备实际运营经验，掌握端到端的供应链管理方法；\n2、能够明确对应模块关键业务的诉求，进行需求编写、流程设计、独立完成BRD并能将需求准确的传递后后端产品和研发部门；\n3、较好的项目管理能力和风险管理能力，保障实施交付落地；能基于计划执行推动相关方完成相关动作的落地；\n4、良好的数据处理能力；\n5、熟练使用SQL等数据提取工具；\n6、具备一定的团队管理相关经验。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1、计划管理体系的迭代及运营：长期及短期的进销存计划制定，协同物流和计划，对计划偏差进行分析，持续改善计划的可执行性，提升全链路的运营效率；\n2、需求管理和产品协同：负责供应计划业务逻辑和产品逻辑迭代，承接相关的项目需求并协同各方进行进行需求梳理、可行性分析、上线验收及落地运营等；\n3、建立监测指标体系，及时发现并联动物流解决问题，提出改进方案和措施；\n4、协同城市计划和品类计划对全盘计划进行统筹，制定和运营库存指标；\n5、产品和流程优化：承接需求预测、库存策略、库存仿真、订货系统等计划相关产品/数据/应用需求，并承接需求梳理->上线->运营的相关工作；通过流程优化、专题项目、系统构建等方式提高链路的协同效率；\n5、上下游拉通，拉通算法、产品、计划运营、业务等各方共识，类项目管理的方式推进需求落地和产品功能上线。\n\n岗位基本要求\n1、供应链计划产品实施经验，熟悉需求计划、库存计划、供应计划、s&op流程并具备实际运营经验，掌握端到端的供应链管理方法；\n2、能够明确对应模块关键业务的诉求，进行需求编写、流程设计、独立完成BRD并能将需求准确的传递后后端产品和研发部门；\n3、较好的项目管理能力和风险管理能力，保障实施交付落地；能基于计划执行推动相关方完成相关动作的落地；\n4、良好的数据处理能力；\n5、熟练使用SQL等数据提取工具；\n6、具备一定的团队管理相关经验。\n\n岗位亮点\n具有挑战性的业务场景，利于专业沉淀；有机会完成0-1的新能力建设。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4654383070","sourceKey":"meituan_social","company":"美团","title":"小象超市-品类计划专家（即食计划）","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4654383070&jobShareType=1","duty":"1、负责供应链品类计划：基于用户需求预测，输出品类备货计划，并通过持续提升计划准确度及备货弹性，保障商品稳定供给，提升用户体验；\n2、负责供应链产品优化：根据不同品类的独特发展需求及特点，建立全链路供应链优化及解决方案，沉淀策略并推进产品化，提升供应链计划自动化进程；\n3、负责供应链运营提效：通过管控输入及输出指标，监控库存现货率、周转、库龄，及时提出滞销、断货预警，识别风险点及机会点，提升现有供给链路效率；\n4、结合AI/大模型工具，持续优化需求预测模型和算法，推动计划决策从人工经验向数据智能演进；\n5、与算法、产品团队协同，探索AI Agent在库存预警、异常处置等场景的落地应用。","requirements":"1、具备创业精神，积极主动，有较强的自驱力和韧性；\n2、熟练掌握各类办公软件，具有较强的逻辑思考能力、数据分析能力、复杂问题的拆解能力；\n3、具备较强责任心、沟通、协同、推动影响力；\n4、2年以上供应计划工作经验；\n5、有大数据分析平台（如Spark/SQL）或AI工具（如ChatGPT/Copilot等）实际使用经验优先；对智能化供应链有探索热情。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1、负责供应链品类计划：基于用户需求预测，输出品类备货计划，并通过持续提升计划准确度及备货弹性，保障商品稳定供给，提升用户体验；\n2、负责供应链产品优化：根据不同品类的独特发展需求及特点，建立全链路供应链优化及解决方案，沉淀策略并推进产品化，提升供应链计划自动化进程；\n3、负责供应链运营提效：通过管控输入及输出指标，监控库存现货率、周转、库龄，及时提出滞销、断货预警，识别风险点及机会点，提升现有供给链路效率；\n4、结合AI/大模型工具，持续优化需求预测模型和算法，推动计划决策从人工经验向数据智能演进；\n5、与算法、产品团队协同，探索AI Agent在库存预警、异常处置等场景的落地应用。\n\n岗位基本要求\n1、具备创业精神，积极主动，有较强的自驱力和韧性；\n2、熟练掌握各类办公软件，具有较强的逻辑思考能力、数据分析能力、复杂问题的拆解能力；\n3、具备较强责任心、沟通、协同、推动影响力；\n4、2年以上供应计划工作经验；\n5、有大数据分析平台（如Spark/SQL）或AI工具（如ChatGPT/Copilot等）实际使用经验优先；对智能化供应链有探索热情。\n\n具备以下条件优先\n1、具备较强数据统计以及分析能力，熟练使用SQL；\n2、参与过同类型业务，具备多门店库存管理经验优先；\n3、供应链管理、物流管理专业优先；\n4、乐观向上正能量者优先。\n\n岗位亮点\n1、供应链能力建设价值高：供给侧需要有无限接近和满足消费者的能力，对于需求计划，库存计划，补货管理专业能力建设；以及通过供应链条的整体优化最大化供给的弹性。这种能力区别于现在的远场电商/线下电商已有的供应链能力，也会成为未来即时零售的核心竞争力；\n2、小象供应链场景的复杂度能帮助在供应链专业上的深度拓展：供应链链路上的节点多，品类复杂，异常场景多等，都对供应链规划/计划/执行能力上有更高的要求，是很好的专业深度挑战；\n3、构建更宽广的职业发展图景：有机会全身心地参与新零售业态，在急速发展的业务当中，从0到1地建立对业务和产业的认知，能和电商、O2O、物流、零售、人工智能等多元化背景的团队一起，综合学习，共同进步；\n4、深度参与美团供应链AI化升级：在AI重塑供应链的关键窗口期，与算法/产品/技术团队共同探索智能计划体系，既有深度的供应链专业修炼，也有AI转型浪潮的先行视角。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4724398596","sourceKey":"meituan_social","company":"美团","title":"国际风控策略分析师","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4724398596&jobShareType=1","duty":"1、探索和落实AI及大模型技术在策略场景的应用，包括AI辅助特征挖掘、策略生成与仿真评估，推动策略体系向智能化演进；\n\n2、负责国际支付欺诈风险防控，减少公司资金损失，基于历史数据和专家经验，通过数据分析、数据挖掘和大模型能力，设计针对盗卡、盗账户等欺诈场景的风控策略并持续优化； \n\n3、平衡支付的体验和资损，设计、实施、监控风险-收益最大化的安全策略，保障业务健康发展； \n\n4、建立策略监控指标体系与数据报表体系，完善风险监控与预警机制，进行日常风险指标与策略、模型性能监控； \n\n5、联动产品、技术、算法等团队，建设风险引擎中台能力，设计和构建体系化的风控策略、流程与机制。","requirements":"1、熟悉大模型应用场景，能够将AI能力融入风控策略设计与迭代，具有AI+风控策略实践落地经验者优先；\n\n2、3年以上风控策略/数据分析经验，有国际支付或跨境风控经验者优先；本科及以上学历，计算机、数学、统计学、金融等相关专业，可使用中英文作为工作语言；\n\n3、熟练使用至少一种分析工具（SQL、Python、R等），具备扎实的策略分析与数据挖掘能力，熟悉盗卡、盗账户、拒付等反欺诈策略设计，了解国际卡组织与支付网络运作机制踪业界前沿动态并快速评估其在反欺诈场景的适用性；\n\n4、突出的分析问题和解决问题能力，自我驱动，具备较强的学习能力、创新应用能力及沟通协调能力。","description":"部门介绍\n美团金融服务平台成立于2016年，以“场景+金融”模式，携手合作伙伴构建开放生态，为美团平台用户和商户提供底层账户、支付通道、信贷、保险和理财等金融解决方案。我们致力于以科技为核心，助力金融机构打通金融普惠“最后一公里”。我们期待与大家共同完成每一件平凡而卓越的事情，一起为用户提供优质的产品体验，守护用户的资金安全，让生活变得更美好。\n\n岗位职责\n1、探索和落实AI及大模型技术在策略场景的应用，包括AI辅助特征挖掘、策略生成与仿真评估，推动策略体系向智能化演进；\n\n2、负责国际支付欺诈风险防控，减少公司资金损失，基于历史数据和专家经验，通过数据分析、数据挖掘和大模型能力，设计针对盗卡、盗账户等欺诈场景的风控策略并持续优化； \n\n3、平衡支付的体验和资损，设计、实施、监控风险-收益最大化的安全策略，保障业务健康发展； \n\n4、建立策略监控指标体系与数据报表体系，完善风险监控与预警机制，进行日常风险指标与策略、模型性能监控； \n\n5、联动产品、技术、算法等团队，建设风险引擎中台能力，设计和构建体系化的风控策略、流程与机制。\n\n岗位基本要求\n1、熟悉大模型应用场景，能够将AI能力融入风控策略设计与迭代，具有AI+风控策略实践落地经验者优先；\n\n2、3年以上风控策略/数据分析经验，有国际支付或跨境风控经验者优先；本科及以上学历，计算机、数学、统计学、金融等相关专业，可使用中英文作为工作语言；\n\n3、熟练使用至少一种分析工具（SQL、Python、R等），具备扎实的策略分析与数据挖掘能力，熟悉盗卡、盗账户、拒付等反欺诈策略设计，了解国际卡组织与支付网络运作机制踪业界前沿动态并快速评估其在反欺诈场景的适用性；\n\n4、突出的分析问题和解决问题能力，自我驱动，具备较强的学习能力、创新应用能力及沟通协调能力。\n\n具备以下条件优先\n1、具备AI风控实践落地经验的互联网风险产品人才；\n2、英语可作为工作语言优先。\n\n岗位亮点\n1、AI机会：深度参与AI技术在国际风控策略场景的落地，接触大模型、智能决策等前沿AI应用，具备AI与策略复合能力的候选人将获得优先发展机会；\n\n2、业务基本盘：国际化业务是美团重要战略方向，参与美团国际化业务高速发展，深度参与国际支付风控策略体系和风控体系建设，成长空间广阔；\n\n3、成长与资源：团队学习氛围好，与风控产品、算法专家协作，快速积累国际化风控策略与全链路风控能力，美团国际丰富的数据资源与技术平台为策略创新提供有力支撑；","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4047275798","sourceKey":"meituan_social","company":"美团","title":"Senior Legal Counsel (Kuwait)","city":"科威特城","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4047275798&jobShareType=1","duty":"Job Description\n\nKey Responsibilities\n\n1. Conduct legal research and provide comprehensive legal advice and support on transactions and commercial matters in Kuwait and the broader GCC region, including cross-border transactions, joint ventures, franchising, and licensing arrangements.\n\n2. Draft, review, and negotiate contracts, agreements, and other legal documents in both English and Arabic, ensuring compliance with Kuwaiti and applicable international laws.\n\n3. Advise on compliance with Kuwaiti local laws and regulations; identify and assess legal risks, and develop strategies to mitigate them.\n\n4. Assist business team, GA team in applying for and obtaining license and permit necessary for the operation of the retail, logistic, warehousing and other areas of the company.\n\n5. Work closely with senior management and business units to ensure legal requirements are met in all business operations across Kuwait.\n\n6. Support business units in communicating with relevant Kuwaiti authorities and external stakeholders, to maintain a business-friendly regulatory environment.\n\n7. Represent the company in legal proceedings, negotiations, and dispute resolution matters in Kuwaiti courts and alternative dispute resolution forums.\n\n8. Stay up-to-date with changes in the Kuwaiti legal landscape, GCC regulatory developments, and industry trends; proactively communicate updates to relevant internal stakeholders.\n\n9. Develop and maintain an adequate and high-quality resource pool of external law firms and legal advisors in Kuwait, and maintain strong relationships with external legal advisors and partners.\n\n10. Collaborate with the global legal team to ensure consistency in legal frameworks and compliance standards across jurisdictions.","requirements":"Mandatory Requirements\n\n1. A bachelor's degree in law from a recognized university. An advanced degree is preferred.\n\n2. A minimum of 7 years of relevant legal work experience, among which at least 5 years in Kuwait.\n\n3. Extensive knowledge of Kuwaiti corporate law, contract law, commercial law, labor law, and regulatory frameworks applicable to foreign-invested enterprises.\n\n4. Strong analytical, problem-solving, and communication skills with the ability to present complex legal matters clearly to non-legal stakeholders.\n\n5. Native Arabic speaker, with fluent English proficiency (both written and spoken) as a working language.\n\n6. Ability to work independently and as part of a cross-functional team.\n\n7. Proven track record of managing complex legal projects, transactions, and deadlines in a fast-paced environment.\n\n8. Familiarity with Kuwaiti regulatory authorities, licensing procedures, and government approval mechanisms.\n\n9. Experience in the retail, logistics, warehousing or food delivery industry, with understanding of supply chain, warehouse operations, dark store leasing, merchant contracts, and logistics service agreements.","description":"部门介绍\n公司事务平台负责构建公司的公共战略体系，助力业务可持续发展及公司对外影响力的提升。通过内外部风险管理，确保公司合规发展；通过深耕公共战略，推动内外良好沟通，连接公司发展与社会期待，助力业务高质量发展；通过管理社会责任议题、公益投入等，助力公司创造更多社会价值；同时为公司提供行政、采购等基础服务。我们坚持“懂业务、拿结果，勇担当、善协同，不唯上、只唯真”的工作理念，期待具有公共战略素养、了解公司治理逻辑的你加入！\n\n岗位职责\nJob Description\n\nKey Responsibilities\n\n1. Conduct legal research and provide comprehensive legal advice and support on transactions and commercial matters in Kuwait and the broader GCC region, including cross-border transactions, joint ventures, franchising, and licensing arrangements.\n\n2. Draft, review, and negotiate contracts, agreements, and other legal documents in both English and Arabic, ensuring compliance with Kuwaiti and applicable international laws.\n\n3. Advise on compliance with Kuwaiti local laws and regulations; identify and assess legal risks, and develop strategies to mitigate them.\n\n4. Assist business team, GA team in applying for and obtaining license and permit necessary for the operation of the retail, logistic, warehousing and other areas of the company.\n\n5. Work closely with senior management and business units to ensure legal requirements are met in all business operations across Kuwait.\n\n6. Support business units in communicating with relevant Kuwaiti authorities and external stakeholders, to maintain a business-friendly regulatory environment.\n\n7. Represent the company in legal proceedings, negotiations, and dispute resolution matters in Kuwaiti courts and alternative dispute resolution forums.\n\n8. Stay up-to-date with changes in the Kuwaiti legal landscape, GCC regulatory developments, and industry trends; proactively communicate updates to relevant internal stakeholders.\n\n9. Develop and maintain an adequate and high-quality resource pool of external law firms and legal advisors in Kuwait, and maintain strong relationships with external legal advisors and partners.\n\n10. Collaborate with the global legal team to ensure consistency in legal frameworks and compliance standards across jurisdictions.\n\n岗位基本要求\nMandatory Requirements\n\n1. A bachelor's degree in law from a recognized university. An advanced degree is preferred.\n\n2. A minimum of 7 years of relevant legal work experience, among which at least 5 years in Kuwait.\n\n3. Extensive knowledge of Kuwaiti corporate law, contract law, commercial law, labor law, and regulatory frameworks applicable to foreign-invested enterprises.\n\n4. Strong analytical, problem-solving, and communication skills with the ability to present complex legal matters clearly to non-legal stakeholders.\n\n5. Native Arabic speaker, with fluent English proficiency (both written and spoken) as a working language.\n\n6. Ability to work independently and as part of a cross-functional team.\n\n7. Proven track record of managing complex legal projects, transactions, and deadlines in a fast-paced environment.\n\n8. Familiarity with Kuwaiti regulatory authorities, licensing procedures, and government approval mechanisms.\n\n9. Experience in the retail, logistics, warehousing or food delivery industry, with understanding of supply chain, warehouse operations, dark store leasing, merchant contracts, and logistics service agreements.\n\n具备以下条件优先\nPreferred Qualifications (Will Be a Plus but Not a Must)\n\n- Diverse professional background, including experience in law firms, in-house legal teams, government, and/or judicial institutions (e.g., courts or prosecutorial bodies)\n\n- Overseas education experience in an English-speaking country\n\n- Experience working with or advising multinational companies in the technology or delivery industry\n\n-Professional legal qualification recognized in Kuwait (e.g., Kuwait Bar Association eligibility or equivalent)\n\n- Knowledge of Sharia law principles as they relate to commercial transactions\n\n- Knowledge with i) Kuwait's legal requirements for foreign investment and joint ventures under Kuwaiti Companies Law, ii) e-commerce, fintech, or digital services regulation in Kuwait, and iii) Kuwait's Public Tender Law and procurement frameworks\n\n岗位亮点\n1. Opportunities for professional growth and development.\n2. A challenging and rewarding work environment.\n3. The chance to work with a transnational team of experts.","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4473719060","sourceKey":"meituan_social","company":"美团","title":"Senior Legal Counsel-Kuwait中方法务","city":"科威特城","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4473719060&jobShareType=1","duty":"1.负责公司在中东国家的本地法律事务，确保公司业务合规运营。\n\n2.起草、审核、翻译中英文合同、协议及法律文件，协助业务部门处理各类法律问题。\n\n3.处理日常法务咨询、合规检查、政府问询沟通等事项。\n\n4.协助建立和完善子公司合规体系、法律风险防控机制，落实总部合规制度政策。与本地法务和全球法务团队协作，确保跨司法管辖区法律框架和合规标准的一致性。\n\n5.开发、维护外部律师、律所及其他法律服务供应商资源池。\n\n6.支持公司内部培训、法律宣传及员工合规意识提升。","requirements":"1.法律相关专业本科及以上学历。\n\n2.7年以上涉外业务法务工作经验，有跨境法律事务处理背景或有英语国家海外教育经历。\n\n3.英语流利，具备法律文件中英双语起草、翻译和沟通能力。\n\n4.具备分析能力、解决问题能力以及向非法律人员解释复杂法律问题的能力。\n\n5.熟悉政府流程，有政府沟通能力及政府调查、问询应对经验，能够处理政府合规、调查等相关事务。\n\n6.良好的沟通协调能力、团队合作精神及跨文化适应能力。\n\n7.工作细致严谨，责任心强，能承受一定工作压力、在快节奏环境中管理复杂法律项目，乐于接受新鲜事物、迎接挑战。","description":"部门介绍\n公司事务平台负责构建公司的公共战略体系，助力业务可持续发展及公司对外影响力的提升。通过内外部风险管理，确保公司合规发展；通过深耕公共战略，推动内外良好沟通，连接公司发展与社会期待，助力业务高质量发展；通过管理社会责任议题、公益投入等，助力公司创造更多社会价值；同时为公司提供行政、采购等基础服务。我们坚持“懂业务、拿结果，勇担当、善协同，不唯上、只唯真”的工作理念，期待具有公共战略素养、了解公司治理逻辑的你加入！\n\n岗位职责\n1.负责公司在中东国家的本地法律事务，确保公司业务合规运营。\n\n2.起草、审核、翻译中英文合同、协议及法律文件，协助业务部门处理各类法律问题。\n\n3.处理日常法务咨询、合规检查、政府问询沟通等事项。\n\n4.协助建立和完善子公司合规体系、法律风险防控机制，落实总部合规制度政策。与本地法务和全球法务团队协作，确保跨司法管辖区法律框架和合规标准的一致性。\n\n5.开发、维护外部律师、律所及其他法律服务供应商资源池。\n\n6.支持公司内部培训、法律宣传及员工合规意识提升。\n\n岗位基本要求\n1.法律相关专业本科及以上学历。\n\n2.7年以上涉外业务法务工作经验，有跨境法律事务处理背景或有英语国家海外教育经历。\n\n3.英语流利，具备法律文件中英双语起草、翻译和沟通能力。\n\n4.具备分析能力、解决问题能力以及向非法律人员解释复杂法律问题的能力。\n\n5.熟悉政府流程，有政府沟通能力及政府调查、问询应对经验，能够处理政府合规、调查等相关事务。\n\n6.良好的沟通协调能力、团队合作精神及跨文化适应能力。\n\n7.工作细致严谨，责任心强，能承受一定工作压力、在快节奏环境中管理复杂法律项目，乐于接受新鲜事物、迎接挑战。\n\n具备以下条件优先\n有互联网、平台、物流、仓储、外卖等行业法务经验者优先。\n\n有科威特或卡塔尔工作经历优先。\n\n具有中国或其他国家法律执业资格优先。\n\n会阿拉伯语者优先。\n\n岗位亮点\n海外业务蓬勃发展，熟悉业务能力的同事发展空间大。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4724280631","sourceKey":"meituan_social","company":"美团","title":"快驴水果——买手负责人（南京）","city":"南京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4724280631&jobShareType=1","duty":"1.负责所辖区域的水果招商团队的管理及商家管理工作；\n2.完成每个月设定的经营指标（交易、客诉率）；\n3.具备水果全品类规划能力、供应链建设和成本优化；\n4.针对类目供应链和货品需求情况，进行定向招商，合同谈判及合作条款；\n5.商家管理：管理供应商入场后行为，与供应商建立长期稳定的合作关系；\n6.基于市场和用户，敏锐的了解行业动态，及时调整商品配置，价格，策略\n7.过程指标监控及问题定位；\n8.团队建设及管理","requirements":"1.5年以上水果品类采购及管理经历；\n2.具备较强的商务谈判和采购成本管理能力；\n3.具有较强的业务分析能力、解决复杂问题能力及团队合作意识；\n4.具备线下零售业和电商品类管理的知识和经营，具备业务的中长期规划能力；\n5.具备项目统筹能力，能够协调和推进公司各支持部门完成项目落地及后续效率优化；","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1.负责所辖区域的水果招商团队的管理及商家管理工作；\n2.完成每个月设定的经营指标（交易、客诉率）；\n3.具备水果全品类规划能力、供应链建设和成本优化；\n4.针对类目供应链和货品需求情况，进行定向招商，合同谈判及合作条款；\n5.商家管理：管理供应商入场后行为，与供应商建立长期稳定的合作关系；\n6.基于市场和用户，敏锐的了解行业动态，及时调整商品配置，价格，策略\n7.过程指标监控及问题定位；\n8.团队建设及管理\n\n岗位基本要求\n1.5年以上水果品类采购及管理经历；\n2.具备较强的商务谈判和采购成本管理能力；\n3.具有较强的业务分析能力、解决复杂问题能力及团队合作意识；\n4.具备线下零售业和电商品类管理的知识和经营，具备业务的中长期规划能力；\n5.具备项目统筹能力，能够协调和推进公司各支持部门完成项目落地及后续效率优化；\n\n具备以下条件优先\n有水果B端采购供应管理经验者优先\n\n岗位亮点\n1.带领团队实现城市水果需求全结构经营；\n2.熟悉不同商业模式下不同的品类玩法和中长期业务规划 ；\n3.锻炼业务的框架性思维；","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4137426224","sourceKey":"meituan_social","company":"美团","title":"医药-B2C-采购专家（药品方向）","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4137426224&jobShareType=1","duty":"1.从事美团买药自营业务的采购工作，深入分析产品及其库存特征，制定合理采购计划和库存管控措施并跟进执行；保证各项库存指标达标，如周转、滞销、现货率等，并持续改善优化；\n2.对上游供应链现状进行梳理和诊断，识别判断最优采购路径，不断优化采购成本，提升低成本结构竞争力；\n3.推进采购流程系统建设，包括但不限于智能补货、采购看板、工作台、多仓运营采购体系等，推进系统规划建设并落地应用，运用AI数据分析工具对美团买药自营业务进行智能诊断，促进提升采购效率；\n4.引入优质供应商资源，与负责的供应商不断深入合作，做好供应商资源管理，为公司争取更多的供应链资源；\n5.部门内部、跨部门交流分享，牵头跨部门的整体项目，通过横向沟通获得必要的支持和高效协同，对项目结果负责，通过交流分享帮助他人和自身迅速成长。","requirements":"1.本科或以上学历，5年及以上电商平台快消行业采购经验，有医药行业采购经验者优先；\n2.对数据敏感度高，具备精细化商品分析经验，具备AI工具学习意识、独立思考能力强；\n3.乐于沟通，语言表达和感染说服能力突出，可应对复杂情形的商业谈判、组织协调；\n4.积极乐观，充满正能量，认同美团价值观并努力践行。","description":"部门介绍\n美团医药健康事业部是美团核心本地商业板块下专注健康领域的业务部门，涵盖美团买药、美团医美和美团医疗三大业务。自创立以来，美团医药健康致力于为用户提供全健康周期产品及服务，满足人民群众多层次多元化医疗健康需求，现已覆盖购药到家、居家检测、问诊挂号、医保支付、求医寻院、医疗美容等核心场景。此外，美团医药健康还为商户提供数字化转型创新解决方案，打造贯穿上游的联动机制，长期参与共建更透明、更可持续的医药健康产业生态圈，目前业务已覆盖25万家药店，收录27万家医疗机构。未来，美团医药康将协同更多行业伙伴，帮助大家变得更健康、更美丽、更养生。\n\n岗位职责\n1.从事美团买药自营业务的采购工作，深入分析产品及其库存特征，制定合理采购计划和库存管控措施并跟进执行；保证各项库存指标达标，如周转、滞销、现货率等，并持续改善优化；\n2.对上游供应链现状进行梳理和诊断，识别判断最优采购路径，不断优化采购成本，提升低成本结构竞争力；\n3.推进采购流程系统建设，包括但不限于智能补货、采购看板、工作台、多仓运营采购体系等，推进系统规划建设并落地应用，运用AI数据分析工具对美团买药自营业务进行智能诊断，促进提升采购效率；\n4.引入优质供应商资源，与负责的供应商不断深入合作，做好供应商资源管理，为公司争取更多的供应链资源；\n5.部门内部、跨部门交流分享，牵头跨部门的整体项目，通过横向沟通获得必要的支持和高效协同，对项目结果负责，通过交流分享帮助他人和自身迅速成长。\n\n岗位基本要求\n1.本科或以上学历，5年及以上电商平台快消行业采购经验，有医药行业采购经验者优先；\n2.对数据敏感度高，具备精细化商品分析经验，具备AI工具学习意识、独立思考能力强；\n3.乐于沟通，语言表达和感染说服能力突出，可应对复杂情形的商业谈判、组织协调；\n4.积极乐观，充满正能量，认同美团价值观并努力践行。\n\n岗位亮点\n1.公司福利优厚：定期团建、带薪年假、定期体检；\n2.业务发展广阔前景，是公司重点突破业务；\n3.电商品类运营核心岗位，参与建设美团医药业务从小到大的发展阶段，并从中收获宝贵的经验。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4723335725","sourceKey":"meituan_social","company":"美团","title":"高级网安专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4723335725&jobShareType=1","duty":"1.推进网络安全主管部门朋友圈建设，覆盖部、省、市各级，建立与主管单位、行业协会、科研院所及头部厂商的战略合作关系。\n2.统筹网络安全合规事务，应对安全检查、合规审查及专项治理，协调内部资源完成整改、报告与数据报送。\n3.牵头处置公司级网络安全事件，制定应急预案并组织演练，对接主管部门事件报告与后续跟进。\n4.跟踪研判网络安全法律法规及政策动态，输出政策简报，为公司合规运营提供风险预警与策略建议。","requirements":"1.大学本科及以上学历，信息安全、网络安全、计算机、法律等相关专业。\n2.具备5年以上互联网企业或相关机构网络安全工作经历。\n3.具备高阶沟通能力和主管部门朋友圈建设经验，能独立承担日常维护工作。\n4.熟悉网络安全，信息安全等相关合规体系，具备敏锐的政策敏感度。\n5.具备较强的资源整合能力和危机处理能力，能有效协调内外部资源应对突发事件。","description":"部门介绍\n公司事务平台负责构建公司的公共战略体系，助力业务可持续发展及公司对外影响力的提升。通过内外部风险管理，确保公司合规发展；通过深耕公共战略，推动内外良好沟通，连接公司发展与社会期待，助力业务高质量发展；通过管理社会责任议题、公益投入等，助力公司创造更多社会价值；同时为公司提供行政、采购等基础服务。我们坚持“懂业务、拿结果，勇担当、善协同，不唯上、只唯真”的工作理念，期待具有公共战略素养、了解公司治理逻辑的你加入！\n\n岗位职责\n1.推进网络安全主管部门朋友圈建设，覆盖部、省、市各级，建立与主管单位、行业协会、科研院所及头部厂商的战略合作关系。\n2.统筹网络安全合规事务，应对安全检查、合规审查及专项治理，协调内部资源完成整改、报告与数据报送。\n3.牵头处置公司级网络安全事件，制定应急预案并组织演练，对接主管部门事件报告与后续跟进。\n4.跟踪研判网络安全法律法规及政策动态，输出政策简报，为公司合规运营提供风险预警与策略建议。\n\n岗位基本要求\n1.大学本科及以上学历，信息安全、网络安全、计算机、法律等相关专业。\n2.具备5年以上互联网企业或相关机构网络安全工作经历。\n3.具备高阶沟通能力和主管部门朋友圈建设经验，能独立承担日常维护工作。\n4.熟悉网络安全，信息安全等相关合规体系，具备敏锐的政策敏感度。\n5.具备较强的资源整合能力和危机处理能力，能有效协调内外部资源应对突发事件。\n\n岗位亮点\n平台大，资源多，可触达全国各层级网安朋友圈；\n成长空间大，管理者储备或资深专家方向均可；\n团队氛围好，不内卷，协同顺畅。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4721367330","sourceKey":"meituan_social","company":"美团","title":"歪马送酒直营主管【昆明】","city":"昆明市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4721367330&jobShareType=1","duty":"1. 负责昆明地区歪马送酒直营业务的日常运营管理，确保配送效率与服务质量达标。  \n2. 带领10余人团队完成销售目标，制定并执行运营策略，优化业务流程。  \n3. 监控关键运营指标，分析数据并输出改进方案，提升用户满意度与复购率。  \n4. 协调仓储、配送、客服等环节，保障订单履约顺畅，处理突发问题。  \n5. 定期培训团队成员，提升业务能力与服务意识，营造高效协作氛围。","requirements":"1. 大学本科及以上学历，具备3年以上运营管理或销售运营相关经验。  \n2. 熟悉本地生活服务或即时零售行业，有酒水、快消品运营背景者优先。  \n3. 具备较强的数据分析能力与逻辑思维，能独立制定运营策略。  \n4. 优秀的团队管理与沟通协调能力，结果导向。  \n5. 熟练使用办公软件及基础数据分析工具。","description":"部门介绍\n美团闪购是美团旗下的即时零售平台，依托即时配送能力，连接本地零售供给，满足消费者30分钟万物到家的即时需求。美团闪购涵盖超市便利、食材、水果、鲜花绿植、休闲零食、酒水饮料、数码家电、美妆个护、母婴玩具、日用百货、服饰鞋帽、宠物等诸多品类，业务覆盖全国近3,000个县市区旗，每日百万级在岗骑手，以高效的配送、丰富的品类和广泛的覆盖，为美团数亿用户带来便捷的生活体验，积极助力实体零售线上化转型，提升本地商业活力。\n\n岗位职责\n1. 负责昆明地区歪马送酒直营业务的日常运营管理，确保配送效率与服务质量达标。  \n2. 带领10余人团队完成销售目标，制定并执行运营策略，优化业务流程。  \n3. 监控关键运营指标，分析数据并输出改进方案，提升用户满意度与复购率。  \n4. 协调仓储、配送、客服等环节，保障订单履约顺畅，处理突发问题。  \n5. 定期培训团队成员，提升业务能力与服务意识，营造高效协作氛围。\n\n岗位基本要求\n1. 大学本科及以上学历，具备3年以上运营管理或销售运营相关经验。  \n2. 熟悉本地生活服务或即时零售行业，有酒水、快消品运营背景者优先。  \n3. 具备较强的数据分析能力与逻辑思维，能独立制定运营策略。  \n4. 优秀的团队管理与沟通协调能力，结果导向。  \n5. 熟练使用办公软件及基础数据分析工具。\n\n岗位亮点\n1. 加入快速发展的酒水即时零售平台，业务增长空间大。  \n2. 拥有明确的晋升通道与完善的培训体系，助力个人成长。  \n3. 团队氛围年轻有活力，扁平化管理，决策高效。  \n4. 提供具有竞争力的薪酬与绩效激励，多劳多得。  \n5. 工作地点位于昆明市核心区域，交通便利。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4698196771","sourceKey":"meituan_social","company":"美团","title":"快乐猴-杭州门店店长","city":"杭州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4698196771&jobShareType=1","duty":"1、确保公司营运标准高效在门店落地，提升销售与毛利；\n2、理解商圈和用户，据此对门店品类和商品经营方向有清晰的认知，通过品类/商品经营、拉新、营销、门店布局、商品订货、陈列、服务，售后，库存管控等；\n3、管控店内损耗、提升门店人效，优化可控费用（如物料，水电煤等营运费用），达成主要考核KPI；\n4、对内各协同部门的日常高效交互，达成共识，高效执行总部和区域新项目落地；\n5、对外关系的建立维护，如相关政府职能部门（市场管理、消协等）、物业关系，打造协作融洽的合作伙伴；","requirements":"1、具有传统大型零售运营的思维模式，5年以上工作经验，担任过2年以上传统实体零售门店生鲜副店长及以上级别的管理岗,关注客户价值和客户体验;\n2、诚实正直、品行端正、责任心强、肯吃苦、有激情且执行力强，有商人视角；\n3、勇于承担，乐于分享，指导与培养团队各项能力，能够打造高绩效团队，形成阶梯化人才成长模式；\n4、具备建设组织和体系搭建能力，可以制定并落实各环节的流程；\n5、掌握基本的AI工具，具备数字化运营思维，能快速学习并应用AI辅助工具提升工作效率。","description":"部门介绍\n快乐猴是美团自营社区超市，依托自有供应链和门店管理体系，聚焦家庭用户的三餐所需，为消费者提供高质价比的食杂商品。快乐猴以数字化能力与科学品控为基础，不断满足消费者对“省”和“便利”的需求。\n\n岗位职责\n1、确保公司营运标准高效在门店落地，提升销售与毛利；\n2、理解商圈和用户，据此对门店品类和商品经营方向有清晰的认知，通过品类/商品经营、拉新、营销、门店布局、商品订货、陈列、服务，售后，库存管控等；\n3、管控店内损耗、提升门店人效，优化可控费用（如物料，水电煤等营运费用），达成主要考核KPI；\n4、对内各协同部门的日常高效交互，达成共识，高效执行总部和区域新项目落地；\n5、对外关系的建立维护，如相关政府职能部门（市场管理、消协等）、物业关系，打造协作融洽的合作伙伴；\n\n岗位基本要求\n1、具有传统大型零售运营的思维模式，5年以上工作经验，担任过2年以上传统实体零售门店生鲜副店长及以上级别的管理岗,关注客户价值和客户体验;\n2、诚实正直、品行端正、责任心强、肯吃苦、有激情且执行力强，有商人视角；\n3、勇于承担，乐于分享，指导与培养团队各项能力，能够打造高绩效团队，形成阶梯化人才成长模式；\n4、具备建设组织和体系搭建能力，可以制定并落实各环节的流程；\n5、掌握基本的AI工具，具备数字化运营思维，能快速学习并应用AI辅助工具提升工作效率。\n\n具备以下条件优先\n有主流线下硬折扣门店店长经验，传统超商连锁门店营运中层管理经验优先。\n\n岗位亮点\n1、创新型重点项目，从0-1，成长空间广阔，共同推动门店高效营运\n2、AI数据看板、智能补货预测、数字化稽核系统全面赋能，让你用互联网公司的工具做零售管理。告别凭感觉管店，AI数据告诉你哪里出了问题、该怎么改。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4698251034","sourceKey":"meituan_social","company":"美团","title":"快乐猴-杭州门店副店长","city":"杭州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4698251034&jobShareType=1","duty":"1、确保公司营运标准高效在门店落地，提升销售与毛利；\n2、理解商圈和用户，据此对门店品类和商品经营方向有清晰的认知，通过品类/商品经营、拉新、营销、门店布局、商品订货、陈列、服务，售后，库存管控等；\n3、管控店内损耗、提升门店人效，优化可控费用（如物料，水电煤等营运费用），达成主要考核KPI；\n4、对内各协同部门的日常高效交互，达成共识，高效执行总部和区域新项目落地；\n5、对外关系的建立维护，如相关政府职能部门（市场管理、消协等）、物业关系，打造协作融洽的合作伙伴；","requirements":"1、具有传统大型零售运营的思维模式，5年以上工作经验，担任过2年以上传统实体零售门店生鲜副店长及以上级别的管理岗,关注客户价值和客户体验;\n2、诚实正直、品行端正、责任心强、肯吃苦、有激情且执行力强，有商人视角；\n3、勇于承担，乐于分享，指导与培养团队各项能力，能够打造高绩效团队，形成阶梯化人才成长模式；\n4、具备建设组织和体系搭建能力，可以制定并落实各环节的流程；\n5、掌握基本的AI工具，具备数字化运营思维，能快速学习并应用AI辅助工具提升工作效率。","description":"部门介绍\n快乐猴是美团自营社区超市，依托自有供应链和门店管理体系，聚焦家庭用户的三餐所需，为消费者提供高质价比的食杂商品。快乐猴以数字化能力与科学品控为基础，不断满足消费者对“省”和“便利”的需求。\n\n岗位职责\n1、确保公司营运标准高效在门店落地，提升销售与毛利；\n2、理解商圈和用户，据此对门店品类和商品经营方向有清晰的认知，通过品类/商品经营、拉新、营销、门店布局、商品订货、陈列、服务，售后，库存管控等；\n3、管控店内损耗、提升门店人效，优化可控费用（如物料，水电煤等营运费用），达成主要考核KPI；\n4、对内各协同部门的日常高效交互，达成共识，高效执行总部和区域新项目落地；\n5、对外关系的建立维护，如相关政府职能部门（市场管理、消协等）、物业关系，打造协作融洽的合作伙伴；\n\n岗位基本要求\n1、具有传统大型零售运营的思维模式，5年以上工作经验，担任过2年以上传统实体零售门店生鲜副店长及以上级别的管理岗,关注客户价值和客户体验;\n2、诚实正直、品行端正、责任心强、肯吃苦、有激情且执行力强，有商人视角；\n3、勇于承担，乐于分享，指导与培养团队各项能力，能够打造高绩效团队，形成阶梯化人才成长模式；\n4、具备建设组织和体系搭建能力，可以制定并落实各环节的流程；\n5、掌握基本的AI工具，具备数字化运营思维，能快速学习并应用AI辅助工具提升工作效率。\n\n具备以下条件优先\n有硬折扣门店店长经验，传统超商连锁门店营运中层管理经验优先。\n\n岗位亮点\n1、创新型重点项目，从0-1，成长空间广阔，共同推动门店高效营运\n2、AI数据看板、智能补货预测、数字化稽核系统全面赋能，让你用互联网公司的工具做零售管理。告别凭感觉管店，AI数据告诉你哪里出了问题、该怎么改。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4641502799","sourceKey":"meituan_social","company":"美团","title":"快乐猴-嘉兴门店副店长","city":"嘉兴市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4641502799&jobShareType=1","duty":"1、确保公司营运标准高效在门店落地，提升销售与毛利；\n2、理解商圈和用户，据此对门店品类和商品经营方向有清晰的认知，通过品类/商品经营、拉新、营销、门店布局、商品订货、陈列、服务，售后，库存管控等；\n3、管控店内损耗、提升门店人效，优化可控费用（如物料，水电煤等营运费用），达成主要考核KPI；\n4、对内各协同部门的日常高效交互，达成共识，高效执行总部和区域新项目落地；\n5、对外关系的建立维护，如相关政府职能部门（市场管理、消协等）、物业关系，打造协作融洽的合作伙伴。","requirements":"1、具有传统大型零售运营的思维模式，5年以上工作经验，担任过2年以上传统实体零售门店生鲜副店长及以上级别的管理岗,关注客户价值和客户体验;\n2、诚实正直、品行端正、责任心强、肯吃苦、有激情且执行力强，有商人视角；\n3、勇于承担，乐于分享，指导与培养团队各项能力，能够打造高绩效团队，形成阶梯化人才成长模式；\n4、具备建设组织和体系搭建能力，可以制定并落实各环节的流程。\n5、掌握基本的AI工具，具备数字化运营思维，能快速学习并应用AI辅助工具提升工作效率。","description":"部门介绍\n快乐猴是美团自营社区超市，依托自有供应链和门店管理体系，聚焦家庭用户的三餐所需，为消费者提供高质价比的食杂商品。快乐猴以数字化能力与科学品控为基础，不断满足消费者对“省”和“便利”的需求。\n\n岗位职责\n1、确保公司营运标准高效在门店落地，提升销售与毛利；\n2、理解商圈和用户，据此对门店品类和商品经营方向有清晰的认知，通过品类/商品经营、拉新、营销、门店布局、商品订货、陈列、服务，售后，库存管控等；\n3、管控店内损耗、提升门店人效，优化可控费用（如物料，水电煤等营运费用），达成主要考核KPI；\n4、对内各协同部门的日常高效交互，达成共识，高效执行总部和区域新项目落地；\n5、对外关系的建立维护，如相关政府职能部门（市场管理、消协等）、物业关系，打造协作融洽的合作伙伴。\n\n岗位基本要求\n1、具有传统大型零售运营的思维模式，5年以上工作经验，担任过2年以上传统实体零售门店生鲜副店长及以上级别的管理岗,关注客户价值和客户体验;\n2、诚实正直、品行端正、责任心强、肯吃苦、有激情且执行力强，有商人视角；\n3、勇于承担，乐于分享，指导与培养团队各项能力，能够打造高绩效团队，形成阶梯化人才成长模式；\n4、具备建设组织和体系搭建能力，可以制定并落实各环节的流程。\n5、掌握基本的AI工具，具备数字化运营思维，能快速学习并应用AI辅助工具提升工作效率。\n\n具备以下条件优先\n有硬折扣门店店长经验，传统超商连锁门店营运中层管理经验优先。\n\n岗位亮点\n1、创新型重点项目，从0-1，成长空间广阔，共同推动门店高效营运。\n2、AI数据看板、智能补货预测、数字化稽核系统全面赋能，让你用互联网公司的工具做零售管理。告别凭感觉管店，AI数据告诉你哪里出了问题、该怎么改。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3021622793","sourceKey":"meituan_social","company":"美团","title":"AI产品负责人","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3021622793&jobShareType=1","duty":"1.负责企业办公管理领域下一代AI产品的设计、开发和优化。\n2.领导和管理团队，制定团队目标并监督团队成员的工作进展。\n3.与产品经理、开发团队和其他相关部门密切合作，确保产品按时交付并满足客户需求。\n4.负责产品的市场调研和竞争分析，提供产品改进的建议和策略。\n5.跟踪和分析产品的使用情况和用户反馈，及时解决问题并改进产品体验。\n6.跟进新技术和行业趋势，为产品创新提供支持和建议。","requirements":"1.本科及以上学历，计算机科学、软件工程或相关专业优先。\n2.至少8年以上产品开发或相关工作经验，具备丰富的产品设计和开发经验。\n3.熟悉AI技术和人工智能办公工具，对人机交互、自然语言处理等领域有深入了解。\n4.具备良好的团队管理和领导能力，有成功带领团队完成项目的经验。\n5.具备较强的沟通和协调能力，能有效与不同部门和团队进行合作。\n6.具备敏锐的市场洞察力和商业意识，能够理解客户需求并提供相应解决方案。\n7.具备良好的分析和解决问题的能力，能够快速响应和处理紧急情况。","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n1.负责企业办公管理领域下一代AI产品的设计、开发和优化。\n2.领导和管理团队，制定团队目标并监督团队成员的工作进展。\n3.与产品经理、开发团队和其他相关部门密切合作，确保产品按时交付并满足客户需求。\n4.负责产品的市场调研和竞争分析，提供产品改进的建议和策略。\n5.跟踪和分析产品的使用情况和用户反馈，及时解决问题并改进产品体验。\n6.跟进新技术和行业趋势，为产品创新提供支持和建议。\n\n岗位基本要求\n1.本科及以上学历，计算机科学、软件工程或相关专业优先。\n2.至少8年以上产品开发或相关工作经验，具备丰富的产品设计和开发经验。\n3.熟悉AI技术和人工智能办公工具，对人机交互、自然语言处理等领域有深入了解。\n4.具备良好的团队管理和领导能力，有成功带领团队完成项目的经验。\n5.具备较强的沟通和协调能力，能有效与不同部门和团队进行合作。\n6.具备敏锐的市场洞察力和商业意识，能够理解客户需求并提供相应解决方案。\n7.具备良好的分析和解决问题的能力，能够快速响应和处理紧急情况。\n\n岗位亮点\n1.拥有丰富的产品设计和开发经验，能够参与和推动高阶AI办公产品的创新和发展。\n2.能够带领团队完成复杂项目，提升团队的技术能力和工作效率。\n3.跟踪和应用新技术，紧跟行业发展趋势，为产品创新提供支持和建议。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4721277378","sourceKey":"meituan_social","company":"美团","title":"高级测试开发工程师","city":"北京市/成都市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4721277378&jobShareType=1","duty":"1. 负责基于测试Agent的全流程质量保障工作，覆盖需求分析、测试设计、执行及缺陷闭环管理。  \n2. 构建并优化测试Agent能力，实现测试任务自主规划、用例生成、执行及结果分析的端到端自动化。  \n3. 探索测试Agent在复杂场景下的应用，如智能回归测试、异常路径挖掘及多模态交互验证。  \n4. 协同研发团队将测试Agent集成至CI/CD流程，提升测试效率与覆盖率。  \n5. 跟踪AI测试技术趋势，推动测试Agent在性能测试、安全测试等领域的创新落地。","requirements":"1. 硕士研究生学历，计算机、人工智能或相关专业背景。  \n2. 5年以上测试开发经验，具备AI应用或智能测试工具实战经验。  \n3. 熟悉测试Agent技术栈（如LLM、RPA、AutoML），有自主测试系统建设经验者优先。  \n4. 精通Python/Java等语言，掌握主流测试框架及DevOps工具链。  \n5. 具备优秀的系统思维和跨团队协作能力，能推动测试Agent规模化应用。","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n1. 负责基于测试Agent的全流程质量保障工作，覆盖需求分析、测试设计、执行及缺陷闭环管理。  \n2. 构建并优化测试Agent能力，实现测试任务自主规划、用例生成、执行及结果分析的端到端自动化。  \n3. 探索测试Agent在复杂场景下的应用，如智能回归测试、异常路径挖掘及多模态交互验证。  \n4. 协同研发团队将测试Agent集成至CI/CD流程，提升测试效率与覆盖率。  \n5. 跟踪AI测试技术趋势，推动测试Agent在性能测试、安全测试等领域的创新落地。\n\n岗位基本要求\n1. 硕士研究生学历，计算机、人工智能或相关专业背景。  \n2. 5年以上测试开发经验，具备AI应用或智能测试工具实战经验。  \n3. 熟悉测试Agent技术栈（如LLM、RPA、AutoML），有自主测试系统建设经验者优先。  \n4. 精通Python/Java等语言，掌握主流测试框架及DevOps工具链。  \n5. 具备优秀的系统思维和跨团队协作能力，能推动测试Agent规模化应用。\n\n具备以下条件优先\n有AI Agent测试经验\n\n岗位亮点\n1. 主导测试Agent从0到1的落地，打造行业先进的智能测试体系。  \n2. 深度参与AI驱动的测试革命，技术成长与行业影响力双重提升。  \n3. 弹性工作制，配备高性能算力资源支持创新实验。  \n4. 成都AI产业生态完善，提供持续的技术交流与学习机会。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4721968881","sourceKey":"meituan_social","company":"美团","title":"资深招聘经理","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4721968881&jobShareType=1","duty":"1、全流程招聘交付 ：主导从需求诊断、面试评估设计、Offer 谈判到入职跟进的全流程，确保招聘质量与候选人体验；针对紧急、稀缺或跨区域疑难岗位，制定专项招聘计划，推动跨部门、跨区域协作；\n2、能够与业务管理者定期对话，深入理解业务战略与组织规划，主动输出人才市场洞察与招聘策略建议\n3、人才 Mapping 与智能寻访 ：能够定义目标公司与人才画像，通过Mapping等方法了解行业内信息，给业务部门行业内信息输入，梳理对应的寻访目标公司，构建人才地图，完善人才储备，提升招聘效率；\n4、候选人深度经营 ：能够精准洞察高端候选人的职业诉求与决策逻辑，通过持续的关系维护建立长期人才网络；在关键节点（薪酬谈判、犹豫期）提供个性化沟通策略\n5、数据驱动持续优化： 基于 AI 输出的招聘漏斗分析，诊断瓶颈环节并提出改进方案；定期复盘招聘效果，推动流程优化","requirements":"1、本科及以上学历，招聘领域有扎实的实战积累（不设硬性年限门槛，以能力和成果为评估标准）\n2、高端岗位招聘经验：有独立完成从需求诊断到 Offer 关单全流程的成功案例，有高管猎聘经验者优先\n3、候选人经营能力：擅长与高端候选人建立深度信任，有成熟的人脉网络管理方法论\n5、商业敏感度：能快速理解业务战略并转化为招聘策略，不只是执行需求而是主动输出洞察\n6、AI 工具应用意识：愿意拥抱 AI 工具，善于利用技术手段提升工作效率；至少有使用 AI 辅助工作的实际经验（如 ChatGPT、Copilot 或类似工具）","description":"部门介绍\n核心本地商业（Core Local Commerce）是美团“零售+科技”战略的重要载体，涵盖了到店餐饮、服务零售、酒店旅行、外卖、履约配送、闪购、医药健康等多个业务，覆盖了超过200个消费场景，致力于通过“随时随地”的商品和服务，满足消费者的多样性需求，帮大家吃得更好，生活更好。核心本地商业扎根本地消费，围绕消费者的“吃、住、行、游、购、娱”进行深度创新，引领发展了即时零售、团购等多种消费业态，并在全国范围内广泛投资发展本地供给、履约平台等设施，助力创造产业、带动就业。基于多年的持续投入，核心本地商业打造了连接全国超过一千万中小微企业的服务体系，以及全球最大的即时配送网络。由核心本地商业所推行的30分钟“万物到家”体系，已覆盖全国2800多个城镇，为数亿用户提供优质的商品与服务。发展过程中，核心本地商业有效助力商超、连锁、本地小店等各类实体经济主体扩大交易规模、降低交易成本。截至目前，核心本地商业日均创造订单量数千万笔，助力千万商户实现了高质量发展。未来，核心本地商业将继续践行美团“零售+科技”战略，通过更大的投资，更多的技术创新，支持、培育消费新业态，为促进消费、服务民生、带动就业作出力所能及的贡献。欢迎优秀的你加入核心本地商业，我们携手助力市场繁荣，为用户创造更好的消费体验。\n\n岗位职责\n1、全流程招聘交付 ：主导从需求诊断、面试评估设计、Offer 谈判到入职跟进的全流程，确保招聘质量与候选人体验；针对紧急、稀缺或跨区域疑难岗位，制定专项招聘计划，推动跨部门、跨区域协作；\n2、能够与业务管理者定期对话，深入理解业务战略与组织规划，主动输出人才市场洞察与招聘策略建议\n3、人才 Mapping 与智能寻访 ：能够定义目标公司与人才画像，通过Mapping等方法了解行业内信息，给业务部门行业内信息输入，梳理对应的寻访目标公司，构建人才地图，完善人才储备，提升招聘效率；\n4、候选人深度经营 ：能够精准洞察高端候选人的职业诉求与决策逻辑，通过持续的关系维护建立长期人才网络；在关键节点（薪酬谈判、犹豫期）提供个性化沟通策略\n5、数据驱动持续优化： 基于 AI 输出的招聘漏斗分析，诊断瓶颈环节并提出改进方案；定期复盘招聘效果，推动流程优化\n\n岗位基本要求\n1、本科及以上学历，招聘领域有扎实的实战积累（不设硬性年限门槛，以能力和成果为评估标准）\n2、高端岗位招聘经验：有独立完成从需求诊断到 Offer 关单全流程的成功案例，有高管猎聘经验者优先\n3、候选人经营能力：擅长与高端候选人建立深度信任，有成熟的人脉网络管理方法论\n5、商业敏感度：能快速理解业务战略并转化为招聘策略，不只是执行需求而是主动输出洞察\n6、AI 工具应用意识：愿意拥抱 AI 工具，善于利用技术手段提升工作效率；至少有使用 AI 辅助工作的实际经验（如 ChatGPT、Copilot 或类似工具）\n\n具备以下条件优先\n1、有 AI 工具在招聘场景的落地实践经验（如 AI 简历筛选、智能外呼、自动化 sourcing 等）\n2、有系统化的人才 Mapping / 市场情报搜集方法论/项目运营经验\n3、具备良好的沟通表达能力，逻辑思考能力和项目管理能力（含进程推进能力），拥有良好的客户需求沟通和管理能力；4、具备较强的自驱力，责任心，学习能力强，良好的团队协作精神、主动学习、积极驱动的能力、反应灵敏等。\n\n岗位亮点\n1.可以参与新业务从0-1搭建的过程；既能支持后线职位，也可以深入一线了解业务，拥有一线视角，提升全局观和对业务的深度理解。\n2.能力发展全面：目前所支持业务基本属于闭环业务，职位类型齐全，涵盖美团乃至互联网行业大部分职位类型，可以全面发展也可以专精几个方向；可以锻炼招聘运营的思路，用“运营”的思路做招聘。\n3.团队氛围好：友爱，有活力，目标感强，可以共同进步，协作共赢。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4684712919","sourceKey":"meituan_social","company":"美团","title":"无人车业务部-车辆交付主管","city":"深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4684712919&jobShareType=1","duty":"1.主导重点客户物流项目从签约到稳定运营的全周期交付，统筹交付计划制定与关键里程碑验收；\n2.负责项目现场交付管理，完成作业环境评估与交付条件建设，推动项目具备落地运营条件；\n3.参与技术能力验收，确保核心功能与业务系统对接能力达到交付标准；\n4.统筹测试与试跑阶段运营管理，建立监控机制、跟踪关键指标，开展客户培训，推动客户独立运营并保障履约；\n5.统筹交付所需车辆、人力等资源配置，承担车辆全生命周期管理，保障资产安全。","requirements":"1.本科及以上学历，物流管理、交通运输、自动化、车辆工程等相关专业优先；\n2.3年以上物流运营、项目管理或相关领域交付经验，有末端配送、仓配一体化项目经验者优先；\n3.善于运用AI工具辅助数据分析与策略研究；\n4.具备较强的项目交付意识、现场执行力与跨部门协调能力，有数据敏感度和客户视角；\n5.适应高频出差，持有C1及以上驾驶证。","description":"部门介绍\n无人车业务部成立于2016年，旨在用无人驾驶技术提升物流配送的效率和体验。美团无人车以自研L4级自动驾驶软硬件技术为核心，与美团即时零售业务结合，形成满足公开道路、社区、工业园区等室外全场景下的无人配送整体解决方案。自2020年起，无人车已在北京、深圳等多地进入常态化试运营阶段，在城市复杂场景下提供针对餐饮外卖、生鲜食杂等货物的即时配送服务。2025年，美团无人车又踏上了同城货运的新探索，并在2026年持续扩大运营范围和车队数量，为更多城市带来智能配送服务。\n欢迎加入美团无人车团队，与我们一起用科技推动即时零售再升级！\n\n岗位职责\n1.主导重点客户物流项目从签约到稳定运营的全周期交付，统筹交付计划制定与关键里程碑验收；\n2.负责项目现场交付管理，完成作业环境评估与交付条件建设，推动项目具备落地运营条件；\n3.参与技术能力验收，确保核心功能与业务系统对接能力达到交付标准；\n4.统筹测试与试跑阶段运营管理，建立监控机制、跟踪关键指标，开展客户培训，推动客户独立运营并保障履约；\n5.统筹交付所需车辆、人力等资源配置，承担车辆全生命周期管理，保障资产安全。\n\n岗位基本要求\n1.本科及以上学历，物流管理、交通运输、自动化、车辆工程等相关专业优先；\n2.3年以上物流运营、项目管理或相关领域交付经验，有末端配送、仓配一体化项目经验者优先；\n3.善于运用AI工具辅助数据分析与策略研究；\n4.具备较强的项目交付意识、现场执行力与跨部门协调能力，有数据敏感度和客户视角；\n5.适应高频出差，持有C1及以上驾驶证。\n\n具备以下条件优先\n有物流/出行、自动驾驶等行业经验者优先\n\n岗位亮点\n1. 深度参与前沿无人车技术研发与商业化探索，站在行业创新最前线；\n2. 与核心技术团队和业务专家协作，快速提升技术与商业复合能力；\n3. 提供具有竞争力的薪酬与职业发展通道。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4698736063","sourceKey":"meituan_social","company":"美团","title":"医药健康-用户体验","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4698736063&jobShareType=1","duty":"1.负责医药健康的用户体验管理工作，通过数据分析、客诉分析、行业分析等形式，洞察当前业务体验问题与机会点；\n2.与业务、产品、治理、履约、客服等组织合作，从根源探查体验问题与解决思路，制定长期方案；\n3.负责制定并跟踪用户体验提升执行方案，并跟踪指标变化，评估方案效果，确保结果符合预期。","requirements":"1.大学本科及以上学历，具有即时零售、快递电商、到店服务行业相关背景，了解业务模式特点和用户需求。\n2.具有3年以上用户体验相关经验，能够制定运营策略和执行方案。\n3.具备SQL取数能力，有良好的数据分析能力和数据驱动思维，能够根据数据结果做出相应的决策和调整。\n4.具备优秀的沟通能力和团队合作能力，能够与产品团队、技术团队等部门紧密协作，推动项目的顺利进行。\n5.具备医药、医疗、医美等行业经验优先。","description":"部门介绍\n美团平台为用户的基础产品体验负责，还承担了美团的用户增长、市场和品牌营销以及多条业务线的产品设计职责，建立了融合文字、图片、视频和直播等不同形式的內容生态系统，同时整合地图服务部、客户服务和体验部、企业业务部、网约车业务部等部门，致力于用科技提升美团数亿消费者、近千万商家、骑手、司机和团长的服务体验。美团平台拥有高并发、多业务的复杂场景，为技术深度优化提供了最佳实践可能。这里有简单、讲逻辑、有爱的团队，更是一块理想的实战场地，舞台广阔，欢迎你来尽情施展。\n\n岗位职责\n1.负责医药健康的用户体验管理工作，通过数据分析、客诉分析、行业分析等形式，洞察当前业务体验问题与机会点；\n2.与业务、产品、治理、履约、客服等组织合作，从根源探查体验问题与解决思路，制定长期方案；\n3.负责制定并跟踪用户体验提升执行方案，并跟踪指标变化，评估方案效果，确保结果符合预期。\n\n岗位基本要求\n1.大学本科及以上学历，具有即时零售、快递电商、到店服务行业相关背景，了解业务模式特点和用户需求。\n2.具有3年以上用户体验相关经验，能够制定运营策略和执行方案。\n3.具备SQL取数能力，有良好的数据分析能力和数据驱动思维，能够根据数据结果做出相应的决策和调整。\n4.具备优秀的沟通能力和团队合作能力，能够与产品团队、技术团队等部门紧密协作，推动项目的顺利进行。\n5.具备医药、医疗、医美等行业经验优先。\n\n具备以下条件优先\n学习能力强，有探索欲\n\n岗位亮点\n1.多业务模式与业态，探索空间充足，不仅有巨大的成长空间，更有机会做出改变行业的事；\n2.有机会与各个团队紧密合作，包括产品团队、技术团队等，拓宽自身的工作经验和技能。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4721163866","sourceKey":"meituan_social","company":"美团","title":"高级经营分析专家（全球目标与经营管理方向）","city":"北京市/香港特别行政区","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4721163866&jobShareType=1","duty":"1. 统筹多个海外市场的年度经营规划，建立统一的规划节奏、国家目标包、核心假设口径和管理层决策流程。\n2. 结合市场空间、竞争格局、发展阶段、组织能力和战略要求，对不同国家进行经营定位，提出规模、份额、盈利、用户、供给或模式验证等目标优先级。\n3. 建立自上而下与自下而上相结合的目标校验机制，判断国家计划与全球战略是否一致，不同国家的目标压力和资源配置是否合理、可解释。\n4. 将订单、用户、供给、履约、定价、补贴、收入和利润等关键变量纳入目标模型，识别增长路径、资源需求、回报质量和关键约束。\n5. 统筹月度滚动预测，持续更新全年预估、目标偏差、资源变化和关键假设，形成跨国横向比较、风险分级及待决策事项。\n6. 面向高级管理层和国家 GM 输出清晰的经营判断，讲清事实、假设、选择和代价，推动目标调整、资源配置及关键经营动作形成决策。\n7. 沉淀全球目标管理方法，包括国家分型、目标拆解、资源回报测算、关键假设库、风险升级标准和典型案例，并推动目标管理 AI 工具建设和应用。","requirements":"1. 5 年及以上经营分析、商业分析、战略规划、战略财务或目标预算相关经验，能够独立负责一个业务线、区域或多个国家的目标与经营管理。\n2. 完整参与过年度经营规划、预算、滚动预测和经营复盘。能基于市场阶段和战略选择设计目标，具备较强的 P&L、单位经济和资源效率意识，能够讲清规模、份额、用户价值、供给、履约、补贴、收入和利润之间的关系。\n3. 具备跨业务、跨职能项目推动能力，推动国家商分、GM、财务、业务和数据团队共同完成复杂交付。\n4. 具备优秀的管理层表达和书面表达能力，能将复杂分析转化为可讨论、可选择、可执行的管理建议。\n5. 熟练使用 SQL 和常用分析工具，能够独立完成业务测算和数据校验；能在英文环境下工作，接受跨时区协作及必要的海外出差。","description":"部门介绍\nKeeta是全球领先外卖平台美团旗下的独立品牌，肩负着“帮大家吃得更好，生活更好”的使命。依托美团深耕中国市场15年的技术与运营积淀，我们正引领全球餐饮与商品即时配送服务的创新与发展。\n\n自2023年成立以来，Keeta始终扎根社区并创造价值。我们为用户提供可靠的外卖体验，以智慧技术助餐厅提升经营效率，在为骑手拓宽收入来源的同时，也充分提供安全保障措施。基于这份多方共赢、共同成长的理念，我们的业务已从中国香港稳步拓展至中东及巴西，并持续向世界迈进。\n\n岗位职责\n1. 统筹多个海外市场的年度经营规划，建立统一的规划节奏、国家目标包、核心假设口径和管理层决策流程。\n2. 结合市场空间、竞争格局、发展阶段、组织能力和战略要求，对不同国家进行经营定位，提出规模、份额、盈利、用户、供给或模式验证等目标优先级。\n3. 建立自上而下与自下而上相结合的目标校验机制，判断国家计划与全球战略是否一致，不同国家的目标压力和资源配置是否合理、可解释。\n4. 将订单、用户、供给、履约、定价、补贴、收入和利润等关键变量纳入目标模型，识别增长路径、资源需求、回报质量和关键约束。\n5. 统筹月度滚动预测，持续更新全年预估、目标偏差、资源变化和关键假设，形成跨国横向比较、风险分级及待决策事项。\n6. 面向高级管理层和国家 GM 输出清晰的经营判断，讲清事实、假设、选择和代价，推动目标调整、资源配置及关键经营动作形成决策。\n7. 沉淀全球目标管理方法，包括国家分型、目标拆解、资源回报测算、关键假设库、风险升级标准和典型案例，并推动目标管理 AI 工具建设和应用。\n\n岗位基本要求\n1. 5 年及以上经营分析、商业分析、战略规划、战略财务或目标预算相关经验，能够独立负责一个业务线、区域或多个国家的目标与经营管理。\n2. 完整参与过年度经营规划、预算、滚动预测和经营复盘。能基于市场阶段和战略选择设计目标，具备较强的 P&L、单位经济和资源效率意识，能够讲清规模、份额、用户价值、供给、履约、补贴、收入和利润之间的关系。\n3. 具备跨业务、跨职能项目推动能力，推动国家商分、GM、财务、业务和数据团队共同完成复杂交付。\n4. 具备优秀的管理层表达和书面表达能力，能将复杂分析转化为可讨论、可选择、可执行的管理建议。\n5. 熟练使用 SQL 和常用分析工具，能够独立完成业务测算和数据校验；能在英文环境下工作，接受跨时区协作及必要的海外出差。\n\n具备以下条件优先\n1. 有外卖、即时零售、电商、出行、酒旅或其他平台型业务经验。\n2. 有海外多国经营、新市场从 0 到 1、区域目标统筹经验。\n3. 做过市场进入、国家战略定位、目标预算、资源配置、滚动预测或盈利规划。\n4. 曾直接支持 CEO、区域负责人、国家 GM 或事业部负责人进行经营决策。\n5. 有将目标管理方法沉淀为模板、机制、数据产品或 AI 工具的经验。\n\n岗位亮点\n1. 我们期待你真正参与目标选择和资源取舍，让年度规划能够被持续追踪、验证和调整，并将多国经营经验沉淀为组织能力。\n2. 你会面对不同市场阶段、竞争环境和经营约束下的真实问题，需要在不完全信息中形成判断，也有机会参与 Keeta 全球经营管理机制从建立到成熟的全过程。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4647648944","sourceKey":"meituan_social","company":"美团","title":"闪购-店铺运营专家-华北","city":"北京市/青岛市/石家庄市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4647648944&jobShareType=1","duty":"1.根据区域消费特征及市场行情变化，制定城市/门店差异化运营策略（包含但不限于门店选址/商品运营/营销活动/门店营运管理/流量投放等）；\n2.协调内外部营销活动资源，指导并监督合作商落地执行，实现品牌销售增长目标；\n3.对合作商及门店日常运营进行监控，对运营数据进行分析，及时发现异常并探寻可增长点；\n4.负责建立日常运营管理工具，为运营监控提效，为合作商赋能；\n5.负责与协同部门及合作商密切沟通，促进品牌整体运营结果达成和策略落地。","requirements":"1.有连锁品牌线上运营管理经验，熟悉外卖运营规则，超市便利品类优先；\n2.有较强的数据分析能力，熟练使用SQL优先；\n3.有较强的多方协同能力、沟通能力；\n4.有较强的有自驱力、执行力；\n5.能适应快速变化及快节奏工作。","description":"部门介绍\n美团闪购是美团旗下的即时零售平台，依托即时配送能力，连接本地零售供给，满足消费者30分钟万物到家的即时需求。美团闪购涵盖超市便利、食材、水果、鲜花绿植、休闲零食、酒水饮料、数码家电、美妆个护、母婴玩具、日用百货、服饰鞋帽、宠物等诸多品类，业务覆盖全国近3,000个县市区旗，每日百万级在岗骑手，以高效的配送、丰富的品类和广泛的覆盖，为美团数亿用户带来便捷的生活体验，积极助力实体零售线上化转型，提升本地商业活力。\n\n岗位职责\n1.根据区域消费特征及市场行情变化，制定城市/门店差异化运营策略（包含但不限于门店选址/商品运营/营销活动/门店营运管理/流量投放等）；\n2.协调内外部营销活动资源，指导并监督合作商落地执行，实现品牌销售增长目标；\n3.对合作商及门店日常运营进行监控，对运营数据进行分析，及时发现异常并探寻可增长点；\n4.负责建立日常运营管理工具，为运营监控提效，为合作商赋能；\n5.负责与协同部门及合作商密切沟通，促进品牌整体运营结果达成和策略落地。\n\n岗位基本要求\n1.有连锁品牌线上运营管理经验，熟悉外卖运营规则，超市便利品类优先；\n2.有较强的数据分析能力，熟练使用SQL优先；\n3.有较强的多方协同能力、沟通能力；\n4.有较强的有自驱力、执行力；\n5.能适应快速变化及快节奏工作。\n\n岗位亮点\n1.有机会从0-1跟随项目成长，更广阔的的视角，更多的机会与发展空间；\n2.工作氛围简单、直接、开放、高效。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4491564181","sourceKey":"meituan_social","company":"美团","title":"酒店直连通道运营专家","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4491564181&jobShareType=1","duty":"1.负责酒店直连通道的运营管理，统筹商家侧咨询响应机制、预订链路监控及异常问题的协调处理，保障直连交易链路的稳定性与高效性；\n2.负责商家供给运营体系的管理与优化，推进供应商、酒店及房型产品的上下线运营和营销配置标准化，持续提升供给质量与运营效率；合理配置监控报警机制，确保异常信息准确触达相关方。\n3.负责境内重点酒店商家的供给运营，通过数据分析和一线调研洞察供给问题，联动产品与业务团队制定解决方案并推动落地，闭环负责商家供给策略的产出与结果达成。\n4.负责直连/预付产品策略的制定与运营，推动核心商家供给质量提升；多方协同确保产品策略在商家端的有效执行与闭环。\n5.通过数据归因识别供给机会，持续优化商家供给效率指标；定期输出业务数据分析报告，为运营决策提供数据支持；沉淀共性问题与知识库，探索AI工具在运营场景的落地应用。","requirements":"1.大学本科及以上学历，5年以上酒店/旅游/OTA行业相关经验。\n2.熟悉重点商家的供给运营模式；熟悉商家分层分类、供应链经营成本分析、供需联动相关知识。\n3.具备OTA产品运营、B端商家运营或商务合作经验者优先；有供给运营或业主关系经验优先。\n4.具备优秀的数据分析能力，能通过数据归因识别供给问题并推动改进；有熟练的项目复盘能力；具备体系性思考能力，表达逻辑清晰。\n5.具备出色的沟通理解能力、团队合作能力与项目推动管理能力，能高效协同多部门落地项目。\n6.能结合AI工具输出做业务判断，具备与AI产品团队协同的经验优先；对大模型在B端运营场景的应用有基础认知。\n7.学习能力强，自我驱动，有韧劲。","description":"部门介绍\n美团酒店旅行业务涵盖酒店、民宿、机票、火车票、旅游度假、景点门票等各类住行游品类，通过与产业上下游的深度合作，为用户提供美好的旅游旅行体验。我们积极打造AI友好型组织，使用AI等新技术提升旅游服务的供需匹配效率，更好满足用户个性化、多样化的出游需求。我们持续深耕产业链，用数字化服务助力实体商家高质量经营，探索自有品牌等供给新模式，打造健康的商家生态，保障用户服务体验。为满足用户日益增长的跨境旅行需求，我们将聚焦亚太区域，打造高品质的住宿、交通、游玩等服务矩阵。\n这里有多元的业务布局、持续的成长空间，无论是向往的远方还是眼前的工作，一路都是风景相伴。加入我们，共同为用户创造旅游旅行中的高光时刻！\n\n岗位职责\n1.负责酒店直连通道的运营管理，统筹商家侧咨询响应机制、预订链路监控及异常问题的协调处理，保障直连交易链路的稳定性与高效性；\n2.负责商家供给运营体系的管理与优化，推进供应商、酒店及房型产品的上下线运营和营销配置标准化，持续提升供给质量与运营效率；合理配置监控报警机制，确保异常信息准确触达相关方。\n3.负责境内重点酒店商家的供给运营，通过数据分析和一线调研洞察供给问题，联动产品与业务团队制定解决方案并推动落地，闭环负责商家供给策略的产出与结果达成。\n4.负责直连/预付产品策略的制定与运营，推动核心商家供给质量提升；多方协同确保产品策略在商家端的有效执行与闭环。\n5.通过数据归因识别供给机会，持续优化商家供给效率指标；定期输出业务数据分析报告，为运营决策提供数据支持；沉淀共性问题与知识库，探索AI工具在运营场景的落地应用。\n\n岗位基本要求\n1.大学本科及以上学历，5年以上酒店/旅游/OTA行业相关经验。\n2.熟悉重点商家的供给运营模式；熟悉商家分层分类、供应链经营成本分析、供需联动相关知识。\n3.具备OTA产品运营、B端商家运营或商务合作经验者优先；有供给运营或业主关系经验优先。\n4.具备优秀的数据分析能力，能通过数据归因识别供给问题并推动改进；有熟练的项目复盘能力；具备体系性思考能力，表达逻辑清晰。\n5.具备出色的沟通理解能力、团队合作能力与项目推动管理能力，能高效协同多部门落地项目。\n6.能结合AI工具输出做业务判断，具备与AI产品团队协同的经验优先；对大模型在B端运营场景的应用有基础认知。\n7.学习能力强，自我驱动，有韧劲。\n\n具备以下条件优先\n1.有供给运营或商家关系管理经验。\n2.有OTA平台商家运营或产品运营经验。\n3.对直连产品（系统对接、通道建设等）有基础认知。\n4.了解大模型在B端运营场景的应用方向。\n\n岗位亮点\n1.参与核心商家的供给业务，对接行业头部品牌；岗位职能兼具体系建设和业务实践。\n2.主导产品策略从需求到落地的全链路；可构建深入的业务领域知识体系，有机会在多个细分领域探索、积累、实践。\n3.独立owner方向，接触直连/预付等产品体系，提升跨业务环节的系统化运营能力。\n4.团队氛围开放、友好，具备业务与产品方法论体系及培养机制。\n5.发展方向清晰：入职以通道运营为核心，积累业务理解后可向供给运营、策略运营方向发展。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4721095543","sourceKey":"meituan_social","company":"美团","title":"上海仓拣库存主管","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4721095543&jobShareType=1","duty":"1. 负责上海仓拣货区域的日常运营管理，确保拣货、补货、盘点等作业高效有序进行。  \n2. 管理并带领团队，制定排班计划，监督执行标准操作流程，提升团队作业效率。  \n3. 监控库存准确率，组织定期盘点，分析差异原因并推动改进措施落地。  \n4. 协同仓储运营团队，优化拣货路径与库存布局，降低作业成本。  \n5. 落实安全管理制度，开展员工培训，营造安全、规范的工作环境。","requirements":"1. 大学专科及以上学历，物流、供应链或相关专业优先。  \n2. 具备3年以上仓储物流现场管理经验，有电商或快消行业背景者优先。  \n3. 熟悉WMS系统操作及库存管理流程，具备数据分析与问题解决能力。  \n4. 具备较强的团队管理与沟通协调能力，能承受一定工作压力。  \n5. 熟练使用办公软件，具备基本的英语读写能力。","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1. 负责上海仓拣货区域的日常运营管理，确保拣货、补货、盘点等作业高效有序进行。  \n2. 管理并带领团队，制定排班计划，监督执行标准操作流程，提升团队作业效率。  \n3. 监控库存准确率，组织定期盘点，分析差异原因并推动改进措施落地。  \n4. 协同仓储运营团队，优化拣货路径与库存布局，降低作业成本。  \n5. 落实安全管理制度，开展员工培训，营造安全、规范的工作环境。\n\n岗位基本要求\n1. 大学专科及以上学历，物流、供应链或相关专业优先。  \n2. 具备3年以上仓储物流现场管理经验，有电商或快消行业背景者优先。  \n3. 熟悉WMS系统操作及库存管理流程，具备数据分析与问题解决能力。  \n4. 具备较强的团队管理与沟通协调能力，能承受一定工作压力。  \n5. 熟练使用办公软件，具备基本的英语读写能力。\n\n岗位亮点\n1. 大型仓储团队管理经验积累，快速提升综合管理能力。  \n2. 位于上海核心物流枢纽，业务规模大，发展平台广阔。  \n3. 完善的培训体系与晋升通道，支持个人职业成长。  \n4. 行业具有竞争力的薪酬福利与绩效激励机制。  \n5. 扁平化管理氛围，注重员工发展与团队协作。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4435462200","sourceKey":"meituan_social","company":"美团","title":"AI支付产品经理","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4435462200&jobShareType=1","duty":"负责AI 支付产品的整体规划与路线图制定，定义产品边界、体验标准与演进节奏，推动从0到1的产品落地。\n\n深入了解业务场景，识别业务痛点，聚焦支付核心链路，构建主动服务型智能产品，提升平台整体效率与用户体验。\n\n通过新的协作范式，完成产品方案设计，与协作团队紧密配合，把控从方案到上线的完整交付链路；建立产品效果评估体系，通过数据与用户反馈持续优化产品体验。\n\n持续观察行业最前沿的技术能力及应用实例，为团队输入有效的信息。","requirements":"3年以上互联网产品经验，了解 LLM/Agent 技术原理，有 AI 产品实践经验。有金融支付背景优先。\n\n具备优秀的用户洞察与需求分析能力，能够独立完成复杂产品方案设计、设计评测方案、分析线上数据。\n\n有良好的学习能力和自驱力，持续关注行业前沿，输出可落地的产品建议。","description":"部门介绍\n美团金融服务平台成立于2016年，以“场景+金融”模式，携手合作伙伴构建开放生态，为美团平台用户和商户提供底层账户、支付通道、信贷、保险和理财等金融解决方案。我们致力于以科技为核心，助力金融机构打通金融普惠“最后一公里”。我们期待与大家共同完成每一件平凡而卓越的事情，一起为用户提供优质的产品体验，守护用户的资金安全，让生活变得更美好。\n\n岗位职责\n负责AI 支付产品的整体规划与路线图制定，定义产品边界、体验标准与演进节奏，推动从0到1的产品落地。\n\n深入了解业务场景，识别业务痛点，聚焦支付核心链路，构建主动服务型智能产品，提升平台整体效率与用户体验。\n\n通过新的协作范式，完成产品方案设计，与协作团队紧密配合，把控从方案到上线的完整交付链路；建立产品效果评估体系，通过数据与用户反馈持续优化产品体验。\n\n持续观察行业最前沿的技术能力及应用实例，为团队输入有效的信息。\n\n岗位基本要求\n3年以上互联网产品经验，了解 LLM/Agent 技术原理，有 AI 产品实践经验。有金融支付背景优先。\n\n具备优秀的用户洞察与需求分析能力，能够独立完成复杂产品方案设计、设计评测方案、分析线上数据。\n\n有良好的学习能力和自驱力，持续关注行业前沿，输出可落地的产品建议。\n\n岗位亮点\n美团有丰富的业务场景，AI 落地空间极大，参与并推动AI支付产品从 0 到 1 的落地。\n\n美团连接数亿用户与千万商家，支付作为连接交易、资金与商业的关键环节，价值巨大。\n\n新团队刚成立，扁平化管理，产研一体，汇报给业务负责人，流程简单高效，想法快速落地。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4676963042","sourceKey":"meituan_social","company":"美团","title":"净菜运营总监","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4676963042&jobShareType=1","duty":"1. 负责净菜业务的整体运营规划与管理，制定并执行运营策略，提升运营效率与服务质量。  \n2. 协同供应链各环节，包括采购、品控、加工、配送等，确保流程标准化与成本优化。  \n3. 带领团队完成日常运营目标，监控关键指标，及时调整运营方案以应对市场变化。  \n4. 推动净菜产品标准化建设，保证质量目标达成；  \n5. 根据公司下发目标，制定经营策略，提升毛利降低成本，带领团队逐步拓展深加工边界拓展.","requirements":"1. 大学本科及以上学历，物流\\食品科学或相关专业优先。  \n2. 具备8年以上生鲜运营相关工作经验，有净菜、预制菜背景者优先。  \n3. 具备资深运营管理能力，有100人以上团队管理经验，擅长跨部门协作与资源整合。  \n4. 熟悉生鲜供应链全流程，对食品安全、冷链物流、仓储管理有深入理解。  \n5. 具备较强的数据分析能力与战略思维，能独立制定并推动运营策略落地。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1. 负责净菜业务的整体运营规划与管理，制定并执行运营策略，提升运营效率与服务质量。  \n2. 协同供应链各环节，包括采购、品控、加工、配送等，确保流程标准化与成本优化。  \n3. 带领团队完成日常运营目标，监控关键指标，及时调整运营方案以应对市场变化。  \n4. 推动净菜产品标准化建设，保证质量目标达成；  \n5. 根据公司下发目标，制定经营策略，提升毛利降低成本，带领团队逐步拓展深加工边界拓展.\n\n岗位基本要求\n1. 大学本科及以上学历，物流\\食品科学或相关专业优先。  \n2. 具备8年以上生鲜运营相关工作经验，有净菜、预制菜背景者优先。  \n3. 具备资深运营管理能力，有100人以上团队管理经验，擅长跨部门协作与资源整合。  \n4. 熟悉生鲜供应链全流程，对食品安全、冷链物流、仓储管理有深入理解。  \n5. 具备较强的数据分析能力与战略思维，能独立制定并推动运营策略落地。\n\n具备以下条件优先\n1、具有净菜和沙拉菜生产管理者优先；\n2、具有城市管理和中台运营能力者优先；\n\n岗位亮点\n1. 加入快速发展的生鲜行业，参与净菜业务从0到1的规模化建设。  \n2. 拥有高度自主权，全面负责运营体系搭建与团队管理。  \n 3. 工作地点位于北京，享受具有竞争力的薪酬与职业发展通道。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4645387574","sourceKey":"meituan_social","company":"美团","title":"仓储经理","city":"深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4645387574&jobShareType=1","duty":"1.负责RDC仓库的日常运营管理工作，包括入库、出库、库存管理等，确保仓库运作顺畅。\n2.负责制定并执行仓库的作业流程和标准操作规范，提高工作效率和准确性。\n3.负责团队的日常管理和指导，培训新员工，提升团队整体素质。\n4.负责仓库设备的维护和保养，确保设备正常运转。\n5.协调内部各部门，保障仓库运营的顺利进行。","requirements":"1.大学专科及以上学历，物流管理、仓储管理等相关专业优先。\n2.具有5年以上物流/仓储运营管理经验，有大型RDC仓库管理经验者优先。\n3.具备良好的团队管理能力和沟通协调能力，能够有效领导团队达成目标。\n4.熟悉仓储管理系统和操作流程，具备较强的数据分析能力和问题解决能力。\n5.有韧性，由良好的应变能力，能够应对复杂的工作环境和突发事件。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1.负责RDC仓库的日常运营管理工作，包括入库、出库、库存管理等，确保仓库运作顺畅。\n2.负责制定并执行仓库的作业流程和标准操作规范，提高工作效率和准确性。\n3.负责团队的日常管理和指导，培训新员工，提升团队整体素质。\n4.负责仓库设备的维护和保养，确保设备正常运转。\n5.协调内部各部门，保障仓库运营的顺利进行。\n\n岗位基本要求\n1.大学专科及以上学历，物流管理、仓储管理等相关专业优先。\n2.具有5年以上物流/仓储运营管理经验，有大型RDC仓库管理经验者优先。\n3.具备良好的团队管理能力和沟通协调能力，能够有效领导团队达成目标。\n4.熟悉仓储管理系统和操作流程，具备较强的数据分析能力和问题解决能力。\n5.有韧性，由良好的应变能力，能够应对复杂的工作环境和突发事件。\n\n岗位亮点\n1.薪资福利优厚，提供完善的培训和晋升机会。\n2.工作地点灵活，可选择在上海市或苏州市。\n3.所属团队规模适中，工作氛围轻松愉快，有较大的发展空间。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4665479999","sourceKey":"meituan_social","company":"美团","title":"运筹优化算法工程师","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4665479999&jobShareType=1","duty":"1. 负责骑行换电&资产业务相关的运筹优化算法设计、研发和迭代优化，包括但不限于资产找寻调度、换电调度、换电智能排班、换电站点选址、换电责任田划分等\n\n2. 参与算法体系搭建，抽象并定义算法问题、算法技术选型、模型搭建、落地推广应用，实现业务效果优化\n\n3. 深入了解业务，与产品、工程、数据、业务团队密切合作，持续推动从算法技术到业务价值的转化，驱动业务变革\n\n4. 综合运用机器学习、运筹优化、强化学习、因果推断、大模型等前沿技术优化骑行领域的相关问题","requirements":"1. 硕士研究生及以上学历，专业背景为运筹学、数学、计算机科学等相关领域\n\n2. 熟悉常用的运筹调度算法和模型优化方法，具备扎实的运筹优化理论基础\n\n3. 熟悉运筹调度问题的建模和求解，具备扎实的数学基础和优秀的分析能力\n\n4. 熟练掌握至少一种编程语言，如Java、Python、C++等，并具备良好的编程能力\n\n5. 具备良好的沟通能力和团队合作精神，能够与各个团队紧密合作，解决问题\n\n6. 具备较强的自我驱动力和学习能力，了解常用 AI Coding 工作范式、方法论等","description":"部门介绍\n美团的使命是“帮大家吃得更好，生活更好”，公司聚焦“零售 + 科技”战略，和广大商户与各类合作伙伴一起，努力为消费者提供品质生活，推动商品零售和服务零售在需求侧和供给侧的数字化转型。\n2018年9月20日，美团正式在港交所挂牌上市。美团将始终坚持以客户为中心，不断加大在科技研发方面的投入，更好承担社会责任，更多创造社会价值，与广大合作伙伴一起发展共赢。\n\n岗位职责\n1. 负责骑行换电&资产业务相关的运筹优化算法设计、研发和迭代优化，包括但不限于资产找寻调度、换电调度、换电智能排班、换电站点选址、换电责任田划分等\n\n2. 参与算法体系搭建，抽象并定义算法问题、算法技术选型、模型搭建、落地推广应用，实现业务效果优化\n\n3. 深入了解业务，与产品、工程、数据、业务团队密切合作，持续推动从算法技术到业务价值的转化，驱动业务变革\n\n4. 综合运用机器学习、运筹优化、强化学习、因果推断、大模型等前沿技术优化骑行领域的相关问题\n\n岗位基本要求\n1. 硕士研究生及以上学历，专业背景为运筹学、数学、计算机科学等相关领域\n\n2. 熟悉常用的运筹调度算法和模型优化方法，具备扎实的运筹优化理论基础\n\n3. 熟悉运筹调度问题的建模和求解，具备扎实的数学基础和优秀的分析能力\n\n4. 熟练掌握至少一种编程语言，如Java、Python、C++等，并具备良好的编程能力\n\n5. 具备良好的沟通能力和团队合作精神，能够与各个团队紧密合作，解决问题\n\n6. 具备较强的自我驱动力和学习能力，了解常用 AI Coding 工作范式、方法论等\n\n岗位亮点\n1. 业务价值高：核心决策岗位，算法方案直接作用于业务关键运营指标，从底层驱动成本优化与效率提升，技术投入的 ROI 高度可量化\n\n2. 技术纵深广：深度融合运筹优化、机器学习、强化学习等多技术栈，技术挑战覆盖从复杂业务建模、大规模高效求解到在线自适应决策的完整算法链路","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4687058259","sourceKey":"meituan_social","company":"美团","title":"丽人行业专家（美发方向）","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4687058259&jobShareType=1","duty":"1、行业经营\n对所负责细分行业的经营结果端到端负责，包括收入（CPS/CPC/增值服务）、交易规模（GTV）、补贴效率与投入产出比，独立完成年度/季度运营规划与目标拆解；\n基于市场规模、竞争格局、供需结构的定量分析，判断行业所处阶段与核心矛盾，识别增长杠杆；\n\n2、产运端到端闭环\n不止于提出需求，而是定义产品：基于对用户决策链路和商家经营流程的理解，输出产品策略与方案，与协作团队共同完成从 0 到 1 的能力建设；\n打通「策略设计 → 产品落地 → 运营放大 → 效果归因 → 策略迭代」的完整闭环，对闭环中的每一环负责，而非只负责其中一段；\n推动能力从单点验证走向规模化：把为头部客户定制的解决方案，抽象为可低成本复制的标准产品与 SOP。\n\n3、商家分层经营与生态建设\n基于商家规模、经营意识、数字化程度进行分层，针对不同层级设计差异化的产品组合、激励政策与服务模式；\n\n4、方法论沉淀\n将实践中验证有效的策略抽象为可迁移的方法论，形成可复制的行业解决方案；","requirements":"本科及以上学历，3 年以上产品、行业运营、商家运营、产品运营或战略/商业分析经验；\n有完整负责过一个业务单元或从 0 到 1 项目的经历，能清晰讲出自己的判断逻辑与结果归因。\n\n核心能力要求\n① 行业洞察力\n掌握结构化的行业分析方法，能独立完成市场规模测算、竞争格局分析、供需结构拆解和上下游产业链梳理；\n对线下商业的真实经营逻辑有体感——理解一家门店的成本结构、人员激励、获客路径，而非只看得懂线上数据；\n\n② 产品闭环能力\n具备产品思维，能独立输出产品策略、参与方案设计，与产研团队高效对话；\n理解 AI 时代的产品设计范式差异——从「设计操作流程」转向「定义目标与约束」，从「控制每一步」转向「信任与验证结果」；\n有推动复杂产品从设计到上线到规模化覆盖的完整经验。\n\n③ AI 应用能力\n在实际工作中高频使用 AI 完成分析、内容生产、方案设计等任务，对 AI 的能力边界与失效模式有真实体感；\n加分项：有 Agent/AI 产品的设计或落地经验，理解评测体系、知识库建设、工具调用等核心机制；\n\n④ 数据驱动\n强数据敏感度，能通过指标异动定位业务问题，建立输入-输出指标体系并持续迭代；\n能用数据支撑决策与说服，而非用观点说服。\n\n⑤ 推动力与影响力\n具备复杂项目的跨组织协调能力，能在多方目标不一致时找到共识路径；\n具备面对高模糊度问题时的韧性——从定策略、到多方对齐、到能力迭代、到销售侧落地，链条长、周期久、变量多。","description":"部门介绍\n美团服务零售事业部下设乐生活业务部、易生活业务部、进场零售业务部以及中小城市发展部四大业务部门，旨在通过提供丰富、可靠、实惠的服务与商品满足用户各类生活需求。我们所处的服务零售行业是一个具有万亿规模的市场，覆盖足疗洗浴、酒吧KTV、运动健身、美发美甲、教育培训、亲子游乐、家政洗涤维修、摄影写真等数十个服务消费细分领域，同时延伸至超市便利、美妆个护、3C数码、服饰珠宝、运动户外、商场购物中心等实体零售到店消费场景，连接数十万品牌商户与线下门店。作为商家和行业的小帮手，我们持续深入服务零售与实体零售产业链，用AI等技术推动行业变革，帮助商家提升经营效率、实现高效的线上化经营与到店转化，优化消费者服务体验，提供安心、放心的履约保障。这里有着多元的业务布局，有着富有挑战和影响力的工作内容，为你提供丰富的视野、持续的成长和发展机会，引领你发现更多可能。期待和你在“随时随地，美好生活”的愿景指引下，共建美好的生活服务体验、健康的商家生态与高质量的经营结果。\n\n岗位职责\n1、行业经营\n对所负责细分行业的经营结果端到端负责，包括收入（CPS/CPC/增值服务）、交易规模（GTV）、补贴效率与投入产出比，独立完成年度/季度运营规划与目标拆解；\n基于市场规模、竞争格局、供需结构的定量分析，判断行业所处阶段与核心矛盾，识别增长杠杆；\n\n2、产运端到端闭环\n不止于提出需求，而是定义产品：基于对用户决策链路和商家经营流程的理解，输出产品策略与方案，与协作团队共同完成从 0 到 1 的能力建设；\n打通「策略设计 → 产品落地 → 运营放大 → 效果归因 → 策略迭代」的完整闭环，对闭环中的每一环负责，而非只负责其中一段；\n推动能力从单点验证走向规模化：把为头部客户定制的解决方案，抽象为可低成本复制的标准产品与 SOP。\n\n3、商家分层经营与生态建设\n基于商家规模、经营意识、数字化程度进行分层，针对不同层级设计差异化的产品组合、激励政策与服务模式；\n\n4、方法论沉淀\n将实践中验证有效的策略抽象为可迁移的方法论，形成可复制的行业解决方案；\n\n岗位基本要求\n本科及以上学历，3 年以上产品、行业运营、商家运营、产品运营或战略/商业分析经验；\n有完整负责过一个业务单元或从 0 到 1 项目的经历，能清晰讲出自己的判断逻辑与结果归因。\n\n核心能力要求\n① 行业洞察力\n掌握结构化的行业分析方法，能独立完成市场规模测算、竞争格局分析、供需结构拆解和上下游产业链梳理；\n对线下商业的真实经营逻辑有体感——理解一家门店的成本结构、人员激励、获客路径，而非只看得懂线上数据；\n\n② 产品闭环能力\n具备产品思维，能独立输出产品策略、参与方案设计，与产研团队高效对话；\n理解 AI 时代的产品设计范式差异——从「设计操作流程」转向「定义目标与约束」，从「控制每一步」转向「信任与验证结果」；\n有推动复杂产品从设计到上线到规模化覆盖的完整经验。\n\n③ AI 应用能力\n在实际工作中高频使用 AI 完成分析、内容生产、方案设计等任务，对 AI 的能力边界与失效模式有真实体感；\n加分项：有 Agent/AI 产品的设计或落地经验，理解评测体系、知识库建设、工具调用等核心机制；\n\n④ 数据驱动\n强数据敏感度，能通过指标异动定位业务问题，建立输入-输出指标体系并持续迭代；\n能用数据支撑决策与说服，而非用观点说服。\n\n⑤ 推动力与影响力\n具备复杂项目的跨组织协调能力，能在多方目标不一致时找到共识路径；\n具备面对高模糊度问题时的韧性——从定策略、到多方对齐、到能力迭代、到销售侧落地，链条长、周期久、变量多。\n\n岗位亮点\n1、你负责的不是一个项目，而是一个行业单元。统筹看策略、产品方向、资源调度，最接近「创业」的组织内岗位形态。\n\n2、服务零售是 AI 最难啃、但一旦啃下来非常有价值的场景——高度非标、角色复杂、数据分散。你不是在用别人做好的 AI 工具，而是在定义 AI 在这个行业里应该长什么样。这段经历在市场上具有稀缺性。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4701902765","sourceKey":"meituan_social","company":"美团","title":"运健行业运营","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4701902765&jobShareType=1","duty":"1. 负责运健行业用户和供给管理，包括行业流量运营、商家及供给日常运营，促平台交易转化；\n2. 协助制定并执行行业运营策略，提升多渠道用户流量、商家活跃度和供给丰富度；\n3. 深入运健产业链/价值链，探查机会点，并输出产品方案，推动商业化收入达成；\n4. 与产品、市场、销售等团队协作，推动运营工具及流程的AI优化落地，持续提升工作效率。","requirements":"1. 大学本科及以上学历，具备3年以上产品运营或商家运营相关工作经验。\n2. 熟悉运健行业者（如运动健身、健康管理等）及AI工具使用者优先。\n3. 具备较强的数据分析能力，熟练使用AI分析工具。\n4. 具备良好的沟通能力和团队协作意识，能承受一定工作压力。","description":"部门介绍\n美团服务零售事业部下设乐生活业务部、易生活业务部、进场零售业务部以及中小城市发展部四大业务部门，旨在通过提供丰富、可靠、实惠的服务与商品满足用户各类生活需求。我们所处的服务零售行业是一个具有万亿规模的市场，覆盖足疗洗浴、酒吧KTV、运动健身、美发美甲、教育培训、亲子游乐、家政洗涤维修、摄影写真等数十个服务消费细分领域，同时延伸至超市便利、美妆个护、3C数码、服饰珠宝、运动户外、商场购物中心等实体零售到店消费场景，连接数十万品牌商户与线下门店。作为商家和行业的小帮手，我们持续深入服务零售与实体零售产业链，用AI等技术推动行业变革，帮助商家提升经营效率、实现高效的线上化经营与到店转化，优化消费者服务体验，提供安心、放心的履约保障。这里有着多元的业务布局，有着富有挑战和影响力的工作内容，为你提供丰富的视野、持续的成长和发展机会，引领你发现更多可能。期待和你在“随时随地，美好生活”的愿景指引下，共建美好的生活服务体验、健康的商家生态与高质量的经营结果。\n\n岗位职责\n1. 负责运健行业用户和供给管理，包括行业流量运营、商家及供给日常运营，促平台交易转化；\n2. 协助制定并执行行业运营策略，提升多渠道用户流量、商家活跃度和供给丰富度；\n3. 深入运健产业链/价值链，探查机会点，并输出产品方案，推动商业化收入达成；\n4. 与产品、市场、销售等团队协作，推动运营工具及流程的AI优化落地，持续提升工作效率。\n\n岗位基本要求\n1. 大学本科及以上学历，具备3年以上产品运营或商家运营相关工作经验。\n2. 熟悉运健行业者（如运动健身、健康管理等）及AI工具使用者优先。\n3. 具备较强的数据分析能力，熟练使用AI分析工具。\n4. 具备良好的沟通能力和团队协作意识，能承受一定工作压力。\n\n岗位亮点\n1. 加入快速发展的运健行业，参与平台生态建设。\n2. 与行业头部商家深度合作，积累丰富的运营经验。\n3. 成长空间大，有机会参与核心运动健身AI工具项目。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4709592616","sourceKey":"meituan_social","company":"美团","title":"小象超市-工程经理","city":"广州市/深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4709592616&jobShareType=1","duty":"1. 制度与体系：结合业务模式拟定工程管理制度并严格落实，建立符合小象超市业态特点的项目管理标准化流程，保障项目安全高效推进；\n2. 全面管控：对工程项目的进度、质量、成本、安全进行全面把控，持续优化项目管理模式，做好指导、监督与考核，确保批量开店目标达成；\n3. 多方协同：组织设计、施工、供应商等多方会审，主导重要物料及工程验收备案；实时监督总包/分包履约状况，敏锐捕捉工程问题并迅速给出整改方案；\n4. 选址与交接：实地勘察场地，协同拓展部明确技术条件，助力完成选址、签约与场地交接，对门店的工程可行性提供专业判断；\n5. 结算与审计：严谨审查竣工图纸与结算资料，推动审计结算进程，配合完成结算闭环，有效控制工程超支风险；\n6. 报批报建：牵头负责施工及消防报批报建工作，获取开工许可等审批文件，熟练应对各地政策差异；\n7. 供应商管理：以设计标准为指引管理供应商体系，驱动培训考核，持续提升施工执行能力和材料品控水平；\n8. 数字化工程管控：推动工程管理数字化落地——运用BIM/数字孪生进行施工前预演和图纸审查；\n9. 借助AI辅助工具（如AI图纸合规检查、AI工期/成本预警）提升工程决策效率；\n10. 借助智能工单系统实现多项目并行的进度追踪和问题闭环；配合门店智能化改造，完成IoT设备（冷链监控、能耗管理、智能安防）调试与验收交付。","requirements":"1. 5年以上连锁商超或餐饮工程管理实践经验；\n2. 工程、土木、机电专业出身优先熟悉商超/餐饮工程各类标准、规范、技术方案及常用设备（制冷/强弱电/消防等）\n3. 精通工程管理、招投标、成本管控流程，具备独立管理多项目并行能力拥有施工报建、消防报审全流程实操经验具备良好的跨部门沟通协调能力，能有效推动多方资源协同\n4. 具备BIM基础操作能力，或使用过工程数字化工具\n5. 有使用AI工具辅助工程工作的经验（如AI图纸审查、AI工程文档生成、AI成本测算等工具）","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1. 制度与体系：结合业务模式拟定工程管理制度并严格落实，建立符合小象超市业态特点的项目管理标准化流程，保障项目安全高效推进；\n2. 全面管控：对工程项目的进度、质量、成本、安全进行全面把控，持续优化项目管理模式，做好指导、监督与考核，确保批量开店目标达成；\n3. 多方协同：组织设计、施工、供应商等多方会审，主导重要物料及工程验收备案；实时监督总包/分包履约状况，敏锐捕捉工程问题并迅速给出整改方案；\n4. 选址与交接：实地勘察场地，协同拓展部明确技术条件，助力完成选址、签约与场地交接，对门店的工程可行性提供专业判断；\n5. 结算与审计：严谨审查竣工图纸与结算资料，推动审计结算进程，配合完成结算闭环，有效控制工程超支风险；\n6. 报批报建：牵头负责施工及消防报批报建工作，获取开工许可等审批文件，熟练应对各地政策差异；\n7. 供应商管理：以设计标准为指引管理供应商体系，驱动培训考核，持续提升施工执行能力和材料品控水平；\n8. 数字化工程管控：推动工程管理数字化落地——运用BIM/数字孪生进行施工前预演和图纸审查；\n9. 借助AI辅助工具（如AI图纸合规检查、AI工期/成本预警）提升工程决策效率；\n10. 借助智能工单系统实现多项目并行的进度追踪和问题闭环；配合门店智能化改造，完成IoT设备（冷链监控、能耗管理、智能安防）调试与验收交付。\n\n岗位基本要求\n1. 5年以上连锁商超或餐饮工程管理实践经验；\n2. 工程、土木、机电专业出身优先熟悉商超/餐饮工程各类标准、规范、技术方案及常用设备（制冷/强弱电/消防等）\n3. 精通工程管理、招投标、成本管控流程，具备独立管理多项目并行能力拥有施工报建、消防报审全流程实操经验具备良好的跨部门沟通协调能力，能有效推动多方资源协同\n4. 具备BIM基础操作能力，或使用过工程数字化工具\n5. 有使用AI工具辅助工程工作的经验（如AI图纸审查、AI工程文档生成、AI成本测算等工具）\n\n岗位亮点\n有机会全身心地参与新零售业态，和团队一起更快速、更有效的完成工程筹建，提升个人能力； 能和电商、物流、零售、人工智能等多元化背景的团队技术大牛一起，综合学习，共同进步；工程团队的图纸审查、进度预警、成本分析都在探索AI辅助，你将有机会成为\"AI+工程管理\"这个新方向的先行者","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4691912539","sourceKey":"meituan_social","company":"美团","title":"休闲行业运营","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4691912539&jobShareType=1","duty":"1. 负责按摩足疗&洗浴商家及供给的运营策略制定与执行，提升平台商家活跃度与供给质量\n2. 深度理解按摩足疗&洗浴行业用户需求与商家痛点，推动产品功能优化与运营活动落地\n3. 搭建并完善商家成长体系，通过数据分析驱动商家运营效率提升\n4. 协同产品、市场、技术等团队，推动行业解决方案的迭代与创新\n5. 定期输出运营数据分析报告，识别问题并推动持续优化","requirements":"1. 大学本科及以上学历，3年以上产品运营或商家运营相关工作经验\n2. 具备休闲行业（如按摩足疗、洗浴等）运营经验者优先\n3. 熟悉商家生命周期管理，具备较强的数据分析与策略制定能力\n4. 优秀的沟通协调能力和跨团队协作能力，具备较强的项目推动力\n5. 能适应快节奏工作环境，具备高度责任心","description":"部门介绍\n美团服务零售事业部下设乐生活业务部、易生活业务部、进场零售业务部以及中小城市发展部四大业务部门，旨在通过提供丰富、可靠、实惠的服务与商品满足用户各类生活需求。我们所处的服务零售行业是一个具有万亿规模的市场，覆盖足疗洗浴、酒吧KTV、运动健身、美发美甲、教育培训、亲子游乐、家政洗涤维修、摄影写真等数十个服务消费细分领域，同时延伸至超市便利、美妆个护、3C数码、服饰珠宝、运动户外、商场购物中心等实体零售到店消费场景，连接数十万品牌商户与线下门店。作为商家和行业的小帮手，我们持续深入服务零售与实体零售产业链，用AI等技术推动行业变革，帮助商家提升经营效率、实现高效的线上化经营与到店转化，优化消费者服务体验，提供安心、放心的履约保障。这里有着多元的业务布局，有着富有挑战和影响力的工作内容，为你提供丰富的视野、持续的成长和发展机会，引领你发现更多可能。期待和你在“随时随地，美好生活”的愿景指引下，共建美好的生活服务体验、健康的商家生态与高质量的经营结果。\n\n岗位职责\n1. 负责按摩足疗&洗浴商家及供给的运营策略制定与执行，提升平台商家活跃度与供给质量\n2. 深度理解按摩足疗&洗浴行业用户需求与商家痛点，推动产品功能优化与运营活动落地\n3. 搭建并完善商家成长体系，通过数据分析驱动商家运营效率提升\n4. 协同产品、市场、技术等团队，推动行业解决方案的迭代与创新\n5. 定期输出运营数据分析报告，识别问题并推动持续优化\n\n岗位基本要求\n1. 大学本科及以上学历，3年以上产品运营或商家运营相关工作经验\n2. 具备休闲行业（如按摩足疗、洗浴等）运营经验者优先\n3. 熟悉商家生命周期管理，具备较强的数据分析与策略制定能力\n4. 优秀的沟通协调能力和跨团队协作能力，具备较强的项目推动力\n5. 能适应快节奏工作环境，具备高度责任心\n\n具备以下条件优先\n具备AI运营的主观性，能用AI处理日常运营的绝大部分工作；数据逻辑强\n\n岗位亮点\n1. 深耕垂直行业，参与平台核心供给运营，发展空间广阔\n2. 与行业头部商家深度合作，积累丰富的B端运营经验\n3. 团队氛围开放，鼓励创新与数据驱动决策","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4720793416","sourceKey":"meituan_social","company":"美团","title":"丽人行业运营","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4720793416&jobShareType=1","duty":"1. 负责行业运营策略的制定与执行，结合市场趋势和用户需求，推动业务增长。  \n2. 协调产品、技术、市场等多方资源，确保项目高效落地并达成目标。  \n3. 深入分析行业数据，输出运营分析报告，为决策提供数据支持。  \n4. 搭建并优化行业运营流程，提升团队协作效率与运营质量。","requirements":"1. 大学本科及以上学历，3年以上产品运营或项目管理相关工作经验。  \n2. 具备优秀的沟通协调能力，能够推动跨部门协作。  \n3. 熟悉行业运营方法论，有成功案例者优先。  \n4. 具备较强的数据分析能力，熟练使用各类数据工具。","description":"部门介绍\n美团服务零售事业部下设乐生活业务部、易生活业务部、进场零售业务部以及中小城市发展部四大业务部门，旨在通过提供丰富、可靠、实惠的服务与商品满足用户各类生活需求。我们所处的服务零售行业是一个具有万亿规模的市场，覆盖足疗洗浴、酒吧KTV、运动健身、美发美甲、教育培训、亲子游乐、家政洗涤维修、摄影写真等数十个服务消费细分领域，同时延伸至超市便利、美妆个护、3C数码、服饰珠宝、运动户外、商场购物中心等实体零售到店消费场景，连接数十万品牌商户与线下门店。作为商家和行业的小帮手，我们持续深入服务零售与实体零售产业链，用AI等技术推动行业变革，帮助商家提升经营效率、实现高效的线上化经营与到店转化，优化消费者服务体验，提供安心、放心的履约保障。这里有着多元的业务布局，有着富有挑战和影响力的工作内容，为你提供丰富的视野、持续的成长和发展机会，引领你发现更多可能。期待和你在“随时随地，美好生活”的愿景指引下，共建美好的生活服务体验、健康的商家生态与高质量的经营结果。\n\n岗位职责\n1. 负责行业运营策略的制定与执行，结合市场趋势和用户需求，推动业务增长。  \n2. 协调产品、技术、市场等多方资源，确保项目高效落地并达成目标。  \n3. 深入分析行业数据，输出运营分析报告，为决策提供数据支持。  \n4. 搭建并优化行业运营流程，提升团队协作效率与运营质量。\n\n岗位基本要求\n1. 大学本科及以上学历，3年以上产品运营或项目管理相关工作经验。  \n2. 具备优秀的沟通协调能力，能够推动跨部门协作。  \n3. 熟悉行业运营方法论，有成功案例者优先。  \n4. 具备较强的数据分析能力，熟练使用各类数据工具。\n\n岗位亮点\n1. 参与核心业务运营，直接影响公司战略方向。  \n2. 与行业优秀团队共事，快速提升专业能力。  \n3. 提供广阔的职业发展空间和晋升机会。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4702367353","sourceKey":"meituan_social","company":"美团","title":"美团骑行-车辆运营主管（大理市）","city":"大理白族自治州","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4702367353&jobShareType=1","duty":"1.负责所属区域的车辆运营管理工作，对有效运营车辆和活跃车辆指标负责；\n2.通过实地观察、数据分析、行业分析，制定提升市占营收的经营策略，例如车辆投放、调度策略，故障干预策略等，提升市占营收等指标；\n3.组建和管理运维团队，包括一线运维司机、摆车人员；\n4.对接区域内政府主管部门，配合政府部门对城市运营问题进行管理。","requirements":"1.本科及以上学历，不限专业不限工作经历；\n2.具备较好的沟通协调能力和执行力。","description":"部门介绍\n美团骑行事业部在全国各个城市开展美团单车、电单车业务，提供绿色、便捷的共享出行服务，是美团出行板块重要的组成部分。我们力求为城市可持续发展提供低碳智能的解决方案，通过技术创新和硬件升级，不断优化全流程骑行体验，为低碳出行提供更好的服务。其中，美团单车旨在为城市居民提供通勤接驳服务，满足用户短途接驳出行需求；美团电单车则满足用户中短途多场景低碳出行需求。\n我们有开放的工作氛围，也有充满韧劲和创造力，心系低碳出行的伙伴。加入我们，一起为用户创造更好的出行体验。\n\n岗位职责\n1.负责所属区域的车辆运营管理工作，对有效运营车辆和活跃车辆指标负责；\n2.通过实地观察、数据分析、行业分析，制定提升市占营收的经营策略，例如车辆投放、调度策略，故障干预策略等，提升市占营收等指标；\n3.组建和管理运维团队，包括一线运维司机、摆车人员；\n4.对接区域内政府主管部门，配合政府部门对城市运营问题进行管理。\n\n岗位基本要求\n1.本科及以上学历，不限专业不限工作经历；\n2.具备较好的沟通协调能力和执行力。\n\n岗位亮点\n年轻团队、富有活力；发展空间大，开放的工作氛围","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4630136117","sourceKey":"meituan_social","company":"美团","title":"美团企业版-餐饮商户供应链商务拓展（BD）","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4630136117&jobShareType=1","duty":"品牌签约：负责所属品牌方的商务合作，包含外卖、到餐KA及CKA品牌，协同品牌业务、财税、SaaS等多方角色的方案讲解、商务谈判、合同签署；\n发票回收：负责所属品牌方的周期性发票回收工作；\n品牌经营：借助数据分析工具，基于行业数据、品牌经营数据分析，持续指导品牌B端场景资源投入，包括企业专属商品、价格的经营方案迭代，确保品牌经营策略有效性。","requirements":"本科及以上学历，3年及以上大客户销售/运营工作经验；\n逻辑清晰，强烈的责任心和事业心，具备良好的职业素养，正直诚信；\n具备良好的沟通表达能力、较强的数据分析能力及良好的跨部门协作能力；\n适应互联网行业的快速发展，精力充沛，心态积极进取，有较强的目标意识及自驱力；\n具备较好的商家谈判与沟通能力，同时具备商家运营能力；\n具备AI辅助工作工具的使用意愿，能利用AI工具辅助商务方案撰写、拜访准备及数据报告生成。","description":"部门介绍\n美团平台为用户的基础产品体验负责，还承担了美团的用户增长、市场和品牌营销以及多条业务线的产品设计职责，建立了融合文字、图片、视频和直播等不同形式的內容生态系统，同时整合地图服务部、客户服务和体验部、企业业务部、网约车业务部等部门，致力于用科技提升美团数亿消费者、近千万商家、骑手、司机和团长的服务体验。美团平台拥有高并发、多业务的复杂场景，为技术深度优化提供了最佳实践可能。这里有简单、讲逻辑、有爱的团队，更是一块理想的实战场地，舞台广阔，欢迎你来尽情施展。\n\n岗位职责\n品牌签约：负责所属品牌方的商务合作，包含外卖、到餐KA及CKA品牌，协同品牌业务、财税、SaaS等多方角色的方案讲解、商务谈判、合同签署；\n发票回收：负责所属品牌方的周期性发票回收工作；\n品牌经营：借助数据分析工具，基于行业数据、品牌经营数据分析，持续指导品牌B端场景资源投入，包括企业专属商品、价格的经营方案迭代，确保品牌经营策略有效性。\n\n岗位基本要求\n本科及以上学历，3年及以上大客户销售/运营工作经验；\n逻辑清晰，强烈的责任心和事业心，具备良好的职业素养，正直诚信；\n具备良好的沟通表达能力、较强的数据分析能力及良好的跨部门协作能力；\n适应互联网行业的快速发展，精力充沛，心态积极进取，有较强的目标意识及自驱力；\n具备较好的商家谈判与沟通能力，同时具备商家运营能力；\n具备AI辅助工作工具的使用意愿，能利用AI工具辅助商务方案撰写、拜访准备及数据报告生成。\n\n岗位亮点\n【新业务】美团内部专业面向企业市场的To B业务。我们为“企业公务消费管理”提供一站式SaaS服务，涵盖企业用餐、报销费控等多个领域（这些领域已经在服务美团自身）。我们帮助企业实现公务消费线上化，助力企业降本增效，帮助员工告别线下报销；\n【空间大】公务消费有数万亿的大盘，有足够的想象力。该业务会涉及外卖、到店餐饮等业务类型，能给大家提供足够的学习成长空间；\n【有希望】To B的大势刚刚开始，依托于美团过去10年的积累和对自身服务的深厚理解，我们认为很有机会把业务做大做成；\n【氛围好】务实求真，创业氛围。人际简单，组织扁平。这是一个巨大的机会，也需要长期的耐心。To B星辰大海，征程期待有你。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4705906085","sourceKey":"meituan_social","company":"美团","title":"高级投放运营专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4705906085&jobShareType=1","duty":"1.独立操盘投放增长业务，基于用户生命周期、业务目标与竞争格局，制定分层分阶段的投放增长策略，对用户规模、交易与ROI等核心指标负责；\n\n2.主导预算规划与动态调优，构建渠道组合与资源分配机制，以数据驱动持续优化投放模型，在规模与效率之间实现最优平衡；\n\n3.深度洞察用户需求与决策逻辑，联动货品供给、补贴政策、营销热点等要素设计投放打法，沉淀可复用的增长方法论；\n\n4.研判电商、OTA等交易型行业的核心打法与趋势，迁移跨行业最佳实践，驱动策略持续迭代；\n\n5.探索并落地AI在投放增长中的应用，借助AIGC、智能投放、大模型等技术提升素材创意产出、人群洞察与出价效率，构建智能化投放能力；\n\n6.协同商分、产研、供给等团队推动策略落地，并对投放链路能力（RTA、归因、唤端等）提出系统性优化建议。","requirements":"1.本科及以上学历，具备扎实的互联网投放或用户增长经验，有电商、OTA等交易型行业背景者优先；\n\n2.精通信息流、搜索、DSP等主流投放渠道与增长手段，熟悉RTA、归因分析等技术体系；\n\n3.具备AI/智能化投放的应用能力，熟悉AIGC、智能投放工具或大模型在营销增长场景的落地，有相关实践者优先；\n\n4.对数据高度敏感，具备优秀的数据分析与商业判断能力，能够以数据洞察驱动策略决策；\n\n5.具备成熟的策略思维与全局视角，既能独立操盘亦能推动高质量落地，逻辑严谨、学习能力强；\n\n6.具备优秀的跨团队协同与资源整合能力，沟通表达精准高效。","description":"部门介绍\n美团平台为用户的基础产品体验负责，还承担了美团的用户增长、市场和品牌营销以及多条业务线的产品设计职责，建立了融合文字、图片、视频和直播等不同形式的內容生态系统，同时整合地图服务部、客户服务和体验部、企业业务部、网约车业务部等部门，致力于用科技提升美团数亿消费者、近千万商家、骑手、司机和团长的服务体验。美团平台拥有高并发、多业务的复杂场景，为技术深度优化提供了最佳实践可能。这里有简单、讲逻辑、有爱的团队，更是一块理想的实战场地，舞台广阔，欢迎你来尽情施展。\n\n岗位职责\n1.独立操盘投放增长业务，基于用户生命周期、业务目标与竞争格局，制定分层分阶段的投放增长策略，对用户规模、交易与ROI等核心指标负责；\n\n2.主导预算规划与动态调优，构建渠道组合与资源分配机制，以数据驱动持续优化投放模型，在规模与效率之间实现最优平衡；\n\n3.深度洞察用户需求与决策逻辑，联动货品供给、补贴政策、营销热点等要素设计投放打法，沉淀可复用的增长方法论；\n\n4.研判电商、OTA等交易型行业的核心打法与趋势，迁移跨行业最佳实践，驱动策略持续迭代；\n\n5.探索并落地AI在投放增长中的应用，借助AIGC、智能投放、大模型等技术提升素材创意产出、人群洞察与出价效率，构建智能化投放能力；\n\n6.协同商分、产研、供给等团队推动策略落地，并对投放链路能力（RTA、归因、唤端等）提出系统性优化建议。\n\n岗位基本要求\n1.本科及以上学历，具备扎实的互联网投放或用户增长经验，有电商、OTA等交易型行业背景者优先；\n\n2.精通信息流、搜索、DSP等主流投放渠道与增长手段，熟悉RTA、归因分析等技术体系；\n\n3.具备AI/智能化投放的应用能力，熟悉AIGC、智能投放工具或大模型在营销增长场景的落地，有相关实践者优先；\n\n4.对数据高度敏感，具备优秀的数据分析与商业判断能力，能够以数据洞察驱动策略决策；\n\n5.具备成熟的策略思维与全局视角，既能独立操盘亦能推动高质量落地，逻辑严谨、学习能力强；\n\n6.具备优秀的跨团队协同与资源整合能力，沟通表达精准高效。\n\n岗位亮点\n1.核心业务、资源充足：处于强竞争、复杂度的核心业务，资源投入充分，提供稀缺的策略决策实践机会；\n\n2.决策价值高：可深度参与业务增长核心决策，接触前沿的用户增长理念、AI应用与行业最佳实践；\n\n3.团队氛围好：团队开放团结、气氛轻松，人际关系简单纯粹。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4063523731","sourceKey":"meituan_social","company":"美团","title":"食杂零售税务BP","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4063523731&jobShareType=1","duty":"1.深入了解公司业务，积极为业务提供可落地的税务问题解决方案；\n2.识别业务操作中的税务风险，并从税务合规角度提供优化建议；\n3.掌握与业务相关的税务政策变化及趋势，有能力向业务提供前瞻性的税务指引，为业务创造长期可持续的价值；\n4.为承载业务的法人主体提供税金预测、税务筹划和关联交易安排；\n5.研究同业的税务处理方案，可对标匹配优秀方案供业务参考；\n6.配合公司发展战略和税收政策，优化税务结构，提高税收效益；\n7.加强零售业务线税务系统智能化建设；\n8.推动该领域AI 化提效： 梳理税务高频工作场景，建立标准化 AI 辅助工作流与 Prompt 模板，沉淀团队操作规范，持续提升人均处理效率与决策质量。","requirements":"1. 对中国财税政策清晰和深刻的掌握，能为业务提供闭环的税务解决方案；\n2. 有全局观，对零售行业税务工作有熟练实操经验，有产品化思维能力，能通过AI提高工作效率及沉淀经验；\n3. 有四大+互联网公司税务工作经历者优先；\n4. 英语可作为日常沟通语言；\n4. 具有较强的沟通协同能力，业务思维好。\n5. 关注大模型、AI Agent 等前沿技术在税务领域的应用进展，有参与或推动资金场景/AI/数字化工具落地经验者优先。","description":"部门介绍\n财务平台负责公司整体和各业务层面的财务管理工作，通过建设专业、全面、复合的财务管理能力和与业务经营的紧密结合来支持公司健康发展。目前财务平台拥有财务会计、财务报告、资金管理、税务管理、财务共享、财务系统、规划分析、财务BP和内控内审等主要工作方向。我们的目标是建设业界一流的财务管理能力和经营支持体系，为公司战略的正确落地、投入效率的持续提升、业务价值的不断增长保驾护航。欢迎加入财务平台，携手一起向未来！\n\n岗位职责\n1.深入了解公司业务，积极为业务提供可落地的税务问题解决方案；\n2.识别业务操作中的税务风险，并从税务合规角度提供优化建议；\n3.掌握与业务相关的税务政策变化及趋势，有能力向业务提供前瞻性的税务指引，为业务创造长期可持续的价值；\n4.为承载业务的法人主体提供税金预测、税务筹划和关联交易安排；\n5.研究同业的税务处理方案，可对标匹配优秀方案供业务参考；\n6.配合公司发展战略和税收政策，优化税务结构，提高税收效益；\n7.加强零售业务线税务系统智能化建设；\n8.推动该领域AI 化提效： 梳理税务高频工作场景，建立标准化 AI 辅助工作流与 Prompt 模板，沉淀团队操作规范，持续提升人均处理效率与决策质量。\n\n岗位基本要求\n1. 对中国财税政策清晰和深刻的掌握，能为业务提供闭环的税务解决方案；\n2. 有全局观，对零售行业税务工作有熟练实操经验，有产品化思维能力，能通过AI提高工作效率及沉淀经验；\n3. 有四大+互联网公司税务工作经历者优先；\n4. 英语可作为日常沟通语言；\n4. 具有较强的沟通协同能力，业务思维好。\n5. 关注大模型、AI Agent 等前沿技术在税务领域的应用进展，有参与或推动资金场景/AI/数字化工具落地经验者优先。\n\n岗位亮点\n1. 有机会深刻了解美团的业务和运作、深度学习美团方法论；\n2. 有机会深度参与互联网头部企业的战略和业务的税务方案设计；\n3. 美团有丰富的业务线和专业领域，提供给同学们在税务管理各个岗位轮岗锻炼的机会；\n4. 我们的团队专业、开放、乐于分享、拥抱挑战。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:2754956080","sourceKey":"meituan_social","company":"美团","title":"内部审计专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=2754956080&jobShareType=1","duty":"1. 参与业务运营类审计项目，识别风险，基于业务目标、行业现状等提出可落地的改进建议；\n2. 追踪整改进展，并探索建设持续化审计工具开展长期风险监控；\n3. 探索利用AI能力和工具延展审计边界，提高工作效率，发掘深度风险和新兴风险。","requirements":"1. 硕士研究生学历，审计、信息管理或相关专业背景；  \n2. 具备3年以上风险管理相关工作经验，具有零售或IoT行业背景优先；    \n3. 具备优秀的主动性和韧性、良好的沟通能力和团队协作精神。","description":"部门介绍\n财务平台负责公司整体和各业务层面的财务管理工作，通过建设专业、全面、复合的财务管理能力和与业务经营的紧密结合来支持公司健康发展。目前财务平台拥有财务会计、财务报告、资金管理、税务管理、财务共享、财务系统、规划分析、财务BP和内控内审等主要工作方向。我们的目标是建设业界一流的财务管理能力和经营支持体系，为公司战略的正确落地、投入效率的持续提升、业务价值的不断增长保驾护航。欢迎加入财务平台，携手一起向未来！\n\n岗位职责\n1. 参与业务运营类审计项目，识别风险，基于业务目标、行业现状等提出可落地的改进建议；\n2. 追踪整改进展，并探索建设持续化审计工具开展长期风险监控；\n3. 探索利用AI能力和工具延展审计边界，提高工作效率，发掘深度风险和新兴风险。\n\n岗位基本要求\n1. 硕士研究生学历，审计、信息管理或相关专业背景；  \n2. 具备3年以上风险管理相关工作经验，具有零售或IoT行业背景优先；    \n3. 具备优秀的主动性和韧性、良好的沟通能力和团队协作精神。\n\n岗位亮点\n1. 深入零售、IoT、平台服务等多业态，兼具业务深度和广度，单点问题解法可形成横向高杠杆成果；  \n2. 风险管理视角和业务运营视角兼备，可参与到管理动作决策过程；\n3. 参与AI时代内审行业变革探索；\n4. 团队实事求是，严肃活泼，各有专长，是很好的成长平台。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3750031159","sourceKey":"meituan_social","company":"美团","title":"LongCat - Search Agent 算法研究员","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3750031159&jobShareType=1","duty":"1. 深度参与LongCat基模Agent能力优化，包括但不限于以DeepSearch、DeepResearch等为代表的Search Agent能力，以及以生活服务等为代表的真实世界复杂任务上的Agentic能力\n2. 跟进大模型的前沿技术，包括但不限于：Mid-Train、SFT、GRM、PRM、RLVR、Agentic RL、Agent自进化、Context管理/Memory等，在LongCat模型上做出创新性的研究成果\n3. 结合大模型全模态能力，探索下一代大模型+Agent+搜索的新的技术和产品范式","requirements":"1. 硕士研究生及以上学历，计算机科学、人工智能、自然语言处理等相关领域优先；\n2. 优秀的编程能力，熟悉PyTorch、TensorFlow等深度学习框架，同时具备极强的AI Coding意识和能力；\n3. 熟悉深度学习和LLM相关的算法和技术，具备丰富的模型训练调优经验；\n4. 出色的分析和解决问题能力，具备极强的自驱力，能够独立地开展前沿研究工作\n5. 有ACL/NeurIPS等顶会论文者优先，有ACM/ICPC、NOI/IOI、Top Coder、Kaggle等比赛获奖者优先","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n1. 深度参与LongCat基模Agent能力优化，包括但不限于以DeepSearch、DeepResearch等为代表的Search Agent能力，以及以生活服务等为代表的真实世界复杂任务上的Agentic能力\n2. 跟进大模型的前沿技术，包括但不限于：Mid-Train、SFT、GRM、PRM、RLVR、Agentic RL、Agent自进化、Context管理/Memory等，在LongCat模型上做出创新性的研究成果\n3. 结合大模型全模态能力，探索下一代大模型+Agent+搜索的新的技术和产品范式\n\n岗位基本要求\n1. 硕士研究生及以上学历，计算机科学、人工智能、自然语言处理等相关领域优先；\n2. 优秀的编程能力，熟悉PyTorch、TensorFlow等深度学习框架，同时具备极强的AI Coding意识和能力；\n3. 熟悉深度学习和LLM相关的算法和技术，具备丰富的模型训练调优经验；\n4. 出色的分析和解决问题能力，具备极强的自驱力，能够独立地开展前沿研究工作\n5. 有ACL/NeurIPS等顶会论文者优先，有ACM/ICPC、NOI/IOI、Top Coder、Kaggle等比赛获奖者优先\n\n岗位亮点\n1、丰富的研发经验，参与公司核心产品的研发和优化。\n2、充足的GPU资源用于实验探索。\n3、提供优厚的薪资福利和良好的晋升空间。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4720843309","sourceKey":"meituan_social","company":"美团","title":"点评技术-推荐算法工程师","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4720843309&jobShareType=1","duty":"1. 负责推荐系统全链路的优化与设计，包括召回、粗排、精排等模块的迭代与创新。  \n2. 基于用户行为数据构建和迭代推荐模型，探索scaling up、多模态推荐等前沿方向。  \n3. 探索并落地生成式推荐技术，推动大模型在推荐场景中的应用与创新。  \n4. 与产品、工程团队协作，推动算法策略在业务场景中的落地应用。","requirements":"1. 硕士研究生学历，计算机、数学、统计学等相关专业。  \n2. 1年以上推荐算法或相关领域工作经验，具备扎实的机器学习理论基础。  \n3. 熟练掌握Python、C++等编程语言，熟悉TensorFlow、PyTorch等深度学习框架。  \n4. 具备良好的数据分析和问题解决能力，有大规模推荐系统实践经验者优先。","description":"部门介绍\n美团核心本地商业下业务研发平台，基于公司“零售+科技”的战略导向，通过从底层架构到应用系统、从软件到硬件、从传统算法到GenAI的全方位技术研究，以及开发、运维、安全等全流程能力建设，致力于推动美团核心本地商业下需求侧与供给侧的数字化和智能化升级，助力业务实现高质量增长，优化用户使用体验，提升商户经营水平，促进行业生态伙伴关系的持续健康发展。团队秉持务实、自驱、开放以及追求卓越的工程师文化，一方面通过系统和技术体系的持续迭代升级，帮助业务高质量增长；另一方面，密切关注前沿技术趋势变化，积极创新技术能力，为业务未来发展创造新的可能性。期待优秀的你加入我们，在夯实专业、深耕平台的基础上与业务携手同行，一起用技术 “帮大家吃得更好，生活更好”。\n\n岗位职责\n1. 负责推荐系统全链路的优化与设计，包括召回、粗排、精排等模块的迭代与创新。  \n2. 基于用户行为数据构建和迭代推荐模型，探索scaling up、多模态推荐等前沿方向。  \n3. 探索并落地生成式推荐技术，推动大模型在推荐场景中的应用与创新。  \n4. 与产品、工程团队协作，推动算法策略在业务场景中的落地应用。\n\n岗位基本要求\n1. 硕士研究生学历，计算机、数学、统计学等相关专业。  \n2. 1年以上推荐算法或相关领域工作经验，具备扎实的机器学习理论基础。  \n3. 熟练掌握Python、C++等编程语言，熟悉TensorFlow、PyTorch等深度学习框架。  \n4. 具备良好的数据分析和问题解决能力，有大规模推荐系统实践经验者优先。\n\n具备以下条件优先\n具有之前做搜广推相关经历。\n\n岗位亮点\n1. 参与亿级用户产品的推荐系统建设，业务影响力大。  \n2. 技术氛围浓厚，可与资深算法专家共同成长。  \n3. 工作地点覆盖北京、上海，提供灵活办公选择。  \n4. 完善的职业发展路径和具有竞争力的薪酬福利。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4705321633","sourceKey":"meituan_social","company":"美团","title":"小象超市-线下店前场运营-成都","city":"成都市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4705321633&jobShareType=1","duty":"1.经营目标管理：负责对大区门店前场各模块的销售、毛利及利润指标进行拆解、追踪与达成管理，确保整体经营目标实现。\n2.运营标准建设：建立并迭代所辖品类的运营SOP、服务标准与质量管控体系，并通过巡检、督导与考核机制确保在终端门店的落地执行。\n3.卖场效能优化：主导前场的品类结构、空间布局与商品陈列方案的规划与优化，基于销售数据与顾客动线分析，持续提升卖场空间效率与产出。\n4.营销活动落地：负责区域级营销活动在前场部门的策划、执行与效果追踪，完成活动复盘，以驱动客流与销售转化。\n5.顾客体验管理：监控并分析前台服务模块的运营数据与客诉反馈，定位服务短板，推动改善流程，对顾客满意度负责。\n6.数据复盘赋能：具备优秀的数据处理与报告撰写能力，定期输出前场经营分析报告，精准诊断问题并提出行动策略，为管理层决策与门店运营提供专业支持。","requirements":"1.本科及以上学历。\n2.拥有3年以上零售行业运营管理经验，具备线下多品类管理背景者优先。\n3.在品类规划、卖场布局、商品陈列等方面拥有扎实的实践经验。\n4.具备良好的数据处理能力，能熟练使用报表类处理工具进行业务分析。\n5.拥有优秀的报告撰写与陈述能力，能清晰呈现经营状况与策略计划。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1.经营目标管理：负责对大区门店前场各模块的销售、毛利及利润指标进行拆解、追踪与达成管理，确保整体经营目标实现。\n2.运营标准建设：建立并迭代所辖品类的运营SOP、服务标准与质量管控体系，并通过巡检、督导与考核机制确保在终端门店的落地执行。\n3.卖场效能优化：主导前场的品类结构、空间布局与商品陈列方案的规划与优化，基于销售数据与顾客动线分析，持续提升卖场空间效率与产出。\n4.营销活动落地：负责区域级营销活动在前场部门的策划、执行与效果追踪，完成活动复盘，以驱动客流与销售转化。\n5.顾客体验管理：监控并分析前台服务模块的运营数据与客诉反馈，定位服务短板，推动改善流程，对顾客满意度负责。\n6.数据复盘赋能：具备优秀的数据处理与报告撰写能力，定期输出前场经营分析报告，精准诊断问题并提出行动策略，为管理层决策与门店运营提供专业支持。\n\n岗位基本要求\n1.本科及以上学历。\n2.拥有3年以上零售行业运营管理经验，具备线下多品类管理背景者优先。\n3.在品类规划、卖场布局、商品陈列等方面拥有扎实的实践经验。\n4.具备良好的数据处理能力，能熟练使用报表类处理工具进行业务分析。\n5.拥有优秀的报告撰写与陈述能力，能清晰呈现经营状况与策略计划。\n\n岗位亮点\n“前场经营质量”关键角色，岗位价值高，晋升空间大。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4705833566","sourceKey":"meituan_social","company":"美团","title":"小象超市-线下店培训运营-成都","city":"成都市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4705833566&jobShareType=1","duty":"1.培训体系规划：基于大区业务战略与人才梯队现状，进行培训需求分析，负责构建并持续迭代区域分层、分条线的全流程培训体系与年度规划。\n2.学习内容开发：主导关键课程（如服务标准、运营流程、销售技巧、管理能力等）的课件设计与内容制作，开发标准化教材、案例库及数字化学习材料。\n3.培训项目落地：负责组织并实施各类培训项目，包括新员工入职集训、在岗技能提升、储备干部培养及管理层发展项目，确保培训高效落地。\n4.讲师团队管理与赋能：负责区域内部讲师团队的选拔、培养、认证与激励，通过定期教研与技能培训，提升讲师团队的专业交付能力。\n5.培训效果检验：建立科学的培训效果评估体系，通过考核、调研、行为观察及业务数据比对等方式，检验培训转化效果，并持续优化培训策略。\n6.学习运营与数字化：负责学习平台与资源的日常运营管理，探索并应用多样化的学习技术与形式，提升培训的覆盖度、便捷性与员工学习体验。\n7.掌握基本的AI工具，使用工具提升工作流程效率。","requirements":"1.人力资源管理、教育学、心理学等相关专业优先。\n2.拥有3年以上培训相关工作经验，具备零售行业培训背景者佳。\n3.具备独立完成培训需求分析、项目规划、课件开发与授课交付的全流程实操经验。\n4.具备良好的数据处理能力，能使用常用函数和相关数据工具分析培训效果与人才数据。\n5.拥有优秀的报告撰写与呈现能力，能清晰展示培训项目价值与人才发展成果。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1.培训体系规划：基于大区业务战略与人才梯队现状，进行培训需求分析，负责构建并持续迭代区域分层、分条线的全流程培训体系与年度规划。\n2.学习内容开发：主导关键课程（如服务标准、运营流程、销售技巧、管理能力等）的课件设计与内容制作，开发标准化教材、案例库及数字化学习材料。\n3.培训项目落地：负责组织并实施各类培训项目，包括新员工入职集训、在岗技能提升、储备干部培养及管理层发展项目，确保培训高效落地。\n4.讲师团队管理与赋能：负责区域内部讲师团队的选拔、培养、认证与激励，通过定期教研与技能培训，提升讲师团队的专业交付能力。\n5.培训效果检验：建立科学的培训效果评估体系，通过考核、调研、行为观察及业务数据比对等方式，检验培训转化效果，并持续优化培训策略。\n6.学习运营与数字化：负责学习平台与资源的日常运营管理，探索并应用多样化的学习技术与形式，提升培训的覆盖度、便捷性与员工学习体验。\n7.掌握基本的AI工具，使用工具提升工作流程效率。\n\n岗位基本要求\n1.人力资源管理、教育学、心理学等相关专业优先。\n2.拥有3年以上培训相关工作经验，具备零售行业培训背景者佳。\n3.具备独立完成培训需求分析、项目规划、课件开发与授课交付的全流程实操经验。\n4.具备良好的数据处理能力，能使用常用函数和相关数据工具分析培训效果与人才数据。\n5.拥有优秀的报告撰写与呈现能力，能清晰展示培训项目价值与人才发展成果。\n\n岗位亮点\n区域人才发展的“总教练”与“赋能引擎”，岗位价值高，未来发展空间大。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4705838762","sourceKey":"meituan_social","company":"美团","title":"小象超市-线下店后场运营-成都","city":"成都市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4705838762&jobShareType=1","duty":"1.仓储体系管理：负责建立与优化大区各门店后场的仓储运营标准、作业流程与管理制度，确保库存准确、作业规范与库内安全。\n2.物流配送优化：统筹管理区域内的物流配送网络，监控配送时效与成本，持续优化调拨、补货等物流路由，提升商品到店效率。\n3.库存精准控制：通过有效的库存数据分析，设定并监控各类别商品的安全库存与周转天数，推动库存结构的持续优化，降低滞销与缺货风险。\n4.成本效率管控：负责后场运营相关成本（如仓储、人力、物流等）的预算编制与过程控制，通过流程改进与技术应用，提升人效与坪效，实现降本增效。\n5.团队与安全督导：建立后场员工作业技能培训与绩效考核体系，并全面落实仓储物流环节的安全生产管理，杜绝重大运营与安全事故。\n6.数据复盘赋能：具备优秀的数据处理与报告撰写能力，定期输出后场运营分析报告，精准诊断库存、效率、成本等问题，并推动改善策略落地。","requirements":"1.本科及以上学历，物流管理、供应链管理等相关专业优先。\n2.拥有3年以上零售行业仓储管理、物流管理相关工作经验，熟悉现代化仓储物流运作模式。\n3.在WMS系统应用、库存控制、物流规划及成本管控方面拥有扎实的实践经验。\n4.具备良好的数据处理能力，能熟练使用报表等工具进行运营分析。\n5.拥有优秀的报告撰写与陈述能力，能清晰呈现运营状况与管理策略。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1.仓储体系管理：负责建立与优化大区各门店后场的仓储运营标准、作业流程与管理制度，确保库存准确、作业规范与库内安全。\n2.物流配送优化：统筹管理区域内的物流配送网络，监控配送时效与成本，持续优化调拨、补货等物流路由，提升商品到店效率。\n3.库存精准控制：通过有效的库存数据分析，设定并监控各类别商品的安全库存与周转天数，推动库存结构的持续优化，降低滞销与缺货风险。\n4.成本效率管控：负责后场运营相关成本（如仓储、人力、物流等）的预算编制与过程控制，通过流程改进与技术应用，提升人效与坪效，实现降本增效。\n5.团队与安全督导：建立后场员工作业技能培训与绩效考核体系，并全面落实仓储物流环节的安全生产管理，杜绝重大运营与安全事故。\n6.数据复盘赋能：具备优秀的数据处理与报告撰写能力，定期输出后场运营分析报告，精准诊断库存、效率、成本等问题，并推动改善策略落地。\n\n岗位基本要求\n1.本科及以上学历，物流管理、供应链管理等相关专业优先。\n2.拥有3年以上零售行业仓储管理、物流管理相关工作经验，熟悉现代化仓储物流运作模式。\n3.在WMS系统应用、库存控制、物流规划及成本管控方面拥有扎实的实践经验。\n4.具备良好的数据处理能力，能熟练使用报表等工具进行运营分析。\n5.拥有优秀的报告撰写与陈述能力，能清晰呈现运营状况与管理策略。\n\n岗位亮点\n区域后场供应链的“运营专家”和“效率中心”，岗位价值高，未来晋升空间大。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4704954573","sourceKey":"meituan_social","company":"美团","title":"小象超市-线下店综合运营（EHS）-成都","city":"成都市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4704954573&jobShareType=1","duty":"1.EHS体系管理：负责建立、推行与维护大区的环境、健康与安全（EHS）管理体系，制定并落实安全运营标准与应急预案，确保区域合规零风险。\n2.联营商运营管理：负责联营商家的引入评估、合同履约管理与日常运营协调，建立联营商效能评估体系，提升合作方的经营质量与顾客服务水平。\n3.质量稽核与控管：主导建立门店运营质量稽核标准与流程，定期组织对门店环境、服务、商品质量及操作规范进行审计，并追踪整改结果，形成管理闭环。\n4.风险前置管控：建立常态化的风险排查机制，能够对EHS、联营商运营及商品质量中的潜在风险进行精准识别与前置预警，并推动预防性措施落地。\n5.标准建设与赋能：针对EHS、联营、质控三大模块，输出标准化的作业流程与管理工具，并通过培训、宣导与现场指导，赋能门店团队执行到位。\n6.数据复盘与报告：具备优秀的数据处理与报告撰写能力，定期输出综合运营分析报告，清晰呈现各模块运营状态、核心问题及改进策略，为管理决策提供支持。","requirements":"1.安全工程、质量管理、工商管理等相关专业优先。\n2.拥有3年以上零售或相关服务业综合运营管理经验，必须具备EHS管理、质量稽核、联营运营管理其中至少两项的实战经验。\n3.熟悉业内EHS相关规范，具备质量体系搭建或稽核经验，精通联营商管理全流程。\n4.具备良好的数据处理能力，能熟练使用报表工具进行多维度运营分析。\n5.拥有优秀的报告撰写与陈述能力，能输出逻辑严谨、建议专业的综合分析报告。\n6.掌握基本的AI工具，使用工具提升工作流程效率。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1.EHS体系管理：负责建立、推行与维护大区的环境、健康与安全（EHS）管理体系，制定并落实安全运营标准与应急预案，确保区域合规零风险。\n2.联营商运营管理：负责联营商家的引入评估、合同履约管理与日常运营协调，建立联营商效能评估体系，提升合作方的经营质量与顾客服务水平。\n3.质量稽核与控管：主导建立门店运营质量稽核标准与流程，定期组织对门店环境、服务、商品质量及操作规范进行审计，并追踪整改结果，形成管理闭环。\n4.风险前置管控：建立常态化的风险排查机制，能够对EHS、联营商运营及商品质量中的潜在风险进行精准识别与前置预警，并推动预防性措施落地。\n5.标准建设与赋能：针对EHS、联营、质控三大模块，输出标准化的作业流程与管理工具，并通过培训、宣导与现场指导，赋能门店团队执行到位。\n6.数据复盘与报告：具备优秀的数据处理与报告撰写能力，定期输出综合运营分析报告，清晰呈现各模块运营状态、核心问题及改进策略，为管理决策提供支持。\n\n岗位基本要求\n1.安全工程、质量管理、工商管理等相关专业优先。\n2.拥有3年以上零售或相关服务业综合运营管理经验，必须具备EHS管理、质量稽核、联营运营管理其中至少两项的实战经验。\n3.熟悉业内EHS相关规范，具备质量体系搭建或稽核经验，精通联营商管理全流程。\n4.具备良好的数据处理能力，能熟练使用报表工具进行多维度运营分析。\n5.拥有优秀的报告撰写与陈述能力，能输出逻辑严谨、建议专业的综合分析报告。\n6.掌握基本的AI工具，使用工具提升工作流程效率。\n\n岗位亮点\n区域运营“安全、质量与合作伙伴管理”的基石，岗位价值高，晋升空间大。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4411483145","sourceKey":"meituan_social","company":"美团","title":"小象综合分析财务BP","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4411483145&jobShareType=1","duty":"1. 深入理解业务模式，结合财务数据与业务指标，提供多维度的财务分析与决策支持。  \n2. 负责预算编制、执行监控、滚动预测及差异分析，推动业务目标达成。  \n3. 搭建并优化财务分析模型和长期预测模型，提升数据洞察效率与准确性。 探索 AI 工具在预测模型中的应用，提升预测准确率和响应速度。\n4. 定期输出经营分析报告，向管理层提供可落地的财务建议。能够借助 AI 辅助生成分析框架与报告初稿，提升产出效率。","requirements":"1. 5年以上财务分析或财务BP相关工作经验，具备互联网或高增长行业背景优先。  \n2. 具备较强的逻辑思维、数据敏感度和业务理解能力。  \n3. 具备良好的沟通协调能力，能独立推动跨部门协作。\n4. 熟悉SQL、Power BI、AI工具等数据分析工具者优先。\n5. 具备 AI 工具学习意愿，能主动探索 AI 在财务场景中的落地应用。","description":"部门介绍\n财务平台负责公司整体和各业务层面的财务管理工作，通过建设专业、全面、复合的财务管理能力和与业务经营的紧密结合来支持公司健康发展。目前财务平台拥有财务会计、财务报告、资金管理、税务管理、财务共享、财务系统、规划分析、财务BP和内控内审等主要工作方向。我们的目标是建设业界一流的财务管理能力和经营支持体系，为公司战略的正确落地、投入效率的持续提升、业务价值的不断增长保驾护航。欢迎加入财务平台，携手一起向未来！\n\n岗位职责\n1. 深入理解业务模式，结合财务数据与业务指标，提供多维度的财务分析与决策支持。  \n2. 负责预算编制、执行监控、滚动预测及差异分析，推动业务目标达成。  \n3. 搭建并优化财务分析模型和长期预测模型，提升数据洞察效率与准确性。 探索 AI 工具在预测模型中的应用，提升预测准确率和响应速度。\n4. 定期输出经营分析报告，向管理层提供可落地的财务建议。能够借助 AI 辅助生成分析框架与报告初稿，提升产出效率。\n\n岗位基本要求\n1. 5年以上财务分析或财务BP相关工作经验，具备互联网或高增长行业背景优先。  \n2. 具备较强的逻辑思维、数据敏感度和业务理解能力。  \n3. 具备良好的沟通协调能力，能独立推动跨部门协作。\n4. 熟悉SQL、Power BI、AI工具等数据分析工具者优先。\n5. 具备 AI 工具学习意愿，能主动探索 AI 在财务场景中的落地应用。\n\n岗位亮点\n1. 深入参与核心业务决策，发挥财务价值引领作用。  \n2. 与高速发展的业务团队共同成长，发展空间广阔。  \n3. 扁平化管理，开放沟通氛围，鼓励创新与主动担当。  \n4. 身处 AI 应用探索前沿，有机会参与财务智能化转型实践。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4685609051","sourceKey":"meituan_social","company":"美团","title":"美团骑行-城市经理（重庆）","city":"重庆市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4685609051&jobShareType=1","duty":"1. 负责美团骑行在重庆地区的日常运营支持与车辆运维管理工作，确保车辆调度、维修、投放等环节高效运转。  \n2. 带领5人团队，制定并执行城市运营策略，提升车辆使用率与用户满意度。  \n3. 协同城市政府、物业等外部单位，推动合规运营与资源协调，保障业务稳定开展。  \n4. 监控运营数据，分析问题并提出优化方案，持续改善城市骑行体验与运营效率。  \n5. 建立并完善团队培训与考核机制，提升团队专业能力与执行力。","requirements":"1. 大学本科及以上学历，具备5年以上运营或运维相关工作经验。  \n2. 有团队管理经验，具备较强的组织协调能力与问题解决能力。  \n3. 熟悉城市交通或共享出行行业，具备较强的数据分析与策略制定能力。  \n4. 具备良好的沟通能力和跨部门协作经验，能应对复杂外部环境。  \n5. 工作责任心强，能适应高强度工作节奏。","description":"部门介绍\n美团骑行事业部在全国各个城市开展美团单车、电单车业务，提供绿色、便捷的共享出行服务，是美团出行板块重要的组成部分。我们力求为城市可持续发展提供低碳智能的解决方案，通过技术创新和硬件升级，不断优化全流程骑行体验，为低碳出行提供更好的服务。其中，美团单车旨在为城市居民提供通勤接驳服务，满足用户短途接驳出行需求；美团电单车则满足用户中短途多场景低碳出行需求。\n我们有开放的工作氛围，也有充满韧劲和创造力，心系低碳出行的伙伴。加入我们，一起为用户创造更好的出行体验。\n\n岗位职责\n1. 负责美团骑行在重庆地区的日常运营支持与车辆运维管理工作，确保车辆调度、维修、投放等环节高效运转。  \n2. 带领5人团队，制定并执行城市运营策略，提升车辆使用率与用户满意度。  \n3. 协同城市政府、物业等外部单位，推动合规运营与资源协调，保障业务稳定开展。  \n4. 监控运营数据，分析问题并提出优化方案，持续改善城市骑行体验与运营效率。  \n5. 建立并完善团队培训与考核机制，提升团队专业能力与执行力。\n\n岗位基本要求\n1. 大学本科及以上学历，具备5年以上运营或运维相关工作经验。  \n2. 有团队管理经验，具备较强的组织协调能力与问题解决能力。  \n3. 熟悉城市交通或共享出行行业，具备较强的数据分析与策略制定能力。  \n4. 具备良好的沟通能力和跨部门协作经验，能应对复杂外部环境。  \n5. 工作责任心强，能适应高强度工作节奏。\n\n岗位亮点\n1. 加入美团核心出行业务，参与城市绿色出行生态建设。  \n2. 拥有明确的职业发展路径与丰富的跨部门协作机会。  \n3. 团队氛围积极，注重员工成长与能力提升。  \n4. 工作地点位于重庆核心区域，交通便利，办公环境优良。  \n5. 提供具有竞争力的薪酬福利与完善的培训体系。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4612329304","sourceKey":"meituan_social","company":"美团","title":"Darkstore Workforce Management","city":"利雅得/科威特城/多哈","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4612329304&jobShareType=1","duty":"1.Based on the headcount targets required by business needs, break down the recruitment pace and cycle to ensure sufficient personnel.\n2. With the goal of achieving the scale of suppliers and delivery capabilities, promote the improvement of the quantity and quality of procurement and introduction of merchants, and establish a supporting merchant management mechanism and system capabilities. \n3. Assist in developing and optimizing staffing strategies to support manpower allocation and temporary staffing arrangements during peak business periods.\n4. Establish and improve local employment management systems and processes, and promote the standardization of the employment system through internal and external benchmarking and efficiency optimization.   \n5. Work closely with the city operations team to promote the implementation of standardized processes and ensure compliance with employment regulations.","requirements":"1. Bachelor's degree or above, with preference given to candidates majoring in Human Resource Management, Operations Management, or a related field.\n2. Minimum 3 years of experience in operations or HR-related work, with preference given to candidates with backgrounds in warehousing, retail, or logistics.\n3. Proficient in data analysis tools and possess basic data insight capabilities.\n4. Excellent communication and coordination skills, able to adapt to a fast-paced work environment across multiple cities.","description":"部门介绍\n美团的使命是“帮大家吃得更好，生活更好”，公司聚焦“零售 + 科技”战略，和广大商户与各类合作伙伴一起，努力为消费者提供品质生活，推动商品零售和服务零售在需求侧和供给侧的数字化转型。\n2018年9月20日，美团正式在港交所挂牌上市。美团将始终坚持以客户为中心，不断加大在科技研发方面的投入，更好承担社会责任，更多创造社会价值，与广大合作伙伴一起发展共赢。\n\n岗位职责\n1.Based on the headcount targets required by business needs, break down the recruitment pace and cycle to ensure sufficient personnel.\n2. With the goal of achieving the scale of suppliers and delivery capabilities, promote the improvement of the quantity and quality of procurement and introduction of merchants, and establish a supporting merchant management mechanism and system capabilities. \n3. Assist in developing and optimizing staffing strategies to support manpower allocation and temporary staffing arrangements during peak business periods.\n4. Establish and improve local employment management systems and processes, and promote the standardization of the employment system through internal and external benchmarking and efficiency optimization.   \n5. Work closely with the city operations team to promote the implementation of standardized processes and ensure compliance with employment regulations.\n\n岗位基本要求\n1. Bachelor's degree or above, with preference given to candidates majoring in Human Resource Management, Operations Management, or a related field.\n2. Minimum 3 years of experience in operations or HR-related work, with preference given to candidates with backgrounds in warehousing, retail, or logistics.\n3. Proficient in data analysis tools and possess basic data insight capabilities.\n4. Excellent communication and coordination skills, able to adapt to a fast-paced work environment across multiple cities.\n\n具备以下条件优先\nTalabat、Sultan、snoonu mart 、Ninja  work experience\n\n岗位亮点\n1. Join a rapidly growing regional business team and participate in building the core operational system.\n2. Work locations cover Riyadh, Kuwait City, and Doha, providing cross-regional development opportunities.\n3. Assume key management responsibilities, with ample room for growth and a clear promotion path.\n4. Collaborate with a multicultural team to enhance international perspectives and comprehensive management capabilities.","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4611846725","sourceKey":"meituan_social","company":"美团","title":"闪购-歪马-前置仓区域主管（青岛、济南、天津、石家庄）","city":"天津市/石家庄市/济南市/青岛市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4611846725&jobShareType=1","duty":"1.管辖13-17个酒水前置仓的业务开拓和日常管理；\n2.团队搭建，完成前置仓团队搭建，人员选用育励汰；\n3.具备一定的销售管理能力，有进行目标拆解和过程管理能力，承担区域增长目标，完成地推获客，留存等增长指标；\n4.对前置仓的商品进行管理，并不断提高前置仓操作规范性和门店的规范性；\n5.保障前置仓的日常营运，确保配送时效，前置仓内商品准确，保障用户体验；\n6.有较好的数据意识，能过通过数据发现前置仓运行中的问题；\n7.有较好的成本意识，能合理的管控仓内日常消耗品，地推赠品等耗材的管理。","requirements":"1.有1-3年的前置仓履约或直销管理经验，熟悉零售业务，对前置仓管理，商品管理等有一定经验；\n2.熟悉即时配业务特性，关注用户体验；\n3.有较好的团队管理，人员培养的经验和方法沉淀；\n4.有价值观正，能够横向协同多部门，达成公司业务指标；\n5.有较好的数据敏感度，能够透过数据发现问题。","description":"部门介绍\n美团闪购是美团旗下的即时零售平台，依托即时配送能力，连接本地零售供给，满足消费者30分钟万物到家的即时需求。美团闪购涵盖超市便利、食材、水果、鲜花绿植、休闲零食、酒水饮料、数码家电、美妆个护、母婴玩具、日用百货、服饰鞋帽、宠物等诸多品类，业务覆盖全国近3,000个县市区旗，每日百万级在岗骑手，以高效的配送、丰富的品类和广泛的覆盖，为美团数亿用户带来便捷的生活体验，积极助力实体零售线上化转型，提升本地商业活力。\n\n岗位职责\n1.管辖13-17个酒水前置仓的业务开拓和日常管理；\n2.团队搭建，完成前置仓团队搭建，人员选用育励汰；\n3.具备一定的销售管理能力，有进行目标拆解和过程管理能力，承担区域增长目标，完成地推获客，留存等增长指标；\n4.对前置仓的商品进行管理，并不断提高前置仓操作规范性和门店的规范性；\n5.保障前置仓的日常营运，确保配送时效，前置仓内商品准确，保障用户体验；\n6.有较好的数据意识，能过通过数据发现前置仓运行中的问题；\n7.有较好的成本意识，能合理的管控仓内日常消耗品，地推赠品等耗材的管理。\n\n岗位基本要求\n1.有1-3年的前置仓履约或直销管理经验，熟悉零售业务，对前置仓管理，商品管理等有一定经验；\n2.熟悉即时配业务特性，关注用户体验；\n3.有较好的团队管理，人员培养的经验和方法沉淀；\n4.有价值观正，能够横向协同多部门，达成公司业务指标；\n5.有较好的数据敏感度，能够透过数据发现问题。\n\n具备以下条件优先\n长期有耐心，认可美团文化！熟悉零售业务，有前置仓管理，商品管理经验，直销外卖/团购/SaaS销售团队管理经验者优先！\n\n岗位亮点\n1.【歪马业务】是【本地核心商业/闪购事业部】下新成立的，由前线业务+运营/采购+产品全闭环的组织;\n2.歪马业务聚焦于酒类万亿市场，通过中心仓+前置仓、平台自营模式，为用户提供15分钟送达的买酒业务;\n3.业务当前正处于快速发展期，26年将覆盖全国，目前歪马送酒已是即时零售行业中的头部品牌！\n4.全方位深入业务，在全闭环的组织里感受不同职能彼此的输入/输出，同时可以参与业务模式的定义；\n5.足够宽的Scope，深入参与自营零售业务的经营。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4580016645","sourceKey":"meituan_social","company":"美团","title":"Maintenance Manager","city":"利雅得/吉达/艾卜哈/麦地那/吉赞","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4580016645&jobShareType=1","duty":"1. Engineering Equipment Maintenance Management: Responsible for overseeing regional engineering equipment maintenance operations, monitoring and enhancing the quality and efficiency of maintenance work within the area to ensure timely delivery, quality standards and cost control are met;\n2. Maintenance Process Standards: Establish and refine maintenance procedures and operational standards for engineering equipment, encompassing daily operations, repairs, servicing, inspection management and other aspects to safeguard business continuity;\n3. Maintenance Supplier Management: Establish supplier maintenance management mechanisms, encompassing supplier tendering, assessment, incentives, allocation, and replacement;\n4. Incident Response: Manage engineering equipment work orders during store operations, track progress, quality and cost. Demonstrate proficiency in specialist disciplines (plumbing, electrical, refrigeration, etc.), develop contingency plans, and lead relevant personnel to swiftly resolve unexpected equipment failures;\n5. Energy Consumption Management: Oversee energy usage of engineering equipment across stores within the region, implement energy-saving measures, and achieve store-level energy reduction targets.","requirements":"1.大学专科及以上学历，机电工程专业优先，具备电工证件；\n2. 5年以上零售、冷链、制冷设备或相关行业工程设备维护工作经历，具备维保人员管理经验；\n3. 具备良好的沟通和协调能力，能够与不同部门和候选人进行有效沟通和协调；\n4.工作积极主动、严谨，执行力强，具有强烈目标达成意识；\n5 .学习能力和协作能力强，思维缜密，接受新事物能力强，能在短时间内迅速了解行业特点.","description":"部门介绍\n美团的使命是“帮大家吃得更好，生活更好”，公司聚焦“零售 + 科技”战略，和广大商户与各类合作伙伴一起，努力为消费者提供品质生活，推动商品零售和服务零售在需求侧和供给侧的数字化转型。\n2018年9月20日，美团正式在港交所挂牌上市。美团将始终坚持以客户为中心，不断加大在科技研发方面的投入，更好承担社会责任，更多创造社会价值，与广大合作伙伴一起发展共赢。\n\n岗位职责\n1. Engineering Equipment Maintenance Management: Responsible for overseeing regional engineering equipment maintenance operations, monitoring and enhancing the quality and efficiency of maintenance work within the area to ensure timely delivery, quality standards and cost control are met;\n2. Maintenance Process Standards: Establish and refine maintenance procedures and operational standards for engineering equipment, encompassing daily operations, repairs, servicing, inspection management and other aspects to safeguard business continuity;\n3. Maintenance Supplier Management: Establish supplier maintenance management mechanisms, encompassing supplier tendering, assessment, incentives, allocation, and replacement;\n4. Incident Response: Manage engineering equipment work orders during store operations, track progress, quality and cost. Demonstrate proficiency in specialist disciplines (plumbing, electrical, refrigeration, etc.), develop contingency plans, and lead relevant personnel to swiftly resolve unexpected equipment failures;\n5. Energy Consumption Management: Oversee energy usage of engineering equipment across stores within the region, implement energy-saving measures, and achieve store-level energy reduction targets.\n\n岗位基本要求\n1.大学专科及以上学历，机电工程专业优先，具备电工证件；\n2. 5年以上零售、冷链、制冷设备或相关行业工程设备维护工作经历，具备维保人员管理经验；\n3. 具备良好的沟通和协调能力，能够与不同部门和候选人进行有效沟通和协调；\n4.工作积极主动、严谨，执行力强，具有强烈目标达成意识；\n5 .学习能力和协作能力强，思维缜密，接受新事物能力强，能在短时间内迅速了解行业特点.\n\n具备以下条件优先\n小象、朴朴维保经验\n\n岗位亮点\n有沙特及中东国家工作经验者优先；\n\n熟练掌握英语、阿拉伯语、汉语者优先。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4100394858","sourceKey":"meituan_social","company":"美团","title":"CKA业务中心-成都-产品销售","city":"成都市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4100394858&jobShareType=1","duty":"岗位职责:\n1.深刻、全面的理解客户需求，协同相关部门制定服务方案，帮助客户更好进行服务规划、完成服务目标、提升服务满意度，从而提升美团公司品牌影响力；\n2.深入理解客户流程、决策的决策链和关键人；\n3.理解行业规律及市场空间，总结销售方法论；\n4.开拓中型大型客户、维护客户关系、建立长期的合作关系，对结果负责。","requirements":"岗位要求:\n1.三年以上客户销售经验，有食材客户销售经验者优先考虑；\n2.较强的沟通能力和同理心，能够和客户深入交流、赢得客户信任、获取客户需求、进行专业宣讲和方案引导；\n3.能够跟进客户需求制定销售策略；\n4.自我驱动、有创新意识、有激情、结果导向，具备良好的团队合作精神，以客户为中心，能组织、协调周边资源达成组织、项目的目标；\n5.较强的学习能力、适应性强、组织协调能力强。","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n岗位职责:\n1.深刻、全面的理解客户需求，协同相关部门制定服务方案，帮助客户更好进行服务规划、完成服务目标、提升服务满意度，从而提升美团公司品牌影响力；\n2.深入理解客户流程、决策的决策链和关键人；\n3.理解行业规律及市场空间，总结销售方法论；\n4.开拓中型大型客户、维护客户关系、建立长期的合作关系，对结果负责。\n\n岗位基本要求\n岗位要求:\n1.三年以上客户销售经验，有食材客户销售经验者优先考虑；\n2.较强的沟通能力和同理心，能够和客户深入交流、赢得客户信任、获取客户需求、进行专业宣讲和方案引导；\n3.能够跟进客户需求制定销售策略；\n4.自我驱动、有创新意识、有激情、结果导向，具备良好的团队合作精神，以客户为中心，能组织、协调周边资源达成组织、项目的目标；\n5.较强的学习能力、适应性强、组织协调能力强。\n\n岗位亮点\n岗位亮点:\n1.能够较快的建立销售技能及视野；\n2.加入快速成长的学习型团队，快速提升综合能力。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4098791079","sourceKey":"meituan_social","company":"美团","title":"CKA业务中心-重庆-产品销售","city":"重庆市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4098791079&jobShareType=1","duty":"1.深刻、全面的理解客户需求，协同相关部门制定服务方案，帮助客户更好进行服务规划、完成服务目标、提升服务满意度，从而提升美团公司品牌影响力；2.深入理解客户流程、决策的决策链和关键人；3.理解行业规律及市场空间，总结销售方法论；4.开拓中型大型客户、维护客户关系、建立长期的合作关系，对销售结果负责。","requirements":"1.三年以上客户销售经验，有食材客户销售经验者优先考虑；2.较强的沟通能力和同理心，能够和客户深入交流、赢得客户信任、获取客户需求、进行专业宣讲和方案引导；3.能够跟进客户需求制定销售策略；4.自我驱动、有创新意识、有激情、结果导向，具备良好的团队合作精神，以客户为中心，能组织、协调周边资源达成组织、项目的目标；5.较强的学习能力、适应性强、组织协调能力强。","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1.深刻、全面的理解客户需求，协同相关部门制定服务方案，帮助客户更好进行服务规划、完成服务目标、提升服务满意度，从而提升美团公司品牌影响力；2.深入理解客户流程、决策的决策链和关键人；3.理解行业规律及市场空间，总结销售方法论；4.开拓中型大型客户、维护客户关系、建立长期的合作关系，对销售结果负责。\n\n岗位基本要求\n1.三年以上客户销售经验，有食材客户销售经验者优先考虑；2.较强的沟通能力和同理心，能够和客户深入交流、赢得客户信任、获取客户需求、进行专业宣讲和方案引导；3.能够跟进客户需求制定销售策略；4.自我驱动、有创新意识、有激情、结果导向，具备良好的团队合作精神，以客户为中心，能组织、协调周边资源达成组织、项目的目标；5.较强的学习能力、适应性强、组织协调能力强。\n\n岗位亮点\n1.能够较快的建立销售技能及视野；2.加入快速成长的学习型团队，快速提升综合能力。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4685590070","sourceKey":"meituan_social","company":"美团","title":"PC城市负责人--华南","city":"深圳市/广州市/南宁市/厦门市/福州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4685590070&jobShareType=1","duty":"1、履约保障：全面统筹加工中心日常运营管理，制定并分解生产计划，确保各环节有序推进、按时交付，保障中心整体产能目标达成。\n2、团队建设：负责团队的选用育励汰，为团队成员的成长和发展负责，建设一直高执行、高标准的一线运营团队。\n3、跨部门协同：建立与横向部门高效的协同关系，推动链路卡点解决，善于形成方法论，推动流程制度建设。\n4、精益改善：建立生产数据监控机制，定期分析关键指标（效率、质量、损耗等），识别瓶颈与异常，持续优化加工工艺与作业流程，提升效率，保障加工品质，提出针对性改进方案，推动持续改善。\n5、项目运营：负责新项目的测试进度、结果分析总结，推动新项目落地。","requirements":"1. 大学本科及以上学历，物流、工业工程、食品等相关专业优先。\n2. 具备5年以上物流、食品加工、生鲜领域工作经验，有大规模（300人以上）团队管理经验。\n3. 熟悉生产管理流程，具备较强的数据分析能力和问题解决能力。\n4. 具备良好的沟通协调能力和项目管理能力，能独立推动复杂项目落地\n5. 工作责任心强，能适应快节奏工作环境。\n6.有中央厨房、净菜生产经验优先。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1、履约保障：全面统筹加工中心日常运营管理，制定并分解生产计划，确保各环节有序推进、按时交付，保障中心整体产能目标达成。\n2、团队建设：负责团队的选用育励汰，为团队成员的成长和发展负责，建设一直高执行、高标准的一线运营团队。\n3、跨部门协同：建立与横向部门高效的协同关系，推动链路卡点解决，善于形成方法论，推动流程制度建设。\n4、精益改善：建立生产数据监控机制，定期分析关键指标（效率、质量、损耗等），识别瓶颈与异常，持续优化加工工艺与作业流程，提升效率，保障加工品质，提出针对性改进方案，推动持续改善。\n5、项目运营：负责新项目的测试进度、结果分析总结，推动新项目落地。\n\n岗位基本要求\n1. 大学本科及以上学历，物流、工业工程、食品等相关专业优先。\n2. 具备5年以上物流、食品加工、生鲜领域工作经验，有大规模（300人以上）团队管理经验。\n3. 熟悉生产管理流程，具备较强的数据分析能力和问题解决能力。\n4. 具备良好的沟通协调能力和项目管理能力，能独立推动复杂项目落地\n5. 工作责任心强，能适应快节奏工作环境。\n6.有中央厨房、净菜生产经验优先。\n\n岗位亮点\n平台宽广，晋升空间大；\n业务快速发展期，个人成长快速","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4637218190","sourceKey":"meituan_social","company":"美团","title":"华西大区负责人","city":"成都市/西安市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4637218190&jobShareType=1","duty":"1. 全面负责华西大区物流运营生产体系的规划、建设与优化，确保区域效率与服务质量及新能看建设的持续提升。  \n2. 制定并执行大区物流战略，统筹多个城市，果蔬加工，净菜加工，等项目的运营管理及目标达成。  \n3. 带领团队完成日常运营目标，监督KPI达成情况，推动流程标准化与数字化升级。  \n4. 协同总部与各区域资源，解决重大运营问题，提升客户满意度与市场响应速度。  \n5. 建立并培养高效物流团队，完善人才梯队建设与绩效激励机制。","requirements":"1. 大学本科及以上学历，食品、物流、供应链、管理类相关专业优先。  \n2. 8年以上生产行业工作经验，具备大区或跨区域物流运营管理经验。  \n3. 具备较强的数据分析能力、战略规划能力和团队管理能力。  \n5. 工作地点为上海市或杭州市，能适应高频次跨区域出差。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1. 全面负责华西大区物流运营生产体系的规划、建设与优化，确保区域效率与服务质量及新能看建设的持续提升。  \n2. 制定并执行大区物流战略，统筹多个城市，果蔬加工，净菜加工，等项目的运营管理及目标达成。  \n3. 带领团队完成日常运营目标，监督KPI达成情况，推动流程标准化与数字化升级。  \n4. 协同总部与各区域资源，解决重大运营问题，提升客户满意度与市场响应速度。  \n5. 建立并培养高效物流团队，完善人才梯队建设与绩效激励机制。\n\n岗位基本要求\n1. 大学本科及以上学历，食品、物流、供应链、管理类相关专业优先。  \n2. 8年以上生产行业工作经验，具备大区或跨区域物流运营管理经验。  \n3. 具备较强的数据分析能力、战略规划能力和团队管理能力。  \n5. 工作地点为上海市或杭州市，能适应高频次跨区域出差。\n\n具备以下条件优先\n1、区域管理经验 — 有区域/中台综合岗位经历者优先\n2、数据化思维 — 具备数据驱动管理理念\n3、生鲜工厂背景 — 大型生鲜生产工厂、多元化业务经验\n\n岗位亮点\n1. 担任大区负责人，拥有高度自主权与战略决策参与机会。  \n2. 加入行业优选企业，平台资源丰富，发展空间广阔。  \n3. 大团队规模的管理，具备完善的管理支持体系与晋升通道。  \n4. 工作地点位于长三角核心城市，交通便利，生活配套完善。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4712530077","sourceKey":"meituan_social","company":"美团","title":"生鲜加工主管","city":"青岛市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4712530077&jobShareType=1","duty":"1、负责排产、排班、出勤计划执行，加工进度管控、每日订单目标交付达成；\n2、负责加工过程中人员组台、品类拆分、原料进度追踪、异常协调等业务；\n3、负责加工品质保障、加工数据准确性管理、上下游入库准确性管理；\n4、负责设备高效使用，员工积极性策略推动与执行；\n5、负责加工区域6S、生产安全、消防安全、食品安全等管理；\n6、负责促成部门各指标达成（品质、原料成本、人力成本、员工留存等）\n7、负责班次团队组织架构搭建、招聘计划、人员培养汰换，每日生产会议。","requirements":"1.具备物流或仓储相关领域的大学专科及以上学历。\n2.至少3年以上物流或仓储管理经验，有生鲜加工管理经验者优先考虑。\n3.熟悉生鲜产品的质量标准和加工工艺，具备相关品控知识。\n4.具备较好的团队管理能力，能够激励团队成员，提高工作效率。\n5.具备良好的沟通协调能力，能够与不同部门和供应商进行有效的合作。\n6.具备一定的问题解决能力和应变能力，能够灵活应对工作中的各种挑战。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1、负责排产、排班、出勤计划执行，加工进度管控、每日订单目标交付达成；\n2、负责加工过程中人员组台、品类拆分、原料进度追踪、异常协调等业务；\n3、负责加工品质保障、加工数据准确性管理、上下游入库准确性管理；\n4、负责设备高效使用，员工积极性策略推动与执行；\n5、负责加工区域6S、生产安全、消防安全、食品安全等管理；\n6、负责促成部门各指标达成（品质、原料成本、人力成本、员工留存等）\n7、负责班次团队组织架构搭建、招聘计划、人员培养汰换，每日生产会议。\n\n岗位基本要求\n1.具备物流或仓储相关领域的大学专科及以上学历。\n2.至少3年以上物流或仓储管理经验，有生鲜加工管理经验者优先考虑。\n3.熟悉生鲜产品的质量标准和加工工艺，具备相关品控知识。\n4.具备较好的团队管理能力，能够激励团队成员，提高工作效率。\n5.具备良好的沟通协调能力，能够与不同部门和供应商进行有效的合作。\n6.具备一定的问题解决能力和应变能力，能够灵活应对工作中的各种挑战。\n\n具备以下条件优先\n有食品加工或生鲜加工管理经验优先。\n\n岗位亮点\n1、公司业务发展快，晋升空间大；\n2、公司有定期培训，学习机会多，个人成长速度快。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4712480835","sourceKey":"meituan_social","company":"美团","title":"生鲜加工主管","city":"青岛市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4712480835&jobShareType=1","duty":"1、负责排产、排班、出勤计划执行，加工进度管控、每日订单目标交付达成；\n2、负责加工过程中人员组台、品类拆分、原料进度追踪、异常协调等业务；\n3、负责加工品质保障、加工数据准确性管理、上下游入库准确性管理；\n4、负责设备高效使用，员工积极性策略推动与执行；\n5、负责加工区域6S、生产安全、消防安全、食品安全等管理；\n6、负责促成部门各指标达成（品质、原料成本、人力成本、员工留存等）\n7、负责班次团队组织架构搭建、招聘计划、人员培养汰换，每日生产会议。","requirements":"1.具备物流或仓储相关领域的大学本科及以上学历。\n2.至少5年以上物流或仓储管理经验，有生鲜加工管理经验者优先考虑。\n3.熟悉生鲜产品的质量标准和加工工艺，具备相关品控知识。\n4.具备团队搭建能力，较强的团队管理能力能够激励团队成员，提高工作效率。\n5.具备良好的沟通协调能力，能够与不同部门和供应商进行有效的合作。\n6.具备一定的问题解决能力和应变能力，能够灵活应对工作中的各种挑战。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1、负责排产、排班、出勤计划执行，加工进度管控、每日订单目标交付达成；\n2、负责加工过程中人员组台、品类拆分、原料进度追踪、异常协调等业务；\n3、负责加工品质保障、加工数据准确性管理、上下游入库准确性管理；\n4、负责设备高效使用，员工积极性策略推动与执行；\n5、负责加工区域6S、生产安全、消防安全、食品安全等管理；\n6、负责促成部门各指标达成（品质、原料成本、人力成本、员工留存等）\n7、负责班次团队组织架构搭建、招聘计划、人员培养汰换，每日生产会议。\n\n岗位基本要求\n1.具备物流或仓储相关领域的大学本科及以上学历。\n2.至少5年以上物流或仓储管理经验，有生鲜加工管理经验者优先考虑。\n3.熟悉生鲜产品的质量标准和加工工艺，具备相关品控知识。\n4.具备团队搭建能力，较强的团队管理能力能够激励团队成员，提高工作效率。\n5.具备良好的沟通协调能力，能够与不同部门和供应商进行有效的合作。\n6.具备一定的问题解决能力和应变能力，能够灵活应对工作中的各种挑战。\n\n具备以下条件优先\n有食品加工或生鲜加工管理经验优先。\n\n岗位亮点\n1、公司业务发展快，晋升空间大；\n2、公司有定期培训，学习机会多，个人成长速度快。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4712066831","sourceKey":"meituan_social","company":"美团","title":"快乐猴仓储主管（冷藏）","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4712066831&jobShareType=1","duty":"1、负责仓库的日常管理工作；做好仓库商品的收发管理控制工作，提高员工的工作效率；持续提升、不断改善工作效率和工作质量。提高入库工作的管理水平，保证突发问题能够予以快速、妥善的解决；\n2、监督各项管理制的执行，检查和审核员工的工作进度，负责员工的考勤及绩效考核；\n3、组织做好仓库的安全管理工作，发现问题或隐患及时上报处理；\n4、对工进行必要的岗位知识培训，同时对工作结果进行评价；\n5、合理对货位进行安排，做到物资整洁、清晰、便于操作、便于识别；\n6、提高库房各项资源的利用率；\n7、完成上级交办的其他作务。","requirements":"1、专科以上学历，物流管理等相关专业优先；\n2、3年以上物流、仓储相关领域管理工作经验，有分仓管理经验者优先；\n3、较强的计划组强能力、计划落实能力、执行能力；\n4、良好的沟通协调能力，熟练使用电脑，熟悉办公软件；\n5、熟悉物流、仓储业务流程，熟悉相关质量管理体系；\n6、有零售便利店或者生鲜工作经验优先；\n7、了解仓储自动化相关机械设备。","description":"部门介绍\n快乐猴是美团自营社区超市，依托自有供应链和门店管理体系，聚焦家庭用户的三餐所需，为消费者提供高质价比的食杂商品。快乐猴以数字化能力与科学品控为基础，不断满足消费者对“省”和“便利”的需求。\n\n岗位职责\n1、负责仓库的日常管理工作；做好仓库商品的收发管理控制工作，提高员工的工作效率；持续提升、不断改善工作效率和工作质量。提高入库工作的管理水平，保证突发问题能够予以快速、妥善的解决；\n2、监督各项管理制的执行，检查和审核员工的工作进度，负责员工的考勤及绩效考核；\n3、组织做好仓库的安全管理工作，发现问题或隐患及时上报处理；\n4、对工进行必要的岗位知识培训，同时对工作结果进行评价；\n5、合理对货位进行安排，做到物资整洁、清晰、便于操作、便于识别；\n6、提高库房各项资源的利用率；\n7、完成上级交办的其他作务。\n\n岗位基本要求\n1、专科以上学历，物流管理等相关专业优先；\n2、3年以上物流、仓储相关领域管理工作经验，有分仓管理经验者优先；\n3、较强的计划组强能力、计划落实能力、执行能力；\n4、良好的沟通协调能力，熟练使用电脑，熟悉办公软件；\n5、熟悉物流、仓储业务流程，熟悉相关质量管理体系；\n6、有零售便利店或者生鲜工作经验优先；\n7、了解仓储自动化相关机械设备。\n\n具备以下条件优先\n大型商超物流工作经验优先\n\n岗位亮点\n发展前景好，薪资体系成熟，大平台，团队工作氛围好","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4718352008","sourceKey":"meituan_social","company":"美团","title":"深圳蔬果前置品控","city":"深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4718352008&jobShareType=1","duty":"1. 负责深圳地区蔬果前置仓的品质管控工作，确保商品符合公司质量标准。  \n2. 对入库、存储及出库环节的蔬果进行抽检与评估，及时发现并反馈品质异常。  \n3. 协助制定并优化蔬果品控流程，提升前置运营效率与商品合格率。  \n4. 与采购、仓储及物流团队协同，推动品质问题的闭环解决。","requirements":"1. 大学专科及以上学历，农业、食品科学、供应链管理等相关专业优先。  \n2. 具备3年以上生鲜、蔬果或快消品行业品质管理经验。  \n3. 熟悉蔬果品类特性及常见品质问题，具备现场判断与处理能力。  \n4. 工作细致、责任心强，能适应前置仓现场工作环境。","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1. 负责深圳地区蔬果前置仓的品质管控工作，确保商品符合公司质量标准。  \n2. 对入库、存储及出库环节的蔬果进行抽检与评估，及时发现并反馈品质异常。  \n3. 协助制定并优化蔬果品控流程，提升前置运营效率与商品合格率。  \n4. 与采购、仓储及物流团队协同，推动品质问题的闭环解决。\n\n岗位基本要求\n1. 大学专科及以上学历，农业、食品科学、供应链管理等相关专业优先。  \n2. 具备3年以上生鲜、蔬果或快消品行业品质管理经验。  \n3. 熟悉蔬果品类特性及常见品质问题，具备现场判断与处理能力。  \n4. 工作细致、责任心强，能适应前置仓现场工作环境。\n\n具备以下条件优先\n基本的数据分析、蔬果专业知识、沟通协作能力\n\n岗位亮点\n1. 深入生鲜供应链一线，积累实战型品控经验。  \n2. 参与流程优化与标准建设，提升专业影响力。  \n3. 地处深圳核心区域，交通便利，团队氛围积极。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4626088366","sourceKey":"meituan_social","company":"美团","title":"政府/校园渠道业务拓展经理","city":"济南市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4626088366&jobShareType=1","duty":"1、负责区域内高校、职教园区渠道开发与维护，对接院校后勤、保卫、学工等部门，洽谈校园共享电单车准入合作，推进校园站点布局、运营方案落地；\n2、统筹政企、校园项目全流程：商务谈判、合作方案撰写、合同洽谈签署、项目落地跟进、存量合作续约，完成渠道拓展指标；\n3、持续跟踪地方政策变化、区域动态，定期输出市场分析，为业务投放策略、运营调整提供依据；\n4、协同运营、合规团队，保障政企项目、校园项目平稳运营、校园运营相关问题。\n5、负责所辖区域政府主管部门对接，建立常态化沟通机制，跟进共享电单车路权、投放准入、运营政策，推动项目准入落地；","requirements":"1、本科及以上学历，市场营销、公共管理、商务管理相关专业优先；\n2、5年以上大客户商务拓展经验，拥有政府政企对接经验，或高校校园渠道拓展经验优先；有出行、共享行业资源者加分；\n3、熟悉高校校园生态，具备大客户谈判、方案撰写、资源整合能力，能够独立推进项目从洽谈至落地；\n4、优秀对外沟通、跨部门协同、项目推进能力，目标导向，具备较强结果意识；\n5、能够接受区域内短途出差，主动进取，具备良好的商务礼仪；\n6、了解共享电单车、两轮出行行业者优先。","description":"部门介绍\n美团骑行事业部在全国各个城市开展美团单车、电单车业务，提供绿色、便捷的共享出行服务，是美团出行板块重要的组成部分。我们力求为城市可持续发展提供低碳智能的解决方案，通过技术创新和硬件升级，不断优化全流程骑行体验，为低碳出行提供更好的服务。其中，美团单车旨在为城市居民提供通勤接驳服务，满足用户短途接驳出行需求；美团电单车则满足用户中短途多场景低碳出行需求。\n我们有开放的工作氛围，也有充满韧劲和创造力，心系低碳出行的伙伴。加入我们，一起为用户创造更好的出行体验。\n\n岗位职责\n1、负责区域内高校、职教园区渠道开发与维护，对接院校后勤、保卫、学工等部门，洽谈校园共享电单车准入合作，推进校园站点布局、运营方案落地；\n2、统筹政企、校园项目全流程：商务谈判、合作方案撰写、合同洽谈签署、项目落地跟进、存量合作续约，完成渠道拓展指标；\n3、持续跟踪地方政策变化、区域动态，定期输出市场分析，为业务投放策略、运营调整提供依据；\n4、协同运营、合规团队，保障政企项目、校园项目平稳运营、校园运营相关问题。\n5、负责所辖区域政府主管部门对接，建立常态化沟通机制，跟进共享电单车路权、投放准入、运营政策，推动项目准入落地；\n\n岗位基本要求\n1、本科及以上学历，市场营销、公共管理、商务管理相关专业优先；\n2、5年以上大客户商务拓展经验，拥有政府政企对接经验，或高校校园渠道拓展经验优先；有出行、共享行业资源者加分；\n3、熟悉高校校园生态，具备大客户谈判、方案撰写、资源整合能力，能够独立推进项目从洽谈至落地；\n4、优秀对外沟通、跨部门协同、项目推进能力，目标导向，具备较强结果意识；\n5、能够接受区域内短途出差，主动进取，具备良好的商务礼仪；\n6、了解共享电单车、两轮出行行业者优先。\n\n具备以下条件优先\n校园事务工作经验、大客户销售经验、有渠道商合作管理经验，对共享出行行业有一定了解和热爱\n\n岗位亮点\n内部业务发展快，个人成长空间大；基于公司平台接触社会资源更广泛，对个人能力提升有很大帮助","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4708709770","sourceKey":"meituan_social","company":"美团","title":"大客户销售（线索和新行业）","city":"北京市/上海市/深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4708709770&jobShareType=1","duty":"岗位职责：\n\n1.存量KA品牌营销运营：协同全国行业品牌提升线上经营能力，通过改善线上运营的方法，策略，有效提升商家流量、转化、转介绍等指标；\n2.白名单客户开拓：通过线上线下的方式主动拓展行业头部白名单客户，包含KA客户建立联系，挖掘需求，邀约拜访，传递产品价值，为KA客户提供整套数字化整合营销方案及商业变现的解决方案；\n3.专业赋能：研究LE行业特点，品牌线上及线下经营阻碍，帮助品牌制定专业线上经营方案和策略，输出赋能，影响品牌方；\n4.数据分析：KA销售（大客户销售）通过分析历史经营数据，行业数据分析，品牌经营数据分析，了解行业规律，确保品牌经营策略有效性，持续指导经营方案迭代；\n5.创新孵化：思考分析行业发展走势，赋能品牌共同探索下阶段行业商业模式和增长点；\n6.跨团队协同：根据业务发展需要，跨团队协调资源，共同解决商家需求，维护商家与平台的良性长久合作。","requirements":"1、KA客户分层管理：工作3年以上，有品牌客户/KA客户的销售经验；；\n2、有制作营销提案的能力，有较快的学习能力；\n3、对互联网行业各平台发展历程有认知；\n4、良好的商务沟通与方案演讲能力；\n5、本科及以上学历，熟知办公软件技能；\n6、跨部门沟通协调能力。\n7、有教育、家具家居、家用电器、亲子母婴、结婚/摄影，生活服务等行业KA销售或运营经验者优先。","description":"部门介绍\n美团服务零售事业部下设乐生活业务部、易生活业务部、进场零售业务部以及中小城市发展部四大业务部门，旨在通过提供丰富、可靠、实惠的服务与商品满足用户各类生活需求。我们所处的服务零售行业是一个具有万亿规模的市场，覆盖足疗洗浴、酒吧KTV、运动健身、美发美甲、教育培训、亲子游乐、家政洗涤维修、摄影写真等数十个服务消费细分领域，同时延伸至超市便利、美妆个护、3C数码、服饰珠宝、运动户外、商场购物中心等实体零售到店消费场景，连接数十万品牌商户与线下门店。作为商家和行业的小帮手，我们持续深入服务零售与实体零售产业链，用AI等技术推动行业变革，帮助商家提升经营效率、实现高效的线上化经营与到店转化，优化消费者服务体验，提供安心、放心的履约保障。这里有着多元的业务布局，有着富有挑战和影响力的工作内容，为你提供丰富的视野、持续的成长和发展机会，引领你发现更多可能。期待和你在“随时随地，美好生活”的愿景指引下，共建美好的生活服务体验、健康的商家生态与高质量的经营结果。\n\n岗位职责\n岗位职责：\n\n1.存量KA品牌营销运营：协同全国行业品牌提升线上经营能力，通过改善线上运营的方法，策略，有效提升商家流量、转化、转介绍等指标；\n2.白名单客户开拓：通过线上线下的方式主动拓展行业头部白名单客户，包含KA客户建立联系，挖掘需求，邀约拜访，传递产品价值，为KA客户提供整套数字化整合营销方案及商业变现的解决方案；\n3.专业赋能：研究LE行业特点，品牌线上及线下经营阻碍，帮助品牌制定专业线上经营方案和策略，输出赋能，影响品牌方；\n4.数据分析：KA销售（大客户销售）通过分析历史经营数据，行业数据分析，品牌经营数据分析，了解行业规律，确保品牌经营策略有效性，持续指导经营方案迭代；\n5.创新孵化：思考分析行业发展走势，赋能品牌共同探索下阶段行业商业模式和增长点；\n6.跨团队协同：根据业务发展需要，跨团队协调资源，共同解决商家需求，维护商家与平台的良性长久合作。\n\n岗位基本要求\n1、KA客户分层管理：工作3年以上，有品牌客户/KA客户的销售经验；；\n2、有制作营销提案的能力，有较快的学习能力；\n3、对互联网行业各平台发展历程有认知；\n4、良好的商务沟通与方案演讲能力；\n5、本科及以上学历，熟知办公软件技能；\n6、跨部门沟通协调能力。\n7、有教育、家具家居、家用电器、亲子母婴、结婚/摄影，生活服务等行业KA销售或运营经验者优先。\n\n岗位亮点\n岗位亮点：\n1、开放、直接的工作氛围，以逻辑、数据和事实说话，而不是岗位级别和层级。我们尊重知识和常识，努力以业务视角思考自身工作。\n2、行业覆盖面广，在这个团队你能够接触各个行业的专家，打开你的职场新视角。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4711517636","sourceKey":"meituan_social","company":"美团","title":"员工关系管理高级专家（风险安全方向）","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4711517636&jobShareType=1","duty":"ER事件全流程处理，覆盖全国前置仓几万员工；降低事故发生率。\n\n1. 劳资纠纷处理： 负责日常员工劳资纠纷的受理、调查、调解与闭环处理，包括但不限于工资争议、工伤认定争议、解除劳动合同纠纷等。\n2. 交通/仓内事故处理： 对接城市管理者，代理商，保险公司，公司安全法务等各方，负责员工交通事故的应急响应、责任认定跟进、伤者安置与善后处理，协调交警、保险等多方资源，推动ER事件快速闭环。\n3. 对接劳动监察人社等部门，配合调查和政策推发，解释相关业务逻辑。\n4. 台账维护： 全量ER事件分类登记、全程记录、定期更新，建立规范化管理台账，确保数据真实、完整、可追溯。\n5. 经验总结与优化： 针对不同事故类型，定期总结经验教训，识别高频风险点和管理薄弱环节，针对性改进，降低事故发生率。联动城市调优管理动作， 基于ER事件数据分析，向城市管理层提供决策支持，优化骑手管理、仓储运营、站点调度等可能引发事故和纠纷的关键环节，持续降低事故发生率。\n6. 流程与制度完善：推动完善员工关系管理相关制度（例如车辆车牌管理）、流程与标准，形成规范化的操作手册和应急预案，了解代理商的垫款和兜底空间能力，建立风险备用金等相关机制。\n7. 保险公司理赔进度跟进，优化保险条款，确保保障范围与实际风险匹配，管理保费合理性，定期评估保险方案性价比。","requirements":"1. 大学本科及以上学历，人力资源相关专业优先。  \n2. 至少3年员工关系或相关业务运营管理工作经验。  \n3. 熟悉劳动法律法规，具备较强的沟通协调与问题解决能力。  \n4. 工作城市为北京市，能适应跨部门协作与快节奏工作环境。\n5.  需要全国出差，根据监察部门要求、事故严重程度等，现场沟通。","description":"部门介绍\n美团闪购是美团旗下的即时零售平台，依托即时配送能力，连接本地零售供给，满足消费者30分钟万物到家的即时需求。美团闪购涵盖超市便利、食材、水果、鲜花绿植、休闲零食、酒水饮料、数码家电、美妆个护、母婴玩具、日用百货、服饰鞋帽、宠物等诸多品类，业务覆盖全国近3,000个县市区旗，每日百万级在岗骑手，以高效的配送、丰富的品类和广泛的覆盖，为美团数亿用户带来便捷的生活体验，积极助力实体零售线上化转型，提升本地商业活力。\n\n岗位职责\nER事件全流程处理，覆盖全国前置仓几万员工；降低事故发生率。\n\n1. 劳资纠纷处理： 负责日常员工劳资纠纷的受理、调查、调解与闭环处理，包括但不限于工资争议、工伤认定争议、解除劳动合同纠纷等。\n2. 交通/仓内事故处理： 对接城市管理者，代理商，保险公司，公司安全法务等各方，负责员工交通事故的应急响应、责任认定跟进、伤者安置与善后处理，协调交警、保险等多方资源，推动ER事件快速闭环。\n3. 对接劳动监察人社等部门，配合调查和政策推发，解释相关业务逻辑。\n4. 台账维护： 全量ER事件分类登记、全程记录、定期更新，建立规范化管理台账，确保数据真实、完整、可追溯。\n5. 经验总结与优化： 针对不同事故类型，定期总结经验教训，识别高频风险点和管理薄弱环节，针对性改进，降低事故发生率。联动城市调优管理动作， 基于ER事件数据分析，向城市管理层提供决策支持，优化骑手管理、仓储运营、站点调度等可能引发事故和纠纷的关键环节，持续降低事故发生率。\n6. 流程与制度完善：推动完善员工关系管理相关制度（例如车辆车牌管理）、流程与标准，形成规范化的操作手册和应急预案，了解代理商的垫款和兜底空间能力，建立风险备用金等相关机制。\n7. 保险公司理赔进度跟进，优化保险条款，确保保障范围与实际风险匹配，管理保费合理性，定期评估保险方案性价比。\n\n岗位基本要求\n1. 大学本科及以上学历，人力资源相关专业优先。  \n2. 至少3年员工关系或相关业务运营管理工作经验。  \n3. 熟悉劳动法律法规，具备较强的沟通协调与问题解决能力。  \n4. 工作城市为北京市，能适应跨部门协作与快节奏工作环境。\n5.  需要全国出差，根据监察部门要求、事故严重程度等，现场沟通。\n\n具备以下条件优先\n1. 具备一线员工及家属谈判能力： 直接与员工及其家属进行沟通谈判，妥善处理赔偿、安抚等事宜，维护公司形象与员工关系稳定。\n2. 具备数据归纳整理能力： 定期汇总各类型事故/纠纷数据，从事件类型、发生频次、责任方、赔付金额、处理周期等多维度进行数据分析和归纳整理。\n3. 总结汇报能力： 每半年度完成风险与安全方向的全面总结，沉淀典型ERcase与经验，向管理层汇报风险态势、处理成效、优化成果及下一步规划，形成可复制的经验方法论。\n\n岗位亮点\n1. 业务发展上升期，平稳扩张，与平台一起发展进步。\n2. 提供完善的职业发展通道。  \n3. 团队氛围开放包容，鼓励创新与主动担当。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4718245519","sourceKey":"meituan_social","company":"美团","title":"景点玩乐服务流程运营","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4718245519&jobShareType=1","duty":"1、负责统筹服务全流程和链路的设计与运营，持续改善客户/商户服务的工作流程、执行规范等基础制度，并能落地实施。\n2、持续提升客户服务解决能力，关注客户体验，建立有效的运营机制，赋能客服团队并提升其解决问题的能力。\n3、通过对行业/业务分析&调研、客户声音的洞察&分析等举措，发现痛点问题，与协同团队密切合作，推动问题从源头解决。\n4、负责与业务建立良好的协同关系，带领团队通过深入走访业务一线等方式熟悉业务运营的各个环节，识别有效问题，主动为业务团队提出改善建议并推动需求项目执行。\n5、引入AI工具辅助服务流程优化。","requirements":"1、本科及以上学历，3年以上客户服务行业经验。\n2、具备大中型复杂项目管理能力和较强的业务推动能力，有一定的目标导向，自驱力强。\n3、逻辑性强，具备较强的数据分析能力，能清楚的判断客户痛点，具备发现问题及主动改善能力，解析影响客户体验的具体因素，结构化输出合理化解决方案，并推动方案执行达成结果。\n4、能够协同或整合内外部资源 ，有团队合作精神，工作严谨踏实，责任心强。\n5、能够熟练运用AI工具和人机协作，具备岗位要求的AI能力。","description":"部门介绍\n美团平台为用户的基础产品体验负责，还承担了美团的用户增长、市场和品牌营销以及多条业务线的产品设计职责，建立了融合文字、图片、视频和直播等不同形式的內容生态系统，同时整合地图服务部、客户服务和体验部、企业业务部、网约车业务部等部门，致力于用科技提升美团数亿消费者、近千万商家、骑手、司机和团长的服务体验。美团平台拥有高并发、多业务的复杂场景，为技术深度优化提供了最佳实践可能。这里有简单、讲逻辑、有爱的团队，更是一块理想的实战场地，舞台广阔，欢迎你来尽情施展。\n\n岗位职责\n1、负责统筹服务全流程和链路的设计与运营，持续改善客户/商户服务的工作流程、执行规范等基础制度，并能落地实施。\n2、持续提升客户服务解决能力，关注客户体验，建立有效的运营机制，赋能客服团队并提升其解决问题的能力。\n3、通过对行业/业务分析&调研、客户声音的洞察&分析等举措，发现痛点问题，与协同团队密切合作，推动问题从源头解决。\n4、负责与业务建立良好的协同关系，带领团队通过深入走访业务一线等方式熟悉业务运营的各个环节，识别有效问题，主动为业务团队提出改善建议并推动需求项目执行。\n5、引入AI工具辅助服务流程优化。\n\n岗位基本要求\n1、本科及以上学历，3年以上客户服务行业经验。\n2、具备大中型复杂项目管理能力和较强的业务推动能力，有一定的目标导向，自驱力强。\n3、逻辑性强，具备较强的数据分析能力，能清楚的判断客户痛点，具备发现问题及主动改善能力，解析影响客户体验的具体因素，结构化输出合理化解决方案，并推动方案执行达成结果。\n4、能够协同或整合内外部资源 ，有团队合作精神，工作严谨踏实，责任心强。\n5、能够熟练运用AI工具和人机协作，具备岗位要求的AI能力。\n\n岗位亮点\n1、热门核心行业以及重点岗位，能够全面接触以及深入了解行业动态、服务策略等，有助于眼界开阔。\n2、有机会参与或统筹复杂业务场景中跨部门重大项目管理工作。\n3、专业可靠的工作搭子，团队关系融洽，工作学习氛围好，重视每个成员的个人发展。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4679202315","sourceKey":"meituan_social","company":"美团","title":"小象超市长沙-PC仓运营支持主管","city":"长沙市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4679202315&jobShareType=1","duty":"1、数据监控体系搭建：能深入了解业务，熟悉负责方向的业务流程，建立区域业务数据跟踪监控体系，搭建可准确反映业务运作状况的数据指标体系和数据产品；\n2、数据提取：负责团队内业务数据需求梳理，结合业务逻辑，为团队提供数据查询、提取及数据分析处理工作；\n3、数据看板及可视化：根据公司提供的相关数据渠道搭建并维护各种线上报表，为业务侧提供数据过程监控，能够使用Ex-cel、SQL、Power BI、Ta-bleau等工具实现数据可视化；\n4、数据检核：配合运营团队完成对业务侧的日常关键输入/输出数据核查、异常定位等工作；\n5、项目管理：参与业务核心项目，负责核心项目的运营支持，协助项目组成员目标制定、策略拆解、路径达成、组织资源等多维度的合理性和可提升的机会点，及时识别业务风险、推动问题解决、形成闭环管理，保障项目目标达成；\n6、部门内其他需要协调完成的相关工作。","requirements":"1、专科及以上学历，计算机、数学、统计学相关专业优先；\n2、至少3年左右数据分析经验，互联网数据库经验者优先，拥有1年以上项目管理及PMO相关工作经验优先；\n3、精通HIVE/SQL数据查询语言，有很好数据报表以及报告呈现能力；熟练操作办公软件，掌握Ex-cel、Power BI、Ta-bleau等工具，并有使用经验者优先；\n4、具备快速学习能力，能在短期内快速了解业务逻辑；\n5、具备较强的逻辑思维能力、独立解决问题的能力；\n6、积极主动、性格开朗、善于沟通、工作严谨、责任心强、具有团队合作精神。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1、数据监控体系搭建：能深入了解业务，熟悉负责方向的业务流程，建立区域业务数据跟踪监控体系，搭建可准确反映业务运作状况的数据指标体系和数据产品；\n2、数据提取：负责团队内业务数据需求梳理，结合业务逻辑，为团队提供数据查询、提取及数据分析处理工作；\n3、数据看板及可视化：根据公司提供的相关数据渠道搭建并维护各种线上报表，为业务侧提供数据过程监控，能够使用Ex-cel、SQL、Power BI、Ta-bleau等工具实现数据可视化；\n4、数据检核：配合运营团队完成对业务侧的日常关键输入/输出数据核查、异常定位等工作；\n5、项目管理：参与业务核心项目，负责核心项目的运营支持，协助项目组成员目标制定、策略拆解、路径达成、组织资源等多维度的合理性和可提升的机会点，及时识别业务风险、推动问题解决、形成闭环管理，保障项目目标达成；\n6、部门内其他需要协调完成的相关工作。\n\n岗位基本要求\n1、专科及以上学历，计算机、数学、统计学相关专业优先；\n2、至少3年左右数据分析经验，互联网数据库经验者优先，拥有1年以上项目管理及PMO相关工作经验优先；\n3、精通HIVE/SQL数据查询语言，有很好数据报表以及报告呈现能力；熟练操作办公软件，掌握Ex-cel、Power BI、Ta-bleau等工具，并有使用经验者优先；\n4、具备快速学习能力，能在短期内快速了解业务逻辑；\n5、具备较强的逻辑思维能力、独立解决问题的能力；\n6、积极主动、性格开朗、善于沟通、工作严谨、责任心强、具有团队合作精神。\n\n岗位亮点\n1、公司业务发展快，晋升空间大；\n2、学习机会多，个人成长速度快；","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4469108597","sourceKey":"meituan_social","company":"美团","title":"美团骑行-资管城市经理-安徽","city":"合肥市/厦门市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4469108597&jobShareType=1","duty":"1.负责所辖区域运营资源供给保障及仓库管理，支撑管辖区域经营目标的达成；\n2.执行落地相关管理要求及流程标准；\n3.对资产/作业/现场等的各场景下的安全管理工作进行体系化建设，防范和处理风险；\n4.管理和培养团队，持续提升团队现场管理能力和作业效率。","requirements":"1.本科及以上学历，具有2年以上团队管理经验，有相关物流仓储工作经验优先；\n2.具有较强的人际交往能力和应变能力；\n3.熟悉基本电脑办公软件，有良好的数据分析和提炼能力；\n4.具有强烈的责任感，学习能力强，吃苦耐劳，认可公司绿色出行与共享理念。","description":"部门介绍\n美团骑行事业部在全国各个城市开展美团单车、电单车业务，提供绿色、便捷的共享出行服务，是美团出行板块重要的组成部分。我们力求为城市可持续发展提供低碳智能的解决方案，通过技术创新和硬件升级，不断优化全流程骑行体验，为低碳出行提供更好的服务。其中，美团单车旨在为城市居民提供通勤接驳服务，满足用户短途接驳出行需求；美团电单车则满足用户中短途多场景低碳出行需求。\n我们有开放的工作氛围，也有充满韧劲和创造力，心系低碳出行的伙伴。加入我们，一起为用户创造更好的出行体验。\n\n岗位职责\n1.负责所辖区域运营资源供给保障及仓库管理，支撑管辖区域经营目标的达成；\n2.执行落地相关管理要求及流程标准；\n3.对资产/作业/现场等的各场景下的安全管理工作进行体系化建设，防范和处理风险；\n4.管理和培养团队，持续提升团队现场管理能力和作业效率。\n\n岗位基本要求\n1.本科及以上学历，具有2年以上团队管理经验，有相关物流仓储工作经验优先；\n2.具有较强的人际交往能力和应变能力；\n3.熟悉基本电脑办公软件，有良好的数据分析和提炼能力；\n4.具有强烈的责任感，学习能力强，吃苦耐劳，认可公司绿色出行与共享理念。\n\n具备以下条件优先\n有两轮共享出行、骑行资产管理相关经验的\n\n岗位亮点\n1.岗位未来可以承担更大的管理宽幅和职级提升；\n2.职级上，表现优异着可获得晋升机会；\n3.公司平台大，发展空间大。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4701466661","sourceKey":"meituan_social","company":"美团","title":"公共事务专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4701466661&jobShareType=1","duty":"1.日常与网信等政府部门、行业协会相关方的沟通，包括会议参与、活动组织等，承担对外公文及材料的撰写工作。\n2.熟悉网络文化领域的相关政策，熟练运用AI工具协助做好研判分析，寻找创造双赢合作机会，为业务发展提供助力。\n3.支持公司相关业务板块的需求，获取更多资源和正向合作机会，及时化解相关危机，排查业务运行过程中的风险。","requirements":"1.本科及以上学历，5年以上工作经验。\n2.具备较强的政治敏锐性和政策敏感性，具备良好的沟通表达能力。\n3.工作具备主动性，善于思考总结和使用相关AI产品工具，能适应互联网创新环境。","description":"部门介绍\n公司事务平台负责构建公司的公共战略体系，助力业务可持续发展及公司对外影响力的提升。通过内外部风险管理，确保公司合规发展；通过深耕公共战略，推动内外良好沟通，连接公司发展与社会期待，助力业务高质量发展；通过管理社会责任议题、公益投入等，助力公司创造更多社会价值；同时为公司提供行政、采购等基础服务。我们坚持“懂业务、拿结果，勇担当、善协同，不唯上、只唯真”的工作理念，期待具有公共战略素养、了解公司治理逻辑的你加入！\n\n岗位职责\n1.日常与网信等政府部门、行业协会相关方的沟通，包括会议参与、活动组织等，承担对外公文及材料的撰写工作。\n2.熟悉网络文化领域的相关政策，熟练运用AI工具协助做好研判分析，寻找创造双赢合作机会，为业务发展提供助力。\n3.支持公司相关业务板块的需求，获取更多资源和正向合作机会，及时化解相关危机，排查业务运行过程中的风险。\n\n岗位基本要求\n1.本科及以上学历，5年以上工作经验。\n2.具备较强的政治敏锐性和政策敏感性，具备良好的沟通表达能力。\n3.工作具备主动性，善于思考总结和使用相关AI产品工具，能适应互联网创新环境。\n\n岗位亮点\n1.大平台锻炼机会：美团拥有庞大的用户基础和广泛的业务覆盖，为员工提供了在大平台上锻炼和成长的机会。员工可以接触到最前沿的技术和业务模式，参与大型项目，积累宝贵的经验。\n2.成长型组织：美团注重员工的成长和发展，提供多样化的培训和学习机会。员工可以参与内部培训课程、在线学习平台、跨部门交流等活动，不断提升自己的专业技能和综合素质。同时，公司还鼓励员工跨部门合作，拓展视野和思维方式。\n3.共同参与和见证团队发展：美团正处于快速发展阶段，员工可以亲身参与并见证公司的成长和变革。这种参与感不仅能让员工感受到自己的价值和贡献，还能激发员工的归属感和自豪感。\n4.创新氛围浓厚：公司鼓励员工勇于尝试、敢于创新，积极探索使用AI，为公司的未来发展贡献智慧和力量。在这种创新氛围中，员工可以不断挑战自我、超越自我，实现个人价值和企业价值的双赢。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4674117477","sourceKey":"meituan_social","company":"美团","title":"下沉市场-校园业务运营","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4674117477&jobShareType=1","duty":"1.负责校园合作商运营，结合市场竞争及业务盈亏表现，制定合作政策及运营政策；搭建商管理机制，推动合作商完成校园开拓和运营，通过数据监控和分析，优化过程管理质量。\n\n2.提升校园业务开展系统化能力，通过CRM产品、销售工具等完成对高校经营基本要素（学校、食堂、档口、履约路线等）的线上化运营，结合流程建设等改善运营效率。\n\n3.挖掘并培育下沉市场校内外新增长机会，包含校园团购、校园跑腿等多模式尝试及培育，并协作其他团队实现相应资源/政策落地。","requirements":"1.本科及以上学历，有4年以上业务运营经验，目标感、自驱力强。\n\n2.具备优秀的逻辑思维和沟通表达能力，善于跨团队协同，具备中大型项目管理经验者优先。\n\n3.具备数据SQL使用和分析和复盘。","description":"部门介绍\n美团核心本地商业-下沉市场发展部于2015年成立，通过招募优质的合作商伙伴并对其业务经营能力、组织能力等赋能，以期为下沉城市提供一站式的本地生活服务。\n下沉市场发展部的业务场景涵盖了外卖餐饮、团购、拼好饭、闪购、医药等多元化的生活服务领域，同时搭建了一套稳定、高效的即时配送网络，为更多本地用户提供品质化、多样化、便捷高效的生活服务体验，为当地商户提供数字化发展机遇、提升数字化水平，为社会创造更多的就地就业机会。\n截至2024年6月，下沉市场发展部已开拓全国4000+县区市，帮助百万商户实现本地生活服务数字化，日订单量突破千万，为数十万名骑手提供就业岗位，让本地生活服务逐渐成长为地方新基建，实现美团“帮助大家吃得更好，生活更好”的使命！\n\n岗位职责\n1.负责校园合作商运营，结合市场竞争及业务盈亏表现，制定合作政策及运营政策；搭建商管理机制，推动合作商完成校园开拓和运营，通过数据监控和分析，优化过程管理质量。\n\n2.提升校园业务开展系统化能力，通过CRM产品、销售工具等完成对高校经营基本要素（学校、食堂、档口、履约路线等）的线上化运营，结合流程建设等改善运营效率。\n\n3.挖掘并培育下沉市场校内外新增长机会，包含校园团购、校园跑腿等多模式尝试及培育，并协作其他团队实现相应资源/政策落地。\n\n岗位基本要求\n1.本科及以上学历，有4年以上业务运营经验，目标感、自驱力强。\n\n2.具备优秀的逻辑思维和沟通表达能力，善于跨团队协同，具备中大型项目管理经验者优先。\n\n3.具备数据SQL使用和分析和复盘。\n\n具备以下条件优先\n具备校园业务经验、以及服务商、合作商运营经验者优先。\n\n岗位亮点\n外卖核心业务，平台大，视角广，有足够的成长空间。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4717145056","sourceKey":"meituan_social","company":"美团","title":"社群运营高级专家","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4717145056&jobShareType=1","duty":"1、社群体系策略制定：制定平台深入城市的社群运营的策略，包括自营社群定位、外部社群合作、以及两者之间的协同机制；基于市场趋势、用户洞察和竞争格局，制定中长期社群运营发展策略\n2、用户行为变化设计：基于用户洞察，设计通过社群运营引发用户从认知到行动再到传播的全链路行为变化路径（C的变化）；建立用户分层运营机制，实现精准触达与高效转化\n3、自营社群矩阵搭建：建立多层次、多维度的自营社群矩阵，包括社群搭建、内容运营、活动策划、用户管理等全链路流程\n4、外部社群生态建设：建立和维护与各类外部社群的合作关系；探索多样化的合作模式；建立外部社群渠道的价值评估体系，优化资源配置，提升合作ROI\n5、数据驱动优化：建立社群运营的指标体系，通过数据分析持续优化社群运营效率和效果；运用AI技术提升社群运营效率，探索社群渠道的AI化管理","requirements":"1、本科及以上学历，5年以上用户运营/社群运营相关经验，其中至少3年团队管理的经验\n2、有互联网平台、本地生活、社交产品等相关行业背景，对社群经济有深刻理解；具备从0到1搭建社群运营体系的经验，有成功的社群增长案例\n3、具备极强的策略思维能力，能够从宏观视角制定业务策略，并拆解为可执行的行动方案；面对复杂业务场景，能够快速识别核心矛盾，做出有价值的策略选择\n4、具备优秀的数据分析能力，能够通过数据驱动业务决策；建立数据指标体系，持续追踪和优化运营效果\n5、具备出色的团队搭建和人才培养能力，能够建立清晰的人才梯队，激发团队潜能；具备优秀的跨部门协同能力，能够推动复杂项目高效落地\n6、在行业有一定影响力，有行业演讲、文章发表等经历者优先；对本地生活行业有深刻洞察，能够代表行业发声","description":"部门介绍\n大众点评作为国内重要的本地生活消费决策参考平台，多年来深耕本地生活消费领域，深受广大用户的信任和喜爱。我们的业务覆盖了吃喝玩乐游购娱等生活场景，通过极具辨识度和公信力的”星级“和”评价“产品，为数亿用户提供了全面、可信的消费决策依据。为更好满足用户探索城市的需求，大众点评在原有星级和评价的基础上，以信息流产品形式，助力用户发现更多好去处。大量优秀年轻同学的加入，为我们的团队注入了澎湃活力。我们相信，真实的生活是不可替代的，真实的感受是值得记录的，真实的美好是要被看到的。希望优秀的你能和我们一起，帮助广大用户在大众点评上发现更多好去处，找到属于自己的人间烟火气，共创美好生活。\n\n岗位职责\n1、社群体系策略制定：制定平台深入城市的社群运营的策略，包括自营社群定位、外部社群合作、以及两者之间的协同机制；基于市场趋势、用户洞察和竞争格局，制定中长期社群运营发展策略\n2、用户行为变化设计：基于用户洞察，设计通过社群运营引发用户从认知到行动再到传播的全链路行为变化路径（C的变化）；建立用户分层运营机制，实现精准触达与高效转化\n3、自营社群矩阵搭建：建立多层次、多维度的自营社群矩阵，包括社群搭建、内容运营、活动策划、用户管理等全链路流程\n4、外部社群生态建设：建立和维护与各类外部社群的合作关系；探索多样化的合作模式；建立外部社群渠道的价值评估体系，优化资源配置，提升合作ROI\n5、数据驱动优化：建立社群运营的指标体系，通过数据分析持续优化社群运营效率和效果；运用AI技术提升社群运营效率，探索社群渠道的AI化管理\n\n岗位基本要求\n1、本科及以上学历，5年以上用户运营/社群运营相关经验，其中至少3年团队管理的经验\n2、有互联网平台、本地生活、社交产品等相关行业背景，对社群经济有深刻理解；具备从0到1搭建社群运营体系的经验，有成功的社群增长案例\n3、具备极强的策略思维能力，能够从宏观视角制定业务策略，并拆解为可执行的行动方案；面对复杂业务场景，能够快速识别核心矛盾，做出有价值的策略选择\n4、具备优秀的数据分析能力，能够通过数据驱动业务决策；建立数据指标体系，持续追踪和优化运营效果\n5、具备出色的团队搭建和人才培养能力，能够建立清晰的人才梯队，激发团队潜能；具备优秀的跨部门协同能力，能够推动复杂项目高效落地\n6、在行业有一定影响力，有行业演讲、文章发表等经历者优先；对本地生活行业有深刻洞察，能够代表行业发声\n\n具备以下条件优先\n有独立负责社群0-1搭建或品牌会员运营经验的优先\n\n岗位亮点\n1、业务持续高速增长，核心战略方向，成长空间充足；理解全国城市不同用户特征，影响亿万用户的本地生活体验\n2、岗位视角全面，横跨自营社群与外部社群生态，是深度理解社群经济运营的较全面视角之一\n3、团队氛围融洽，业务节奏快，适合有进取心、有想法、能落地的运营leader；与优秀的人一起做有挑战的事","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4716968935","sourceKey":"meituan_social","company":"美团","title":"热点运营高级专家","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4716968935&jobShareType=1","duty":"1、热点运营顶层设计：制定热点运营的整体策略，形成系统化的热点运营方法论；建立热点标签生产及内容关联、热点内容生产与分发、重点场景完整解决方案的三层策略体系\n2、热点内容生产与运营：建立热点标签与存量内容的高效关联机制，实现热点的快速内容化；建立规模化的热点内容生产模式，包括常态热点和非常态热点、线上线下联动的差异化承接策略。\n3、市场与行业影响力突破：灵活调度资源形成多样性的合作机制，通过热点运营持续扩大平台在本地生活领域的影响力，建立平台在热点响应方面的行业标杆地位；\n4、团队搭建与资源整合：搭建高效热点运营团队，培养具备热点敏感度和执行力的专业人才；整合外部合作伙伴资源，包括兼职团队、地推渠道等，建立灵活的外部协作网络","requirements":"1、本科及以上学历，5年以上市场营销、品牌运营或热点营销相关经验，其中至少3年独立项目负责人或管理经验\n2、有互联网平台、本地生活、内容平台等相关行业背景，对热点营销有深刻理解和实操经验；具备极强的热点敏感度和判断力，能够快速识别有价值的社会热点并进行有效承接\n3、有成功操盘大型热点营销活动的经验，有从热点发掘到效果放大的完整案例；具备创新思维，能够不断探索热点运营的新模式、新路径\n4、具备完整的从策略到落地的全链路操盘能力，能够独立制定并落地热点运营策略，对业务结果负责；熟悉搜索承接、内容分发等多端触达逻辑\n5、具备较强的策略思维、数据分析能力和跨团队协作能力，能够通过数据发现问题、验证策略并持续优化；具备优秀的团队搭建和人才培养能力\n6、在行业有一定影响力，有行业演讲、文章发表等经历者优先；能够代表行业发声，参与行业对话","description":"部门介绍\n大众点评作为国内重要的本地生活消费决策参考平台，多年来深耕本地生活消费领域，深受广大用户的信任和喜爱。我们的业务覆盖了吃喝玩乐游购娱等生活场景，通过极具辨识度和公信力的”星级“和”评价“产品，为数亿用户提供了全面、可信的消费决策依据。为更好满足用户探索城市的需求，大众点评在原有星级和评价的基础上，以信息流产品形式，助力用户发现更多好去处。大量优秀年轻同学的加入，为我们的团队注入了澎湃活力。我们相信，真实的生活是不可替代的，真实的感受是值得记录的，真实的美好是要被看到的。希望优秀的你能和我们一起，帮助广大用户在大众点评上发现更多好去处，找到属于自己的人间烟火气，共创美好生活。\n\n岗位职责\n1、热点运营顶层设计：制定热点运营的整体策略，形成系统化的热点运营方法论；建立热点标签生产及内容关联、热点内容生产与分发、重点场景完整解决方案的三层策略体系\n2、热点内容生产与运营：建立热点标签与存量内容的高效关联机制，实现热点的快速内容化；建立规模化的热点内容生产模式，包括常态热点和非常态热点、线上线下联动的差异化承接策略。\n3、市场与行业影响力突破：灵活调度资源形成多样性的合作机制，通过热点运营持续扩大平台在本地生活领域的影响力，建立平台在热点响应方面的行业标杆地位；\n4、团队搭建与资源整合：搭建高效热点运营团队，培养具备热点敏感度和执行力的专业人才；整合外部合作伙伴资源，包括兼职团队、地推渠道等，建立灵活的外部协作网络\n\n岗位基本要求\n1、本科及以上学历，5年以上市场营销、品牌运营或热点营销相关经验，其中至少3年独立项目负责人或管理经验\n2、有互联网平台、本地生活、内容平台等相关行业背景，对热点营销有深刻理解和实操经验；具备极强的热点敏感度和判断力，能够快速识别有价值的社会热点并进行有效承接\n3、有成功操盘大型热点营销活动的经验，有从热点发掘到效果放大的完整案例；具备创新思维，能够不断探索热点运营的新模式、新路径\n4、具备完整的从策略到落地的全链路操盘能力，能够独立制定并落地热点运营策略，对业务结果负责；熟悉搜索承接、内容分发等多端触达逻辑\n5、具备较强的策略思维、数据分析能力和跨团队协作能力，能够通过数据发现问题、验证策略并持续优化；具备优秀的团队搭建和人才培养能力\n6、在行业有一定影响力，有行业演讲、文章发表等经历者优先；能够代表行业发声，参与行业对话\n\n岗位亮点\n1、业务持续高速增长，核心战略方向，成长空间充足；理解全国城市不同用户特征，影响亿万用户的本地生活体验\n2、岗位视角全面，横跨热点识别、内容生产、线上线下联动等多个维度，是深度理解热点营销运营的较全面视角之一\n3、团队氛围融洽，业务节奏快，适合有进取心、有想法、能落地的运营leader；有机会打造行业级的热点运营方法论","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4716978871","sourceKey":"meituan_social","company":"美团","title":"会员运营高级专家","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4716978871&jobShareType=1","duty":"1、会员权益体系设计：结合平台会员结构进行权益体系顶层策略指定，通过有效的权益设计和运营手段，激发会员的活跃度和忠诚度\n2、品牌与平台会员体系协同：兼顾品牌会员体系与平台会员体系的运营需求，实现两者之间的协同效应。能打造行业内有影响力的标杆案例并沉淀系统方法论\n3、AI技术赋能会员运营：探索AI技术在会员运营中的应用，通过技术手段提升会员运营的效率和效果；将AI能力融入日常会员运营体系，推动会员运营的智能化升级\n4、数据驱动与效果评估：建立完善会员运营的数据指标体系，包括会员规模、活跃度、留存率、LTV等核心指标；建立会员价值的评估模型，量化会员运营对公司业务的贡献，为资源投入决策提供依据\n5、团队搭建与人才培养：搭建高效会员运营团队（10-15人），培养具备会员策略思维和运营能力的专业人才；与品牌方、产品团队、技术团队等高效协同，推动会员运营策略的落地执行","requirements":"1、本科及以上学历，8年以上用户运营、会员运营或CRM相关经验，其中至少3年管理经验\n2、有互联网平台、零售、餐饮等相关行业的会员运营经验，对会员经济有深刻理解；有从0到1搭建会员体系或重构会员权益体系的成功经验，对会员权益设计有深刻洞察\n3、有连锁品牌会员运营经验，了解品牌会员体系与平台会员体系的差异和协同点；有成功操盘大型会员运营项目的经验，能够将创意构想转化为可执行、可衡量的增长方案\n4、具备优秀的方法论沉淀和输出能力，能够将实战经验转化为可复用的知识体系；对AI工具在运营场景有实践认知，能将AI能力融入日常运营体系\n5、具备较强的策略思维、数据分析能力和跨团队协作能力，能够通过数据驱动业务决策；具备优秀的团队搭建和人才培养能力","description":"部门介绍\n大众点评作为国内重要的本地生活消费决策参考平台，多年来深耕本地生活消费领域，深受广大用户的信任和喜爱。我们的业务覆盖了吃喝玩乐游购娱等生活场景，通过极具辨识度和公信力的”星级“和”评价“产品，为数亿用户提供了全面、可信的消费决策依据。为更好满足用户探索城市的需求，大众点评在原有星级和评价的基础上，以信息流产品形式，助力用户发现更多好去处。大量优秀年轻同学的加入，为我们的团队注入了澎湃活力。我们相信，真实的生活是不可替代的，真实的感受是值得记录的，真实的美好是要被看到的。希望优秀的你能和我们一起，帮助广大用户在大众点评上发现更多好去处，找到属于自己的人间烟火气，共创美好生活。\n\n岗位职责\n1、会员权益体系设计：结合平台会员结构进行权益体系顶层策略指定，通过有效的权益设计和运营手段，激发会员的活跃度和忠诚度\n2、品牌与平台会员体系协同：兼顾品牌会员体系与平台会员体系的运营需求，实现两者之间的协同效应。能打造行业内有影响力的标杆案例并沉淀系统方法论\n3、AI技术赋能会员运营：探索AI技术在会员运营中的应用，通过技术手段提升会员运营的效率和效果；将AI能力融入日常会员运营体系，推动会员运营的智能化升级\n4、数据驱动与效果评估：建立完善会员运营的数据指标体系，包括会员规模、活跃度、留存率、LTV等核心指标；建立会员价值的评估模型，量化会员运营对公司业务的贡献，为资源投入决策提供依据\n5、团队搭建与人才培养：搭建高效会员运营团队（10-15人），培养具备会员策略思维和运营能力的专业人才；与品牌方、产品团队、技术团队等高效协同，推动会员运营策略的落地执行\n\n岗位基本要求\n1、本科及以上学历，8年以上用户运营、会员运营或CRM相关经验，其中至少3年管理经验\n2、有互联网平台、零售、餐饮等相关行业的会员运营经验，对会员经济有深刻理解；有从0到1搭建会员体系或重构会员权益体系的成功经验，对会员权益设计有深刻洞察\n3、有连锁品牌会员运营经验，了解品牌会员体系与平台会员体系的差异和协同点；有成功操盘大型会员运营项目的经验，能够将创意构想转化为可执行、可衡量的增长方案\n4、具备优秀的方法论沉淀和输出能力，能够将实战经验转化为可复用的知识体系；对AI工具在运营场景有实践认知，能将AI能力融入日常运营体系\n5、具备较强的策略思维、数据分析能力和跨团队协作能力，能够通过数据驱动业务决策；具备优秀的团队搭建和人才培养能力\n\n具备以下条件优先\n具备出色的外部影响力，有行业演讲、文章发表等经历者优先；能够代表行业发声，提升公司在会员运营领域的品牌影响力\n\n岗位亮点\n1、业务持续高速增长，核心战略方向，成长空间充足；理解全国城市不同用户特征，影响亿万用户的本地生活体验\n2、岗位视角全面，横跨品牌会员与平台会员体系，是深度理解会员经济运营的较全面视角之一；有机会打造行业级的会员运营方法论\n3、团队氛围融洽，业务节奏快，适合有进取心、有想法、能落地的运营leader；与优秀的人一起做有挑战的事，推动AI技术在会员运营中的创新应用","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4716143043","sourceKey":"meituan_social","company":"美团","title":"内容运营高级专家","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4716143043&jobShareType=1","duty":"1、内容运营体系设计：制定平台城市化内容运营的整体策略，包括内容定位、内容标准、内容生态等核心框架；\n2、内容生产能力/流程建设：规划和建设组织的内容生产能力，包括内部团队、外部合作、UGC激励等多种生产模式；建立内容质量标准体系，包括内容完整性、鲜活度、可信度等维度的标准\n3、内容分发模型推动：推动内容分发策略迭代，通过搜索、推荐、活动等多渠道实现内容的有效触达；通过活动策划、用户激励等手段促进内容消费，提升内容的二次传播和转化效果\n4、团队搭建与人才培养：搭建高效的内容运营团队，培养具备内容策划、生产和分发能力的专业人才；与产品、技术、市场、社群等部门高效协同，推动内容运营策略的落地执行","requirements":"1、本科及以上学历，8年以上内容运营、内容营销或内容产品相关经验，其中至少3年管理经验\n2、有互联网平台、内容平台、本地生活等相关行业背景，对内容生态有深刻理解；具备优秀的内容策划能力，有从0到1搭建内容运营体系的经验\n3、对平台内容生态有深入了解，能够制定符合平台特性的内容策略；熟悉搜索承接、推荐分发等多端触达逻辑\n4、具备优秀的数据分析能力，能够通过数据驱动内容运营决策；建立内容运营效果评估体系，持续追踪和优化运营效果\n5、具备出色的团队搭建和人才培养能力，能够建立清晰的人才梯队，激发团队潜能；具备优秀的跨部门协同能力，能够推动复杂项目高效落地","description":"部门介绍\n大众点评作为国内重要的本地生活消费决策参考平台，多年来深耕本地生活消费领域，深受广大用户的信任和喜爱。我们的业务覆盖了吃喝玩乐游购娱等生活场景，通过极具辨识度和公信力的”星级“和”评价“产品，为数亿用户提供了全面、可信的消费决策依据。为更好满足用户探索城市的需求，大众点评在原有星级和评价的基础上，以信息流产品形式，助力用户发现更多好去处。大量优秀年轻同学的加入，为我们的团队注入了澎湃活力。我们相信，真实的生活是不可替代的，真实的感受是值得记录的，真实的美好是要被看到的。希望优秀的你能和我们一起，帮助广大用户在大众点评上发现更多好去处，找到属于自己的人间烟火气，共创美好生活。\n\n岗位职责\n1、内容运营体系设计：制定平台城市化内容运营的整体策略，包括内容定位、内容标准、内容生态等核心框架；\n2、内容生产能力/流程建设：规划和建设组织的内容生产能力，包括内部团队、外部合作、UGC激励等多种生产模式；建立内容质量标准体系，包括内容完整性、鲜活度、可信度等维度的标准\n3、内容分发模型推动：推动内容分发策略迭代，通过搜索、推荐、活动等多渠道实现内容的有效触达；通过活动策划、用户激励等手段促进内容消费，提升内容的二次传播和转化效果\n4、团队搭建与人才培养：搭建高效的内容运营团队，培养具备内容策划、生产和分发能力的专业人才；与产品、技术、市场、社群等部门高效协同，推动内容运营策略的落地执行\n\n岗位基本要求\n1、本科及以上学历，8年以上内容运营、内容营销或内容产品相关经验，其中至少3年管理经验\n2、有互联网平台、内容平台、本地生活等相关行业背景，对内容生态有深刻理解；具备优秀的内容策划能力，有从0到1搭建内容运营体系的经验\n3、对平台内容生态有深入了解，能够制定符合平台特性的内容策略；熟悉搜索承接、推荐分发等多端触达逻辑\n4、具备优秀的数据分析能力，能够通过数据驱动内容运营决策；建立内容运营效果评估体系，持续追踪和优化运营效果\n5、具备出色的团队搭建和人才培养能力，能够建立清晰的人才梯队，激发团队潜能；具备优秀的跨部门协同能力，能够推动复杂项目高效落地\n\n具备以下条件优先\n在行业有一定影响力，有行业演讲、文章发表等经历者优先；对内容运营领域有深刻洞察，能够代表行业发声\n\n岗位亮点\n1、业务持续高速增长，核心战略方向，成长空间充足；理解全国城市不同用户特征，影响亿万用户的本地生活体验\n2、岗位视角全面，横跨内容生产、内容分发、搜索承接等多个维度，是深度理解内容运营的较全面视角之一；有机会探索AI技术在内容生产中的创新应用\n3、团队氛围融洽，业务节奏快，适合有进取心、有想法、能落地的运营leader；与优秀的人一起做有挑战的事，打造行业级的内容运营方法论","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4715510665","sourceKey":"meituan_social","company":"美团","title":"商业分析师","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4715510665&jobShareType=1","duty":"1.协同公信力生态和星级评价业务团队一起深入分析研究业务逻辑，通过数据帮助业务制定发展方向和策略；\n2.数据洞察诊断分析，通过数据发现业务问题，并进行专题分析，输出结论和建议；\n3.从App整体视角和项目视角，提供策略制定、分析体系搭建、监控体系设计及监控分析，评估分析的闭环，为业务执行提供全方面的分析建议，并积极推进策略落地；\n4.关注外部行业和公司变化，编写研究报告，为平台提供发展建议；","requirements":"1.有行业视角和具体业务分析项目落地经验；\n2.具有框架式分析能力，较好的逻辑思维能力；\n3.沟通能力较好，积极主动，具备自驱力和成长意愿；\n4.具有优秀的商业分析技能，熟练掌握SQL等数据处理和分析工具，具备一定的算法建模能力","description":"部门介绍\n大众点评作为国内重要的本地生活消费决策参考平台，多年来深耕本地生活消费领域，深受广大用户的信任和喜爱。我们的业务覆盖了吃喝玩乐游购娱等生活场景，通过极具辨识度和公信力的”星级“和”评价“产品，为数亿用户提供了全面、可信的消费决策依据。为更好满足用户探索城市的需求，大众点评在原有星级和评价的基础上，以信息流产品形式，助力用户发现更多好去处。大量优秀年轻同学的加入，为我们的团队注入了澎湃活力。我们相信，真实的生活是不可替代的，真实的感受是值得记录的，真实的美好是要被看到的。希望优秀的你能和我们一起，帮助广大用户在大众点评上发现更多好去处，找到属于自己的人间烟火气，共创美好生活。\n\n岗位职责\n1.协同公信力生态和星级评价业务团队一起深入分析研究业务逻辑，通过数据帮助业务制定发展方向和策略；\n2.数据洞察诊断分析，通过数据发现业务问题，并进行专题分析，输出结论和建议；\n3.从App整体视角和项目视角，提供策略制定、分析体系搭建、监控体系设计及监控分析，评估分析的闭环，为业务执行提供全方面的分析建议，并积极推进策略落地；\n4.关注外部行业和公司变化，编写研究报告，为平台提供发展建议；\n\n岗位基本要求\n1.有行业视角和具体业务分析项目落地经验；\n2.具有框架式分析能力，较好的逻辑思维能力；\n3.沟通能力较好，积极主动，具备自驱力和成长意愿；\n4.具有优秀的商业分析技能，熟练掌握SQL等数据处理和分析工具，具备一定的算法建模能力\n\n具备以下条件优先\n统计学、计算机、经济学相关专业优先，有内容生态、AI分析应用落地相关数据分析经验者\n具备所有者精神（Ownership）、学习并好奇（Learn and Be Curious）、坚持高标准（Insist on the Highest Standards）、应对不确定性的能力(Deal with Ambiguity）等价值观者优先\n\n岗位亮点\n我们有开放、直接的工作氛围，以逻辑和事实说话，而不是岗位级别和层级。我们尊重知识和常识，努力以业务视角思考自身工作。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4592075220","sourceKey":"meituan_social","company":"美团","title":"城市经理/区域经理","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4592075220&jobShareType=1","duty":"1. 负责区域内快驴业务的市场开拓与销售策略制定，推动业务规模持续增长。  \n2. 管理并带领销售团队，优化团队结构，提升团队执行力与业务转化效率。  \n3. 深度挖掘本地餐饮商户需求，拓展重点客户资源，建立并维护长期稳定的合作关系。  \n4. 协同总部运营、供应链及物流团队，推动区域业务高效落地，确保业绩目标达成。","requirements":"1. 大学专科及以上学历，市场营销、供应链管理或相关专业优先。  \n2. 具备7年以上B2B销售或业务开发经验，其中至少3年团队管理经验，有餐饮供应链或快消品行业背景者优先。  \n3. 熟悉北京市餐饮市场生态，具备较强的商户拓展能力与客户关系管理能力。  \n4. 具备优秀的领导力和数据分析能力，能够驱动团队实现高绩效目标。","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1. 负责区域内快驴业务的市场开拓与销售策略制定，推动业务规模持续增长。  \n2. 管理并带领销售团队，优化团队结构，提升团队执行力与业务转化效率。  \n3. 深度挖掘本地餐饮商户需求，拓展重点客户资源，建立并维护长期稳定的合作关系。  \n4. 协同总部运营、供应链及物流团队，推动区域业务高效落地，确保业绩目标达成。\n\n岗位基本要求\n1. 大学专科及以上学历，市场营销、供应链管理或相关专业优先。  \n2. 具备7年以上B2B销售或业务开发经验，其中至少3年团队管理经验，有餐饮供应链或快消品行业背景者优先。  \n3. 熟悉北京市餐饮市场生态，具备较强的商户拓展能力与客户关系管理能力。  \n4. 具备优秀的领导力和数据分析能力，能够驱动团队实现高绩效目标。\n\n岗位亮点\n1. 深度参与快驴核心业务，具备高成长性与战略影响力。  \n2. 深耕本地餐饮供应链市场，直面商户痛点，推动业务创新与突破。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4698476095","sourceKey":"meituan_social","company":"美团","title":"闪购-歪马-督导经理（内蒙古/河南/河北）","city":"石家庄市/呼和浩特市/郑州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4698476095&jobShareType=1","duty":"1.协助合作商组建和管理团队，辅导和监督合作商做好团队管理工作；\n2.对合作商各级人员形成有效赋能，在履约配送、推广获客、商品运营、门店经营等模块实现标准化管理、业绩达成和盈利管理；\n3.稽核门店在仓内管理履约体验地推获客标准化落地，提升各个环节效率；\n4.结合商管政策做上传下达，做好门店全生命周期管控，达成总部目标；\n5.收集行业和竞争信息，做好战场动态传达。\n6.负责管理省内各城市商及门店","requirements":"1.本科及以上学历，市场营销、商务管理或相关专业优先考虑。\n2.具备丰富的渠道管理经验，熟悉渠道销售流程和渠道拓展方法。\n3.具备较强的市场分析能力和数据分析能力，能够准确判断市场需求和销售趋势。\n4.具备良好的沟通能力和团队合作精神，能够与不同部门和合作伙伴进行有效沟通和协调。\n5.具备较强的计划和执行能力，能够制定并执行有效的渠道销售策略。\n6.具备较强问题解决能力，保持良好的工作状态。","description":"部门介绍\n美团闪购是美团旗下的即时零售平台，依托即时配送能力，连接本地零售供给，满足消费者30分钟万物到家的即时需求。美团闪购涵盖超市便利、食材、水果、鲜花绿植、休闲零食、酒水饮料、数码家电、美妆个护、母婴玩具、日用百货、服饰鞋帽、宠物等诸多品类，业务覆盖全国近3,000个县市区旗，每日百万级在岗骑手，以高效的配送、丰富的品类和广泛的覆盖，为美团数亿用户带来便捷的生活体验，积极助力实体零售线上化转型，提升本地商业活力。\n\n岗位职责\n1.协助合作商组建和管理团队，辅导和监督合作商做好团队管理工作；\n2.对合作商各级人员形成有效赋能，在履约配送、推广获客、商品运营、门店经营等模块实现标准化管理、业绩达成和盈利管理；\n3.稽核门店在仓内管理履约体验地推获客标准化落地，提升各个环节效率；\n4.结合商管政策做上传下达，做好门店全生命周期管控，达成总部目标；\n5.收集行业和竞争信息，做好战场动态传达。\n6.负责管理省内各城市商及门店\n\n岗位基本要求\n1.本科及以上学历，市场营销、商务管理或相关专业优先考虑。\n2.具备丰富的渠道管理经验，熟悉渠道销售流程和渠道拓展方法。\n3.具备较强的市场分析能力和数据分析能力，能够准确判断市场需求和销售趋势。\n4.具备良好的沟通能力和团队合作精神，能够与不同部门和合作伙伴进行有效沟通和协调。\n5.具备较强的计划和执行能力，能够制定并执行有效的渠道销售策略。\n6.具备较强问题解决能力，保持良好的工作状态。\n\n具备以下条件优先\n1.有加盟/酒水连锁门店管理经验者优先；\n2.有前置仓行业经验者优先。\n\n岗位亮点\n1.能够接触到全面的渠道管理工作，为个人职业发展提供广阔的空间。\n2.可以与各类合作伙伴进行广泛的合作，提升沟通和协调能力。\n3.可以参与制定并执行渠道营销方案，提升销售业绩和市场份额。\n4.可以通过分析市场动态和销售数据，提供有针对性的销售策略和决策支持。\n5.可以在团队协作中提升自己的团队合作和领导能力。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4661385969","sourceKey":"meituan_social","company":"美团","title":"AI安全专家","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4661385969&jobShareType=1","duty":"1、AI资产梳理与风险分级：识别企业内部AI资产（如：AI Agent、MCP Server、RAG应用等），梳理其数据访问范围与权限边界，建立资产清单和风险分级机制。\n2、AI行为风险识别：分析AI Agent在工具调用、文件访问、命令执行、身份权限使用等环节的行为风险，识别越权操作、敏感数据外传、异常自动化执行等问题。\n3、AI安全检测与响应：建立AI安全告警分级、调查和响应流程，协同公司内部系统实现高风险访问阻断、Agent暂停、Token回收等响应机制。\n4、AI使用安全治理：负责三方模型、Al Agent场景的日常安全管控与风险治理。","requirements":"1，具备3年以上信息安全经验，具备公司级安全产品设计或开发经验。\n2，具备AI 安全相关经验，拥有成功的AI安全落地案例。","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n1、AI资产梳理与风险分级：识别企业内部AI资产（如：AI Agent、MCP Server、RAG应用等），梳理其数据访问范围与权限边界，建立资产清单和风险分级机制。\n2、AI行为风险识别：分析AI Agent在工具调用、文件访问、命令执行、身份权限使用等环节的行为风险，识别越权操作、敏感数据外传、异常自动化执行等问题。\n3、AI安全检测与响应：建立AI安全告警分级、调查和响应流程，协同公司内部系统实现高风险访问阻断、Agent暂停、Token回收等响应机制。\n4、AI使用安全治理：负责三方模型、Al Agent场景的日常安全管控与风险治理。\n\n岗位基本要求\n1，具备3年以上信息安全经验，具备公司级安全产品设计或开发经验。\n2，具备AI 安全相关经验，拥有成功的AI安全落地案例。\n\n具备以下条件优先\n互联网大厂安全履历\n\n岗位亮点\nAI安全蓝海领域，共建AI安全业界最佳实践","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4677153178","sourceKey":"meituan_social","company":"美团","title":"无人车业务部-嵌入式系统软件BSP工程师(蓝牙/Wi-Fi方向)","city":"北京市/深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4677153178&jobShareType=1","duty":"1、负责车载蓝牙/Wi-Fi 模组的嵌入式驱动开发与 Bring-up，包括芯片选型评估、BSP 层适配、外设驱动（UART/SDIO/PCIe/USB 等）调试及电源管理、低功耗优化。\n2、负责 Bluetooth（Classic + BLE）协议栈的移植、集成与调优，重点覆盖 A2DP、HFP、AVRCP、SPP、LE Audio（LC3/BAP）等核心 Profile，保障车载数据透传、蓝牙遥控器等业务的连接稳定性与低延时。\n3、主导无线连接稳定性与抗干扰方案的研发，深入分析与解决复杂电磁环境下的信号干扰、断连、延时等问题，确保产品在任何场景下的可靠连接。\n4、负责 Wi-Fi 协议栈的适配与性能调优，包括 802.11 协议栈参数优化、TCP/IP 传输性能优化，以及车载场景下的漫游/抗干扰/共存策略设计与验证。\n5、参与无人车的车端分布式系统的迭代设计开发、系统移植和定制，以及深度性能优化，交付高可靠性、高性能的车载分布式系统。\n6、参与车载综合业务网关（TBU）设备的系统软件和底层软件设计与开发，保障系统稳定性与性能。\n7、参与BootLoader、Linux Kernel 配置与裁剪、外设驱动的开发与调试，以及锁、调度、IO 等系统级优化。","requirements":"1、熟悉 Linux 系统（不限于 Ubuntu、Yocto、OpenWRT），OS 功底扎实。具备出色的 C/C++ 软件工程能力，以及良好的软件架构设计能力。\n2、具备 Linux 驱动开发能力，熟悉常见的总线接口（SPI、I2C、UART、PCIe、USB、SDIO 等）。\n3、3年以上嵌入式无线通信软件开发经验，有完整的蓝牙或 Wi-Fi 产品从方案选型到量产的全流程经验。\n4、精通 Bluetooth 协议栈架构，深入理解 BT Classic 与 BLE 双模原理，熟悉 A2DP、HFP、AVRCP、SPP、LE Audio（LC3/BAP）等核心规范及其编解码传输机制。\n5、具备无线抗干扰问题解决能力：熟悉无线电频谱、射频基本原理，有使用频谱分析仪等工具定位无线干扰问题的实际经验。","description":"部门介绍\n无人车业务部成立于2016年，旨在用无人驾驶技术提升物流配送的效率和体验。美团无人车以自研L4级自动驾驶软硬件技术为核心，与美团即时零售业务结合，形成满足公开道路、社区、工业园区等室外全场景下的无人配送整体解决方案。自2020年起，无人车已在北京、深圳等多地进入常态化试运营阶段，在城市复杂场景下提供针对餐饮外卖、生鲜食杂等货物的即时配送服务。2025年，美团无人车又踏上了同城货运的新探索，并在2026年持续扩大运营范围和车队数量，为更多城市带来智能配送服务。\n欢迎加入美团无人车团队，与我们一起用科技推动即时零售再升级！\n\n岗位职责\n1、负责车载蓝牙/Wi-Fi 模组的嵌入式驱动开发与 Bring-up，包括芯片选型评估、BSP 层适配、外设驱动（UART/SDIO/PCIe/USB 等）调试及电源管理、低功耗优化。\n2、负责 Bluetooth（Classic + BLE）协议栈的移植、集成与调优，重点覆盖 A2DP、HFP、AVRCP、SPP、LE Audio（LC3/BAP）等核心 Profile，保障车载数据透传、蓝牙遥控器等业务的连接稳定性与低延时。\n3、主导无线连接稳定性与抗干扰方案的研发，深入分析与解决复杂电磁环境下的信号干扰、断连、延时等问题，确保产品在任何场景下的可靠连接。\n4、负责 Wi-Fi 协议栈的适配与性能调优，包括 802.11 协议栈参数优化、TCP/IP 传输性能优化，以及车载场景下的漫游/抗干扰/共存策略设计与验证。\n5、参与无人车的车端分布式系统的迭代设计开发、系统移植和定制，以及深度性能优化，交付高可靠性、高性能的车载分布式系统。\n6、参与车载综合业务网关（TBU）设备的系统软件和底层软件设计与开发，保障系统稳定性与性能。\n7、参与BootLoader、Linux Kernel 配置与裁剪、外设驱动的开发与调试，以及锁、调度、IO 等系统级优化。\n\n岗位基本要求\n1、熟悉 Linux 系统（不限于 Ubuntu、Yocto、OpenWRT），OS 功底扎实。具备出色的 C/C++ 软件工程能力，以及良好的软件架构设计能力。\n2、具备 Linux 驱动开发能力，熟悉常见的总线接口（SPI、I2C、UART、PCIe、USB、SDIO 等）。\n3、3年以上嵌入式无线通信软件开发经验，有完整的蓝牙或 Wi-Fi 产品从方案选型到量产的全流程经验。\n4、精通 Bluetooth 协议栈架构，深入理解 BT Classic 与 BLE 双模原理，熟悉 A2DP、HFP、AVRCP、SPP、LE Audio（LC3/BAP）等核心规范及其编解码传输机制。\n5、具备无线抗干扰问题解决能力：熟悉无线电频谱、射频基本原理，有使用频谱分析仪等工具定位无线干扰问题的实际经验。\n\n具备以下条件优先\n1、有主流蓝牙/Wi-Fi 芯片平台开发经验者优先，如：Qualcomm（高通）、Realtek（瑞昱）、恒玄 BES、炬芯、Nordic、杰理等。\n2、有车载场景下的蓝牙/Wi-Fi 开发经验，如车载信息娱乐系统（IVI）、T-Box、车载音频（A2DP/HFP/LE Audio）等。\n3、有 TWS 耳机、蓝牙音箱、Wi-Fi 音箱、智能穿戴等消费类无线音频产品量产经验。\n\n岗位亮点\n1、自动驾驶分布式系统平台和智能网联域控制器是无人车配送系统的核心支撑，跨越多个软硬件平台，对技术的广度和深度都有很大的挑战和锻炼。\n\n2、密切参与到最前沿的自动驾驶技术和无人车配送技术的研发迭代，为无人车配送系统的规模化落地运营贡献力量，开阔视野、扩宽个人职业道路。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4491537434","sourceKey":"meituan_social","company":"美团","title":"无人车业务部-公共事务发展经理-华中","city":"北京市/上海市/深圳市/武汉市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4491537434&jobShareType=1","duty":"1、负责目标城市政府关系从0到1搭建，协调地方政府及交通部门，推动自动驾驶运营权、路权及商业化运营资质的获取；借助 AI 工具快速梳理华中各城市政策法规差异，生成定制化政策沟通材料，提升开城节奏；\n2、协调跨部门资源，完成数据上报、平台对接等合规要求；探索 AI 辅助合规文档整理和报送流程标准化，减少重复性行政事务投入；\n3、联动科研院所、车企等合作伙伴，推动常态化运营项目落地；利用 AI 工具进行合作伙伴图谱梳理和优先级分析，提高资源整合效率；\n4、处理属地舆情与问题，平衡政府数据安全要求与企业技术诉求；利用 AI 辅助舆情监测与快速响应材料撰写，提升危机处置速度与质量。","requirements":"1、本科及以上学历，5年以上工作经验。\n2、具备开城经验、有智能网联/新能源汽车领域路权成功案例者优先；在目标区域（华中区）具备成熟政企合作经验优先。\n3、善于沟通和协同合作伙伴推动业务落地，有较强的销售能力，掌握自动驾驶技术基础（如传感器配置、算法合规要求），实现技术与政策语言转化。\n4、有主动使用 AI 工具提升政策研究、文案撰写、信息整合效率的习惯；能识别日常工作中可 AI 化的重复性事务并付诸实践；对 AI 辅助政务工作持开放态度。","description":"部门介绍\n无人车业务部成立于2016年，旨在用无人驾驶技术提升物流配送的效率和体验。美团无人车以自研L4级自动驾驶软硬件技术为核心，与美团即时零售业务结合，形成满足公开道路、社区、工业园区等室外全场景下的无人配送整体解决方案。自2020年起，无人车已在北京、深圳等多地进入常态化试运营阶段，在城市复杂场景下提供针对餐饮外卖、生鲜食杂等货物的即时配送服务。2025年，美团无人车又踏上了同城货运的新探索，并在2026年持续扩大运营范围和车队数量，为更多城市带来智能配送服务。\n欢迎加入美团无人车团队，与我们一起用科技推动即时零售再升级！\n\n岗位职责\n1、负责目标城市政府关系从0到1搭建，协调地方政府及交通部门，推动自动驾驶运营权、路权及商业化运营资质的获取；借助 AI 工具快速梳理华中各城市政策法规差异，生成定制化政策沟通材料，提升开城节奏；\n2、协调跨部门资源，完成数据上报、平台对接等合规要求；探索 AI 辅助合规文档整理和报送流程标准化，减少重复性行政事务投入；\n3、联动科研院所、车企等合作伙伴，推动常态化运营项目落地；利用 AI 工具进行合作伙伴图谱梳理和优先级分析，提高资源整合效率；\n4、处理属地舆情与问题，平衡政府数据安全要求与企业技术诉求；利用 AI 辅助舆情监测与快速响应材料撰写，提升危机处置速度与质量。\n\n岗位基本要求\n1、本科及以上学历，5年以上工作经验。\n2、具备开城经验、有智能网联/新能源汽车领域路权成功案例者优先；在目标区域（华中区）具备成熟政企合作经验优先。\n3、善于沟通和协同合作伙伴推动业务落地，有较强的销售能力，掌握自动驾驶技术基础（如传感器配置、算法合规要求），实现技术与政策语言转化。\n4、有主动使用 AI 工具提升政策研究、文案撰写、信息整合效率的习惯；能识别日常工作中可 AI 化的重复性事务并付诸实践；对 AI 辅助政务工作持开放态度。\n\n岗位亮点\n无人配送是行业最快落地的场景，是美团战略部署，加入美团无人配送将有机会引领整个行业的政策导向、推动整个行业的发展。\nAI 深度赋能岗位：政策文本分析、申报材料生成、知识库管理\n带薪年假、定期体检、五险一金、发展空间大、个人能力提升快。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4695430105","sourceKey":"meituan_social","company":"美团","title":"酒店供应链采购经理（工程物资）","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4695430105&jobShareType=1","duty":"1. 根据业务目标，倒推动作，结合品类策略制定采购策略、价格策略达成结果； \n\n2. 负责供应商筛选、合作洽谈、考察、合同签约等； \n\n3. 负责供应商履约管理与投诉管理，核实投诉与履约问题，督促问题整改、执行处罚； \n\n4. 负责供应商产品/服务质量监督检查，不定期抽检、公示度、督导改进一级处罚执行； \n\n5. 与公司各部门配合，及时处理客户/各部门的反馈、投诉和建议，提高服务满意度。","requirements":"1. 本科及以上学历；\n\n 2. 5以上采购管理经验； \n\n3. 熟悉采购工作流程，拥有较强的产品资源开拓、商务洽谈等能力；\n\n 4. 良好的沟通能力，逻辑清晰，跨部门沟通顺畅，具有良好额团队合作精神，善于学习与思考，执行力强； \n\n5. 过往从事过酒店、地产类等工程采购经验优先；","description":"部门介绍\n美团酒店旅行业务涵盖酒店、民宿、机票、火车票、旅游度假、景点门票等各类住行游品类，通过与产业上下游的深度合作，为用户提供美好的旅游旅行体验。我们积极打造AI友好型组织，使用AI等新技术提升旅游服务的供需匹配效率，更好满足用户个性化、多样化的出游需求。我们持续深耕产业链，用数字化服务助力实体商家高质量经营，探索自有品牌等供给新模式，打造健康的商家生态，保障用户服务体验。为满足用户日益增长的跨境旅行需求，我们将聚焦亚太区域，打造高品质的住宿、交通、游玩等服务矩阵。\n这里有多元的业务布局、持续的成长空间，无论是向往的远方还是眼前的工作，一路都是风景相伴。加入我们，共同为用户创造旅游旅行中的高光时刻！\n\n岗位职责\n1. 根据业务目标，倒推动作，结合品类策略制定采购策略、价格策略达成结果； \n\n2. 负责供应商筛选、合作洽谈、考察、合同签约等； \n\n3. 负责供应商履约管理与投诉管理，核实投诉与履约问题，督促问题整改、执行处罚； \n\n4. 负责供应商产品/服务质量监督检查，不定期抽检、公示度、督导改进一级处罚执行； \n\n5. 与公司各部门配合，及时处理客户/各部门的反馈、投诉和建议，提高服务满意度。\n\n岗位基本要求\n1. 本科及以上学历；\n\n 2. 5以上采购管理经验； \n\n3. 熟悉采购工作流程，拥有较强的产品资源开拓、商务洽谈等能力；\n\n 4. 良好的沟通能力，逻辑清晰，跨部门沟通顺畅，具有良好额团队合作精神，善于学习与思考，执行力强； \n\n5. 过往从事过酒店、地产类等工程采购经验优先；\n\n岗位亮点\n可接触更多品类，拓宽个人对产品的知识点，从采购到管理全链条接触。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3574337886","sourceKey":"meituan_social","company":"美团","title":"酒店连锁品牌合作商管理","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3574337886&jobShareType=1","duty":"1.负责合作商准入准出机制的设计与持续优化，制定资质审核、运营能力评估等标准，确保机制与品牌战略及市场动态匹配。\n2.负责合作全链路流程管理，包括合同起草与签署、费用收取与核算、装修验收及开业支持等关键环节的推进与优化，提升执行效率。\n3.定期监控合作商经营数据（入住率、收益率等），输出运营分析报告，识别经营风险并推动整改落地。\n4.监督合作商品牌标准执行情况，对服务质量、卫生条件、设施维护等不达标项提出整改要求并跟踪闭环。\n5.为合作商提供运营赋能支持，包括收益优化建议、市场推广协助、培训资源对接等，建立高效沟通机制。\n6.建立并维护合作商管理数据库，深入分析合作商数据，为品牌战略调整、区域布局及合作政策优化提供决策支撑。\n7.探索AI工具在合作商管理中的应用，如利用智能模型辅助经营健康度预警、合作商风险评估、数据报告自动生成等，推动管理流程的数字化与智能化升级。","requirements":"1.本科及以上学历，酒店管理、工商管理、财务管理等相关专业优先。\n2.3年以上连锁酒店、连锁餐饮或其他连锁品牌合作商管理经验，熟悉合作商全生命周期管理。\n3.熟悉合作商管理全流程及相关法律法规，具备合同管理、财务核算及数据分析能力，对酒店4.行业运营模式及品牌标准有深刻理解。\n5.出色的沟通协调能力与逻辑思维能力，能推动跨部门协作、梳理复杂业务链条并提出解决方案。\n6.具备风险识别与管理能力，能应对突发问题并妥善解决。\n7.熟练使用办公软件及数据分析工具，善于利用AI工具提升数据处理与日常管理效率者优先。","description":"部门介绍\n美团酒店旅行业务涵盖酒店、民宿、机票、火车票、旅游度假、景点门票等各类住行游品类，通过与产业上下游的深度合作，为用户提供美好的旅游旅行体验。我们积极打造AI友好型组织，使用AI等新技术提升旅游服务的供需匹配效率，更好满足用户个性化、多样化的出游需求。我们持续深耕产业链，用数字化服务助力实体商家高质量经营，探索自有品牌等供给新模式，打造健康的商家生态，保障用户服务体验。为满足用户日益增长的跨境旅行需求，我们将聚焦亚太区域，打造高品质的住宿、交通、游玩等服务矩阵。\n这里有多元的业务布局、持续的成长空间，无论是向往的远方还是眼前的工作，一路都是风景相伴。加入我们，共同为用户创造旅游旅行中的高光时刻！\n\n岗位职责\n1.负责合作商准入准出机制的设计与持续优化，制定资质审核、运营能力评估等标准，确保机制与品牌战略及市场动态匹配。\n2.负责合作全链路流程管理，包括合同起草与签署、费用收取与核算、装修验收及开业支持等关键环节的推进与优化，提升执行效率。\n3.定期监控合作商经营数据（入住率、收益率等），输出运营分析报告，识别经营风险并推动整改落地。\n4.监督合作商品牌标准执行情况，对服务质量、卫生条件、设施维护等不达标项提出整改要求并跟踪闭环。\n5.为合作商提供运营赋能支持，包括收益优化建议、市场推广协助、培训资源对接等，建立高效沟通机制。\n6.建立并维护合作商管理数据库，深入分析合作商数据，为品牌战略调整、区域布局及合作政策优化提供决策支撑。\n7.探索AI工具在合作商管理中的应用，如利用智能模型辅助经营健康度预警、合作商风险评估、数据报告自动生成等，推动管理流程的数字化与智能化升级。\n\n岗位基本要求\n1.本科及以上学历，酒店管理、工商管理、财务管理等相关专业优先。\n2.3年以上连锁酒店、连锁餐饮或其他连锁品牌合作商管理经验，熟悉合作商全生命周期管理。\n3.熟悉合作商管理全流程及相关法律法规，具备合同管理、财务核算及数据分析能力，对酒店4.行业运营模式及品牌标准有深刻理解。\n5.出色的沟通协调能力与逻辑思维能力，能推动跨部门协作、梳理复杂业务链条并提出解决方案。\n6.具备风险识别与管理能力，能应对突发问题并妥善解决。\n7.熟练使用办公软件及数据分析工具，善于利用AI工具提升数据处理与日常管理效率者优先。\n\n岗位亮点\n岗位亮点：\n1.全面参与连锁酒店品牌的合作商全生命周期管理，助力品牌扩张与运营优化。\n2.深度参与合作商准入准出机制及流程优化设计，推动品牌加盟体系的规范化与高效化。\n3.与品牌总部及合作上紧密协作，积累丰富的行业资源与管理经验。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4711376783","sourceKey":"meituan_social","company":"美团","title":"华南干调招商采购","city":"广州市/深圳市/东莞市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4711376783&jobShareType=1","duty":"1. 负责广州/深圳/东莞地区干调类商品的招商工作，拓展优质供应商资源，建立长期合作关系。  \n2. 价格谈判及合同签订，确保商品供应稳定。  \n3. 分析销售数据与市场趋势，优化商品结构，提升品类竞争力 \n4. 协同运营、仓储等团队，保障供应链高效运转。","requirements":"1. 大学专科及以上学历，3年以上商品招商或采购相关工作经验，有干调行业背景优先。  \n2. 熟悉广东市场（广州/深圳/东莞优先），具备一定的供应商资源及渠道拓展能力。  \n3. 具备良好的谈判技巧、数据分析能力和跨部门沟通协调能力。  \n4. 工作积极主动，具备较强的责任心和执行力，能适应一定的工作压力。","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1. 负责广州/深圳/东莞地区干调类商品的招商工作，拓展优质供应商资源，建立长期合作关系。  \n2. 价格谈判及合同签订，确保商品供应稳定。  \n3. 分析销售数据与市场趋势，优化商品结构，提升品类竞争力 \n4. 协同运营、仓储等团队，保障供应链高效运转。\n\n岗位基本要求\n1. 大学专科及以上学历，3年以上商品招商或采购相关工作经验，有干调行业背景优先。  \n2. 熟悉广东市场（广州/深圳/东莞优先），具备一定的供应商资源及渠道拓展能力。  \n3. 具备良好的谈判技巧、数据分析能力和跨部门沟通协调能力。  \n4. 工作积极主动，具备较强的责任心和执行力，能适应一定的工作压力。\n\n具备以下条件优先\n有美菜、优大集工作经验优先\n\n岗位亮点\n1. 深耕本地市场，聚焦干调品类，发展空间广阔。  \n2. 团队氛围开放协作，支持个人成长与能力提升。  \n3. 公司提供完善的培训体系与职业发展通道。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4713261240","sourceKey":"meituan_social","company":"美团","title":"点评玩乐-高级产品专家","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4713261240&jobShareType=1","duty":"1、负责大众点评玩乐业务的用户产品规划与迭代，对点评玩乐的用户规模、转化效率及核心体验负责。结合行业发展趋势与业务特性，明确规划并推动业务增长。\n\n2、主导点评玩乐的核心场景产品设计、体验优化与持续迭代。运用 AI 辅助原型生成工具验证方案可行性，通过数据驱动与用户研究定位关键问题；探索并落地AI产品功能，驱动产品创新与解决方案落地。\n\n3、与运营、研发、算法、商业分析等团队紧密协作，利用 AI 辅助项目管理工具提升跨团队协同效率，高效推动复杂项目，确保业务目标高质量达成。\n\n4、深度洞察用户需求与行业趋势，基于大模型辅助用户调研分析定义差异化产品价值，支撑点评玩乐业务规模增长。","requirements":"1、3年及以上互联网用户产品经验，具备0-1负责复杂产品模块的经验，有O2O、本地生活背景者优先。\n\n2、出色的业务分析与产品规划能力，能在复杂业务环境中保持清晰判断，具备独当一面的项目推进与落地能力。熟悉 AI 辅助产品设计工具链，能将 AI 能力融入日常产品工作流。\n\n3、目标导向，拥有优秀的横向沟通与协同能力，能够有效整合资源，推动跨团队协作。具备数据驱动思维，可以熟练使用 AI 增强型数据分析工具进行指标归因与决策支持。\n\n4、对用户需求有敏锐的洞察力，具备创新思维与解题能力，不拘泥于固有模式。对 AI 技术发展趋势有敏锐感知，能主动探索 AI 在本地生活场景的创新应用，通过产品方案解决本质问题。","description":"部门介绍\n大众点评作为国内重要的本地生活消费决策参考平台，多年来深耕本地生活消费领域，深受广大用户的信任和喜爱。我们的业务覆盖了吃喝玩乐游购娱等生活场景，通过极具辨识度和公信力的”星级“和”评价“产品，为数亿用户提供了全面、可信的消费决策依据。为更好满足用户探索城市的需求，大众点评在原有星级和评价的基础上，以信息流产品形式，助力用户发现更多好去处。大量优秀年轻同学的加入，为我们的团队注入了澎湃活力。我们相信，真实的生活是不可替代的，真实的感受是值得记录的，真实的美好是要被看到的。希望优秀的你能和我们一起，帮助广大用户在大众点评上发现更多好去处，找到属于自己的人间烟火气，共创美好生活。\n\n岗位职责\n1、负责大众点评玩乐业务的用户产品规划与迭代，对点评玩乐的用户规模、转化效率及核心体验负责。结合行业发展趋势与业务特性，明确规划并推动业务增长。\n\n2、主导点评玩乐的核心场景产品设计、体验优化与持续迭代。运用 AI 辅助原型生成工具验证方案可行性，通过数据驱动与用户研究定位关键问题；探索并落地AI产品功能，驱动产品创新与解决方案落地。\n\n3、与运营、研发、算法、商业分析等团队紧密协作，利用 AI 辅助项目管理工具提升跨团队协同效率，高效推动复杂项目，确保业务目标高质量达成。\n\n4、深度洞察用户需求与行业趋势，基于大模型辅助用户调研分析定义差异化产品价值，支撑点评玩乐业务规模增长。\n\n岗位基本要求\n1、3年及以上互联网用户产品经验，具备0-1负责复杂产品模块的经验，有O2O、本地生活背景者优先。\n\n2、出色的业务分析与产品规划能力，能在复杂业务环境中保持清晰判断，具备独当一面的项目推进与落地能力。熟悉 AI 辅助产品设计工具链，能将 AI 能力融入日常产品工作流。\n\n3、目标导向，拥有优秀的横向沟通与协同能力，能够有效整合资源，推动跨团队协作。具备数据驱动思维，可以熟练使用 AI 增强型数据分析工具进行指标归因与决策支持。\n\n4、对用户需求有敏锐的洞察力，具备创新思维与解题能力，不拘泥于固有模式。对 AI 技术发展趋势有敏锐感知，能主动探索 AI 在本地生活场景的创新应用，通过产品方案解决本质问题。\n\n岗位亮点\n1、开放、务实、以用户价值为导向的团队氛围，鼓励创新思考与突破实践，欢迎一起探索AI在本地生活场景的实际落地。\n\n2、具有市场竞争力的薪酬福利、长期激励与完善的职业发展通道。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4713156325","sourceKey":"meituan_social","company":"美团","title":"软硬件法务BP","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4713156325&jobShareType=1","duty":"1.结合业务目标、外部环境变化及法律合规需求，形成对业务有效的法律风险控制方案，如业务全国各区域运营、数据合规、信息安全、广告合规等风险评估；\n2.参与业务的产品设计，评估法律风险和提出法律建议，能运用自己的专业知识通过合同、流程、机制、培训等多种路径，帮助实现业务目标；\n3.支持业务硬件（整车、零部件、电池等）采购、供应链管理、产品研发等项目风险评估，合同支持以及纠纷事件处置；\n4.支持业务各链路发生的争议纠纷、突发事件、行政处罚风险等；\n5.业务政策、立法跟踪、分析解读并向业务输出指导意见；\n6.整合法务团队内外部资源，协调多个部门，完成重点专项的推进与落地。","requirements":"1.有耐心，能够熟练进行法律风险咨询和评估，有应对突发事件经验；\n2.执行力强，善于沟通，愿意配合团队完成任务；\n3.通过国家统一法律职业资格考试，法学本科及以上学历；\n4.有5年以上公司法务或律师工作经验，熟悉硬件、有产品质量纠纷处置经验或诉讼经验优先。","description":"部门介绍\n公司事务平台负责构建公司的公共战略体系，助力业务可持续发展及公司对外影响力的提升。通过内外部风险管理，确保公司合规发展；通过深耕公共战略，推动内外良好沟通，连接公司发展与社会期待，助力业务高质量发展；通过管理社会责任议题、公益投入等，助力公司创造更多社会价值；同时为公司提供行政、采购等基础服务。我们坚持“懂业务、拿结果，勇担当、善协同，不唯上、只唯真”的工作理念，期待具有公共战略素养、了解公司治理逻辑的你加入！\n\n岗位职责\n1.结合业务目标、外部环境变化及法律合规需求，形成对业务有效的法律风险控制方案，如业务全国各区域运营、数据合规、信息安全、广告合规等风险评估；\n2.参与业务的产品设计，评估法律风险和提出法律建议，能运用自己的专业知识通过合同、流程、机制、培训等多种路径，帮助实现业务目标；\n3.支持业务硬件（整车、零部件、电池等）采购、供应链管理、产品研发等项目风险评估，合同支持以及纠纷事件处置；\n4.支持业务各链路发生的争议纠纷、突发事件、行政处罚风险等；\n5.业务政策、立法跟踪、分析解读并向业务输出指导意见；\n6.整合法务团队内外部资源，协调多个部门，完成重点专项的推进与落地。\n\n岗位基本要求\n1.有耐心，能够熟练进行法律风险咨询和评估，有应对突发事件经验；\n2.执行力强，善于沟通，愿意配合团队完成任务；\n3.通过国家统一法律职业资格考试，法学本科及以上学历；\n4.有5年以上公司法务或律师工作经验，熟悉硬件、有产品质量纠纷处置经验或诉讼经验优先。\n\n岗位亮点\n业务多元、有机会接触前沿商业模式，团队氛围活泼","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4704871410","sourceKey":"meituan_social","company":"美团","title":"无人车业务部-融合定位算法专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4704871410&jobShareType=1","duty":"1、负责提升当前多传感器融合定位系统在各类长尾场景上的能力。\n2、负责探索基于深度学习模型的3D视觉的应用能力；例如deep odometry, deep 3D matching and reconstruction.\n3、与高精地图、感知、PnC等算法团队合作，能够完成从研发到工程化到上线落地的过程。","requirements":"1、硕士以上学历优先，计算机相关专业（人工智能，模式识别，计算机科学，数学等)；\n2、熟练掌握计算机视觉及多传感器融合相关的知识。熟悉深度学习相关知识。具有独立分析问题、制定技术方案、开发上线的能力；\n3、熟悉GPS卫星定位原理，如PVT、精密单点定位（PPP）、RTK算法、卫星差分后处理算法等；\n4、具备较好的编程能力，熟练掌握C/C++或Python编程语言。","description":"部门介绍\n无人车业务部成立于2016年，旨在用无人驾驶技术提升物流配送的效率和体验。美团无人车以自研L4级自动驾驶软硬件技术为核心，与美团即时零售业务结合，形成满足公开道路、社区、工业园区等室外全场景下的无人配送整体解决方案。自2020年起，无人车已在北京、深圳等多地进入常态化试运营阶段，在城市复杂场景下提供针对餐饮外卖、生鲜食杂等货物的即时配送服务。2025年，美团无人车又踏上了同城货运的新探索，并在2026年持续扩大运营范围和车队数量，为更多城市带来智能配送服务。\n欢迎加入美团无人车团队，与我们一起用科技推动即时零售再升级！\n\n岗位职责\n1、负责提升当前多传感器融合定位系统在各类长尾场景上的能力。\n2、负责探索基于深度学习模型的3D视觉的应用能力；例如deep odometry, deep 3D matching and reconstruction.\n3、与高精地图、感知、PnC等算法团队合作，能够完成从研发到工程化到上线落地的过程。\n\n岗位基本要求\n1、硕士以上学历优先，计算机相关专业（人工智能，模式识别，计算机科学，数学等)；\n2、熟练掌握计算机视觉及多传感器融合相关的知识。熟悉深度学习相关知识。具有独立分析问题、制定技术方案、开发上线的能力；\n3、熟悉GPS卫星定位原理，如PVT、精密单点定位（PPP）、RTK算法、卫星差分后处理算法等；\n4、具备较好的编程能力，熟练掌握C/C++或Python编程语言。\n\n具备以下条件优先\n1、3年以上计算机视觉或2年以上自动驾驶相关工作经验优先；\n2、在机器人领域或者计算机视觉或机器学习相关领域发表过高质量论文；\n3、在Github上有深度学习、计算机视觉、融合定位等相关高质量项目。\n\n岗位亮点\n美团自动车配送部在公开道路、居民区、校园三大行驶场景上有深厚的技术和数据积累，定位作为自动驾驶最基础且核心的功能之一，对自动驾驶落地有重要的价值，过去、现在及未来都是自动车配送部重点建设团队。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4708608380","sourceKey":"meituan_social","company":"美团","title":"生产主管","city":"石家庄市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4708608380&jobShareType=1","duty":"1.负责石家庄仓内生产管理工作，并对人效，质量和履约负责；\n2.持续员工培训，并监督有效执行；\n3.横向部门沟通协调工作；\n4.不断优化现有作业流程。提高人效.减低差异；\n5.仓内员工的正负激励措施及执行；\n6.现场6S管理；\n7.直接上级安排的其它工作；","requirements":"具备较强团队管理能力，激发员工工作热情；\n熟悉仓库管理各操作流程；\n熟练使用仓库WMS操作系统和办公软件；","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1.负责石家庄仓内生产管理工作，并对人效，质量和履约负责；\n2.持续员工培训，并监督有效执行；\n3.横向部门沟通协调工作；\n4.不断优化现有作业流程。提高人效.减低差异；\n5.仓内员工的正负激励措施及执行；\n6.现场6S管理；\n7.直接上级安排的其它工作；\n\n岗位基本要求\n具备较强团队管理能力，激发员工工作热情；\n熟悉仓库管理各操作流程；\n熟练使用仓库WMS操作系统和办公软件；\n\n具备以下条件优先\n大型仓储生产管理经验；\n\n岗位亮点\n团队稳定，大平台，晋升空间大，模块仓库，便于个人能力发挥；","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4709347488","sourceKey":"meituan_social","company":"美团","title":"业务培训专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4709347488&jobShareType=1","duty":"1. 负责制定并实施面向内外部的业务培训项目，助一线蓝领群体快速掌握对应技能。  \n2. 设计并优化培训课程体系，包括组织资源、标杆体系等开发，确保培训内容贴合业务实际需求。  \n3. 组织并独立交付线下及线上培训活动，包括培训授课、现场答疑及效果跟踪，保障培训质量与参与度。  \n4. 收集学习活动反馈，分析培训效果，持续改进培训方案，提升客户满意度和业务转化率。  \n5. 团队内外紧密协作，推动培训成果在业务场景中的落地应用。","requirements":"1. 大学本科及以上学历，具备3-5年业务培训或相关领域工作经验。\n2. 熟悉培训体系搭建与课程设计，有外训或客户培训经验者优先。  \n3. 具备优秀的表达与沟通能力，能够清晰传递复杂业务信息，适应高频次出差及对外授课。  \n4. 具备较强的项目管理和跨团队协作能力，能独立推进培训项目全流程。  \n5. 利用AI工具辅助课程开发、知识萃取与学习数据分析，能够基于业务场景设计智能化培训方案，提升培训效率与个性化学习体验。","description":"部门介绍\n美团闪购是美团旗下的即时零售平台，依托即时配送能力，连接本地零售供给，满足消费者30分钟万物到家的即时需求。美团闪购涵盖超市便利、食材、水果、鲜花绿植、休闲零食、酒水饮料、数码家电、美妆个护、母婴玩具、日用百货、服饰鞋帽、宠物等诸多品类，业务覆盖全国近3,000个县市区旗，每日百万级在岗骑手，以高效的配送、丰富的品类和广泛的覆盖，为美团数亿用户带来便捷的生活体验，积极助力实体零售线上化转型，提升本地商业活力。\n\n岗位职责\n1. 负责制定并实施面向内外部的业务培训项目，助一线蓝领群体快速掌握对应技能。  \n2. 设计并优化培训课程体系，包括组织资源、标杆体系等开发，确保培训内容贴合业务实际需求。  \n3. 组织并独立交付线下及线上培训活动，包括培训授课、现场答疑及效果跟踪，保障培训质量与参与度。  \n4. 收集学习活动反馈，分析培训效果，持续改进培训方案，提升客户满意度和业务转化率。  \n5. 团队内外紧密协作，推动培训成果在业务场景中的落地应用。\n\n岗位基本要求\n1. 大学本科及以上学历，具备3-5年业务培训或相关领域工作经验。\n2. 熟悉培训体系搭建与课程设计，有外训或客户培训经验者优先。  \n3. 具备优秀的表达与沟通能力，能够清晰传递复杂业务信息，适应高频次出差及对外授课。  \n4. 具备较强的项目管理和跨团队协作能力，能独立推进培训项目全流程。  \n5. 利用AI工具辅助课程开发、知识萃取与学习数据分析，能够基于业务场景设计智能化培训方案，提升培训效率与个性化学习体验。\n\n具备以下条件优先\n有酒水、零售或连锁行业经验优先\n\n岗位亮点\n1. 加入快速发展的零售品牌，参与全国门店网络扩张与运营升级。  \n2. 拥有完善的培训体系支持与职业发展通道，助力个人专业能力提升。  \n3. 团队氛围开放包容，鼓励创新与持续学习。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4411022345","sourceKey":"meituan_social","company":"美团","title":"智能营销大模型算法专家","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4411022345&jobShareType=1","duty":"全链路增长体系构建：负责金融营销垂直领域基座模型的深度定制，推动大模型技术从 0 到 1 落地应用及持续迭代，从用户全生命周期（感知、获客、激活、转化、留存、召回）出发，深度参与构建高度智能的业务增长算法体系；\n\n基于Agent技术的数字员工构建：在智能理赔、智能客服等高人力消耗领域，构建各类智能 Agent，通过提供高效智能服务，有效降低人工成本，同时提升用户服务体验。\n\n高效的效果分析与复盘能力构建：构建自闭环高效效果分析系统，整合大模型营销全链路数据，建立涵盖转化率、ROI、用户体验、合规性的多维度评估指标体系；通过数据归因、异常诊断等手段定位瓶颈，形成标准化复盘流程并输出优化建议，驱动系统与策略迭代，实现全闭环运转，最大化 AI 营销效能。\n\n驱动项目的完成：与产品、运营团队紧密配合，将业务问题转化为科学的数学模型，有效协调上下游资源推进项目，保障目标落地。","requirements":"具备扎实的大模型与 AI 算法基础，熟悉大模型、自然语言处理NLP、因果推断、机器学习与深度学习核心技术；\n\n熟悉Pytorch/TensorFlow框架，具备分布式训练和模型优化经验。\n\n熟练掌握大模型训练调优与推理加速，包括但不限于大模型微调（SFT）、强化学习、蒸馏、量化部署等全流程工作\n\n拥有生产环境 AI 项目落地经验，熟悉RAG、智能 Agent等主流框架与实现机制（FAISS/Milvus/LangChain/LangGraph），熟练掌握Prompt Engineering，能够独立完成任务设计与效果优化；能够将大模型技术与金融营销场景结合，构建用户理解、智能交互、策略优化与自动化迭代系统。","description":"部门介绍\n美团金融服务平台成立于2016年，以“场景+金融”模式，携手合作伙伴构建开放生态，为美团平台用户和商户提供底层账户、支付通道、信贷、保险和理财等金融解决方案。我们致力于以科技为核心，助力金融机构打通金融普惠“最后一公里”。我们期待与大家共同完成每一件平凡而卓越的事情，一起为用户提供优质的产品体验，守护用户的资金安全，让生活变得更美好。\n\n岗位职责\n全链路增长体系构建：负责金融营销垂直领域基座模型的深度定制，推动大模型技术从 0 到 1 落地应用及持续迭代，从用户全生命周期（感知、获客、激活、转化、留存、召回）出发，深度参与构建高度智能的业务增长算法体系；\n\n基于Agent技术的数字员工构建：在智能理赔、智能客服等高人力消耗领域，构建各类智能 Agent，通过提供高效智能服务，有效降低人工成本，同时提升用户服务体验。\n\n高效的效果分析与复盘能力构建：构建自闭环高效效果分析系统，整合大模型营销全链路数据，建立涵盖转化率、ROI、用户体验、合规性的多维度评估指标体系；通过数据归因、异常诊断等手段定位瓶颈，形成标准化复盘流程并输出优化建议，驱动系统与策略迭代，实现全闭环运转，最大化 AI 营销效能。\n\n驱动项目的完成：与产品、运营团队紧密配合，将业务问题转化为科学的数学模型，有效协调上下游资源推进项目，保障目标落地。\n\n岗位基本要求\n具备扎实的大模型与 AI 算法基础，熟悉大模型、自然语言处理NLP、因果推断、机器学习与深度学习核心技术；\n\n熟悉Pytorch/TensorFlow框架，具备分布式训练和模型优化经验。\n\n熟练掌握大模型训练调优与推理加速，包括但不限于大模型微调（SFT）、强化学习、蒸馏、量化部署等全流程工作\n\n拥有生产环境 AI 项目落地经验，熟悉RAG、智能 Agent等主流框架与实现机制（FAISS/Milvus/LangChain/LangGraph），熟练掌握Prompt Engineering，能够独立完成任务设计与效果优化；能够将大模型技术与金融营销场景结合，构建用户理解、智能交互、策略优化与自动化迭代系统。\n\n具备以下条件优先\n3年以上大模型、智能Agent、NLP、搜广推营销相关方向工作经验，硕士以上学历，有营销算法工作经验优先，有金融领域工作经验优先。\n\n岗位亮点\n大模型积淀与实践沃土：团队过去在模型微调（Fine-tuning）、强化学习、Agent能力建设等领域有深厚积累。未来，也将拥有充足的支持和丰富的应用场景，探索大模型在营销领域、Agent数字员工等方向的落地机会；\n\n海量数据与高挑战：依托海量用户规模和真实复杂的营销场景，算法策略将直接驱动亿级流量，适合各种前沿技术的快速验证与迭代；\n\n价值实现的直通车：业务导向明确，算法每一次的迭代都能直接反映在ROI、转化率等核心商业指标上，成就感十足；\n\n优秀的人才密度与研究氛围：团队同学全部来自国内外名校及大厂，可以与优秀同事并肩作战，另团队各种分享与研讨会活动丰富，技术氛围浓厚，鼓励创新与技术分享。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4130974558","sourceKey":"meituan_social","company":"美团","title":"医药健康-医美品类运营","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4130974558&jobShareType=1","duty":"1.品类策略制定与执行：基于用户需求和行业趋势，定义品类分层（核心品类/潜力品类/新兴品类），制定各品类的增长目标和运营策略；\n\n2.上游品牌增长方案：针对核心品类和潜力品类，制定上游品牌入驻和增长策略，联合品牌打造明星爆品，推动平台收入增长；\n\n3.品类数据监控与迭代：建立品类健康度指标体系（业务增速、用户渗透率、复购率、满意度等），持续监控品类表现，发现增长机会和风险；\n\n4.跨部门资源协同：联动整合营销、广告运营、商家运营团队，将品类策略融入整体业务运营节奏，形成品类增长的合力。","requirements":"1.5年以上互联网品类运营经验，有平台品类运营经验，熟悉品类管理方法论；；\n\n2.具备品类洞察力——能判断，有品类成功孵化案例；\n\n3.理解上游供应链、品牌商和线下机构的运营逻辑；\n\n4.商业敏感度高：能从品类数据中发现商业机会，将洞察转化为可执行的品类策略和收入增长方案；\n\n5.能驾驭行业复杂性，以及上游供应链的多方协调，需要同时具备行业理解力和商业判断力。","description":"部门介绍\n美团医药健康事业部是美团核心本地商业板块下专注健康领域的业务部门，涵盖美团买药、美团医美和美团医疗三大业务。自创立以来，美团医药健康致力于为用户提供全健康周期产品及服务，满足人民群众多层次多元化医疗健康需求，现已覆盖购药到家、居家检测、问诊挂号、医保支付、求医寻院、医疗美容等核心场景。此外，美团医药健康还为商户提供数字化转型创新解决方案，打造贯穿上游的联动机制，长期参与共建更透明、更可持续的医药健康产业生态圈，目前业务已覆盖25万家药店，收录27万家医疗机构。未来，美团医药康将协同更多行业伙伴，帮助大家变得更健康、更美丽、更养生。\n\n岗位职责\n1.品类策略制定与执行：基于用户需求和行业趋势，定义品类分层（核心品类/潜力品类/新兴品类），制定各品类的增长目标和运营策略；\n\n2.上游品牌增长方案：针对核心品类和潜力品类，制定上游品牌入驻和增长策略，联合品牌打造明星爆品，推动平台收入增长；\n\n3.品类数据监控与迭代：建立品类健康度指标体系（业务增速、用户渗透率、复购率、满意度等），持续监控品类表现，发现增长机会和风险；\n\n4.跨部门资源协同：联动整合营销、广告运营、商家运营团队，将品类策略融入整体业务运营节奏，形成品类增长的合力。\n\n岗位基本要求\n1.5年以上互联网品类运营经验，有平台品类运营经验，熟悉品类管理方法论；；\n\n2.具备品类洞察力——能判断，有品类成功孵化案例；\n\n3.理解上游供应链、品牌商和线下机构的运营逻辑；\n\n4.商业敏感度高：能从品类数据中发现商业机会，将洞察转化为可执行的品类策略和收入增长方案；\n\n5.能驾驭行业复杂性，以及上游供应链的多方协调，需要同时具备行业理解力和商业判断力。\n\n岗位亮点\n1、业务高速发展，市场发展机会好；\n2、团队氛围坦诚直接、能够在学习型组织中快速成长。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4301506211","sourceKey":"meituan_social","company":"美团","title":"供应链负责人","city":"北京市/深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4301506211&jobShareType=1","duty":"1、供应链体系建设与战略规划：负责项目及量产硬件产品成本、交付业务指标达成。制定并推行覆盖采购、计划交付、物流、成本等模块的供应链整体战略与年度规划，构建或优化敏捷供应链体系流程与机制，支撑硬件产品从研发试制到大规模量产的全生命周期管理。\n2、AI驱动的智能供应链升级：主导供应链AI应用场景落地，推动需求预测AI模型、智能库存优化、AI驱动的供应商评估与风险预警、智能排产与产能规划等能力建设，用数据与AI持续提升供应链决策效率与准确性。\n3、供应链数字化系统建设与优化：推动SRM/ERP/MES/WMS等供应链数字化平台的建设与应用，实现供应链全环节的实时数据采集、可视化监控与智能分析，打造\"数字智能化供应链\"。\n4、团队建设与管理：管理供应链团队，涵盖计划供应、运营体系、商务采购、成本优化、物流信息化等方向，建立人才梯队，推动团队能力建设与组织效能提升。\n5、供应链风险管理与合规：建立供应链风险评估与预警机制，识别地缘政治、原材料波动、产能瓶颈等潜在风险并制定应对预案；确保供应链合规运营，符合ESG与可持续发展要求。\n6、供应链生态建设：拓展供应链生态资源，探索柔性供应链、共创发展等创新模式，支撑业务快速增长。","requirements":"1、本科及以上学历，供应链管理、工业工程、机械、电子、计算机等相关专业优先。\n2、10年以上供应链管理经验，5年以上担任供应链负责人/高级总监岗位，管理30人以上团队；汽车、机器人、消费电子、智能硬件等行业背景，具备敏捷供应链完整管理经验。\n3、精通采购管理、计划交付、物流仓储、成本管控等模块，有从0到1搭建或从1到N升级供应链体系的成功经验优先。\n4、具备战略格局与全局视野，善于用数据分析与量化方法驱动决策。\n5、具备推动组织变革与流程再造的领导力，优秀的跨部门协同与影响力。\n6、能组建和领导AI+供应链复合型团队，推动传统供应链向\"AI+数据\"驱动型组织转型，持续AI前沿技术在供应链领域的应用。","description":"部门介绍\n美团的使命是“帮大家吃得更好，生活更好”，公司聚焦“零售 + 科技”战略，和广大商户与各类合作伙伴一起，努力为消费者提供品质生活，推动商品零售和服务零售在需求侧和供给侧的数字化转型。\n2018年9月20日，美团正式在港交所挂牌上市。美团将始终坚持以客户为中心，不断加大在科技研发方面的投入，更好承担社会责任，更多创造社会价值，与广大合作伙伴一起发展共赢。\n\n岗位职责\n1、供应链体系建设与战略规划：负责项目及量产硬件产品成本、交付业务指标达成。制定并推行覆盖采购、计划交付、物流、成本等模块的供应链整体战略与年度规划，构建或优化敏捷供应链体系流程与机制，支撑硬件产品从研发试制到大规模量产的全生命周期管理。\n2、AI驱动的智能供应链升级：主导供应链AI应用场景落地，推动需求预测AI模型、智能库存优化、AI驱动的供应商评估与风险预警、智能排产与产能规划等能力建设，用数据与AI持续提升供应链决策效率与准确性。\n3、供应链数字化系统建设与优化：推动SRM/ERP/MES/WMS等供应链数字化平台的建设与应用，实现供应链全环节的实时数据采集、可视化监控与智能分析，打造\"数字智能化供应链\"。\n4、团队建设与管理：管理供应链团队，涵盖计划供应、运营体系、商务采购、成本优化、物流信息化等方向，建立人才梯队，推动团队能力建设与组织效能提升。\n5、供应链风险管理与合规：建立供应链风险评估与预警机制，识别地缘政治、原材料波动、产能瓶颈等潜在风险并制定应对预案；确保供应链合规运营，符合ESG与可持续发展要求。\n6、供应链生态建设：拓展供应链生态资源，探索柔性供应链、共创发展等创新模式，支撑业务快速增长。\n\n岗位基本要求\n1、本科及以上学历，供应链管理、工业工程、机械、电子、计算机等相关专业优先。\n2、10年以上供应链管理经验，5年以上担任供应链负责人/高级总监岗位，管理30人以上团队；汽车、机器人、消费电子、智能硬件等行业背景，具备敏捷供应链完整管理经验。\n3、精通采购管理、计划交付、物流仓储、成本管控等模块，有从0到1搭建或从1到N升级供应链体系的成功经验优先。\n4、具备战略格局与全局视野，善于用数据分析与量化方法驱动决策。\n5、具备推动组织变革与流程再造的领导力，优秀的跨部门协同与影响力。\n6、能组建和领导AI+供应链复合型团队，推动传统供应链向\"AI+数据\"驱动型组织转型，持续AI前沿技术在供应链领域的应用。\n\n具备以下条件优先\n互联网大厂，负责多个产品业务线供应链，年千万量级规模交付；一起探索AI在硬件供应链领域的加速应用。\n\n岗位亮点\n具备丰富电子、结构、整机采购和交付经验，支持过千万量级交付。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4681996791","sourceKey":"meituan_social","company":"美团","title":"小象超市PC加工经理","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4681996791&jobShareType=1","duty":"1. 负责小象超市PC加工中心的日常运营管理，确保生产计划高效执行。  \n2. 统筹200人团队的排班、培训与绩效考核，提升团队整体作业效率。  \n3. 优化加工流程与标准作业程序，保障商品品质与食品安全合规。  \n4. 协同仓储、物流及采购部门，实现库存精准控制与成本优化。  \n5. 监控关键运营指标，定期输出分析报告并提出改进方案。","requirements":"1. 大学专科及以上学历，物流、仓储、供应链管理等相关专业优先。  \n2. 具备5年以上生鲜加工或零售仓储管理经验，有大型团队管理背景。  \n3. 熟悉PC加工中心运作流程，具备食品安全管理体系知识。  \n4. 具备较强的数据分析能力与跨部门沟通协调能力。  \n5. 工作城市为北京市，能适应高强度工作环境。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1. 负责小象超市PC加工中心的日常运营管理，确保生产计划高效执行。  \n2. 统筹200人团队的排班、培训与绩效考核，提升团队整体作业效率。  \n3. 优化加工流程与标准作业程序，保障商品品质与食品安全合规。  \n4. 协同仓储、物流及采购部门，实现库存精准控制与成本优化。  \n5. 监控关键运营指标，定期输出分析报告并提出改进方案。\n\n岗位基本要求\n1. 大学专科及以上学历，物流、仓储、供应链管理等相关专业优先。  \n2. 具备5年以上生鲜加工或零售仓储管理经验，有大型团队管理背景。  \n3. 熟悉PC加工中心运作流程，具备食品安全管理体系知识。  \n4. 具备较强的数据分析能力与跨部门沟通协调能力。  \n5. 工作城市为北京市，能适应高强度工作环境。\n\n岗位亮点\n1. 管理200人规模团队，具备广阔的职业发展空间。  \n2. 参与生鲜零售核心业务，推动供应链效率提升。  \n3. 公司提供完善的培训体系与晋升机制。  \n4. 工作地点位于北京核心区域，交通便利。  \n5. 享受具有竞争力的薪酬与福利待遇。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4636736507","sourceKey":"meituan_social","company":"美团","title":"华东大区负责人","city":"上海市/杭州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4636736507&jobShareType=1","duty":"1. 全面负责华东大区物流运营生产体系的规划、建设与优化，确保区域效率与服务质量及新能看建设的持续提升。  \n2. 制定并执行大区物流战略，统筹多个城市，果蔬加工，净菜加工，等项目的运营管理及目标达成。  \n3. 带领团队完成日常运营目标，监督KPI达成情况，推动流程标准化与数字化升级。  \n4. 协同总部与各区域资源，解决重大运营问题，提升客户满意度与市场响应速度。  \n5. 建立并培养高效物流团队，完善人才梯队建设与绩效激励机制。","requirements":"1. 大学本科及以上学历，食品、物流、供应链、管理类相关专业优先。  \n2. 8年以上生产行业工作经验，具备大区或跨区域物流运营管理经验。  \n3. 具备较强的数据分析能力、战略规划能力和团队管理能力。  \n5. 工作地点为上海市或杭州市，能适应高频次跨区域出差。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1. 全面负责华东大区物流运营生产体系的规划、建设与优化，确保区域效率与服务质量及新能看建设的持续提升。  \n2. 制定并执行大区物流战略，统筹多个城市，果蔬加工，净菜加工，等项目的运营管理及目标达成。  \n3. 带领团队完成日常运营目标，监督KPI达成情况，推动流程标准化与数字化升级。  \n4. 协同总部与各区域资源，解决重大运营问题，提升客户满意度与市场响应速度。  \n5. 建立并培养高效物流团队，完善人才梯队建设与绩效激励机制。\n\n岗位基本要求\n1. 大学本科及以上学历，食品、物流、供应链、管理类相关专业优先。  \n2. 8年以上生产行业工作经验，具备大区或跨区域物流运营管理经验。  \n3. 具备较强的数据分析能力、战略规划能力和团队管理能力。  \n5. 工作地点为上海市或杭州市，能适应高频次跨区域出差。\n\n具备以下条件优先\n1、区域管理经验 — 有区域/中台综合岗位经历者优先\n2、数据化思维 — 具备数据驱动管理理念\n3、生鲜工厂背景 — 大型生鲜生产工厂、多元化业务经验\n\n岗位亮点\n1. 担任大区负责人，拥有高度自主权与战略决策参与机会。  \n2. 加入行业优选企业，平台资源丰富，发展空间广阔。  \n3. 大团队规模的管理，具备完善的管理支持体系与晋升通道。  \n4. 工作地点位于长三角核心城市，交通便利，生活配套完善。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4620811504","sourceKey":"meituan_social","company":"美团","title":"自动化规划实施负责人","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4620811504&jobShareType=1","duty":"1.制定仓内自动化设备的整体应用战略与中长期规划，主导智能化、人机结合解决方案的顶层设计。统筹规划团队完成数据分析、布局设计、作业流程与系统流程设计，输出高可行性方案并完成项目立项，确保技术方向与业务需求高度匹配。\n2.建立从方案设计到工程落地的全生命周期项目管理体系，统筹项目参与方与外部厂商资源，制定并把控项目计划节点，推动项目按期高质量交付。同时负责实施过程中的风险识别、问题闭环与方案纠偏，保障项目交付效率与质量。\n3.主导仓储改造工程的设计标准迭代，包括强电、给排水、土木工程结构等专业技术规范。对竣工图纸进行审核校验，核准工程变更，推动规划实施标准持续优化，形成可复制、可规模化的工程实施能力。\n4.收集并分析使用方的需求与痛点，建立常态化反馈机制。对已落地项目进行效果复盘与持续优化，推动自动化方案在业务场景中不断迭代升级，确保技术方案的适用性与先驱性。\n5.负责自动化规划与规划实施两个团队的日常管理与能力建设，培养复合型技术人才。协同运营、采购、供应链、技术等多部门，推动自动化项目从规划到落地的顺畅衔接。","requirements":"1.具备物流、自动化、工业工程相关专业背景，本科及以上学历。拥有8年以上仓储自动化、物流规划等相关经验\n2.熟悉仓储自动化设备（如AGV、AMR、自动分拣、立体库等）的应用原理与部署逻辑；具备扎实的工程设计专业知识，对机电、暖通、给排水、消防及强电等工程领域有系统认知；了解仓储智能化系统与作业流程设计方法。\n3.具备大型项目全生命周期管理经验，能够统筹多方资源、把控项目节点与交付质量。具备较强的风险意识与推动能力，能在快节奏的环境下保障项目顺利推进。\n4.具备强烈的互联网思维与数据驱动意识，善于用系统化的方法解决复杂问题。拥有主人翁精神，学习能力强，能够快速适应业务变化与新技术发展。具备较强的沟通协调能力与跨部门推动力。\n5.具备良好的任务应对能力，可适应项目所需的出差安排。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1.制定仓内自动化设备的整体应用战略与中长期规划，主导智能化、人机结合解决方案的顶层设计。统筹规划团队完成数据分析、布局设计、作业流程与系统流程设计，输出高可行性方案并完成项目立项，确保技术方向与业务需求高度匹配。\n2.建立从方案设计到工程落地的全生命周期项目管理体系，统筹项目参与方与外部厂商资源，制定并把控项目计划节点，推动项目按期高质量交付。同时负责实施过程中的风险识别、问题闭环与方案纠偏，保障项目交付效率与质量。\n3.主导仓储改造工程的设计标准迭代，包括强电、给排水、土木工程结构等专业技术规范。对竣工图纸进行审核校验，核准工程变更，推动规划实施标准持续优化，形成可复制、可规模化的工程实施能力。\n4.收集并分析使用方的需求与痛点，建立常态化反馈机制。对已落地项目进行效果复盘与持续优化，推动自动化方案在业务场景中不断迭代升级，确保技术方案的适用性与先驱性。\n5.负责自动化规划与规划实施两个团队的日常管理与能力建设，培养复合型技术人才。协同运营、采购、供应链、技术等多部门，推动自动化项目从规划到落地的顺畅衔接。\n\n岗位基本要求\n1.具备物流、自动化、工业工程相关专业背景，本科及以上学历。拥有8年以上仓储自动化、物流规划等相关经验\n2.熟悉仓储自动化设备（如AGV、AMR、自动分拣、立体库等）的应用原理与部署逻辑；具备扎实的工程设计专业知识，对机电、暖通、给排水、消防及强电等工程领域有系统认知；了解仓储智能化系统与作业流程设计方法。\n3.具备大型项目全生命周期管理经验，能够统筹多方资源、把控项目节点与交付质量。具备较强的风险意识与推动能力，能在快节奏的环境下保障项目顺利推进。\n4.具备强烈的互联网思维与数据驱动意识，善于用系统化的方法解决复杂问题。拥有主人翁精神，学习能力强，能够快速适应业务变化与新技术发展。具备较强的沟通协调能力与跨部门推动力。\n5.具备良好的任务应对能力，可适应项目所需的出差安排。\n\n具备以下条件优先\n兼具自动化方案设计能力与工程实施管理经验者优先。\n\n岗位亮点\n小象超市业务发展迅速， 有比较大的平台和需求，利于自动化发展。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4604300717","sourceKey":"meituan_social","company":"美团","title":"小象超市-自有商品品质治理专家","city":"北京市/上海市/深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4604300717&jobShareType=1","duty":"1、负责小象超市自营商品预包装食品的品质管理的全面规划与执行，确保商品在各个环节的品质标准得到有效控制。  2、建立和完善自营商品品质管理体系，包括制定自营商品品质管理流程、标准和指导文件，并监督执行情况、主导新品开发阶段的品质标准制定、配方与工艺评审。 \n3、负责供应商（特别是PB商品）的开发准入审核、定期验厂及风险评估。主导对供应商工厂的体系审核（如BRC 、FSSC 22000,、ISO 22000, HACCP等）与过程审核，现场评估其质量保证能力、生产条件与卫生控制水平。\n 4、负责自营商品品质问题的调查与处理，商品品质数据的统计和分析，及时发现问题并提出改进措施，提高产品品质和客户满意度，推动供应商质量能力提升；基于客诉及内外部检验数据，进行趋势分析，发起跨部门质量改进项目，系统性降低质量风险。 \n5、负责PB商品全生命周期品质管理：如质量体系与标准建设：制定负责品类和更新PB商品及其他相关商品的验收标准、质量协议及质量管理流程。监控PB商品从试产、量产到上市后的全过程品质表现，确保所有品质管理活动符合国家法律法规、行业标准及企业内部要求。 \n6、对负责的品类产品的日常口感测评任务，并对测评结果实施统计分析跟进结果。","requirements":"1、：本科及以上学历，食品科学与工程、质量管理、农学等相关专业。5年以上食品制造业或大型零售/电商企业品质管理工作经验，研发经验；具备PB商品或自有品牌的质量管理经验。\n2、精通食品行业质量管理体系（BRC、ISO 22000,、HACCP,、GMP等）及食品安全法规，具备丰富的供应商现场审核经验。\n3、出色的客诉分析与解决能力，熟练运用质量工具（如8D, 5Why, FMEA, SPC等）进行根本原因分析和持续改进。 4、扎实的沟通协调能力、谈判技巧及跨部门项目推动能力。优秀的团队协作精神，能够与研发、商品、生产商、服务体验等多部门高效协同。\n 5、能适应经常性的供应商工厂出差，具备一定的快节奏岗位适应能力。\n 6.掌握基本的AI工具，使用工具提升工作流程效率。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1、负责小象超市自营商品预包装食品的品质管理的全面规划与执行，确保商品在各个环节的品质标准得到有效控制。  2、建立和完善自营商品品质管理体系，包括制定自营商品品质管理流程、标准和指导文件，并监督执行情况、主导新品开发阶段的品质标准制定、配方与工艺评审。 \n3、负责供应商（特别是PB商品）的开发准入审核、定期验厂及风险评估。主导对供应商工厂的体系审核（如BRC 、FSSC 22000,、ISO 22000, HACCP等）与过程审核，现场评估其质量保证能力、生产条件与卫生控制水平。\n 4、负责自营商品品质问题的调查与处理，商品品质数据的统计和分析，及时发现问题并提出改进措施，提高产品品质和客户满意度，推动供应商质量能力提升；基于客诉及内外部检验数据，进行趋势分析，发起跨部门质量改进项目，系统性降低质量风险。 \n5、负责PB商品全生命周期品质管理：如质量体系与标准建设：制定负责品类和更新PB商品及其他相关商品的验收标准、质量协议及质量管理流程。监控PB商品从试产、量产到上市后的全过程品质表现，确保所有品质管理活动符合国家法律法规、行业标准及企业内部要求。 \n6、对负责的品类产品的日常口感测评任务，并对测评结果实施统计分析跟进结果。\n\n岗位基本要求\n1、：本科及以上学历，食品科学与工程、质量管理、农学等相关专业。5年以上食品制造业或大型零售/电商企业品质管理工作经验，研发经验；具备PB商品或自有品牌的质量管理经验。\n2、精通食品行业质量管理体系（BRC、ISO 22000,、HACCP,、GMP等）及食品安全法规，具备丰富的供应商现场审核经验。\n3、出色的客诉分析与解决能力，熟练运用质量工具（如8D, 5Why, FMEA, SPC等）进行根本原因分析和持续改进。 4、扎实的沟通协调能力、谈判技巧及跨部门项目推动能力。优秀的团队协作精神，能够与研发、商品、生产商、服务体验等多部门高效协同。\n 5、能适应经常性的供应商工厂出差，具备一定的快节奏岗位适应能力。\n 6.掌握基本的AI工具，使用工具提升工作流程效率。\n\n具备以下条件优先\n1.具备5年以上食品制造业、零售企业全链路的品质管理能力优先：\n 2.独立负责过自营商品品质管理经验的优先；在食品零售行业、食品制造业、互联网行业食品品类管理经验优先；\n\n岗位亮点\n1、资深食品品质管理人员，将有机会负责带领团队负责对商品品质管理的全流程工作，积累丰富的管理经验。 \n2、业务管理的精深：端到端深度参与，从供应商源头到消费者终端，提供全链路的质量管理视角与实践机会，极大拓宽专业广度与深度。\n3、影响力与成长性：岗位具有内部能见度与影响力，PB商品的品质生命线，价值贡献清晰可见。 \n4、系统性能力建设：不仅处理具体问题，更有机会不断提升整个PB商品品质管理体系管理能力。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4707954252","sourceKey":"meituan_social","company":"美团","title":"闪购-歪马-门店拓展经理","city":"北京市/上海市/杭州市/武汉市/广州市/深圳市/成都市/西安市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4707954252&jobShareType=1","duty":"1.负责统筹所支持区域的资产管理工作，包括续约、换仓、租金或其他费用的优化等；\n2.处理前置仓的租赁合同在履行过程中发生的履约、纠纷、变更等工作；\n3.根据城市规划在计划开仓区域完成仓源储备及仓源复核，输出选址评审报告并完成开仓任务。\n4.负责前置仓租赁商务谈判、合同谈判、合同签约，基本工程条件的谈判以及风险评估；\n5.根据开仓指标达成情况可以做出分析和复盘，输出相关选址迭代标准及策略；","requirements":"1.本科及以上学历；\n2.3年及以上零售拓展行业的相关工作经验，具备前置仓、便利店、街边店铺选址的工作经验者优先；\n3.较强的专业能力，能够独立完成选址评估、谈判、签约及进场工作；\n4.掌握与租赁合同相关的基本法律、法规问题，与房东洽谈时能够辨别和规避法律风险、保障公司权益；\n5.掌握基本的工程常识，做选址评估时能够辨别较为明显的工程隐患；\n6.较强的沟通、谈判、协调能力，具备一定的谈判技巧及处理公共关系的能力；\n7. 有较强的自我驱动力、学习能力，对新零售有一定了解。\n8.能接受无固定城市长期出差的工作。","description":"部门介绍\n美团闪购是美团旗下的即时零售平台，依托即时配送能力，连接本地零售供给，满足消费者30分钟万物到家的即时需求。美团闪购涵盖超市便利、食材、水果、鲜花绿植、休闲零食、酒水饮料、数码家电、美妆个护、母婴玩具、日用百货、服饰鞋帽、宠物等诸多品类，业务覆盖全国近3,000个县市区旗，每日百万级在岗骑手，以高效的配送、丰富的品类和广泛的覆盖，为美团数亿用户带来便捷的生活体验，积极助力实体零售线上化转型，提升本地商业活力。\n\n岗位职责\n1.负责统筹所支持区域的资产管理工作，包括续约、换仓、租金或其他费用的优化等；\n2.处理前置仓的租赁合同在履行过程中发生的履约、纠纷、变更等工作；\n3.根据城市规划在计划开仓区域完成仓源储备及仓源复核，输出选址评审报告并完成开仓任务。\n4.负责前置仓租赁商务谈判、合同谈判、合同签约，基本工程条件的谈判以及风险评估；\n5.根据开仓指标达成情况可以做出分析和复盘，输出相关选址迭代标准及策略；\n\n岗位基本要求\n1.本科及以上学历；\n2.3年及以上零售拓展行业的相关工作经验，具备前置仓、便利店、街边店铺选址的工作经验者优先；\n3.较强的专业能力，能够独立完成选址评估、谈判、签约及进场工作；\n4.掌握与租赁合同相关的基本法律、法规问题，与房东洽谈时能够辨别和规避法律风险、保障公司权益；\n5.掌握基本的工程常识，做选址评估时能够辨别较为明显的工程隐患；\n6.较强的沟通、谈判、协调能力，具备一定的谈判技巧及处理公共关系的能力；\n7. 有较强的自我驱动力、学习能力，对新零售有一定了解。\n8.能接受无固定城市长期出差的工作。\n\n具备以下条件优先\n1.从事过前置仓/酒水行业线下选址规划工作。\n2.擅长通过部门协同达成项目目标。\n3.独立完成过2个以上或多个城市选址开发工作。\n\n岗位亮点\n1. 歪马业务聚焦于酒类万亿市场，通过前置仓+中心仓、平台自营模式，为用户提供 15分钟送达的买酒服务；\n2.团队氛围轻松，融洽，个人成长空间大。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4406478938","sourceKey":"meituan_social","company":"美团","title":"销售数据分析师","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4406478938&jobShareType=1","duty":"1. 快速理解业务需求，负责业务指标设计、口径制定及基础数据工具建设。  \n2. 负责专项分析与业绩复盘，识别业务机会、拆解异动原因，并输出可落地的业务指导建议。  \n3. 梳理业务监测指标体系，沉淀常规分析方法，建设配套数据产品以提升业务工作效率。  \n4. 结合业务目标与策略，自上而下拆解目标，持续优化目标分配逻辑，提升拆解合理性。","requirements":"1. 具备3年以上互联网数据分析工作经验，至少主导3个完整的数据分析项目，能独立承担分析任务。  \n2. 熟练掌握SQL、Python或R等数据分析工具，具备扎实的数据处理、分析与报告呈现能力。 且能使用AI工具提效，包括但不限于能使用AI工具完成数据提取、处理、业务分析、报告撰写等工作。 \n3. 具备较强的商业敏感度、分析能力及结论输出能力，能独立完成数据分析与报告撰写，学习意愿强，沟通协调能力佳，善于结合业务细节推动数据应用落地。  \n4. 硕士研究生学历，统计、数学、计算机、信息管理等相关专业优先。","description":"部门介绍\n美团酒店旅行业务涵盖酒店、民宿、机票、火车票、旅游度假、景点门票等各类住行游品类，通过与产业上下游的深度合作，为用户提供美好的旅游旅行体验。我们积极打造AI友好型组织，使用AI等新技术提升旅游服务的供需匹配效率，更好满足用户个性化、多样化的出游需求。我们持续深耕产业链，用数字化服务助力实体商家高质量经营，探索自有品牌等供给新模式，打造健康的商家生态，保障用户服务体验。为满足用户日益增长的跨境旅行需求，我们将聚焦亚太区域，打造高品质的住宿、交通、游玩等服务矩阵。\n这里有多元的业务布局、持续的成长空间，无论是向往的远方还是眼前的工作，一路都是风景相伴。加入我们，共同为用户创造旅游旅行中的高光时刻！\n\n岗位职责\n1. 快速理解业务需求，负责业务指标设计、口径制定及基础数据工具建设。  \n2. 负责专项分析与业绩复盘，识别业务机会、拆解异动原因，并输出可落地的业务指导建议。  \n3. 梳理业务监测指标体系，沉淀常规分析方法，建设配套数据产品以提升业务工作效率。  \n4. 结合业务目标与策略，自上而下拆解目标，持续优化目标分配逻辑，提升拆解合理性。\n\n岗位基本要求\n1. 具备3年以上互联网数据分析工作经验，至少主导3个完整的数据分析项目，能独立承担分析任务。  \n2. 熟练掌握SQL、Python或R等数据分析工具，具备扎实的数据处理、分析与报告呈现能力。 且能使用AI工具提效，包括但不限于能使用AI工具完成数据提取、处理、业务分析、报告撰写等工作。 \n3. 具备较强的商业敏感度、分析能力及结论输出能力，能独立完成数据分析与报告撰写，学习意愿强，沟通协调能力佳，善于结合业务细节推动数据应用落地。  \n4. 硕士研究生学历，统计、数学、计算机、信息管理等相关专业优先。\n\n具备以下条件优先\n1. 学习意愿强，有好奇心，主动性高，注重自我持续成长。\n2. 熟悉美团NoCode平台或类似低代码/无代码工具（如“龙虾”），能够独立完成数据看板搭建、流程自动化、基础分析等任务。\n\n岗位亮点\n1. 项目机会丰富，深度参与业务策略制定，个人成长与发展空间广阔。  \n2. 拥有成熟的培养体系，助力员工快速上手，在实践中提升专业技能与业务理解力。  \n3. 团队氛围开放包容，鼓励独立思考与表达，支持创新与协作。\n4.有丰富的AI工具实践机会。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4706027665","sourceKey":"meituan_social","company":"美团","title":"渠道经理","city":"银川市/乌鲁木齐市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4706027665&jobShareType=1","duty":"1. 对所辖区域电单车渠道合作商日常管理和业务运营管理，承担经营过程和结果指标的任务达成；\n2. 充分了解用户、市场等行业信息，制定有针对性的城市打法，指导渠道运营落地拿结果；\n3. 保持对政府良好合作关系，进行必要陪访，配合政策要求及时响应；\n4. 促进与渠道合作商负责人建立良好客情，帮其分析车辆点位、调度规律，制定合理运营计划，给出收益管理和人员管理建议，推动合作伙伴投入资源达成运营任务并更加盈利；\n5. 落地执行公司对商政策的传导，对商的选、育、用、励、汰负责。","requirements":"1. 本科学历，3年以上渠道开发、渠道管理经验，共享出行行业经验者优先；\n2. 学习能力强，对渠道管理模式有深刻认知或学习欲望，能激发合作商积极性，有管理方法论沉淀；\n3. 熟练使用电脑办公软件，商务沟通能力强，逻辑能力强，有良好文字功底；\n4. 热爱工作，接受挑战，有团队协作精神和服务意识；价值观正，诚实，责任心强；\n5. 具备很好的跨部门协同能力，能有效整合资源推进业务发展；\n6. 可接受出差。","description":"部门介绍\n美团骑行事业部在全国各个城市开展美团单车、电单车业务，提供绿色、便捷的共享出行服务，是美团出行板块重要的组成部分。我们力求为城市可持续发展提供低碳智能的解决方案，通过技术创新和硬件升级，不断优化全流程骑行体验，为低碳出行提供更好的服务。其中，美团单车旨在为城市居民提供通勤接驳服务，满足用户短途接驳出行需求；美团电单车则满足用户中短途多场景低碳出行需求。\n我们有开放的工作氛围，也有充满韧劲和创造力，心系低碳出行的伙伴。加入我们，一起为用户创造更好的出行体验。\n\n岗位职责\n1. 对所辖区域电单车渠道合作商日常管理和业务运营管理，承担经营过程和结果指标的任务达成；\n2. 充分了解用户、市场等行业信息，制定有针对性的城市打法，指导渠道运营落地拿结果；\n3. 保持对政府良好合作关系，进行必要陪访，配合政策要求及时响应；\n4. 促进与渠道合作商负责人建立良好客情，帮其分析车辆点位、调度规律，制定合理运营计划，给出收益管理和人员管理建议，推动合作伙伴投入资源达成运营任务并更加盈利；\n5. 落地执行公司对商政策的传导，对商的选、育、用、励、汰负责。\n\n岗位基本要求\n1. 本科学历，3年以上渠道开发、渠道管理经验，共享出行行业经验者优先；\n2. 学习能力强，对渠道管理模式有深刻认知或学习欲望，能激发合作商积极性，有管理方法论沉淀；\n3. 熟练使用电脑办公软件，商务沟通能力强，逻辑能力强，有良好文字功底；\n4. 热爱工作，接受挑战，有团队协作精神和服务意识；价值观正，诚实，责任心强；\n5. 具备很好的跨部门协同能力，能有效整合资源推进业务发展；\n6. 可接受出差。\n\n岗位亮点\n1. 良好的晋升空间和发展机会；\n2. 有机会接触和拓展不同地区市场；\n3. 具有竞争力的薪资福利和完善的培训体\n系。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4580776953","sourceKey":"meituan_social","company":"美团","title":"商业分析专家（仓配方向）","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4580776953&jobShareType=1","duty":"1、结合业界观点、竞争态势和战略方向，对物流运营策略、链路优化进行分析判断；\n2、剖析大仓生产、运输等履约环节策略执行中的问题，并拆解原因，为物流提供决策建议，支持业务团队达成关键目标；\n3、完善物流相关的业务数据模型、经营指标体系和分析框架，为业务指标异常提供预警、检测和解读；\n4、对物流上下游供应计划、前置仓到货等环节进行协同分析，沉淀数据和积累认知；\n5、支持物流相关组织各类经营分析项目。","requirements":"1、本科及以上学历，1~3年咨询或商业分析经验，有零售行业经验优先；\n2、熟练掌握商业分析的基本方法论，有较好的量化分析能力和数据驱动决策意识；\n3、逻辑思维能力出色，思路严谨缜密，理解能力、沟通表达能力和协调推进能力良好，业务敏感度强，热爱思考，自驱力强，学习能力强。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1、结合业界观点、竞争态势和战略方向，对物流运营策略、链路优化进行分析判断；\n2、剖析大仓生产、运输等履约环节策略执行中的问题，并拆解原因，为物流提供决策建议，支持业务团队达成关键目标；\n3、完善物流相关的业务数据模型、经营指标体系和分析框架，为业务指标异常提供预警、检测和解读；\n4、对物流上下游供应计划、前置仓到货等环节进行协同分析，沉淀数据和积累认知；\n5、支持物流相关组织各类经营分析项目。\n\n岗位基本要求\n1、本科及以上学历，1~3年咨询或商业分析经验，有零售行业经验优先；\n2、熟练掌握商业分析的基本方法论，有较好的量化分析能力和数据驱动决策意识；\n3、逻辑思维能力出色，思路严谨缜密，理解能力、沟通表达能力和协调推进能力良好，业务敏感度强，热爱思考，自驱力强，学习能力强。\n\n具备以下条件优先\n有零售、物流行业经验优先\n\n岗位亮点\n1、万亿零售市场，有机会参与并深入业务，深入了解零售业务；\n2、团队成员年轻化，氛围好；\n3、能够在分析领域不断提升自己，发展成为商业分析专家。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4708704120","sourceKey":"meituan_social","company":"美团","title":"CatPaw-Design全栈开发工程师","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4708704120&jobShareType=1","duty":"美团 Design Agent 团队致力于用 AI 重构从需求理解、方案生成、可视化编辑到研发交付的完整链路，让 AI 不只生成设计方案，还能产出可编辑、可运行、可落地的设计与代码资产。\n这是一个全栈开发岗位，工作范围覆盖前端渲染、可视化编辑、后端服务及 AI Agent 工程。当前阶段将重点参与 Design Agent 的前端技术攻坚，包括 MRN、MSC、H5、Native、Machpro 等方向的实时渲染能力建设，以及基于 Canvas 的可视化编辑器开发。\n\n1.参与 Design Agent 的全栈架构设计与开发，打通 AI 生成、任务执行、可视化编辑和多端渲染链路。\n2.建设 MRN、MSC、H5、Native、Machpro 等技术方向的实时渲染能力，解决多端适配、渲染一致性、性能和稳定性问题。\n3.开发基于 Canvas 的可视化编辑器，支持画布操作、节点编排、属性配置、实时预览和方案迭代。\n4.参与后端服务和 Agent 工程建设，包括方案管理、版本管理、任务编排、工具调用、状态持久化及异常恢复。\n5.探索 AI 在设计和研发流程中的实际应用，将重复性工作沉淀为工具或 Skill，提升团队交付效率。","requirements":"1.具备扎实的编程基础，熟悉 JavaScript、TypeScript，并掌握至少一门后端语言，如 Python、Go 或 Java。\n2.具备全栈开发和端到端交付能力，能够完成前端系统、后端服务、接口和数据存储等工作。\n3.熟悉 React、浏览器运行机制和前端工程化，有复杂交互系统、可视化系统或跨端应用开发经验。\n4.具备良好的系统设计和问题分析能力，重视代码质量、性能、稳定性与可维护性。\n5.对 AI 保持持续的热情和好奇心，认可 AI Native 的做事方式，愿意主动思考 AI 如何改变设计、研发和用户体验，并真正将 AI 应用于日常开发。\n6.不一定要求入职前已经熟悉 MRN、MSC、Native、Machpro 等全部技术栈，但希望你具备快速学习和解决陌生问题的能力，并有信心在 AI 的辅助下快速吃透相关技术。","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n美团 Design Agent 团队致力于用 AI 重构从需求理解、方案生成、可视化编辑到研发交付的完整链路，让 AI 不只生成设计方案，还能产出可编辑、可运行、可落地的设计与代码资产。\n这是一个全栈开发岗位，工作范围覆盖前端渲染、可视化编辑、后端服务及 AI Agent 工程。当前阶段将重点参与 Design Agent 的前端技术攻坚，包括 MRN、MSC、H5、Native、Machpro 等方向的实时渲染能力建设，以及基于 Canvas 的可视化编辑器开发。\n\n1.参与 Design Agent 的全栈架构设计与开发，打通 AI 生成、任务执行、可视化编辑和多端渲染链路。\n2.建设 MRN、MSC、H5、Native、Machpro 等技术方向的实时渲染能力，解决多端适配、渲染一致性、性能和稳定性问题。\n3.开发基于 Canvas 的可视化编辑器，支持画布操作、节点编排、属性配置、实时预览和方案迭代。\n4.参与后端服务和 Agent 工程建设，包括方案管理、版本管理、任务编排、工具调用、状态持久化及异常恢复。\n5.探索 AI 在设计和研发流程中的实际应用，将重复性工作沉淀为工具或 Skill，提升团队交付效率。\n\n岗位基本要求\n1.具备扎实的编程基础，熟悉 JavaScript、TypeScript，并掌握至少一门后端语言，如 Python、Go 或 Java。\n2.具备全栈开发和端到端交付能力，能够完成前端系统、后端服务、接口和数据存储等工作。\n3.熟悉 React、浏览器运行机制和前端工程化，有复杂交互系统、可视化系统或跨端应用开发经验。\n4.具备良好的系统设计和问题分析能力，重视代码质量、性能、稳定性与可维护性。\n5.对 AI 保持持续的热情和好奇心，认可 AI Native 的做事方式，愿意主动思考 AI 如何改变设计、研发和用户体验，并真正将 AI 应用于日常开发。\n6.不一定要求入职前已经熟悉 MRN、MSC、Native、Machpro 等全部技术栈，但希望你具备快速学习和解决陌生问题的能力，并有信心在 AI 的辅助下快速吃透相关技术。\n\n具备以下条件优先\n1.有 Canvas、WebGL、图形渲染或可视化编辑器开发经验。\n2.有 React Native、小程序、Native 或其他跨端开发经验。\n3.有 AI Agent、LLM 应用、MCP、Tool Calling 或 AI 编程工具实践经验。\n4.有设计系统、设计工具插件、设计稿转代码或实时协同系统建设经验。\n\n岗位亮点\n你将参与真实的 Design Agent 产品建设，面对的不是简单的模型调用，而是 AI 生成、多端实时渲染、可视化编辑和工程交付之间的系统性问题。岗位具有明确的全栈属性，同时能够深入参与 AI 如何改变设计和研发流程的探索与落地。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4663192300","sourceKey":"meituan_social","company":"美团","title":"电话商务拓展专员","city":"石家庄市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4663192300&jobShareType=1","duty":"1.负责电话销售业务的开拓和推广，完成销售目标。\n2.针对潜在客户进行电话拜访、沟通，了解客户需求并进行产品推介。\n3.负责与客户建立良好的业务关系，维护客户满意度。\n4.跟进销售进展，协助解决客户问题和投诉，并提供售后服务。\n5.协助上级完成团队销售业绩的达成。\n6.及时汇报工作进展和市场动态，提供有关销售和竞争对手的信息。","requirements":"1.大学本科及以上学历。\n2.具备1年以上电话销售或业务开发经验，熟悉销售流程和销售技巧。\n3.具备良好的沟通能力和说服能力，能够与不同背景的客户进行有效的沟通。\n4.具备良好的团队合作精神，能够积极配合团队完成销售目标。\n5.具备较强的学习能力和适应能力，能够快速掌握产品知识和市场信息。\n6.具备良好的适应能力，能够应对工作中的挑战和压力。","description":"部门介绍\n美团到餐事业部拥有美团历史悠久的餐饮团购业务，聚焦美团“零售+科技”战略，为数以万计的餐饮商户提供一站式营销服务，为广大消费者提供优质的消费体验。我们帮助餐饮商户沉淀口碑、获取用户、增加复购等，持续提升商户数字化经营水平，同时秉承着“帮大家吃得更好，生活更好”的使命，面向消费者提供丰富的产品和服务，帮助消费者更好地作出消费决策。\n我们有高效成熟的管理体系，还将为你提供全面的人才培养机制和广阔的成长空间。让我们一起创造更大的价值，帮助消费者吃得更好，商户经营得更好！\n\n岗位职责\n1.负责电话销售业务的开拓和推广，完成销售目标。\n2.针对潜在客户进行电话拜访、沟通，了解客户需求并进行产品推介。\n3.负责与客户建立良好的业务关系，维护客户满意度。\n4.跟进销售进展，协助解决客户问题和投诉，并提供售后服务。\n5.协助上级完成团队销售业绩的达成。\n6.及时汇报工作进展和市场动态，提供有关销售和竞争对手的信息。\n\n岗位基本要求\n1.大学本科及以上学历。\n2.具备1年以上电话销售或业务开发经验，熟悉销售流程和销售技巧。\n3.具备良好的沟通能力和说服能力，能够与不同背景的客户进行有效的沟通。\n4.具备良好的团队合作精神，能够积极配合团队完成销售目标。\n5.具备较强的学习能力和适应能力，能够快速掌握产品知识和市场信息。\n6.具备良好的适应能力，能够应对工作中的挑战和压力。\n\n岗位亮点\n1.提供丰富的电话销售经验，有机会与不同类型的客户进行沟通和合作。\n2.能够通过销售业绩的提升获得相应的晋升机会。\n3.工作地点位于石家庄市，为您提供便利的工作环境和生活条件。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4687345552","sourceKey":"meituan_social","company":"美团","title":"Keeta-CS 智能运营Intelligent Operations","city":"北京市/上海市/广州市/深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4687345552&jobShareType=1","duty":"智能化工具管理：负责智能客服机器人、自动化工具、自动外呼、智能IVR等自动化工具的运营、优化及升级。\n策略制定：基于客服站点需求，与产品、研发团队协作，制定智能化运营策略，推动智能化工具的迭代和实施，提升智能解决率、客户满意度及运营效率。\n数据监控与分析：分析智能工具的使用效果，监控关键指标（如智能解决率、客户转接率等），持续优化运营策略。\n培训支持：为客服团队提供智能工具使用培训，编写相关操作手册和指导文档，支持现场答疑。\n\nIntelligent Tools Management: Manage intelligent customer service tools, such as chatbots, intelligent tools, automated outbound calls, and intelligent IVR, ensuring their smooth operation and upgrades.\nStrategy Development: Collaborate with product and R&D teams to develop and implement intelligent operations strategies based on CE-Sites needs, improving resolution rates, customer satisfaction, and operational efficiency.\nData Monitoring and Analysis: Analyze tool usage and monitor key performance indicators (e.g., resolution rates, customer transfer rates), continuously optimizing operational strategies\nTraining and Support: Provide training on intelligent tool usage for the customer service team, develop relevant manuals and guidance documents, and offer on-site s","requirements":"具有5年以上智能工具运营经验。\n具有良好的跨部门协调能力，擅长项目管理、建立并优化机制。\n具有良好的执行能力和一定的策略制定能力，有效推动智能服务产品工具的落地运营。\n能熟练运用英文沟通，有良好的学习能力。\n\nAt least 5 years of experience in operating intelligent tools.\nStrong cross-department coordination skills, with expertise in project management and establishing and optimizing processes.\nProven execution capability and strategic planning skills to effectively drive the implementation and operation of intelligent service tools.\nProficient in English communication with strong learning abilities.","description":"部门介绍\nKeeta是全球领先外卖平台美团旗下的独立品牌，肩负着“帮大家吃得更好，生活更好”的使命。依托美团深耕中国市场15年的技术与运营积淀，我们正引领全球餐饮与商品即时配送服务的创新与发展。\n\n自2023年成立以来，Keeta始终扎根社区并创造价值。我们为用户提供可靠的外卖体验，以智慧技术助餐厅提升经营效率，在为骑手拓宽收入来源的同时，也充分提供安全保障措施。基于这份多方共赢、共同成长的理念，我们的业务已从中国香港稳步拓展至中东及巴西，并持续向世界迈进。\n\n岗位职责\n智能化工具管理：负责智能客服机器人、自动化工具、自动外呼、智能IVR等自动化工具的运营、优化及升级。\n策略制定：基于客服站点需求，与产品、研发团队协作，制定智能化运营策略，推动智能化工具的迭代和实施，提升智能解决率、客户满意度及运营效率。\n数据监控与分析：分析智能工具的使用效果，监控关键指标（如智能解决率、客户转接率等），持续优化运营策略。\n培训支持：为客服团队提供智能工具使用培训，编写相关操作手册和指导文档，支持现场答疑。\n\nIntelligent Tools Management: Manage intelligent customer service tools, such as chatbots, intelligent tools, automated outbound calls, and intelligent IVR, ensuring their smooth operation and upgrades.\nStrategy Development: Collaborate with product and R&D teams to develop and implement intelligent operations strategies based on CE-Sites needs, improving resolution rates, customer satisfaction, and operational efficiency.\nData Monitoring and Analysis: Analyze tool usage and monitor key performance indicators (e.g., resolution rates, customer transfer rates), continuously optimizing operational strategies\nTraining and Support: Provide training on intelligent tool usage for the customer service team, develop relevant manuals and guidance documents, and offer on-site s\n\n岗位基本要求\n具有5年以上智能工具运营经验。\n具有良好的跨部门协调能力，擅长项目管理、建立并优化机制。\n具有良好的执行能力和一定的策略制定能力，有效推动智能服务产品工具的落地运营。\n能熟练运用英文沟通，有良好的学习能力。\n\nAt least 5 years of experience in operating intelligent tools.\nStrong cross-department coordination skills, with expertise in project management and establishing and optimizing processes.\nProven execution capability and strategic planning skills to effectively drive the implementation and operation of intelligent service tools.\nProficient in English communication with strong learning abilities.\n\n岗位亮点\n在 Keeta，你将亲历美团全球扩张的宏伟蓝图，见证行业影响力从中国走向世界，积累开拓全球市场的实战经验，拓宽你的国际化视野。\nAt Keeta, you'll be part of Meituan's ambitious global expansion journey, witnessing the industry's influence extend from China to the world. You'll gain hands-on experience in navigating global markets and broaden your international perspective.","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4691284347","sourceKey":"meituan_social","company":"美团","title":"浣熊食堂-选址规划专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4691284347&jobShareType=1","duty":"1、基于线上数据及线下调研情况，制定各城市的网络布局规划，划定各商圈的拓展优先级，输出店型匹配建议；\n2、针对已有门店布局及运营数据进行定期复盘，持续优化选址策略；\n3、梳理选址规划的策略、标准、流程，推动产品工具的建设，提高选址的效率和准确性；\n4、协同开发团队完成开店目标。","requirements":"1、5年以上门店选址规划、网络规划、商业地产分析经验；\n2、具备新零售、餐饮、便利店业态的选址规划经验；\n3、精通数据分析与建模，熟悉各类选址、数据分析、AI工具；\n4、理解消费者需求、竞争格局、商业模式，能够将数据分析转化为战略决策。","description":"部门介绍\n美团外卖秉承“帮大家吃得更好，生活更好”的使命，始终聚焦于消费者用餐需求。我们通过科技连接消费者和商家，依托庞大的骑手团队，以“线上+线下”的业务模式，为消费者提供品质化、精细化、多样化的餐饮外卖服务。\n外卖事业部是为用户与商家提供全链路交易服务的业务组织，围绕餐饮外卖搭建了包含外卖业务与创新孵化业务在内的多个部门。\n我们的目标是帮助商家开源增收、提高经营效率，促进餐饮行业数字化，以及为更多用户提供更便捷更有品质的外卖服务。加入我们，一起为上亿用户提供更好的用餐体验，帮助大家吃得更好，生活更好！\n\n岗位职责\n1、基于线上数据及线下调研情况，制定各城市的网络布局规划，划定各商圈的拓展优先级，输出店型匹配建议；\n2、针对已有门店布局及运营数据进行定期复盘，持续优化选址策略；\n3、梳理选址规划的策略、标准、流程，推动产品工具的建设，提高选址的效率和准确性；\n4、协同开发团队完成开店目标。\n\n岗位基本要求\n1、5年以上门店选址规划、网络规划、商业地产分析经验；\n2、具备新零售、餐饮、便利店业态的选址规划经验；\n3、精通数据分析与建模，熟悉各类选址、数据分析、AI工具；\n4、理解消费者需求、竞争格局、商业模式，能够将数据分析转化为战略决策。\n\n具备以下条件优先\n了解AI在选址中的应用场景，具备相关项目经验\n\n岗位亮点\n浣熊食堂是处于高速发展期的创新业务，发展前景大、管理扁平、团队氛围融洽。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4166342899","sourceKey":"meituan_social","company":"美团","title":"闪购-品类增长运营","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4166342899&jobShareType=1","duty":"1. 负责闪购重点品类的运营与增长，为品类交易规模及效率指标负责；\n2. 基于用户需求与购买路径分析，制定补贴策略，整合营销资源，提升品类各渠道转化效率；\n3. 构建品类货盘分层体系，通过选品、定价及商家协同策略，持续优化供给结构与丰富度；\n4. 洞察行业趋势与竞争变化，制定品类增长策略并推动落地，沉淀方法论驱动团队认知升级；\n5. 善用AI工具探索新运营方法，包括但不限于数据分析、选品洞察、策略生成复盘与日常提效等。","requirements":"1. 本科及以上学历，3年以上电商/即时零售行业经验，有品类运营或商品运营经验优先；\n2. 有独立负责策略从制定到落地的完整经验，具备跨团队协同推动项目的能力，以结果为导向；\n3. 对零售、商品逻辑或营销方法有较深理解，具备行业敏感度和商业判断力；\n4. 具备较强的数据分析能力，熟练使用SQL及常用分析工具，能用数据驱动业务决策；\n5. 自驱力强，善于学习新工具新方法（尤其AI工具的业务应用）。","description":"部门介绍\n美团闪购是美团旗下的即时零售平台，依托即时配送能力，连接本地零售供给，满足消费者30分钟万物到家的即时需求。美团闪购涵盖超市便利、食材、水果、鲜花绿植、休闲零食、酒水饮料、数码家电、美妆个护、母婴玩具、日用百货、服饰鞋帽、宠物等诸多品类，业务覆盖全国近3,000个县市区旗，每日百万级在岗骑手，以高效的配送、丰富的品类和广泛的覆盖，为美团数亿用户带来便捷的生活体验，积极助力实体零售线上化转型，提升本地商业活力。\n\n岗位职责\n1. 负责闪购重点品类的运营与增长，为品类交易规模及效率指标负责；\n2. 基于用户需求与购买路径分析，制定补贴策略，整合营销资源，提升品类各渠道转化效率；\n3. 构建品类货盘分层体系，通过选品、定价及商家协同策略，持续优化供给结构与丰富度；\n4. 洞察行业趋势与竞争变化，制定品类增长策略并推动落地，沉淀方法论驱动团队认知升级；\n5. 善用AI工具探索新运营方法，包括但不限于数据分析、选品洞察、策略生成复盘与日常提效等。\n\n岗位基本要求\n1. 本科及以上学历，3年以上电商/即时零售行业经验，有品类运营或商品运营经验优先；\n2. 有独立负责策略从制定到落地的完整经验，具备跨团队协同推动项目的能力，以结果为导向；\n3. 对零售、商品逻辑或营销方法有较深理解，具备行业敏感度和商业判断力；\n4. 具备较强的数据分析能力，熟练使用SQL及常用分析工具，能用数据驱动业务决策；\n5. 自驱力强，善于学习新工具新方法（尤其AI工具的业务应用）。\n\n岗位亮点\n1. 参与平台核心增长业务，直接影响千万级用户购物体验。   \n2. 扁平化管理，快速成长通道，独立负责业务模块。  \n3. 团队氛围开放，鼓励创新，支持前沿业务模式探索。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4695203399","sourceKey":"meituan_social","company":"美团","title":"PC加工主管","city":"天津市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4695203399&jobShareType=1","duty":"1、负责排产、排班、出勤计划执行，加工进度管控、每日订单目标交付达成；\n2、负责加工过程中人员组台、品类拆分、原料进度追踪、异常协调等业务；\n3、负责加工品质保障、加工数据准确性管理、上下游入库准确性管理；\n4、负责设备高效使用，员工积极性策略推动与执行；\n5、负责加工区域6S、生产安全、消防安全、食品安全等管理；\n6、负责促成部门各指标达成（品质、原料成本、人力成本、员工留存等）\n7、负责班次团队组织架构搭建、招聘计划、人员培养汰换，每日生产会议。","requirements":"1.具备物流或仓储相关领域的大学专科及以上学历。\n2.至少3年以上物流或仓储管理经验，有生鲜加工管理经验者优先考虑。\n3.熟悉生鲜产品的质量标准和加工工艺，具备相关品控知识。\n4.具备较好的团队管理能力，能够激励团队成员，提高工作效率。\n5.具备良好的沟通协调能力，能够与不同部门和供应商进行有效的合作。\n6.具备一定的问题解决能力和应变能力，能够灵活应对工作中的各种挑战。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1、负责排产、排班、出勤计划执行，加工进度管控、每日订单目标交付达成；\n2、负责加工过程中人员组台、品类拆分、原料进度追踪、异常协调等业务；\n3、负责加工品质保障、加工数据准确性管理、上下游入库准确性管理；\n4、负责设备高效使用，员工积极性策略推动与执行；\n5、负责加工区域6S、生产安全、消防安全、食品安全等管理；\n6、负责促成部门各指标达成（品质、原料成本、人力成本、员工留存等）\n7、负责班次团队组织架构搭建、招聘计划、人员培养汰换，每日生产会议。\n\n岗位基本要求\n1.具备物流或仓储相关领域的大学专科及以上学历。\n2.至少3年以上物流或仓储管理经验，有生鲜加工管理经验者优先考虑。\n3.熟悉生鲜产品的质量标准和加工工艺，具备相关品控知识。\n4.具备较好的团队管理能力，能够激励团队成员，提高工作效率。\n5.具备良好的沟通协调能力，能够与不同部门和供应商进行有效的合作。\n6.具备一定的问题解决能力和应变能力，能够灵活应对工作中的各种挑战。\n\n具备以下条件优先\n互联网公司经验、生鲜仓储或果蔬加工作经验、熟悉生鲜品类特性（蔬菜、水果、净菜加工等）\n\n岗位亮点\n1、公司业务发展快，晋升空间大；\n2、公司有定期培训，学习机会多，个人成长速度快；\n具备以下优先:\n有食品加工或生鲜加工管理经验优先。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4701960271","sourceKey":"meituan_social","company":"美团","title":"Agent稳定性测试工程师","city":"北京市/成都市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4701960271&jobShareType=1","duty":"负责 CatPaw Agent 稳定性测试和评测体系建设，设计并实现覆盖 Skill/Plugin、工具调用、端到端任务完成度的评测框架与自动化测试基建，支撑模型与策略选型决策，以及持续量化并提升开发者体验。\n面向 CatPaw 多智能体集群构建运行时评测能力，针对路由调度、会话管理、记忆系统等模块设计场景化用例集与回归基线，识别多轮长链路下的能力衰减与稳定性风险。\n主导长程任务 harness 效果评估工作，围绕Prompt 工程、tool Calling 、上下文管理、以及memory能力建立指标体系，评测驱动Agent持续优化。\n主导CatPaw Agent产品需求交付质量保障、AI自动化测试开发，保障Agent产品的高质量高效上线。\n覆盖 IM/社交/办公等多端渠道及浏览器自动化场景的真实链路验收，badcase分析，沉淀可复用的场景数据集与自动化巡检能力，推动线上质量可观测，以及数据飞轮建设。\n参与安全与合规评测，针对多租户权限隔离、数据沙箱、越权与提示注入等风险构建红队用例与对抗性评测方案，保障系统安全性与稳定性。","requirements":"大学本科及以上学历，3 年以上研发或质量工程经验，精通 TypeScript/Node.js 或 Python，具备较强的工程实现能力。\n重度 AI Coding 用户，熟练使用 CatPaw/NoCode/Cursor/CC/CodeX 等 AI 编程工具完成日常开发与评测脚本建设。\n深入理解 LLM 应用开发，掌握 Prompt 设计、Tool Use、RAG 等核心技术，理解其常见失效模式与对应的评估手段。\n熟悉大模型评测方法论，包括自动化评测、LLM-as-a-Judge、人工标注与抽样、A/B 实验与统计显著性判断，能设计出可复现、低噪声的评测流程。\n具备平台或框架级系统设计能力，能独立完成评测平台核心模块的架构与实现，并推动数据驱动的质量改进落地。\n具备自驱力，善于与 AI 协作，主动探索技术边界并推动结论转化为产品迭代。","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n负责 CatPaw Agent 稳定性测试和评测体系建设，设计并实现覆盖 Skill/Plugin、工具调用、端到端任务完成度的评测框架与自动化测试基建，支撑模型与策略选型决策，以及持续量化并提升开发者体验。\n面向 CatPaw 多智能体集群构建运行时评测能力，针对路由调度、会话管理、记忆系统等模块设计场景化用例集与回归基线，识别多轮长链路下的能力衰减与稳定性风险。\n主导长程任务 harness 效果评估工作，围绕Prompt 工程、tool Calling 、上下文管理、以及memory能力建立指标体系，评测驱动Agent持续优化。\n主导CatPaw Agent产品需求交付质量保障、AI自动化测试开发，保障Agent产品的高质量高效上线。\n覆盖 IM/社交/办公等多端渠道及浏览器自动化场景的真实链路验收，badcase分析，沉淀可复用的场景数据集与自动化巡检能力，推动线上质量可观测，以及数据飞轮建设。\n参与安全与合规评测，针对多租户权限隔离、数据沙箱、越权与提示注入等风险构建红队用例与对抗性评测方案，保障系统安全性与稳定性。\n\n岗位基本要求\n大学本科及以上学历，3 年以上研发或质量工程经验，精通 TypeScript/Node.js 或 Python，具备较强的工程实现能力。\n重度 AI Coding 用户，熟练使用 CatPaw/NoCode/Cursor/CC/CodeX 等 AI 编程工具完成日常开发与评测脚本建设。\n深入理解 LLM 应用开发，掌握 Prompt 设计、Tool Use、RAG 等核心技术，理解其常见失效模式与对应的评估手段。\n熟悉大模型评测方法论，包括自动化评测、LLM-as-a-Judge、人工标注与抽样、A/B 实验与统计显著性判断，能设计出可复现、低噪声的评测流程。\n具备平台或框架级系统设计能力，能独立完成评测平台核心模块的架构与实现，并推动数据驱动的质量改进落地。\n具备自驱力，善于与 AI 协作，主动探索技术边界并推动结论转化为产品迭代。\n\n具备以下条件优先\n有 Agent 平台、AI-IDE 或 CLI 工具链的评测/质量保障经验。\n熟悉浏览器自动化技术（如 Playwright/CDP），能用于构建端到端评测与线上巡检。\n参与过公开或自建 Benchmark（如 SWE-bench、AgentBench、GAIA 类任务集）的建设、复现或评测数据集标注。\n负责过Agent产品：WorkBuddy、QoderWork、Claude的测试质量保障工作\n搭建过 AI 助理并投入日常使用，对 Agent 的真实体验瓶颈有及时判断。\n\n岗位亮点\n参与构建下一代 AI Agent 开发框架的评测标准与质量体系，结论直接影响框架演进方向，技术影响力广泛。\n深度使用 AI 工具进行开发与评测，鼓励高效人机协作。\n与前沿 AI 技术团队共同探索多智能体系统、浏览器自动化等创新方向的评估难题。\n扁平化工作环境，支持技术自主决策与快速迭代。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4688178782","sourceKey":"meituan_social","company":"美团","title":"渠道经营策略专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4688178782&jobShareType=1","duty":"直接支持部门负责人，作为部门重点项目的“经营视角”和“第二双眼睛”。\n\n围绕项目的目标、策略、资源投入、执行过程和经营结果进行独立审视，及时发现问题、挑战结论、推动纠偏，并将个别项目的问题沉淀为组织机制，持续提高部门项目策略与经营管理的标准。\n\n1、重点项目经营审计\n\n对部门重点项目进行全生命周期审视，包括目标合理性、策略完整性、数据口径、资源投入、关键里程碑、投入产出、风险依赖和结果真实性等。\n独立验证项目的重要数据和关键结论，及时识别目标模糊、策略缺失、指标失真、进度虚高、资源浪费、风险后置等问题。\n\n2、提升项目策略质量\n\n参与重点项目立项及策略评审，追问目标依据、核心假设、关键证据、备选方案和验证路径，推动项目从“有动作”升级为“有策略、有验证、有结果”。\n对重要策略提出独立判断和改进建议，持续提升部门项目方案的完整性与决策质量。\n\n3、建立经营管理机制\n\n建立并维护重点项目分级、经营看板、红黄灯预警、问题台账、周月度复盘等机制，帮助管理者及时掌握真实经营状态。\n推动经营信息和项目数据自动化采集，减少重复填表和材料汇报，让经营管理更加简单、真实、高效。\n\n4、推动问题解决与项目闭环\n\n对识别出的问题明确责任人、解决方案、完成时间和验收标准，持续跟进直至真正闭环。\n对跨团队依赖、长期悬而未决或可能影响经营结果的问题，及时组织协调、升级风险并推动决策。\n\n5、沉淀流程、制度与方法\n\n从单个项目问题中识别共性原因，推动完善相关流程、制度、决策标准、项目模板和复盘机制，降低同类问题反复发生的概率。\n定期评估现有制度的有效性，避免流程空转、制度僵化以及为了合规而合规。","requirements":"1、战略运营、经营分析、业务运营、战略PMO、总经办、管理咨询或内部经营管理相关经验。\n\n2、数据敏感度高，能够识别指标口径、数据归因和业务结论中的漏洞，并通过数据、事实和逻辑验证判断。\n\n3、具备较强的问题意识和独立性，敢于提出不同意见，能够挑战不合理的目标、策略和结论，不回避真实问题。\n\n4、具有很强的推动力和结果意识，能够在复杂协作关系中持续推动问题解决，同时保持建设性的合作关系。\n\n5、有大型互联网平台、多业务线协同、用户增长、广告投放、渠道经营或复杂项目管理经验者优先。熟悉数据分析、经营看板及AI效率工具，具备经营管理自动化实践经验者优先。","description":"部门介绍\n美团平台为用户的基础产品体验负责，还承担了美团的用户增长、市场和品牌营销以及多条业务线的产品设计职责，建立了融合文字、图片、视频和直播等不同形式的內容生态系统，同时整合地图服务部、客户服务和体验部、企业业务部、网约车业务部等部门，致力于用科技提升美团数亿消费者、近千万商家、骑手、司机和团长的服务体验。美团平台拥有高并发、多业务的复杂场景，为技术深度优化提供了最佳实践可能。这里有简单、讲逻辑、有爱的团队，更是一块理想的实战场地，舞台广阔，欢迎你来尽情施展。\n\n岗位职责\n直接支持部门负责人，作为部门重点项目的“经营视角”和“第二双眼睛”。\n\n围绕项目的目标、策略、资源投入、执行过程和经营结果进行独立审视，及时发现问题、挑战结论、推动纠偏，并将个别项目的问题沉淀为组织机制，持续提高部门项目策略与经营管理的标准。\n\n1、重点项目经营审计\n\n对部门重点项目进行全生命周期审视，包括目标合理性、策略完整性、数据口径、资源投入、关键里程碑、投入产出、风险依赖和结果真实性等。\n独立验证项目的重要数据和关键结论，及时识别目标模糊、策略缺失、指标失真、进度虚高、资源浪费、风险后置等问题。\n\n2、提升项目策略质量\n\n参与重点项目立项及策略评审，追问目标依据、核心假设、关键证据、备选方案和验证路径，推动项目从“有动作”升级为“有策略、有验证、有结果”。\n对重要策略提出独立判断和改进建议，持续提升部门项目方案的完整性与决策质量。\n\n3、建立经营管理机制\n\n建立并维护重点项目分级、经营看板、红黄灯预警、问题台账、周月度复盘等机制，帮助管理者及时掌握真实经营状态。\n推动经营信息和项目数据自动化采集，减少重复填表和材料汇报，让经营管理更加简单、真实、高效。\n\n4、推动问题解决与项目闭环\n\n对识别出的问题明确责任人、解决方案、完成时间和验收标准，持续跟进直至真正闭环。\n对跨团队依赖、长期悬而未决或可能影响经营结果的问题，及时组织协调、升级风险并推动决策。\n\n5、沉淀流程、制度与方法\n\n从单个项目问题中识别共性原因，推动完善相关流程、制度、决策标准、项目模板和复盘机制，降低同类问题反复发生的概率。\n定期评估现有制度的有效性，避免流程空转、制度僵化以及为了合规而合规。\n\n岗位基本要求\n1、战略运营、经营分析、业务运营、战略PMO、总经办、管理咨询或内部经营管理相关经验。\n\n2、数据敏感度高，能够识别指标口径、数据归因和业务结论中的漏洞，并通过数据、事实和逻辑验证判断。\n\n3、具备较强的问题意识和独立性，敢于提出不同意见，能够挑战不合理的目标、策略和结论，不回避真实问题。\n\n4、具有很强的推动力和结果意识，能够在复杂协作关系中持续推动问题解决，同时保持建设性的合作关系。\n\n5、有大型互联网平台、多业务线协同、用户增长、广告投放、渠道经营或复杂项目管理经验者优先。熟悉数据分析、经营看板及AI效率工具，具备经营管理自动化实践经验者优先。\n\n岗位亮点\n1、直接参与核心经营决策\n\n直接支持部门负责人，深入参与部门重点项目和关键经营议题，拥有较高的信息密度和业务视野。岗位不以收材料、排会议、催进度为核心，而是对项目策略、经营质量和结果真实性拥有独立审视权。\n\n2、覆盖完整经营链路\n\n工作范围涵盖战略判断、项目立项、资源投入、过程管理、经营审计、结果复盘和机制建设，能够建立完整的经营管理能力。拥有真实的组织影响力，不仅解决单个项目问题，还能通过流程、制度和经营机制建设，持续提升整个部门的项目管理与策略标准。\n\n3、有机会从0到1建设经营体系\n\n包括重点项目管理机制、经营看板、项目审计标准、复盘体系以及AI驱动的经营管理工具。\n\n4、清晰的成长空间\n\n可进一步成长为部门经营负责人、战略运营负责人、业务管理负责人或综合经营管理者。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4702721745","sourceKey":"meituan_social","company":"美团","title":"美团会员权益运营","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4702721745&jobShareType=1","duty":"深入理解联合会员及高价值用户需求，将其转化为商家经营方案。通过长期服务核心商家，帮助商家做好会员经营，并获得有竞争力、可持续的会员权益。\n\n职责包括\n1、负责会员专属价、会员神券、排队加速等权益的商家合作与供给建设，制定商家分层及招商策略。\n2、洞察联合会员的消费特征和核心需求，结合商家的品牌定位与经营目标，设计双方认可的权益合作方案。\n3、长期服务核心品牌，帮助商家提升高价值用户的获取、转化与经营效率，深化商家与平台的合作关系。\n4、通过数据分析、用户研究和商家调研发现经营问题，协调产品、销售、运营等团队推动方案落地并复盘效果。\n5、沉淀商家诊断、方案设计、权益谈判和运营复盘等标准化方法，并运用AI工具提升分析、方案生产及招商协同效率。","requirements":"1、本科及以上学历，5年及以上会员运营、用户运营、商业运营或大客户经营经验；有本地生活、餐饮、零售或互联网平台经验者优先。\n2、对会员经营有深入理解，能够将用户需求转化为清晰的商家价值和经营方案。\n3、具备商家经营意识，能够从长期服务和解决问题的角度建立合作关系，而非只完成一次性招商。\n4、能够独立负责核心品牌或复杂项目，完成问题诊断、方案设计、商务沟通、协同落地及结果复盘。\n5、具备较强的数据分析、用户洞察、沟通谈判和跨团队推动能力，能使用数据但不盲从数据。\n6、对消费及餐饮行业有兴趣，自驱、坚韧，能够持续推进模糊复杂的问题。\n7、熟悉主流AI工具，并有将其用于数据分析、用户研究或运营提效的实践经验。","description":"部门介绍\n美团平台为用户的基础产品体验负责，还承担了美团的用户增长、市场和品牌营销以及多条业务线的产品设计职责，建立了融合文字、图片、视频和直播等不同形式的內容生态系统，同时整合地图服务部、客户服务和体验部、企业业务部、网约车业务部等部门，致力于用科技提升美团数亿消费者、近千万商家、骑手、司机和团长的服务体验。美团平台拥有高并发、多业务的复杂场景，为技术深度优化提供了最佳实践可能。这里有简单、讲逻辑、有爱的团队，更是一块理想的实战场地，舞台广阔，欢迎你来尽情施展。\n\n岗位职责\n深入理解联合会员及高价值用户需求，将其转化为商家经营方案。通过长期服务核心商家，帮助商家做好会员经营，并获得有竞争力、可持续的会员权益。\n\n职责包括\n1、负责会员专属价、会员神券、排队加速等权益的商家合作与供给建设，制定商家分层及招商策略。\n2、洞察联合会员的消费特征和核心需求，结合商家的品牌定位与经营目标，设计双方认可的权益合作方案。\n3、长期服务核心品牌，帮助商家提升高价值用户的获取、转化与经营效率，深化商家与平台的合作关系。\n4、通过数据分析、用户研究和商家调研发现经营问题，协调产品、销售、运营等团队推动方案落地并复盘效果。\n5、沉淀商家诊断、方案设计、权益谈判和运营复盘等标准化方法，并运用AI工具提升分析、方案生产及招商协同效率。\n\n岗位基本要求\n1、本科及以上学历，5年及以上会员运营、用户运营、商业运营或大客户经营经验；有本地生活、餐饮、零售或互联网平台经验者优先。\n2、对会员经营有深入理解，能够将用户需求转化为清晰的商家价值和经营方案。\n3、具备商家经营意识，能够从长期服务和解决问题的角度建立合作关系，而非只完成一次性招商。\n4、能够独立负责核心品牌或复杂项目，完成问题诊断、方案设计、商务沟通、协同落地及结果复盘。\n5、具备较强的数据分析、用户洞察、沟通谈判和跨团队推动能力，能使用数据但不盲从数据。\n6、对消费及餐饮行业有兴趣，自驱、坚韧，能够持续推进模糊复杂的问题。\n7、熟悉主流AI工具，并有将其用于数据分析、用户研究或运营提效的实践经验。\n\n具备以下条件优先\n1、有联合会员、付费会员或高价值用户运营经验；\n2、有核心餐饮品牌、大客户或战略商家经营经验；\n3、有会员权益招商或平台与品牌联合运营经验。\n\n岗位亮点\n1、深度参与美团到餐联合会员及高价值用户经营；\n2、以长期经营核心商家为主，不是传统的一次性招商岗位；\n3、作为高级个人贡献者，独立负责重要品牌和复杂项目。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4701989120","sourceKey":"meituan_social","company":"美团","title":"美团联盟行业运营（到店方向）","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4701989120&jobShareType=1","duty":"1、行业运营：上下游对接本地生活业务团队及联盟渠道团队，负责相应业务在美团联盟的预算管理、资源分配、上下游协同\n2、供给及招商运营：包括供给价格策略、流量分发策略、渠道定价策略，以及过程监控、效果复盘、策略调优\n3、营销活动运营：负责统筹相关行业在联盟的大促/营销活动策划、资源调动、策略变更及全流程跟进\n4、产品建设：推进相关行业所需资源在联盟的产品/工具建设\n5、AI推进：负责相关AI工作流推进，包括预算申请全流程、营销活动全流程、招商策略全流程等","requirements":"1.大学本科及以上学历，具备3年以上用户运营/流量运营/策略运营的经验；\n2.具备出色的数据分析和沟通协调能力，有责任心和使命感；\n3.对AI赋能运营有强烈兴趣和实践认知，了解大模型（LLM）、智能体（Agent）、自动化工作流等AI技术在运营场景中的应用方向","description":"部门介绍\n美团平台为用户的基础产品体验负责，还承担了美团的用户增长、市场和品牌营销以及多条业务线的产品设计职责，建立了融合文字、图片、视频和直播等不同形式的內容生态系统，同时整合地图服务部、客户服务和体验部、企业业务部、网约车业务部等部门，致力于用科技提升美团数亿消费者、近千万商家、骑手、司机和团长的服务体验。美团平台拥有高并发、多业务的复杂场景，为技术深度优化提供了最佳实践可能。这里有简单、讲逻辑、有爱的团队，更是一块理想的实战场地，舞台广阔，欢迎你来尽情施展。\n\n岗位职责\n1、行业运营：上下游对接本地生活业务团队及联盟渠道团队，负责相应业务在美团联盟的预算管理、资源分配、上下游协同\n2、供给及招商运营：包括供给价格策略、流量分发策略、渠道定价策略，以及过程监控、效果复盘、策略调优\n3、营销活动运营：负责统筹相关行业在联盟的大促/营销活动策划、资源调动、策略变更及全流程跟进\n4、产品建设：推进相关行业所需资源在联盟的产品/工具建设\n5、AI推进：负责相关AI工作流推进，包括预算申请全流程、营销活动全流程、招商策略全流程等\n\n岗位基本要求\n1.大学本科及以上学历，具备3年以上用户运营/流量运营/策略运营的经验；\n2.具备出色的数据分析和沟通协调能力，有责任心和使命感；\n3.对AI赋能运营有强烈兴趣和实践认知，了解大模型（LLM）、智能体（Agent）、自动化工作流等AI技术在运营场景中的应用方向\n\n具备以下条件优先\n1.有本地生活工作经验优先；\n2.有供给策略/招商策略经验优先；\n3.有AI工具落地运营场景经验者优先\n\n岗位亮点\n1.作为业务-供给-流量的枢纽，锻炼上游业务视角、下游渠道及用户视角，成长空间大\n2.参与招商、AI等重点项目，沉淀复杂项目经验","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4686503492","sourceKey":"meituan_social","company":"美团","title":"小象-南昌水产仓运输主管","city":"南昌市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4686503492&jobShareType=1","duty":"1. 承运商与车辆管理：负责合作车辆、承运商日常管理，包含系统维护、车辆安全检查、司机培训、KPI考核及各类运输异常问题处理。\n2. 排班派车与线路统筹：根据每日货量合理规划运输线路、完成派车调度，整理司机单据，保障每日运输有序落地。\n3. 现场运输管控：开展每日车队晨会、车辆安全巡检、运输环境标准核查，落实现场标准化管理。\n4. 运输节点把控：全程跟进供应商到货、上货、发车进度，严格把控各时间节点，保障链路时效。\n5. 到站交接合规管理：监督车辆到站交接流程合规性，快速处理交接环节出现的异常问题。\n6. 在途与末端巡检：负责车辆在途跟踪、尾站巡车、封签检查，不定期跟车核查链路问题，排查司机违规操作。\n7. 跨部门协同：联动各横向业务部门，高效解决运输链路卡点、异常故障，保障业务顺畅运转。\n8. 数据复盘与整改：按日、周、月维度统计运营数据，梳理不达标问题，输出整改方案并落地闭环。\n9. 服从团队管理：接受公司出差、异地调动、班次轮岗等工作安排，完成上级交办的其他工作。","requirements":"1. 经验要求：具备3年及以上城配/运输运营管理经验，有水产冷链运输经验优先，非硬性要求。\n2. 管理能力：可独立管理10人左右劳务车队团队，具备现场带队、人员统筹、现场管控能力。\n3. 综合素养：沟通能力强，擅长处理各类突发异常事件，责任心强、承压应变能力突出。\n4. 技能要求：熟练使用各类办公软件，具备数据整理、复盘分析、方案输出能力。\n5. 工作态度：吃苦耐劳、主动上进，服从排班轮岗安排，适配多班次工作节奏。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1. 承运商与车辆管理：负责合作车辆、承运商日常管理，包含系统维护、车辆安全检查、司机培训、KPI考核及各类运输异常问题处理。\n2. 排班派车与线路统筹：根据每日货量合理规划运输线路、完成派车调度，整理司机单据，保障每日运输有序落地。\n3. 现场运输管控：开展每日车队晨会、车辆安全巡检、运输环境标准核查，落实现场标准化管理。\n4. 运输节点把控：全程跟进供应商到货、上货、发车进度，严格把控各时间节点，保障链路时效。\n5. 到站交接合规管理：监督车辆到站交接流程合规性，快速处理交接环节出现的异常问题。\n6. 在途与末端巡检：负责车辆在途跟踪、尾站巡车、封签检查，不定期跟车核查链路问题，排查司机违规操作。\n7. 跨部门协同：联动各横向业务部门，高效解决运输链路卡点、异常故障，保障业务顺畅运转。\n8. 数据复盘与整改：按日、周、月维度统计运营数据，梳理不达标问题，输出整改方案并落地闭环。\n9. 服从团队管理：接受公司出差、异地调动、班次轮岗等工作安排，完成上级交办的其他工作。\n\n岗位基本要求\n1. 经验要求：具备3年及以上城配/运输运营管理经验，有水产冷链运输经验优先，非硬性要求。\n2. 管理能力：可独立管理10人左右劳务车队团队，具备现场带队、人员统筹、现场管控能力。\n3. 综合素养：沟通能力强，擅长处理各类突发异常事件，责任心强、承压应变能力突出。\n4. 技能要求：熟练使用各类办公软件，具备数据整理、复盘分析、方案输出能力。\n5. 工作态度：吃苦耐劳、主动上进，服从排班轮岗安排，适配多班次工作节奏。\n\n具备以下条件优先\n具备分析、写作和外部沟通协调能力，熟练使用办公软件，有相关水产和运输行业经验。\n\n岗位亮点\n1. 业务体系成熟：负责完整的城配运输链路管理，从派车、现场、在途、末端、复盘全流程锻炼，成长维度全面。\n2. 管理权限独立：直管10人劳务团队，独立负责车辆、司机、承运商考核管理，锻炼现场统筹与团队管理能力。\n3. 发展空间灵活：支持异地调动、多仓轮岗，接触多区域运营模式，积累多城市水产物流运营经验。\n4. 工作内容扎实：兼顾现场实操、数据复盘、异常攻坚，能力提升快，岗位含金量高。\n5. 准入门槛友好：水产经验不做硬性强制，优秀运输管理经验者均可适配，包容性强。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4650045173","sourceKey":"meituan_social","company":"美团","title":"AIoT解决方案","city":"深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4650045173&jobShareType=1","duty":"1、负责美团食杂零售 AIoT 解决方案的设计与落地，应用场景覆盖多个业务线与全部供应链环节（产地、PC 加工、仓储物流、前置仓、门店等）；\n2、深潜零售一线，结合专业知识与行业调研，通过 AIoT 解决方案实现对不同业务线各个供应链环节的智能化改造并提升经营效率；\n3、负责 AIoT 解决方案的需求定义、硬件选型、研发与试点部署、落地推广、持续迭代的全生命周期项目工作；\n4、高效协同内外部多类部门（业务、供应商、算法、软件产研等），保障解决方案可以高质量落地。","requirements":"1、本科及以上学历，电子信息、自动化、计算机、物联网等相关专业优先，5年以上 AIoT，智能硬件相关产品经验；\n2、具备软硬件整体解决方案的全生命周期项目管理经验。有零售/仓储/供应链场景落地经验，或 IoT 设备、机器视觉、物流自动化相关项目经验者优先；\n3、良好的沟通协调能力，能够整合跨部门资源实现解决方案的落地推广与持续迭代；\n4、具备创新思维并深潜业务一线，能够基于零售业务发展趋势与硬件技术迭代节奏，决策并输出经营收益最大化的软硬件解决方案；\n5、具备与算法团队协作经验，对当前主流 AI 技术有清晰理解，有通过 AI 实现效率提升或辅助决策经验优先。","description":"部门介绍\n美团的使命是“帮大家吃得更好，生活更好”，公司聚焦“零售 + 科技”战略，和广大商户与各类合作伙伴一起，努力为消费者提供品质生活，推动商品零售和服务零售在需求侧和供给侧的数字化转型。\n2018年9月20日，美团正式在港交所挂牌上市。美团将始终坚持以客户为中心，不断加大在科技研发方面的投入，更好承担社会责任，更多创造社会价值，与广大合作伙伴一起发展共赢。\n\n岗位职责\n1、负责美团食杂零售 AIoT 解决方案的设计与落地，应用场景覆盖多个业务线与全部供应链环节（产地、PC 加工、仓储物流、前置仓、门店等）；\n2、深潜零售一线，结合专业知识与行业调研，通过 AIoT 解决方案实现对不同业务线各个供应链环节的智能化改造并提升经营效率；\n3、负责 AIoT 解决方案的需求定义、硬件选型、研发与试点部署、落地推广、持续迭代的全生命周期项目工作；\n4、高效协同内外部多类部门（业务、供应商、算法、软件产研等），保障解决方案可以高质量落地。\n\n岗位基本要求\n1、本科及以上学历，电子信息、自动化、计算机、物联网等相关专业优先，5年以上 AIoT，智能硬件相关产品经验；\n2、具备软硬件整体解决方案的全生命周期项目管理经验。有零售/仓储/供应链场景落地经验，或 IoT 设备、机器视觉、物流自动化相关项目经验者优先；\n3、良好的沟通协调能力，能够整合跨部门资源实现解决方案的落地推广与持续迭代；\n4、具备创新思维并深潜业务一线，能够基于零售业务发展趋势与硬件技术迭代节奏，决策并输出经营收益最大化的软硬件解决方案；\n5、具备与算法团队协作经验，对当前主流 AI 技术有清晰理解，有通过 AI 实现效率提升或辅助决策经验优先。\n\n岗位亮点\n1、美团食杂零售业务多样、供应链长复杂度高，你的解决方案将可能提升千万级用户的体验；\n2、AIoT 产品通过软硬件解决方案赋能，提升零售供应链各个环节的效率，这将是践行美团“零售+科技”业务战略的最佳实践；\n3、AI 环境友好，你将与一群具有创新精神的伙伴共同探索并改变物理世界。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4617028400","sourceKey":"meituan_social","company":"美团","title":"松鼠便利华东区上海中心仓运营支持","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4617028400&jobShareType=1","duty":"1. 结算与费用管理：依据合同约定计费标准，独立核算应付费用，识别并标记异常差异项，在业财系统中准确创建结算申请单并完成审批跟进，主动发现、分析结算差异原因，推动多方协调核实与解决。\n2. 物流成本分析与数据支持：定期整理汇总结算相关数据，制作物流成本分析报表，识别成本异常和优化空间，为成本控制及精细化运营提供数据支撑。\n3. 闪购商家入驻与规则管理：负责闪购商家入驻规则的迭代优化，协同合规、GA等业务方及时更新审核规则，完成内外部政策透传与规则落地。\n4. 中心仓运营支持：负责输出中心仓日报，支持仓配经理精细化运营；管理差异专员的认责和举证效率，驱动履约体验提升；定期收集门店和采销的投诉与反馈，协助优化流程、提升全链路体验；负责大区内相关岗位的绩效得分核算。\n5. 仓内行政与后勤管理：负责中心仓物资设备验收、入账、盘点、报损及水电办公成本控制结算；负责人员排班休假管理、5S管理，以及外部联络接待（物业、回收商、设备维保、消防等）。","requirements":"1.大学专科以上学历，财务、物流或人力资源相关专业优先。\n2.具备良好的团队管理能力和沟通能力，能有效协调团队工作。\n3.熟练操作办公软件，了解物流管理流程。\n4.具备较强的责任心和执行力，能够承受一定的工作压力。","description":"部门介绍\n美团闪购是美团旗下的即时零售平台，依托即时配送能力，连接本地零售供给，满足消费者30分钟万物到家的即时需求。美团闪购涵盖超市便利、食材、水果、鲜花绿植、休闲零食、酒水饮料、数码家电、美妆个护、母婴玩具、日用百货、服饰鞋帽、宠物等诸多品类，业务覆盖全国近3,000个县市区旗，每日百万级在岗骑手，以高效的配送、丰富的品类和广泛的覆盖，为美团数亿用户带来便捷的生活体验，积极助力实体零售线上化转型，提升本地商业活力。\n\n岗位职责\n1. 结算与费用管理：依据合同约定计费标准，独立核算应付费用，识别并标记异常差异项，在业财系统中准确创建结算申请单并完成审批跟进，主动发现、分析结算差异原因，推动多方协调核实与解决。\n2. 物流成本分析与数据支持：定期整理汇总结算相关数据，制作物流成本分析报表，识别成本异常和优化空间，为成本控制及精细化运营提供数据支撑。\n3. 闪购商家入驻与规则管理：负责闪购商家入驻规则的迭代优化，协同合规、GA等业务方及时更新审核规则，完成内外部政策透传与规则落地。\n4. 中心仓运营支持：负责输出中心仓日报，支持仓配经理精细化运营；管理差异专员的认责和举证效率，驱动履约体验提升；定期收集门店和采销的投诉与反馈，协助优化流程、提升全链路体验；负责大区内相关岗位的绩效得分核算。\n5. 仓内行政与后勤管理：负责中心仓物资设备验收、入账、盘点、报损及水电办公成本控制结算；负责人员排班休假管理、5S管理，以及外部联络接待（物业、回收商、设备维保、消防等）。\n\n岗位基本要求\n1.大学专科以上学历，财务、物流或人力资源相关专业优先。\n2.具备良好的团队管理能力和沟通能力，能有效协调团队工作。\n3.熟练操作办公软件，了解物流管理流程。\n4.具备较强的责任心和执行力，能够承受一定的工作压力。\n\n具备以下条件优先\n零售物流经验优先。\n\n岗位亮点\n1. 加入高速发展的松鼠便利，参与区域核心仓储运营。  \n2. 扁平化管理，提供清晰的职业成长路径。  \n3. 团队氛围年轻活跃，注重员工能力提升。  \n4. 提供行业竞争力的薪资及绩效激励。  \n5. 弹性工作制，注重工作与生活平衡。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4686264809","sourceKey":"meituan_social","company":"美团","title":"车辆运营主管","city":"南宁市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4686264809&jobShareType=1","duty":"负责管理区域内车辆的日常运营调度与管理工作，确保车辆高效运转\n通过实地观察、数据分析、行业分析，制定提升市占营收的经营策略，例如车辆投放、调度策略，故障干预策略等，提升市占营收等指标\n对接区域内政府主管部门，配合政府部门对城市运营问题进行管理\n收集并分析运营数据，提出优化建议，提升车辆使用效率与用户体验。","requirements":"大学本科及以上学历，专业不限，交通运输、物流管理相关专业优先。\n具备3年以上运营支持或车辆运维相关工作经验。\n熟悉南宁市交通环境，具备良好的沟通协调能力与应变能力。\n熟练使用办公软件，具备基础数据分析能力，有政务沟通经验优先\n有项目地推经验加分","description":"部门介绍\n美团骑行事业部在全国各个城市开展美团单车、电单车业务，提供绿色、便捷的共享出行服务，是美团出行板块重要的组成部分。我们力求为城市可持续发展提供低碳智能的解决方案，通过技术创新和硬件升级，不断优化全流程骑行体验，为低碳出行提供更好的服务。其中，美团单车旨在为城市居民提供通勤接驳服务，满足用户短途接驳出行需求；美团电单车则满足用户中短途多场景低碳出行需求。\n我们有开放的工作氛围，也有充满韧劲和创造力，心系低碳出行的伙伴。加入我们，一起为用户创造更好的出行体验。\n\n岗位职责\n负责管理区域内车辆的日常运营调度与管理工作，确保车辆高效运转\n通过实地观察、数据分析、行业分析，制定提升市占营收的经营策略，例如车辆投放、调度策略，故障干预策略等，提升市占营收等指标\n对接区域内政府主管部门，配合政府部门对城市运营问题进行管理\n收集并分析运营数据，提出优化建议，提升车辆使用效率与用户体验。\n\n岗位基本要求\n大学本科及以上学历，专业不限，交通运输、物流管理相关专业优先。\n具备3年以上运营支持或车辆运维相关工作经验。\n熟悉南宁市交通环境，具备良好的沟通协调能力与应变能力。\n熟练使用办公软件，具备基础数据分析能力，有政务沟通经验优先\n有项目地推经验加分\n\n岗位亮点\n1. 参与城市绿色出行项目，助力可持续交通发展。  \n2. 扁平化管理，快速成长通道，积累一线运营实战经验。  \n3.大平台，发展潜力大，晋升路径畅通。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4658605284","sourceKey":"meituan_social","company":"美团","title":"大客户管理BP","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4658605284&jobShareType=1","duty":"1.负责大客户销售目标的制定、拆解与过程管理，建立完善的销售跟踪与复盘机制，推动团队目标高质量达成；\n\n2.搭建并优化大客户销售漏斗管理体系，深度参与重点项目推进，协调内外部资源，提升销售转化效率；\n\n3.持续开展行业市场研究与竞争分析，洞察客户需求与市场机会，输出策略建议，赋能一线销售团队。","requirements":"学历：本科及以上学历，市场营销、工商管理、供应链管理等相关专业优先\n工作经验：3年以上B2B销售管理/客户运营相关经验，有KA客户管理或大客户销售支持经验者优先\n行业背景：有零售、物流、供应链或相关行业从业经验者优先（食杂零售行业经验尤佳）","description":"部门介绍\n无人车业务部成立于2016年，旨在用无人驾驶技术提升物流配送的效率和体验。美团无人车以自研L4级自动驾驶软硬件技术为核心，与美团即时零售业务结合，形成满足公开道路、社区、工业园区等室外全场景下的无人配送整体解决方案。自2020年起，无人车已在北京、深圳等多地进入常态化试运营阶段，在城市复杂场景下提供针对餐饮外卖、生鲜食杂等货物的即时配送服务。2025年，美团无人车又踏上了同城货运的新探索，并在2026年持续扩大运营范围和车队数量，为更多城市带来智能配送服务。\n欢迎加入美团无人车团队，与我们一起用科技推动即时零售再升级！\n\n岗位职责\n1.负责大客户销售目标的制定、拆解与过程管理，建立完善的销售跟踪与复盘机制，推动团队目标高质量达成；\n\n2.搭建并优化大客户销售漏斗管理体系，深度参与重点项目推进，协调内外部资源，提升销售转化效率；\n\n3.持续开展行业市场研究与竞争分析，洞察客户需求与市场机会，输出策略建议，赋能一线销售团队。\n\n岗位基本要求\n学历：本科及以上学历，市场营销、工商管理、供应链管理等相关专业优先\n工作经验：3年以上B2B销售管理/客户运营相关经验，有KA客户管理或大客户销售支持经验者优先\n行业背景：有零售、物流、供应链或相关行业从业经验者优先（食杂零售行业经验尤佳）\n\n岗位亮点\n①无人配送行业最快落地场景，有机会直接引领全国政策导向；\n②AI 深度赋能岗位：AI 在本岗位的应用空间极大，是 AI 辅助政务工作的前沿探索者；\n③团队氛围好、发展空间大、个人能力提升快。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4621911277","sourceKey":"meituan_social","company":"美团","title":"医美SKA客户组长","city":"北京市/上海市/杭州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4621911277&jobShareType=1","duty":"1. 负责医美行业SKA客户的开发与维护，制定并执行客户拓展策略，达成业绩目标。  \n2. 带领5人团队开展大客户销售工作，统筹资源支持团队完成关键项目落地。  \n3. 深度理解客户需求，协调内部产品、运营及交付团队，推动定制化解决方案的实施。  \n4. 定期分析客户经营数据与市场趋势，输出行业洞察报告，优化客户合作模式。  \n5. 建立并维护与SKA客户高层的长期合作关系，提升客户满意度与续约率。","requirements":"1. 大学本科及以上学历，市场营销、商务管理或相关专业优先。  \n2. 具备7年以上大客户销售或业务开发经验，有医美、大健康或高端消费行业背景者优先。  \n3. 有成功主导SKA客户合作案例，熟悉客户生命周期管理与价值挖掘方法。  \n4. 具备优秀的团队管理能力，能够激励并指导团队成员达成目标。  \n5. 出色的沟通表达与商务谈判能力，适应高频出差，工作地点为北京、上海或杭州。","description":"部门介绍\n美团医药健康事业部是美团核心本地商业板块下专注健康领域的业务部门，涵盖美团买药、美团医美和美团医疗三大业务。自创立以来，美团医药健康致力于为用户提供全健康周期产品及服务，满足人民群众多层次多元化医疗健康需求，现已覆盖购药到家、居家检测、问诊挂号、医保支付、求医寻院、医疗美容等核心场景。此外，美团医药健康还为商户提供数字化转型创新解决方案，打造贯穿上游的联动机制，长期参与共建更透明、更可持续的医药健康产业生态圈，目前业务已覆盖25万家药店，收录27万家医疗机构。未来，美团医药康将协同更多行业伙伴，帮助大家变得更健康、更美丽、更养生。\n\n岗位职责\n1. 负责医美行业SKA客户的开发与维护，制定并执行客户拓展策略，达成业绩目标。  \n2. 带领5人团队开展大客户销售工作，统筹资源支持团队完成关键项目落地。  \n3. 深度理解客户需求，协调内部产品、运营及交付团队，推动定制化解决方案的实施。  \n4. 定期分析客户经营数据与市场趋势，输出行业洞察报告，优化客户合作模式。  \n5. 建立并维护与SKA客户高层的长期合作关系，提升客户满意度与续约率。\n\n岗位基本要求\n1. 大学本科及以上学历，市场营销、商务管理或相关专业优先。  \n2. 具备7年以上大客户销售或业务开发经验，有医美、大健康或高端消费行业背景者优先。  \n3. 有成功主导SKA客户合作案例，熟悉客户生命周期管理与价值挖掘方法。  \n4. 具备优秀的团队管理能力，能够激励并指导团队成员达成目标。  \n5. 出色的沟通表达与商务谈判能力，适应高频出差，工作地点为北京、上海或杭州。\n\n岗位亮点\n1. 加入高速发展的医美行业，参与行业头部客户战略合作项目。  \n2. 扁平化管理机制，拥有充分的资源支持与决策参与空间。  \n3. 团队氛围积极开放，注重专业成长与跨部门协作能力提升。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4611956079","sourceKey":"meituan_social","company":"美团","title":"无人车业务部-商超零售行业KA","city":"北京市/上海市/深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4611956079&jobShareType=1","duty":"1、聚焦商超零售行业，负责全国连锁商超，便利店，生鲜连锁，餐饮连锁KA客户的开发与维护，制定客户开发计划，完成销售目标，推动业务规模化增长。\n2、深度拆解零售行业城配场景痛点，挖掘客户需求，输出无人配送解决方案并推动签约落地，建立长期稳定的战略合作关系。\n3、统筹项目从试点验证到规模化落地的全流程，把控全项目进度节点，统筹协调产品、研发、交付、技术等内外部资源，保障项目落地和稳定运营，跟进项目回款，对交付质量和客户满意度负责。\n4、定期输出商超零售行业市场分析报告，根据客户需求和行业特点反向推动产品，解决方案迭代优化。\n5、积极探索并落地 AI 工具在客户拓展、项目管理、方案制作等工作场景中的应用，借助 AI 能力提升销售效率与客户服务质量，推动客户场景化落地合作。","requirements":"1、学历：本科及以上学历，物流管理，冷链物流，供应链管理，市场营销相关专业优先。\n2、经验：8年以上商超/便利店/生鲜/餐饮连锁B端大客户销售经验。\n3、专业能力：具备独立开拓全新市场的实战成功案例，完整操盘过0到1大客户项目，商务谈判、方案宣讲、高层对接能力突出。\n4、综合素质：目标感强，能力优异，工作执行力高效，能够适配业务节奏，接受高频次异地出差。\n5、AI应用：对 AI 技术发展趋势保持持续关注，具备使用 AI 工具辅助日常工作的实践能力。","description":"部门介绍\n无人车业务部成立于2016年，旨在用无人驾驶技术提升物流配送的效率和体验。美团无人车以自研L4级自动驾驶软硬件技术为核心，与美团即时零售业务结合，形成满足公开道路、社区、工业园区等室外全场景下的无人配送整体解决方案。自2020年起，无人车已在北京、深圳等多地进入常态化试运营阶段，在城市复杂场景下提供针对餐饮外卖、生鲜食杂等货物的即时配送服务。2025年，美团无人车又踏上了同城货运的新探索，并在2026年持续扩大运营范围和车队数量，为更多城市带来智能配送服务。\n欢迎加入美团无人车团队，与我们一起用科技推动即时零售再升级！\n\n岗位职责\n1、聚焦商超零售行业，负责全国连锁商超，便利店，生鲜连锁，餐饮连锁KA客户的开发与维护，制定客户开发计划，完成销售目标，推动业务规模化增长。\n2、深度拆解零售行业城配场景痛点，挖掘客户需求，输出无人配送解决方案并推动签约落地，建立长期稳定的战略合作关系。\n3、统筹项目从试点验证到规模化落地的全流程，把控全项目进度节点，统筹协调产品、研发、交付、技术等内外部资源，保障项目落地和稳定运营，跟进项目回款，对交付质量和客户满意度负责。\n4、定期输出商超零售行业市场分析报告，根据客户需求和行业特点反向推动产品，解决方案迭代优化。\n5、积极探索并落地 AI 工具在客户拓展、项目管理、方案制作等工作场景中的应用，借助 AI 能力提升销售效率与客户服务质量，推动客户场景化落地合作。\n\n岗位基本要求\n1、学历：本科及以上学历，物流管理，冷链物流，供应链管理，市场营销相关专业优先。\n2、经验：8年以上商超/便利店/生鲜/餐饮连锁B端大客户销售经验。\n3、专业能力：具备独立开拓全新市场的实战成功案例，完整操盘过0到1大客户项目，商务谈判、方案宣讲、高层对接能力突出。\n4、综合素质：目标感强，能力优异，工作执行力高效，能够适配业务节奏，接受高频次异地出差。\n5、AI应用：对 AI 技术发展趋势保持持续关注，具备使用 AI 工具辅助日常工作的实践能力。\n\n具备以下条件优先\n有全国连锁商超零售总部供应链/物流决策层资源者优先。\n\n岗位亮点\n商超零售是无人车商业化落地核心板块，业务发展空间大。\n沉淀自动驾驶+快消供应链复合经验。\n激励政策优厚，发展空间大、个人能力提升快。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4583709908","sourceKey":"meituan_social","company":"美团","title":"医药健康事业部-医疗业务部财务BP TL","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4583709908&jobShareType=1","duty":"1. 财务管理规划与推动：能够从战略高度和长短线视角诊断业务健康度并规划财务管理策略，基于业务阶段、财务组织及能力建设需要，以及AI对于财务工作范式的变革，系统性规划工作重点并带领团队交付推进工作。\n2. 策略支撑及优化：作为业务部门的合作伙伴，深入参与到业务的日常经营支持和策略制定中：1)熟悉核算、结算、资金、税务的专业知识，能够有效牵引调度专业财务团队提供合规且可实施的方案并落地实施；2）打通业务战略-运营-资源投入的全局视角，协助业务优化商业模式，看清收益和效率，支持业务制定并优化策略；3）控制业务经营相关的财务风险，通过机制设计和追踪体系能力，确保风险敞口可控；4）参与日常财务运营，包括但不限于合同和付款审核等。\n3. 预算及预测管理：负责年度预算以及月度滚动预测编制、监控和分析：1）预算流程中，参与业务战略和策略的讨论，并主导业务线的预算流程，与业务共同规划收益和投资结构；2）使用滚动预测工具前瞻性地协助业务预期经营结果，支持短期资源的分配。\n4. 经营分析：1）针对业务重点问题，能够通过分析识别关键问题并提出有效建议，支持业务高质量盈利性增长；2）资源投入管理及复盘：能够综合战略、业务和商业价值视角对重点项目业财表现进行复盘，综合设计有效的ROI指标平衡长短期增长和财务收益；3）多维度细颗粒度分析：对于重点维度能够展开分析，结合业务特性和商业逻辑识别机会和风险点，提升业务效能。","requirements":"1. 本科及以上学历，8年以上财务相关经验，具有扎实的财务专业知识，具有财务管理经验。\n2. 具有商业敏感度和思辨思维，逻辑性强、条理清楚的有效沟通能力。\n3. 具备优秀的学习能力、逻辑分析能力、书面及口头沟通能力。\n4. 具备团队管理经验。\n5. 具备一定的AI agent的理解和使用经验，熟悉SQL等数据工具应用。","description":"部门介绍\n财务平台负责公司整体和各业务层面的财务管理工作，通过建设专业、全面、复合的财务管理能力和与业务经营的紧密结合来支持公司健康发展。目前财务平台拥有财务会计、财务报告、资金管理、税务管理、财务共享、财务系统、规划分析、财务BP和内控内审等主要工作方向。我们的目标是建设业界一流的财务管理能力和经营支持体系，为公司战略的正确落地、投入效率的持续提升、业务价值的不断增长保驾护航。欢迎加入财务平台，携手一起向未来！\n\n岗位职责\n1. 财务管理规划与推动：能够从战略高度和长短线视角诊断业务健康度并规划财务管理策略，基于业务阶段、财务组织及能力建设需要，以及AI对于财务工作范式的变革，系统性规划工作重点并带领团队交付推进工作。\n2. 策略支撑及优化：作为业务部门的合作伙伴，深入参与到业务的日常经营支持和策略制定中：1)熟悉核算、结算、资金、税务的专业知识，能够有效牵引调度专业财务团队提供合规且可实施的方案并落地实施；2）打通业务战略-运营-资源投入的全局视角，协助业务优化商业模式，看清收益和效率，支持业务制定并优化策略；3）控制业务经营相关的财务风险，通过机制设计和追踪体系能力，确保风险敞口可控；4）参与日常财务运营，包括但不限于合同和付款审核等。\n3. 预算及预测管理：负责年度预算以及月度滚动预测编制、监控和分析：1）预算流程中，参与业务战略和策略的讨论，并主导业务线的预算流程，与业务共同规划收益和投资结构；2）使用滚动预测工具前瞻性地协助业务预期经营结果，支持短期资源的分配。\n4. 经营分析：1）针对业务重点问题，能够通过分析识别关键问题并提出有效建议，支持业务高质量盈利性增长；2）资源投入管理及复盘：能够综合战略、业务和商业价值视角对重点项目业财表现进行复盘，综合设计有效的ROI指标平衡长短期增长和财务收益；3）多维度细颗粒度分析：对于重点维度能够展开分析，结合业务特性和商业逻辑识别机会和风险点，提升业务效能。\n\n岗位基本要求\n1. 本科及以上学历，8年以上财务相关经验，具有扎实的财务专业知识，具有财务管理经验。\n2. 具有商业敏感度和思辨思维，逻辑性强、条理清楚的有效沟通能力。\n3. 具备优秀的学习能力、逻辑分析能力、书面及口头沟通能力。\n4. 具备团队管理经验。\n5. 具备一定的AI agent的理解和使用经验，熟悉SQL等数据工具应用。\n\n岗位亮点\n1、核心事业部，覆盖到家模式与到店模式，多元商业模式视角。\n2、伴随业务第二和第三曲线的扩张，成长空间大，成长机会多。\n3、所处行业潜力好，业务经营佳。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4514435793","sourceKey":"meituan_social","company":"美团","title":"美团骑行-政企大客户专家","city":"武汉市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4514435793&jobShareType=1","duty":"1. 负责美团骑行在湖北省政企大客户的业务拓展与维护，挖掘并转化高潜力客户。  \n2. 深入了解客户需求，制定定制化解决方案，推动骑行产品在政府、园区、企业等场景的落地应用。  \n3. 协调内部资源，联动产品、运营、市场等团队，确保项目高效推进与交付。  \n4. 定期分析客户数据与市场动态，输出行业洞察报告，优化客户策略与业务模式。","requirements":"1. 大学本科及以上学历，具备3年以上大客户销售或政企合作相关经验。  \n2. 熟悉政府及企业采购流程，具备良好的商务谈判与客户关系管理能力。  \n3. 具备较强的逻辑思维与数据分析能力，能够独立推动项目闭环。  \n4. 有出行、本地生活或B端服务行业背景者优先。","description":"部门介绍\n美团骑行事业部在全国各个城市开展美团单车、电单车业务，提供绿色、便捷的共享出行服务，是美团出行板块重要的组成部分。我们力求为城市可持续发展提供低碳智能的解决方案，通过技术创新和硬件升级，不断优化全流程骑行体验，为低碳出行提供更好的服务。其中，美团单车旨在为城市居民提供通勤接驳服务，满足用户短途接驳出行需求；美团电单车则满足用户中短途多场景低碳出行需求。\n我们有开放的工作氛围，也有充满韧劲和创造力，心系低碳出行的伙伴。加入我们，一起为用户创造更好的出行体验。\n\n岗位职责\n1. 负责美团骑行在湖北省政企大客户的业务拓展与维护，挖掘并转化高潜力客户。  \n2. 深入了解客户需求，制定定制化解决方案，推动骑行产品在政府、园区、企业等场景的落地应用。  \n3. 协调内部资源，联动产品、运营、市场等团队，确保项目高效推进与交付。  \n4. 定期分析客户数据与市场动态，输出行业洞察报告，优化客户策略与业务模式。\n\n岗位基本要求\n1. 大学本科及以上学历，具备3年以上大客户销售或政企合作相关经验。  \n2. 熟悉政府及企业采购流程，具备良好的商务谈判与客户关系管理能力。  \n3. 具备较强的逻辑思维与数据分析能力，能够独立推动项目闭环。  \n4. 有出行、本地生活或B端服务行业背景者优先。\n\n岗位亮点\n1. 参与城市绿色出行生态建设，推动可持续交通发展。  \n2. 与政府机构及大型企业深度合作，拓展职业资源网络。  \n3. 在快速发展的业务体系中承担关键角色，具备广阔成长空间。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4268722220","sourceKey":"meituan_social","company":"美团","title":"无人车业务部-华南-公共事务发展经理","city":"广州市/深圳市/东莞市/中山市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4268722220&jobShareType=1","duty":"1、建立并维护与公安交管等安全相关政府部门的良好沟通关系，协助各运营城市的自动驾驶道路测试通知书、示范应用许可等安全相关审批的申报与维护工作；借助 AI 工具快速梳理各城市政策法规差异，生成定制化的政策沟通材料，提升开城效率；\n2、协调跨部门资源，完成数据上报、平台对接等合规要求；探索 AI 辅助合规文档整理和报送流程自动化，减少重复性行政事务投入；\n3、处理属地舆情与问题，平衡政府数据安全要求与企业技术诉求；利用 AI 辅助舆情监测与快速响应材料撰写，提升危机处置速度与质量。","requirements":"1、本科及以上学历，5年以上工作经验。\n2、具备开城经验、有智能网联/新能源汽车领域路权成功案例者优先；在目标区域（华南等）具备成熟警企合作经验优先。\n3、善于沟通和协同合作伙伴推动业务落地，有较强的销售能力，掌握自动驾驶技术基础（如传感器配置、算法合规要求），实现技术与政策语言转化。\n4、有主动使用 AI 工具提升政策研究、文案撰写、信息整合效率的习惯；能识别日常工作中可 AI 化的重复性事务并付诸实践；对 AI 辅助政务工作持开放态度。","description":"部门介绍\n无人车业务部成立于2016年，旨在用无人驾驶技术提升物流配送的效率和体验。美团无人车以自研L4级自动驾驶软硬件技术为核心，与美团即时零售业务结合，形成满足公开道路、社区、工业园区等室外全场景下的无人配送整体解决方案。自2020年起，无人车已在北京、深圳等多地进入常态化试运营阶段，在城市复杂场景下提供针对餐饮外卖、生鲜食杂等货物的即时配送服务。2025年，美团无人车又踏上了同城货运的新探索，并在2026年持续扩大运营范围和车队数量，为更多城市带来智能配送服务。\n欢迎加入美团无人车团队，与我们一起用科技推动即时零售再升级！\n\n岗位职责\n1、建立并维护与公安交管等安全相关政府部门的良好沟通关系，协助各运营城市的自动驾驶道路测试通知书、示范应用许可等安全相关审批的申报与维护工作；借助 AI 工具快速梳理各城市政策法规差异，生成定制化的政策沟通材料，提升开城效率；\n2、协调跨部门资源，完成数据上报、平台对接等合规要求；探索 AI 辅助合规文档整理和报送流程自动化，减少重复性行政事务投入；\n3、处理属地舆情与问题，平衡政府数据安全要求与企业技术诉求；利用 AI 辅助舆情监测与快速响应材料撰写，提升危机处置速度与质量。\n\n岗位基本要求\n1、本科及以上学历，5年以上工作经验。\n2、具备开城经验、有智能网联/新能源汽车领域路权成功案例者优先；在目标区域（华南等）具备成熟警企合作经验优先。\n3、善于沟通和协同合作伙伴推动业务落地，有较强的销售能力，掌握自动驾驶技术基础（如传感器配置、算法合规要求），实现技术与政策语言转化。\n4、有主动使用 AI 工具提升政策研究、文案撰写、信息整合效率的习惯；能识别日常工作中可 AI 化的重复性事务并付诸实践；对 AI 辅助政务工作持开放态度。\n\n岗位亮点\n无人配送是行业最快落地的场景，是美团战略部署，加入美团无人配送将有机会引领整个行业的政策导向、推动整个行业的发展。\nAI 深度赋能岗位：政策文本分析、申报材料生成、知识库管理\n带薪年假、定期体检、五险一金、发展空间大、个人能力提升快。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4644279736","sourceKey":"meituan_social","company":"美团","title":"财务科技-全栈开发工程师","city":"北京市/成都市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4644279736&jobShareType=1","duty":"1. 负责投资系统的全栈研发建设，围绕投前、投后全流程管理场景，持续提升系统能力，支撑美团投资业务发展；\n2. 深入理解业务场景，与用户、产品团队协同推进需求分析、方案设计及技术落地，持续提升系统能力和用户体验；\n3. 负责业务模块端到端研发，覆盖前端、后端及测试等环节，推动系统建设与交付；\n4. 探索并推动 AI Coding / Agent 等新型研发模式在业务中的应用落地，提升工程效率和研发智能化水平。","requirements":"1.计算机相关专业，本科及以上学历，具备扎实的软件工程能力；\n2.扎实掌握 Java 技术栈，熟悉Web、 Spring、MySQL、消息队列、缓存、微服务、分布式系统等相关技术；\n3.具备较强的业务理解能力与问题识别、推动落地能力，沟通协同能力强，拥抱 AI 技术，对工程效率和技术创新有持续热情；\n4.3年以上企业级系统开发经验，有投资管理系统、基金系统、财务系统、资金系统建设经验优先。","description":"部门介绍\n财务平台负责公司整体和各业务层面的财务管理工作，通过建设专业、全面、复合的财务管理能力和与业务经营的紧密结合来支持公司健康发展。目前财务平台拥有财务会计、财务报告、资金管理、税务管理、财务共享、财务系统、规划分析、财务BP和内控内审等主要工作方向。我们的目标是建设业界一流的财务管理能力和经营支持体系，为公司战略的正确落地、投入效率的持续提升、业务价值的不断增长保驾护航。欢迎加入财务平台，携手一起向未来！\n\n岗位职责\n1. 负责投资系统的全栈研发建设，围绕投前、投后全流程管理场景，持续提升系统能力，支撑美团投资业务发展；\n2. 深入理解业务场景，与用户、产品团队协同推进需求分析、方案设计及技术落地，持续提升系统能力和用户体验；\n3. 负责业务模块端到端研发，覆盖前端、后端及测试等环节，推动系统建设与交付；\n4. 探索并推动 AI Coding / Agent 等新型研发模式在业务中的应用落地，提升工程效率和研发智能化水平。\n\n岗位基本要求\n1.计算机相关专业，本科及以上学历，具备扎实的软件工程能力；\n2.扎实掌握 Java 技术栈，熟悉Web、 Spring、MySQL、消息队列、缓存、微服务、分布式系统等相关技术；\n3.具备较强的业务理解能力与问题识别、推动落地能力，沟通协同能力强，拥抱 AI 技术，对工程效率和技术创新有持续热情；\n4.3年以上企业级系统开发经验，有投资管理系统、基金系统、财务系统、资金系统建设经验优先。\n\n岗位亮点\n1. 参与金融科技前沿项目，接触大规模投资系统核心业务；\n2. 技术氛围浓厚，与资深工程师共同成长，提升技术深度与广度；\n3. 工作地点灵活，支持北京、成都双城办公，享受一线城市资源与二线城市生活节奏；\n4. 完善的职业发展通道与培训体系，助力个人长期发展。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3819650714","sourceKey":"meituan_social","company":"美团","title":"Keemart 财务BP-综合分析","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3819650714&jobShareType=1","duty":"1、 深入了解业务，建立合理有效的分析体系，能够给予业务方有效专业的财务意见及解决方案；\n2、 深度参与年度预算及月度业务目标制定，高频追踪目标完成情况对风险及时预警，对重点业务和项目进行随时跟进，定期反馈；\n3、 与业务部门建立良好合作关系，对业务策略有判断并能输出财务意见；\n4、 建立业务运营风险管控机制，识别合同、运营、合规类风险，并制定应对方案。","requirements":"1、 财务或相关专业本科及以上学历，7年及以上财务相关经验，有零售行业分析、FP&A相关工作经验者优先；\n2、 具备数据敏感性和探知欲、分析和解决问题的能力，逻辑清晰严谨，沟通表达和协调能力强；\n3、 勤奋踏实，有较强的工作投入度和自驱力，富有团对合作精神。\n4、 具备良好的沟通、协调与合作能力。\n5、 认同企业文化，拥抱变化，乐观自信。\n6、 英文流利，支持日常工作。\n7、对 AI 技术在财务和业务分析领域的应用有主动探索意识，能结合 AI 工具创新分析方法，推动财务支持数智化转型。","description":"部门介绍\n财务平台负责公司整体和各业务层面的财务管理工作，通过建设专业、全面、复合的财务管理能力和与业务经营的紧密结合来支持公司健康发展。目前财务平台拥有财务会计、财务报告、资金管理、税务管理、财务共享、财务系统、规划分析、财务BP和内控内审等主要工作方向。我们的目标是建设业界一流的财务管理能力和经营支持体系，为公司战略的正确落地、投入效率的持续提升、业务价值的不断增长保驾护航。欢迎加入财务平台，携手一起向未来！\n\n岗位职责\n1、 深入了解业务，建立合理有效的分析体系，能够给予业务方有效专业的财务意见及解决方案；\n2、 深度参与年度预算及月度业务目标制定，高频追踪目标完成情况对风险及时预警，对重点业务和项目进行随时跟进，定期反馈；\n3、 与业务部门建立良好合作关系，对业务策略有判断并能输出财务意见；\n4、 建立业务运营风险管控机制，识别合同、运营、合规类风险，并制定应对方案。\n\n岗位基本要求\n1、 财务或相关专业本科及以上学历，7年及以上财务相关经验，有零售行业分析、FP&A相关工作经验者优先；\n2、 具备数据敏感性和探知欲、分析和解决问题的能力，逻辑清晰严谨，沟通表达和协调能力强；\n3、 勤奋踏实，有较强的工作投入度和自驱力，富有团对合作精神。\n4、 具备良好的沟通、协调与合作能力。\n5、 认同企业文化，拥抱变化，乐观自信。\n6、 英文流利，支持日常工作。\n7、对 AI 技术在财务和业务分析领域的应用有主动探索意识，能结合 AI 工具创新分析方法，推动财务支持数智化转型。\n\n具备以下条件优先\n英文流利， 零售业务行业分析，FP&A相关工作经验，能够接受定期出差。\n\n岗位亮点\n1、深入参与到业务模式探索中，通过财务分析推动业务决策及方案落地\n2、能够参与海外业务0-1的建设过程，快速成长，提升综合能力\n3、团队氛围好","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4614784854","sourceKey":"meituan_social","company":"美团","title":"无人车业务部-算法数据开发工程师","city":"北京市/深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4614784854&jobShareType=1","duty":"负责提升自动驾驶数据闭环能力，结合自动驾驶模型算法的设计与迭代流程，建设高效的数据分析系统与工具。具体职责包括数据分析与挖掘、数据检索与标签系统搭建、数据的修复与生产、从数据维度出发的模型效果闭环提升等。","requirements":"1、具备良好的工程开发能力。熟练使用一门编程语言包括不限于C++、Python等。\n2、具备良好的系统设计能力。能够理解、拆解、梳理需求并根据需求设计系统解决方案，合理考虑长短期需求，进行模块拆分和技术选型，能够完成系统的实现。对自己负责的项目的提出动机和技术细节清晰。","description":"部门介绍\n无人车业务部成立于2016年，旨在用无人驾驶技术提升物流配送的效率和体验。美团无人车以自研L4级自动驾驶软硬件技术为核心，与美团即时零售业务结合，形成满足公开道路、社区、工业园区等室外全场景下的无人配送整体解决方案。自2020年起，无人车已在北京、深圳等多地进入常态化试运营阶段，在城市复杂场景下提供针对餐饮外卖、生鲜食杂等货物的即时配送服务。2025年，美团无人车又踏上了同城货运的新探索，并在2026年持续扩大运营范围和车队数量，为更多城市带来智能配送服务。\n欢迎加入美团无人车团队，与我们一起用科技推动即时零售再升级！\n\n岗位职责\n负责提升自动驾驶数据闭环能力，结合自动驾驶模型算法的设计与迭代流程，建设高效的数据分析系统与工具。具体职责包括数据分析与挖掘、数据检索与标签系统搭建、数据的修复与生产、从数据维度出发的模型效果闭环提升等。\n\n岗位基本要求\n1、具备良好的工程开发能力。熟练使用一门编程语言包括不限于C++、Python等。\n2、具备良好的系统设计能力。能够理解、拆解、梳理需求并根据需求设计系统解决方案，合理考虑长短期需求，进行模块拆分和技术选型，能够完成系统的实现。对自己负责的项目的提出动机和技术细节清晰。\n\n具备以下条件优先\n具备模型训练、数据闭环相关经验，了解整体流程。\n\n岗位亮点\n- 能加入一个高水平研发团队，快速成长。团队成员来自清华、北大、中科院等知名高校。在工作中强调思考，尊重事实和逻辑，是一个能够快速成长的工作环境； \n- 能创造社会价值，参与改变未来的技术革新。拥有丰富的业务场景，推动无人车这一前沿技术在各场景下落地","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4585969238","sourceKey":"meituan_social","company":"美团","title":"咖啡培训和稽查","city":"利雅得","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4585969238&jobShareType=1","duty":"1、Develop and deliver training programs on coffee product knowledge, brewing standards, and service procedures for store staff, new hires, and management.\n2、Design and optimize the coffee training curriculum, including theoretical instruction, hands-on practice, and assessment protocols to ensure standardization.\n3、Organize regular offline and online training sessions, such as new product launches, skill enhancement, and certification exams.\n4、Conduct regular on-site audits of coffee quality, operational procedures, and hygiene standards across regional or national stores.\n5、Assist in building a coffee quality monitoring system to drive continuous improvement across stores.\n6、Analyze coffee-related customer complaints, identify root causes, and drive frontline teams to implement corrective actions for continuous improvement.","requirements":"1、Bachelor’s degree or above, preferred majors include Food Science, Quality management.\n2、Minimum 5 years of experience in coffee industry or chain restaurant quality management, familiarity with coffee operation and quality standards.\n3、Excellent communication and problem-solving skills; ability to travel independently and complete audit assignments.\n4、Excellent training delivery and communication skills; ability to independently design training courses.","description":"部门介绍\n美团的使命是“帮大家吃得更好，生活更好”，公司聚焦“零售 + 科技”战略，和广大商户与各类合作伙伴一起，努力为消费者提供品质生活，推动商品零售和服务零售在需求侧和供给侧的数字化转型。\n2018年9月20日，美团正式在港交所挂牌上市。美团将始终坚持以客户为中心，不断加大在科技研发方面的投入，更好承担社会责任，更多创造社会价值，与广大合作伙伴一起发展共赢。\n\n岗位职责\n1、Develop and deliver training programs on coffee product knowledge, brewing standards, and service procedures for store staff, new hires, and management.\n2、Design and optimize the coffee training curriculum, including theoretical instruction, hands-on practice, and assessment protocols to ensure standardization.\n3、Organize regular offline and online training sessions, such as new product launches, skill enhancement, and certification exams.\n4、Conduct regular on-site audits of coffee quality, operational procedures, and hygiene standards across regional or national stores.\n5、Assist in building a coffee quality monitoring system to drive continuous improvement across stores.\n6、Analyze coffee-related customer complaints, identify root causes, and drive frontline teams to implement corrective actions for continuous improvement.\n\n岗位基本要求\n1、Bachelor’s degree or above, preferred majors include Food Science, Quality management.\n2、Minimum 5 years of experience in coffee industry or chain restaurant quality management, familiarity with coffee operation and quality standards.\n3、Excellent communication and problem-solving skills; ability to travel independently and complete audit assignments.\n4、Excellent training delivery and communication skills; ability to independently design training courses.\n\n具备以下条件优先\nPrefer candidates with Starbucks or coffee address work experience.\n\n岗位亮点\n1. Opportunity to shape coffee culture and elevate service standards across a growing brand.\n2. Work in a dynamic, learning-focused environment with access to specialty coffee resources and tools.\n3. Play a key role in talent development and operational excellence within the coffee division.\n4. Competitive compensation package with professional development opportunities.\n5. Be part of a passionate team dedicated to delivering exceptional coffee experiences.","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4596514908","sourceKey":"meituan_social","company":"美团","title":"KSA-运输经理 Transport Manager","city":"利雅得/吉达","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4596514908&jobShareType=1","duty":"Core Objective: Translate annual transportation goals into actionable monthly strategies, execute plans, conduct regular performance reviews, and lead the team to achieve core business KPIs.\n\nResource & Vendor Management: Leverage local resources to mobilize vendor support and enhance operational collaboration.\n\nFleet & Distribution Expertise: Possess deep understanding of urban distribution, with proven experience managing fleets of 100+ vehicles daily.\n\nCost & Talent Optimization: Demonstrate expertise in transportation cost reduction, driver management, and professional training.","requirements":"Stable work history; proficient in data organization and analysis.","description":"部门介绍\n美团的使命是“帮大家吃得更好，生活更好”，公司聚焦“零售 + 科技”战略，和广大商户与各类合作伙伴一起，努力为消费者提供品质生活，推动商品零售和服务零售在需求侧和供给侧的数字化转型。\n2018年9月20日，美团正式在港交所挂牌上市。美团将始终坚持以客户为中心，不断加大在科技研发方面的投入，更好承担社会责任，更多创造社会价值，与广大合作伙伴一起发展共赢。\n\n岗位职责\nCore Objective: Translate annual transportation goals into actionable monthly strategies, execute plans, conduct regular performance reviews, and lead the team to achieve core business KPIs.\n\nResource & Vendor Management: Leverage local resources to mobilize vendor support and enhance operational collaboration.\n\nFleet & Distribution Expertise: Possess deep understanding of urban distribution, with proven experience managing fleets of 100+ vehicles daily.\n\nCost & Talent Optimization: Demonstrate expertise in transportation cost reduction, driver management, and professional training.\n\n岗位基本要求\nStable work history; proficient in data organization and analysis.\n\n具备以下条件优先\nHas relevant work experience and has worked in Qatar for more than one year.\n\n岗位亮点\nThe company is in a stage of rapid growth, with great potential and promising prospects.","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4706982878","sourceKey":"meituan_social","company":"美团","title":"品质管理专家","city":"广州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4706982878&jobShareType=1","duty":"1、负责自营商品预包装食品的品质管理的全面规划与执行，确保商品在各个环节的品质标准得到有效控制。\n 2、建立和完善自营商品品质管理体系，包括制定自营商品品质管理流程、标准和指导文件，并监督执行情况、主导新品开发阶段的品质标准制定、配方与工艺评审。 \n3、负责供应商（特别是PB商品）的开发准入审核、定期验厂及风险评估。主导对供应商工厂的体系审核（如BRC 、FSSC 22000,、ISO 22000, HACCP等）与过程审核，现场评估其质量保证能力、生产条件与卫生控制水平。\n 4、负责自营商品品质问题的调查与处理，商品品质数据的统计和分析，及时发现问题并提出改进措施，提高产品品质和客户满意度，推动供应商质量能力提升；基于客诉及内外部检验数据，进行趋势分析，发起跨部门质量改进项目，系统性降低质量风险。","requirements":"1、本科及以上学历，食品科学与工程、质量管理、农学等相关专业。5年以上食品制造业或大型零售/电商企业品质管理工作经验，研发经验；具备PB商品或自有品牌的质量管理经验。\n2、精通食品行业质量管理体系（BRC、ISO 22000,、HACCP,、GMP等）及食品安全法规，具备丰富的供应商现场审核经验。\n3、出色的客诉分析与解决能力，熟练运用质量工具（如8D, 5Why, FMEA, SPC等）进行根本原因分析和持续改进。 4、扎实的沟通协调能力、谈判技巧及跨部门项目推动能力。优秀的团队协作精神，能够与研发、商品、生产商、服务体验等多部门高效协同。\n 5、能适应经常性的供应商工厂出差，具备一定的快节奏岗位适应能力。\n 6、掌握基本的AI工具，使用工具提升工作流程效率。","description":"部门介绍\n美团的使命是“帮大家吃得更好，生活更好”，公司聚焦“零售 + 科技”战略，和广大商户与各类合作伙伴一起，努力为消费者提供品质生活，推动商品零售和服务零售在需求侧和供给侧的数字化转型。\n2018年9月20日，美团正式在港交所挂牌上市。美团将始终坚持以客户为中心，不断加大在科技研发方面的投入，更好承担社会责任，更多创造社会价值，与广大合作伙伴一起发展共赢。\n\n岗位职责\n1、负责自营商品预包装食品的品质管理的全面规划与执行，确保商品在各个环节的品质标准得到有效控制。\n 2、建立和完善自营商品品质管理体系，包括制定自营商品品质管理流程、标准和指导文件，并监督执行情况、主导新品开发阶段的品质标准制定、配方与工艺评审。 \n3、负责供应商（特别是PB商品）的开发准入审核、定期验厂及风险评估。主导对供应商工厂的体系审核（如BRC 、FSSC 22000,、ISO 22000, HACCP等）与过程审核，现场评估其质量保证能力、生产条件与卫生控制水平。\n 4、负责自营商品品质问题的调查与处理，商品品质数据的统计和分析，及时发现问题并提出改进措施，提高产品品质和客户满意度，推动供应商质量能力提升；基于客诉及内外部检验数据，进行趋势分析，发起跨部门质量改进项目，系统性降低质量风险。\n\n岗位基本要求\n1、本科及以上学历，食品科学与工程、质量管理、农学等相关专业。5年以上食品制造业或大型零售/电商企业品质管理工作经验，研发经验；具备PB商品或自有品牌的质量管理经验。\n2、精通食品行业质量管理体系（BRC、ISO 22000,、HACCP,、GMP等）及食品安全法规，具备丰富的供应商现场审核经验。\n3、出色的客诉分析与解决能力，熟练运用质量工具（如8D, 5Why, FMEA, SPC等）进行根本原因分析和持续改进。 4、扎实的沟通协调能力、谈判技巧及跨部门项目推动能力。优秀的团队协作精神，能够与研发、商品、生产商、服务体验等多部门高效协同。\n 5、能适应经常性的供应商工厂出差，具备一定的快节奏岗位适应能力。\n 6、掌握基本的AI工具，使用工具提升工作流程效率。\n\n岗位亮点\n扁平化管理，团队氛围好，发展空间大，福利待遇好","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4702259651","sourceKey":"meituan_social","company":"美团","title":"小象超市-资产维护经理","city":"重庆市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4702259651&jobShareType=1","duty":"岗位职责：\n1.负责统筹所支持城市所属区域已运营的“小象超市”站点场址的资产管理工作，包括续约、关店、置换、升级、租金或其他费用的优化等等；\n2.处理站点场址的租赁合同在履行过程中发生的履约、纠纷、变更等工作；\n3.日常拜访和维护租赁场地租约权属各方的良好关系，建立通畅的沟通渠道；\n4.支持与协助运营团队或其他合作团队，出于公司业务提升、或安全合规等等目的，对资产管理提出的有关租赁场地、租赁关系等方面的改善需求；\n5.完成上级安排的其他日常工作安排，处理日常文书、书面汇报等工作。","requirements":"岗位基本要求：\n1.至少3年以上相关工作经验，有连锁零售或连锁餐饮等行业资产管理工作经验，或类似行业地产选址开发工作经验，或商业地产/商超等行业的商业招商工作经验；\n2.具备商业场址租赁管理相关法律常识；\n3.具备法律知识、文书起草及阅读理解能力；\n4.具备商业洽谈、谈判能力；\n5.了解零售行业租赁规则、熟悉行业运行机制；\n6.健康积极乐观的心态，以客户为中心，积极处理内外部客户的需求，善于协调各方面信息及资源，善于团队合作；\n7.善于接受新事物，学习能力强。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n岗位职责：\n1.负责统筹所支持城市所属区域已运营的“小象超市”站点场址的资产管理工作，包括续约、关店、置换、升级、租金或其他费用的优化等等；\n2.处理站点场址的租赁合同在履行过程中发生的履约、纠纷、变更等工作；\n3.日常拜访和维护租赁场地租约权属各方的良好关系，建立通畅的沟通渠道；\n4.支持与协助运营团队或其他合作团队，出于公司业务提升、或安全合规等等目的，对资产管理提出的有关租赁场地、租赁关系等方面的改善需求；\n5.完成上级安排的其他日常工作安排，处理日常文书、书面汇报等工作。\n\n岗位基本要求\n岗位基本要求：\n1.至少3年以上相关工作经验，有连锁零售或连锁餐饮等行业资产管理工作经验，或类似行业地产选址开发工作经验，或商业地产/商超等行业的商业招商工作经验；\n2.具备商业场址租赁管理相关法律常识；\n3.具备法律知识、文书起草及阅读理解能力；\n4.具备商业洽谈、谈判能力；\n5.了解零售行业租赁规则、熟悉行业运行机制；\n6.健康积极乐观的心态，以客户为中心，积极处理内外部客户的需求，善于协调各方面信息及资源，善于团队合作；\n7.善于接受新事物，学习能力强。\n\n具备以下条件优先\n具备拓展/资产管理岗位工作经验优先\n\n岗位亮点\n项目负责制、能充分发挥个人才华、团队工作氛围融洽","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4691692321","sourceKey":"meituan_social","company":"美团","title":"阿联酋-用户策略运营专家","city":"迪拜","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4691692321&jobShareType=1","duty":"1. 用户分层与策略设计\n基于用户生命周期（获客、激活、留存、回流），制定差异化用户运营策略\n建立用户分层体系，针对不同层级用户设计精准触达方案\n主导用户促活、留存、召回等核心策略的制定与落地\n\n2. 用户调研、数据分析与策略迭代\n通过用户调研和数据分析等工具进行用户行为数据分析，深挖用户需求场景与增长机会\n建立关键运营指标监控体系，及时识别业务异动并输出分析报告\n持续通过 A/B 测试验证策略效果，推动策略快速迭代优化\n\n3. 增长策略规划\n结合阿联酋本地市场特点（节日、消费习惯、文化差异），制定本地化运营策略\n参与用户增长专项项目，推动 DAU、复购率、用户 LTV 等核心指标提升\n跨部门协作（产品、市场、BD），推动策略落地执行\n\n4. 运营体系建设\n搭建可复用的用户运营 SOP 和策略框架\n沉淀方法论，推动团队运营能力标准化与规模化","requirements":"1、本科及以上学历，3年以上互联网用户运营/用户策略相关经验\n2、具备较强的数据分析能力，熟练使用 SQL / Hive 进行数据查询与分析\n3、有清晰的策略思维，能将业务问题拆解为可执行的运营方案\n4、具备英语工作能力","description":"部门介绍\nKeeta是全球领先外卖平台美团旗下的独立品牌，肩负着“帮大家吃得更好，生活更好”的使命。依托美团深耕中国市场15年的技术与运营积淀，我们正引领全球餐饮与商品即时配送服务的创新与发展。\n\n自2023年成立以来，Keeta始终扎根社区并创造价值。我们为用户提供可靠的外卖体验，以智慧技术助餐厅提升经营效率，在为骑手拓宽收入来源的同时，也充分提供安全保障措施。基于这份多方共赢、共同成长的理念，我们的业务已从中国香港稳步拓展至中东及巴西，并持续向世界迈进。\n\n岗位职责\n1. 用户分层与策略设计\n基于用户生命周期（获客、激活、留存、回流），制定差异化用户运营策略\n建立用户分层体系，针对不同层级用户设计精准触达方案\n主导用户促活、留存、召回等核心策略的制定与落地\n\n2. 用户调研、数据分析与策略迭代\n通过用户调研和数据分析等工具进行用户行为数据分析，深挖用户需求场景与增长机会\n建立关键运营指标监控体系，及时识别业务异动并输出分析报告\n持续通过 A/B 测试验证策略效果，推动策略快速迭代优化\n\n3. 增长策略规划\n结合阿联酋本地市场特点（节日、消费习惯、文化差异），制定本地化运营策略\n参与用户增长专项项目，推动 DAU、复购率、用户 LTV 等核心指标提升\n跨部门协作（产品、市场、BD），推动策略落地执行\n\n4. 运营体系建设\n搭建可复用的用户运营 SOP 和策略框架\n沉淀方法论，推动团队运营能力标准化与规模化\n\n岗位基本要求\n1、本科及以上学历，3年以上互联网用户运营/用户策略相关经验\n2、具备较强的数据分析能力，熟练使用 SQL / Hive 进行数据查询与分析\n3、有清晰的策略思维，能将业务问题拆解为可执行的运营方案\n4、具备英语工作能力\n\n具备以下条件优先\n1、有海外市场运营经验优先\n2、有外卖、电商、本地生活等平台用户增长经验优先\n3、有用户分层体系、会员体系搭建经验者优先\n\n岗位亮点\n1、参与出海核心市场从 0 到 1 的建设机会\n2、多元文化的国际化工作环境\n3、美团体系内成熟的平台资源与技术支持","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4705197979","sourceKey":"meituan_social","company":"美团","title":"装修维保经理","city":"北京市/上海市/广州市/成都市/深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4705197979&jobShareType=1","duty":"1. 负责装修项目的日常维保工作，包括巡检、故障排查及维修处理。  \n2. 协调内外部资源，推动维保问题的及时解决，确保项目正常运行。  \n3. 制定并优化装修维保流程和标准，提升服务质量和效率。  \n4. 管理维保相关文档和记录，定期输出维保报告并提出改进建议。","requirements":"1. 大学本科及以上学历，工程类、建筑类或相关专业优先。  \n2. 对冷库质制冷机组技术精通。\n3. 具备3年以上装修或工程维保相关工作经验。  \n4. 熟悉装修材料及施工工艺，具备基本的现场问题判断能力。  \n5. 具备良好的沟通协调能力和团队协作精神。","description":"部门介绍\n美团闪购是美团旗下的即时零售平台，依托即时配送能力，连接本地零售供给，满足消费者30分钟万物到家的即时需求。美团闪购涵盖超市便利、食材、水果、鲜花绿植、休闲零食、酒水饮料、数码家电、美妆个护、母婴玩具、日用百货、服饰鞋帽、宠物等诸多品类，业务覆盖全国近3,000个县市区旗，每日百万级在岗骑手，以高效的配送、丰富的品类和广泛的覆盖，为美团数亿用户带来便捷的生活体验，积极助力实体零售线上化转型，提升本地商业活力。\n\n岗位职责\n1. 负责装修项目的日常维保工作，包括巡检、故障排查及维修处理。  \n2. 协调内外部资源，推动维保问题的及时解决，确保项目正常运行。  \n3. 制定并优化装修维保流程和标准，提升服务质量和效率。  \n4. 管理维保相关文档和记录，定期输出维保报告并提出改进建议。\n\n岗位基本要求\n1. 大学本科及以上学历，工程类、建筑类或相关专业优先。  \n2. 对冷库质制冷机组技术精通。\n3. 具备3年以上装修或工程维保相关工作经验。  \n4. 熟悉装修材料及施工工艺，具备基本的现场问题判断能力。  \n5. 具备良好的沟通协调能力和团队协作精神。\n\n具备以下条件优先\n从事过冷库维修维保工作经验者优先\n\n岗位亮点\n1. 工作地点覆盖北京、上海、广州、成都、深圳等一线城市，发展机会多。  \n2. 初级岗位，适合有经验但希望稳定发展的候选人。  \n3. 工作内容贴近实际项目，实践性强，有助于积累综合管理能力。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4704972030","sourceKey":"meituan_social","company":"美团","title":"美团骑行-运营主管（沈阳）","city":"沈阳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4704972030&jobShareType=1","duty":"1. 负责沈阳地区车辆运营的日常管理与协调工作，确保车辆调度、维护和运营效率。  \n2. 支持软硬件系统的运营需求，协助解决车辆相关技术问题，提升用户体验。  \n3. 分析骑行数据，优化车辆投放策略，提升区域运营效益。  \n4. 协同经营一区团队，推动运营目标达成，支持区域业务增长。","requirements":"1. 大学本科及以上学历，具备3年以上运营支持或车辆运维相关工作经验。  \n2. 熟悉车辆运营流程，具备一定的数据分析能力和问题解决能力。  \n3. 了解软硬件系统基本原理，能与技术人员有效沟通协作。  \n4. 工作责任心强，具备良好的执行力和团队协作精神。","description":"部门介绍\n美团骑行事业部在全国各个城市开展美团单车、电单车业务，提供绿色、便捷的共享出行服务，是美团出行板块重要的组成部分。我们力求为城市可持续发展提供低碳智能的解决方案，通过技术创新和硬件升级，不断优化全流程骑行体验，为低碳出行提供更好的服务。其中，美团单车旨在为城市居民提供通勤接驳服务，满足用户短途接驳出行需求；美团电单车则满足用户中短途多场景低碳出行需求。\n我们有开放的工作氛围，也有充满韧劲和创造力，心系低碳出行的伙伴。加入我们，一起为用户创造更好的出行体验。\n\n岗位职责\n1. 负责沈阳地区车辆运营的日常管理与协调工作，确保车辆调度、维护和运营效率。  \n2. 支持软硬件系统的运营需求，协助解决车辆相关技术问题，提升用户体验。  \n3. 分析骑行数据，优化车辆投放策略，提升区域运营效益。  \n4. 协同经营一区团队，推动运营目标达成，支持区域业务增长。\n\n岗位基本要求\n1. 大学本科及以上学历，具备3年以上运营支持或车辆运维相关工作经验。  \n2. 熟悉车辆运营流程，具备一定的数据分析能力和问题解决能力。  \n3. 了解软硬件系统基本原理，能与技术人员有效沟通协作。  \n4. 工作责任心强，具备良好的执行力和团队协作精神。\n\n岗位亮点\n1. 参与城市出行生态建设，推动绿色出行发展。  \n2. 与跨职能团队紧密合作，积累多领域运营经验。  \n3. 在快速发展的业务中承担关键职责，具备成长空间。  \n4. 工作地点位于沈阳，享受本地化支持与资源倾斜。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3283653215","sourceKey":"meituan_social","company":"美团","title":"智能体（Agent）算法工程师","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3283653215&jobShareType=1","duty":"1、负责智能体（Agent）系统的全链路设计与开发，构建具备自主决策、动态规划能力的智能系统架构，实现复杂场景下的自动化执行；\n2、主导Agent核心算法的研发与优化，持续提升系统在多模态感知、工具调用、协作推理等领域的性能表现，包括数据、评测、架构、模型等方面的设计与优化；\n3、深度对接业务场景需求，与产品、数据、业务团队紧密协作，推动智能体技术在本地生活场景下的规模化应用，包括但不限于 搜索智能体、旅行智能体、餐饮智能体等；\n4、构建智能体系统评估体系，设计多维度的评估方案，持续提升系统在效果、规模和推理速度方面的技术指标；\n5、追踪行业前沿技术动态，探索大模型与Agent技术的融合应用，拓展智能体系统、多智能体系统的能力边界。","requirements":"1、对大模型以及智能体技术和应用有浓厚兴趣和较强的自我驱动力，能够主动分析解决问题；\n2、有基于PyTorch等深度学习框架以及Megatron等分布式框架的实战项目经验，具有较强的编程能力； \n3、具有扎实的算法理论基础，熟悉主流大模型以及多模态模型，对模型背后的原理和各自适用场景有一定的理解；\n4、深入理解ReAct等Agent框架原理，在任务规划、工具调用、策略优化等方向有实际项目经验；\n5、具备较强的团队协作能力和沟通能力，有较强的学习能力和业务分析及问题解决能力。","description":"部门介绍\n美团核心本地商业下业务研发平台，基于公司“零售+科技”的战略导向，通过从底层架构到应用系统、从软件到硬件、从传统算法到GenAI的全方位技术研究，以及开发、运维、安全等全流程能力建设，致力于推动美团核心本地商业下需求侧与供给侧的数字化和智能化升级，助力业务实现高质量增长，优化用户使用体验，提升商户经营水平，促进行业生态伙伴关系的持续健康发展。团队秉持务实、自驱、开放以及追求卓越的工程师文化，一方面通过系统和技术体系的持续迭代升级，帮助业务高质量增长；另一方面，密切关注前沿技术趋势变化，积极创新技术能力，为业务未来发展创造新的可能性。期待优秀的你加入我们，在夯实专业、深耕平台的基础上与业务携手同行，一起用技术 “帮大家吃得更好，生活更好”。\n\n岗位职责\n1、负责智能体（Agent）系统的全链路设计与开发，构建具备自主决策、动态规划能力的智能系统架构，实现复杂场景下的自动化执行；\n2、主导Agent核心算法的研发与优化，持续提升系统在多模态感知、工具调用、协作推理等领域的性能表现，包括数据、评测、架构、模型等方面的设计与优化；\n3、深度对接业务场景需求，与产品、数据、业务团队紧密协作，推动智能体技术在本地生活场景下的规模化应用，包括但不限于 搜索智能体、旅行智能体、餐饮智能体等；\n4、构建智能体系统评估体系，设计多维度的评估方案，持续提升系统在效果、规模和推理速度方面的技术指标；\n5、追踪行业前沿技术动态，探索大模型与Agent技术的融合应用，拓展智能体系统、多智能体系统的能力边界。\n\n岗位基本要求\n1、对大模型以及智能体技术和应用有浓厚兴趣和较强的自我驱动力，能够主动分析解决问题；\n2、有基于PyTorch等深度学习框架以及Megatron等分布式框架的实战项目经验，具有较强的编程能力； \n3、具有扎实的算法理论基础，熟悉主流大模型以及多模态模型，对模型背后的原理和各自适用场景有一定的理解；\n4、深入理解ReAct等Agent框架原理，在任务规划、工具调用、策略优化等方向有实际项目经验；\n5、具备较强的团队协作能力和沟通能力，有较强的学习能力和业务分析及问题解决能力。\n\n具备以下条件优先\n1、在智能体和大模型后训练等领域有研究成果者或者实际落地经验优先；\n2、在国际顶级会议（NeurIPS/ICML/AAAI/ICLR/ACL等）发表相关论文者优先；\n3、具备有良好的代码开发能力，有一定影响力的开源社区项目开发经验或者在具有影响力的编程比赛中获得较好名次。\n\n岗位亮点\n1、参与美团商业场景的智能化改造，接触前沿的人工智能技术；\n2、在快速发展的领域中积累经验，成为大模型和智能体领域的技术专家；\n3、拥有业界一流的团队，其成员大多来自国内外名校，支持进行前沿技术与业务探索；\n4、创新型团队扁平化管理，直接参与面向用户的应用探索。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4704716227","sourceKey":"meituan_social","company":"美团","title":"无人车资深系统BSP开发","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4704716227&jobShareType=1","duty":"1、负责自动驾驶域控制器/车载计算平台的新硬件 BSP 开发与 Bringup，包括 Bootloader 移植、设备树配置、内核裁剪与启动优化，支撑新硬件平台的快速导入和量产落地。\n2、负责车载计算平台 Linux BSP 的维护与迭代，包括内核驱动开发（PCIe、CAN、Ethernet、GPIO、I2C/SPI/UART 等总线）、HAL 层开发、以及内核子系统（调度、内存、文件系统、网络协议栈）的深度定制与优化。\n3、负责传感器 BSP 集成与稳定性保障，支撑 Lidar、Camera、GNSS、Audio、IMU 等外设的驱动适配、接口调试、数据链路验证，确保自动驾驶感知系统在目标硬件平台上的高性能与高可靠性。\n4、建立 BSP 开发规范与交付体系，包括固件版本管理、量产烧录流程、OTA 升级底座搭建、BSP 回归测试平台构建，持续提升自动驾驶硬件平台的工程化能力和规模化部署效率。\n5、参与车载分布式系统的底层平台设计与性能优化，与硬件团队紧密协作完成板级信号验证、硬件问题定位与修复，为自动驾驶系统的全栈研发迭代提供可靠的 BSP 底座支撑。","requirements":"1、计算机、电子、通信等相关专业本科及以上学历，5 年以上 Linux BSP/嵌入式系统开发经验。\n2、OS 功底扎实，具备出色的 C/C++ 软件工程能力。熟悉常见处理器架构，精通 Linux 内核至少 2 个以上子系统（如 PCIe、线程调度、内存管理、文件系统、网络协议栈、总线和外设驱动等）。\n3、具备丰富的硬件 Bringup 经验，熟悉 Bootloader（U-Boot/UEFI）开发、设备树（Device Tree）配置、内核移植与裁剪，能够独立完成新硬件平台的 BSP 开发与上电验证。\n4、具备丰富的 Linux 驱动和 HAL 开发经验，熟悉常见总线接口（I2C、SPI、UART、CAN、PCIe、Ethernet 等），有 Lidar、Camera、GNSS、Audio 等传感器驱动开发经验者优先。\n5、熟悉自动驾驶系统软硬件架构，对域控制器硬件平台、分布式消息中间件和自动驾驶 framework 框架有深入理解，具备系统级问题定位和性能优化实战经验。\n6、具备良好的系统分析能力、出色的抽象和逻辑思维能力，能快速分析复杂硬件/软件问题并给出合理的解决方案。\n7、具备技术和业务的综合能力，能够从不同维度和层面全面思考和处理各种问题。具有出色的学习能力，保持技术栈的持续更新迭代。工作积极主动，具有强烈的责任心。","description":"部门介绍\n无人车业务部成立于2016年，旨在用无人驾驶技术提升物流配送的效率和体验。美团无人车以自研L4级自动驾驶软硬件技术为核心，与美团即时零售业务结合，形成满足公开道路、社区、工业园区等室外全场景下的无人配送整体解决方案。自2020年起，无人车已在北京、深圳等多地进入常态化试运营阶段，在城市复杂场景下提供针对餐饮外卖、生鲜食杂等货物的即时配送服务。2025年，美团无人车又踏上了同城货运的新探索，并在2026年持续扩大运营范围和车队数量，为更多城市带来智能配送服务。\n欢迎加入美团无人车团队，与我们一起用科技推动即时零售再升级！\n\n岗位职责\n1、负责自动驾驶域控制器/车载计算平台的新硬件 BSP 开发与 Bringup，包括 Bootloader 移植、设备树配置、内核裁剪与启动优化，支撑新硬件平台的快速导入和量产落地。\n2、负责车载计算平台 Linux BSP 的维护与迭代，包括内核驱动开发（PCIe、CAN、Ethernet、GPIO、I2C/SPI/UART 等总线）、HAL 层开发、以及内核子系统（调度、内存、文件系统、网络协议栈）的深度定制与优化。\n3、负责传感器 BSP 集成与稳定性保障，支撑 Lidar、Camera、GNSS、Audio、IMU 等外设的驱动适配、接口调试、数据链路验证，确保自动驾驶感知系统在目标硬件平台上的高性能与高可靠性。\n4、建立 BSP 开发规范与交付体系，包括固件版本管理、量产烧录流程、OTA 升级底座搭建、BSP 回归测试平台构建，持续提升自动驾驶硬件平台的工程化能力和规模化部署效率。\n5、参与车载分布式系统的底层平台设计与性能优化，与硬件团队紧密协作完成板级信号验证、硬件问题定位与修复，为自动驾驶系统的全栈研发迭代提供可靠的 BSP 底座支撑。\n\n岗位基本要求\n1、计算机、电子、通信等相关专业本科及以上学历，5 年以上 Linux BSP/嵌入式系统开发经验。\n2、OS 功底扎实，具备出色的 C/C++ 软件工程能力。熟悉常见处理器架构，精通 Linux 内核至少 2 个以上子系统（如 PCIe、线程调度、内存管理、文件系统、网络协议栈、总线和外设驱动等）。\n3、具备丰富的硬件 Bringup 经验，熟悉 Bootloader（U-Boot/UEFI）开发、设备树（Device Tree）配置、内核移植与裁剪，能够独立完成新硬件平台的 BSP 开发与上电验证。\n4、具备丰富的 Linux 驱动和 HAL 开发经验，熟悉常见总线接口（I2C、SPI、UART、CAN、PCIe、Ethernet 等），有 Lidar、Camera、GNSS、Audio 等传感器驱动开发经验者优先。\n5、熟悉自动驾驶系统软硬件架构，对域控制器硬件平台、分布式消息中间件和自动驾驶 framework 框架有深入理解，具备系统级问题定位和性能优化实战经验。\n6、具备良好的系统分析能力、出色的抽象和逻辑思维能力，能快速分析复杂硬件/软件问题并给出合理的解决方案。\n7、具备技术和业务的综合能力，能够从不同维度和层面全面思考和处理各种问题。具有出色的学习能力，保持技术栈的持续更新迭代。工作积极主动，具有强烈的责任心。\n\n具备以下条件优先\n1、熟悉 Linux 内核多个子系统，不限于：PCIe、线程调度、内存管理、文件系统、网络协议栈、总线和外设驱动等。\n2、具有车载计算平台（如 NVIDIA Orin/Xavier、TI TDA4、地平线 J5 等）BSP 开发经验。\n3、熟悉 Yocto/Buildroot 等嵌入式 Linux 构建系统，具备量产固件打包、OTA 升级、安全启动（Secure Boot）开发经验。\n4、具有硬件调试经验，熟练使用示波器、逻辑分析仪等工具进行信号分析和硬件问题定位。\n5、有 AUTOSAR Classic/Adaptive 或车载以太网（TSN/SOMEIP）开发经验。\n\n岗位亮点\n1、自动驾驶域控制器 BSP 是自动驾驶系统的核心底座，直接决定硬件平台的可量产性和系统稳定性，技术挑战度高，对个人技术深度和广度都有极大锻炼。\n2、深入参与前沿自动驾驶硬件平台的研发与量产落地，跨越芯片 Bringup、内核定制、驱动开发、量产交付全链路，全面拓宽 BSP 工程师的职业发展空间。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4679585423","sourceKey":"meituan_social","company":"美团","title":"AI产研效能专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4679585423&jobShareType=1","duty":"1、负责骑行S/A项目的推进，包括资源协调、进度跟进、过程监控、风险识别、可视化和数据收集分析等，对项目结果负责，综合提升各方满意度。\n2、牵头产研效能度量体系建设，作为中立第三方开展效能度量工作，包括采集试点前基线数据、定义统一口径、跟踪交付周期及AI使用率等关键指标，持续输出效能洞察分析报告，为管理层决策提供数据支撑。\n3、负责跨团队范式沉淀，提炼最佳实践和反模式，推动敏捷实践在流程、工程、工具、意识等各层面落地，持续优化工具和度量体系。\n4、参与AI变革项目集管理，推动产研端到端协作新范式落地及AI体系治理工作，探索AI Native敏捷模式下的项目管理新方法。\n5、推动项目管理数字化建设，将项目管理方法论沉淀为数字化工具和AI Agent能力，提升PMO团队的工作效率和数字化水平。\n6、其它跨部门的协作工作。","requirements":"1、具备至少3年以上重点产研项目管理经验，能够进行多项目并行管理，互联网行业背景优先。\n2、对项目管理、敏捷开发、产研度量相关领域知识有深刻理解，能够综合运用相关知识去解决各种复杂问题，并具备良好的相关管理、工具和度量体系搭建能力，不断提升产研效能。\n3、有AI Agent建设或数字化转型项目经验者，对于AI产研效能度量有关键认知。\n4、优秀的个人沟通和推动能力，能够和不同层级的人灵活沟通，尤其是高层管理人员的沟通，并能够借力拿到结果。\n5、勤于思考，能够不断抽象问题、归纳总结，推动相关工作效率不断提升。","description":"部门介绍\n美团骑行事业部在全国各个城市开展美团单车、电单车业务，提供绿色、便捷的共享出行服务，是美团出行板块重要的组成部分。我们力求为城市可持续发展提供低碳智能的解决方案，通过技术创新和硬件升级，不断优化全流程骑行体验，为低碳出行提供更好的服务。其中，美团单车旨在为城市居民提供通勤接驳服务，满足用户短途接驳出行需求；美团电单车则满足用户中短途多场景低碳出行需求。\n我们有开放的工作氛围，也有充满韧劲和创造力，心系低碳出行的伙伴。加入我们，一起为用户创造更好的出行体验。\n\n岗位职责\n1、负责骑行S/A项目的推进，包括资源协调、进度跟进、过程监控、风险识别、可视化和数据收集分析等，对项目结果负责，综合提升各方满意度。\n2、牵头产研效能度量体系建设，作为中立第三方开展效能度量工作，包括采集试点前基线数据、定义统一口径、跟踪交付周期及AI使用率等关键指标，持续输出效能洞察分析报告，为管理层决策提供数据支撑。\n3、负责跨团队范式沉淀，提炼最佳实践和反模式，推动敏捷实践在流程、工程、工具、意识等各层面落地，持续优化工具和度量体系。\n4、参与AI变革项目集管理，推动产研端到端协作新范式落地及AI体系治理工作，探索AI Native敏捷模式下的项目管理新方法。\n5、推动项目管理数字化建设，将项目管理方法论沉淀为数字化工具和AI Agent能力，提升PMO团队的工作效率和数字化水平。\n6、其它跨部门的协作工作。\n\n岗位基本要求\n1、具备至少3年以上重点产研项目管理经验，能够进行多项目并行管理，互联网行业背景优先。\n2、对项目管理、敏捷开发、产研度量相关领域知识有深刻理解，能够综合运用相关知识去解决各种复杂问题，并具备良好的相关管理、工具和度量体系搭建能力，不断提升产研效能。\n3、有AI Agent建设或数字化转型项目经验者，对于AI产研效能度量有关键认知。\n4、优秀的个人沟通和推动能力，能够和不同层级的人灵活沟通，尤其是高层管理人员的沟通，并能够借力拿到结果。\n5、勤于思考，能够不断抽象问题、归纳总结，推动相关工作效率不断提升。\n\n具备以下条件优先\n1、有出行/骑行行业经验优先；\n2、持有PMP、P2、MSP、ACP认证者优先。\n\n岗位亮点\n美团骑行业务正处于AI Native转型的关键时期，该岗位有很好的机会参与到骑行产研AI变革的全方位建设中去。我们的业务涵盖共享单车、电单车、租车SaaS等多元化业务形态，服务了国内数亿用户的出行需求。在这里，你将深度参与敏捷效能度量体系搭建、AI驱动的项目管理数字化建设，用数据和工具驱动产研效能持续提升。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4654923911","sourceKey":"meituan_social","company":"美团","title":"重庆城市经理","city":"重庆市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4654923911&jobShareType=1","duty":"1. 负责组建高质量的销售、采购团队，对团队梯队搭建、人才培养、人员管理负责；\n2. 负责城市目标、策略制定及分解、落地负责，确保在正确的策略下完成业务目标，同时沉淀方法论；\n3. 带领团队帮助客户更好进行服务规划、完成服务目标、提升服务满意度，从而提升公司品牌影响力；\n4. 协调总部相关部门带领采销仓配出色完成业务目标；\n5.从运营的各个环的运营中发现问题、提出建议、建立流程持续提高城市团队运营效率。\n6.熟悉并擅长使用AI工具","requirements":"1.大专以上毕业，5年以上工作经验；\n2.有大规模直销管理经验则优先考虑；\n3.有食材经验值优先考虑；\n4.超强的使命感和执行力、不屈不挠的斗志、能吃苦；\n岗位亮点:\n行业发展增长潜力大，发展空间大；\n有机会不断提升个人职业素养和管理能力；\n具备以下优先:\n有零售行业优先","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1. 负责组建高质量的销售、采购团队，对团队梯队搭建、人才培养、人员管理负责；\n2. 负责城市目标、策略制定及分解、落地负责，确保在正确的策略下完成业务目标，同时沉淀方法论；\n3. 带领团队帮助客户更好进行服务规划、完成服务目标、提升服务满意度，从而提升公司品牌影响力；\n4. 协调总部相关部门带领采销仓配出色完成业务目标；\n5.从运营的各个环的运营中发现问题、提出建议、建立流程持续提高城市团队运营效率。\n6.熟悉并擅长使用AI工具\n\n岗位基本要求\n1.大专以上毕业，5年以上工作经验；\n2.有大规模直销管理经验则优先考虑；\n3.有食材经验值优先考虑；\n4.超强的使命感和执行力、不屈不挠的斗志、能吃苦；\n岗位亮点:\n行业发展增长潜力大，发展空间大；\n有机会不断提升个人职业素养和管理能力；\n具备以下优先:\n有零售行业优先\n\n岗位亮点\n零售业务、大平台、多客群发展机会、供应链协同","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4702892432","sourceKey":"meituan_social","company":"美团","title":"外卖搜索算法工程师","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4702892432&jobShareType=1","duty":"负责搜索重混排模型的设计与优化。在容器混排框架下，以GE（Generative）范式为核心，重点探索生成式重排与Listwise建模方法，实现容器内商品的最优排列，驱动业务核心指标提升；同时推动AutoResearch能力在排序迭代中的落地应用，系统性提升实验效率与模型演进速度。","requirements":"• 3年及以上搜索/推荐/广告排序算法经验\n• 有容器混排、Listwise建模、生成式重排等方向的实际落地经验\n• 能独立完成从方案设计、离线验证到线上部署的全流程闭环\n• 熟练掌握TensorFlow/PyTorch等主流深度学习框架","description":"部门介绍\n美团核心本地商业下业务研发平台，基于公司“零售+科技”的战略导向，通过从底层架构到应用系统、从软件到硬件、从传统算法到GenAI的全方位技术研究，以及开发、运维、安全等全流程能力建设，致力于推动美团核心本地商业下需求侧与供给侧的数字化和智能化升级，助力业务实现高质量增长，优化用户使用体验，提升商户经营水平，促进行业生态伙伴关系的持续健康发展。团队秉持务实、自驱、开放以及追求卓越的工程师文化，一方面通过系统和技术体系的持续迭代升级，帮助业务高质量增长；另一方面，密切关注前沿技术趋势变化，积极创新技术能力，为业务未来发展创造新的可能性。期待优秀的你加入我们，在夯实专业、深耕平台的基础上与业务携手同行，一起用技术 “帮大家吃得更好，生活更好”。\n\n岗位职责\n负责搜索重混排模型的设计与优化。在容器混排框架下，以GE（Generative）范式为核心，重点探索生成式重排与Listwise建模方法，实现容器内商品的最优排列，驱动业务核心指标提升；同时推动AutoResearch能力在排序迭代中的落地应用，系统性提升实验效率与模型演进速度。\n\n岗位基本要求\n• 3年及以上搜索/推荐/广告排序算法经验\n• 有容器混排、Listwise建模、生成式重排等方向的实际落地经验\n• 能独立完成从方案设计、离线验证到线上部署的全流程闭环\n• 熟练掌握TensorFlow/PyTorch等主流深度学习框架\n\n具备以下条件优先\n• AutoResearch/自动化实验平台的建设或深度使用经验\n• LLM在重排场景的探索与应用经验\n• 顶会论文发表（SIGIR/KDD/WWW/NeurIPS等）\n\n岗位亮点\n岗位直接服务外卖的高优先级目标，搜索流量规模大、业务链路长且系统复杂，对模型效果、实时性和稳定性都有极高要求；同时聚焦容器混排、生成式重排、Listwise、AutoResearch 等前沿方向，能够在大规模真实业务中完成从技术探索到线上收益验证的闭环，成长空间和个人影响力都很大。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4690845196","sourceKey":"meituan_social","company":"美团","title":"搜索算法工程师","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4690845196&jobShareType=1","duty":"1、负责美团到餐业务的搜索算法策略迭代，优化用户搜索体验，提升点击率、转化率等核心指标。\n2、应用大规模机器学习模型和系统，优化查询理解、召回、粗排、精排、重排等算法模块。 \n3、探索并落地LLM/大模型在搜索全链路中的应用，包括基于大模型的Query理解、语义召回、智能排序、结果摘要与推荐理由生成等，提升搜索智能化水平。\n4、跟进AI Agent、RAG、向量检索等前沿技术在本地生活搜索场景的应用，推动生成式AI与检索系统的深度融合。\n5、深入思考产品业务价值，参与制定及落实团队在技术、业务等多维度发展方向。 \n6、与其他团队密切合作，包括数据工程师、前后端工程师、产品经理等，实现高质量的产品和解决方案。","requirements":"1、拥有计算机、电子、通信、数学、统计学或相关专业的本科及以上学历，具备5年及以上工作经验。\n2、熟悉掌握机器学习和深度学习算法，在搜索、广告或推荐等领域有实际工作经验，并在多目标优化、序列建模、深度召回等一个或多个方向有深入研究。\n3、熟练使用Hive/Spark/Hadoop等大数据工具，熟悉TensorFlow/PyTorch等框架，具备大规模深度学习项目实际经验，具备良好的代码开发能力。\n4、具备一定的业务敏感度，创新精神和理论与实践相结合的能力，具有主动思考和学习的动力，乐于与业务共同成长。\n5、熟悉LLM原理及主流大模型（如GPT、Claude、LLaMA、Qwen等）的应用范式，具备大模型微调（Fine-tuning/PEFT）、RAG、Agent开发等实际项目经验；了解多模态大模型在图文理解中的应用优先。\n5、具备出色的问题分析和解决能力，具有团队合作意识，对具有挑战性的问题充满激情，对AI技术驱动业务增长有强烈热情和实践经验。","description":"部门介绍\n美团核心本地商业下业务研发平台，基于公司“零售+科技”的战略导向，通过从底层架构到应用系统、从软件到硬件、从传统算法到GenAI的全方位技术研究，以及开发、运维、安全等全流程能力建设，致力于推动美团核心本地商业下需求侧与供给侧的数字化和智能化升级，助力业务实现高质量增长，优化用户使用体验，提升商户经营水平，促进行业生态伙伴关系的持续健康发展。团队秉持务实、自驱、开放以及追求卓越的工程师文化，一方面通过系统和技术体系的持续迭代升级，帮助业务高质量增长；另一方面，密切关注前沿技术趋势变化，积极创新技术能力，为业务未来发展创造新的可能性。期待优秀的你加入我们，在夯实专业、深耕平台的基础上与业务携手同行，一起用技术 “帮大家吃得更好，生活更好”。\n\n岗位职责\n1、负责美团到餐业务的搜索算法策略迭代，优化用户搜索体验，提升点击率、转化率等核心指标。\n2、应用大规模机器学习模型和系统，优化查询理解、召回、粗排、精排、重排等算法模块。 \n3、探索并落地LLM/大模型在搜索全链路中的应用，包括基于大模型的Query理解、语义召回、智能排序、结果摘要与推荐理由生成等，提升搜索智能化水平。\n4、跟进AI Agent、RAG、向量检索等前沿技术在本地生活搜索场景的应用，推动生成式AI与检索系统的深度融合。\n5、深入思考产品业务价值，参与制定及落实团队在技术、业务等多维度发展方向。 \n6、与其他团队密切合作，包括数据工程师、前后端工程师、产品经理等，实现高质量的产品和解决方案。\n\n岗位基本要求\n1、拥有计算机、电子、通信、数学、统计学或相关专业的本科及以上学历，具备5年及以上工作经验。\n2、熟悉掌握机器学习和深度学习算法，在搜索、广告或推荐等领域有实际工作经验，并在多目标优化、序列建模、深度召回等一个或多个方向有深入研究。\n3、熟练使用Hive/Spark/Hadoop等大数据工具，熟悉TensorFlow/PyTorch等框架，具备大规模深度学习项目实际经验，具备良好的代码开发能力。\n4、具备一定的业务敏感度，创新精神和理论与实践相结合的能力，具有主动思考和学习的动力，乐于与业务共同成长。\n5、熟悉LLM原理及主流大模型（如GPT、Claude、LLaMA、Qwen等）的应用范式，具备大模型微调（Fine-tuning/PEFT）、RAG、Agent开发等实际项目经验；了解多模态大模型在图文理解中的应用优先。\n5、具备出色的问题分析和解决能力，具有团队合作意识，对具有挑战性的问题充满激情，对AI技术驱动业务增长有强烈热情和实践经验。\n\n岗位亮点\n1、团队业务紧跟公司的业务目标，每一次策略迭代都能给公司的业务目标带来具体的价值，实现自我价值和个人成就感。\n2、团队成员大多来自于名校和名企，在这里有机会学习、尝试和落地业界先进技术。\n3、业务处于快速发展阶段，能够为个人提供了快速成长的空间，拥有自主迭代的决策权，更好地实现创新。\n4、团队正处于传统搜推向\"AI+搜索\"转型的关键阶段，深度参与大模型在本地生活搜索的落地，有机会定义下一代智能搜索产品形态。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4311923014","sourceKey":"meituan_social","company":"美团","title":"Media Buying","city":"利雅得","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4311923014&jobShareType=1","duty":"The role is mainly focused on follow ups, handling the implementation on the system, and ensuring everything is executed and on track.","requirements":"•Highly dedicated and committed to work\n  •Strong follow up and organizational skills\n  •Detail oriented and responsible\n  •Positive attitude and strong sense of ownership","description":"部门介绍\n美团的使命是“帮大家吃得更好，生活更好”，公司聚焦“零售 + 科技”战略，和广大商户与各类合作伙伴一起，努力为消费者提供品质生活，推动商品零售和服务零售在需求侧和供给侧的数字化转型。\n2018年9月20日，美团正式在港交所挂牌上市。美团将始终坚持以客户为中心，不断加大在科技研发方面的投入，更好承担社会责任，更多创造社会价值，与广大合作伙伴一起发展共赢。\n\n岗位职责\nThe role is mainly focused on follow ups, handling the implementation on the system, and ensuring everything is executed and on track.\n\n岗位基本要求\n•Highly dedicated and committed to work\n  •Strong follow up and organizational skills\n  •Detail oriented and responsible\n  •Positive attitude and strong sense of ownership\n\n岗位亮点\n•\tStrong learning and development environment with hands-on experience\n\t•\tExposure to real business operations and system workflows\n\t•\tOpportunity to build core skills in coordination, follow-up, and execution\n\t•\tWork closely with experienced team members and learn from them\n\t•\tSupportive and collaborative team environment","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4664437335","sourceKey":"meituan_social","company":"美团","title":"下沉市场 - 运力线管理","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4664437335&jobShareType=1","duty":"1.结合业务发展需求，制定各阶段运力规模增长、留存策略，协同各相关推动方案落地，构建运力壁垒；对稳定的配送体验负责，保证运力弹性及基础体验指标在合理范围内；\n2.统筹运力全生命周期管理，有效助推运力等级与权益精细，从而实现有效控本和提升服务质量；\n3.通过建立针对骑手的运力管理体系，促进运力管理效率提升，提升专送运力池承载能力和弹性；\n4.运力管理能力重塑：深度理解运力管理场景与业务模式，挖掘AI Agent应用场景，推动运力管理的智能化升级与模式重构。","requirements":"1.本科以上学历，3年及以上工作经验，有即时配送物流、O2O等相关行业策略产品或策略运营经验者优先；\n2.具备AI应用场景的识别与设计思维，能将运力管理痛点转化为AI可解决的业务需求，推动智能化工具在运营场景中的落地应用。\n3.具备项目管理和跨部门合作能力，能够主导并高效完成项目的规划和执行；行业视野广，具有较强的工作投入度及自驱力；","description":"部门介绍\n美团核心本地商业-下沉市场发展部于2015年成立，通过招募优质的合作商伙伴并对其业务经营能力、组织能力等赋能，以期为下沉城市提供一站式的本地生活服务。\n下沉市场发展部的业务场景涵盖了外卖餐饮、团购、拼好饭、闪购、医药等多元化的生活服务领域，同时搭建了一套稳定、高效的即时配送网络，为更多本地用户提供品质化、多样化、便捷高效的生活服务体验，为当地商户提供数字化发展机遇、提升数字化水平，为社会创造更多的就地就业机会。\n截至2024年6月，下沉市场发展部已开拓全国4000+县区市，帮助百万商户实现本地生活服务数字化，日订单量突破千万，为数十万名骑手提供就业岗位，让本地生活服务逐渐成长为地方新基建，实现美团“帮助大家吃得更好，生活更好”的使命！\n\n岗位职责\n1.结合业务发展需求，制定各阶段运力规模增长、留存策略，协同各相关推动方案落地，构建运力壁垒；对稳定的配送体验负责，保证运力弹性及基础体验指标在合理范围内；\n2.统筹运力全生命周期管理，有效助推运力等级与权益精细，从而实现有效控本和提升服务质量；\n3.通过建立针对骑手的运力管理体系，促进运力管理效率提升，提升专送运力池承载能力和弹性；\n4.运力管理能力重塑：深度理解运力管理场景与业务模式，挖掘AI Agent应用场景，推动运力管理的智能化升级与模式重构。\n\n岗位基本要求\n1.本科以上学历，3年及以上工作经验，有即时配送物流、O2O等相关行业策略产品或策略运营经验者优先；\n2.具备AI应用场景的识别与设计思维，能将运力管理痛点转化为AI可解决的业务需求，推动智能化工具在运营场景中的落地应用。\n3.具备项目管理和跨部门合作能力，能够主导并高效完成项目的规划和执行；行业视野广，具有较强的工作投入度及自驱力；\n\n具备以下条件优先\nAI应用场景有实际经验，即时配送物流、O2O等相关行业策略产品或策略运营经验者优先；\n\n岗位亮点\n1.优秀大厂的核心业务，组织稳定，风格严肃活泼。专注于为下沉市场用户解决万物到家的需求，负责全国近2000个城市的配送业务，间接管理几十万骑手，业务体量大且刚需，可探索的空间大，价值感强。\n2.业务所在的万物到家，以及同城配送行业，业务场景丰富，配送链条中调度、定价、路径规划、骑手匹配等环节均有大量AI应用探索场景，技术与业务深度结合，具备将前沿AI能力转化为实际业务价值的高效路径，行业具备很好的成长空间，个人有较大的发展机遇。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4604098647","sourceKey":"meituan_social","company":"美团","title":"小象超市-用户运营专家（投放方向）","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4604098647&jobShareType=1","duty":"1、投放策略与用户增长：负责小象超市App在抖音、快手、广告等主流媒体平台的效果广告投放策略制定与执行，对年度获客规模、获客成本（CAC）及投放ROI负责；\n2、数据驱动优化：建立广告投放的完整数据监控与分析体系，实时监控各渠道投放表现，通过数据分析发现优化机会，产出投放复盘报告与策略迭代方案；\n3、渠道管理与算法应用：深入理解各广告平台的流量拍卖机制与算法逻辑，结合业务场景制定差异化投放策略，运用智能出价、程序化投放等工具提升投放效率；\n4、AI赋能投放全流程：运用AI工具辅助广告策略优化，包括AI辅助素材生成与审核、智能人群定向策略、自动化投放调优、投放效果归因分析等，推动AI在投放工作流中的落地应用；\n5、创意与素材协同：基于投放数据洞察，提出广告创意优化方向，协同设计团队打磨高转化素材，持续提升点击率、转化率和ROI；\n6、新渠道探索与测试：持续关注新兴媒体渠道和投放玩法（如AI广告、本地推、搜索意图广告等），评估并测试新渠道的投放效果，沉淀可复用的投放方法论；\n7、跨部门协作与项目推动：与产品、数据、市场等团队紧密协作，推动投放策略与产品功能联动优化，以项目制方式推进重点投放项目落地。","requirements":"1、本科及以上学历，市场营销、广告学、统计学、经济学、计算机等相关专业优先；\n2、5年以上互联网效果广告投放经验，有电商/即时零售/本地生活行业经验优先；\n3、熟悉抖音、快手、广告等平台投放逻辑与工具，具备信息流广告和搜索广告实操经验；\n4、数据驱动意识强，具备较强的数据分析与建模能力，能通过数据发现问题、制定策略、验证效果。熟练使用SQL、Python或类似数据工具者优先；\n5、对AI在广告领域的应用有认知或实践经验，包括但不限于AI辅助创意生成、智能投放策略、自动化数据报告等，能主动探索AI工具在工作中的落地场景；\n6、逻辑清晰，结构化思维能力强，能够独立完成复杂业务问题的拆解与策略设计；\n7、具备优秀的沟通协调能力和跨部门项目推动能力，自驱力强，能在快速变化的业务环境中独立推进工作；\n8、对广告行业趋势敏感，关注AI技术对广告投放的影响，有持续学习和探索的习惯。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1、投放策略与用户增长：负责小象超市App在抖音、快手、广告等主流媒体平台的效果广告投放策略制定与执行，对年度获客规模、获客成本（CAC）及投放ROI负责；\n2、数据驱动优化：建立广告投放的完整数据监控与分析体系，实时监控各渠道投放表现，通过数据分析发现优化机会，产出投放复盘报告与策略迭代方案；\n3、渠道管理与算法应用：深入理解各广告平台的流量拍卖机制与算法逻辑，结合业务场景制定差异化投放策略，运用智能出价、程序化投放等工具提升投放效率；\n4、AI赋能投放全流程：运用AI工具辅助广告策略优化，包括AI辅助素材生成与审核、智能人群定向策略、自动化投放调优、投放效果归因分析等，推动AI在投放工作流中的落地应用；\n5、创意与素材协同：基于投放数据洞察，提出广告创意优化方向，协同设计团队打磨高转化素材，持续提升点击率、转化率和ROI；\n6、新渠道探索与测试：持续关注新兴媒体渠道和投放玩法（如AI广告、本地推、搜索意图广告等），评估并测试新渠道的投放效果，沉淀可复用的投放方法论；\n7、跨部门协作与项目推动：与产品、数据、市场等团队紧密协作，推动投放策略与产品功能联动优化，以项目制方式推进重点投放项目落地。\n\n岗位基本要求\n1、本科及以上学历，市场营销、广告学、统计学、经济学、计算机等相关专业优先；\n2、5年以上互联网效果广告投放经验，有电商/即时零售/本地生活行业经验优先；\n3、熟悉抖音、快手、广告等平台投放逻辑与工具，具备信息流广告和搜索广告实操经验；\n4、数据驱动意识强，具备较强的数据分析与建模能力，能通过数据发现问题、制定策略、验证效果。熟练使用SQL、Python或类似数据工具者优先；\n5、对AI在广告领域的应用有认知或实践经验，包括但不限于AI辅助创意生成、智能投放策略、自动化数据报告等，能主动探索AI工具在工作中的落地场景；\n6、逻辑清晰，结构化思维能力强，能够独立完成复杂业务问题的拆解与策略设计；\n7、具备优秀的沟通协调能力和跨部门项目推动能力，自驱力强，能在快速变化的业务环境中独立推进工作；\n8、对广告行业趋势敏感，关注AI技术对广告投放的影响，有持续学习和探索的习惯。\n\n具备以下条件优先\n有互联网公司、LBS类业务效果投放经验者优先，具备多业务场景投放经验者优先。\n\n岗位亮点\n1、加入快速发展的新零售业务，参与千万级用户规模的产品运营；\n2、获得丰富的业务实战与成长机会；\n3、扁平化管理，拥有充分的自主权与创新空间； \n4、AI+投放前沿：美团正在推进AI技术在广告投放领域的深度应用，加入后有机会参与AI辅助投放策略、智能素材生成等前沿项目，成为AI时代广告运营的先驱者。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4226385652","sourceKey":"meituan_social","company":"美团","title":"医药工业广告","city":"石家庄市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4226385652&jobShareType=1","duty":"1.负责美团医药大客户广告产品的线上入驻和维护，促成客户与平台的持续合作；\n2.通过主动电话外呼进行招商，与合作商户负责人沟通建立客情；\n3.洞察经营需求，并提供专业的线上代运营方案：店铺设置，产品优化，活动报名，节日营销等；","requirements":"1.大专及以上学历；\n2.有电销、销售经验优先；\n3.能够熟练使用办公软件；\n4.学习能力和适应能力强，能够快速迭代，拥抱变化；\n5.积极主动、富有激情、具有良好的沟通能力；","description":"部门介绍\n商业增值部是服务于美团核心本地商业客户的增值服务平台，覆盖餐饮、即时零售、医药、休闲娱乐、丽人医美、生活服务、酒旅度假等业务领域。我们致力于构建健康的本地商业生态，通过为平台客户和消费者提供符合其需求的多元、便捷、高效的商业产品和服务，帮助生态伙伴提高效率、优化经营、实现持续健康发展，推动本地商业数字化营销的发展，促进商业生态繁荣。作为本地商业的头部平台，我们为产品、运营、商务、技术、商业分析等领域人才提供广阔的发展空间。诚邀你加入美团商业增值团队，共筑本地商业的健康繁荣生态！\n\n岗位职责\n1.负责美团医药大客户广告产品的线上入驻和维护，促成客户与平台的持续合作；\n2.通过主动电话外呼进行招商，与合作商户负责人沟通建立客情；\n3.洞察经营需求，并提供专业的线上代运营方案：店铺设置，产品优化，活动报名，节日营销等；\n\n岗位基本要求\n1.大专及以上学历；\n2.有电销、销售经验优先；\n3.能够熟练使用办公软件；\n4.学习能力和适应能力强，能够快速迭代，拥抱变化；\n5.积极主动、富有激情、具有良好的沟通能力；\n\n岗位亮点\n1.入职即开展带薪培训，减缓融入和适应的压力；\n2.入职即购买六险一金，并享受带薪年假；\n3.完善的晋升发展机制；\n4.每年一次免费健康体检；\n5.丰富的员工活动和每月团建活动；\n6.双休+法定节假日；","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4683942537","sourceKey":"meituan_social","company":"美团","title":"产品经理-创新业务产品","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4683942537&jobShareType=1","duty":"1. 负责独立业务的产品规划、需求分析及产品设计，推动产品从0到1落地、以及1到100的规模化。\n2. 深入理解行业趋势和BC端客户需求，制定产品方案持续优化各端产品能力，助力业务发展。\n3. 统筹跨团队协作，协同内外部技术、设计、业务等团队，高效推进项目进展，确保功能高质量上线。\n4. 能通过数据复盘驱动效率与体验持续提升，对规模化后的骑行用户体验、商家履约质量、业务收益负责。","requirements":"1. 大学本科及以上学历，3年以上产品相关工作经验，具备独立负责业务线产品经验优先。\n2. 业务意识好，有较好的视野广度，善于解构业务问题，能够独立负责某个业务方向整体产品规划及落地。\n3. 具备良好的逻辑思维、跨团队协作能力，有owner 意识，适应创新业务的节奏和开放性。\n4. 具备AI产品实践经验，能判断不同AI方案适用场景和可行性，结合业务痛点设计AI解决方案，提升业务效率。\n5. 有共享出行、分时租赁行业经验，或有 LBS / IoT 产品经验者优先。","description":"部门介绍\n美团骑行事业部在全国各个城市开展美团单车、电单车业务，提供绿色、便捷的共享出行服务，是美团出行板块重要的组成部分。我们力求为城市可持续发展提供低碳智能的解决方案，通过技术创新和硬件升级，不断优化全流程骑行体验，为低碳出行提供更好的服务。其中，美团单车旨在为城市居民提供通勤接驳服务，满足用户短途接驳出行需求；美团电单车则满足用户中短途多场景低碳出行需求。\n我们有开放的工作氛围，也有充满韧劲和创造力，心系低碳出行的伙伴。加入我们，一起为用户创造更好的出行体验。\n\n岗位职责\n1. 负责独立业务的产品规划、需求分析及产品设计，推动产品从0到1落地、以及1到100的规模化。\n2. 深入理解行业趋势和BC端客户需求，制定产品方案持续优化各端产品能力，助力业务发展。\n3. 统筹跨团队协作，协同内外部技术、设计、业务等团队，高效推进项目进展，确保功能高质量上线。\n4. 能通过数据复盘驱动效率与体验持续提升，对规模化后的骑行用户体验、商家履约质量、业务收益负责。\n\n岗位基本要求\n1. 大学本科及以上学历，3年以上产品相关工作经验，具备独立负责业务线产品经验优先。\n2. 业务意识好，有较好的视野广度，善于解构业务问题，能够独立负责某个业务方向整体产品规划及落地。\n3. 具备良好的逻辑思维、跨团队协作能力，有owner 意识，适应创新业务的节奏和开放性。\n4. 具备AI产品实践经验，能判断不同AI方案适用场景和可行性，结合业务痛点设计AI解决方案，提升业务效率。\n5. 有共享出行、分时租赁行业经验，或有 LBS / IoT 产品经验者优先。\n\n具备以下条件优先\n1. 有共享出行、两轮车/汽车租赁、分时租赁行业经验。\n2. 有 LBS 或 IoT / 智能硬件产品经验。\n3. 有线上线下结合（OMO）业务经验。\n\n岗位亮点\n1. 方向重点：参与重点创新业务，业务已跑通，能完整经历从1到100的高速增长期。\n2. 成长更快：团队氛围扁平，持续完善的学习分享机制，鼓励创新思维与快速试错，成长更快。\n3. 充分自主：作为产品方向owner，你有充分权利，定义产品形态与演进路线，独立推动全流程落地。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4682655868","sourceKey":"meituan_social","company":"美团","title":"电单车渠道经理-山东","city":"济南市/青岛市/淄博市/潍坊市/济宁市/泰安市/临沂市/德州市/聊城市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4682655868&jobShareType=1","duty":"岗位职责：\n1、对所辖城市群的电单车渠道合作商管理工作负责，承担经营过程和结果指标的任务达成；\n2、充分了解用户、市场等行业信息，制定有针对性的城市打法，并能够指导渠道运营落地，拿到结果；\n3、保持对政府的良好合作关系，进行必要的陪访，配合政策要求及时响应；\n4、与渠道合作商负责人建立良好客情，帮其分析车辆点位、调度规律，制定合理运营计划，以及给出收益管理和人员管理建议，不断推动合作伙伴投入资源达成运营任务并更加盈利；对商的选、育、励、汰负责；\n5、落地执行公司对商政策的上传下达，以及商的赋能工作。","requirements":"岗位要求：\n1、具备渠道开发、渠道管理经验，有共享出行、物流管理、快消行业经验者优先；\n2、学习能力强，对渠道管理模式有比较深刻的认知，能够激发合作商积极性，对管理合作商有一定方法论沉淀；\n3、商务沟通能力强，逻辑能力强，有良好的文字功底；\n4、热爱工作，接受挑战，有团队协作精神和较强的服务意识；价值观正，诚实，责任心强；\n5、大学本科以上学历，可接受出差；","description":"部门介绍\n美团骑行事业部在全国各个城市开展美团单车、电单车业务，提供绿色、便捷的共享出行服务，是美团出行板块重要的组成部分。我们力求为城市可持续发展提供低碳智能的解决方案，通过技术创新和硬件升级，不断优化全流程骑行体验，为低碳出行提供更好的服务。其中，美团单车旨在为城市居民提供通勤接驳服务，满足用户短途接驳出行需求；美团电单车则满足用户中短途多场景低碳出行需求。\n我们有开放的工作氛围，也有充满韧劲和创造力，心系低碳出行的伙伴。加入我们，一起为用户创造更好的出行体验。\n\n岗位职责\n岗位职责：\n1、对所辖城市群的电单车渠道合作商管理工作负责，承担经营过程和结果指标的任务达成；\n2、充分了解用户、市场等行业信息，制定有针对性的城市打法，并能够指导渠道运营落地，拿到结果；\n3、保持对政府的良好合作关系，进行必要的陪访，配合政策要求及时响应；\n4、与渠道合作商负责人建立良好客情，帮其分析车辆点位、调度规律，制定合理运营计划，以及给出收益管理和人员管理建议，不断推动合作伙伴投入资源达成运营任务并更加盈利；对商的选、育、励、汰负责；\n5、落地执行公司对商政策的上传下达，以及商的赋能工作。\n\n岗位基本要求\n岗位要求：\n1、具备渠道开发、渠道管理经验，有共享出行、物流管理、快消行业经验者优先；\n2、学习能力强，对渠道管理模式有比较深刻的认知，能够激发合作商积极性，对管理合作商有一定方法论沉淀；\n3、商务沟通能力强，逻辑能力强，有良好的文字功底；\n4、热爱工作，接受挑战，有团队协作精神和较强的服务意识；价值观正，诚实，责任心强；\n5、大学本科以上学历，可接受出差；\n\n岗位亮点\n1.综合用户运营-车辆重资产运营-治理者g端运营多方面，培养各方面综合能力\n2.进步空间大，有机会接触高线资源；","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4566579169","sourceKey":"meituan_social","company":"美团","title":"供应链解决方案专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4566579169&jobShareType=1","duty":"1.供应链管理解决方案设计：基于供应链业务目标和策略方向，将业务问题转化为体系化的流程/系统解决方案，为供应链系统能力和流程效率负责。\n2.基于不同品类运营策略，制定差异化的供应链解决方案并推进落地，提升商品有货率&动销率、降低成本。\n3.产研协同：与牵牛花产研团队紧密协作，输出高质量解决方案/MRD、把控需求优先级，推动需求高质量交付。\n4.流程建设：与品类运营、仓配、物流等上下游协同，梳理供应链业务规则和协作流程，识别效率瓶颈并推进端到端优化。\n5.专项推进落地：参与供应链重点专项（如智能订货系统升级、调拨策略系统化、大促保障流程等），负责组织和推进各品类、商流、物流协同的创新优化项目。","requirements":"1.本科及以上学历，2年以上工作经验，有供应链/电商/即时零售领域经验优先、善用AI提效和解决问题优先。\n2.具有产品化思维和长链条思维，能识别业务关键问题和问题间的因果关系，转化成结构化的解决方案（流程、系统）\n3.熟悉供应链核心流程（订货、调拨、库存管理、仓配履约等），有相关系统建设或产品运营经验优先。\n4.有系统需求设计或产品运营经验，能独立产出完整的需求文档（MRD/PRD/流程图）。\n5.逻辑清晰，沟通高效，书面表达能力强。有优秀的跨部门协调和推动能力，能在产研、运营、仓配等多方之间有效推进共识和落地。","description":"部门介绍\n美团闪购是美团旗下的即时零售平台，依托即时配送能力，连接本地零售供给，满足消费者30分钟万物到家的即时需求。美团闪购涵盖超市便利、食材、水果、鲜花绿植、休闲零食、酒水饮料、数码家电、美妆个护、母婴玩具、日用百货、服饰鞋帽、宠物等诸多品类，业务覆盖全国近3,000个县市区旗，每日百万级在岗骑手，以高效的配送、丰富的品类和广泛的覆盖，为美团数亿用户带来便捷的生活体验，积极助力实体零售线上化转型，提升本地商业活力。\n\n岗位职责\n1.供应链管理解决方案设计：基于供应链业务目标和策略方向，将业务问题转化为体系化的流程/系统解决方案，为供应链系统能力和流程效率负责。\n2.基于不同品类运营策略，制定差异化的供应链解决方案并推进落地，提升商品有货率&动销率、降低成本。\n3.产研协同：与牵牛花产研团队紧密协作，输出高质量解决方案/MRD、把控需求优先级，推动需求高质量交付。\n4.流程建设：与品类运营、仓配、物流等上下游协同，梳理供应链业务规则和协作流程，识别效率瓶颈并推进端到端优化。\n5.专项推进落地：参与供应链重点专项（如智能订货系统升级、调拨策略系统化、大促保障流程等），负责组织和推进各品类、商流、物流协同的创新优化项目。\n\n岗位基本要求\n1.本科及以上学历，2年以上工作经验，有供应链/电商/即时零售领域经验优先、善用AI提效和解决问题优先。\n2.具有产品化思维和长链条思维，能识别业务关键问题和问题间的因果关系，转化成结构化的解决方案（流程、系统）\n3.熟悉供应链核心流程（订货、调拨、库存管理、仓配履约等），有相关系统建设或产品运营经验优先。\n4.有系统需求设计或产品运营经验，能独立产出完整的需求文档（MRD/PRD/流程图）。\n5.逻辑清晰，沟通高效，书面表达能力强。有优秀的跨部门协调和推动能力，能在产研、运营、仓配等多方之间有效推进共识和落地。\n\n具备以下条件优先\n零售SaaS系统产品经验、供应链管理经验\n\n岗位亮点\n1.参与品牌官旗闪电仓的运营管理，能够接触到即时零售行业中的前沿技术和发展趋势，能快速积累全链路视角。\n2.有机会与商家及供给运营团队紧密合作，拓展人际关系和行业资源。\n3.发展和上升空间广阔，是一个能够快速成长和提升的职业发展平台。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4434228343","sourceKey":"meituan_social","company":"美团","title":"商业分析师（智能精算）","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4434228343&jobShareType=1","duty":"1、负责美团场景内健康险、百万医疗险、意外险等保险方案设计及保费测算工作，独立完成保障方案设计、差异化定价/调价及核保规则梳理。\n2、基于精算知识和大模型能力，搭建保险成本收益监控及预警体系，包括常态化监控、业务综成率监控体系等，维稳业务质量健康度，并对行业输出真实、客观的分析报告。\n3、参与制定业务风险应对策略，定期组织重点指标专项分析，并提供完善的业务解决方案。\n4、利用AI工具挖掘隐藏的风险关联与市场规律，为定价策略优化、风险防控、产品创新提供更具前瞻性的支撑。","requirements":"1、本科及以上学历，至少3年以上保险精算定价方向经验，有互联网平台工作经验者优先。\n2、对技术革新保持敏感，有通过使用并不断优化AI工具，赋能工作成果的实际落地经验。\n3、熟悉常规的精算定价模型方法，具备较强的业务理解和数据挖掘能力，深入理解与思考行业逻辑并找到突破点。\n4、有较强的自驱力和沟通表达能力，具有主人翁意识和团队协作精神，能够协调各方资源推动完成工作。","description":"部门介绍\n美团金融服务平台成立于2016年，以“场景+金融”模式，携手合作伙伴构建开放生态，为美团平台用户和商户提供底层账户、支付通道、信贷、保险和理财等金融解决方案。我们致力于以科技为核心，助力金融机构打通金融普惠“最后一公里”。我们期待与大家共同完成每一件平凡而卓越的事情，一起为用户提供优质的产品体验，守护用户的资金安全，让生活变得更美好。\n\n岗位职责\n1、负责美团场景内健康险、百万医疗险、意外险等保险方案设计及保费测算工作，独立完成保障方案设计、差异化定价/调价及核保规则梳理。\n2、基于精算知识和大模型能力，搭建保险成本收益监控及预警体系，包括常态化监控、业务综成率监控体系等，维稳业务质量健康度，并对行业输出真实、客观的分析报告。\n3、参与制定业务风险应对策略，定期组织重点指标专项分析，并提供完善的业务解决方案。\n4、利用AI工具挖掘隐藏的风险关联与市场规律，为定价策略优化、风险防控、产品创新提供更具前瞻性的支撑。\n\n岗位基本要求\n1、本科及以上学历，至少3年以上保险精算定价方向经验，有互联网平台工作经验者优先。\n2、对技术革新保持敏感，有通过使用并不断优化AI工具，赋能工作成果的实际落地经验。\n3、熟悉常规的精算定价模型方法，具备较强的业务理解和数据挖掘能力，深入理解与思考行业逻辑并找到突破点。\n4、有较强的自驱力和沟通表达能力，具有主人翁意识和团队协作精神，能够协调各方资源推动完成工作。\n\n岗位亮点\n1、可以接触最前沿的AI大模型能力和海量算力，借助AI算法实现风险因子的智能识别、赔付数据的快速分析及定价模型的动态优化。\n2、美团拥有丰富的互联网业务场景，能深入了解互联网各类场景需求并参与业务全链路的核心策略，能极大丰富个人业务视野，积累行业经验。\n3、团队成员具有优秀的教育背景及职业履历，关系融洽，学习氛围浓郁。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:2348894455","sourceKey":"meituan_social","company":"美团","title":"大模型应用算法工程师（智能客服）","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=2348894455&jobShareType=1","duty":"1. 支持智能客服项目，负责对话理解和生成类任务的算法建模工作，包括但不限于知识和指令遵循、深度推理、反思和评估等能力的优化和落地。\n2. 参与大模型研发及业务落地，支持客户之声、风控、舆情、客服机器人等多场景的效果优化；\n3. 通过系统建设，降低业务分析数据的门槛，影响和提升业务对数据价值挖掘的能力和效率；\n4. 参与技术新的探索，挖掘大模型落地场景。","requirements":"1. 计算机、人工智能、数学等相关专业硕士及以上学历，两年以上大模型、智能体或相关领域研发经验。\n2. 具备扎实的大模型训练和调优背景，熟悉主流的大语言模型（Deepseek、Qwen、Llama等）及其他开源模型。精通至少一种深度学习框架（如TensorFlow, PyTorch）。\n3. 在以下至少一个技术领域有深入研究和丰富的实践经验：\n- 智能客服大模型\n- 复杂指令遵循、逻辑和数学推理、结合知识约束的推理、DPO、强化学习等\n- 大模型问答系统，RAG、Function Call等\n- Agent模型、多智能体系统\n4. 熟练掌握机器学习和深度学习的理论知识，并具备目标导向和数据思维。\n5. 具备优秀的算法设计和实现能力，能够独立完成算法的需求分析、方案设计、代码实现和效果评估，有发表顶会论文（ACL/AAAI/SIGIR等）者优先。\n6. 具备良好的团队合作精神和沟通能力，能够与产品、工程团队高效协作。\n7. 宽广的技术视野，强烈的钻研精神，主观能动性和学习能力，适应快速变化的技术趋势。","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n1. 支持智能客服项目，负责对话理解和生成类任务的算法建模工作，包括但不限于知识和指令遵循、深度推理、反思和评估等能力的优化和落地。\n2. 参与大模型研发及业务落地，支持客户之声、风控、舆情、客服机器人等多场景的效果优化；\n3. 通过系统建设，降低业务分析数据的门槛，影响和提升业务对数据价值挖掘的能力和效率；\n4. 参与技术新的探索，挖掘大模型落地场景。\n\n岗位基本要求\n1. 计算机、人工智能、数学等相关专业硕士及以上学历，两年以上大模型、智能体或相关领域研发经验。\n2. 具备扎实的大模型训练和调优背景，熟悉主流的大语言模型（Deepseek、Qwen、Llama等）及其他开源模型。精通至少一种深度学习框架（如TensorFlow, PyTorch）。\n3. 在以下至少一个技术领域有深入研究和丰富的实践经验：\n- 智能客服大模型\n- 复杂指令遵循、逻辑和数学推理、结合知识约束的推理、DPO、强化学习等\n- 大模型问答系统，RAG、Function Call等\n- Agent模型、多智能体系统\n4. 熟练掌握机器学习和深度学习的理论知识，并具备目标导向和数据思维。\n5. 具备优秀的算法设计和实现能力，能够独立完成算法的需求分析、方案设计、代码实现和效果评估，有发表顶会论文（ACL/AAAI/SIGIR等）者优先。\n6. 具备良好的团队合作精神和沟通能力，能够与产品、工程团队高效协作。\n7. 宽广的技术视野，强烈的钻研精神，主观能动性和学习能力，适应快速变化的技术趋势。\n\n具备以下条件优先\n1. 有大模型落地经验优先\n2. 有顶会论文发表经历优先\n3. 有大型项目落地经验优先\n\n岗位亮点\n1. 丰富的落地应用场景\n2. 充足的GPU计算资源\n3. 学习型组织的团队氛围\n4. 业界一流的同行专家","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4494746854","sourceKey":"meituan_social","company":"美团","title":"Keeta-资深商业分析师/经营分析专家","city":"北京市/利雅得","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4494746854&jobShareType=1","duty":"1、负责沙特外卖业务的整体经营分析，搭建并完善核心指标体系，并定期产出经营分析报告追踪业务健康度，及时识别经营问题或经营风险，为管理层提供决策弹药。\n2、持续追踪沙特市场的宏观大盘与竞争态势，深入开展行业调研与用户洞察，能够跳出现有框架，在当前业务模式及跨业态中敏锐捕捉新的增长机会点。\n3、深入挖掘用户、商户数据，洞察沙特市场的本地化特征与供需匹配规律，输出高质量的专题分析报告，直接驱动业务策略的迭代。\n4、积极探索利用AI工具进行日常各项分析工作。","requirements":"1、本科及以上学历，3-5年以上互联网/咨询/投行等相关领域的商业分析、经营分析或战略分析经验（有外卖、电商、O2O或出海经验者加分！）。\n2、具备一定的市场盘点、竞争分析与用户调研经验，能够独立操盘定性/定量研究项目，对宏观趋势和行业动态有较强的敏锐度。\n3、精通SQL，熟练使用Python/R等分析工具，能从海量且复杂的非标数据中抽丝剥茧。\n4、具备较强的结构化思维和商业敏锐度，不沉溺于取数，而是能把数据翻译成“人话”和“业务动作”。\n5、有要性和韧性，拥抱变化，能在模糊地带中找到确定性。","description":"部门介绍\nKeeta是全球领先外卖平台美团旗下的独立品牌，肩负着“帮大家吃得更好，生活更好”的使命。依托美团深耕中国市场15年的技术与运营积淀，我们正引领全球餐饮与商品即时配送服务的创新与发展。\n\n自2023年成立以来，Keeta始终扎根社区并创造价值。我们为用户提供可靠的外卖体验，以智慧技术助餐厅提升经营效率，在为骑手拓宽收入来源的同时，也充分提供安全保障措施。基于这份多方共赢、共同成长的理念，我们的业务已从中国香港稳步拓展至中东及巴西，并持续向世界迈进。\n\n岗位职责\n1、负责沙特外卖业务的整体经营分析，搭建并完善核心指标体系，并定期产出经营分析报告追踪业务健康度，及时识别经营问题或经营风险，为管理层提供决策弹药。\n2、持续追踪沙特市场的宏观大盘与竞争态势，深入开展行业调研与用户洞察，能够跳出现有框架，在当前业务模式及跨业态中敏锐捕捉新的增长机会点。\n3、深入挖掘用户、商户数据，洞察沙特市场的本地化特征与供需匹配规律，输出高质量的专题分析报告，直接驱动业务策略的迭代。\n4、积极探索利用AI工具进行日常各项分析工作。\n\n岗位基本要求\n1、本科及以上学历，3-5年以上互联网/咨询/投行等相关领域的商业分析、经营分析或战略分析经验（有外卖、电商、O2O或出海经验者加分！）。\n2、具备一定的市场盘点、竞争分析与用户调研经验，能够独立操盘定性/定量研究项目，对宏观趋势和行业动态有较强的敏锐度。\n3、精通SQL，熟练使用Python/R等分析工具，能从海量且复杂的非标数据中抽丝剥茧。\n4、具备较强的结构化思维和商业敏锐度，不沉溺于取数，而是能把数据翻译成“人话”和“业务动作”。\n5、有要性和韧性，拥抱变化，能在模糊地带中找到确定性。\n\n岗位亮点\n1、行业顶配的商分体系：深度掌握美团沉淀多年的本地生活商业分析方法论，能够直接对接国家负责人及各业务团队负责人，并得到直接的指导，让你的专业能力再上一个台阶。\n2、降维打击的成就感：将成熟的中国互联网打法与中东本土特色结合，你的每一个洞察都可能直接改变一个国家的消费习惯。\n3、广阔的职业天花板：出海是未来十年的大趋势，成为具备全球化视野的商分专家，做最稀缺的人才。\n4、开放包容的团队氛围：和一群聪明、务实、有拼劲的伙伴并肩作战，偶尔还能一起吐槽不同时区的工作趣事。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4630850039","sourceKey":"meituan_social","company":"美团","title":"Keeta-商业分析师（经营分析）-卡塔尔","city":"多哈/北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4630850039&jobShareType=1","duty":"1. 建立并完善外卖业务经营主要模块的指标体系，建立日/周/月维度的经营监控和分析框架，识别业务关键要素的指标变化，并诊断经营异动，通过下钻分析和专题拆解充分定位问题，为业务改进提供判断。\n\n2. 内外部分析结合，包括不限于宏观和行业分析、用户需求持续洞察、用户和商户调研、用户质量评估、本地市场及业务规律的长期探索、盈亏分析、业务策略效果评估，可以在业务关键决策点开展专题研究，为业务策略制定和迭代提供关键输入。\n\n3. 持续性竞争研究，包括不限于竞争信息收集、竞争和大盘数据分析、竞争策略研究、竞争形势推演等，为业务目标制定和关键策略调整提供判断。\n\n4.针对重点经营策略项目，主导制定项目目标、规划策略并通过项目管理统筹策略落地，达成业务目标。\n\n5.积极探索利用AI工具进行日常各项分析工作。","requirements":"1.大学本科以上学历，4年以上互联网或商业分析经验，有过较复杂的专题或策略分析经验。\n\n2.有良好的业务sense和沟通能力，能够与业务团队对话，并协同业务推动策略落地。\n\n3.扎实掌握统计学知识，熟练使用办公软件和SQL等数据分析工具，具备优秀的数据分析和文档撰写基本功，能运用好AI是加分项。\n\n4.英语可以作为基本的工作语言，有本地生活或海外经验优先。\n\n5.有要性、承压能力强，并能做好时间管理，心态开放，可接受外派到其他国家工作。","description":"部门介绍\nKeeta是全球领先外卖平台美团旗下的独立品牌，肩负着“帮大家吃得更好，生活更好”的使命。依托美团深耕中国市场15年的技术与运营积淀，我们正引领全球餐饮与商品即时配送服务的创新与发展。\n\n自2023年成立以来，Keeta始终扎根社区并创造价值。我们为用户提供可靠的外卖体验，以智慧技术助餐厅提升经营效率，在为骑手拓宽收入来源的同时，也充分提供安全保障措施。基于这份多方共赢、共同成长的理念，我们的业务已从中国香港稳步拓展至中东及巴西，并持续向世界迈进。\n\n岗位职责\n1. 建立并完善外卖业务经营主要模块的指标体系，建立日/周/月维度的经营监控和分析框架，识别业务关键要素的指标变化，并诊断经营异动，通过下钻分析和专题拆解充分定位问题，为业务改进提供判断。\n\n2. 内外部分析结合，包括不限于宏观和行业分析、用户需求持续洞察、用户和商户调研、用户质量评估、本地市场及业务规律的长期探索、盈亏分析、业务策略效果评估，可以在业务关键决策点开展专题研究，为业务策略制定和迭代提供关键输入。\n\n3. 持续性竞争研究，包括不限于竞争信息收集、竞争和大盘数据分析、竞争策略研究、竞争形势推演等，为业务目标制定和关键策略调整提供判断。\n\n4.针对重点经营策略项目，主导制定项目目标、规划策略并通过项目管理统筹策略落地，达成业务目标。\n\n5.积极探索利用AI工具进行日常各项分析工作。\n\n岗位基本要求\n1.大学本科以上学历，4年以上互联网或商业分析经验，有过较复杂的专题或策略分析经验。\n\n2.有良好的业务sense和沟通能力，能够与业务团队对话，并协同业务推动策略落地。\n\n3.扎实掌握统计学知识，熟练使用办公软件和SQL等数据分析工具，具备优秀的数据分析和文档撰写基本功，能运用好AI是加分项。\n\n4.英语可以作为基本的工作语言，有本地生活或海外经验优先。\n\n5.有要性、承压能力强，并能做好时间管理，心态开放，可接受外派到其他国家工作。\n\n岗位亮点\n1. Keeta是美团出海的战略级业务，能全程参与这个业务从0-1的高速成长，开阔文化视野，拓新市场挑战。\n\n2. 团队追求专业主义有助于个人职场提升，团队氛围积极友好互助。\n\n3.负责复杂专题与策略，能够直接对接国家负责人及各业务团队负责人，并得到直接的指导，帮助个人快速成长。\n\n3.团队配备完善的AI工具体系，鼓励成员将AI能力融入日常工作流，持续探索人机协作最佳实践。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4692295063","sourceKey":"meituan_social","company":"美团","title":"Keeta-Senior Product Manager for Internationalization Platform（国际化平台产品专家）","city":"北京市/深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4692295063&jobShareType=1","duty":"1、负责i18n平台整体产品规划与建设，推动平台从翻译管理向国际化体验管理平台发展。\n2、建设国际化语言资产管理工具，与语言专家共同为业务术语、语言规范和治理的体验和效率负责。\n3、探索AI在国际化平台中的应用，推动国际化平台的自动化和智能化建设。","requirements":"1、具备优秀的平台产品设计能力：5年以上产品经理经验，有复杂平台型产品设计经验，能够从业务需求中抽象通用能力，设计可复用的平台产品，具备较强的数据建模、流程设计和系统抽象能力。\n2、具备AI产品设计能力：对大模型、AI Agent或AI工作流有实践经验或深入理解。能够将AI能力融入业务流程，而不是简单调用模型API。\n3、具备跨团队协作能力：能够协调研发、算法、设计、语言专家、海外业务团队共同推进复杂项目。\n4、具备较强的英文沟通能力，能够顺畅阅读和理解海外技术资料。\n5、加分项：有国际化/i18n相关或CMS内容管理平台的产品经验；有互联网产品全球化经验，有多个国家/地区业务支持经验。","description":"部门介绍\nKeeta是全球领先外卖平台美团旗下的独立品牌，肩负着“帮大家吃得更好，生活更好”的使命。依托美团深耕中国市场15年的技术与运营积淀，我们正引领全球餐饮与商品即时配送服务的创新与发展。\n\n自2023年成立以来，Keeta始终扎根社区并创造价值。我们为用户提供可靠的外卖体验，以智慧技术助餐厅提升经营效率，在为骑手拓宽收入来源的同时，也充分提供安全保障措施。基于这份多方共赢、共同成长的理念，我们的业务已从中国香港稳步拓展至中东及巴西，并持续向世界迈进。\n\n岗位职责\n1、负责i18n平台整体产品规划与建设，推动平台从翻译管理向国际化体验管理平台发展。\n2、建设国际化语言资产管理工具，与语言专家共同为业务术语、语言规范和治理的体验和效率负责。\n3、探索AI在国际化平台中的应用，推动国际化平台的自动化和智能化建设。\n\n岗位基本要求\n1、具备优秀的平台产品设计能力：5年以上产品经理经验，有复杂平台型产品设计经验，能够从业务需求中抽象通用能力，设计可复用的平台产品，具备较强的数据建模、流程设计和系统抽象能力。\n2、具备AI产品设计能力：对大模型、AI Agent或AI工作流有实践经验或深入理解。能够将AI能力融入业务流程，而不是简单调用模型API。\n3、具备跨团队协作能力：能够协调研发、算法、设计、语言专家、海外业务团队共同推进复杂项目。\n4、具备较强的英文沟通能力，能够顺畅阅读和理解海外技术资料。\n5、加分项：有国际化/i18n相关或CMS内容管理平台的产品经验；有互联网产品全球化经验，有多个国家/地区业务支持经验。\n\n具备以下条件优先\n有以下任一经验均是加分项：\n1、有企业平台/中台成功项目经验，尤其是有CMS相关项目经验的\n2、有国际化平台产品经验\n3、有AI效率工具成功项目经验\n\n岗位亮点\n我们目标是建设面向全球即时零售业务的国际化平台基建，通过对语言、时区、币种等国际化体验资产管理、AI翻译、自动化流程和智能化能力，帮助业务以更低成本、更高质量进入全球市场。你将参与从1到10的建设国际化基础设施，并推动i18n从翻译能力向全球国际化综合体验平台演进。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4701887814","sourceKey":"meituan_social","company":"美团","title":"生鲜采控专家","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4701887814&jobShareType=1","duty":"1、计划管理：负责PC成品需求计划、sku加工计划、原料库存计划拉通与输出\n2、订货履约：负责PC原料采购及商家履约运营管理\n3、指标运营：负责成品及原料的缺货、周转、不健康库存运营管理\n4、进向成本：负责包装物、载具、进向仓网链路等成本优化项目挖掘推进\n5、工具建设：负责PC进销存退产品建设与迭代，以及日常运营管理工具看板搭建等","requirements":"1、本科学历及以上，具备3年及以上采购、供应链或库存管理经验，在计划和库存管理方面有较好的方法论沉淀；\n2、具备较好的数据分析能力，熟练使用数据分析软件，会使用SQL、Python优先；\n3、熟悉电商行业采控岗位整体工作流程，对供应链计划、需求预测、订单执行及履约入库、库存管理等方面，具备0-1标准化体系搭建；\n4、有过供应链产品、流程优化、S&OP等大型项目推动经验的优先。","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1、计划管理：负责PC成品需求计划、sku加工计划、原料库存计划拉通与输出\n2、订货履约：负责PC原料采购及商家履约运营管理\n3、指标运营：负责成品及原料的缺货、周转、不健康库存运营管理\n4、进向成本：负责包装物、载具、进向仓网链路等成本优化项目挖掘推进\n5、工具建设：负责PC进销存退产品建设与迭代，以及日常运营管理工具看板搭建等\n\n岗位基本要求\n1、本科学历及以上，具备3年及以上采购、供应链或库存管理经验，在计划和库存管理方面有较好的方法论沉淀；\n2、具备较好的数据分析能力，熟练使用数据分析软件，会使用SQL、Python优先；\n3、熟悉电商行业采控岗位整体工作流程，对供应链计划、需求预测、订单执行及履约入库、库存管理等方面，具备0-1标准化体系搭建；\n4、有过供应链产品、流程优化、S&OP等大型项目推动经验的优先。\n\n具备以下条件优先\n有生鲜蔬果采控经验、PC加工业务经验者、AI应用实践经历优先\n\n岗位亮点\n行业头部平台，且仍处于增长期，发展机会较多；岗位专业化分工，有助于个人行业经验沉淀","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4699132006","sourceKey":"meituan_social","company":"美团","title":"keeta商家端产品","city":"北京市/深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4699132006&jobShareType=1","duty":"1. 对来自各渠道、各市场的需求加以甄别和专业判断，输出高质量的产品方案，运用AI工具辅助需求分析和方案优化\n2. 深入理解商家使用商家端产品的全流程，准确识别商家痛点，洞察商家行为的动因\n3. 研究全球范围内行业头部玩家的商家端产品能力，了解商家服务领域的最佳实践，结合Keeta业务特点明确产品升级方向\n4. 持续迭代产品功能，满足商家在经营、交易承接场景的诉求，帮商家做好外卖生意。","requirements":"1. 本科及以上学历，3年以上互联网产品经验，有商家端或B端产品经验者优先\n2. 对商家需求理解准确，能转化为清晰的产品策略\n3. 具备用户产品和工具产品的设计能力，学习意愿强\n4. 英文流利，能独立和各国商家、BD、运营沟通，高效收集信息、讨论方案\n5. 有较好的产品审美，有AI工具实际使用经验（如使用AI进行需求分析、方案设计、市场研究等），能输出高质量的产品方案\n6. 具备定量分析能力，能设计A/B实验并解读实验结果与业务逻辑\n7. 责任心强，能在多线并行工作中保持条理，结果导向","description":"部门介绍\nKeeta是全球领先外卖平台美团旗下的独立品牌，肩负着“帮大家吃得更好，生活更好”的使命。依托美团深耕中国市场15年的技术与运营积淀，我们正引领全球餐饮与商品即时配送服务的创新与发展。\n\n自2023年成立以来，Keeta始终扎根社区并创造价值。我们为用户提供可靠的外卖体验，以智慧技术助餐厅提升经营效率，在为骑手拓宽收入来源的同时，也充分提供安全保障措施。基于这份多方共赢、共同成长的理念，我们的业务已从中国香港稳步拓展至中东及巴西，并持续向世界迈进。\n\n岗位职责\n1. 对来自各渠道、各市场的需求加以甄别和专业判断，输出高质量的产品方案，运用AI工具辅助需求分析和方案优化\n2. 深入理解商家使用商家端产品的全流程，准确识别商家痛点，洞察商家行为的动因\n3. 研究全球范围内行业头部玩家的商家端产品能力，了解商家服务领域的最佳实践，结合Keeta业务特点明确产品升级方向\n4. 持续迭代产品功能，满足商家在经营、交易承接场景的诉求，帮商家做好外卖生意。\n\n岗位基本要求\n1. 本科及以上学历，3年以上互联网产品经验，有商家端或B端产品经验者优先\n2. 对商家需求理解准确，能转化为清晰的产品策略\n3. 具备用户产品和工具产品的设计能力，学习意愿强\n4. 英文流利，能独立和各国商家、BD、运营沟通，高效收集信息、讨论方案\n5. 有较好的产品审美，有AI工具实际使用经验（如使用AI进行需求分析、方案设计、市场研究等），能输出高质量的产品方案\n6. 具备定量分析能力，能设计A/B实验并解读实验结果与业务逻辑\n7. 责任心强，能在多线并行工作中保持条理，结果导向\n\n具备以下条件优先\n* 如果你已经在日常产品的工作中灵活运用AI提升工作能效，是个加分项\n* 如果你对交易类平台产品有过成功战绩，是个加分项\n\n岗位亮点\n1. 国际化业务，直接服务全球商家，拓展职业视野\n2. 业务处于高速发展期，个人成长与业务增长强绑定\n3. AI-Native工作氛围，团队积极推动AI在商家端产品中的深度应用\n4. 从0到1参与AI+商家服务的智能化建设，在商家赋能前沿领域积累先发经验\n5. 团队氛围求真务实，决策扁平高效","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4698961217","sourceKey":"meituan_social","company":"美团","title":"keeta商家端产品运营","city":"北京市/深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4698961217&jobShareType=1","duty":"你将作为商家端的平台产品运营，负责以下日常工作：\n* 你需要深入商家群体，展开各种形式的调研，挖掘在商家端经营与交易能力上的真需求\n* 你需要搭建产品运营的工作机制，借助流程和机制，去持续牵引和改善商家端产品体验\n* 你负责商家对经营和交易产品的使用推广，以及关注商家的反馈\n* 你要运用 AI 工具（如 ChatGPT/Copilot/内部 AI 平台）提升日常工作效率，推动团队 AI 工具的落地应用\n* 你要探索并落地 AI 在 [你的业务场景] 中的应用，持续优化工作流程\n* 你要通过 AI 辅助完成 [具体任务，如数据分析/文档撰写/代码审查]，将精力聚焦于判断和决策","requirements":"我们希望你具备如下的能力：\n* 有用户调研的经验，能找对角度，用对方法，问对问题，敏锐且洞察用户的需求\n* 在流程和机制的设计和拿结果上，有过不错的战绩\n* 沟通和表达能力好，英语熟练，并且能同理商家\n* 如果你在交易类平台上有工作经验，熟悉B端客群和业务，是个加分项\n* 你熟练使用至少一种 AI 工具辅助日常工作（如 ChatGPT/Claude/Kimi/豆包等）\n* 你对 AI 技术有好奇心，能主动探索新工具并推动团队应用","description":"部门介绍\nKeeta是全球领先外卖平台美团旗下的独立品牌，肩负着“帮大家吃得更好，生活更好”的使命。依托美团深耕中国市场15年的技术与运营积淀，我们正引领全球餐饮与商品即时配送服务的创新与发展。\n\n自2023年成立以来，Keeta始终扎根社区并创造价值。我们为用户提供可靠的外卖体验，以智慧技术助餐厅提升经营效率，在为骑手拓宽收入来源的同时，也充分提供安全保障措施。基于这份多方共赢、共同成长的理念，我们的业务已从中国香港稳步拓展至中东及巴西，并持续向世界迈进。\n\n岗位职责\n你将作为商家端的平台产品运营，负责以下日常工作：\n* 你需要深入商家群体，展开各种形式的调研，挖掘在商家端经营与交易能力上的真需求\n* 你需要搭建产品运营的工作机制，借助流程和机制，去持续牵引和改善商家端产品体验\n* 你负责商家对经营和交易产品的使用推广，以及关注商家的反馈\n* 你要运用 AI 工具（如 ChatGPT/Copilot/内部 AI 平台）提升日常工作效率，推动团队 AI 工具的落地应用\n* 你要探索并落地 AI 在 [你的业务场景] 中的应用，持续优化工作流程\n* 你要通过 AI 辅助完成 [具体任务，如数据分析/文档撰写/代码审查]，将精力聚焦于判断和决策\n\n岗位基本要求\n我们希望你具备如下的能力：\n* 有用户调研的经验，能找对角度，用对方法，问对问题，敏锐且洞察用户的需求\n* 在流程和机制的设计和拿结果上，有过不错的战绩\n* 沟通和表达能力好，英语熟练，并且能同理商家\n* 如果你在交易类平台上有工作经验，熟悉B端客群和业务，是个加分项\n* 你熟练使用至少一种 AI 工具辅助日常工作（如 ChatGPT/Claude/Kimi/豆包等）\n* 你对 AI 技术有好奇心，能主动探索新工具并推动团队应用\n\n具备以下条件优先\n* 如果你在日常工作中已经掌握了AI且带来了提效，是个不错的加分项\n\n岗位亮点\n业务处在上升和发展的快车道\n团队氛围求真务实，且专注\n公司内部 AI 工具完善（CatPaw/美境/NoCode 等），鼓励用 AI 替代重复劳动\nAI-Native 的工作氛围，注重人机协作效率","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4692090128","sourceKey":"meituan_social","company":"美团","title":"搜推算法专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4692090128&jobShareType=1","duty":"1.负责美团酒旅业务搜索算法策略迭代，优化用户搜推体验，提升业务转化、收入等核心指标。\n2.应用先进技术手段，优化查询理解、召回、粗排、精排、重排等算法模块，显著提升用户体验和转化效率。\n3.深入思考产品及业务价值，参与制定及落实团队在技术、业务等多维度发展方向。\n4.深度使用大模型能力，重构现有搜索架构及产品，建设下一代搜索系统。 \n4.与其他团队密切合作，为用户提供卓越的酒店旅行产品。","requirements":"1.拥有计算机、电子、通信、数学、统计学或相关专业的本科及以上学历，具备5年及以上工作经验。\n2.熟悉掌握机器学习和深度学习算法，在搜索、广告或推荐等领域有实际工作经验，并在多目标优化、序列建模、深度召回等一个或多个方向有深入研究。\n3.熟练使用Hive/Spark/Hadoop等大数据工具，熟悉TensorFlow/PyTorch等框架，具备大规模深度学习项目实际经验，具备良好的代码开发能力。\n4.具备一定的业务敏感度，创新精神和理论与实践相结合的能力，具有主动思考和学习的动力，乐于与业务共同成长。\n5.具备出色的问题分析和解决能力，具有团队合作意识，对具有挑战性的问题充满激情。\n6.积极拥抱大模型等新技术。","description":"部门介绍\n美团核心本地商业下业务研发平台，基于公司“零售+科技”的战略导向，通过从底层架构到应用系统、从软件到硬件、从传统算法到GenAI的全方位技术研究，以及开发、运维、安全等全流程能力建设，致力于推动美团核心本地商业下需求侧与供给侧的数字化和智能化升级，助力业务实现高质量增长，优化用户使用体验，提升商户经营水平，促进行业生态伙伴关系的持续健康发展。团队秉持务实、自驱、开放以及追求卓越的工程师文化，一方面通过系统和技术体系的持续迭代升级，帮助业务高质量增长；另一方面，密切关注前沿技术趋势变化，积极创新技术能力，为业务未来发展创造新的可能性。期待优秀的你加入我们，在夯实专业、深耕平台的基础上与业务携手同行，一起用技术 “帮大家吃得更好，生活更好”。\n\n岗位职责\n1.负责美团酒旅业务搜索算法策略迭代，优化用户搜推体验，提升业务转化、收入等核心指标。\n2.应用先进技术手段，优化查询理解、召回、粗排、精排、重排等算法模块，显著提升用户体验和转化效率。\n3.深入思考产品及业务价值，参与制定及落实团队在技术、业务等多维度发展方向。\n4.深度使用大模型能力，重构现有搜索架构及产品，建设下一代搜索系统。 \n4.与其他团队密切合作，为用户提供卓越的酒店旅行产品。\n\n岗位基本要求\n1.拥有计算机、电子、通信、数学、统计学或相关专业的本科及以上学历，具备5年及以上工作经验。\n2.熟悉掌握机器学习和深度学习算法，在搜索、广告或推荐等领域有实际工作经验，并在多目标优化、序列建模、深度召回等一个或多个方向有深入研究。\n3.熟练使用Hive/Spark/Hadoop等大数据工具，熟悉TensorFlow/PyTorch等框架，具备大规模深度学习项目实际经验，具备良好的代码开发能力。\n4.具备一定的业务敏感度，创新精神和理论与实践相结合的能力，具有主动思考和学习的动力，乐于与业务共同成长。\n5.具备出色的问题分析和解决能力，具有团队合作意识，对具有挑战性的问题充满激情。\n6.积极拥抱大模型等新技术。\n\n具备以下条件优先\n对AI、LLM等新技术有热情有信仰，并积极付诸实践的。\n\n岗位亮点\n1. 参与核心业务的核心入口优化。\n2. 在工作中落地大模型、生成式等新技术，建设下一代搜索系统。\n3. 与优秀的人一起共事。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4684250035","sourceKey":"meituan_social","company":"美团","title":"特团推荐算法工程师","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4684250035&jobShareType=1","duty":"1.参与Agent Loop 链路设计与迭代、 与知识沉淀、评测集建设、线上化系统链路建设。\n3.负责特团推荐算法策略的开发和优化，提高搜推荐策略的效果和效率。\n4.进行算法模型的设计、开发和调优，提高推荐算法的准确性和精度。\n5.分析用户数据和行为，挖掘用户需求和行为特征，为产品和业务提供算法支持。\n6.跟踪行业动态和竞争对手的算法策略，及时调整和优化算法模型，保持竞争力。\n7.与产品和技术团队合作，推动算法策略的落地和实施，确保算法的有效性和可行性。","requirements":"1.硕士研究生及以上学历，计算机相关专业，熟悉机器学习和数据挖掘算法。\n2.至少1年以上相关工作经验，有搜索推荐和营销算法开发经验者优先考虑。\n3.了解Prompt、上下文工程、Agent 编排、RAG 与知识库构建、评测体系设计、把大模型能力落地经验。\n4.熟练掌握Python、Java等编程语言，具备良好的编程能力和代码规范。\n5.熟悉常见的机器学习算法和数据挖掘技术，有实际项目经验者优先。\n6.具备较强的数据分析和问题解决能力，能够独立完成算法模型的设计和开发。\n7.具备良好的沟通能力和团队合作意识，能够与产品和技术团队紧密配合，推动项目进展。","description":"部门介绍\n美团核心本地商业下业务研发平台，基于公司“零售+科技”的战略导向，通过从底层架构到应用系统、从软件到硬件、从传统算法到GenAI的全方位技术研究，以及开发、运维、安全等全流程能力建设，致力于推动美团核心本地商业下需求侧与供给侧的数字化和智能化升级，助力业务实现高质量增长，优化用户使用体验，提升商户经营水平，促进行业生态伙伴关系的持续健康发展。团队秉持务实、自驱、开放以及追求卓越的工程师文化，一方面通过系统和技术体系的持续迭代升级，帮助业务高质量增长；另一方面，密切关注前沿技术趋势变化，积极创新技术能力，为业务未来发展创造新的可能性。期待优秀的你加入我们，在夯实专业、深耕平台的基础上与业务携手同行，一起用技术 “帮大家吃得更好，生活更好”。\n\n岗位职责\n1.参与Agent Loop 链路设计与迭代、 与知识沉淀、评测集建设、线上化系统链路建设。\n3.负责特团推荐算法策略的开发和优化，提高搜推荐策略的效果和效率。\n4.进行算法模型的设计、开发和调优，提高推荐算法的准确性和精度。\n5.分析用户数据和行为，挖掘用户需求和行为特征，为产品和业务提供算法支持。\n6.跟踪行业动态和竞争对手的算法策略，及时调整和优化算法模型，保持竞争力。\n7.与产品和技术团队合作，推动算法策略的落地和实施，确保算法的有效性和可行性。\n\n岗位基本要求\n1.硕士研究生及以上学历，计算机相关专业，熟悉机器学习和数据挖掘算法。\n2.至少1年以上相关工作经验，有搜索推荐和营销算法开发经验者优先考虑。\n3.了解Prompt、上下文工程、Agent 编排、RAG 与知识库构建、评测体系设计、把大模型能力落地经验。\n4.熟练掌握Python、Java等编程语言，具备良好的编程能力和代码规范。\n5.熟悉常见的机器学习算法和数据挖掘技术，有实际项目经验者优先。\n6.具备较强的数据分析和问题解决能力，能够独立完成算法模型的设计和开发。\n7.具备良好的沟通能力和团队合作意识，能够与产品和技术团队紧密配合，推动项目进展。\n\n具备以下条件优先\n1、参与海量推荐系统的开发、训练、应用等，有AI、LLM、Agent相关实操经验者优先；\n2、有序列化推荐深度模型、因果推断模型、运筹优化及强化学习创新及落地经验者优先；\n3、对推荐系统及营销增长技术现状和发展趋势有深刻的理解和认知，并对相关技术有极高的热情。\n4、计算机相关专业获得硕士学位， 博士优先， 发表过相关研究AI顶会论文者优先； \n5、具备有良好的代码开发能力，有开源项目开发经验优先。\n\n岗位亮点\n1.本地核心商业重点特团业务，机会多挑战大，团队成员nice。\n2.团队业务紧跟公司的业务目标，每一次策略迭代都能给公司的业务目标带来具体的价值，实现自我价值和个人成就感。\n3.团队成员大多来自于名校和名企，在这里有机会学习、尝试和落地业界先进技术。\n4.业务处于快速发展阶段，能够为个人提供了快速成长的空间，拥有自主迭代的决策权，更好地实现创新。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:2989369067","sourceKey":"meituan_social","company":"美团","title":"团购业务策略分析师","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=2989369067&jobShareType=1","duty":"1.具有数据处理和分析能力，建设业务洞察看数基础，借助AI工具进行数据处理和分析；\n2.周期性复盘业务的现状，精准定位业务存在的问题，为业务负责人作出关键业务决策提供输入和支持；\n3.根据业务存在的问题输出业务策略，并推动策略落地；\n4.监控竞争形势的演进，清晰解读和判断背后的动因和影响，及时跟进策略。","requirements":"1. 统计学、数学、经济学、计算机等相关专业，3年以上数据分析/业务分析/业务策略等工作经验， 互联网行业优先考虑；\n2. 逻辑清晰，思维框架完整，具备优秀的数据分析能力，善于从数据中发现业务痛点并提出应对策略；\n3. 具备较好的口头和书面沟通能力，较多项目管理和跨部门合作经历，能够高效完成项目的规划和执行；\n4. 有进取心，积极主动且乐于团队合作，具备将AI能力融入日常工作流程的意识和AI实践经验；\n5. 有较好的SQL能力，具备较强的AI使用技能，能够利用AI改善工作流程，提高流程决策效率。","description":"部门介绍\n美团核心本地商业-下沉市场发展部于2015年成立，通过招募优质的合作商伙伴并对其业务经营能力、组织能力等赋能，以期为下沉城市提供一站式的本地生活服务。\n下沉市场发展部的业务场景涵盖了外卖餐饮、团购、拼好饭、闪购、医药等多元化的生活服务领域，同时搭建了一套稳定、高效的即时配送网络，为更多本地用户提供品质化、多样化、便捷高效的生活服务体验，为当地商户提供数字化发展机遇、提升数字化水平，为社会创造更多的就地就业机会。\n截至2024年6月，下沉市场发展部已开拓全国4000+县区市，帮助百万商户实现本地生活服务数字化，日订单量突破千万，为数十万名骑手提供就业岗位，让本地生活服务逐渐成长为地方新基建，实现美团“帮助大家吃得更好，生活更好”的使命！\n\n岗位职责\n1.具有数据处理和分析能力，建设业务洞察看数基础，借助AI工具进行数据处理和分析；\n2.周期性复盘业务的现状，精准定位业务存在的问题，为业务负责人作出关键业务决策提供输入和支持；\n3.根据业务存在的问题输出业务策略，并推动策略落地；\n4.监控竞争形势的演进，清晰解读和判断背后的动因和影响，及时跟进策略。\n\n岗位基本要求\n1. 统计学、数学、经济学、计算机等相关专业，3年以上数据分析/业务分析/业务策略等工作经验， 互联网行业优先考虑；\n2. 逻辑清晰，思维框架完整，具备优秀的数据分析能力，善于从数据中发现业务痛点并提出应对策略；\n3. 具备较好的口头和书面沟通能力，较多项目管理和跨部门合作经历，能够高效完成项目的规划和执行；\n4. 有进取心，积极主动且乐于团队合作，具备将AI能力融入日常工作流程的意识和AI实践经验；\n5. 有较好的SQL能力，具备较强的AI使用技能，能够利用AI改善工作流程，提高流程决策效率。\n\n具备以下条件优先\n对 AI 技术在商业场景中的应用有浓厚兴趣，关注 Anthropic、OpenAI、Deepseek 等前沿大模型动态；\n对餐饮、零售等消费行业有深度好奇心，喜欢竞争分析，有自主学习和知识沉淀习惯（如整理 wiki、输出复盘文档等）。\n\n岗位亮点\n1.前沿的万亿业务；\n2.行业头部企业；\n3.核心业务策略岗位；\n4.业务链条长且复杂，能够学到丰富的商业知识；\n5.新业务方向具有创新性、挑战性，成长空间广阔","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3510361830","sourceKey":"meituan_social","company":"美团","title":"Keeta技术-Java高级工程师","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3510361830&jobShareType=1","duty":"1.参与境外配送管控、运营活动、商奖惩系统研发工作，核心模块的需求分析和设计，核心代码的开发等；\n2.参与管控平台、考核平台、活动系统的设计工作，探索调研和优化业务架构模型，平台能力建设；\n3.负责解决项目中关键问题和技术难题，线上疑难问题排查和解决，并给出合理的指导和改进建议；\n4.借助AI Coding工具提升管控与运营系统研发效率，探索AI技术在规则引擎智能化、运营活动自动配置等场景中的工程落地。","requirements":"1.本科及以上学历，3年以上互联网系统研发经验；\n2.具备优秀的业务分析能力和解决问题能力，能够将复杂的业务问题转变为清晰的系统需求；\n3.对技术有热情，有强烈的求知欲、好奇心和进取心，关注IT行业动态，能够快速学习和运用新技术；\n4.做事有责任感和主动性，面对复杂业务问题，可以从技术和业务多角度推进，最终达成目标；\n5.熟练使用AI辅助编码工具（如GitHub Copilot/Cursor），能将AI工具融入日常开发流程；有运营活动、管控等配送核心系统设计开发经验或国际化从业经验者优先。","description":"部门介绍\n美团核心本地商业下业务研发平台，基于公司“零售+科技”的战略导向，通过从底层架构到应用系统、从软件到硬件、从传统算法到GenAI的全方位技术研究，以及开发、运维、安全等全流程能力建设，致力于推动美团核心本地商业下需求侧与供给侧的数字化和智能化升级，助力业务实现高质量增长，优化用户使用体验，提升商户经营水平，促进行业生态伙伴关系的持续健康发展。团队秉持务实、自驱、开放以及追求卓越的工程师文化，一方面通过系统和技术体系的持续迭代升级，帮助业务高质量增长；另一方面，密切关注前沿技术趋势变化，积极创新技术能力，为业务未来发展创造新的可能性。期待优秀的你加入我们，在夯实专业、深耕平台的基础上与业务携手同行，一起用技术 “帮大家吃得更好，生活更好”。\n\n岗位职责\n1.参与境外配送管控、运营活动、商奖惩系统研发工作，核心模块的需求分析和设计，核心代码的开发等；\n2.参与管控平台、考核平台、活动系统的设计工作，探索调研和优化业务架构模型，平台能力建设；\n3.负责解决项目中关键问题和技术难题，线上疑难问题排查和解决，并给出合理的指导和改进建议；\n4.借助AI Coding工具提升管控与运营系统研发效率，探索AI技术在规则引擎智能化、运营活动自动配置等场景中的工程落地。\n\n岗位基本要求\n1.本科及以上学历，3年以上互联网系统研发经验；\n2.具备优秀的业务分析能力和解决问题能力，能够将复杂的业务问题转变为清晰的系统需求；\n3.对技术有热情，有强烈的求知欲、好奇心和进取心，关注IT行业动态，能够快速学习和运用新技术；\n4.做事有责任感和主动性，面对复杂业务问题，可以从技术和业务多角度推进，最终达成目标；\n5.熟练使用AI辅助编码工具（如GitHub Copilot/Cursor），能将AI工具融入日常开发流程；有运营活动、管控等配送核心系统设计开发经验或国际化从业经验者优先。\n\n具备以下条件优先\n1.有运营活动、人员组织、管控等配送核心系统设计开发经验；\n2.主导过大型复杂分布式互联网业务系统的设计，有高并发场景下的架构设计和稳定性保障经验；\n3.有过国际化相关从业经验；\n4.英语流利，可作为工作语言者。\n\n岗位亮点\n1.能全面参与国际化配送业务从0到1的建设过程，可了解国际上履约业务全貌及系统架构演进；\n2.如果你对世界充满好奇心，在这里，你会接触到不同的国家、语言和文化，开拓国际视野，探索异域市场；\n3.如果你富有冒险精神，在这里，一个个陌生的国家等待你的开发，一个个全新的关卡等待你的挑战；\n4.如果你渴望快速成长，在这里，你可以经历新业务从0到1的过程，不断解锁新技能，持续获得成就感；\n5.团队积极拥抱AI工作方式，日常研发已全面接入AI Coding工具，并持续探索AI驱动的配送管控系统智能化实践；\n6.我们的目标是星辰大海，期待有想法、敢于冒险、渴望快速成长的你加入！让我们一同见证美团国际化的征程！","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4688120602","sourceKey":"meituan_social","company":"美团","title":"快乐猴仓储主管（常温）","city":"杭州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4688120602&jobShareType=1","duty":"1.仓储作业计划执行与班组进度跟踪督导\n• 承接仓储经理下达的作业计划，将任务合理分解至班组各岗位，跟踪收货、上架、拣选、出库、退货等各环节执行进度• 及时发现作业滞后或异常，快速协调资源调配，确保班组日常运营目标按时达成\n2. 货物收发验货与库存数据核对管理\n• 组织并监督货物收货验货、上架入库、出库发货等全流程规范执行，严格把控货物数量、质量与单据一致性\n• 定期核对库存数据，确保账实相符，及时处理收发差异，保障库存数据准确可靠\n3. 班组人员培训与作业规范执行督查\n• 组织开展新员工岗前培训及在职人员技能培训，确保班组成员熟知并掌握作业标准与操作规范；\n• 日常巡查作业执行情况，及时纠正违规操作，持续提升班组成员规范执行能力与作业质量。\n4. 库存损耗统计分析与异常品类原因排查\n• 定期统计班组库存损耗数据，识别损耗异常品类与高频问题节点\n• 深入排查损耗原因，区分操作失误、仓储条件、流程漏洞等因素，提出针对性改善建议并跟踪整改落地，持续降低库存损耗率\n5. 流程标准化执行落地与仓储安全问题整改\n• 负责公司仓储标准化在本班组的宣贯培训、执行落地与日常监督，确保各岗位人员严格按标准规范操作• 负责班组区域日常安全巡查，检查消防通道、货架稳固、设备使用、食品卫生等安全隐患• 对班组人员开展安全规范宣导，确保安全生产无事故","requirements":"1、专业技能：熟悉仓储管理系统及常见物流设备操作，了解仓储标准化作业流程；\n2、管理能力：具备良好的团队管理能力与沟通协调能力，能有效推动现场作业执行与团队协作；\n3、综合素质：工作责任心强，具备创新意识与问题解决能力，能适应高强度作业环境。","description":"部门介绍\n快乐猴是美团自营社区超市，依托自有供应链和门店管理体系，聚焦家庭用户的三餐所需，为消费者提供高质价比的食杂商品。快乐猴以数字化能力与科学品控为基础，不断满足消费者对“省”和“便利”的需求。\n\n岗位职责\n1.仓储作业计划执行与班组进度跟踪督导\n• 承接仓储经理下达的作业计划，将任务合理分解至班组各岗位，跟踪收货、上架、拣选、出库、退货等各环节执行进度• 及时发现作业滞后或异常，快速协调资源调配，确保班组日常运营目标按时达成\n2. 货物收发验货与库存数据核对管理\n• 组织并监督货物收货验货、上架入库、出库发货等全流程规范执行，严格把控货物数量、质量与单据一致性\n• 定期核对库存数据，确保账实相符，及时处理收发差异，保障库存数据准确可靠\n3. 班组人员培训与作业规范执行督查\n• 组织开展新员工岗前培训及在职人员技能培训，确保班组成员熟知并掌握作业标准与操作规范；\n• 日常巡查作业执行情况，及时纠正违规操作，持续提升班组成员规范执行能力与作业质量。\n4. 库存损耗统计分析与异常品类原因排查\n• 定期统计班组库存损耗数据，识别损耗异常品类与高频问题节点\n• 深入排查损耗原因，区分操作失误、仓储条件、流程漏洞等因素，提出针对性改善建议并跟踪整改落地，持续降低库存损耗率\n5. 流程标准化执行落地与仓储安全问题整改\n• 负责公司仓储标准化在本班组的宣贯培训、执行落地与日常监督，确保各岗位人员严格按标准规范操作• 负责班组区域日常安全巡查，检查消防通道、货架稳固、设备使用、食品卫生等安全隐患• 对班组人员开展安全规范宣导，确保安全生产无事故\n\n岗位基本要求\n1、专业技能：熟悉仓储管理系统及常见物流设备操作，了解仓储标准化作业流程；\n2、管理能力：具备良好的团队管理能力与沟通协调能力，能有效推动现场作业执行与团队协作；\n3、综合素质：工作责任心强，具备创新意识与问题解决能力，能适应高强度作业环境。\n\n具备以下条件优先\n1、学历专业：大学专科及以上学历，物流管理、供应链管理或相关专业优先；\n2、工作经验：具备3年以上仓储物流现场管理经验，具备团队管理经验者，硬折扣、商超物流经验者优先（超盒算、奥乐齐、永辉、华润万家、大润发等）\n\n岗位亮点\n1、快速发展型业务，表现优异可快速晋升\n2、支持跨部门横向流动，拓展职业维度与综合能力","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4691213764","sourceKey":"meituan_social","company":"美团","title":"里白酒店设计项目经理","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4691213764&jobShareType=1","duty":"1. 设计品牌标准执行：深度贯彻品牌设计标准及视觉识别系统，确保各连锁门店设计风格的一致性、独特性与市场适应性，有效提升品牌辨识度与竞争力。\n\n2. 项目全流程管理把控：全面负责酒店设计项目从前期设计、方案深化到施工图纸标准管控、制定项目设计管理计划，严格把控项目设计进度、及时高效解决项目推进过程中的各类设计问题与技术难题，确保项目按预定计划高品质交付运营。\n\n3. 跨部门沟通协作协调：作为设计部门核心代表，积极主动与工程、采购、市场、运营等多部门建立紧密高效的沟通协作机制，确保设计方案与工程施工、物资采购、市场营销及酒店运营等环节的无缝对接与高效配合，共同推动项目顺利实施与成功运营。\n\n4. 标准店复盘：及时跟进标准店项目反馈，不断优化酒店设计流程与方法，持续反馈酒店落地过程问题，为标准完善和用户体验设计提升做好信息输入。","requirements":"一、专业背景与技能\n\n1. 本科及以上学历，室内设计、建筑学、环境艺术设计等相关专业毕业。具备扎实的设计理论基础，熟悉酒店设计规范、流程与标准。\n2. 熟练掌握 设计软件，精通酒店空间规划与布局，善于优化空间利用，营造独特舒适的酒店环境氛围，深入理解酒店功能分区与流线设计，确保各区域高效运作且相互协调。\n\n二、工作经验\n\n1. 具有5年以上酒店设计工作经验，其中至少3年连锁酒店设计管理经验。主导或深度参与过多个连锁酒店项目设计，熟悉不同品牌定位与风格特色，能根据市场需求与品牌标准制定适宜的设计策略并全程把控实施。\n2. 过往设计作品在酒店行业具有较高知名度与影响力，荣获相关设计奖项者优先考虑。\n\n三、项目管理能力\n\n具备出色的项目统筹规划与组织协调能力，能制定详细合理的项目计划，精准把控项目进度、质量、成本与风险。有效组织设计团队及跨部门合作，与工程、采购、运营等部门紧密沟通协作，确保设计方案顺利落地实施。\n\n四、沟通与团队管理能力\n\n1. 具备出色的沟通表达与团队管理能力，能够清晰准确地传达设计理念与要求，积极倾听各方意见与建议，妥善处理团队内部及跨部门沟通协作中的问题与矛盾，营造良好的合作氛围与工作环境。","description":"部门介绍\n美团酒店旅行业务涵盖酒店、民宿、机票、火车票、旅游度假、景点门票等各类住行游品类，通过与产业上下游的深度合作，为用户提供美好的旅游旅行体验。我们积极打造AI友好型组织，使用AI等新技术提升旅游服务的供需匹配效率，更好满足用户个性化、多样化的出游需求。我们持续深耕产业链，用数字化服务助力实体商家高质量经营，探索自有品牌等供给新模式，打造健康的商家生态，保障用户服务体验。为满足用户日益增长的跨境旅行需求，我们将聚焦亚太区域，打造高品质的住宿、交通、游玩等服务矩阵。\n这里有多元的业务布局、持续的成长空间，无论是向往的远方还是眼前的工作，一路都是风景相伴。加入我们，共同为用户创造旅游旅行中的高光时刻！\n\n岗位职责\n1. 设计品牌标准执行：深度贯彻品牌设计标准及视觉识别系统，确保各连锁门店设计风格的一致性、独特性与市场适应性，有效提升品牌辨识度与竞争力。\n\n2. 项目全流程管理把控：全面负责酒店设计项目从前期设计、方案深化到施工图纸标准管控、制定项目设计管理计划，严格把控项目设计进度、及时高效解决项目推进过程中的各类设计问题与技术难题，确保项目按预定计划高品质交付运营。\n\n3. 跨部门沟通协作协调：作为设计部门核心代表，积极主动与工程、采购、市场、运营等多部门建立紧密高效的沟通协作机制，确保设计方案与工程施工、物资采购、市场营销及酒店运营等环节的无缝对接与高效配合，共同推动项目顺利实施与成功运营。\n\n4. 标准店复盘：及时跟进标准店项目反馈，不断优化酒店设计流程与方法，持续反馈酒店落地过程问题，为标准完善和用户体验设计提升做好信息输入。\n\n岗位基本要求\n一、专业背景与技能\n\n1. 本科及以上学历，室内设计、建筑学、环境艺术设计等相关专业毕业。具备扎实的设计理论基础，熟悉酒店设计规范、流程与标准。\n2. 熟练掌握 设计软件，精通酒店空间规划与布局，善于优化空间利用，营造独特舒适的酒店环境氛围，深入理解酒店功能分区与流线设计，确保各区域高效运作且相互协调。\n\n二、工作经验\n\n1. 具有5年以上酒店设计工作经验，其中至少3年连锁酒店设计管理经验。主导或深度参与过多个连锁酒店项目设计，熟悉不同品牌定位与风格特色，能根据市场需求与品牌标准制定适宜的设计策略并全程把控实施。\n2. 过往设计作品在酒店行业具有较高知名度与影响力，荣获相关设计奖项者优先考虑。\n\n三、项目管理能力\n\n具备出色的项目统筹规划与组织协调能力，能制定详细合理的项目计划，精准把控项目进度、质量、成本与风险。有效组织设计团队及跨部门合作，与工程、采购、运营等部门紧密沟通协作，确保设计方案顺利落地实施。\n\n四、沟通与团队管理能力\n\n1. 具备出色的沟通表达与团队管理能力，能够清晰准确地传达设计理念与要求，积极倾听各方意见与建议，妥善处理团队内部及跨部门沟通协作中的问题与矛盾，营造良好的合作氛围与工作环境。\n\n具备以下条件优先\n大型连锁酒店工作经验优先\n\n岗位亮点\n1、大平台：站在平台视角研发酒店产品，深度参与各个环节，相比传统酒店研发可以从全新角度思考酒店产品，拥有更大的发挥空间。（全程参与酒店产品前期市场调研、产品定位、酒店产品研发、供应链落地、以及线上展示方案落地）\n2、规模大：针对平台商家，提供不同程度改造产品，产品覆盖面大，商家规模大，更多机会接触优秀设计资源，供应链资源，能力提升快。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:2951750236","sourceKey":"meituan_social","company":"美团","title":"华东区域-地面商户拓展-外卖拼好饭BD","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=2951750236&jobShareType=1","duty":"1.承接执行公司销售策略及政策，负责区域内新商户的拓展、老商户的维护，与商户建立长期稳定的商务合作关系，达成业绩目标；\n2.通过深入了解商户需求，结合区域消费市场特征制定个性化营销和运营方案并促成更多元的合作，帮助商家提升经营水平；\n3.通过与公司各部门有效配合，快速解决商户经营中遇到的问题及突发事件，及时处理来自商家和消费者的投诉、反馈、建议等，提高消费者和商家的满意度；\n4.通过及时收集区域内商户和消费者意见，了解当地市场信息等对业务提出发展参考意见，持续帮助树立企业优良品牌。","requirements":"1.本科及以上学历，欢迎希望从事销售类工作的优秀应届毕业生；\n2.具备1年以上的零售、快消、餐饮或其他生活服务行业的销售或运营类岗位经验优先；\n3.具备良好的服务意识，团队合作精神和敬业精神，个性开朗，反应敏捷，有责任心；","description":"部门介绍\n美团外卖秉承“帮大家吃得更好，生活更好”的使命，始终聚焦于消费者用餐需求。我们通过科技连接消费者和商家，依托庞大的骑手团队，以“线上+线下”的业务模式，为消费者提供品质化、精细化、多样化的餐饮外卖服务。\n外卖事业部是为用户与商家提供全链路交易服务的业务组织，围绕餐饮外卖搭建了包含外卖业务与创新孵化业务在内的多个部门。\n我们的目标是帮助商家开源增收、提高经营效率，促进餐饮行业数字化，以及为更多用户提供更便捷更有品质的外卖服务。加入我们，一起为上亿用户提供更好的用餐体验，帮助大家吃得更好，生活更好！\n\n岗位职责\n1.承接执行公司销售策略及政策，负责区域内新商户的拓展、老商户的维护，与商户建立长期稳定的商务合作关系，达成业绩目标；\n2.通过深入了解商户需求，结合区域消费市场特征制定个性化营销和运营方案并促成更多元的合作，帮助商家提升经营水平；\n3.通过与公司各部门有效配合，快速解决商户经营中遇到的问题及突发事件，及时处理来自商家和消费者的投诉、反馈、建议等，提高消费者和商家的满意度；\n4.通过及时收集区域内商户和消费者意见，了解当地市场信息等对业务提出发展参考意见，持续帮助树立企业优良品牌。\n\n岗位基本要求\n1.本科及以上学历，欢迎希望从事销售类工作的优秀应届毕业生；\n2.具备1年以上的零售、快消、餐饮或其他生活服务行业的销售或运营类岗位经验优先；\n3.具备良好的服务意识，团队合作精神和敬业精神，个性开朗，反应敏捷，有责任心；\n\n具备以下条件优先\n1.具备成熟的商家谈判绩效，过往工作有优秀的业绩结果；\n2.熟悉互联网产品应用，对商家运营有较深入的理解；\n3.有一定的数据分析基础。\n\n岗位亮点\n1.公司提供完善的员工福利：社保公积金+补充商业保险、法定节假日之外的额外带薪假期；\n2.公司拥有完善的培训体系和转岗、晋升机制，可以帮助员工不断提升多项专业技能和管理技能；\n3.团队士气高，有激情，工作氛围好。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3054923165","sourceKey":"meituan_social","company":"美团","title":"Keeta技术-数据开发专家（深圳）","city":"深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3054923165&jobShareType=1","duty":"1. 数据仓库开发与优化，设计并实施高性能、可扩展的海外业务数仓架构，支持多时区、多语言数据集成。与数据分析师、业务团队协作，理解需求并输出数据服务（如指标体系、数据API）。 \n2. 实时数据开发，构建实时数据工程开发服务平台，沉淀平台能力，支持Flink SQL无法满足的实时指标计算场景。基于Flink/Kafka/Spark Streaming等构建实时数据处理管道，支持业务实时监控与告警。解决实时场景下的数据延迟、乱序、Exactly-Once等挑战。\n3. 数据服务工具构建，构建数据服务平台，提供通用的接口服务与指标管理，连接数仓数据与数据应用（线上系统、分析系统、用户等）。推动数据治理（质量监控、血缘追踪、权限管理）在海外业务的落地。 \n4. 项目管理与跨团队协作，主导数据项目全生命周期管理（需求评审、排期、风险控制、交付），协调跨时区团队。制定数据开发规范，主导技术方案评审，培养初级工程师。","requirements":"1. 5年以上数据开发经验，具备以下背景之一：① 数据平台/中台开发经验（如数据湖、计算引擎优化），有向数仓方向转型的意愿；② 后端开发经验（Java/Scala/Python）+ 3年以上数仓开发经验。\n2.熟悉云数仓（Snowflake/BigQuery/Redshift）或湖仓一体架构（Delta Lake/Iceberg）； 熟练掌握数仓分层理论、建模方法，熟悉Hive/Spark/Impala等大数据组件。。\n3.了解 GDPR 等数据安全合规要求；英语能力优秀，可处理英文文档并进行跨时区沟通；\n4.了解 AI 辅助数据开发工具（如 AI SQL 生成、智能数据质量检测），能将 AI 能力融入数仓建模与数据服务研发流程。\n5. 精通实时数据处理技术栈（如Flink/Kafka/Redis），有高吞吐、低延迟场景实战经验。\n6. 有项目管理经验（至少主导过2个中型以上数据项目），熟悉敏捷开发流程。","description":"部门介绍\n美团核心本地商业下业务研发平台，基于公司“零售+科技”的战略导向，通过从底层架构到应用系统、从软件到硬件、从传统算法到GenAI的全方位技术研究，以及开发、运维、安全等全流程能力建设，致力于推动美团核心本地商业下需求侧与供给侧的数字化和智能化升级，助力业务实现高质量增长，优化用户使用体验，提升商户经营水平，促进行业生态伙伴关系的持续健康发展。团队秉持务实、自驱、开放以及追求卓越的工程师文化，一方面通过系统和技术体系的持续迭代升级，帮助业务高质量增长；另一方面，密切关注前沿技术趋势变化，积极创新技术能力，为业务未来发展创造新的可能性。期待优秀的你加入我们，在夯实专业、深耕平台的基础上与业务携手同行，一起用技术 “帮大家吃得更好，生活更好”。\n\n岗位职责\n1. 数据仓库开发与优化，设计并实施高性能、可扩展的海外业务数仓架构，支持多时区、多语言数据集成。与数据分析师、业务团队协作，理解需求并输出数据服务（如指标体系、数据API）。 \n2. 实时数据开发，构建实时数据工程开发服务平台，沉淀平台能力，支持Flink SQL无法满足的实时指标计算场景。基于Flink/Kafka/Spark Streaming等构建实时数据处理管道，支持业务实时监控与告警。解决实时场景下的数据延迟、乱序、Exactly-Once等挑战。\n3. 数据服务工具构建，构建数据服务平台，提供通用的接口服务与指标管理，连接数仓数据与数据应用（线上系统、分析系统、用户等）。推动数据治理（质量监控、血缘追踪、权限管理）在海外业务的落地。 \n4. 项目管理与跨团队协作，主导数据项目全生命周期管理（需求评审、排期、风险控制、交付），协调跨时区团队。制定数据开发规范，主导技术方案评审，培养初级工程师。\n\n岗位基本要求\n1. 5年以上数据开发经验，具备以下背景之一：① 数据平台/中台开发经验（如数据湖、计算引擎优化），有向数仓方向转型的意愿；② 后端开发经验（Java/Scala/Python）+ 3年以上数仓开发经验。\n2.熟悉云数仓（Snowflake/BigQuery/Redshift）或湖仓一体架构（Delta Lake/Iceberg）； 熟练掌握数仓分层理论、建模方法，熟悉Hive/Spark/Impala等大数据组件。。\n3.了解 GDPR 等数据安全合规要求；英语能力优秀，可处理英文文档并进行跨时区沟通；\n4.了解 AI 辅助数据开发工具（如 AI SQL 生成、智能数据质量检测），能将 AI 能力融入数仓建模与数据服务研发流程。\n5. 精通实时数据处理技术栈（如Flink/Kafka/Redis），有高吞吐、低延迟场景实战经验。\n6. 有项目管理经验（至少主导过2个中型以上数据项目），熟悉敏捷开发流程。\n\n岗位亮点\n1. 主导海外数据中台从0到1建设：负责支撑多国业务的数仓架构设计，解决多时区、多语言、多货币的数据集成挑战，技术复杂度在国内数据领域属于前沿；\n2. 全链路数据影响力：你的数据服务将直接支撑 Keeta 在多个国家的业务决策，从实时监控到战略分析，数据价值清晰可见；\n3. 跨时区协作成长：与海外业务团队深度协作，快速积累国际化数据工程经验，拓展职业发展边界。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4637407377","sourceKey":"meituan_social","company":"美团","title":"美团金融-招聘经理（AI驱动）","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4637407377&jobShareType=1","duty":"关于金服\n美团金融服务板块，以支付为核心，覆盖信贷、保险、风控、资管等多条业务线。公司持续投入的战略业务，资源丰富，空间广阔。\n\n我们期待这样的你\n当AI正在改写招聘的每一个环节，我们希望找到一位既能\"动手用AI\"、又能\"懂业务语境\"的招聘伙伴；\n你会用AI工具和数据分析来做判断，而不是只靠表格和直觉；\n你愿意花时间去了解金服各条线在想什么、缺什么样的人，知道哪些人是\"能把AI能力迁过来的人\"；\n你能和业务Leader、Hrbp站到一起，把招聘动作翻译成团队能的看得见的成果；\n你对新鲜事物保持好奇，也喜欢拉上团队一起试试新工具；\n如果你对\"AI × 金融 × 招聘\"这个交汇点有热情，欢迎一起。\n\n你会做什么\n一、用AI重新设计招聘链路\n1. 在社招、校招、猎头合作等关键环节中，探索用AI工具释放重复劳动（如简历初筛、流程协调、数据整理），让团队把时间花在\"识人\"和\"决策\"上；\n2. 力所能及地试点 Agent / AI tool 在招聘场景的应用（如智能沟通、进度看板、人才分析等），不求大而全，但求跑得通、能落地；\n3. 把实践中沉淀的方法（AI协同招聘的 prompt 库、Agent 搭建经验等）在金服各团队复用，让\"一个人摸索\"变成\"一群人能用的能力\"。\n\n二、把招聘放到业务语境里做\n1. 理解金服各团队的战略重点，识别\"AI实践落地型\"和\"AI学习能力型\"两类画像，让招聘输入和业务节奏同频；\n2. 与金服各层级保持常态沟通，提前感知人才需求变化，减少被动响应；\n3. 联动校招、社招、猎头、内推等渠道，用数据驱动资源优化；\n4. 关注行业人才流动，逐步形成市场的核心人才感知。\n\n三、和招聘团队一起进化\n1. 和团队一起走向\"AI Baseline\"——每位伙伴都能在日常工作中自然地用AI工具提效；\n2. 用透明的数据可视替代\"数人头\"式的汇报，让进展和风险一目了然；\n3. 更轻量的\"AI胜任力评估\"方式，帮助面试官在面试中更自然地考察候选人的AI应用能力。","requirements":"我们希望你具备\n1. 本科及以上学历；5年以上互联网或金融行业招聘经验，有支付/金融/信贷/保险等相关团队服务经验加分；\n2. 熟悉社招、校招、猎头、内推等多种渠道，能判断不同岗位类型的获取路径；\n3. 本人是AI工具的深度使用者，有可分享的实际案例（数据分析、流程提效、候选人沟通等）；\n4. 能快速理解业务战略，并将其转化为招聘策略，而不是被动接收需求；\n6. 良好的跨部门协作力，能在业务Leader、HRBP、招聘团队之间建立信任、高效推进。","description":"部门介绍\n美团HR的使命是“建设有生命力的组织，为客户和社会创造价值。” 我们认为HR的工作不是以自身“专业”为中心，而是要建设有助于员工发挥创造力的环境，支持他们更好地为外部客户和社会创造价值，也实现组织自身的进化和传承。在这个过程中，我们的每位HR同学都是“业务的战略合作伙伴、组织能力的建设者、美团精神的布道者、员工的成长伙伴”。我们要设计面向长期支撑组织有效运转的机制，我们要求真务实地帮业务解决发展中的问题和阵痛，我们要支持每一位员工历经磨炼收获成长。我们要影响和驱动让世界更美好的变化发生。如果这也是你追求的，欢迎加入美团HR，与我们一路同行！\n\n岗位职责\n关于金服\n美团金融服务板块，以支付为核心，覆盖信贷、保险、风控、资管等多条业务线。公司持续投入的战略业务，资源丰富，空间广阔。\n\n我们期待这样的你\n当AI正在改写招聘的每一个环节，我们希望找到一位既能\"动手用AI\"、又能\"懂业务语境\"的招聘伙伴；\n你会用AI工具和数据分析来做判断，而不是只靠表格和直觉；\n你愿意花时间去了解金服各条线在想什么、缺什么样的人，知道哪些人是\"能把AI能力迁过来的人\"；\n你能和业务Leader、Hrbp站到一起，把招聘动作翻译成团队能的看得见的成果；\n你对新鲜事物保持好奇，也喜欢拉上团队一起试试新工具；\n如果你对\"AI × 金融 × 招聘\"这个交汇点有热情，欢迎一起。\n\n你会做什么\n一、用AI重新设计招聘链路\n1. 在社招、校招、猎头合作等关键环节中，探索用AI工具释放重复劳动（如简历初筛、流程协调、数据整理），让团队把时间花在\"识人\"和\"决策\"上；\n2. 力所能及地试点 Agent / AI tool 在招聘场景的应用（如智能沟通、进度看板、人才分析等），不求大而全，但求跑得通、能落地；\n3. 把实践中沉淀的方法（AI协同招聘的 prompt 库、Agent 搭建经验等）在金服各团队复用，让\"一个人摸索\"变成\"一群人能用的能力\"。\n\n二、把招聘放到业务语境里做\n1. 理解金服各团队的战略重点，识别\"AI实践落地型\"和\"AI学习能力型\"两类画像，让招聘输入和业务节奏同频；\n2. 与金服各层级保持常态沟通，提前感知人才需求变化，减少被动响应；\n3. 联动校招、社招、猎头、内推等渠道，用数据驱动资源优化；\n4. 关注行业人才流动，逐步形成市场的核心人才感知。\n\n三、和招聘团队一起进化\n1. 和团队一起走向\"AI Baseline\"——每位伙伴都能在日常工作中自然地用AI工具提效；\n2. 用透明的数据可视替代\"数人头\"式的汇报，让进展和风险一目了然；\n3. 更轻量的\"AI胜任力评估\"方式，帮助面试官在面试中更自然地考察候选人的AI应用能力。\n\n岗位基本要求\n我们希望你具备\n1. 本科及以上学历；5年以上互联网或金融行业招聘经验，有支付/金融/信贷/保险等相关团队服务经验加分；\n2. 熟悉社招、校招、猎头、内推等多种渠道，能判断不同岗位类型的获取路径；\n3. 本人是AI工具的深度使用者，有可分享的实际案例（数据分析、流程提效、候选人沟通等）；\n4. 能快速理解业务战略，并将其转化为招聘策略，而不是被动接收需求；\n6. 良好的跨部门协作力，能在业务Leader、HRBP、招聘团队之间建立信任、高效推进。\n\n具备以下条件优先\n1. 有 Agent / AI 工具实际搭建或落地经验；\n2. 有金融服务行业从业背景；\n3. 有从0到1搭建招聘团队或主导招聘流程迭代的经验；\n4. 有人才mapping、组织研究等项目的实操经验；\n5. 有非HR的业务背景，能把业务语言翻译成招聘动作。\n\n岗位亮点\n1.金服业务处于快速规模AI探索&落地阶段，有较大增长空间，对招聘同学而言是很好的「战场」；\n2.团队高度拥抱 AI，鼓励每位成员探索 AI 工具在 HR 场景中的创新应用，你的探索将直接影响团队效能和自身成长曲线；\n3.人力本身是一个专业天花板非常高、职业发展前景广阔的职业，头部公司都重视人力管理工作。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4699931277","sourceKey":"meituan_social","company":"美团","title":"财务运营方案","city":"圣保罗","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4699931277&jobShareType=1","duty":"1. 业务支持：负责对接Keeta巴西业务需求，结合会计准则，结算规则，合规要求等，识别和判断业务活动对财务的影响，出具相应的财务方案，为业务部门的发展及商业决策提供积极的财务支持；\n2. 提升财务信息化能力：结合对业务场景及业财系统的深入理解，与各方产研配合推进财务信息化建设，包括业务场景的线上计费结算、线上化传账及业财数据校验、财务系统优化升级等；\n3. 业财流程优化：通过专项梳理推进财务运营流程、信息化进程等优化，发现并解决各类财务问题，提高财务结果的效率和准确性，能识别日常工作中的流程问题，如流程断点、冗余，并通过优化流程和工具，同时积极探索并应用AI工具（大模型辅助方案撰写、自动化对账、异常检测等）提升财务运营效能；\n4. 跨部门协调：与财务其他团队积极协调，完成业务支持及其他指定任务。","requirements":"1. 本科及以上学历，会计、经济、管理类等相关专业，5 年及以上财会相关工作经验；具备账务核算及财务系统对接实操经验者优先；\n2. 具备较强的沟通能力、协调能力，能和业务线对接，具备优秀的逻辑思维和分析能力；\n3. 工作认真细心、责任心强、具有良好的团队协作精神和服务意识，有好奇心；\n4. 能够以英文作为日常工作沟通语言；\n5. 热爱并拥抱 AI，对 AI 如何重塑财务工作方式保持热情与好奇心。","description":"部门介绍\n财务平台负责公司整体和各业务层面的财务管理工作，通过建设专业、全面、复合的财务管理能力和与业务经营的紧密结合来支持公司健康发展。目前财务平台拥有财务会计、财务报告、资金管理、税务管理、财务共享、财务系统、规划分析、财务BP和内控内审等主要工作方向。我们的目标是建设业界一流的财务管理能力和经营支持体系，为公司战略的正确落地、投入效率的持续提升、业务价值的不断增长保驾护航。欢迎加入财务平台，携手一起向未来！\n\n岗位职责\n1. 业务支持：负责对接Keeta巴西业务需求，结合会计准则，结算规则，合规要求等，识别和判断业务活动对财务的影响，出具相应的财务方案，为业务部门的发展及商业决策提供积极的财务支持；\n2. 提升财务信息化能力：结合对业务场景及业财系统的深入理解，与各方产研配合推进财务信息化建设，包括业务场景的线上计费结算、线上化传账及业财数据校验、财务系统优化升级等；\n3. 业财流程优化：通过专项梳理推进财务运营流程、信息化进程等优化，发现并解决各类财务问题，提高财务结果的效率和准确性，能识别日常工作中的流程问题，如流程断点、冗余，并通过优化流程和工具，同时积极探索并应用AI工具（大模型辅助方案撰写、自动化对账、异常检测等）提升财务运营效能；\n4. 跨部门协调：与财务其他团队积极协调，完成业务支持及其他指定任务。\n\n岗位基本要求\n1. 本科及以上学历，会计、经济、管理类等相关专业，5 年及以上财会相关工作经验；具备账务核算及财务系统对接实操经验者优先；\n2. 具备较强的沟通能力、协调能力，能和业务线对接，具备优秀的逻辑思维和分析能力；\n3. 工作认真细心、责任心强、具有良好的团队协作精神和服务意识，有好奇心；\n4. 能够以英文作为日常工作沟通语言；\n5. 热爱并拥抱 AI，对 AI 如何重塑财务工作方式保持热情与好奇心。\n\n具备以下条件优先\n有互联网大公司平台经验者优先，具备财务专业基础扎实、有流程、系统优化的经验、沟通协调能力强、英语好能力者、熟悉AI工具优先\n\n岗位亮点\n- 见证 Keeta 境外业务从 0 到 1 的发展全过程，深度参与业务日常运营及业财系统建设（含 AI 实践），全面提升财务专业能力与国际视野。\n- 接触全球化互联网财务体系，是极具含金量的职业发展机会，个人成长空间广阔。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4427806108","sourceKey":"meituan_social","company":"美团","title":"物流仓储规划岗","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4427806108&jobShareType=1","duty":"1.负责仓网整体布局规划，结合业务增长目标输出仓网拓展方案；主导中心仓选址评估，综合硬件条件、覆盖半径、运营成本及合规标准，输出选址决策报告;\n2.统筹仓库功能分区、面积测算及存储策略设计，规划进销存全链路作业动线；从源头保障作业效率与库容合理性；结合库存数据识别商品结构与存储布局矛盾，主导跨部门推动落地，追踪改善效果。\n3.建立库容日监控机制，实时跟踪仓容利用率与产能水位；协同供应链计划，前置识别爆仓风险与产能瓶颈，制定扩容/扩产/流程优化预案并主导落地；\n4.动态跟踪库存结构、ABC分类及件型变化，定期输出存储布局诊断报告；通过货位优化、拣货路径调整等手段，持续提升人效与坪效；\n5.负责存储设备、搬运工具及辅助设施的选型配置与迭代；推动自动化/智能化设备创新落地，驱动作业效率系统性提升；","requirements":"1.本科及以上学历，供应链管理、物流工程、工业工程等相关专业优先；\n2.3年以上仓储规划/仓库运营/物流工程经验，电商/零售/快消行业背景优先；\n3.具备较强的项目推动能力与跨部门协作能力，能独立主导规划方案的设计与落地；\n4. 熟悉仓储管理系统及常见仓储设备，具备较强的结构化思维和数据分析能力；","description":"部门介绍\n美团闪购是美团旗下的即时零售平台，依托即时配送能力，连接本地零售供给，满足消费者30分钟万物到家的即时需求。美团闪购涵盖超市便利、食材、水果、鲜花绿植、休闲零食、酒水饮料、数码家电、美妆个护、母婴玩具、日用百货、服饰鞋帽、宠物等诸多品类，业务覆盖全国近3,000个县市区旗，每日百万级在岗骑手，以高效的配送、丰富的品类和广泛的覆盖，为美团数亿用户带来便捷的生活体验，积极助力实体零售线上化转型，提升本地商业活力。\n\n岗位职责\n1.负责仓网整体布局规划，结合业务增长目标输出仓网拓展方案；主导中心仓选址评估，综合硬件条件、覆盖半径、运营成本及合规标准，输出选址决策报告;\n2.统筹仓库功能分区、面积测算及存储策略设计，规划进销存全链路作业动线；从源头保障作业效率与库容合理性；结合库存数据识别商品结构与存储布局矛盾，主导跨部门推动落地，追踪改善效果。\n3.建立库容日监控机制，实时跟踪仓容利用率与产能水位；协同供应链计划，前置识别爆仓风险与产能瓶颈，制定扩容/扩产/流程优化预案并主导落地；\n4.动态跟踪库存结构、ABC分类及件型变化，定期输出存储布局诊断报告；通过货位优化、拣货路径调整等手段，持续提升人效与坪效；\n5.负责存储设备、搬运工具及辅助设施的选型配置与迭代；推动自动化/智能化设备创新落地，驱动作业效率系统性提升；\n\n岗位基本要求\n1.本科及以上学历，供应链管理、物流工程、工业工程等相关专业优先；\n2.3年以上仓储规划/仓库运营/物流工程经验，电商/零售/快消行业背景优先；\n3.具备较强的项目推动能力与跨部门协作能力，能独立主导规划方案的设计与落地；\n4. 熟悉仓储管理系统及常见仓储设备，具备较强的结构化思维和数据分析能力；\n\n具备以下条件优先\n有B2B行业经验， 大型仓储项目从 0 到 1 规划落地经验优先\n\n岗位亮点\n即时零售方向，行业前景好；\n美团核心业务方向，发展空间大；","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4449373230","sourceKey":"meituan_social","company":"美团","title":"组织发展专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4449373230&jobShareType=1","duty":"1. 深度理解业务，能根据业务策略，洞察事业部各个部门的发展需求，支持组织架构优化与职责梳理，提供相应解决方案并推动落地。\n\n2. 开展内外部标杆组织及方法论研究、管理机制探索研究及工具迭代，并在AI转型过程中前瞻性对组织范式、角色分工、协同模式等方向进行思考，并助力各个方向的组织转型落地。\n\n3. 基于具体业务需求，协同联动相关方，为业务提供专项的综合人力解决方案。","requirements":"1、愿意深潜业务，能够围绕业务策略推进合适的组织发展举措。\n\n2、具备较好的项目推进和沟通表达能力。\n\n3、有较好的AI理解和推动力，结合AI变化趋势，不断优化组织效率，推动产出。","description":"部门介绍\n美团HR的使命是“建设有生命力的组织，为客户和社会创造价值。” 我们认为HR的工作不是以自身“专业”为中心，而是要建设有助于员工发挥创造力的环境，支持他们更好地为外部客户和社会创造价值，也实现组织自身的进化和传承。在这个过程中，我们的每位HR同学都是“业务的战略合作伙伴、组织能力的建设者、美团精神的布道者、员工的成长伙伴”。我们要设计面向长期支撑组织有效运转的机制，我们要求真务实地帮业务解决发展中的问题和阵痛，我们要支持每一位员工历经磨炼收获成长。我们要影响和驱动让世界更美好的变化发生。如果这也是你追求的，欢迎加入美团HR，与我们一路同行！\n\n岗位职责\n1. 深度理解业务，能根据业务策略，洞察事业部各个部门的发展需求，支持组织架构优化与职责梳理，提供相应解决方案并推动落地。\n\n2. 开展内外部标杆组织及方法论研究、管理机制探索研究及工具迭代，并在AI转型过程中前瞻性对组织范式、角色分工、协同模式等方向进行思考，并助力各个方向的组织转型落地。\n\n3. 基于具体业务需求，协同联动相关方，为业务提供专项的综合人力解决方案。\n\n岗位基本要求\n1、愿意深潜业务，能够围绕业务策略推进合适的组织发展举措。\n\n2、具备较好的项目推进和沟通表达能力。\n\n3、有较好的AI理解和推动力，结合AI变化趋势，不断优化组织效率，推动产出。\n\n具备以下条件优先\n有互联网+零售、快消或餐饮行业经验。\n\n岗位亮点\n新业务线，具备组织资源管理全链路的实践机会，可深入影响业务决策。人力资源体系构建中，能探索人力资源前沿命题。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4589767680","sourceKey":"meituan_social","company":"美团","title":"小象-物流HRBP","city":"深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4589767680&jobShareType=1","duty":"1.作为业务部门的合作伙伴，能够将业务策略转化为组织策略，站在业务视角思考长周期的组织和人才发展，致力于帮助业务成功；\n2.关注人员配置合理性，协助进行内部组织结构优化，并发现组织效率改善机会，推动变化发生；\n3.通过各种专业的人力资源管理工具和方法，结合业务及组织策略，设计清晰的人才供应管理模式，对人才的选用育励汰进行全方位进行思考和推行；\n4.传承公司的文化价值观，提升团队的凝聚力和战斗力，并保障底线控制风险。","requirements":"1. 业务导向、客户导向，有较强的业务敏锐度；\n2. 本科及以上学历，具备5年及以上HRBP工作经验；\n3. 优秀的沟通能力，人际敏感度、逻辑清晰、具备结构化系统性思维，有同理心和HR的坚守；\n4. 具备非职权的影响力，韧劲儿足，在能不确定的环境中探索出工作方式和方法。","description":"部门介绍\n美团HR的使命是“建设有生命力的组织，为客户和社会创造价值。” 我们认为HR的工作不是以自身“专业”为中心，而是要建设有助于员工发挥创造力的环境，支持他们更好地为外部客户和社会创造价值，也实现组织自身的进化和传承。在这个过程中，我们的每位HR同学都是“业务的战略合作伙伴、组织能力的建设者、美团精神的布道者、员工的成长伙伴”。我们要设计面向长期支撑组织有效运转的机制，我们要求真务实地帮业务解决发展中的问题和阵痛，我们要支持每一位员工历经磨炼收获成长。我们要影响和驱动让世界更美好的变化发生。如果这也是你追求的，欢迎加入美团HR，与我们一路同行！\n\n岗位职责\n1.作为业务部门的合作伙伴，能够将业务策略转化为组织策略，站在业务视角思考长周期的组织和人才发展，致力于帮助业务成功；\n2.关注人员配置合理性，协助进行内部组织结构优化，并发现组织效率改善机会，推动变化发生；\n3.通过各种专业的人力资源管理工具和方法，结合业务及组织策略，设计清晰的人才供应管理模式，对人才的选用育励汰进行全方位进行思考和推行；\n4.传承公司的文化价值观，提升团队的凝聚力和战斗力，并保障底线控制风险。\n\n岗位基本要求\n1. 业务导向、客户导向，有较强的业务敏锐度；\n2. 本科及以上学历，具备5年及以上HRBP工作经验；\n3. 优秀的沟通能力，人际敏感度、逻辑清晰、具备结构化系统性思维，有同理心和HR的坚守；\n4. 具备非职权的影响力，韧劲儿足，在能不确定的环境中探索出工作方式和方法。\n\n岗位亮点\n我们有开放、直接的工作氛围，用逻辑和事实说话。\n我们尊重知识和常识，努力以业务视角思考HR自身工作。\n我们理想的候选人，能够在快速变化的环境中工作，贴近业务一线，关注组织氛围和人心；能够有理论思考和快速学习能力，也能够推动解决业务实际问题。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4642382284","sourceKey":"meituan_social","company":"美团","title":"海外HRBP","city":"利雅得","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4642382284&jobShareType=1","duty":"1. 负责Keemart海外业务BP工作，深入理解业务需求并联动COE提供定制化HR解决方案。  \n2. 搭建并优化海外团队的组织架构，推动人才发展、绩效管理、员工关系等模块落地实施。  \n3. 协助业务负责人进行团队建设，推动招聘，提升组织效能与员工敬业度，营造积极的企业文化氛围。  \n4. 解决日常中的各种员工问题，确保用工管理的合规性和稳定性。","requirements":"1. 大学本科及以上学历，人力资源管理或相关专业优先。  \n2. 具备10年以上人力资源工作经验，其中至少5年HRBP岗位经验。有工作经验者优先。  \n3.英语能作为工作语言，阿拉伯语能力为加分项。  \n4.心里状态成熟，能够应对复杂的环境。","description":"部门介绍\n美团HR的使命是“建设有生命力的组织，为客户和社会创造价值。” 我们认为HR的工作不是以自身“专业”为中心，而是要建设有助于员工发挥创造力的环境，支持他们更好地为外部客户和社会创造价值，也实现组织自身的进化和传承。在这个过程中，我们的每位HR同学都是“业务的战略合作伙伴、组织能力的建设者、美团精神的布道者、员工的成长伙伴”。我们要设计面向长期支撑组织有效运转的机制，我们要求真务实地帮业务解决发展中的问题和阵痛，我们要支持每一位员工历经磨炼收获成长。我们要影响和驱动让世界更美好的变化发生。如果这也是你追求的，欢迎加入美团HR，与我们一路同行！\n\n岗位职责\n1. 负责Keemart海外业务BP工作，深入理解业务需求并联动COE提供定制化HR解决方案。  \n2. 搭建并优化海外团队的组织架构，推动人才发展、绩效管理、员工关系等模块落地实施。  \n3. 协助业务负责人进行团队建设，推动招聘，提升组织效能与员工敬业度，营造积极的企业文化氛围。  \n4. 解决日常中的各种员工问题，确保用工管理的合规性和稳定性。\n\n岗位基本要求\n1. 大学本科及以上学历，人力资源管理或相关专业优先。  \n2. 具备10年以上人力资源工作经验，其中至少5年HRBP岗位经验。有工作经验者优先。  \n3.英语能作为工作语言，阿拉伯语能力为加分项。  \n4.心里状态成熟，能够应对复杂的环境。\n\n岗位亮点\n1. 参与公司全球化战略布局，深入海外一线业务场景，成长空间广阔。  \n2. 利雅得作为新兴商业中心，职业发展机会丰富，国际化视野提升显著。  \n3. 公司提供具有竞争力的薪酬福利及完善的海外外派支持体系。  \n4. 与多元文化团队共事，提升跨文化管理与协作能力。  \n5. 资深岗位定位，具备独立决策权与影响力，助力个人职业跃迁。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4662999141","sourceKey":"meituan_social","company":"美团","title":"Keemart HRBP","city":"科威特城","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4662999141&jobShareType=1","duty":"1. 深入业务部门，理解业务战略与需求，提供定制化的人力资源解决方案。  \n2. 负责人才招聘、绩效管理、员工关系及组织发展等模块的落地执行。  \n3. 推动企业文化建设，提升员工敬业度与组织凝聚力。  \n4. 协助业务负责人进行团队搭建与人才梯队培养。","requirements":"1. 大学本科及以上学历，人力资源、管理类相关专业优先。  \n2. 至少5年HR相关工作经验，具备HRBP或类似岗位经验。  \n3. 熟悉科威特地区劳动法规及用工环境，有科威特或海湾国家工作经验者。\n4. 优秀的沟通协调能力与跨文化适应能力，英语流利，阿拉伯语为加分项。","description":"部门介绍\n美团HR的使命是“建设有生命力的组织，为客户和社会创造价值。” 我们认为HR的工作不是以自身“专业”为中心，而是要建设有助于员工发挥创造力的环境，支持他们更好地为外部客户和社会创造价值，也实现组织自身的进化和传承。在这个过程中，我们的每位HR同学都是“业务的战略合作伙伴、组织能力的建设者、美团精神的布道者、员工的成长伙伴”。我们要设计面向长期支撑组织有效运转的机制，我们要求真务实地帮业务解决发展中的问题和阵痛，我们要支持每一位员工历经磨炼收获成长。我们要影响和驱动让世界更美好的变化发生。如果这也是你追求的，欢迎加入美团HR，与我们一路同行！\n\n岗位职责\n1. 深入业务部门，理解业务战略与需求，提供定制化的人力资源解决方案。  \n2. 负责人才招聘、绩效管理、员工关系及组织发展等模块的落地执行。  \n3. 推动企业文化建设，提升员工敬业度与组织凝聚力。  \n4. 协助业务负责人进行团队搭建与人才梯队培养。\n\n岗位基本要求\n1. 大学本科及以上学历，人力资源、管理类相关专业优先。  \n2. 至少5年HR相关工作经验，具备HRBP或类似岗位经验。  \n3. 熟悉科威特地区劳动法规及用工环境，有科威特或海湾国家工作经验者。\n4. 优秀的沟通协调能力与跨文化适应能力，英语流利，阿拉伯语为加分项。\n\n岗位亮点\n1. 加入国际化团队，参与跨国业务的人力资源战略制定。  \n2. 工作地点位于科威特，享受具有竞争力的薪酬与福利待遇。  \n3. 提供广阔的职业发展空间与跨文化管理经验积累机会。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4572733127","sourceKey":"meituan_social","company":"美团","title":"Keemart招聘","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4572733127&jobShareType=1","duty":"1. 负责Keemart岗位的招聘全流程执行，包括职位发布、简历筛选、面试安排及候选人跟进。  \n2. 与业务部门沟通招聘需求，明确岗位要求并制定相应的招聘策略。  \n3. 拓展和维护招聘渠道，提升优质候选人获取效率。  \n4. 协助完成招聘数据统计与分析，优化招聘流程与效果。","requirements":"1. 大学本科及以上学历，人力资源管理或相关专业优先。  \n2. 具备2年以上招聘相关工作经验，有互联网或电商行业背景者优先。  \n3. 熟悉招聘流程及常用招聘工具，具备良好的沟通协调能力。  \n4. 工作积极主动，具备较强的执行力和情绪管理能力。\n5.英文能面试沟通者优先。","description":"部门介绍\n美团HR的使命是“建设有生命力的组织，为客户和社会创造价值。” 我们认为HR的工作不是以自身“专业”为中心，而是要建设有助于员工发挥创造力的环境，支持他们更好地为外部客户和社会创造价值，也实现组织自身的进化和传承。在这个过程中，我们的每位HR同学都是“业务的战略合作伙伴、组织能力的建设者、美团精神的布道者、员工的成长伙伴”。我们要设计面向长期支撑组织有效运转的机制，我们要求真务实地帮业务解决发展中的问题和阵痛，我们要支持每一位员工历经磨炼收获成长。我们要影响和驱动让世界更美好的变化发生。如果这也是你追求的，欢迎加入美团HR，与我们一路同行！\n\n岗位职责\n1. 负责Keemart岗位的招聘全流程执行，包括职位发布、简历筛选、面试安排及候选人跟进。  \n2. 与业务部门沟通招聘需求，明确岗位要求并制定相应的招聘策略。  \n3. 拓展和维护招聘渠道，提升优质候选人获取效率。  \n4. 协助完成招聘数据统计与分析，优化招聘流程与效果。\n\n岗位基本要求\n1. 大学本科及以上学历，人力资源管理或相关专业优先。  \n2. 具备2年以上招聘相关工作经验，有互联网或电商行业背景者优先。  \n3. 熟悉招聘流程及常用招聘工具，具备良好的沟通协调能力。  \n4. 工作积极主动，具备较强的执行力和情绪管理能力。\n5.英文能面试沟通者优先。\n\n岗位亮点\n1. 加入快速发展的电商平台，参与核心人才招聘工作。  \n2. 与优秀团队共事，获得专业成长与职业发展空间。  \n3. 工作地点位于北京核心区域，办公环境舒适，福利待遇完善。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4695519837","sourceKey":"meituan_social","company":"美团","title":"数字化品控岗位","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4695519837&jobShareType=1","duty":"1. 全链路品控数字化体系搭建（核心）：深入调研快驴进货品控业务全链路，识别高价值数字化/智能化提效机会点，将传统品控管理流程拆解为可被数据/AI赋能的标准化模块，输出全链路数字化品控提效地图与解决方案，主导或参与建设品控数据资产体系。\n\n2. 数据/AI驱动的品控产品规划与落地：主导品控数字化工具的产品化设计，从业务需求出发，将品控痛点转化为可交付的数字化工具/AI提效方案，可自行闭环或联动产品/数据团队，推动数字化品控工具在业务侧快速落地，跟踪大模型、计算机视觉等AI技术在品控场景的应用潜力，主动探索AI赋能的新场景。\n\n3. 品控数据运营与效果评估：搭建并运营品控数据指标体系，建立覆盖供应商质量、到货质量、仓储质量、配送质量、售后客诉的全链路质量评估指标，通过数据驱动识别质量风险、定位问题根因、优化品控策略，推动质量客诉改善和供应商质量管理升级。","requirements":"1. 数据分析能力：熟练使用SQL数据分析工具，能独立完成数据提取、清洗、分析和可视化，能从海量业务数据中发现质量问题和趋势，并输出可落地的改善方案，有BI工具（如星辰/魔数等）使用经验，能搭建或优化数据看板。\n\n2.产品思维与数字化素养：具备产品思维和用户视角，能将复杂的业务痛点抽象为清晰的数字化/产品化需求，对大模型、AI等前沿技术在企业级落地有浓厚兴趣，能判断技术在品控场景的适用性了解数字化转型的基本方法论，能基于AI工具快速搭建轻量级业务原型验证产品逻辑。\n\n3. 业务理解与执行力：深入理解餐饮供应链全链路（研发、采购、生产、仓储、配送、售后），熟悉生鲜/冻品/干货等品类特性，具备优秀的跨部门沟通协调能力，能推动复杂项目在多方协作中落地，有项目管理经验者优先。","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1. 全链路品控数字化体系搭建（核心）：深入调研快驴进货品控业务全链路，识别高价值数字化/智能化提效机会点，将传统品控管理流程拆解为可被数据/AI赋能的标准化模块，输出全链路数字化品控提效地图与解决方案，主导或参与建设品控数据资产体系。\n\n2. 数据/AI驱动的品控产品规划与落地：主导品控数字化工具的产品化设计，从业务需求出发，将品控痛点转化为可交付的数字化工具/AI提效方案，可自行闭环或联动产品/数据团队，推动数字化品控工具在业务侧快速落地，跟踪大模型、计算机视觉等AI技术在品控场景的应用潜力，主动探索AI赋能的新场景。\n\n3. 品控数据运营与效果评估：搭建并运营品控数据指标体系，建立覆盖供应商质量、到货质量、仓储质量、配送质量、售后客诉的全链路质量评估指标，通过数据驱动识别质量风险、定位问题根因、优化品控策略，推动质量客诉改善和供应商质量管理升级。\n\n岗位基本要求\n1. 数据分析能力：熟练使用SQL数据分析工具，能独立完成数据提取、清洗、分析和可视化，能从海量业务数据中发现质量问题和趋势，并输出可落地的改善方案，有BI工具（如星辰/魔数等）使用经验，能搭建或优化数据看板。\n\n2.产品思维与数字化素养：具备产品思维和用户视角，能将复杂的业务痛点抽象为清晰的数字化/产品化需求，对大模型、AI等前沿技术在企业级落地有浓厚兴趣，能判断技术在品控场景的适用性了解数字化转型的基本方法论，能基于AI工具快速搭建轻量级业务原型验证产品逻辑。\n\n3. 业务理解与执行力：深入理解餐饮供应链全链路（研发、采购、生产、仓储、配送、售后），熟悉生鲜/冻品/干货等品类特性，具备优秀的跨部门沟通协调能力，能推动复杂项目在多方协作中落地，有项目管理经验者优先。\n\n具备以下条件优先\n1.AI产品应用实战经验，NoCode、Skill、AI Agent等数字化工具落地经验。\n\n2.熟练使用Python等数据分析工具。\n\n3.熟悉供应商质量管理、食品安全法规（ISO22000等）者优先。\n\n岗位亮点\n1.AI落地场景丰富：快驴品控业务场景复杂、数据丰富，是AI/大模型落地的优质土壤，有大量\"从想法到产品\"的实战机会。\n\n2.跨职能成长空间：岗位覆盖\"数据+产品+运营+品控\"多维度，能快速成长为复合型数字化人才。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4654926632","sourceKey":"meituan_social","company":"美团","title":"城市经理","city":"上海市/苏州市/南京市/合肥市/无锡市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4654926632&jobShareType=1","duty":"1. 负责组建高质量的销售、采购团队，对团队梯队搭建、人才培养、人员管理负责；\n2. 负责城市目标、策略制定及分解、落地负责，确保在正确的策略下完成业务目标，同时沉淀方法论；\n3. 带领团队帮助客户更好进行服务规划、完成服务目标、提升服务满意度，从而提升公司品牌影响力；\n4. 协调总部相关部门带领采销仓配出色完成业务目标；\n5.从运营的各个环的运营中发现问题、提出建议、建立流程持续提高城市团队运营效率。","requirements":"1.大专以上毕业，5年以上工作经验；\n2.有大规模直销管理经验则优先考虑；\n3.有食材经验值优先考虑；\n4.超强的使命感和执行力、不屈不挠的斗志、能吃苦；","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1. 负责组建高质量的销售、采购团队，对团队梯队搭建、人才培养、人员管理负责；\n2. 负责城市目标、策略制定及分解、落地负责，确保在正确的策略下完成业务目标，同时沉淀方法论；\n3. 带领团队帮助客户更好进行服务规划、完成服务目标、提升服务满意度，从而提升公司品牌影响力；\n4. 协调总部相关部门带领采销仓配出色完成业务目标；\n5.从运营的各个环的运营中发现问题、提出建议、建立流程持续提高城市团队运营效率。\n\n岗位基本要求\n1.大专以上毕业，5年以上工作经验；\n2.有大规模直销管理经验则优先考虑；\n3.有食材经验值优先考虑；\n4.超强的使命感和执行力、不屈不挠的斗志、能吃苦；\n\n具备以下条件优先\n有零售行业优先\n\n岗位亮点\n行业发展增长潜力大，发展空间大；\n有机会不断提升个人职业素养和管理能力；","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4600957909","sourceKey":"meituan_social","company":"美团","title":"企业文化 AI Builder","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4600957909&jobShareType=1","duty":"1.舆情监控与处置：负责组织相关的内外部舆情的监测、分发、整合，与业务部门沟通，输出舆情研判，并支持舆情处置。牵头公司重大舆情事件的应对策略制定、落地，以及事后复盘。\n2.公司舆情体系建设：利用AI工具，主导舆情监控产品的搭建与持续优化，完善监测覆盖与预警能力；沉淀舆情的处置SOP与案例库，提升与业务部门沟通、协同的效率；基于对舆情的深度分析，搭建、丰富舆情信息的产品矩阵，将舆情分析与洞察沉淀为可传播的信息产品。\n3.信息收集与组织洞察：负责组织文化相关的访谈调研、线下活动运营，深入一线获取信息；基于内外部信息的分析、判断，向公司输出组织文化领域的策略建议。\n4.重大项目支持：为公司重大沟通项目、重要管理节点，以及组织文化相关的内容、产品、机制优化，基于舆情方面的信息和专业判断提供支持。","requirements":"1.本科及以上学历，新闻传播学、社会学、统计学、情报学、计算机科学、公共管理等相关专业优先，具备跨学科背景者尤佳。\n2.熟悉主流舆情监测工具，精通数据分析的各类方法，具备Vibe Coding实践经验，能够熟练运用数据工具进行舆情建模与可视化呈现。\n3.3年以上舆情管理、公共关系或相关领域工作经验，具备独立搭建舆情研判框架与工作体系的实战能力，对互联网舆情传播规律有深刻理解，有成功处置重大舆情事件的案例。\n4.出色的跨团队沟通与项目管理能力，具备较强的解决问题能力与应变能力，能够在复杂环境下快速判断并推动舆情项目落地，具备优秀的报告撰写与汇报表达能力。","description":"部门介绍\n美团HR的使命是“建设有生命力的组织，为客户和社会创造价值。” 我们认为HR的工作不是以自身“专业”为中心，而是要建设有助于员工发挥创造力的环境，支持他们更好地为外部客户和社会创造价值，也实现组织自身的进化和传承。在这个过程中，我们的每位HR同学都是“业务的战略合作伙伴、组织能力的建设者、美团精神的布道者、员工的成长伙伴”。我们要设计面向长期支撑组织有效运转的机制，我们要求真务实地帮业务解决发展中的问题和阵痛，我们要支持每一位员工历经磨炼收获成长。我们要影响和驱动让世界更美好的变化发生。如果这也是你追求的，欢迎加入美团HR，与我们一路同行！\n\n岗位职责\n1.舆情监控与处置：负责组织相关的内外部舆情的监测、分发、整合，与业务部门沟通，输出舆情研判，并支持舆情处置。牵头公司重大舆情事件的应对策略制定、落地，以及事后复盘。\n2.公司舆情体系建设：利用AI工具，主导舆情监控产品的搭建与持续优化，完善监测覆盖与预警能力；沉淀舆情的处置SOP与案例库，提升与业务部门沟通、协同的效率；基于对舆情的深度分析，搭建、丰富舆情信息的产品矩阵，将舆情分析与洞察沉淀为可传播的信息产品。\n3.信息收集与组织洞察：负责组织文化相关的访谈调研、线下活动运营，深入一线获取信息；基于内外部信息的分析、判断，向公司输出组织文化领域的策略建议。\n4.重大项目支持：为公司重大沟通项目、重要管理节点，以及组织文化相关的内容、产品、机制优化，基于舆情方面的信息和专业判断提供支持。\n\n岗位基本要求\n1.本科及以上学历，新闻传播学、社会学、统计学、情报学、计算机科学、公共管理等相关专业优先，具备跨学科背景者尤佳。\n2.熟悉主流舆情监测工具，精通数据分析的各类方法，具备Vibe Coding实践经验，能够熟练运用数据工具进行舆情建模与可视化呈现。\n3.3年以上舆情管理、公共关系或相关领域工作经验，具备独立搭建舆情研判框架与工作体系的实战能力，对互联网舆情传播规律有深刻理解，有成功处置重大舆情事件的案例。\n4.出色的跨团队沟通与项目管理能力，具备较强的解决问题能力与应变能力，能够在复杂环境下快速判断并推动舆情项目落地，具备优秀的报告撰写与汇报表达能力。\n\n岗位亮点\n你将有机会作为企业文化团队的“信息中枢”和“AI Builder”，有机会从 0 到 1 独立搭建内部舆情监测与分析体系，参与资讯中心、数字员工运营、员工社区等企业文化场景的 AI 改造，从真实业务问题出发，探索、验证并落地新的沟通信息流，促动企业文化工作持续升级。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4698262666","sourceKey":"meituan_social","company":"美团","title":"市场合规岗","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4698262666&jobShareType=1","duty":"1. 负责公司业务活动的合规性审查，确保符合市场合规相关法律法规及行业合规要求。  \n2. 跟踪并分析市场合规相关政策动态，及时评估对公司业务的影响并提出应对建议。  \n3. 制定并完善市场合规管理制度与流程，推动合规管理工作落地。  \n4. 处理市场合规相关案事件。","requirements":"1. 硕士研究生及以上学历，法律、公共管理、工商管理等相关专业优先。  \n2. 具备5年以上市场合规、公共事务或公司事务相关工作经验，有互联网或科技企业背景者优先。  \n3. 熟悉中国市场合规相关法律法规。  \n4. 具备较强的政策分析能力、沟通协调能力和独立解决问题的能力。","description":"部门介绍\n公司事务平台负责构建公司的公共战略体系，助力业务可持续发展及公司对外影响力的提升。通过内外部风险管理，确保公司合规发展；通过深耕公共战略，推动内外良好沟通，连接公司发展与社会期待，助力业务高质量发展；通过管理社会责任议题、公益投入等，助力公司创造更多社会价值；同时为公司提供行政、采购等基础服务。我们坚持“懂业务、拿结果，勇担当、善协同，不唯上、只唯真”的工作理念，期待具有公共战略素养、了解公司治理逻辑的你加入！\n\n岗位职责\n1. 负责公司业务活动的合规性审查，确保符合市场合规相关法律法规及行业合规要求。  \n2. 跟踪并分析市场合规相关政策动态，及时评估对公司业务的影响并提出应对建议。  \n3. 制定并完善市场合规管理制度与流程，推动合规管理工作落地。  \n4. 处理市场合规相关案事件。\n\n岗位基本要求\n1. 硕士研究生及以上学历，法律、公共管理、工商管理等相关专业优先。  \n2. 具备5年以上市场合规、公共事务或公司事务相关工作经验，有互联网或科技企业背景者优先。  \n3. 熟悉中国市场合规相关法律法规。  \n4. 具备较强的政策分析能力、沟通协调能力和独立解决问题的能力。\n\n岗位亮点\n1. 参与公司核心业务合规体系建设，发挥专业影响力。  \n2. 与高层及多部门协同合作，提升跨领域综合能力。  \n3. 工作地点位于北京核心商务区，办公环境优越。  \n4. 提供具有竞争力的薪酬与完善的职业发展通道。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4695674856","sourceKey":"meituan_social","company":"美团","title":"北京业务合规专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4695674856&jobShareType=1","duty":"1. 对接行业行政主管部门，做好沟通协调和定期汇报，梳理落实政策法规要求事项，并跟进后续落地。\n​\n2. 基于过往工作经验思维，对内开展业务合规自查，识别风险，输出风险清单、整改方案。\n​\n3. 起草、修订企业内部合规管理制度、业务操作规范、台账表单；审核对外涉行政类工作文书。\n​\n4. 协助处理投诉举报、突发事件调查处置；参与行政机关与企业之间沟通交流等相关事务。\n​\n5. 开展内部合规培训，解读政府政策法规等要点，提出合规建议。\n​\n6. 跟踪行业政策更新，定期输出政策提示报告，完成上级交办其他风控、法务相关工作。","requirements":"1. 本科及以上学历，法律/法学专业优先；持有法律职业资格证书优先。\n​\n2. 必须具备行政执法机关一线工作经历（市场JG、综合执法等），熟悉行政执法相关经验。\n​\n3. 熟练掌握《行政处罚法》《行政强制法》《行政复议法》等相关法律法规，能够独立研判企业面临的行政法律风险。\n​\n4. 具备政府部门沟通经验，公文写作能力强，善于撰写报告、情况说明、整改材料；逻辑缜密，原则性强，处事成熟稳重。\n​\n5. 无党纪政务处分、无违法违纪记录；工作能力强，能够应对重大、突发事项。\n​\n6. 有从体制内转行企业工作经历者优先。","description":"部门介绍\n公司事务平台负责构建公司的公共战略体系，助力业务可持续发展及公司对外影响力的提升。通过内外部风险管理，确保公司合规发展；通过深耕公共战略，推动内外良好沟通，连接公司发展与社会期待，助力业务高质量发展；通过管理社会责任议题、公益投入等，助力公司创造更多社会价值；同时为公司提供行政、采购等基础服务。我们坚持“懂业务、拿结果，勇担当、善协同，不唯上、只唯真”的工作理念，期待具有公共战略素养、了解公司治理逻辑的你加入！\n\n岗位职责\n1. 对接行业行政主管部门，做好沟通协调和定期汇报，梳理落实政策法规要求事项，并跟进后续落地。\n​\n2. 基于过往工作经验思维，对内开展业务合规自查，识别风险，输出风险清单、整改方案。\n​\n3. 起草、修订企业内部合规管理制度、业务操作规范、台账表单；审核对外涉行政类工作文书。\n​\n4. 协助处理投诉举报、突发事件调查处置；参与行政机关与企业之间沟通交流等相关事务。\n​\n5. 开展内部合规培训，解读政府政策法规等要点，提出合规建议。\n​\n6. 跟踪行业政策更新，定期输出政策提示报告，完成上级交办其他风控、法务相关工作。\n\n岗位基本要求\n1. 本科及以上学历，法律/法学专业优先；持有法律职业资格证书优先。\n​\n2. 必须具备行政执法机关一线工作经历（市场JG、综合执法等），熟悉行政执法相关经验。\n​\n3. 熟练掌握《行政处罚法》《行政强制法》《行政复议法》等相关法律法规，能够独立研判企业面临的行政法律风险。\n​\n4. 具备政府部门沟通经验，公文写作能力强，善于撰写报告、情况说明、整改材料；逻辑缜密，原则性强，处事成熟稳重。\n​\n5. 无党纪政务处分、无违法违纪记录；工作能力强，能够应对重大、突发事项。\n​\n6. 有从体制内转行企业工作经历者优先。\n\n岗位亮点\n1. 经验价值充分发挥：过往行政执法、办案经验可直接落地应用，不再局限机关流程，站在企业端完整主导合规风控工作，个人实务经验能够直接转化业务价值。\n​\n2. 工作权责清晰：独立负责行政合规板块，拥有制度梳理、风险研判、政府对接的实操空间，不是单纯事务性打杂，能够搭建适配公司的合规体系。\n​\n3. 团队氛围简单务实：管理层重视合规建设，尊重法律专业意见，合规意见能够得到充分听取。\n​\n4. 稳定平台，压力适度：企业经营稳健，配套完善五险一金、年度体检、各类法定福利。\n​\n5. 成长空间：可深度熟悉企业全业务链条，后续可向高级合规、合规管理方向发展。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4472889760","sourceKey":"meituan_social","company":"美团","title":"无人机业务-数据采集项目运营","city":"深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4472889760&jobShareType=1","duty":"1、参与具身智能数据运营体系的从0到1搭建，包括采集场景搭建、采集流程设计、SOP制定与持续迭代\n\n2、支持数据采集人员的招募、培训、排班及日常管理，确保采集流程和人员高效运转\n\n3、制定并执行数据质量监控机制，跟踪关键指标，及时发现并解决质量问题\n\n4、管控数据采集成本，优化人效比，推动有效数据单位成本持续下降\n\n5、作为技术与运营的\"翻译层\"：将算法团队的数据需求转化为一线可执行动作，将运营现实反馈给产品/硬件团队，推动采集任务高效落地\n\n6、搭建数据看板，定期输出运营分析报告，用数据驱动决策优化","requirements":"2年以上工作经验，本科及以上学历，专业不限\n\n学习能力强，有在\"模糊+快速变化\"环境下搭建体系的能力或经历，适应从0到1阶段的不确定性和快节奏\n\n沟通协调能力强，能有效推动跨团队协作\n\n较强的项目推进能力和多线程管理能力，能同时跟进多个并行任务\n\n数据敏感度高，熟练使用AI工具进行数据分析","description":"部门介绍\n为了更好地提升城市即时配送的效率与体验，2017年，美团启动了无人机配送服务的探索，通过科技创新推动履约工具变革，加快建设空地协同的本地即时配送网络。\n在过去的六年里，美团无人机完成了飞行器、自动化机场及智能调度系统的研发工作，实现了研发设计、生产制造、运营运维全链条布局，达成了城市复杂场景物流无人机高频次、高密度、多天时、多天侯运行。\n2023年7月，美团无人机在上海发布了自主研发的第四代无人机，跟此前机型相比，新机型升级了环境适应能力，可在“零下20度至50度”的中雨、中雪、6级风、弱光等环境中稳定飞行，能够适应97%以上国内城市的自然环境要求。\n截至2024年12月，美团无人机已在深圳、北京、上海、广州、南京、迪拜等城市开通53条航线，并累计完成订单超40万单。即时零售配送服务覆盖了办公、社区、景区、市政公园、校园、医疗、图书馆等多种场景。在医疗场景中，美团无人机可围绕医疗血液、检验样本、院前急救物资、特殊药品等医疗物资配送需求建设端到端的全天时急送网络。\n\n岗位职责\n1、参与具身智能数据运营体系的从0到1搭建，包括采集场景搭建、采集流程设计、SOP制定与持续迭代\n\n2、支持数据采集人员的招募、培训、排班及日常管理，确保采集流程和人员高效运转\n\n3、制定并执行数据质量监控机制，跟踪关键指标，及时发现并解决质量问题\n\n4、管控数据采集成本，优化人效比，推动有效数据单位成本持续下降\n\n5、作为技术与运营的\"翻译层\"：将算法团队的数据需求转化为一线可执行动作，将运营现实反馈给产品/硬件团队，推动采集任务高效落地\n\n6、搭建数据看板，定期输出运营分析报告，用数据驱动决策优化\n\n岗位基本要求\n2年以上工作经验，本科及以上学历，专业不限\n\n学习能力强，有在\"模糊+快速变化\"环境下搭建体系的能力或经历，适应从0到1阶段的不确定性和快节奏\n\n沟通协调能力强，能有效推动跨团队协作\n\n较强的项目推进能力和多线程管理能力，能同时跟进多个并行任务\n\n数据敏感度高，熟练使用AI工具进行数据分析\n\n具备以下条件优先\n有线下场景数据采集或标注项目经验\n\n有O2O运营、众包/外包团队管理、数据标注运营、线下地推运营经验\n\n有AI/机器人/自动驾驶行业相关经验\n\n有大规模人员调度或众包平台运营经验\n\n岗位亮点\n场景优势：背靠美团体系，极大地场景应用和数据源优势，是将想法变为现实的理想平台\n\n行业前沿：具身智能是当前 AI 最热门的方向之一，本岗位直接参与具身大模型数据体系从0到1的建设，具有极高的行业稀缺性\n\n规模扩张：极少见的大规模运营实战机会\n\n快速成长：业务快速发展期，有清晰的发展空间和核心决策参与机会","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4677194362","sourceKey":"meituan_social","company":"美团","title":"Keemart-商品商分TL","city":"利雅得/北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4677194362&jobShareType=1","duty":"1. 带领商品商分团队，负责Keemart商品业务的数据分析体系建设，搭建核心指标监控体系并推动落地。  \n2. 深入理解商品运营逻辑，通过数据分析挖掘业务增长机会，输出高质量分析报告并推动策略优化。  \n3. 开展各种调研对标和专项课题研究，提供有效增量输入， 形成驱动业务增长改善的重要策略\n4. 能积极应用 AI 工具，赋能商分和业务工作效率。","requirements":"1. 硕士研究生及以上学历，数学、统计学、计算机、经济学等相关专业优先。  \n2. 6年以上商业分析或数据分析相关工作经验，有深入的专题研究经验，有电商或零售行业背景者优先。  \n3. 熟练使用SQL、Python或R等分析工具，具备较强的数据建模与统计分析能力。  \n4. 具备优秀的逻辑思维、沟通表达能力和跨团队协作能力，能独立承担项目并推动落地。","description":"部门介绍\n美团的使命是“帮大家吃得更好，生活更好”，公司聚焦“零售 + 科技”战略，和广大商户与各类合作伙伴一起，努力为消费者提供品质生活，推动商品零售和服务零售在需求侧和供给侧的数字化转型。\n2018年9月20日，美团正式在港交所挂牌上市。美团将始终坚持以客户为中心，不断加大在科技研发方面的投入，更好承担社会责任，更多创造社会价值，与广大合作伙伴一起发展共赢。\n\n岗位职责\n1. 带领商品商分团队，负责Keemart商品业务的数据分析体系建设，搭建核心指标监控体系并推动落地。  \n2. 深入理解商品运营逻辑，通过数据分析挖掘业务增长机会，输出高质量分析报告并推动策略优化。  \n3. 开展各种调研对标和专项课题研究，提供有效增量输入， 形成驱动业务增长改善的重要策略\n4. 能积极应用 AI 工具，赋能商分和业务工作效率。\n\n岗位基本要求\n1. 硕士研究生及以上学历，数学、统计学、计算机、经济学等相关专业优先。  \n2. 6年以上商业分析或数据分析相关工作经验，有深入的专题研究经验，有电商或零售行业背景者优先。  \n3. 熟练使用SQL、Python或R等分析工具，具备较强的数据建模与统计分析能力。  \n4. 具备优秀的逻辑思维、沟通表达能力和跨团队协作能力，能独立承担项目并推动落地。\n\n岗位亮点\n1. 加入快速发展的跨境电商平台，参与核心商品业务的数据驱动决策。  \n2. 工作地点灵活，可选择利雅得或北京，享受国际化工作环境。  \n3. 担任团队负责人角色，拥有较大的业务影响力和成长空间。  \n4. 与行业资深团队共事，积累前沿的商业分析与电商运营经验。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4653589411","sourceKey":"meituan_social","company":"美团","title":"拼好饭-质控负责人","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4653589411&jobShareType=1","duty":"1.负责商品与供应链管理/品质管理工作，确保产品质量符合公司标准；\n2.负责建立和维护供应商质量管理体系，监督供应商的生产过程；\n3.负责制定品控流程和标准，确保产品质量稳定；\n4.负责处理产品质量问题，及时跟进和解决；","requirements":"岗位要求:\n1.大学本科及以上学历，商品与供应链管理/品质管理相关专业优先；\n2.三年以上商品与供应链管理/品质管理经验，有团队管理经验者优先考虑；\n3.熟悉品控流程和标准，具备良好的沟通协调能力；\n4.具备较强的责任心和执行力，能够承受工作压力；\n5.具备良好的团队合作精神","description":"部门介绍\n美团外卖秉承“帮大家吃得更好，生活更好”的使命，始终聚焦于消费者用餐需求。我们通过科技连接消费者和商家，依托庞大的骑手团队，以“线上+线下”的业务模式，为消费者提供品质化、精细化、多样化的餐饮外卖服务。\n外卖事业部是为用户与商家提供全链路交易服务的业务组织，围绕餐饮外卖搭建了包含外卖业务与创新孵化业务在内的多个部门。\n我们的目标是帮助商家开源增收、提高经营效率，促进餐饮行业数字化，以及为更多用户提供更便捷更有品质的外卖服务。加入我们，一起为上亿用户提供更好的用餐体验，帮助大家吃得更好，生活更好！\n\n岗位职责\n1.负责商品与供应链管理/品质管理工作，确保产品质量符合公司标准；\n2.负责建立和维护供应商质量管理体系，监督供应商的生产过程；\n3.负责制定品控流程和标准，确保产品质量稳定；\n4.负责处理产品质量问题，及时跟进和解决；\n\n岗位基本要求\n岗位要求:\n1.大学本科及以上学历，商品与供应链管理/品质管理相关专业优先；\n2.三年以上商品与供应链管理/品质管理经验，有团队管理经验者优先考虑；\n3.熟悉品控流程和标准，具备良好的沟通协调能力；\n4.具备较强的责任心和执行力，能够承受工作压力；\n5.具备良好的团队合作精神\n\n具备以下条件优先\n在连锁餐企、零售企业、供应链公司从事品质管理的人员优先\n\n岗位亮点\n岗位亮点:\n1.薪资福利优厚，发展空间大；\n2.可与公司高级管理层密切合作，学习机会丰富；\n3.团队氛围好，工作氛围轻松愉快。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4691076393","sourceKey":"meituan_social","company":"美团","title":"易生活行业产品","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4691076393&jobShareType=1","duty":"1.负责易生活行业（生活服务、摄影、教育等）用户决策信息建设、AI内容处理能力建设及上层应用落地，运用AI能力实现内容理解与生产的自动化闭环，驱动用户选店选品导购体验突破\n2.建立AI模型效果标准化评测体系，监控模型识别覆盖、准确率与召回率，持续驱动模型评测与迭代优化，提升各行业内容处理效果。\n3.协同联动算法、研发、运营等上下游资源，推动AI内容能力在搜索、供给、运营等业务环节落地，助力平台易生活行业内容生态长期建设。\n4.参与易生活行业AI产研新范式探索，运用AI辅助工具快速验证MVP，运用AI能力实现部分业务场景的自动化闭环。","requirements":"1.本科及以上学历，具备2年以上C端产品经验，本地生活服务、电商或内容平台行业经验者优先；以用户体验为核心，逻辑清晰，具备优秀的结构化思维和快速学习能力，能通过数据分析定位问题、验证假设、衡量效果。\n2.强烈的Builder心态，喜欢动手做东西，不只是写PRD；具备AI Coding的实战经验，能熟练使用AI辅助工具快速验证产品方案。\n3.善于跨团队沟通协作，有良好的表达和沟通能力，能协同算法、研发、运营等上下游资源推动项目落地拿到结果。\n4.有韧性和责任心，对行业有热情，积极主动，能快速学习并在工作中持续寻求突破。","description":"部门介绍\n美团服务零售事业部下设乐生活业务部、易生活业务部、进场零售业务部以及中小城市发展部四大业务部门，旨在通过提供丰富、可靠、实惠的服务与商品满足用户各类生活需求。我们所处的服务零售行业是一个具有万亿规模的市场，覆盖足疗洗浴、酒吧KTV、运动健身、美发美甲、教育培训、亲子游乐、家政洗涤维修、摄影写真等数十个服务消费细分领域，同时延伸至超市便利、美妆个护、3C数码、服饰珠宝、运动户外、商场购物中心等实体零售到店消费场景，连接数十万品牌商户与线下门店。作为商家和行业的小帮手，我们持续深入服务零售与实体零售产业链，用AI等技术推动行业变革，帮助商家提升经营效率、实现高效的线上化经营与到店转化，优化消费者服务体验，提供安心、放心的履约保障。这里有着多元的业务布局，有着富有挑战和影响力的工作内容，为你提供丰富的视野、持续的成长和发展机会，引领你发现更多可能。期待和你在“随时随地，美好生活”的愿景指引下，共建美好的生活服务体验、健康的商家生态与高质量的经营结果。\n\n岗位职责\n1.负责易生活行业（生活服务、摄影、教育等）用户决策信息建设、AI内容处理能力建设及上层应用落地，运用AI能力实现内容理解与生产的自动化闭环，驱动用户选店选品导购体验突破\n2.建立AI模型效果标准化评测体系，监控模型识别覆盖、准确率与召回率，持续驱动模型评测与迭代优化，提升各行业内容处理效果。\n3.协同联动算法、研发、运营等上下游资源，推动AI内容能力在搜索、供给、运营等业务环节落地，助力平台易生活行业内容生态长期建设。\n4.参与易生活行业AI产研新范式探索，运用AI辅助工具快速验证MVP，运用AI能力实现部分业务场景的自动化闭环。\n\n岗位基本要求\n1.本科及以上学历，具备2年以上C端产品经验，本地生活服务、电商或内容平台行业经验者优先；以用户体验为核心，逻辑清晰，具备优秀的结构化思维和快速学习能力，能通过数据分析定位问题、验证假设、衡量效果。\n2.强烈的Builder心态，喜欢动手做东西，不只是写PRD；具备AI Coding的实战经验，能熟练使用AI辅助工具快速验证产品方案。\n3.善于跨团队沟通协作，有良好的表达和沟通能力，能协同算法、研发、运营等上下游资源推动项目落地拿到结果。\n4.有韧性和责任心，对行业有热情，积极主动，能快速学习并在工作中持续寻求突破。\n\n具备以下条件优先\n1.对AI/LLM/Agent有深度理解和实操经验，理解大模型基础机制（上下文、幻觉、能力边界），能将模型局限性转化为产品决策依据。\n2.评测治理能力：熟悉智能化产品的评估方法论，具备数据标注方案制定、效果评估及模型迭代的闭环管理能力。\n3.AI技术转化经验：对AI/多模态技术有理解力，有图片内容理解、搜索推荐或相关AI产品落地经验，能将技术能力转化为产品方案。\n4.行业认知：有生活服务、摄影、教育、家居等易生活行业深度理解，对内容审美、用户决策路径有独立思考。\n\n岗位亮点\n1.直接服务于用户体验升级和商家供给效率提升两大业务目标，从底层AI模型评测到C端导购体验、B端内容生产，覆盖\"模型评测-产品设计-应用落地-效果验证\"全链路。\n2.技术资源：内部大模型能力、算力支持、工程团队配合，有机会参与多模态AI技术在易生活行业的前沿应用，积累丰富实战经验。\n3.通过工作实践提升AI领域综合能力，实现个人能力跃迁；团队日常深度使用AI工具，持续探索AI产研新范式实践。\n4.行业延展：岗位覆盖生活服务、摄影、教育、家居等易生活行业，可在实践中构建跨行业的深层认知体系，成长空间广阔。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4613752871","sourceKey":"meituan_social","company":"美团","title":"美团拼好饭-区域品牌采购专员","city":"郑州市/福州市/厦门市/合肥市/武汉市/长沙市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4613752871&jobShareType=1","duty":"职级：L5、L6\n基于目标清单，完成连锁品牌的招商引入与合作签约，主动建联品牌方KP、传递合作价值、达成入驻合作，建立并维护品牌方高层（供应链/外卖负责人）的长期合作关系；\n\n推动品牌方完成拼好饭模式的经营落地，识别经营中的核心问题，解决品牌方经营中的核心卡点，持续提升商品的市场表现和用户满意度；\n\n主动联动内部团队，推动品牌方商品策略在区域的落地执行，参与品牌方经营数据的复盘，协同多方团队优化商品成本和经营效率。","requirements":"具备连锁品牌招商拓展或餐饮行业商务谈判经验，能独立对接品牌方决策层；\n\n具备一定的数据分析能力和项目管理能力，能够通过数据分析诊断经营问题，协调资源推动问题的改善与解决，将单点优化沉淀为可复用的组织能力；\n\n对餐饮行业或本地生活业务有基本理解，了解品牌方经营的核心需求；\n\n诚信正直，自我驱动力强，愿意接受挑战，对工作结果交付具有责任心；\n\n具备AI学习意愿，能主动探索AI在工作场景中的应用。","description":"部门介绍\n美团外卖秉承“帮大家吃得更好，生活更好”的使命，始终聚焦于消费者用餐需求。我们通过科技连接消费者和商家，依托庞大的骑手团队，以“线上+线下”的业务模式，为消费者提供品质化、精细化、多样化的餐饮外卖服务。\n外卖事业部是为用户与商家提供全链路交易服务的业务组织，围绕餐饮外卖搭建了包含外卖业务与创新孵化业务在内的多个部门。\n我们的目标是帮助商家开源增收、提高经营效率，促进餐饮行业数字化，以及为更多用户提供更便捷更有品质的外卖服务。加入我们，一起为上亿用户提供更好的用餐体验，帮助大家吃得更好，生活更好！\n\n岗位职责\n职级：L5、L6\n基于目标清单，完成连锁品牌的招商引入与合作签约，主动建联品牌方KP、传递合作价值、达成入驻合作，建立并维护品牌方高层（供应链/外卖负责人）的长期合作关系；\n\n推动品牌方完成拼好饭模式的经营落地，识别经营中的核心问题，解决品牌方经营中的核心卡点，持续提升商品的市场表现和用户满意度；\n\n主动联动内部团队，推动品牌方商品策略在区域的落地执行，参与品牌方经营数据的复盘，协同多方团队优化商品成本和经营效率。\n\n岗位基本要求\n具备连锁品牌招商拓展或餐饮行业商务谈判经验，能独立对接品牌方决策层；\n\n具备一定的数据分析能力和项目管理能力，能够通过数据分析诊断经营问题，协调资源推动问题的改善与解决，将单点优化沉淀为可复用的组织能力；\n\n对餐饮行业或本地生活业务有基本理解，了解品牌方经营的核心需求；\n\n诚信正直，自我驱动力强，愿意接受挑战，对工作结果交付具有责任心；\n\n具备AI学习意愿，能主动探索AI在工作场景中的应用。\n\n岗位亮点\n深度参与品牌方经营，从采购到运营全链路操盘；\n\n配备前沿AI工具与资源，在AI时代持续提升竞争力、加速职业成长。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4683651623","sourceKey":"meituan_social","company":"美团","title":"生意保用户增长专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4683651623&jobShareType=1","duty":"1. 主导用户增长策略的制定与执行落地、对结果负责。\n2. 能从全局视角统筹各协同团队、善用AI工具，解决模糊问题。","requirements":"1. 不低于三年的金融、教育、医疗健康、商家相关业务用户增长相关经验，有投放、电销、企微、渠道运营相关经验优先。\n2. 对大模型、agent有较深理解，担任过运营、产品或核心开发者角色。\n3. 熟悉互联网用户运营方法论，具备在日常工作中熟练使用AI工具的能力，具备SQL能力，有业务sense，有成功的业务经验。\n4. 具备极强的自驱动力和极客精神。","description":"部门介绍\n美团金融服务平台成立于2016年，以“场景+金融”模式，携手合作伙伴构建开放生态，为美团平台用户和商户提供底层账户、支付通道、信贷、保险和理财等金融解决方案。我们致力于以科技为核心，助力金融机构打通金融普惠“最后一公里”。我们期待与大家共同完成每一件平凡而卓越的事情，一起为用户提供优质的产品体验，守护用户的资金安全，让生活变得更美好。\n\n岗位职责\n1. 主导用户增长策略的制定与执行落地、对结果负责。\n2. 能从全局视角统筹各协同团队、善用AI工具，解决模糊问题。\n\n岗位基本要求\n1. 不低于三年的金融、教育、医疗健康、商家相关业务用户增长相关经验，有投放、电销、企微、渠道运营相关经验优先。\n2. 对大模型、agent有较深理解，担任过运营、产品或核心开发者角色。\n3. 熟悉互联网用户运营方法论，具备在日常工作中熟练使用AI工具的能力，具备SQL能力，有业务sense，有成功的业务经验。\n4. 具备极强的自驱动力和极客精神。\n\n岗位亮点\n1. 高速发展业务，参与核心业务运营，直接影响产品用户规模与商业价值。\n2. 打造有商业化价值的金融AI应用能力，对AI的应用在保险行业前沿。\n3. 团队氛围好，业务发展快，有更好的空间接触全面的业务和成长。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4602206560","sourceKey":"meituan_social","company":"美团","title":"快乐猴-杭州片区经理","city":"杭州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4602206560&jobShareType=1","duty":"1、负责线下超市（大于10家门店）片区的日常运营管理工作，包括人员调配、库存管理、销售数据分析等，\n2、负责招聘、培训和管理团队成员，确保团队高效运作，\n3、负责制定并执行该片区门店的整体经营质量，多维度提升门店的营运效率。","requirements":"1、大学专科及以上学历，\n2、至少8年以上线下超市管理相关工作经验，如有较多新店开业经验的可适当放宽，\n3、具备较强的团队管理能力和沟通协调能力，能够有效领导团队实现业绩目标，\n4、具备良好的数据分析能力和解决问题能力，能够快速响应并解决运营中的问题。\n5、运用美团数字化运营工具辅助日常工作，借助AI分析工具提升决策质量，通过数据驱动方式持续优化工作效率和业务成果。","description":"部门介绍\n快乐猴是美团自营社区超市，依托自有供应链和门店管理体系，聚焦家庭用户的三餐所需，为消费者提供高质价比的食杂商品。快乐猴以数字化能力与科学品控为基础，不断满足消费者对“省”和“便利”的需求。\n\n岗位职责\n1、负责线下超市（大于10家门店）片区的日常运营管理工作，包括人员调配、库存管理、销售数据分析等，\n2、负责招聘、培训和管理团队成员，确保团队高效运作，\n3、负责制定并执行该片区门店的整体经营质量，多维度提升门店的营运效率。\n\n岗位基本要求\n1、大学专科及以上学历，\n2、至少8年以上线下超市管理相关工作经验，如有较多新店开业经验的可适当放宽，\n3、具备较强的团队管理能力和沟通协调能力，能够有效领导团队实现业绩目标，\n4、具备良好的数据分析能力和解决问题能力，能够快速响应并解决运营中的问题。\n5、运用美团数字化运营工具辅助日常工作，借助AI分析工具提升决策质量，通过数据驱动方式持续优化工作效率和业务成果。\n\n具备以下条件优先\n具备硬折扣相关业态片区管理工作经验优先。\n\n岗位亮点\n1、可以在快节奏的线下零售行业中展现个人管理能力和团队领导能力，\n2、有机会参与线下超市的整体运营策略规划和执行，实现个人职业发展和成长，\n3、薪资福利优厚，发展空间大，公司提供良好的培训和晋升机会。\n4、美团平台级资源支撑，让你的想法真正落地：跨BG的技术、数据、物流资源都可以为快乐猴后线体系建设服务，你不是单打独斗。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4646366965","sourceKey":"meituan_social","company":"美团","title":"运营策略","city":"广州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4646366965&jobShareType=1","duty":"1、深入理解共享出行行业特点和业务运营策略，参与运营体系的搭建、运营、评估及优化；\n2、负责电单车的供需诊断、调度策略、点位挖掘、责任田激励等策略制定及落地，及时复盘，为策略结果负责，不断提升骑行服务体验；\n3、通过数据发现业务中存在的问题及提升点，持续优化各模块逻辑，提升效率；\n4、不断挖掘产品需求，推动规则/标准的线上化；\n5、多维分析业务发展的趋势，及时发现存在的问题和机会，进行分析并给出预期诊断，提示可能性风险及策略方法，能够跨部门协调并推动优化项目。","requirements":"1、本科及以上学历，3年以上互联网工作经验，数学/统计/金融/经济/计算机专业背景优先；\n2、具备数据分析能力，能够运用统计学知识、数据分析工具等，深挖运营数据；\n3、拥有强烈的责任心和团队合作精神，出色的沟通协调能力。\n4、有推荐策略、搜索策略、补贴策略、供需策略、交易策略、策略投放平台等相关经验优先。","description":"部门介绍\n美团骑行事业部在全国各个城市开展美团单车、电单车业务，提供绿色、便捷的共享出行服务，是美团出行板块重要的组成部分。我们力求为城市可持续发展提供低碳智能的解决方案，通过技术创新和硬件升级，不断优化全流程骑行体验，为低碳出行提供更好的服务。其中，美团单车旨在为城市居民提供通勤接驳服务，满足用户短途接驳出行需求；美团电单车则满足用户中短途多场景低碳出行需求。\n我们有开放的工作氛围，也有充满韧劲和创造力，心系低碳出行的伙伴。加入我们，一起为用户创造更好的出行体验。\n\n岗位职责\n1、深入理解共享出行行业特点和业务运营策略，参与运营体系的搭建、运营、评估及优化；\n2、负责电单车的供需诊断、调度策略、点位挖掘、责任田激励等策略制定及落地，及时复盘，为策略结果负责，不断提升骑行服务体验；\n3、通过数据发现业务中存在的问题及提升点，持续优化各模块逻辑，提升效率；\n4、不断挖掘产品需求，推动规则/标准的线上化；\n5、多维分析业务发展的趋势，及时发现存在的问题和机会，进行分析并给出预期诊断，提示可能性风险及策略方法，能够跨部门协调并推动优化项目。\n\n岗位基本要求\n1、本科及以上学历，3年以上互联网工作经验，数学/统计/金融/经济/计算机专业背景优先；\n2、具备数据分析能力，能够运用统计学知识、数据分析工具等，深挖运营数据；\n3、拥有强烈的责任心和团队合作精神，出色的沟通协调能力。\n4、有推荐策略、搜索策略、补贴策略、供需策略、交易策略、策略投放平台等相关经验优先。\n\n岗位亮点\n加入我们，将让自己投入朝阳行业，这里业务复杂度高，将收获处理大型项目方法论的沉淀和个人能力成长，与优秀的人一起，追求卓越。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4192974374","sourceKey":"meituan_social","company":"美团","title":"无人车财务BP（硬件供应链&资产管理方向）","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4192974374&jobShareType=1","duty":"1、负责无人车业务硬件资产的财务预算、预测和分析等相关财务管理工作，为业务决策提供财务支持。\n2、负责管理无人车业务硬件资产现金流，监控现金流状况，编制现金流报告，并提出优化建议。\n3、负责硬件资产整个生命周期链路的管理，含业务支持和成本管控。\n4、负责资产处置策略和价格管理，提高资产处置效率和收益。\n5、负责资产和硬件供应链体系的建设和迭代；\n6、AI工具应用，主动将AI工具融入日常工作，使用Agent优化提效和增加产出，例如：工作流优化、数据处理与分析、报表/看板搭建、测算/分析模型搭建、项目管理、知识库建设。","requirements":"1、大学本科及以上学历，财务相关专业，具有硬件供应链管理&资产管理财务BP工作经验，有汽车、电池等相关行业背景优先。\n2、工作细致、严谨，具备独立思考和判断能力，具备优秀的分析能力，具备自驱的学习能力。\n3、具备优秀的沟通协调能力和团队合作精神，能够与不同角色和部门人员进行有效合作和项目推动。\n4、较强的问题解决能力，能够推动复杂问题和挑战任务的解决。","description":"部门介绍\n财务平台负责公司整体和各业务层面的财务管理工作，通过建设专业、全面、复合的财务管理能力和与业务经营的紧密结合来支持公司健康发展。目前财务平台拥有财务会计、财务报告、资金管理、税务管理、财务共享、财务系统、规划分析、财务BP和内控内审等主要工作方向。我们的目标是建设业界一流的财务管理能力和经营支持体系，为公司战略的正确落地、投入效率的持续提升、业务价值的不断增长保驾护航。欢迎加入财务平台，携手一起向未来！\n\n岗位职责\n1、负责无人车业务硬件资产的财务预算、预测和分析等相关财务管理工作，为业务决策提供财务支持。\n2、负责管理无人车业务硬件资产现金流，监控现金流状况，编制现金流报告，并提出优化建议。\n3、负责硬件资产整个生命周期链路的管理，含业务支持和成本管控。\n4、负责资产处置策略和价格管理，提高资产处置效率和收益。\n5、负责资产和硬件供应链体系的建设和迭代；\n6、AI工具应用，主动将AI工具融入日常工作，使用Agent优化提效和增加产出，例如：工作流优化、数据处理与分析、报表/看板搭建、测算/分析模型搭建、项目管理、知识库建设。\n\n岗位基本要求\n1、大学本科及以上学历，财务相关专业，具有硬件供应链管理&资产管理财务BP工作经验，有汽车、电池等相关行业背景优先。\n2、工作细致、严谨，具备独立思考和判断能力，具备优秀的分析能力，具备自驱的学习能力。\n3、具备优秀的沟通协调能力和团队合作精神，能够与不同角色和部门人员进行有效合作和项目推动。\n4、较强的问题解决能力，能够推动复杂问题和挑战任务的解决。\n\n岗位亮点\n1、无人车业务处于蓬勃发展的科技领域，行业发展快，作为财务BP可以深度参与业务发展中面临的高模糊度事项的研判中，亲手推动行业的发展，与业务一同成长。\n2、财务团队整体工作氛围好，以结果为导向，学习型团队，有助于专业能力提升，助力职业发展。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4566446957","sourceKey":"meituan_social","company":"美团","title":"AI产品-信贷方向","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4566446957&jobShareType=1","duty":"1. 负责以大模型技术为核心驱动力，重构信贷业务中风控审批、授信额度、利率定价等核心决策链路的产品方案设计与落地，将传统规则/模型驱动的决策体系升级为 AI 原生架构。\n\n2. 规划并推动用户全生命周期经营体系的智能化升级，覆盖获客、激活、授信、用信、留存、沉默唤醒等关键环节，通过大模型实现千人千策的精细化运营。\n\n3. 深入理解风控审批场景，设计 LLM 在非结构化数据解析、智能审核决策、欺诈识别辅助等方向的产品方案，推动审批效率与风险识别能力的同步提升。 \n\n4. 协同风控策略、算法、工程、运营等团队，定义 AI 能力与业务系统的集成方式，确保产品方案高质量落地并持续迭代。\n\n5. 建立数据驱动的产品评估体系，通过 A/B 实验、效果归因等手段，量化大模型对业务指标（通过率、坏账率、定价精度、用户LTV等）的实际贡献。","requirements":"1. 5年以上产品经理工作经验，其中至少2年信贷/金融风控相关产品经验，深入理解风控审批、额度策略、定价模型中至少一个领域的业务逻辑。 \n\n2. 具备 AI / 大模型产品落地经验，熟悉 LLM 基本原理、Context Engineering、Agent 等技术范式，能够判断技术边界并转化为可落地的产品方案。 \n\n3. 具备较强的数据分析能力，能够通过数据定义问题、验证假设、衡量产品效果；熟悉 A/B 实验设计与效果评估方法。 \n\n4. 具备优秀的结构化思维与复杂问题拆解能力，能够将模糊的业务诉求转化为清晰的产品路径。 \n\n5. 具备出色的跨团队沟通与项目推动能力，能够在算法、工程、风控、合规等多方之间高效协调。","description":"部门介绍\n美团金融服务平台成立于2016年，以“场景+金融”模式，携手合作伙伴构建开放生态，为美团平台用户和商户提供底层账户、支付通道、信贷、保险和理财等金融解决方案。我们致力于以科技为核心，助力金融机构打通金融普惠“最后一公里”。我们期待与大家共同完成每一件平凡而卓越的事情，一起为用户提供优质的产品体验，守护用户的资金安全，让生活变得更美好。\n\n岗位职责\n1. 负责以大模型技术为核心驱动力，重构信贷业务中风控审批、授信额度、利率定价等核心决策链路的产品方案设计与落地，将传统规则/模型驱动的决策体系升级为 AI 原生架构。\n\n2. 规划并推动用户全生命周期经营体系的智能化升级，覆盖获客、激活、授信、用信、留存、沉默唤醒等关键环节，通过大模型实现千人千策的精细化运营。\n\n3. 深入理解风控审批场景，设计 LLM 在非结构化数据解析、智能审核决策、欺诈识别辅助等方向的产品方案，推动审批效率与风险识别能力的同步提升。 \n\n4. 协同风控策略、算法、工程、运营等团队，定义 AI 能力与业务系统的集成方式，确保产品方案高质量落地并持续迭代。\n\n5. 建立数据驱动的产品评估体系，通过 A/B 实验、效果归因等手段，量化大模型对业务指标（通过率、坏账率、定价精度、用户LTV等）的实际贡献。\n\n岗位基本要求\n1. 5年以上产品经理工作经验，其中至少2年信贷/金融风控相关产品经验，深入理解风控审批、额度策略、定价模型中至少一个领域的业务逻辑。 \n\n2. 具备 AI / 大模型产品落地经验，熟悉 LLM 基本原理、Context Engineering、Agent 等技术范式，能够判断技术边界并转化为可落地的产品方案。 \n\n3. 具备较强的数据分析能力，能够通过数据定义问题、验证假设、衡量产品效果；熟悉 A/B 实验设计与效果评估方法。 \n\n4. 具备优秀的结构化思维与复杂问题拆解能力，能够将模糊的业务诉求转化为清晰的产品路径。 \n\n5. 具备出色的跨团队沟通与项目推动能力，能够在算法、工程、风控、合规等多方之间高效协调。\n\n岗位亮点\n1. 以大模型重构信贷核心决策链路，这是行业级别的范式变革机会——你将定义 AI 原生金融产品的标准形态。 \n\n2. 平台资源丰富（海量真实金融数据、充足算力、成熟的模型基建），支持快速验证与规模化落地。 \n\n3. 团队技术氛围浓厚，鼓励从产品视角驱动技术创新，拥有充分的自主决策空间。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4666029131","sourceKey":"meituan_social","company":"美团","title":"SMB BD - Account Executive/Management EXTRA HC","city":"圣保罗","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4666029131&jobShareType=1","duty":"1. Responsible for expanding the customer base of small and medium-sized enterprises (SMEs) in the São Paulo area, establishing and maintaining customer relationships. 2. Promote company products and services through telephone, email, and face-to-face visits to achieve sales targets. 3. Analyze customer needs, provide customized solutions, and drive contract signing and order conversion. 4. Collaborate with the marketing and product teams to collect customer feedback and optimize sales strategies.","requirements":"1. Associate's degree or equivalent. 2. At least one year of experience in business development or customer management, with B2B sales background preferred. 3. Excellent communication and negotiation skills, able to work independently. 4. Proficient in office software and possess basic English reading and writing skills.","description":"部门介绍\nKeeta是全球领先外卖平台美团旗下的独立品牌，肩负着“帮大家吃得更好，生活更好”的使命。依托美团深耕中国市场15年的技术与运营积淀，我们正引领全球餐饮与商品即时配送服务的创新与发展。\n\n自2023年成立以来，Keeta始终扎根社区并创造价值。我们为用户提供可靠的外卖体验，以智慧技术助餐厅提升经营效率，在为骑手拓宽收入来源的同时，也充分提供安全保障措施。基于这份多方共赢、共同成长的理念，我们的业务已从中国香港稳步拓展至中东及巴西，并持续向世界迈进。\n\n岗位职责\n1. Responsible for expanding the customer base of small and medium-sized enterprises (SMEs) in the São Paulo area, establishing and maintaining customer relationships. 2. Promote company products and services through telephone, email, and face-to-face visits to achieve sales targets. 3. Analyze customer needs, provide customized solutions, and drive contract signing and order conversion. 4. Collaborate with the marketing and product teams to collect customer feedback and optimize sales strategies.\n\n岗位基本要求\n1. Associate's degree or equivalent. 2. At least one year of experience in business development or customer management, with B2B sales background preferred. 3. Excellent communication and negotiation skills, able to work independently. 4. Proficient in office software and possess basic English reading and writing skills.\n\n岗位亮点\n1. Join a rapidly growing international team and gain ample opportunities for career growth. 2. We provide systematic sales training and a clear career advancement path. 3. The work location is conveniently situated in the heart of São Paulo's business district. 4. Enjoy a competitive compensation structure and performance bonuses.","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4434676135","sourceKey":"meituan_social","company":"美团","title":"快乐猴-东莞店长","city":"东莞市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4434676135&jobShareType=1","duty":"1.负责线下门店的日常运营管理，确保公司营运标准高效在门店落地，提升销售、毛利和客户满意度；\n2.负责团队的招聘、培训和绩效管理，确保团队的稳定和高效运作；\n3.管控店内损耗、提升门店人效，优化可控费用（如物料，水电煤等营运费用），达成主要考核KPI；\n4.对内各协同部门的日常高效交互，达成共识，高效执行总部和区域新项目落地；\n5.对外关系的建立维护，如相关政府职能部门（市场管理、消协等）、物业关系，打造协作融洽的合作伙伴。","requirements":"1.大学专科及以上学历。\n2.至少3年以上线下门店营运管理领域工作经验。\n3.具有良好的团队管理能力、沟通能力和问题解决能力。\n4.具有较强的数据分析能力和业务推动能力，能够制定有效的运营策略和改进方案。\n5.具有责任心，能够独立思考和独立工作。\n6.掌握基本的AI工具，使用工具提升工作流程效率。","description":"部门介绍\n快乐猴是美团自营社区超市，依托自有供应链和门店管理体系，聚焦家庭用户的三餐所需，为消费者提供高质价比的食杂商品。快乐猴以数字化能力与科学品控为基础，不断满足消费者对“省”和“便利”的需求。\n\n岗位职责\n1.负责线下门店的日常运营管理，确保公司营运标准高效在门店落地，提升销售、毛利和客户满意度；\n2.负责团队的招聘、培训和绩效管理，确保团队的稳定和高效运作；\n3.管控店内损耗、提升门店人效，优化可控费用（如物料，水电煤等营运费用），达成主要考核KPI；\n4.对内各协同部门的日常高效交互，达成共识，高效执行总部和区域新项目落地；\n5.对外关系的建立维护，如相关政府职能部门（市场管理、消协等）、物业关系，打造协作融洽的合作伙伴。\n\n岗位基本要求\n1.大学专科及以上学历。\n2.至少3年以上线下门店营运管理领域工作经验。\n3.具有良好的团队管理能力、沟通能力和问题解决能力。\n4.具有较强的数据分析能力和业务推动能力，能够制定有效的运营策略和改进方案。\n5.具有责任心，能够独立思考和独立工作。\n6.掌握基本的AI工具，使用工具提升工作流程效率。\n\n岗位亮点\n1.提供丰富的线下门店管理经验和团队管理经验的机会。\n2.提供良好的职业发展空间和晋升机会，能够在公司内部快速成长。\n3.薪资福利优厚，公司提供完善的培训体系和职业发展计划，帮助员工实现个人职业目标。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4439056014","sourceKey":"meituan_social","company":"美团","title":"美团骑行-区域负责人（多地可base）","city":"北京市/上海市/广州市/深圳市/成都市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4439056014&jobShareType=1","duty":"1、目标及策略的制定和执行：熟悉行业运营环境及竞争情况，且能够识别增量机会及存量风险，制定有利业务短、中长期的打法策略和目标；\n2、经营及成本管理：熟悉区域经营数据，调控区域收入与支出，分析成本结构并有优化路径，对降本增效进行有效落地；\n3、车辆及用户运营管理：负责车辆的整体运维工作，优化运营动作，迭代业务流程，提升车辆运营效率，并实现资产安全；\n4、团队管理：搭建经营型团队并做好日常管理，优化人才培养梯队、共识团队目标并有监督落地执行；\n5、治理者服务：建立良好的政企关系，协助治理者制定行业管理办法，做好治理者需求响应，拆解管理考核要求并高标准兑现；\n6、整体协同：做好和骑行内各部门之间的协同工作，以经营整体视角解决经营过程中出现的问题。","requirements":"1、本科及以上学历，5年以上团队管理经验，善于用开拓性思维解决问题；\n2、有快消品区域覆盖或互联网城市地推管理经验者优先；\n3、善于数据分析，并能通过数据分析的结果不断优化调整工作。 \n4、接受区域调配者优先。","description":"部门介绍\n美团骑行事业部在全国各个城市开展美团单车、电单车业务，提供绿色、便捷的共享出行服务，是美团出行板块重要的组成部分。我们力求为城市可持续发展提供低碳智能的解决方案，通过技术创新和硬件升级，不断优化全流程骑行体验，为低碳出行提供更好的服务。其中，美团单车旨在为城市居民提供通勤接驳服务，满足用户短途接驳出行需求；美团电单车则满足用户中短途多场景低碳出行需求。\n我们有开放的工作氛围，也有充满韧劲和创造力，心系低碳出行的伙伴。加入我们，一起为用户创造更好的出行体验。\n\n岗位职责\n1、目标及策略的制定和执行：熟悉行业运营环境及竞争情况，且能够识别增量机会及存量风险，制定有利业务短、中长期的打法策略和目标；\n2、经营及成本管理：熟悉区域经营数据，调控区域收入与支出，分析成本结构并有优化路径，对降本增效进行有效落地；\n3、车辆及用户运营管理：负责车辆的整体运维工作，优化运营动作，迭代业务流程，提升车辆运营效率，并实现资产安全；\n4、团队管理：搭建经营型团队并做好日常管理，优化人才培养梯队、共识团队目标并有监督落地执行；\n5、治理者服务：建立良好的政企关系，协助治理者制定行业管理办法，做好治理者需求响应，拆解管理考核要求并高标准兑现；\n6、整体协同：做好和骑行内各部门之间的协同工作，以经营整体视角解决经营过程中出现的问题。\n\n岗位基本要求\n1、本科及以上学历，5年以上团队管理经验，善于用开拓性思维解决问题；\n2、有快消品区域覆盖或互联网城市地推管理经验者优先；\n3、善于数据分析，并能通过数据分析的结果不断优化调整工作。 \n4、接受区域调配者优先。\n\n具备以下条件优先\n外卖，共享出行、快消、物流、互联网相关\n\n岗位亮点\n美团单车是美团出行板块重要的组成部份。我们有清晰完善的晋升机制和通道，开放扁平的工作氛围。期待你的加入，与优秀的人共事，一起见证美团单车的重要时刻。发展空间大，长链条复杂业务，提升开拓性思维解决问题能力和互联网思维","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4668026532","sourceKey":"meituan_social","company":"美团","title":"海外风险治理专家","city":"利雅得","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4668026532&jobShareType=1","duty":"1、负责站配业务全链路风险治理，联动风控、运营、稽查等开展风险识别、风险预警及专项治理，建立风险管理闭环，保障业务合规稳定运营。\n2、负责各类违规、舞弊及合规调查，通过专业、合法、合规的方式开展调查，制定调查方案，完成证据收集、责任认定、调查报告输出及整改闭环，惩治违规违纪行为，挽回公司损失。\n3、负责配合总部开展各类专项调查及风险治理项目，识别业务经营风险、管理漏洞及廉洁风险，推动制度优化及流程改善，提升城市整体风险防控能力。\n4、负责城市各类突发事件、运营事故及重大异常事件调查，完成原因分析、责任认定及整改跟踪，保障业务正常经营秩序。\n5、负责组织开展城市合规、廉政及反舞弊培训宣导，持续提升员工合规意识和廉洁从业意识，推动廉洁文化建设。","requirements":"1、五年以上合规、内控、监察、反舞弊、风险治理、资产保护等相关工作经验，具备风险识别、调查方案制定、证据收集、违规调查、责任认定、调查报告撰写及整改闭环能力。\n2、熟悉物流、仓储、即时零售或配送业务流程，具备较强的风险意识，能够识别运营风险、舞弊风险及衍生风险，并推动风险治理。\n3、熟悉调查取证流程，具备数据分析、现场调查、视频核查、人员访谈等调查能力，能够独立完成复杂的违规调查。\n4、具备较强的观察、判断、分析及解决问题能力，良好的跨部门沟通协调能力及执行力。\n5、正直诚信，责任心强，坚持原则，具备良好的职业操守和保密意识。\n6、英语可作为工作语言。","description":"部门介绍\n美团的使命是“帮大家吃得更好，生活更好”，公司聚焦“零售 + 科技”战略，和广大商户与各类合作伙伴一起，努力为消费者提供品质生活，推动商品零售和服务零售在需求侧和供给侧的数字化转型。\n2018年9月20日，美团正式在港交所挂牌上市。美团将始终坚持以客户为中心，不断加大在科技研发方面的投入，更好承担社会责任，更多创造社会价值，与广大合作伙伴一起发展共赢。\n\n岗位职责\n1、负责站配业务全链路风险治理，联动风控、运营、稽查等开展风险识别、风险预警及专项治理，建立风险管理闭环，保障业务合规稳定运营。\n2、负责各类违规、舞弊及合规调查，通过专业、合法、合规的方式开展调查，制定调查方案，完成证据收集、责任认定、调查报告输出及整改闭环，惩治违规违纪行为，挽回公司损失。\n3、负责配合总部开展各类专项调查及风险治理项目，识别业务经营风险、管理漏洞及廉洁风险，推动制度优化及流程改善，提升城市整体风险防控能力。\n4、负责城市各类突发事件、运营事故及重大异常事件调查，完成原因分析、责任认定及整改跟踪，保障业务正常经营秩序。\n5、负责组织开展城市合规、廉政及反舞弊培训宣导，持续提升员工合规意识和廉洁从业意识，推动廉洁文化建设。\n\n岗位基本要求\n1、五年以上合规、内控、监察、反舞弊、风险治理、资产保护等相关工作经验，具备风险识别、调查方案制定、证据收集、违规调查、责任认定、调查报告撰写及整改闭环能力。\n2、熟悉物流、仓储、即时零售或配送业务流程，具备较强的风险意识，能够识别运营风险、舞弊风险及衍生风险，并推动风险治理。\n3、熟悉调查取证流程，具备数据分析、现场调查、视频核查、人员访谈等调查能力，能够独立完成复杂的违规调查。\n4、具备较强的观察、判断、分析及解决问题能力，良好的跨部门沟通协调能力及执行力。\n5、正直诚信，责任心强，坚持原则，具备良好的职业操守和保密意识。\n6、英语可作为工作语言。\n\n岗位亮点\n1、深度参与海外站配业务全链路风险治理体系建设，覆盖站配等核心业务场景。\n2、与总部风控及合规团队协同开展专项调查及风险治理项目，参与海外业务风险管理体系建设。\n3、国际化业务平台，团队专业，氛围良好，能够持续提升风险治理及监察调查专业能力。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4431928848","sourceKey":"meituan_social","company":"美团","title":"医美SKA美莱组-大客户销售","city":"广州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4431928848&jobShareType=1","duty":"1. 负责美莱华北、华东、华南区域的机构的平台合作与客户关系维护，制定并执行销售策略，达成业绩目标。  \n2. 深度挖掘客户需求，提供定制化经营方案，提升客户满意度与长期合作粘性。  \n3. 协调内部资源，推动跨部门协作，确保项目高效落地与客户服务体验优化。  \n4. 定期分析市场动态与竞争对手情况，输出行业洞察报告，支持业务决策。","requirements":"1. 大学本科及以上学历，市场营销、医学、管理类相关专业优先。  \n2. 具备3年以上大客户销售经验，有医美、医疗健康或高端服务行业背景者优先。  \n3. 具备优秀的商务谈判能力与客户关系管理能力，交付结果能力强。  \n4. 熟悉北京地区医美市场，拥有良好的客户资源者优先。","description":"部门介绍\n美团医药健康事业部是美团核心本地商业板块下专注健康领域的业务部门，涵盖美团买药、美团医美和美团医疗三大业务。自创立以来，美团医药健康致力于为用户提供全健康周期产品及服务，满足人民群众多层次多元化医疗健康需求，现已覆盖购药到家、居家检测、问诊挂号、医保支付、求医寻院、医疗美容等核心场景。此外，美团医药健康还为商户提供数字化转型创新解决方案，打造贯穿上游的联动机制，长期参与共建更透明、更可持续的医药健康产业生态圈，目前业务已覆盖25万家药店，收录27万家医疗机构。未来，美团医药康将协同更多行业伙伴，帮助大家变得更健康、更美丽、更养生。\n\n岗位职责\n1. 负责美莱华北、华东、华南区域的机构的平台合作与客户关系维护，制定并执行销售策略，达成业绩目标。  \n2. 深度挖掘客户需求，提供定制化经营方案，提升客户满意度与长期合作粘性。  \n3. 协调内部资源，推动跨部门协作，确保项目高效落地与客户服务体验优化。  \n4. 定期分析市场动态与竞争对手情况，输出行业洞察报告，支持业务决策。\n\n岗位基本要求\n1. 大学本科及以上学历，市场营销、医学、管理类相关专业优先。  \n2. 具备3年以上大客户销售经验，有医美、医疗健康或高端服务行业背景者优先。  \n3. 具备优秀的商务谈判能力与客户关系管理能力，交付结果能力强。  \n4. 熟悉北京地区医美市场，拥有良好的客户资源者优先。\n\n岗位亮点\n1. 服务国内较大规模医美B端客户，平台资源丰富，发展空间广阔。  \n2. 深度了解医美行业和医美机构经营链路，探索新周期下的创新合作模式。\n3. 具备竞争力的薪酬体系与完善的培训发展机制，团队协作氛围佳，支持个人快速成长。\n4. 工作地点位于北京核心区域，办公环境优越。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4692070491","sourceKey":"meituan_social","company":"美团","title":"零售财务BP-物流财务BP","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4692070491&jobShareType=1","duty":"物流方向财务BP，为业务提供决策支持和风险提示：\n1、物流成本分析，目标实现路径挖掘及价值落地追踪；\n2、物流行业调研及对标分析；\n3、物流业务变革项目追踪，价值复盘及风险提示；\n4、年度预算、滚动预测等日常分析监控。","requirements":"1、有物流行业相关经验，对物流成本分析有一定的积累；\n2、优秀的思维逻辑能力和业务敏感度，深潜业务发现机会点；\n3、拥有自驱力和好奇心，能够主动发现问题并交付结果。\n4.   熟练使用SQL、Power BI、AI工具等数据分析工具者优先。","description":"部门介绍\n财务平台负责公司整体和各业务层面的财务管理工作，通过建设专业、全面、复合的财务管理能力和与业务经营的紧密结合来支持公司健康发展。目前财务平台拥有财务会计、财务报告、资金管理、税务管理、财务共享、财务系统、规划分析、财务BP和内控内审等主要工作方向。我们的目标是建设业界一流的财务管理能力和经营支持体系，为公司战略的正确落地、投入效率的持续提升、业务价值的不断增长保驾护航。欢迎加入财务平台，携手一起向未来！\n\n岗位职责\n物流方向财务BP，为业务提供决策支持和风险提示：\n1、物流成本分析，目标实现路径挖掘及价值落地追踪；\n2、物流行业调研及对标分析；\n3、物流业务变革项目追踪，价值复盘及风险提示；\n4、年度预算、滚动预测等日常分析监控。\n\n岗位基本要求\n1、有物流行业相关经验，对物流成本分析有一定的积累；\n2、优秀的思维逻辑能力和业务敏感度，深潜业务发现机会点；\n3、拥有自驱力和好奇心，能够主动发现问题并交付结果。\n4.   熟练使用SQL、Power BI、AI工具等数据分析工具者优先。\n\n岗位亮点\n1. 公司重点投入的新业务，深度参与业务创始阶段战略制定过程，发挥财务价值引领作用。  \n2. 与业务团队紧密协作，快速积累行业洞察与实战经验。  \n3. 团队氛围很好，简单直接灵活，开放包容，鼓励创新。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4695274606","sourceKey":"meituan_social","company":"美团","title":"拼好饭-新供给二组-供应链管理","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4695274606&jobShareType=1","duty":"1. 责拼好饭新供给供应链体系整体规划与顶层设计，制定中长期供应链发展战略与年度经营计划。\n2. 搭建供应链全景视图，覆盖供应商管理、采购策略、需求计划、履约链路等核心环节，识别瓶颈并推动端到端优化。\n3. 制定供应链成本与效率目标，驱动采购成本下降、周转效率提升及履约质量改善，构建可持续的供应链竞争力。\n4. 关注行业趋势与竞争格局，输出供应链战略洞察报告，为业务方向决策提供依据。\n5. 主导需求计划体系搭建，建立从业务前端到供应链后端的需求数据流转与预测机制，提升需求预测准确性。\n6. 深度分析商品供需数据，制定差异化的库存策略与补货逻辑，在缺货与滞销之间找到最优平衡点。\n7. 建立跨部门供需协同机制，打通产品、运营、采购与供应商之间的信息链路，实现需求变更的快速响应与闭环管理。\n8. 主导供应链数字化建设，规划并推动采购管理、需求计划、供应商协同、数据看板等系统模块的搭建与迭代。\n9. 梳理并标准化供应链核心业务流程（SOP），推动流程的系统化落地，减少人工干预，提升规模化承载能力。\n10. 建立供应链数据指标体系，监控关键指标表现，定期输出分析报告，为业务决策提供数据支持。\n11. 探索智能补货、需求预测算法、自动化审批等前沿技术在供应链场景的落地，推动供应链从信息化走向智能化。","requirements":"1. 本科及以上学历，供应链管理、物流工程、统计学等相关专业优先；\n2. 5年以上供应链管理经验，有餐饮/食品行业供应链规划或需求管理经验者优先；\n3. 熟悉供应链计划体系（S&OP、需求预测、库存计划），具备从0到1搭建供应链流程或系统的实战经验；\n4. 数据分析能力强，熟练使用数据可视化工具，能独立完成供需分析、成本拆解与建模；\n5. 了解主流供应链系统（ERP/SRM/计划系统），有系统搭建或产品化经验者优先。\n6. 具备全局视角和系统性思维，能在复杂业务环境中识别关键矛盾并给出优先级判断；\n7. 跨部门协同与推动能力强，能在产品、运营、供应商等多方之间有效对齐目标并推动落地；","description":"部门介绍\n美团外卖秉承“帮大家吃得更好，生活更好”的使命，始终聚焦于消费者用餐需求。我们通过科技连接消费者和商家，依托庞大的骑手团队，以“线上+线下”的业务模式，为消费者提供品质化、精细化、多样化的餐饮外卖服务。\n外卖事业部是为用户与商家提供全链路交易服务的业务组织，围绕餐饮外卖搭建了包含外卖业务与创新孵化业务在内的多个部门。\n我们的目标是帮助商家开源增收、提高经营效率，促进餐饮行业数字化，以及为更多用户提供更便捷更有品质的外卖服务。加入我们，一起为上亿用户提供更好的用餐体验，帮助大家吃得更好，生活更好！\n\n岗位职责\n1. 责拼好饭新供给供应链体系整体规划与顶层设计，制定中长期供应链发展战略与年度经营计划。\n2. 搭建供应链全景视图，覆盖供应商管理、采购策略、需求计划、履约链路等核心环节，识别瓶颈并推动端到端优化。\n3. 制定供应链成本与效率目标，驱动采购成本下降、周转效率提升及履约质量改善，构建可持续的供应链竞争力。\n4. 关注行业趋势与竞争格局，输出供应链战略洞察报告，为业务方向决策提供依据。\n5. 主导需求计划体系搭建，建立从业务前端到供应链后端的需求数据流转与预测机制，提升需求预测准确性。\n6. 深度分析商品供需数据，制定差异化的库存策略与补货逻辑，在缺货与滞销之间找到最优平衡点。\n7. 建立跨部门供需协同机制，打通产品、运营、采购与供应商之间的信息链路，实现需求变更的快速响应与闭环管理。\n8. 主导供应链数字化建设，规划并推动采购管理、需求计划、供应商协同、数据看板等系统模块的搭建与迭代。\n9. 梳理并标准化供应链核心业务流程（SOP），推动流程的系统化落地，减少人工干预，提升规模化承载能力。\n10. 建立供应链数据指标体系，监控关键指标表现，定期输出分析报告，为业务决策提供数据支持。\n11. 探索智能补货、需求预测算法、自动化审批等前沿技术在供应链场景的落地，推动供应链从信息化走向智能化。\n\n岗位基本要求\n1. 本科及以上学历，供应链管理、物流工程、统计学等相关专业优先；\n2. 5年以上供应链管理经验，有餐饮/食品行业供应链规划或需求管理经验者优先；\n3. 熟悉供应链计划体系（S&OP、需求预测、库存计划），具备从0到1搭建供应链流程或系统的实战经验；\n4. 数据分析能力强，熟练使用数据可视化工具，能独立完成供需分析、成本拆解与建模；\n5. 了解主流供应链系统（ERP/SRM/计划系统），有系统搭建或产品化经验者优先。\n6. 具备全局视角和系统性思维，能在复杂业务环境中识别关键矛盾并给出优先级判断；\n7. 跨部门协同与推动能力强，能在产品、运营、供应商等多方之间有效对齐目标并推动落地；\n\n岗位亮点\n1. 参与创新业务模式探索，在快速发展的本地生活平台中发挥关键作用。  \n2. 与行业优秀团队共事，获得丰富的实战经验与职业成长机会。  \n3. 扁平化管理氛围，鼓励创新与主动担当，提供广阔的发展空间。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4641199827","sourceKey":"meituan_social","company":"美团","title":"产教业务发展专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4641199827&jobShareType=1","duty":"1.主导公司对高校产教融合服务方案的标准化设计，打磨核心产品能力，建立可复制的交付模型；\n2.建立从签约到交付的 SOP 体系，输出培训材料和作战手册，赋能团队交付能力；\n3.深入高校和产业侧，梳理产教融合核心价值主张，持续迭代产品，持续提升产品力；\n4.推动代理商/合作方渠道体系建设，探索规模化分销路径，明确合作条件及激励机制；\n5.梳理教育主管部门政策指导方向，持续迭代行业解决方案，推动客户决策效率；\n6.协助团队负责人制定产教发展路径，跟进标杆案例落地，输出竞争策略建议。","requirements":"1.本科及以上学历，5 年以上产教融合/职业教育/B 端教育服务从业经验；\n2.有完整的产品/服务方案从 0 到 1 设计并落地经历，有交付标准化建设经验；\n3.逻辑清晰，能结构化表达，能独立撰写和汇报解决方案；\n4.可独立推动跨部门协作，擅长在模糊中定义及解决问题。","description":"部门介绍\n美团外卖秉承“帮大家吃得更好，生活更好”的使命，始终聚焦于消费者用餐需求。我们通过科技连接消费者和商家，依托庞大的骑手团队，以“线上+线下”的业务模式，为消费者提供品质化、精细化、多样化的餐饮外卖服务。\n外卖事业部是为用户与商家提供全链路交易服务的业务组织，围绕餐饮外卖搭建了包含外卖业务与创新孵化业务在内的多个部门。\n我们的目标是帮助商家开源增收、提高经营效率，促进餐饮行业数字化，以及为更多用户提供更便捷更有品质的外卖服务。加入我们，一起为上亿用户提供更好的用餐体验，帮助大家吃得更好，生活更好！\n\n岗位职责\n1.主导公司对高校产教融合服务方案的标准化设计，打磨核心产品能力，建立可复制的交付模型；\n2.建立从签约到交付的 SOP 体系，输出培训材料和作战手册，赋能团队交付能力；\n3.深入高校和产业侧，梳理产教融合核心价值主张，持续迭代产品，持续提升产品力；\n4.推动代理商/合作方渠道体系建设，探索规模化分销路径，明确合作条件及激励机制；\n5.梳理教育主管部门政策指导方向，持续迭代行业解决方案，推动客户决策效率；\n6.协助团队负责人制定产教发展路径，跟进标杆案例落地，输出竞争策略建议。\n\n岗位基本要求\n1.本科及以上学历，5 年以上产教融合/职业教育/B 端教育服务从业经验；\n2.有完整的产品/服务方案从 0 到 1 设计并落地经历，有交付标准化建设经验；\n3.逻辑清晰，能结构化表达，能独立撰写和汇报解决方案；\n4.可独立推动跨部门协作，擅长在模糊中定义及解决问题。\n\n具备以下条件优先\n1. 有成熟的校企合作方向工作经验；\n2. 有各教育相关组织的资源或对接经验；\n3. 有代理商/合作方渠道拓展及管理经验；\n4. 有职教SaaS公司或职业培训机构背景。\n\n岗位亮点\n1. 产教融合资源投入充分，业务优先级高\n2. 依托美团品牌和平台资源，能撬动头部高校资源\n3. 参与从0到1跑通产教模式的过程，成功即为标杆案例","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4155307204","sourceKey":"meituan_social","company":"美团","title":"【医药健康】医美和美容产品运营","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4155307204&jobShareType=1","duty":"1、负责美容和医美核心路径选品选店的产品优化，提升搜索、货架、商品页、订单页等关键页面的导购效率。有业务视角，能从复杂的业务场景中挖掘用户决策痛点和本质需求，发现体验机会点，制定产品策略\n\n2、数据驱动，基于业务数据现状及用户分析，持续发现业务和用户主交易链路和购后服务流程的优化点，不断优化产品运营效果\n\n3、能高效协同上下游及横向团队，推动产品方案落地、复盘及制定下一步迭代策略","requirements":"1. 3年以上C端产品或产运经验，有消费医疗、医美行业领域经验者优先；\n2. 以用户为中心，对用户需求洞察和C端产品有充足经验，能了解用户消费决策因素，对垂类领域有深入研究加分。\n3.具备运营策略输出能力、项目管理能力，具备良好的沟通界面，能通过沟通协调前后线、产研资源推动项目落地及目标达成；","description":"部门介绍\n美团医药健康事业部是美团核心本地商业板块下专注健康领域的业务部门，涵盖美团买药、美团医美和美团医疗三大业务。自创立以来，美团医药健康致力于为用户提供全健康周期产品及服务，满足人民群众多层次多元化医疗健康需求，现已覆盖购药到家、居家检测、问诊挂号、医保支付、求医寻院、医疗美容等核心场景。此外，美团医药健康还为商户提供数字化转型创新解决方案，打造贯穿上游的联动机制，长期参与共建更透明、更可持续的医药健康产业生态圈，目前业务已覆盖25万家药店，收录27万家医疗机构。未来，美团医药康将协同更多行业伙伴，帮助大家变得更健康、更美丽、更养生。\n\n岗位职责\n1、负责美容和医美核心路径选品选店的产品优化，提升搜索、货架、商品页、订单页等关键页面的导购效率。有业务视角，能从复杂的业务场景中挖掘用户决策痛点和本质需求，发现体验机会点，制定产品策略\n\n2、数据驱动，基于业务数据现状及用户分析，持续发现业务和用户主交易链路和购后服务流程的优化点，不断优化产品运营效果\n\n3、能高效协同上下游及横向团队，推动产品方案落地、复盘及制定下一步迭代策略\n\n岗位基本要求\n1. 3年以上C端产品或产运经验，有消费医疗、医美行业领域经验者优先；\n2. 以用户为中心，对用户需求洞察和C端产品有充足经验，能了解用户消费决策因素，对垂类领域有深入研究加分。\n3.具备运营策略输出能力、项目管理能力，具备良好的沟通界面，能通过沟通协调前后线、产研资源推动项目落地及目标达成；\n\n岗位亮点\n团队氛围开放务实，可以在学习型团队中成长\n可以独立负责从0-1的产品项目，用产品迭代解决把用户体验问题","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:2971035554","sourceKey":"meituan_social","company":"美团","title":"高级开发工程师-工程效能方向","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=2971035554&jobShareType=1","duty":"1. 负责公司级研发效能平台和工具的建设，包括但不限于构建平台、发布平台、测试平台、代码平台、流水线平台等；\n2. 参与公司级研发交付流程的制定与优化，深度了解业务研发场景，提供一站式、全流程的解决方案；\n3. 把控整体项目进度，负责核心模块的技术演进和产品迭代。","requirements":"1.本科及以上学历，计算机相关专业，4年以上大型互联网公司开发经验；\n2.精通至少一门主流编程语言（如Java/Python/Go等），具备扎实的编码能力和系统设计能力；\n3.有 DevOps 落地实践经验，熟悉CI/CD、自动化测试、代码质量管理等工程效能相关技术；\n4.良好的沟通能力和团队协作精神，能够独立承担复杂模块的开发与优化工作；\n5. 拥抱 AI Coding，熟悉 AI Coding 工具的应用与集成，有AI辅助开发实践经验者优先。","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n1. 负责公司级研发效能平台和工具的建设，包括但不限于构建平台、发布平台、测试平台、代码平台、流水线平台等；\n2. 参与公司级研发交付流程的制定与优化，深度了解业务研发场景，提供一站式、全流程的解决方案；\n3. 把控整体项目进度，负责核心模块的技术演进和产品迭代。\n\n岗位基本要求\n1.本科及以上学历，计算机相关专业，4年以上大型互联网公司开发经验；\n2.精通至少一门主流编程语言（如Java/Python/Go等），具备扎实的编码能力和系统设计能力；\n3.有 DevOps 落地实践经验，熟悉CI/CD、自动化测试、代码质量管理等工程效能相关技术；\n4.良好的沟通能力和团队协作精神，能够独立承担复杂模块的开发与优化工作；\n5. 拥抱 AI Coding，熟悉 AI Coding 工具的应用与集成，有AI辅助开发实践经验者优先。\n\n具备以下条件优先\n1.有在实践 DevOps 团队中的工作经验，熟悉 Kubernetes、Docker、Gitlab、Artifactory、Jenkins 等开源工具的开发和使用；\n2.了解前端、服务端、移动端的研发流程，有相关工具或平台开发经验者优先；\n3.具有良好的产品思维能力的开发者优先。\n\n岗位亮点\n1.面向美团大规模的工程师团队，探索并建设支持万级别工程师协同开发的研发平台及工具链，成为服务端/移动端/工程效能领域技术专家；\n2.业务和团队积极拥抱AI 大模型，已有多个研发工具场景落地，有机会和团队一起在这个技术变革点上做点不一样的东西；\n3.极具产品、技术和应用挑战，和公司内多个业务及平台部门的技术专家们深度合作交流；\n4.充分发挥基础技术的杠杆作用，以高可扩展性平台满足复杂多样的业务与技术需求，支撑并驱动业务快速发展迭代。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4693576606","sourceKey":"meituan_social","company":"美团","title":"金服财务运营（支付）","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4693576606&jobShareType=1","duty":"1. 负责对接支付业务财务运营工作，包括但不限于境内支付、跨境支付等业务入账、账务数据校验核对、分析等工作；\n2. 对接新业务新场景，识别业务活动的财务影响，出具会计方案及系统化方案，与业务部门、产品技术部门、财务内部保持频繁有效沟通，确保业务系统能有效准确与财务系统对接，使财务系统化方案落地；\n3. 深入理解业务及相关系统，建立业会核对流程并推动系统化核对，确保账务数据准确性，及时解决业会核对差异，防范财务风险；\n4.与内外部团队积极协调，完成其他指定任务。","requirements":"1.本科及其以上学历，会计、经济、管理类等相关专业，4年及以上财会相关工作经验；\n2. 熟悉互联网业务模式，具有支付业务财务背景及业财系统建设相关经验者优先；\n3. 工作认真细心、责任心强、具有良好的团队协作精神和服务意识；\n4. 具备较强的沟通能力和学习能力，并具备优秀的逻辑思维和分析能力，能够基于数据发现问题和解决问题。","description":"部门介绍\n财务平台负责公司整体和各业务层面的财务管理工作，通过建设专业、全面、复合的财务管理能力和与业务经营的紧密结合来支持公司健康发展。目前财务平台拥有财务会计、财务报告、资金管理、税务管理、财务共享、财务系统、规划分析、财务BP和内控内审等主要工作方向。我们的目标是建设业界一流的财务管理能力和经营支持体系，为公司战略的正确落地、投入效率的持续提升、业务价值的不断增长保驾护航。欢迎加入财务平台，携手一起向未来！\n\n岗位职责\n1. 负责对接支付业务财务运营工作，包括但不限于境内支付、跨境支付等业务入账、账务数据校验核对、分析等工作；\n2. 对接新业务新场景，识别业务活动的财务影响，出具会计方案及系统化方案，与业务部门、产品技术部门、财务内部保持频繁有效沟通，确保业务系统能有效准确与财务系统对接，使财务系统化方案落地；\n3. 深入理解业务及相关系统，建立业会核对流程并推动系统化核对，确保账务数据准确性，及时解决业会核对差异，防范财务风险；\n4.与内外部团队积极协调，完成其他指定任务。\n\n岗位基本要求\n1.本科及其以上学历，会计、经济、管理类等相关专业，4年及以上财会相关工作经验；\n2. 熟悉互联网业务模式，具有支付业务财务背景及业财系统建设相关经验者优先；\n3. 工作认真细心、责任心强、具有良好的团队协作精神和服务意识；\n4. 具备较强的沟通能力和学习能力，并具备优秀的逻辑思维和分析能力，能够基于数据发现问题和解决问题。\n\n具备以下条件优先\n了解支付行业，有系统化经验者优先\n\n岗位亮点\n1.参与公司支付业务，积累金融科技领域实战经验； \n2. 与行业内优秀的人共舞，让自己变得更加优秀；\n3. 简单、高效、和谐的团队氛围。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4673966637","sourceKey":"meituan_social","company":"美团","title":"美团骑行-运营主管（合肥）","city":"合肥市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4673966637&jobShareType=1","duty":"1、负责所属区域的车辆运营管理工作，对有效运营车辆和活跃车辆等指标负责；\n2、通实地观察和数据分析，了解区域的车辆供需状况，制定合理的车辆投放及调度策略；\n3、根据故障车辆及未骑行车辆的数量及分布数据，制定并优化车辆干预管理的策略；\n4、配合政府部门对城市运营问题进行管理；\n5、协助运营经理管理运营团队，提升团队工作效率和结果。","requirements":"1．本科及以上学历。\n2、1一年以上团队管理经验。\n3、善于用开拓性思维解决问题，有较强的执行力和多部门协调能力。\n4、过往有相关行业经验。","description":"部门介绍\n美团骑行事业部在全国各个城市开展美团单车、电单车业务，提供绿色、便捷的共享出行服务，是美团出行板块重要的组成部分。我们力求为城市可持续发展提供低碳智能的解决方案，通过技术创新和硬件升级，不断优化全流程骑行体验，为低碳出行提供更好的服务。其中，美团单车旨在为城市居民提供通勤接驳服务，满足用户短途接驳出行需求；美团电单车则满足用户中短途多场景低碳出行需求。\n我们有开放的工作氛围，也有充满韧劲和创造力，心系低碳出行的伙伴。加入我们，一起为用户创造更好的出行体验。\n\n岗位职责\n1、负责所属区域的车辆运营管理工作，对有效运营车辆和活跃车辆等指标负责；\n2、通实地观察和数据分析，了解区域的车辆供需状况，制定合理的车辆投放及调度策略；\n3、根据故障车辆及未骑行车辆的数量及分布数据，制定并优化车辆干预管理的策略；\n4、配合政府部门对城市运营问题进行管理；\n5、协助运营经理管理运营团队，提升团队工作效率和结果。\n\n岗位基本要求\n1．本科及以上学历。\n2、1一年以上团队管理经验。\n3、善于用开拓性思维解决问题，有较强的执行力和多部门协调能力。\n4、过往有相关行业经验。\n\n具备以下条件优先\n1、出行行业或互联网行业经验，\n2、有快消品区域覆盖或互联网城市地推管理经验者优先；\n3、善于数据分析，并能通过数据分析的结果不断优整工作。\n4、接受区域调配者优先。\n\n岗位亮点\n互联网大厂的广阔发展空间，未来负责多城运营，有晋升空间。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4672766560","sourceKey":"meituan_social","company":"美团","title":"充电宝出海_销售策略运营","city":"香港特别行政区","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4672766560&jobShareType=1","duty":"1. 负责充电宝出海香港业务的销售策略制定与落地执行，结合目标市场特点、竞争格局及商户行为，输出数据驱动的销售策略建议并推动优化；\n2.运营SOP体系搭建：与一线负责人深度配合，制定可落地的运营策略；建立销售SOP和管理SOP，并将关键流程固化为AI可执行的标准动作，推动业务可复制、标准化高效拿结果；\n3. 组织激励与效能提升：与奖金、人力、商分等部门协同，设计符合出海业务发展阶段的考核激励机制，驱动销售团队拿结果；\n4. 协同产研、财法等部门，建立并优化作业流程，持续提升效率与业务可扩展性，并结合AI增效工具的实际应用，驱动效能创新性提升。","requirements":"1. 大学本科及以上学历，具备5年以上销售运营、策略运营或业务运营相关经验，熟悉海外市场环境，或有出海业务经验者优先；\n2. 粤语流利，可在大湾区业务场景中进行无障碍沟通；具备良好英语书面表达能力，能阅读英文业务材料和跨国协作者加分。\n3. 自驱力和责任心并重，能以业务结果导向为先，深入业务和市场，重视落地性；\n4. 具备扎实的数据分析能力，熟练使用SQL等数据工具；具备AI工具辅助数据分析的实践经验者优先； \n5. 框架思维与方法论：具备框架性思考能力，有从0到1建设流程与制度的实际经验，善于将成功经验提炼为可规模化复用的方法论；\n6. 具备良好的跨团队沟通与项目管理能力，能独立推动复杂项目落地。","description":"部门介绍\n美团充电宝是服务零售中的共享租赁业务，承接美团使命，致力让大家充电更简单。美团充电宝业务以应急充电功能为服务核心，覆盖吃喝玩乐生活全场景。目前，已在全国超过2000多个城市的餐饮、娱乐、机场、地铁、火车站、医院、学校、景区等公共区域及场所提供充电服务，铺设机柜超过百万，有KA、直营、渠道合作商多种业务模式，随时随地保障和满足消费者的充电需求。我们的业务资产数量多、场景多元化，追求精益管理。我们的团队大咖云集，崇尚自主驱动，求真务实。我们正处在快速发展期，规模持续增长，目标是市场规模和利润水平双第一。我们的管理者关注团队每个成员的成长，为每个人提供适合自身发展的机会。广阔天地、大有作为，美团充电宝期待你的加入！\n\n岗位职责\n1. 负责充电宝出海香港业务的销售策略制定与落地执行，结合目标市场特点、竞争格局及商户行为，输出数据驱动的销售策略建议并推动优化；\n2.运营SOP体系搭建：与一线负责人深度配合，制定可落地的运营策略；建立销售SOP和管理SOP，并将关键流程固化为AI可执行的标准动作，推动业务可复制、标准化高效拿结果；\n3. 组织激励与效能提升：与奖金、人力、商分等部门协同，设计符合出海业务发展阶段的考核激励机制，驱动销售团队拿结果；\n4. 协同产研、财法等部门，建立并优化作业流程，持续提升效率与业务可扩展性，并结合AI增效工具的实际应用，驱动效能创新性提升。\n\n岗位基本要求\n1. 大学本科及以上学历，具备5年以上销售运营、策略运营或业务运营相关经验，熟悉海外市场环境，或有出海业务经验者优先；\n2. 粤语流利，可在大湾区业务场景中进行无障碍沟通；具备良好英语书面表达能力，能阅读英文业务材料和跨国协作者加分。\n3. 自驱力和责任心并重，能以业务结果导向为先，深入业务和市场，重视落地性；\n4. 具备扎实的数据分析能力，熟练使用SQL等数据工具；具备AI工具辅助数据分析的实践经验者优先； \n5. 框架思维与方法论：具备框架性思考能力，有从0到1建设流程与制度的实际经验，善于将成功经验提炼为可规模化复用的方法论；\n6. 具备良好的跨团队沟通与项目管理能力，能独立推动复杂项目落地。\n\n岗位亮点\n1. 出海最前线，你将是业务决策的直接参与者，而非执行层。你提出的策略框架和激励设计，将直接影响一线团队的行动方向和业务成果。\n2. AI+出海：两个时代机遇叠加在AI重塑所有职业的今天，出海运营是为数不多能\"双倍押注\"的方向：一是全球化带来的新增市场，二是AI工具带来的效率革命。你将在实践中同时掌握两种核心竞争力。\n3. 从境内成熟方法论到国际落地：美团充电宝在境内已积累深厚的运营体系和数据资产。你的任务是把这套经过验证的方法论带到香港，完成从\"大陆最佳实践\"到\"国际化复制\"的关键一步。\n4. 年轻团队，快速成长出海团队规模小、决策链短。没有繁杂的审批流，你的提案可以快速落地，成果可以直接可见。在这里，你会看到自己对业务的直接贡献。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4643392637","sourceKey":"meituan_social","company":"美团","title":"快乐猴-粤东店长","city":"惠州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4643392637&jobShareType=1","duty":"1.负责门店的日常运营管理，确保公司营运标准高效在门店落地，提升销售、毛利和客户满意度；\n2.负责团队的招聘、培训和绩效管理，确保团队的稳定和高效运作；\n3.管控店内损耗、提升门店人效，优化可控费用（如物料，水电煤等营运费用），达成主要考核KPI；\n4.对内各协同部门的日常高效交互，达成共识，高效执行总部和区域新项目落地；\n5.对外关系的建立维护，如相关政府职能部门（市场管理、消协等）、物业关系，打造协作融洽的合作伙伴。","requirements":"1.大学专科及以上学历。\n2.至少3年以上线下门店营运管理领域工作经验。\n3.具有良好的团队管理能力、沟通能力和问题解决能力。\n4.具有较强的数据分析能力和业务推动能力，能够制定有效的运营策略和改进方案。\n5.具有责任心，能够独立思考和独立工作。\n6.掌握基本的AI工具，使用工具提升工作流程效率。","description":"部门介绍\n快乐猴是美团自营社区超市，依托自有供应链和门店管理体系，聚焦家庭用户的三餐所需，为消费者提供高质价比的食杂商品。快乐猴以数字化能力与科学品控为基础，不断满足消费者对“省”和“便利”的需求。\n\n岗位职责\n1.负责门店的日常运营管理，确保公司营运标准高效在门店落地，提升销售、毛利和客户满意度；\n2.负责团队的招聘、培训和绩效管理，确保团队的稳定和高效运作；\n3.管控店内损耗、提升门店人效，优化可控费用（如物料，水电煤等营运费用），达成主要考核KPI；\n4.对内各协同部门的日常高效交互，达成共识，高效执行总部和区域新项目落地；\n5.对外关系的建立维护，如相关政府职能部门（市场管理、消协等）、物业关系，打造协作融洽的合作伙伴。\n\n岗位基本要求\n1.大学专科及以上学历。\n2.至少3年以上线下门店营运管理领域工作经验。\n3.具有良好的团队管理能力、沟通能力和问题解决能力。\n4.具有较强的数据分析能力和业务推动能力，能够制定有效的运营策略和改进方案。\n5.具有责任心，能够独立思考和独立工作。\n6.掌握基本的AI工具，使用工具提升工作流程效率。\n\n岗位亮点\n1.提供丰富的线下门店管理经验和团队管理经验的机会。\n2.提供良好的职业发展空间和晋升机会，能够在公司内部快速成长。\n3.薪资福利优厚，公司提供完善的培训体系和职业发展计划，帮助员工实现个人职业目标。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4550398756","sourceKey":"meituan_social","company":"美团","title":"城市运营主管","city":"拉萨市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4550398756&jobShareType=1","duty":"1. 负责拉萨市车辆运维的日常运营支持工作，确保车辆调度、维护和故障处理的高效执行。  \n2. 协调城市内车辆资源分配，优化运营效率，保障服务质量和用户体验。  \n3. 跟进车辆运维数据，分析运营问题并提出改进建议，提升整体运营水平。  \n4. 协助制定并执行城市运营相关流程和标准，确保合规性和可操作性。  \n5. 与相关部门协作，推动运营问题的快速响应与解决。","requirements":"1. 大学本科及以上学历，专业不限，有运营支持或车辆运维相关背景优先。  \n2. 具备2年以上运营或运维相关工作经验，熟悉城市运营流程者优先。  \n3. 具备良好的沟通协调能力和团队协作精神，能适应高原工作环境。  \n4. 熟练使用办公软件，具备基础数据分析能力。  \n5. 责任心强，执行力强，能承受一定工作压力。","description":"部门介绍\n美团骑行事业部在全国各个城市开展美团单车、电单车业务，提供绿色、便捷的共享出行服务，是美团出行板块重要的组成部分。我们力求为城市可持续发展提供低碳智能的解决方案，通过技术创新和硬件升级，不断优化全流程骑行体验，为低碳出行提供更好的服务。其中，美团单车旨在为城市居民提供通勤接驳服务，满足用户短途接驳出行需求；美团电单车则满足用户中短途多场景低碳出行需求。\n我们有开放的工作氛围，也有充满韧劲和创造力，心系低碳出行的伙伴。加入我们，一起为用户创造更好的出行体验。\n\n岗位职责\n1. 负责拉萨市车辆运维的日常运营支持工作，确保车辆调度、维护和故障处理的高效执行。  \n2. 协调城市内车辆资源分配，优化运营效率，保障服务质量和用户体验。  \n3. 跟进车辆运维数据，分析运营问题并提出改进建议，提升整体运营水平。  \n4. 协助制定并执行城市运营相关流程和标准，确保合规性和可操作性。  \n5. 与相关部门协作，推动运营问题的快速响应与解决。\n\n岗位基本要求\n1. 大学本科及以上学历，专业不限，有运营支持或车辆运维相关背景优先。  \n2. 具备2年以上运营或运维相关工作经验，熟悉城市运营流程者优先。  \n3. 具备良好的沟通协调能力和团队协作精神，能适应高原工作环境。  \n4. 熟练使用办公软件，具备基础数据分析能力。  \n5. 责任心强，执行力强，能承受一定工作压力。\n\n岗位亮点\n1. 在高原特色城市开展运营工作，积累独特地域经验。  \n2. 参与城市级运营体系建设，提升综合管理能力。  \n3. 公司提供完善的培训体系和职业发展通道。  \n4. 团队氛围积极，注重员工成长与关怀。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4259462158","sourceKey":"meituan_social","company":"美团","title":"软硬件服务-AI native组织发展专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4259462158&jobShareType=1","duty":"1.定义并实施Agent支持的未来人力资源运营模式，明确工作如何在人类和agent之间转移，角色如何演变，以及如何重新定义人力资源能力实现组织绩效提升。\n\n2.主导人工智能时代的组织重塑，确保组织设计具有可采纳性和可持续性。\n\n3.通过分析、建模帮助开发下一代劳动力解决方案，支持劳动力规划决策。\n\n4.重新定义人工智能劳动力中的角色、职责和技能，主导岗位设计、角色厘清和劳动力影响评估，帮助员工在人工智能世界中蓬勃发展。\n\n5.将人工智能融入关键的人力资源流程，提高准确性、速度和决策质量。\n\n6.持续寻找新兴的人工智能实践并应用，通过明确的关键指标衡量人工智能计划的影响，利用洞察来改进流程并提升员工体验。","requirements":"1.真实使用过主流AI工具完成实际工作任务，能熟练调用LLM，进行提示工程、RAG、工作流和Agent构建。\n\n2.或者（与要求1）拥有2年以上劳动力管理与流程经验，具备以下一个或多个领域的经验：劳动力战略与解决方案、劳动力能力、组织变革和/或人力资源分析。\n\n3.对人工智能重塑工作和能力需求有深刻理解，或有强烈的兴趣，具有前瞻性思维、好奇心和自信心，喜欢打破常规做事。\n\n4.注重行动和实际执行效果，能快速上手新工具、新平台，能在模糊环境中自驱。\n\n5.擅长跨职能协作，能与人力资源、技术、数据、业务等多方有效沟通和协同推进。","description":"部门介绍\n美团HR的使命是“建设有生命力的组织，为客户和社会创造价值。” 我们认为HR的工作不是以自身“专业”为中心，而是要建设有助于员工发挥创造力的环境，支持他们更好地为外部客户和社会创造价值，也实现组织自身的进化和传承。在这个过程中，我们的每位HR同学都是“业务的战略合作伙伴、组织能力的建设者、美团精神的布道者、员工的成长伙伴”。我们要设计面向长期支撑组织有效运转的机制，我们要求真务实地帮业务解决发展中的问题和阵痛，我们要支持每一位员工历经磨炼收获成长。我们要影响和驱动让世界更美好的变化发生。如果这也是你追求的，欢迎加入美团HR，与我们一路同行！\n\n岗位职责\n1.定义并实施Agent支持的未来人力资源运营模式，明确工作如何在人类和agent之间转移，角色如何演变，以及如何重新定义人力资源能力实现组织绩效提升。\n\n2.主导人工智能时代的组织重塑，确保组织设计具有可采纳性和可持续性。\n\n3.通过分析、建模帮助开发下一代劳动力解决方案，支持劳动力规划决策。\n\n4.重新定义人工智能劳动力中的角色、职责和技能，主导岗位设计、角色厘清和劳动力影响评估，帮助员工在人工智能世界中蓬勃发展。\n\n5.将人工智能融入关键的人力资源流程，提高准确性、速度和决策质量。\n\n6.持续寻找新兴的人工智能实践并应用，通过明确的关键指标衡量人工智能计划的影响，利用洞察来改进流程并提升员工体验。\n\n岗位基本要求\n1.真实使用过主流AI工具完成实际工作任务，能熟练调用LLM，进行提示工程、RAG、工作流和Agent构建。\n\n2.或者（与要求1）拥有2年以上劳动力管理与流程经验，具备以下一个或多个领域的经验：劳动力战略与解决方案、劳动力能力、组织变革和/或人力资源分析。\n\n3.对人工智能重塑工作和能力需求有深刻理解，或有强烈的兴趣，具有前瞻性思维、好奇心和自信心，喜欢打破常规做事。\n\n4.注重行动和实际执行效果，能快速上手新工具、新平台，能在模糊环境中自驱。\n\n5.擅长跨职能协作，能与人力资源、技术、数据、业务等多方有效沟通和协同推进。\n\n具备以下条件优先\n1.直接影响业务结果。不是优化现有流程，而是重新定义组织和工作，释放人的创造性价值；\n\n2.参与HR范式变革。你就是浪潮本身，在真实管理中实战，定义AI时代人力资源工作新范式。\n\n岗位亮点\n1.有AI 产品从0到1的建设经验，可分享案例并有实际可评估的效果。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4692001005","sourceKey":"meituan_social","company":"美团","title":"数字人业务与技术规划师","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4692001005&jobShareType=1","duty":"1. 负责数字人业务的技术架构设计与长期技术规划，推动核心算法与工程系统的落地实施。  \n2. 深入理解数字人应用场景，结合用户需求制定技术路线图，并协调跨团队资源推进项目进展。  \n3. 主导数字人相关算法策略的优化与创新，包括语音合成、动作生成、情感交互等关键技术方向。  \n4. 跟踪行业前沿技术动态，评估新技术在数字人业务中的可行性并推动技术预研与成果转化。","requirements":"1. 硕士研究生及以上学历，计算机科学、人工智能、软件工程等相关专业背景。  \n2. 具备5年以上开发或算法策略相关工作经验，有数字人、虚拟人、智能交互等领域经验者优先。  \n3. 熟悉深度学习、自然语言处理、计算机视觉等至少一个核心技术方向，具备扎实的算法与工程能力。  \n4. 具备良好的技术规划能力与业务理解能力，能够从全局视角推动技术驱动业务增长。","description":"部门介绍\n美团核心本地商业下业务研发平台，基于公司“零售+科技”的战略导向，通过从底层架构到应用系统、从软件到硬件、从传统算法到GenAI的全方位技术研究，以及开发、运维、安全等全流程能力建设，致力于推动美团核心本地商业下需求侧与供给侧的数字化和智能化升级，助力业务实现高质量增长，优化用户使用体验，提升商户经营水平，促进行业生态伙伴关系的持续健康发展。团队秉持务实、自驱、开放以及追求卓越的工程师文化，一方面通过系统和技术体系的持续迭代升级，帮助业务高质量增长；另一方面，密切关注前沿技术趋势变化，积极创新技术能力，为业务未来发展创造新的可能性。期待优秀的你加入我们，在夯实专业、深耕平台的基础上与业务携手同行，一起用技术 “帮大家吃得更好，生活更好”。\n\n岗位职责\n1. 负责数字人业务的技术架构设计与长期技术规划，推动核心算法与工程系统的落地实施。  \n2. 深入理解数字人应用场景，结合用户需求制定技术路线图，并协调跨团队资源推进项目进展。  \n3. 主导数字人相关算法策略的优化与创新，包括语音合成、动作生成、情感交互等关键技术方向。  \n4. 跟踪行业前沿技术动态，评估新技术在数字人业务中的可行性并推动技术预研与成果转化。\n\n岗位基本要求\n1. 硕士研究生及以上学历，计算机科学、人工智能、软件工程等相关专业背景。  \n2. 具备5年以上开发或算法策略相关工作经验，有数字人、虚拟人、智能交互等领域经验者优先。  \n3. 熟悉深度学习、自然语言处理、计算机视觉等至少一个核心技术方向，具备扎实的算法与工程能力。  \n4. 具备良好的技术规划能力与业务理解能力，能够从全局视角推动技术驱动业务增长。\n\n具备以下条件优先\n有大厂的实际参与和负责经验\n\n岗位亮点\n1. 参与前沿数字人技术研发，推动AI技术在创新场景中的规模化应用。  \n2. 与行业TOP技术团队协作，获得广阔的职业发展空间与成长机会。  \n3. 工作地点覆盖北京、上海，提供具有竞争力的薪酬与福利待遇。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4617408310","sourceKey":"meituan_social","company":"美团","title":"松鼠便利西部大区成都中心仓运营支持","city":"成都市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4617408310&jobShareType=1","duty":"1. 结算与费用管理：依据合同约定计费标准，独立核算应付费用，识别并标记异常差异项，在业财系统中准确创建结算申请单并完成审批跟进，主动发现、分析结算差异原因，推动多方协调核实与解决。\n2. 物流成本分析与数据支持：定期整理汇总结算相关数据，制作物流成本分析报表，识别成本异常和优化空间，为成本控制及精细化运营提供数据支撑。\n3. 闪购商家入驻与规则管理：负责闪购商家入驻规则的迭代优化，协同合规、GA等业务方及时更新审核规则，完成内外部政策透传与规则落地。\n4. 中心仓运营支持：负责输出中心仓日报，支持仓配经理精细化运营；管理差异专员的认责和举证效率，驱动履约体验提升；定期收集门店和采销的投诉与反馈，协助优化流程、提升全链路体验；负责大区内相关岗位的绩效得分核算。\n5. 仓内行政与后勤管理：负责中心仓物资设备验收、入账、盘点、报损及水电办公成本控制结算；负责人员排班休假管理、5S管理，以及外部联络接待（物业、回收商、设备维保、消防等）。","requirements":"1.大学专科以上学历，财务、物流或人力资源相关专业优先。\n2.具有至少3年以上财务、行政、人事管理经验。\n3.具备良好的团队管理能力和沟通能力，能有效协调团队工作。\n4.熟练操作办公软件，了解物流管理流程。\n5.具备较强的责任心和执行力，能够承受一定的工作压力。","description":"部门介绍\n美团闪购是美团旗下的即时零售平台，依托即时配送能力，连接本地零售供给，满足消费者30分钟万物到家的即时需求。美团闪购涵盖超市便利、食材、水果、鲜花绿植、休闲零食、酒水饮料、数码家电、美妆个护、母婴玩具、日用百货、服饰鞋帽、宠物等诸多品类，业务覆盖全国近3,000个县市区旗，每日百万级在岗骑手，以高效的配送、丰富的品类和广泛的覆盖，为美团数亿用户带来便捷的生活体验，积极助力实体零售线上化转型，提升本地商业活力。\n\n岗位职责\n1. 结算与费用管理：依据合同约定计费标准，独立核算应付费用，识别并标记异常差异项，在业财系统中准确创建结算申请单并完成审批跟进，主动发现、分析结算差异原因，推动多方协调核实与解决。\n2. 物流成本分析与数据支持：定期整理汇总结算相关数据，制作物流成本分析报表，识别成本异常和优化空间，为成本控制及精细化运营提供数据支撑。\n3. 闪购商家入驻与规则管理：负责闪购商家入驻规则的迭代优化，协同合规、GA等业务方及时更新审核规则，完成内外部政策透传与规则落地。\n4. 中心仓运营支持：负责输出中心仓日报，支持仓配经理精细化运营；管理差异专员的认责和举证效率，驱动履约体验提升；定期收集门店和采销的投诉与反馈，协助优化流程、提升全链路体验；负责大区内相关岗位的绩效得分核算。\n5. 仓内行政与后勤管理：负责中心仓物资设备验收、入账、盘点、报损及水电办公成本控制结算；负责人员排班休假管理、5S管理，以及外部联络接待（物业、回收商、设备维保、消防等）。\n\n岗位基本要求\n1.大学专科以上学历，财务、物流或人力资源相关专业优先。\n2.具有至少3年以上财务、行政、人事管理经验。\n3.具备良好的团队管理能力和沟通能力，能有效协调团队工作。\n4.熟练操作办公软件，了解物流管理流程。\n5.具备较强的责任心和执行力，能够承受一定的工作压力。\n\n具备以下条件优先\n零售电商物流经验优先。\n\n岗位亮点\n1. 加入高速发展的松鼠便利，参与区域核心仓储运营。\n2. 扁平化管理，提供清晰的职业成长路径。\n3. 团队氛围年轻活跃，注重员工能力提升。\n4. 提供行业竞争力的薪资及绩效激励。\n5. 弹性工作制，注重工作与生活平衡。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4605615510","sourceKey":"meituan_social","company":"美团","title":"小象超市-用户运营专家（流量方向）","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4605615510&jobShareType=1","duty":"1、流量策略：制定小象超市全渠道流量获取策略，提升站内（搜索/推荐/广告位）与站外（平台广告/达人合作/异业置换/私域社群）流量布局，提升流量获取效率和变现能力；\n2、渠道拓展：拓展内外部流量渠道，优化流量结构，降低获客成本；建立渠道ROI评估体系，实现流量组合的动态调优；\n3、数据驱动：建立流量数据监控体系和分析框架，追踪UV/CTR/CVR/CPM/CPC等核心指标；基于数据分析发现流量机会和问题，推动持续优化。","requirements":"1、大学本科及以上学历，8年以上互联网用户运营或流量运营经验；\n2、熟悉主流流量分发逻辑（搜索/推荐/广告/私域），具备数据驱动运营能力，熟练使用SQL等分析工具；\n3、有成功主导用户增长或流量优化项目的完整案例，结果导向；\n4、具备较强的跨团队沟通能力和项目管理能力，能协同推进复杂项目；\n5、对零售或电商行业有深刻理解，有生鲜、商超、即时零售类经验者优先。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1、流量策略：制定小象超市全渠道流量获取策略，提升站内（搜索/推荐/广告位）与站外（平台广告/达人合作/异业置换/私域社群）流量布局，提升流量获取效率和变现能力；\n2、渠道拓展：拓展内外部流量渠道，优化流量结构，降低获客成本；建立渠道ROI评估体系，实现流量组合的动态调优；\n3、数据驱动：建立流量数据监控体系和分析框架，追踪UV/CTR/CVR/CPM/CPC等核心指标；基于数据分析发现流量机会和问题，推动持续优化。\n\n岗位基本要求\n1、大学本科及以上学历，8年以上互联网用户运营或流量运营经验；\n2、熟悉主流流量分发逻辑（搜索/推荐/广告/私域），具备数据驱动运营能力，熟练使用SQL等分析工具；\n3、有成功主导用户增长或流量优化项目的完整案例，结果导向；\n4、具备较强的跨团队沟通能力和项目管理能力，能协同推进复杂项目；\n5、对零售或电商行业有深刻理解，有生鲜、商超、即时零售类经验者优先。\n\n具备以下条件优先\n有即时零售行业经验优先\n\n岗位亮点\n1、参与核心业务增长，直接影响用户规模；\n2、团队氛围开放，鼓励创新实验与快速迭代；   \n3、接触海量用户数据，积累高价值运营经验；  \n4、与一线产品、技术团队深度协作，提升综合能力；\n5、美团2025年提出AI三大策略，\"AI at Work\"已渗透到每个角落——从CatPaw AI编程到NoCode零代码，从美境MeiGen到LongCat视频生成。在这里，AI不只是工具，而是运营方法论的核心组成部分。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4563093753","sourceKey":"meituan_social","company":"美团","title":"Kuwait Vendor Management","city":"科威特城","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4563093753&jobShareType=1","duty":"1. Collaborate with business, finance, procurement, legal, and administrative departments to develop, optimize, and implement a comprehensive employment management strategy. Internally, establish an employment management system; externally, optimize the supplier resource pool and improve delivery capabilities.\n\n2. Employment Risk Management: Develop a comprehensive employment risk map, proactively design contingency plans for high-risk areas, and coordinate with various departments to resolve risks related to employee departures, monitoring, and public opinion.\n\n3. Analyze the cost, delivery capacity, efficiency, and risks of employment resources for the assigned business, propose and promote cost reduction and efficiency improvement plans, and plan annual user budgets.\n\n4. Establish relevant systems for employee relations, corporate culture, and talent incentives at the base.\n\n5. Other Specialized Tasks: Outsourcing onboarding and offboarding standards, outsourcing management system requirements analysis, optimization of outsourcing employment management efficiency, external benchmarking, etc.","requirements":"1. Over 5 years of experience in large-scale outsourcing management (both client and vendor perspectives are acceptable).\n\n2. Understanding of employment market practices, familiarity with employment review and management systems, and the application of labor laws and regulations within enterprises; extensive practical experience in employee relations.\n\n3. Project management and data analysis capabilities, strong risk awareness, and expertise in resource integration and solution design.\n\n4. Excellent communication, coordination, and project management skills. Strong sense of purpose; able to ensure operational goals are achieved through the establishment of mechanisms and processes.","description":"部门介绍\n美团的使命是“帮大家吃得更好，生活更好”，公司聚焦“零售 + 科技”战略，和广大商户与各类合作伙伴一起，努力为消费者提供品质生活，推动商品零售和服务零售在需求侧和供给侧的数字化转型。\n2018年9月20日，美团正式在港交所挂牌上市。美团将始终坚持以客户为中心，不断加大在科技研发方面的投入，更好承担社会责任，更多创造社会价值，与广大合作伙伴一起发展共赢。\n\n岗位职责\n1. Collaborate with business, finance, procurement, legal, and administrative departments to develop, optimize, and implement a comprehensive employment management strategy. Internally, establish an employment management system; externally, optimize the supplier resource pool and improve delivery capabilities.\n\n2. Employment Risk Management: Develop a comprehensive employment risk map, proactively design contingency plans for high-risk areas, and coordinate with various departments to resolve risks related to employee departures, monitoring, and public opinion.\n\n3. Analyze the cost, delivery capacity, efficiency, and risks of employment resources for the assigned business, propose and promote cost reduction and efficiency improvement plans, and plan annual user budgets.\n\n4. Establish relevant systems for employee relations, corporate culture, and talent incentives at the base.\n\n5. Other Specialized Tasks: Outsourcing onboarding and offboarding standards, outsourcing management system requirements analysis, optimization of outsourcing employment management efficiency, external benchmarking, etc.\n\n岗位基本要求\n1. Over 5 years of experience in large-scale outsourcing management (both client and vendor perspectives are acceptable).\n\n2. Understanding of employment market practices, familiarity with employment review and management systems, and the application of labor laws and regulations within enterprises; extensive practical experience in employee relations.\n\n3. Project management and data analysis capabilities, strong risk awareness, and expertise in resource integration and solution design.\n\n4. Excellent communication, coordination, and project management skills. Strong sense of purpose; able to ensure operational goals are achieved through the establishment of mechanisms and processes.\n\n具备以下条件优先\nBase is located in Kuwait and has local workforce resources; candidates proficient in English, Arabic, and Chinese will be given priority.\n\n岗位亮点\n1. Team Atmosphere: The team fosters a collaborative atmosphere, emphasizes the accumulation of methodologies, and conducts regular work exchanges.\n\n2. Personal Growth: Team members have the opportunity to collaborate with experts in various modules, gaining insights into the review processes across business modules and enhancing their professional skills.","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4595106760","sourceKey":"meituan_social","company":"美团","title":"综合支持","city":"苏州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4595106760&jobShareType=1","duty":"1.信息传递：有效传递总部重要通知，并汇总反馈一线的重要信息；\n2.培训答疑：协助业务团队做好培训的组织和检核，以及部分业务答疑工作；\n3.流程对接：总部与城市的流程对接，如租房、福利、员工入转调离流程等；\n4.仓库管理：负责城市充电宝设备出入库管理及资产盘点，确保城市实际库存与后台数据一致","requirements":"1.大学本科及以上学历，两年及以上的综支、行政、人事、运营、库管等工作经验；\n2.工作积极主动，有较强的人际沟通能力及服务意识；\n3.工作有条理、细致、认真负责、办事严谨，有强效的执行力；\n4.掌握办公室行政工作流程,熟练操作办公软件；\n5.有互联网公司经验者优先考虑，能接受偶尔的出差走访处理城市工作","description":"部门介绍\n美团的使命是“帮大家吃得更好，生活更好”，公司聚焦“零售 + 科技”战略，和广大商户与各类合作伙伴一起，努力为消费者提供品质生活，推动商品零售和服务零售在需求侧和供给侧的数字化转型。\n2018年9月20日，美团正式在港交所挂牌上市。美团将始终坚持以客户为中心，不断加大在科技研发方面的投入，更好承担社会责任，更多创造社会价值，与广大合作伙伴一起发展共赢。\n\n岗位职责\n1.信息传递：有效传递总部重要通知，并汇总反馈一线的重要信息；\n2.培训答疑：协助业务团队做好培训的组织和检核，以及部分业务答疑工作；\n3.流程对接：总部与城市的流程对接，如租房、福利、员工入转调离流程等；\n4.仓库管理：负责城市充电宝设备出入库管理及资产盘点，确保城市实际库存与后台数据一致\n\n岗位基本要求\n1.大学本科及以上学历，两年及以上的综支、行政、人事、运营、库管等工作经验；\n2.工作积极主动，有较强的人际沟通能力及服务意识；\n3.工作有条理、细致、认真负责、办事严谨，有强效的执行力；\n4.掌握办公室行政工作流程,熟练操作办公软件；\n5.有互联网公司经验者优先考虑，能接受偶尔的出差走访处理城市工作\n\n具备以下条件优先\n1、大型项目主R协调经验；\n2、制度或流程从0-1搭建经验；\n3、数据运营分析能力较强。\n\n岗位亮点\n1.提升综合运营能力；\n2.提升个人与业务侧的协调能力；\n3.提升个人答疑能力；","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4683203354","sourceKey":"meituan_social","company":"美团","title":"一线合规负责人 | Field Compliance Lead","city":"圣保罗","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4683203354&jobShareType=1","duty":"1. 业务合规体系从 0 到 1 搭建\n基于业务实际运营场景，设计并落地端到端的销售合规管理体系，覆盖商家拓展、合同签约、渠道管理、返佣激励等关键环节\n制定合规政策、操作规范和红线标准，确保业务增长与风险可控之间的平衡\n\n2. 业务风险监控模型构建\n深入业务流程，识别高风险场景和关键控制点，建立基于数据的风险预警和监控模型\n搭建风险量化评估框架，对异常交易、违规操作等进行实时或周期性监测，推动风险管理从被动响应转向主动预防\n\n3. 飞检与质控机制建设\n设计并实施飞行检查（飞检）制度，覆盖一线销售行为、商家合作合规性等核心场景\n建立质量控制体系，明确检查标准、频率、反馈闭环和整改追踪机制\n\n4. 外包质检团队搭建与管理\n负责组建并管理外包质检团队，制定人员选拔标准、培训体系和绩效考核机制\n确保质控覆盖率和执行一致性，持续优化团队效能\n\n5. 跨部门协同与合规文化推动\n与业务、法务、数据、安全及中台 Compliance 团队紧密协作，明确一线与中台的职责边界，确保合规要求嵌入业务流程而非外挂式管控\n推动一线团队的合规意识建设，设计培训和宣导方案","requirements":"1.8 年以上工作经验，其中至少 3 年在业务合规、风控、内控或质量管理相关领域\n2.有一线业务经验（销售、渠道、运营等），深刻理解业务流程和商业逻辑，非纯后台职能背景\n3.有从 0 到 1 搭建合规或风控体系的实际经验\n4.具备数据驱动的风险识别能力，能设计监控模型和预警机制\n5.有外包团队或第三方团队管理经验\n6.较强的跨部门沟通和影响力，能在业务压力下坚持原则并推动落地","description":"部门介绍\nKeeta是全球领先外卖平台美团旗下的独立品牌，肩负着“帮大家吃得更好，生活更好”的使命。依托美团深耕中国市场15年的技术与运营积淀，我们正引领全球餐饮与商品即时配送服务的创新与发展。\n\n自2023年成立以来，Keeta始终扎根社区并创造价值。我们为用户提供可靠的外卖体验，以智慧技术助餐厅提升经营效率，在为骑手拓宽收入来源的同时，也充分提供安全保障措施。基于这份多方共赢、共同成长的理念，我们的业务已从中国香港稳步拓展至中东及巴西，并持续向世界迈进。\n\n岗位职责\n1. 业务合规体系从 0 到 1 搭建\n基于业务实际运营场景，设计并落地端到端的销售合规管理体系，覆盖商家拓展、合同签约、渠道管理、返佣激励等关键环节\n制定合规政策、操作规范和红线标准，确保业务增长与风险可控之间的平衡\n\n2. 业务风险监控模型构建\n深入业务流程，识别高风险场景和关键控制点，建立基于数据的风险预警和监控模型\n搭建风险量化评估框架，对异常交易、违规操作等进行实时或周期性监测，推动风险管理从被动响应转向主动预防\n\n3. 飞检与质控机制建设\n设计并实施飞行检查（飞检）制度，覆盖一线销售行为、商家合作合规性等核心场景\n建立质量控制体系，明确检查标准、频率、反馈闭环和整改追踪机制\n\n4. 外包质检团队搭建与管理\n负责组建并管理外包质检团队，制定人员选拔标准、培训体系和绩效考核机制\n确保质控覆盖率和执行一致性，持续优化团队效能\n\n5. 跨部门协同与合规文化推动\n与业务、法务、数据、安全及中台 Compliance 团队紧密协作，明确一线与中台的职责边界，确保合规要求嵌入业务流程而非外挂式管控\n推动一线团队的合规意识建设，设计培训和宣导方案\n\n岗位基本要求\n1.8 年以上工作经验，其中至少 3 年在业务合规、风控、内控或质量管理相关领域\n2.有一线业务经验（销售、渠道、运营等），深刻理解业务流程和商业逻辑，非纯后台职能背景\n3.有从 0 到 1 搭建合规或风控体系的实际经验\n4.具备数据驱动的风险识别能力，能设计监控模型和预警机制\n5.有外包团队或第三方团队管理经验\n6.较强的跨部门沟通和影响力，能在业务压力下坚持原则并推动落地\n\n具备以下条件优先\n1.华为等大型企业的业务+风控复合背景优先\n2.有海外业务合规经验\n3.熟悉互联网/本地生活/电商行业的业务模式和常见风险场景\n\n岗位亮点\n1. 担任合规关键角色，直接影响业务合规策略与执行\n2. 与总部及本地高层紧密合作，具备广阔的职业发展平台\n3. 工作地点位于圣保罗，深入参与拉美核心市场业务运营","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4427710218","sourceKey":"meituan_social","company":"美团","title":"充电宝业务部-城市经理","city":"北京市/成都市/武汉市/长春市/广州市/合肥市/南京市/上海市/杭州市/深圳市/西安市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4427710218&jobShareType=1","duty":"1. 负责所在城市充电宝业务的商户拓展与维护，完成既定合作目标。  \n2. 管理并带领10人以上团队，有带MM机会，制定执行地推计划，提升商户覆盖率与设备使用率。  \n3. 分析区域市场动态，挖掘潜在合作机会，优化商户结构与运营效率。  \n4. 协同产品、运营团队，推动商户端需求落地，提升用户体验与商户满意度。","requirements":"1. 大学本科及以上学历，5年以上业务拓展或地推团队管理经验。  \n2. 熟悉本地生活服务或共享经济行业，具备商户资源者优先。  \n3. 具备较强的团队管理与跨部门协作能力，能承受高强度工作压力。  \n4. 工作地点为北京市、长春市、合肥市、武汉市、广州市、成都市、南京市之一。","description":"部门介绍\n美团充电宝是服务零售中的共享租赁业务，承接美团使命，致力让大家充电更简单。美团充电宝业务以应急充电功能为服务核心，覆盖吃喝玩乐生活全场景。目前，已在全国超过2000多个城市的餐饮、娱乐、机场、地铁、火车站、医院、学校、景区等公共区域及场所提供充电服务，铺设机柜超过百万，有KA、直营、渠道合作商多种业务模式，随时随地保障和满足消费者的充电需求。我们的业务资产数量多、场景多元化，追求精益管理。我们的团队大咖云集，崇尚自主驱动，求真务实。我们正处在快速发展期，规模持续增长，目标是市场规模和利润水平双第一。我们的管理者关注团队每个成员的成长，为每个人提供适合自身发展的机会。广阔天地、大有作为，美团充电宝期待你的加入！\n\n岗位职责\n1. 负责所在城市充电宝业务的商户拓展与维护，完成既定合作目标。  \n2. 管理并带领10人以上团队，有带MM机会，制定执行地推计划，提升商户覆盖率与设备使用率。  \n3. 分析区域市场动态，挖掘潜在合作机会，优化商户结构与运营效率。  \n4. 协同产品、运营团队，推动商户端需求落地，提升用户体验与商户满意度。\n\n岗位基本要求\n1. 大学本科及以上学历，5年以上业务拓展或地推团队管理经验。  \n2. 熟悉本地生活服务或共享经济行业，具备商户资源者优先。  \n3. 具备较强的团队管理与跨部门协作能力，能承受高强度工作压力。  \n4. 工作地点为北京市、长春市、合肥市、武汉市、广州市、成都市、南京市之一。\n\n具备以下条件优先\n拥抱变化，敢想，对AI有一定思考和正在使用AI交互的人\n\n岗位亮点\n1. 加入高速发展的共享充电宝业务，参与城市级市场布局。  \n2. 拥有明确的晋升通道与完善的培训体系，助力个人成长。  \n3. 团队氛围积极，扁平化管理，鼓励创新与结果导向。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4644442664","sourceKey":"meituan_social","company":"美团","title":"快乐猴-华东片区经理","city":"宁波市/绍兴市/金华市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4644442664&jobShareType=1","duty":"1、负责线下超市（大于10家门店）片区的日常运营管理工作，包括人员调配、库存管理、销售数据分析等，\n2、负责招聘、培训和管理团队成员，确保团队高效运作，\n3、负责制定并执行该片区门店的整体经营质量，多维度提升门店的营运效率。","requirements":"1、大学专科及以上学历，\n2、至少8年以上线下超市管理相关工作经验，如有较多新店开业经验的可适当放宽，\n3、具备较强的团队管理能力和沟通协调能力，能够有效领导团队实现业绩目标，\n4、具备良好的数据分析能力和解决问题能力，能够快速响应并解决运营中的问题。\n5、运用美团数字化运营工具辅助日常工作，借助AI分析工具提升决策质量，通过数据驱动方式持续优化工作效率和业务成果。","description":"部门介绍\n快乐猴是美团自营社区超市，依托自有供应链和门店管理体系，聚焦家庭用户的三餐所需，为消费者提供高质价比的食杂商品。快乐猴以数字化能力与科学品控为基础，不断满足消费者对“省”和“便利”的需求。\n\n岗位职责\n1、负责线下超市（大于10家门店）片区的日常运营管理工作，包括人员调配、库存管理、销售数据分析等，\n2、负责招聘、培训和管理团队成员，确保团队高效运作，\n3、负责制定并执行该片区门店的整体经营质量，多维度提升门店的营运效率。\n\n岗位基本要求\n1、大学专科及以上学历，\n2、至少8年以上线下超市管理相关工作经验，如有较多新店开业经验的可适当放宽，\n3、具备较强的团队管理能力和沟通协调能力，能够有效领导团队实现业绩目标，\n4、具备良好的数据分析能力和解决问题能力，能够快速响应并解决运营中的问题。\n5、运用美团数字化运营工具辅助日常工作，借助AI分析工具提升决策质量，通过数据驱动方式持续优化工作效率和业务成果。\n\n岗位亮点\n1、可以在快节奏的线下零售行业中展现个人管理能力和团队领导能力，\n2、有机会参与线下超市的整体运营策略规划和执行，实现个人职业发展和成长，\n3、薪资福利优厚，发展空间大，公司提供良好的培训和晋升机会。\n4、美团平台级资源支撑，让你的想法真正落地：跨BG的技术、数据、物流资源都可以为快乐猴后线体系建设服务，你不是单打独斗。\n具备以下优先:\n具备硬折扣相关业态片区管理工作经验优先。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4672436247","sourceKey":"meituan_social","company":"美团","title":"骑行安全事务专员","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4672436247&jobShareType=1","duty":"1.具有区域安全体系搭建经验，针对业务风险可以提供切实有效的优化管控方案，对负责区域安全实行管理、监督、协调、培训和考核，协助业务完善风险管控制度；\n2.基于业务流程梳理和风险分析，制定、验证并持续优化安全指标体系及风险预警机制，建设风控系统并落地追踪；\n3.负责区域内的安全事件处理，包括但不限于侵财打击、恶意竞争、其他与安全相关事项的配合；\n4. 配合区域内业务主管部门的工作，并保持良好沟通。","requirements":"1.本科及以上学历，6年以上安全管理类工作经验，交通安全管理专业或有相关工作背景者优先；\n2.熟悉业务主管部门的工作方式、语言行为规则和决策流程，熟悉互联网行业，拥有一定行业资源；\n3.具有较强处理复杂事物的能力和团队合作意识，能接受高频出差；\n4.具有较强的总结分析能力、公文写作能力，语言表达能力。","description":"部门介绍\n美团骑行事业部在全国各个城市开展美团单车、电单车业务，提供绿色、便捷的共享出行服务，是美团出行板块重要的组成部分。我们力求为城市可持续发展提供低碳智能的解决方案，通过技术创新和硬件升级，不断优化全流程骑行体验，为低碳出行提供更好的服务。其中，美团单车旨在为城市居民提供通勤接驳服务，满足用户短途接驳出行需求；美团电单车则满足用户中短途多场景低碳出行需求。\n我们有开放的工作氛围，也有充满韧劲和创造力，心系低碳出行的伙伴。加入我们，一起为用户创造更好的出行体验。\n\n岗位职责\n1.具有区域安全体系搭建经验，针对业务风险可以提供切实有效的优化管控方案，对负责区域安全实行管理、监督、协调、培训和考核，协助业务完善风险管控制度；\n2.基于业务流程梳理和风险分析，制定、验证并持续优化安全指标体系及风险预警机制，建设风控系统并落地追踪；\n3.负责区域内的安全事件处理，包括但不限于侵财打击、恶意竞争、其他与安全相关事项的配合；\n4. 配合区域内业务主管部门的工作，并保持良好沟通。\n\n岗位基本要求\n1.本科及以上学历，6年以上安全管理类工作经验，交通安全管理专业或有相关工作背景者优先；\n2.熟悉业务主管部门的工作方式、语言行为规则和决策流程，熟悉互联网行业，拥有一定行业资源；\n3.具有较强处理复杂事物的能力和团队合作意识，能接受高频出差；\n4.具有较强的总结分析能力、公文写作能力，语言表达能力。\n\n具备以下条件优先\n有一线公安管理、互联网安全管理岗位工作经验\n\n岗位亮点\n1.大平台，有长远的成长发展空间，贴近业务侧更容易沉淀公共资源；\n2.具备较好的发展空间，表现优异者可以往管理方面培养；\n3.高水平专业团队，拥有专家型同事和完善培训体系，为个人成长提供广阔环境。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4643473142","sourceKey":"meituan_social","company":"美团","title":"快乐猴-粤西店长","city":"珠海市/中山市/江门市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4643473142&jobShareType=1","duty":"1.负责门店的日常运营管理，确保公司营运标准高效在门店落地，提升销售、毛利和客户满意度；\n2.负责团队的招聘、培训和绩效管理，确保团队的稳定和高效运作；\n3.管控店内损耗、提升门店人效，优化可控费用（如物料，水电煤等营运费用），达成主要考核KPI；\n4.对内各协同部门的日常高效交互，达成共识，高效执行总部和区域新项目落地；\n5.对外关系的建立维护，如相关政府职能部门（市场管理、消协等）、物业关系，打造协作融洽的合作伙伴。","requirements":"1.大学专科及以上学历。\n2.至少3年以上线下门店营运管理领域工作经验。\n3.具有良好的团队管理能力、沟通能力和问题解决能力。\n4.具有较强的数据分析能力和业务推动能力，能够制定有效的运营策略和改进方案。\n5.具有责任心，能够独立思考和独立工作。\n6.掌握基本的AI工具，使用工具提升工作流程效率。","description":"部门介绍\n快乐猴是美团自营社区超市，依托自有供应链和门店管理体系，聚焦家庭用户的三餐所需，为消费者提供高质价比的食杂商品。快乐猴以数字化能力与科学品控为基础，不断满足消费者对“省”和“便利”的需求。\n\n岗位职责\n1.负责门店的日常运营管理，确保公司营运标准高效在门店落地，提升销售、毛利和客户满意度；\n2.负责团队的招聘、培训和绩效管理，确保团队的稳定和高效运作；\n3.管控店内损耗、提升门店人效，优化可控费用（如物料，水电煤等营运费用），达成主要考核KPI；\n4.对内各协同部门的日常高效交互，达成共识，高效执行总部和区域新项目落地；\n5.对外关系的建立维护，如相关政府职能部门（市场管理、消协等）、物业关系，打造协作融洽的合作伙伴。\n\n岗位基本要求\n1.大学专科及以上学历。\n2.至少3年以上线下门店营运管理领域工作经验。\n3.具有良好的团队管理能力、沟通能力和问题解决能力。\n4.具有较强的数据分析能力和业务推动能力，能够制定有效的运营策略和改进方案。\n5.具有责任心，能够独立思考和独立工作。\n6.掌握基本的AI工具，使用工具提升工作流程效率。\n\n岗位亮点\n1.提供丰富的线下门店管理经验和团队管理经验的机会。\n2.提供良好的职业发展空间和晋升机会，能够在公司内部快速成长。\n3.薪资福利优厚，公司提供完善的培训体系和职业发展计划，帮助员工实现个人职业目标。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4691132043","sourceKey":"meituan_social","company":"美团","title":"国际信贷-催收产品","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4691132043&jobShareType=1","duty":"1、依据公司的国际化战略，通过深入洞察当地用户需求和市场竞争格局，负责海外信贷系统的迭代规划、需求收集与调研统筹，与技术团队紧密协作，确保产品技术可行性及高效落地。\n\n2、与Keeta业务场景深度合作，寻找产品价值与场景的深度融合，与策略、业务、商务多方开展合作\n\n3、主导产品上线、运营及维护工作，建立产品数据监测机制，定期输出分析报告，推动业务改进。\n\n4、密切关注行业政策与法规动态，及时调整产品策略，确保平台合规性与风险可控性。\n\n5、探索AI技术在贷后催收场景的创新应用，推动智能化解决方案落地。","requirements":"1、本科及以上学历，熟悉海外信贷或风险流程及系统架构，具备贷后相关经验或AI场景落地经验优先。\n\n2、有过从0到1的产品经验，拥有优秀的产品方案设计和文档撰写能力，具备较强的逻辑思维和极强的个人落地实施能力和意愿；\n\n3、能够独立思考并解决问题，执行力和目标感强，具备良好的协调沟通能力，善于跨团队协作；\n\n4、有大型互联网公司海外业务经验者优先，具备英语沟通能力；\n\n5、具有创业精神，善于应对挑战与压力","description":"部门介绍\n美团金融服务平台成立于2016年，以“场景+金融”模式，携手合作伙伴构建开放生态，为美团平台用户和商户提供底层账户、支付通道、信贷、保险和理财等金融解决方案。我们致力于以科技为核心，助力金融机构打通金融普惠“最后一公里”。我们期待与大家共同完成每一件平凡而卓越的事情，一起为用户提供优质的产品体验，守护用户的资金安全，让生活变得更美好。\n\n岗位职责\n1、依据公司的国际化战略，通过深入洞察当地用户需求和市场竞争格局，负责海外信贷系统的迭代规划、需求收集与调研统筹，与技术团队紧密协作，确保产品技术可行性及高效落地。\n\n2、与Keeta业务场景深度合作，寻找产品价值与场景的深度融合，与策略、业务、商务多方开展合作\n\n3、主导产品上线、运营及维护工作，建立产品数据监测机制，定期输出分析报告，推动业务改进。\n\n4、密切关注行业政策与法规动态，及时调整产品策略，确保平台合规性与风险可控性。\n\n5、探索AI技术在贷后催收场景的创新应用，推动智能化解决方案落地。\n\n岗位基本要求\n1、本科及以上学历，熟悉海外信贷或风险流程及系统架构，具备贷后相关经验或AI场景落地经验优先。\n\n2、有过从0到1的产品经验，拥有优秀的产品方案设计和文档撰写能力，具备较强的逻辑思维和极强的个人落地实施能力和意愿；\n\n3、能够独立思考并解决问题，执行力和目标感强，具备良好的协调沟通能力，善于跨团队协作；\n\n4、有大型互联网公司海外业务经验者优先，具备英语沟通能力；\n\n5、具有创业精神，善于应对挑战与压力\n\n具备以下条件优先\n有海外，特别是南美催收产品相关经验者优先考虑\n\n岗位亮点\n美团海外业务2023年正式确认为公司战略，美团金融与业务深度绑定，共同探索海外金融业务的新突破。我们期待与大家共同完成每一件平凡而卓越的事情，把吃的更好和生活的更好的愿景旗帜插满全球。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4225467712","sourceKey":"meituan_social","company":"美团","title":"医药广告运营","city":"石家庄市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4225467712&jobShareType=1","duty":"1.负责美团医药客户广告产品的线上入驻和维护，促成客户与平台的持续合作\n2.通过主动高频外呼完成客户触达、需求挖掘及转化\n3.涉及异议处理、客户维护及复购引导 \n4.及时响应商户诉求，在规则内协助广告投放等系统设置，为商户提供良好的使用体验。","requirements":"1、大专及以上学历；\n2、有电销、销售经验优先；\n3、能够熟练使用办公软件；\n4、学习能力和适应能力强，能够快速迭代，拥抱变化；\n5、积极主动、富有激情、具有良好的沟通能力；","description":"部门介绍\n商业增值部是服务于美团核心本地商业客户的增值服务平台，覆盖餐饮、即时零售、医药、休闲娱乐、丽人医美、生活服务、酒旅度假等业务领域。我们致力于构建健康的本地商业生态，通过为平台客户和消费者提供符合其需求的多元、便捷、高效的商业产品和服务，帮助生态伙伴提高效率、优化经营、实现持续健康发展，推动本地商业数字化营销的发展，促进商业生态繁荣。作为本地商业的头部平台，我们为产品、运营、商务、技术、商业分析等领域人才提供广阔的发展空间。诚邀你加入美团商业增值团队，共筑本地商业的健康繁荣生态！\n\n岗位职责\n1.负责美团医药客户广告产品的线上入驻和维护，促成客户与平台的持续合作\n2.通过主动高频外呼完成客户触达、需求挖掘及转化\n3.涉及异议处理、客户维护及复购引导 \n4.及时响应商户诉求，在规则内协助广告投放等系统设置，为商户提供良好的使用体验。\n\n岗位基本要求\n1、大专及以上学历；\n2、有电销、销售经验优先；\n3、能够熟练使用办公软件；\n4、学习能力和适应能力强，能够快速迭代，拥抱变化；\n5、积极主动、富有激情、具有良好的沟通能力；\n\n岗位亮点\n1.入职即开展带薪培训，减缓融入和适应的压力；\n2.入职即购买六险一金，并享受带薪年假；\n3.完善的晋升发展机制；\n4.每年一次免费健康体检；\n5.丰富的员工活动和每月团建活动；\n6.双休+法定节假日；","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4686369058","sourceKey":"meituan_social","company":"美团","title":"整合营销广告运营","city":"深圳市/北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4686369058&jobShareType=1","duty":"1. 营销策略制定围绕广告主营销目标为核心，深度理解美团无人机广告资源及跨部门整合营销广告资源，制定高效可行的广告营销策略及执行方案，策划事件营销总包方案（含视频/快闪/线下活动等），支持销售面向快消、医药、餐饮等行业客户的提案包装，提升方案中标率。并负责广告的落地执行与交付。\n2. 跨部门协同与资源整合与销售、产品、运营等团队紧密配合，推动品牌项目落地；协调内外部资源，推动美团内部跨部门协作及资源整合协同落地；可借助AI协同工具提升沟通效率与项目管理可视化程度。\n3. 品牌物料与内容输出，统筹品牌视觉体系、宣传物料、案例包装、方案模版、媒体通稿等内容产出，确保对外传播的专业度和一致性。\n4. 预算管理与渠道调优管理广告预算分配，结合AI预测模型评估渠道表现，优化投放节奏与项目毛利率，实现精细化运营。\n5. 知识沉淀与方法论复用沉淀优质营销案例，运用AI工具协助投后报告自动化生成与洞察提炼，总结可复用方法论并推动团队知识库建设。","requirements":"1.大学本科及以上学历，市场营销、广告、传媒或相关专业优先。\n具备5年以上整合营销或广告运营相关工作经验，有成功的方案策划与落地执行交付案例者优先。\n熟练使用AI辅助工具（如AIGC内容生成、智能文案撰写等）进行方案撰写与效率提升者优先。\n具备良好的沟通协调能力和项目管理能力，能主导推动复杂项目落地；对AI技术在营销领域的应用有敏锐嗅觉和学习热情，能够主动探索并引入新的AI工具/工作流以提升团队人效。","description":"部门介绍\n为了更好地提升城市即时配送的效率与体验，2017年，美团启动了无人机配送服务的探索，通过科技创新推动履约工具变革，加快建设空地协同的本地即时配送网络。\n在过去的六年里，美团无人机完成了飞行器、自动化机场及智能调度系统的研发工作，实现了研发设计、生产制造、运营运维全链条布局，达成了城市复杂场景物流无人机高频次、高密度、多天时、多天侯运行。\n2023年7月，美团无人机在上海发布了自主研发的第四代无人机，跟此前机型相比，新机型升级了环境适应能力，可在“零下20度至50度”的中雨、中雪、6级风、弱光等环境中稳定飞行，能够适应97%以上国内城市的自然环境要求。\n截至2024年12月，美团无人机已在深圳、北京、上海、广州、南京、迪拜等城市开通53条航线，并累计完成订单超40万单。即时零售配送服务覆盖了办公、社区、景区、市政公园、校园、医疗、图书馆等多种场景。在医疗场景中，美团无人机可围绕医疗血液、检验样本、院前急救物资、特殊药品等医疗物资配送需求建设端到端的全天时急送网络。\n\n岗位职责\n1. 营销策略制定围绕广告主营销目标为核心，深度理解美团无人机广告资源及跨部门整合营销广告资源，制定高效可行的广告营销策略及执行方案，策划事件营销总包方案（含视频/快闪/线下活动等），支持销售面向快消、医药、餐饮等行业客户的提案包装，提升方案中标率。并负责广告的落地执行与交付。\n2. 跨部门协同与资源整合与销售、产品、运营等团队紧密配合，推动品牌项目落地；协调内外部资源，推动美团内部跨部门协作及资源整合协同落地；可借助AI协同工具提升沟通效率与项目管理可视化程度。\n3. 品牌物料与内容输出，统筹品牌视觉体系、宣传物料、案例包装、方案模版、媒体通稿等内容产出，确保对外传播的专业度和一致性。\n4. 预算管理与渠道调优管理广告预算分配，结合AI预测模型评估渠道表现，优化投放节奏与项目毛利率，实现精细化运营。\n5. 知识沉淀与方法论复用沉淀优质营销案例，运用AI工具协助投后报告自动化生成与洞察提炼，总结可复用方法论并推动团队知识库建设。\n\n岗位基本要求\n1.大学本科及以上学历，市场营销、广告、传媒或相关专业优先。\n具备5年以上整合营销或广告运营相关工作经验，有成功的方案策划与落地执行交付案例者优先。\n熟练使用AI辅助工具（如AIGC内容生成、智能文案撰写等）进行方案撰写与效率提升者优先。\n具备良好的沟通协调能力和项目管理能力，能主导推动复杂项目落地；对AI技术在营销领域的应用有敏锐嗅觉和学习热情，能够主动探索并引入新的AI工具/工作流以提升团队人效。\n\n具备以下条件优先\n热爱互联网广告营销行业，具有极强的快速学习能力，研究过优秀广告营销案例并有个人心得者优先；\n参与过广告商业化资源/模式0-1探索周期的成功案例者优先；\n主导/参与过具有行业影响力（不限于营销破圈案例/获得过广告行业营销奖项）的项目；\n\n岗位亮点\n1. 加入快速发展的创新型企业，拥有广阔的职业发展空间。  \n2. 参与高影响力品牌项目，直接推动业务增长。  \n3. 深圳核心区域办公，团队氛围开放，鼓励创新与突破。  \n4. 提供具有竞争力的薪酬与完善的福利体系。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4138029704","sourceKey":"meituan_social","company":"美团","title":"工程审计专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4138029704&jobShareType=1","duty":"1.负责公司各类工程项目的管理审计，包括立项、招投标、合同执行、变更签证、结算等环节的合规性与合理性审查，项目类型涵盖IDC建设、门店及前置仓改造、商办综合体收尾、结算等；\n2.组织开展工程成本审计，重点审查工程量计算、定额套用、材料价格、变更签证的真实性与合理性，识别成本超支、浪费及潜在风险，提出优化建议并跟踪整改落实情况；\n3.独立完成审计项目的全流程执行，包括审计方案制定、现场勘察、资料审查、数据测算、底稿编制及审计报告撰写，能够对复杂工程技术问题做出专业判断；\n4.开展工程现场飞检与专项检查，核实施工过程与合同约定、设计文件、验收标准的符合性，发现工程质量与安全隐患；\n5.编制审计报告，向管理层汇报审计发现及改进建议，推动审计成果落地应用。","requirements":"1.大学本科及以上学历，工程管理、土木工程、电气工程、暖通空调等相关专业；\n2.具备5-8年工程审计、工程造价或工程项目管理相关工作经验，能够独立负责审计项目的全流程执行；\n3.具备扎实的工程技术功底，熟悉施工工艺、工程计量规则及造价编制规范；同时具备一定的造价管理能力，能够独立完成工程量复核与结算审计；\n4.熟练使用工程计价软件（如广联达、新点等），能够独立完成工程量计算与组价复核；\n5.具备较强的技术学习能力，能够快速理解IDC等新技术领域的工程特点；\n6.熟悉国家工程建设相关法律法规、招投标制度及工程造价管理规范；\n7.具备较强的数据分析能力、逻辑思维能力和沟通协调能力，能够适应较频繁的出差及现场工作；\n8.持有CIA、一级建造师、一级造价工程师等资格证书者优先。","description":"部门介绍\n财务平台负责公司整体和各业务层面的财务管理工作，通过建设专业、全面、复合的财务管理能力和与业务经营的紧密结合来支持公司健康发展。目前财务平台拥有财务会计、财务报告、资金管理、税务管理、财务共享、财务系统、规划分析、财务BP和内控内审等主要工作方向。我们的目标是建设业界一流的财务管理能力和经营支持体系，为公司战略的正确落地、投入效率的持续提升、业务价值的不断增长保驾护航。欢迎加入财务平台，携手一起向未来！\n\n岗位职责\n1.负责公司各类工程项目的管理审计，包括立项、招投标、合同执行、变更签证、结算等环节的合规性与合理性审查，项目类型涵盖IDC建设、门店及前置仓改造、商办综合体收尾、结算等；\n2.组织开展工程成本审计，重点审查工程量计算、定额套用、材料价格、变更签证的真实性与合理性，识别成本超支、浪费及潜在风险，提出优化建议并跟踪整改落实情况；\n3.独立完成审计项目的全流程执行，包括审计方案制定、现场勘察、资料审查、数据测算、底稿编制及审计报告撰写，能够对复杂工程技术问题做出专业判断；\n4.开展工程现场飞检与专项检查，核实施工过程与合同约定、设计文件、验收标准的符合性，发现工程质量与安全隐患；\n5.编制审计报告，向管理层汇报审计发现及改进建议，推动审计成果落地应用。\n\n岗位基本要求\n1.大学本科及以上学历，工程管理、土木工程、电气工程、暖通空调等相关专业；\n2.具备5-8年工程审计、工程造价或工程项目管理相关工作经验，能够独立负责审计项目的全流程执行；\n3.具备扎实的工程技术功底，熟悉施工工艺、工程计量规则及造价编制规范；同时具备一定的造价管理能力，能够独立完成工程量复核与结算审计；\n4.熟练使用工程计价软件（如广联达、新点等），能够独立完成工程量计算与组价复核；\n5.具备较强的技术学习能力，能够快速理解IDC等新技术领域的工程特点；\n6.熟悉国家工程建设相关法律法规、招投标制度及工程造价管理规范；\n7.具备较强的数据分析能力、逻辑思维能力和沟通协调能力，能够适应较频繁的出差及现场工作；\n8.持有CIA、一级建造师、一级造价工程师等资格证书者优先。\n\n具备以下条件优先\n1.有IDC数据中心、商业门店装修或物流仓储工程项目审计经验者优先；\n2.有互联网或科技企业基建工程审计背景者优先。\n\n岗位亮点\n接触多元业务场景，涵盖互联网基础设施（IDC）、零售门店、商办综合体等多种工程项目类型，专业成长空间大。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4301295312","sourceKey":"meituan_social","company":"美团","title":"LongCat大模型 - Agent 评测产品经理（欢迎算法/工程转型）","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4301295312&jobShareType=1","duty":"1. Agent能力评测体系设计：围绕 OpenClaw、Claude Code 等主流 Agent 框架，设计并落地适配长程任务场景的评测体系，确保 Agent 在真实约束下的交付稳定性与可度量性。\n2. 评测流程与资源建设：设计 Coding、数据分析等核心生产力场景的端到端评测流程，搭建自动化评测数据生产与自动化 Rubrics 生成的标准化 pipeline；同时建设具备强技术背景的专家标注资源池，确保 Case 评审、效果判定等关键环节的专业度与一致性。\n3.数据闭环与模型策略驱动：将评测数据转化为模型迭代的策略输入，建立\"评测→归因→策略建议→效果验证\"的数据驱动闭环，推动 Agent 能力持续提升形成飞轮。\n4.前沿框架跟踪与评测策略适配：持续跟踪 OpenClaw、Claude Code 及行业前沿 Agent 框架的能力演进与架构变化，及时调整评测策略与度量标准，确保评测体系与 Agent 技术范式同步迭代。","requirements":"1. 本科及以上学历，1年以上大模型评测或智能体应用落地相关经验。\n2. 追求评测方案的科学性与细节完备性，并对新范式保持高敏感，关注 Claude Code / OpenClaw 等 Agent 工具链演进，并能转化为相应评测策略。\n3. 对评测、观测、数据闭环有直觉，具备基于数据的归因分析能力。\n4. 具有良好的沟通能力、评测资源搭建与管理能力、跨团队合作精神以及较强的问题解决能力。","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n1. Agent能力评测体系设计：围绕 OpenClaw、Claude Code 等主流 Agent 框架，设计并落地适配长程任务场景的评测体系，确保 Agent 在真实约束下的交付稳定性与可度量性。\n2. 评测流程与资源建设：设计 Coding、数据分析等核心生产力场景的端到端评测流程，搭建自动化评测数据生产与自动化 Rubrics 生成的标准化 pipeline；同时建设具备强技术背景的专家标注资源池，确保 Case 评审、效果判定等关键环节的专业度与一致性。\n3.数据闭环与模型策略驱动：将评测数据转化为模型迭代的策略输入，建立\"评测→归因→策略建议→效果验证\"的数据驱动闭环，推动 Agent 能力持续提升形成飞轮。\n4.前沿框架跟踪与评测策略适配：持续跟踪 OpenClaw、Claude Code 及行业前沿 Agent 框架的能力演进与架构变化，及时调整评测策略与度量标准，确保评测体系与 Agent 技术范式同步迭代。\n\n岗位基本要求\n1. 本科及以上学历，1年以上大模型评测或智能体应用落地相关经验。\n2. 追求评测方案的科学性与细节完备性，并对新范式保持高敏感，关注 Claude Code / OpenClaw 等 Agent 工具链演进，并能转化为相应评测策略。\n3. 对评测、观测、数据闭环有直觉，具备基于数据的归因分析能力。\n4. 具有良好的沟通能力、评测资源搭建与管理能力、跨团队合作精神以及较强的问题解决能力。\n\n具备以下条件优先\n1.计算机相关专业或技术背景，欢迎算法、工程背景转型同学\n2.理解大模型/Agent 基本工作机制\n3.在工作中能熟练使用 AI 提效\n\n岗位亮点\n1. 定义行业评测标准：主导构建覆盖\"认知-决策-执行\"全链路的Agent评测体系，推动 Agent 从 Demo 走向生产。\n2. 前沿方向：AI Agent 正从\"能对话\"走向\"能交付\"，处于范式变革的关键节点。\n3. 转型友好：明确欢迎算法/工程背景转型，从\"实现能力\"走向\"定义效果\"，从\"写代码/训模型\"走向\"搭体系/做闭环\"。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4665727430","sourceKey":"meituan_social","company":"美团","title":"下沉市场-外卖供给专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4665727430&jobShareType=1","duty":"1.想清楚下沉市场该卖什么货。看数据、看趋势、看行业，判断哪些品类、哪些品牌值得重点投入，然后把结论变成各个城市能照着执行的方案。\n2.建一套好用的系统，把供给招商往上游推。让商家商品尽量从商家直接过来，将商家怎么谈进来、商品怎么快速上架、活动怎么覆盖、收入怎么管理，这四件事都要在系统里跑顺。\n3.让系统越来越聪明（AI建设）。找什么线索、选什么品、定什么价、给什么资源——尽量交给系统去做，人只管最关键的决策。\n4.把项目推动起来。定清楚每个阶段做什么、在哪试、什么算成功，然后拉着技术、产品、区域团队一起把它做出来，并对最终效果负责。","requirements":"1.本科以上，3年以上互联网平台、电商或本地生活相关经验，其中至少 2年做过供给、商品或商家侧的活。\n2.从零搭过业务系统或者作业平台，知道一个想法怎么变成产品，也知道产品怎么才能真的被用起来。\n3.对数字敏感，能自己拉数、自己分析、自己得出结论，而不是等着别人给答案。\n4.推得动事。没有汇报关系也能把人拉到一起干活；愿意去城市跑一跑，看看一线到底怎么用你做的东西。\n5.知道 AI 能干什么、不能干什么，不会把它当噱头。做过相关落地项目的加分。","description":"部门介绍\n美团核心本地商业-下沉市场发展部于2015年成立，通过招募优质的合作商伙伴并对其业务经营能力、组织能力等赋能，以期为下沉城市提供一站式的本地生活服务。\n下沉市场发展部的业务场景涵盖了外卖餐饮、团购、拼好饭、闪购、医药等多元化的生活服务领域，同时搭建了一套稳定、高效的即时配送网络，为更多本地用户提供品质化、多样化、便捷高效的生活服务体验，为当地商户提供数字化发展机遇、提升数字化水平，为社会创造更多的就地就业机会。\n截至2024年6月，下沉市场发展部已开拓全国4000+县区市，帮助百万商户实现本地生活服务数字化，日订单量突破千万，为数十万名骑手提供就业岗位，让本地生活服务逐渐成长为地方新基建，实现美团“帮助大家吃得更好，生活更好”的使命！\n\n岗位职责\n1.想清楚下沉市场该卖什么货。看数据、看趋势、看行业，判断哪些品类、哪些品牌值得重点投入，然后把结论变成各个城市能照着执行的方案。\n2.建一套好用的系统，把供给招商往上游推。让商家商品尽量从商家直接过来，将商家怎么谈进来、商品怎么快速上架、活动怎么覆盖、收入怎么管理，这四件事都要在系统里跑顺。\n3.让系统越来越聪明（AI建设）。找什么线索、选什么品、定什么价、给什么资源——尽量交给系统去做，人只管最关键的决策。\n4.把项目推动起来。定清楚每个阶段做什么、在哪试、什么算成功，然后拉着技术、产品、区域团队一起把它做出来，并对最终效果负责。\n\n岗位基本要求\n1.本科以上，3年以上互联网平台、电商或本地生活相关经验，其中至少 2年做过供给、商品或商家侧的活。\n2.从零搭过业务系统或者作业平台，知道一个想法怎么变成产品，也知道产品怎么才能真的被用起来。\n3.对数字敏感，能自己拉数、自己分析、自己得出结论，而不是等着别人给答案。\n4.推得动事。没有汇报关系也能把人拉到一起干活；愿意去城市跑一跑，看看一线到底怎么用你做的东西。\n5.知道 AI 能干什么、不能干什么，不会把它当噱头。做过相关落地项目的加分。\n\n岗位亮点\n下沉市场外卖供给能力建设正是投入期，钱、人、决策速度都跟得上，试错空间也大。这个岗位难得的地方在于，规划和落地都归你——从判断该卖什么，到做出系统，再到看着一线用起来，一整条链路你都能碰到，比只做其中一段的岗位长得快得多。\n\n平台不是从白纸开始，底层已经搭好，几条核心业务也接进来了，有真实的体量撑着，属于业内不多见的\"能拿真业务练 AI\"的场子。地基有了、方向也清楚，缺的就是一个能把它推到出成果的人。\n\n另外，你会直接和业务负责人对话，参与最上层的策略讨论——想快速看懂一门生意是怎么跑起来的，这是个很好的位置。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4579614336","sourceKey":"meituan_social","company":"美团","title":"商家智能-AI Builder","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4579614336&jobShareType=1","duty":"本岗位负责美团金融服务平台商家财务AI产品的规划与设计。作为AI-Builder，充分利用大模型和Agent技术，为公司千万量级的商户提供更优质的财务服务和产品，为每一位商家提供个性化的最优金融产品配置。\n你将和优秀的算法、工程和运营团队一起，深入了解广大中小商家的需求，端到端地探索AI时代商家金融服务新形态，推动新产品的上线和优化。","requirements":"1.AI Agent：有真实上线的 Agent 工程交付经验，做过评测、归因与迭代闭环\n\n2.B端商家经验：对餐饮、酒旅等生活服务商家产品有一定研发经验。对国内企业财税系统有经验plus","description":"部门介绍\n美团金融服务平台成立于2016年，以“场景+金融”模式，携手合作伙伴构建开放生态，为美团平台用户和商户提供底层账户、支付通道、信贷、保险和理财等金融解决方案。我们致力于以科技为核心，助力金融机构打通金融普惠“最后一公里”。我们期待与大家共同完成每一件平凡而卓越的事情，一起为用户提供优质的产品体验，守护用户的资金安全，让生活变得更美好。\n\n岗位职责\n本岗位负责美团金融服务平台商家财务AI产品的规划与设计。作为AI-Builder，充分利用大模型和Agent技术，为公司千万量级的商户提供更优质的财务服务和产品，为每一位商家提供个性化的最优金融产品配置。\n你将和优秀的算法、工程和运营团队一起，深入了解广大中小商家的需求，端到端地探索AI时代商家金融服务新形态，推动新产品的上线和优化。\n\n岗位基本要求\n1.AI Agent：有真实上线的 Agent 工程交付经验，做过评测、归因与迭代闭环\n\n2.B端商家经验：对餐饮、酒旅等生活服务商家产品有一定研发经验。对国内企业财税系统有经验plus\n\n岗位亮点\n1.在千万量级商家的生活服务平台上推动商家AI转型——你将定义商家经营AI产品的新形态。\n2.平台资源丰富（海量真实金融数据、充足算力、各类SOTA模型），支持快速验证与规模化落地。\n3.核心链路负责人，从 0 主导产品设计与 Agent 迭代机制的设计与落地，自主度高。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3397866093","sourceKey":"meituan_social","company":"美团","title":"大模型推理服务专家","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3397866093&jobShareType=1","duty":"1.负责AI Agent核心架构设计与开发，不断优化和提升大模型Agent的技术框架，构建高可用、低延时的分布式系统；\n2.开发多智能体协作系统，实现复杂场景下的任务拆解、工具调用，包括DeepResearch、通用智能体等Multi Agent；\n3.关注公司内外AI Agent领域的技术发展趋势，积极开展前瞻性技术研究，探索将新技术和理念融入现有系统的可行性，持续推动公司Agent技术的创新升级与竞争力提升；\n4.与算法团队紧密配合，推动LLM、RAG等技术与工程系统的深度集成，持续迭代项目能力，提高服务质量。","requirements":"1.具备5年以上Java/Python开发经验，精通分布式系统开发与性能优化；\n2.有AI应用框架或平台研发经验，熟悉大语言模型应用开发流程，了解LangChain、Auto GPT等主流框架，掌握Prompt工程、RAG及大模型工具集成与调用；\n3.拥有大模型应用开发或相关人工智能项目经验，优先有对话系统、搜索推荐系统、大规模机器学习系统等领域经验者；\n4.对新技术充满好奇心和敏锐度，具备出色的复杂问题分析与解决能力，拥有良好的沟通能力和团队协作精神，能够高效推动跨团队合作。","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n1.负责AI Agent核心架构设计与开发，不断优化和提升大模型Agent的技术框架，构建高可用、低延时的分布式系统；\n2.开发多智能体协作系统，实现复杂场景下的任务拆解、工具调用，包括DeepResearch、通用智能体等Multi Agent；\n3.关注公司内外AI Agent领域的技术发展趋势，积极开展前瞻性技术研究，探索将新技术和理念融入现有系统的可行性，持续推动公司Agent技术的创新升级与竞争力提升；\n4.与算法团队紧密配合，推动LLM、RAG等技术与工程系统的深度集成，持续迭代项目能力，提高服务质量。\n\n岗位基本要求\n1.具备5年以上Java/Python开发经验，精通分布式系统开发与性能优化；\n2.有AI应用框架或平台研发经验，熟悉大语言模型应用开发流程，了解LangChain、Auto GPT等主流框架，掌握Prompt工程、RAG及大模型工具集成与调用；\n3.拥有大模型应用开发或相关人工智能项目经验，优先有对话系统、搜索推荐系统、大规模机器学习系统等领域经验者；\n4.对新技术充满好奇心和敏锐度，具备出色的复杂问题分析与解决能力，拥有良好的沟通能力和团队协作精神，能够高效推动跨团队合作。\n\n具备以下条件优先\n1.有技术钻研精神，熟悉主流大模型架构（如Transformer，Bert等），理解其底层原理（自注意力机制、位置编码、训练和推理优化等）者优先；\n2.有较强的逻辑思维能力，善于分析、归纳、描述、沟通、和解决问题。\n\n岗位亮点\n1.你将加入优秀的团队，一起成长：团队高阶研发密度大，汇聚行业大牛，分享交流活动多； \n2.你将负责前沿技术的探究：和迅速发展的大模型行业一起成长，未来拥有广阔的应用前景； \n3.你将拥有快速成长的空间，一起见证技术落地的喜悦，部门业务处于快速发展阶段，应用场景广泛，业务落地场景丰富，复杂度高，挑战性大； \n4.你将拥有更广阔的视野：有行业影响力的培训和学习交流机会、参加国际优质学术会议等。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4676767074","sourceKey":"meituan_social","company":"美团","title":"闪购-歪马-前置仓主管-乌鲁木齐","city":"乌鲁木齐市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4676767074&jobShareType=1","duty":"1.管辖10-13个酒水前置仓的业务开拓和日常管理;\n2.团队搭建，完成前置仓团队搭建，人员选用育励汰;\n3.具备一定的销售管理能力，有进行目标拆解和过程管理能力，承担区域增长目标，完成地推获客，留存等增长指标;\n4.对前置仓的商品进行管理，并不断提高前置仓操作规范性;\n5.保障前置仓的日常营运，确保配送时效，前置仓内商品准确，保障用户体验;\n6.有较好的数据意识，能过通过数据发现前置仓运行中的问题;\n7.有较好的成本意识，能合理的管控仓内日常消耗品，地推赠品等耗材的管理。","requirements":"1.有1-3年的前置仓履约或直销管理经验，熟悉零售业务，对前置仓管理，商品管理等有一定经验;\n2.熟悉即时配业务特性，关注用户体验;\n3.有较好的团队管理，人员培养的经验和方法沉淀;\n4.有价值观正，能够横向协同多部门，达成公司业务指标;\n5.有较好的数据敏感度，能够透过数据发现问题。","description":"部门介绍\n美团闪购是美团旗下的即时零售平台，依托即时配送能力，连接本地零售供给，满足消费者30分钟万物到家的即时需求。美团闪购涵盖超市便利、食材、水果、鲜花绿植、休闲零食、酒水饮料、数码家电、美妆个护、母婴玩具、日用百货、服饰鞋帽、宠物等诸多品类，业务覆盖全国近3,000个县市区旗，每日百万级在岗骑手，以高效的配送、丰富的品类和广泛的覆盖，为美团数亿用户带来便捷的生活体验，积极助力实体零售线上化转型，提升本地商业活力。\n\n岗位职责\n1.管辖10-13个酒水前置仓的业务开拓和日常管理;\n2.团队搭建，完成前置仓团队搭建，人员选用育励汰;\n3.具备一定的销售管理能力，有进行目标拆解和过程管理能力，承担区域增长目标，完成地推获客，留存等增长指标;\n4.对前置仓的商品进行管理，并不断提高前置仓操作规范性;\n5.保障前置仓的日常营运，确保配送时效，前置仓内商品准确，保障用户体验;\n6.有较好的数据意识，能过通过数据发现前置仓运行中的问题;\n7.有较好的成本意识，能合理的管控仓内日常消耗品，地推赠品等耗材的管理。\n\n岗位基本要求\n1.有1-3年的前置仓履约或直销管理经验，熟悉零售业务，对前置仓管理，商品管理等有一定经验;\n2.熟悉即时配业务特性，关注用户体验;\n3.有较好的团队管理，人员培养的经验和方法沉淀;\n4.有价值观正，能够横向协同多部门，达成公司业务指标;\n5.有较好的数据敏感度，能够透过数据发现问题。\n\n具备以下条件优先\n熟悉零售业务，有前置仓管理，商品管理、蓝领管理经验优先\n\n岗位亮点\n[歪马业务]是【到家事业群/闪购业务部]下新成立的，由前线业务+运营/采购+产品全闭环的组织\n2.歪马业务聚焦于酒类万亿市场，通过中心仓+前置仓、平台自营模式，为用户提供15分钟送达的买酒业务\n3.业务当前正处于0-1的快速迭代时期，可以从0-1参与新业务的产品建设\n4.全方位深入业务，在全闭环的组织里感受不同职能彼此的输入/输出，同时可以参与业务模式的定义\n5.足够宽的Scope，深入参与自营零售业务的经营","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4578075426","sourceKey":"meituan_social","company":"美团","title":"品类运营储备","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4578075426&jobShareType=1","duty":"1. 负责品类商品的日常运营，包括商品选品、定价策略、库存管理及促销规划。  \n2. 分析品类销售数据与市场趋势，制定并优化品类发展策略，提升销售转化与毛利率。  \n3. 协同供应链、采购及物流团队，保障商品供应稳定性与周转效率。  \n4. 监控商品动态与行业变化，输出品类洞察报告，支持业务决策。","requirements":"1. 大学本科及以上学历，6年以上商品运营或供应链管理相关工作经验。  \n2. 具备较强的数据分析能力。  \n3. 熟悉电商或零售行业品类运营逻辑，有成功品类增长案例者优先。  \n4. 具备优秀的沟通协调能力与跨部门协作经验，能独立推动项目落地。","description":"部门介绍\n美团HR的使命是“建设有生命力的组织，为客户和社会创造价值。” 我们认为HR的工作不是以自身“专业”为中心，而是要建设有助于员工发挥创造力的环境，支持他们更好地为外部客户和社会创造价值，也实现组织自身的进化和传承。在这个过程中，我们的每位HR同学都是“业务的战略合作伙伴、组织能力的建设者、美团精神的布道者、员工的成长伙伴”。我们要设计面向长期支撑组织有效运转的机制，我们要求真务实地帮业务解决发展中的问题和阵痛，我们要支持每一位员工历经磨炼收获成长。我们要影响和驱动让世界更美好的变化发生。如果这也是你追求的，欢迎加入美团HR，与我们一路同行！\n\n岗位职责\n1. 负责品类商品的日常运营，包括商品选品、定价策略、库存管理及促销规划。  \n2. 分析品类销售数据与市场趋势，制定并优化品类发展策略，提升销售转化与毛利率。  \n3. 协同供应链、采购及物流团队，保障商品供应稳定性与周转效率。  \n4. 监控商品动态与行业变化，输出品类洞察报告，支持业务决策。\n\n岗位基本要求\n1. 大学本科及以上学历，6年以上商品运营或供应链管理相关工作经验。  \n2. 具备较强的数据分析能力。  \n3. 熟悉电商或零售行业品类运营逻辑，有成功品类增长案例者优先。  \n4. 具备优秀的沟通协调能力与跨部门协作经验，能独立推动项目落地。\n\n岗位亮点\n1. 参与核心品类战略规划，具备广阔的成长空间与业务影响力。  \n2. 团队氛围开放，鼓励创新与数据驱动决策。  \n3. 工作地点位于北京核心商圈，交通便利，办公环境优越。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4528791808","sourceKey":"meituan_social","company":"美团","title":"小象售后退款体验策略运营","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4528791808&jobShareType=1","duty":"1、体验策略制定：负责小象线下店退款与售后体验的全链路策略设计与落地，同时为用户体验和业务成本负责；\n2、用户洞察：能够真正站在用户角度思考体验工作，深入用户全流程的体验洞察，提炼用户体验的关键需求和痛点；\n3、方案创新：深入理解业务特性，并结合实际用户场景提出有针对性、可落地的创新解决方案；\n4、跨团队协同：高效协同推动合作伙伴，协调相关资源，推动运营策略和产品方案落地。","requirements":"1、本科及以上学历，3年以上售后或用户体验策略运营经验；\n2、结果导向、自驱力强，能深入一线、对用户体验敏感；\n3、具备强业务策略思维与数据分析能力，善于跨团队协作；\n4、熟练使用SQL；\n5、对AI技术在相关领域的应用有一定的思考或实践。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1、体验策略制定：负责小象线下店退款与售后体验的全链路策略设计与落地，同时为用户体验和业务成本负责；\n2、用户洞察：能够真正站在用户角度思考体验工作，深入用户全流程的体验洞察，提炼用户体验的关键需求和痛点；\n3、方案创新：深入理解业务特性，并结合实际用户场景提出有针对性、可落地的创新解决方案；\n4、跨团队协同：高效协同推动合作伙伴，协调相关资源，推动运营策略和产品方案落地。\n\n岗位基本要求\n1、本科及以上学历，3年以上售后或用户体验策略运营经验；\n2、结果导向、自驱力强，能深入一线、对用户体验敏感；\n3、具备强业务策略思维与数据分析能力，善于跨团队协作；\n4、熟练使用SQL；\n5、对AI技术在相关领域的应用有一定的思考或实践。\n\n岗位亮点\n公司核心业务且高速发展中，团队氛围好，能深入接触零售业。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4686133983","sourceKey":"meituan_social","company":"美团","title":"高级物流采购经理","city":"深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4686133983&jobShareType=1","duty":"1. 负责搭建和持续优化订单物流内外部运作机制，改进运作绩效；\n2. 负责物流供应商资源开发、筛选、评估和引入；建立物流供应商准入标准，包括资质、网络覆盖、服务能力、价格水平、系统能力、风险控制等；\n3. 负责物流供应商的日常运营管理，包括运输、仓储、快递、零担、整车等相关服务；建立供应商分级管理机制，对核心、备用、淘汰供应商进行动态管理；定期组织供应商会议，推动问题整改和服务提升；\n4. 负责物流费用预算、成本测算；通过线路优化、供应商整合、计费模式优化等方式降低物流成本；\n5. 建立物流供应商KPI考核体系，包括准时率、签收率、破损率、异常率、投诉率、回单及时率等；跟踪供应商服务表现，输出月度/季度绩效报告；对服务不达标的供应商制定改善计划，并跟进整改结果；\n6. 物流异常与风险管理：处理运输延误、货损货差、客户投诉、异常赔付等问题；建立物流风险预警机制，保障旺季、促销期、节假日等关键节点的物流稳定；维护备用供应商池，确保业务连续性；\n7. 梳理并优化供应商管理流程，包括准入、报价、合同、对账、结算、考核、淘汰等，提升物流管理数据化、标准化和自动化水平。","requirements":"1.本科及以上学历，物流管理、供应链管理、交通运输、工商管理等相关专业优先；\n2.5年以上物流、供应链、运输、仓配或3PL管理经验，其中2年以上物流供应商管理或物流采购经验；\n3.熟悉物流供应商开发、招投标、合同管理、KPI考核、成本控制及异常处理流程；\n4.熟悉整车、零担、快递、仓储、跨境等一种或多种物流业务模式；具备较强的商务谈判能力、成本分析能力、供应商管理能力和数据分析能力；具备物流数据分析及报告输出能力；\n5.具备良好的沟通协调能力、问题解决能力和项目推动能力。","description":"部门介绍\n为了更好地提升城市即时配送的效率与体验，2017年，美团启动了无人机配送服务的探索，通过科技创新推动履约工具变革，加快建设空地协同的本地即时配送网络。\n在过去的六年里，美团无人机完成了飞行器、自动化机场及智能调度系统的研发工作，实现了研发设计、生产制造、运营运维全链条布局，达成了城市复杂场景物流无人机高频次、高密度、多天时、多天侯运行。\n2023年7月，美团无人机在上海发布了自主研发的第四代无人机，跟此前机型相比，新机型升级了环境适应能力，可在“零下20度至50度”的中雨、中雪、6级风、弱光等环境中稳定飞行，能够适应97%以上国内城市的自然环境要求。\n截至2024年12月，美团无人机已在深圳、北京、上海、广州、南京、迪拜等城市开通53条航线，并累计完成订单超40万单。即时零售配送服务覆盖了办公、社区、景区、市政公园、校园、医疗、图书馆等多种场景。在医疗场景中，美团无人机可围绕医疗血液、检验样本、院前急救物资、特殊药品等医疗物资配送需求建设端到端的全天时急送网络。\n\n岗位职责\n1. 负责搭建和持续优化订单物流内外部运作机制，改进运作绩效；\n2. 负责物流供应商资源开发、筛选、评估和引入；建立物流供应商准入标准，包括资质、网络覆盖、服务能力、价格水平、系统能力、风险控制等；\n3. 负责物流供应商的日常运营管理，包括运输、仓储、快递、零担、整车等相关服务；建立供应商分级管理机制，对核心、备用、淘汰供应商进行动态管理；定期组织供应商会议，推动问题整改和服务提升；\n4. 负责物流费用预算、成本测算；通过线路优化、供应商整合、计费模式优化等方式降低物流成本；\n5. 建立物流供应商KPI考核体系，包括准时率、签收率、破损率、异常率、投诉率、回单及时率等；跟踪供应商服务表现，输出月度/季度绩效报告；对服务不达标的供应商制定改善计划，并跟进整改结果；\n6. 物流异常与风险管理：处理运输延误、货损货差、客户投诉、异常赔付等问题；建立物流风险预警机制，保障旺季、促销期、节假日等关键节点的物流稳定；维护备用供应商池，确保业务连续性；\n7. 梳理并优化供应商管理流程，包括准入、报价、合同、对账、结算、考核、淘汰等，提升物流管理数据化、标准化和自动化水平。\n\n岗位基本要求\n1.本科及以上学历，物流管理、供应链管理、交通运输、工商管理等相关专业优先；\n2.5年以上物流、供应链、运输、仓配或3PL管理经验，其中2年以上物流供应商管理或物流采购经验；\n3.熟悉物流供应商开发、招投标、合同管理、KPI考核、成本控制及异常处理流程；\n4.熟悉整车、零担、快递、仓储、跨境等一种或多种物流业务模式；具备较强的商务谈判能力、成本分析能力、供应商管理能力和数据分析能力；具备物流数据分析及报告输出能力；\n5.具备良好的沟通协调能力、问题解决能力和项目推动能力。\n\n具备以下条件优先\n1. 具备无人机进出口的物流经验者优先；\n2. 具备中东、东亚、欧洲等地的进出口物流经验者优先；\n\n岗位亮点\n低空经济的先行者和开拓展，搭建物流运作体系。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4601955918","sourceKey":"meituan_social","company":"美团","title":"外卖行业运营","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4601955918&jobShareType=1","duty":"1、负责餐饮品类客户运营策略的制定与高效落地，借助大模型辅助数据洞察和 AI 智能客户分层工具，基于品类特性、商户规模、生命周期等多维度深度分析，结合行业趋势与竞争格局，自动识别高潜力客群与增长机会点，设计可量化、可执行的策略方案，持续优化关键业务指标（如广告渗透率、ARPU、留存率等）。\n2、搭建并持续迭代科学、动态的客户分层运营体系，针对头部KA客户提供定制化、高价值的广告运营服务，利用 AI 辅助复盘工具自动生成投放效果诊断报告与预算规划建议，提升复盘效率与标准化水平；打造可复制的标杆案例，显著提升客户广告投放效果、满意度与长期合作意愿，驱动公司效果广告收入目标达成。\n3、主导广告产品在餐饮行业的场景化案例沉淀与包装，**借助 AI 工具（如大模型辅助文档生成、知识库自动整理）**系统提炼产品价值与成功方法论，赋能销售与BD团队；同时深入一线，通过 AI 辅助用户访谈分析工具批量归类客户反馈，精准识别体验痛点与功能缺口，高效协同产品、技术、算法等中台团队推动产品优化与能力升级。","requirements":"1、5年以上互联网广告、本地生活平台或效果营销相关经验，其中至少2年具备团队管理或跨职能复杂项目统筹经验，能主导端到端策略落地，并在快节奏环境中保持高效输出；具备将 AI 工具融入日常工作流的实践经验，能带领团队探索 AI 辅助运营提效的落地路径。\n2、具备扎实的数据分析能力，熟练使用数据分析工具及 AI 辅助分析手段（如大模型自然语言问数、AI 智能归因分析工具），能独立完成从数据提取到业务洞察的全链路分析，并以数据驱动策略迭代与决策。\n3、对餐饮行业有深刻理解，熟悉连锁品牌、区域龙头、中小商户等不同客群的经营逻辑、营销诉求与决策链路，能借助 AI 工具批量生成客户画像与行业洞察报告，具备前瞻性行业洞察力，能预判品类演进方向并提前布局运营抓手。\n4、具备极强的跨部门协同与推动力，善于在产品、运营、销售、技术等多方角色间建立共识、整合资源、对齐目标；熟练使用 AI 辅助会议纪要生成、任务拆解等工具提升协同效率，同时拥有优秀的沟通表达与影响力，能向上汇报、向下赋能、横向协同。\n5、有韧性，面对激烈竞争、业绩压力或突发变化时，能快速调整策略、稳定团队、聚焦核心，始终以结果为导向推进工作。对 AI 工具保持持续学习热情，能主动探索新工具并应用于实际业务场景。","description":"部门介绍\n商业增值部是服务于美团核心本地商业客户的增值服务平台，覆盖餐饮、即时零售、医药、休闲娱乐、丽人医美、生活服务、酒旅度假等业务领域。我们致力于构建健康的本地商业生态，通过为平台客户和消费者提供符合其需求的多元、便捷、高效的商业产品和服务，帮助生态伙伴提高效率、优化经营、实现持续健康发展，推动本地商业数字化营销的发展，促进商业生态繁荣。作为本地商业的头部平台，我们为产品、运营、商务、技术、商业分析等领域人才提供广阔的发展空间。诚邀你加入美团商业增值团队，共筑本地商业的健康繁荣生态！\n\n岗位职责\n1、负责餐饮品类客户运营策略的制定与高效落地，借助大模型辅助数据洞察和 AI 智能客户分层工具，基于品类特性、商户规模、生命周期等多维度深度分析，结合行业趋势与竞争格局，自动识别高潜力客群与增长机会点，设计可量化、可执行的策略方案，持续优化关键业务指标（如广告渗透率、ARPU、留存率等）。\n2、搭建并持续迭代科学、动态的客户分层运营体系，针对头部KA客户提供定制化、高价值的广告运营服务，利用 AI 辅助复盘工具自动生成投放效果诊断报告与预算规划建议，提升复盘效率与标准化水平；打造可复制的标杆案例，显著提升客户广告投放效果、满意度与长期合作意愿，驱动公司效果广告收入目标达成。\n3、主导广告产品在餐饮行业的场景化案例沉淀与包装，**借助 AI 工具（如大模型辅助文档生成、知识库自动整理）**系统提炼产品价值与成功方法论，赋能销售与BD团队；同时深入一线，通过 AI 辅助用户访谈分析工具批量归类客户反馈，精准识别体验痛点与功能缺口，高效协同产品、技术、算法等中台团队推动产品优化与能力升级。\n\n岗位基本要求\n1、5年以上互联网广告、本地生活平台或效果营销相关经验，其中至少2年具备团队管理或跨职能复杂项目统筹经验，能主导端到端策略落地，并在快节奏环境中保持高效输出；具备将 AI 工具融入日常工作流的实践经验，能带领团队探索 AI 辅助运营提效的落地路径。\n2、具备扎实的数据分析能力，熟练使用数据分析工具及 AI 辅助分析手段（如大模型自然语言问数、AI 智能归因分析工具），能独立完成从数据提取到业务洞察的全链路分析，并以数据驱动策略迭代与决策。\n3、对餐饮行业有深刻理解，熟悉连锁品牌、区域龙头、中小商户等不同客群的经营逻辑、营销诉求与决策链路，能借助 AI 工具批量生成客户画像与行业洞察报告，具备前瞻性行业洞察力，能预判品类演进方向并提前布局运营抓手。\n4、具备极强的跨部门协同与推动力，善于在产品、运营、销售、技术等多方角色间建立共识、整合资源、对齐目标；熟练使用 AI 辅助会议纪要生成、任务拆解等工具提升协同效率，同时拥有优秀的沟通表达与影响力，能向上汇报、向下赋能、横向协同。\n5、有韧性，面对激烈竞争、业绩压力或突发变化时，能快速调整策略、稳定团队、聚焦核心，始终以结果为导向推进工作。对 AI 工具保持持续学习热情，能主动探索新工具并应用于实际业务场景。\n\n岗位亮点\n成长空间大，扁平化管理，AI氛围好且落地性极高","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4686627348","sourceKey":"meituan_social","company":"美团","title":"商家履约运营","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4686627348&jobShareType=1","duty":"1.负责商家履约到仓环节，基于不同的履约场景，建立标准化监控、风险识别及管控机制，优化时效、缺货、质量等履约指标。\n2.协同供应链、仓储、物流等团队，推动履约环节的标准制定与落地执行。\n3.分析业务数据，持续识别履约链路的流程机会点，给出有效建议，提升各环节运营效率。\n4.建立并维护商家履约相关SOP，确保运营流程规范化和可复制性。\n5.学习并使用AI在商家履约场景中的应用，如智能监控预警、异常自动识别、数据分析自动化等。","requirements":"1.大学本科及以上学历，供应链管理、物流管理或相关专业背。\n2.具备3年以上采购与供应链管理经验，熟悉电商行业的供应链流程和操作规范，具备较强的数据分析能力。\n3.具备良好的沟通能力和团队合作精神，能够有效领导团队完成工作目标。\n4.具备较强的数据分析能力，熟练使用SQL等工具进行数据处理。\n5.具备良好的沟通协调能力，能够跨团队协作推动项目落地。\n6.具备AI工具应用能力，能够利用大模型、AI Agent等工具辅助数据分析、流程优化及异常识别，提升工作效率。","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1.负责商家履约到仓环节，基于不同的履约场景，建立标准化监控、风险识别及管控机制，优化时效、缺货、质量等履约指标。\n2.协同供应链、仓储、物流等团队，推动履约环节的标准制定与落地执行。\n3.分析业务数据，持续识别履约链路的流程机会点，给出有效建议，提升各环节运营效率。\n4.建立并维护商家履约相关SOP，确保运营流程规范化和可复制性。\n5.学习并使用AI在商家履约场景中的应用，如智能监控预警、异常自动识别、数据分析自动化等。\n\n岗位基本要求\n1.大学本科及以上学历，供应链管理、物流管理或相关专业背。\n2.具备3年以上采购与供应链管理经验，熟悉电商行业的供应链流程和操作规范，具备较强的数据分析能力。\n3.具备良好的沟通能力和团队合作精神，能够有效领导团队完成工作目标。\n4.具备较强的数据分析能力，熟练使用SQL等工具进行数据处理。\n5.具备良好的沟通协调能力，能够跨团队协作推动项目落地。\n6.具备AI工具应用能力，能够利用大模型、AI Agent等工具辅助数据分析、流程优化及异常识别，提升工作效率。\n\n岗位亮点\n站在端到端流程视角，串联商家履约过程，影响履约结果。链路上节点多，业务复杂，异常场景多等，都对供应链流程/计划/执行能力有更高的要求，是很好的专业深度挑战。同时有机会全身心的参与更快速发展的零售业态，在急速发展的业务当中，持续迭代个人对业务的认知，能和多元化背景的团队一起，综合学习，共同进步。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4686988504","sourceKey":"meituan_social","company":"美团","title":"拼好饭-新供给二组-商品运营","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4686988504&jobShareType=1","duty":"1、独立制定 C2M 饮品商品策略，对品类经营结果负责。基于用户需求场景与市场竞争格局，制定品类规划、选品节奏与定价策略。对核心经营指标（杯量、品类渗透率、复购率）负责/\n2、端到端业务项目管理，拉通跨模块目标与交付。主导从开品到爬坡迭代的全链路项目管理。负责经营目标相关方拆解。\n3、建立数据驱动的经营决策机制。搭建品类经营仪表盘，监控杯量趋势、品类结构变化、季节性衰减等关键指标\n基于数据做经营判断。\n4. 品类竞争分析与定量测算。对标行业价格带、爆品机制与流量逻辑，制定差异化竞争策略。建立品类上新的定量预测策略模型。\n5、驱动商品创新与用户心智建设。挖掘 C2M 模式下的品类创新机会，拓展未覆盖场景。推动品牌认知建设，提升用户复购与品牌黏性。","requirements":"1. 大学本科及以上学历，3 年以上餐饮/零售/快消行业商品运营或品类管理经验，有从 0 到 1 搭建品类的经历优先。\n2. 具备独立制定商品策略的能力，能自己定方向、拆目标、推落地、扛结果。\n3. 项目管理能力强，能拉通商品研发、供应链、门店运营等多模块，推动跨团队协作并跟踪交付闭环。\n4. 数据敏感度高，熟练使用数据工具，能从数据中得出经营判断。\n5. 有定量思维，能做品类上新的杯量预测、季节性衰减测算、行业价格带分析等定量工作。","description":"部门介绍\n美团外卖秉承“帮大家吃得更好，生活更好”的使命，始终聚焦于消费者用餐需求。我们通过科技连接消费者和商家，依托庞大的骑手团队，以“线上+线下”的业务模式，为消费者提供品质化、精细化、多样化的餐饮外卖服务。\n外卖事业部是为用户与商家提供全链路交易服务的业务组织，围绕餐饮外卖搭建了包含外卖业务与创新孵化业务在内的多个部门。\n我们的目标是帮助商家开源增收、提高经营效率，促进餐饮行业数字化，以及为更多用户提供更便捷更有品质的外卖服务。加入我们，一起为上亿用户提供更好的用餐体验，帮助大家吃得更好，生活更好！\n\n岗位职责\n1、独立制定 C2M 饮品商品策略，对品类经营结果负责。基于用户需求场景与市场竞争格局，制定品类规划、选品节奏与定价策略。对核心经营指标（杯量、品类渗透率、复购率）负责/\n2、端到端业务项目管理，拉通跨模块目标与交付。主导从开品到爬坡迭代的全链路项目管理。负责经营目标相关方拆解。\n3、建立数据驱动的经营决策机制。搭建品类经营仪表盘，监控杯量趋势、品类结构变化、季节性衰减等关键指标\n基于数据做经营判断。\n4. 品类竞争分析与定量测算。对标行业价格带、爆品机制与流量逻辑，制定差异化竞争策略。建立品类上新的定量预测策略模型。\n5、驱动商品创新与用户心智建设。挖掘 C2M 模式下的品类创新机会，拓展未覆盖场景。推动品牌认知建设，提升用户复购与品牌黏性。\n\n岗位基本要求\n1. 大学本科及以上学历，3 年以上餐饮/零售/快消行业商品运营或品类管理经验，有从 0 到 1 搭建品类的经历优先。\n2. 具备独立制定商品策略的能力，能自己定方向、拆目标、推落地、扛结果。\n3. 项目管理能力强，能拉通商品研发、供应链、门店运营等多模块，推动跨团队协作并跟踪交付闭环。\n4. 数据敏感度高，熟练使用数据工具，能从数据中得出经营判断。\n5. 有定量思维，能做品类上新的杯量预测、季节性衰减测算、行业价格带分析等定量工作。\n\n岗位亮点\n1. 参与创新C2M业务，直接推动用户与供应链的高效匹配。  \n2. 与优秀供应链团队深度协作，提升综合运营能力。  \n3. 扁平化管理，提供快速成长与晋升通道。    \n4. 团队氛围开放，鼓励创新与实践。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4643165130","sourceKey":"meituan_social","company":"美团","title":"景点游玩高级产品专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4643165130&jobShareType=1","duty":"1.负责景点游玩产品的战略规划与顶层设计，基于行业趋势、竞争格局和用户需求演变，定义中长期产品方向和路线图，并推动从规划到落地的全链路闭环；\n2.主导景点交易核心场景（搜索决策、商品详情、交易转化、履约售后）的体系化升级，构建可持续的增长飞轮，对产品主导的GMV、收入等经营指标增长直接负责；\n3.引领AI能力在景点业务中的系统性落地，重新定义产品架构：推动智能推荐、AI导游、动态定价、自动化运营等场景从工具辅助走向AI Native，建立\"数据-模型-产品-业务\"的正向循环；\n4.构建产品方法论体系，包括数据驱动决策框架、实验迭代机制、产品质量标准等，将个人能力转化为组织能力，提升整个产品团队的作战水准；\n5.作为业务核心决策层成员，与技术、算法、运营、销售、BD等多团队深度协同，拉通公司级资源，在复杂利益博弈中推动关键决策落地。","requirements":"1.硕士及以上学历，5年以上互联网产品经验，其中至少3年电商/生活服务/OTA行业核心岗位经历，有完整的业务操盘经验；\n2.有行业级代表作——主导过一个在行业内有辨识度的产品或业务，能清晰还原当时的判断逻辑、关键取舍和最终结果。我们看重的不是规模大小，而是你在其中展现的战略眼光、破局能力和结果交付；\n3.有突破精神——有过在资源受限、方向模糊、组织阻力大的环境下，独立定义问题、说服上下游、拿到结果的实战经历；\n4.有AI胜任力——对大模型、Agent、RAG、Compound AI Systems等技术范式有结构化认知，能判断AI在具体业务场景中的能力边界与落地路径，能与算法团队平等对话并共同定义技术方案，能分辨\"AI能做什么\"和\"AI做不好什么\"；\n5.有较极强的商业Sense——理解供需关系、定价策略、渠道博弈、竞争壁垒等商业本质，能从生意视角而非功能视角思考产品；\n5.有体系化思维与团队影响力——能搭建方法论、建立标准、带动团队认知升级，而不仅是自己能做好。","description":"部门介绍\n美团酒店旅行业务涵盖酒店、民宿、机票、火车票、旅游度假、景点门票等各类住行游品类，通过与产业上下游的深度合作，为用户提供美好的旅游旅行体验。我们积极打造AI友好型组织，使用AI等新技术提升旅游服务的供需匹配效率，更好满足用户个性化、多样化的出游需求。我们持续深耕产业链，用数字化服务助力实体商家高质量经营，探索自有品牌等供给新模式，打造健康的商家生态，保障用户服务体验。为满足用户日益增长的跨境旅行需求，我们将聚焦亚太区域，打造高品质的住宿、交通、游玩等服务矩阵。\n这里有多元的业务布局、持续的成长空间，无论是向往的远方还是眼前的工作，一路都是风景相伴。加入我们，共同为用户创造旅游旅行中的高光时刻！\n\n岗位职责\n1.负责景点游玩产品的战略规划与顶层设计，基于行业趋势、竞争格局和用户需求演变，定义中长期产品方向和路线图，并推动从规划到落地的全链路闭环；\n2.主导景点交易核心场景（搜索决策、商品详情、交易转化、履约售后）的体系化升级，构建可持续的增长飞轮，对产品主导的GMV、收入等经营指标增长直接负责；\n3.引领AI能力在景点业务中的系统性落地，重新定义产品架构：推动智能推荐、AI导游、动态定价、自动化运营等场景从工具辅助走向AI Native，建立\"数据-模型-产品-业务\"的正向循环；\n4.构建产品方法论体系，包括数据驱动决策框架、实验迭代机制、产品质量标准等，将个人能力转化为组织能力，提升整个产品团队的作战水准；\n5.作为业务核心决策层成员，与技术、算法、运营、销售、BD等多团队深度协同，拉通公司级资源，在复杂利益博弈中推动关键决策落地。\n\n岗位基本要求\n1.硕士及以上学历，5年以上互联网产品经验，其中至少3年电商/生活服务/OTA行业核心岗位经历，有完整的业务操盘经验；\n2.有行业级代表作——主导过一个在行业内有辨识度的产品或业务，能清晰还原当时的判断逻辑、关键取舍和最终结果。我们看重的不是规模大小，而是你在其中展现的战略眼光、破局能力和结果交付；\n3.有突破精神——有过在资源受限、方向模糊、组织阻力大的环境下，独立定义问题、说服上下游、拿到结果的实战经历；\n4.有AI胜任力——对大模型、Agent、RAG、Compound AI Systems等技术范式有结构化认知，能判断AI在具体业务场景中的能力边界与落地路径，能与算法团队平等对话并共同定义技术方案，能分辨\"AI能做什么\"和\"AI做不好什么\"；\n5.有较极强的商业Sense——理解供需关系、定价策略、渠道博弈、竞争壁垒等商业本质，能从生意视角而非功能视角思考产品；\n5.有体系化思维与团队影响力——能搭建方法论、建立标准、带动团队认知升级，而不仅是自己能做好。\n\n具备以下条件优先\n1.有景区/目的地/门票/旅游行业深度经验，理解景区供给侧的非标特性、渠道分销逻辑和区域化运营规律；\n2.有AI产品体系化落地经验，从需求定义、数据闭环、效果评估到持续迭代的完整链路，且取得过可量化的业务结果；\n3.有从0到1定义新业务/新产品线的经历，经历过冷启动阶段的不确定性并成功破局；\n4.有团队管理或虚拟团队领导经验，能在矩阵组织中有效整合资源、推动跨团队协作。\n\n岗位亮点\n1.战略级业务 × 巨大空间——景点游玩是美团酒店旅行核心业务，是实现“帮用户生活更好”的关键环节；\n2.AI落地最前线——团队正在将AI从\"锦上添花的功能\"升级为\"重构产品架构的底层能力\"，智能推荐、AI导游、自动化运营等已跑在线上并产生实际业务价值，这里不是做AI demo，是做真正改变业务的AI产品；\n3.决策密度高——真正参与业务核心决策的角色，你会直接面对\"做不做、怎么做、先做哪个\"的高频判断，快速积累战略级产品操盘能力；\n4.务实高效的团队文化——追求单位时间产出而非工时投入，鼓励用数据说话、用工具提效、用结果证明价值。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4688801752","sourceKey":"meituan_social","company":"美团","title":"无人车HRBP","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4688801752&jobShareType=1","duty":"1. 协助业务进行战略研讨和规划，并将业务战略转化为组织能力建设战略，站在业务视角思考长周期的组织发展，致力于帮助业务成功。\n2. 推动AI驱动的组织变革，关注AI技术对组织架构、协作模式及人才结构的影响，设计和实施AI协同办公方案，提升组织效能。\n3. 承接公司的管理体系和HR团队的战略，将管理基本功深化落实到业务各个链条和环节中。\n4. 搭建组织，协助业务负责人一起搭建清晰的组织架构，搭建核心班子，为人才梯队负责。\n5. 结合业务特征，设计清晰的人才供应链管理模式，对人才的选用育励汰全方位进行思考和推行。\n6. 传承公司的文化价值观，提升团队的凝聚力和战斗力，并保障底线控制风险。","requirements":"1. 业务导向、客户导向，有较强的业务敏锐度；\n2. 本科及以上学历，具备5年及以上人力资源工作经验；\n3. 正直、坚韧；双赢思维、求真务实，逻辑清晰；\n4. 具备非职权的影响力，在能不确定的环境中探索出工作方式和方法；\n5. 掌握人力资源相关的知识技能及常用工具；\n6. 了解AI技术发展趋势，具备AI协同办公实践经验或认知，能够推动AI工具在组织场景中的落地应用。","description":"部门介绍\n美团HR的使命是“建设有生命力的组织，为客户和社会创造价值。” 我们认为HR的工作不是以自身“专业”为中心，而是要建设有助于员工发挥创造力的环境，支持他们更好地为外部客户和社会创造价值，也实现组织自身的进化和传承。在这个过程中，我们的每位HR同学都是“业务的战略合作伙伴、组织能力的建设者、美团精神的布道者、员工的成长伙伴”。我们要设计面向长期支撑组织有效运转的机制，我们要求真务实地帮业务解决发展中的问题和阵痛，我们要支持每一位员工历经磨炼收获成长。我们要影响和驱动让世界更美好的变化发生。如果这也是你追求的，欢迎加入美团HR，与我们一路同行！\n\n岗位职责\n1. 协助业务进行战略研讨和规划，并将业务战略转化为组织能力建设战略，站在业务视角思考长周期的组织发展，致力于帮助业务成功。\n2. 推动AI驱动的组织变革，关注AI技术对组织架构、协作模式及人才结构的影响，设计和实施AI协同办公方案，提升组织效能。\n3. 承接公司的管理体系和HR团队的战略，将管理基本功深化落实到业务各个链条和环节中。\n4. 搭建组织，协助业务负责人一起搭建清晰的组织架构，搭建核心班子，为人才梯队负责。\n5. 结合业务特征，设计清晰的人才供应链管理模式，对人才的选用育励汰全方位进行思考和推行。\n6. 传承公司的文化价值观，提升团队的凝聚力和战斗力，并保障底线控制风险。\n\n岗位基本要求\n1. 业务导向、客户导向，有较强的业务敏锐度；\n2. 本科及以上学历，具备5年及以上人力资源工作经验；\n3. 正直、坚韧；双赢思维、求真务实，逻辑清晰；\n4. 具备非职权的影响力，在能不确定的环境中探索出工作方式和方法；\n5. 掌握人力资源相关的知识技能及常用工具；\n6. 了解AI技术发展趋势，具备AI协同办公实践经验或认知，能够推动AI工具在组织场景中的落地应用。\n\n岗位亮点\n我们有开放、直接的工作氛围，用逻辑和事实说话，而不是岗位级别和层级。我们尊重知识和常识，努力以业务视角思考HR自身工作。\n你将有机会参与前沿的AI+HR实践，在AI驱动组织变革的浪潮中发挥关键作用。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4429059429","sourceKey":"meituan_social","company":"美团","title":"Demand Planning","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4429059429&jobShareType=1","duty":"1.负责制定和执行商品的采购计划，确保商品的供应和库存充足。\n2.负责监控商品的销售情况，及时调整采购计划，保证销售业绩达到预期目标。\n3.负责与供应商进行供应链管理，确保供应商提供的商品符合公司的质量标准和交付要求。\n4.管理团队，指导团队成员完成工作任务，促进团队的合作和发展。\n\n1. Develop and implement merchandise procurement plans to ensure adequate supply and inventory levels.\n2. Monitor merchandise sales performance and adjust procurement plans as needed to ensure sales targets are met.\n3. Manage the supply chain in collaboration with suppliers to ensure that the merchandise they provide meets the company’s quality standards and delivery requirements.\n4. Manage the team, guide team members in completing their tasks, and foster teamwork and professional development.","requirements":"1.大学本科及以上学历，专业不限。\n2.拥有5年以上商品与供应链管理相关工作经验。\n3.具备良好的沟通能力和团队管理能力。\n4.熟悉商品采购流程和供应链管理流程。\n5.具备较强的数据分析能力和解决问题能力。","description":"部门介绍\n美团的使命是“帮大家吃得更好，生活更好”，公司聚焦“零售 + 科技”战略，和广大商户与各类合作伙伴一起，努力为消费者提供品质生活，推动商品零售和服务零售在需求侧和供给侧的数字化转型。\n2018年9月20日，美团正式在港交所挂牌上市。美团将始终坚持以客户为中心，不断加大在科技研发方面的投入，更好承担社会责任，更多创造社会价值，与广大合作伙伴一起发展共赢。\n\n岗位职责\n1.负责制定和执行商品的采购计划，确保商品的供应和库存充足。\n2.负责监控商品的销售情况，及时调整采购计划，保证销售业绩达到预期目标。\n3.负责与供应商进行供应链管理，确保供应商提供的商品符合公司的质量标准和交付要求。\n4.管理团队，指导团队成员完成工作任务，促进团队的合作和发展。\n\n1. Develop and implement merchandise procurement plans to ensure adequate supply and inventory levels.\n2. Monitor merchandise sales performance and adjust procurement plans as needed to ensure sales targets are met.\n3. Manage the supply chain in collaboration with suppliers to ensure that the merchandise they provide meets the company’s quality standards and delivery requirements.\n4. Manage the team, guide team members in completing their tasks, and foster teamwork and professional development.\n\n岗位基本要求\n1.大学本科及以上学历，专业不限。\n2.拥有5年以上商品与供应链管理相关工作经验。\n3.具备良好的沟通能力和团队管理能力。\n4.熟悉商品采购流程和供应链管理流程。\n5.具备较强的数据分析能力和解决问题能力。\n\n岗位亮点\n1.薪资福利优厚，提供广阔的晋升空间。\n2.公司提供良好的培训机会和职业发展平台。\n3.可以在跨国公司的国际化工作环境中不断学习和成长。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4688471072","sourceKey":"meituan_social","company":"美团","title":"快乐猴仓储主管（冷藏）","city":"杭州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4688471072&jobShareType=1","duty":"1.仓储作业计划执行与班组进度跟踪督导\n• 承接仓储经理下达的作业计划，将任务合理分解至班组各岗位，跟踪收货、上架、拣选、出库、退货等各环节执行进度• 及时发现作业滞后或异常，快速协调资源调配，确保班组日常运营目标按时达成2. 货物收发验货与库存数据核对管理\n• 组织并监督货物收货验货、上架入库、出库发货等全流程规范执行，严格把控货物数量、质量与单据一致性\n• 定期核对库存数据，确保账实相符，及时处理收发差异，保障库存数据准确可靠3. 班组人员培训与作业规范执行督查\n• 组织开展新员工岗前培训及在职人员技能培训，确保班组成员熟知并掌握作业标准与操作规范；• 日常巡查作业执行情况，及时纠正违规操作，持续提升班组成员规范执行能力与作业质量。4. 库存损耗统计分析与异常品类原因排查\n• 定期统计班组库存损耗数据，识别损耗异常品类与高频问题节点\n• 深入排查损耗原因，区分操作失误、仓储条件、流程漏洞等因素，提出针对性改善建议并跟踪整改落地，持续降低库存损耗率5. 流程标准化执行落地与仓储安全问题整改\n• 负责公司仓储标准化在本班组的宣贯培训、执行落地与日常监督，确保各岗位人员严格按标准规范操作• 负责班组区域日常安全巡查，检查消防通道、货架稳固、设备使用、食品卫生等安全隐患• 对班组人员开展安全规范宣导，确保安全生产无事故","requirements":"1、学历专业：大学专科及以上学历，物流管理、供应链管理或相关专业优先。\n2、工作经验：具备3年以上仓储物流现场管理经验，具备团队管理经验者，硬折扣、商超物流经验者优先（超盒算、奥乐齐、永辉、华润万家、大润发等）。\n3、专业技能：熟悉仓储管理系统及常见物流设备操作，了解仓储标准化作业流程。\n4、管理能力：具备良好的团队管理能力与沟通协调能力，能有效推动现场作业执行与团队协作。\n5、综合素质：工作责任心强，具备创新意识与问题解决能力，能适应高强度作业环境。","description":"部门介绍\n快乐猴是美团自营社区超市，依托自有供应链和门店管理体系，聚焦家庭用户的三餐所需，为消费者提供高质价比的食杂商品。快乐猴以数字化能力与科学品控为基础，不断满足消费者对“省”和“便利”的需求。\n\n岗位职责\n1.仓储作业计划执行与班组进度跟踪督导\n• 承接仓储经理下达的作业计划，将任务合理分解至班组各岗位，跟踪收货、上架、拣选、出库、退货等各环节执行进度• 及时发现作业滞后或异常，快速协调资源调配，确保班组日常运营目标按时达成2. 货物收发验货与库存数据核对管理\n• 组织并监督货物收货验货、上架入库、出库发货等全流程规范执行，严格把控货物数量、质量与单据一致性\n• 定期核对库存数据，确保账实相符，及时处理收发差异，保障库存数据准确可靠3. 班组人员培训与作业规范执行督查\n• 组织开展新员工岗前培训及在职人员技能培训，确保班组成员熟知并掌握作业标准与操作规范；• 日常巡查作业执行情况，及时纠正违规操作，持续提升班组成员规范执行能力与作业质量。4. 库存损耗统计分析与异常品类原因排查\n• 定期统计班组库存损耗数据，识别损耗异常品类与高频问题节点\n• 深入排查损耗原因，区分操作失误、仓储条件、流程漏洞等因素，提出针对性改善建议并跟踪整改落地，持续降低库存损耗率5. 流程标准化执行落地与仓储安全问题整改\n• 负责公司仓储标准化在本班组的宣贯培训、执行落地与日常监督，确保各岗位人员严格按标准规范操作• 负责班组区域日常安全巡查，检查消防通道、货架稳固、设备使用、食品卫生等安全隐患• 对班组人员开展安全规范宣导，确保安全生产无事故\n\n岗位基本要求\n1、学历专业：大学专科及以上学历，物流管理、供应链管理或相关专业优先。\n2、工作经验：具备3年以上仓储物流现场管理经验，具备团队管理经验者，硬折扣、商超物流经验者优先（超盒算、奥乐齐、永辉、华润万家、大润发等）。\n3、专业技能：熟悉仓储管理系统及常见物流设备操作，了解仓储标准化作业流程。\n4、管理能力：具备良好的团队管理能力与沟通协调能力，能有效推动现场作业执行与团队协作。\n5、综合素质：工作责任心强，具备创新意识与问题解决能力，能适应高强度作业环境。\n\n岗位亮点\n1. 加入快速发展的生鲜物流品牌，平台发展空间广阔。  \n2. 提供专业冷链管理培训，助力个人职业成长。  \n3. 工作地点位于杭州市，交通便利，办公环境优良。  \n4. 团队氛围积极，注重员工关怀与职业发展支持。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4685450398","sourceKey":"meituan_social","company":"美团","title":"外卖－业务策略算法工程师/专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4685450398&jobShareType=1","duty":"1、面向外卖商家经营增长，参与业务策略与技术方向规划，识别值得通过算法和 AI 解决的关键经营问题，主导核心方向的技术建设与落地，对商家经营改善、策略增量收益及经营效率等业务结果负责。\n\n2、主导以下一个或多个方向的算法体系建设，建立从经营洞察到策略决策、效果验证的完整闭环：\n- 经营理解与机会发现： 基于海量交易、经营及用户行为数据，建设需求预测、商家与门店刻画、经营诊断等能力，识别不同城市、商圈、品类和经营阶段下的增长机会。\n- 经营策略与资源优化： 建设经营潜力、策略响应及增量价值预估能力，结合因果推断、策略学习和优化技术，解决“什么策略适合什么商家、有限资源如何分配”等问题，提升策略收益与资源效率。\n- 大模型与经营 Agent： 建设面向商家的智能经营助手，推动大模型从经营问答、分析诊断走向策略生成与执行协同，解决真实经营场景中的推理、工具调用、效果评测与可靠性问题。\n\n3、负责所主导方向从问题定义、技术方案到线上验证和规模化应用的全链路工作。建立与业务目标一致的评测和数据反馈机制，通过在线实验与因果评估验证真实增量，持续提升算法及 Agent 在复杂经营场景中的有效性、稳定性与成本效率。\n\n4、作为核心技术骨干，协同产品、工程、数据科学及业务团队推进跨团队项目，牵引技术方案与关键问题攻关，指导团队成员成长；推动 AI 工具在研发、实验分析及迭代流程中的应用，提升团队研发效率。","requirements":"1、计算机、人工智能、数学、统计学、运筹学等相关专业本科及以上学历，具备扎实的机器学习、概率统计或优化理论基础，以及良好的工程实现能力。\n\n2、具备独立负责复杂算法项目的经验，曾主导核心项目从问题定义、方案设计到上线迭代的完整过程，能够清晰说明关键技术决策、效果验证方法及取得的业务收益。\n\n3、在以下至少一个方向具有深入实践和持续迭代经验，能够承担该方向的技术主导职责：\n- 因果推断、Uplift Modeling、策略学习或营销资源优化；\n- 推荐、广告、搜索中的召回、排序或多目标建模；\n- 需求预测、时空建模、图学习或大规模数据挖掘；\n- 运筹优化、强化学习、Contextual Bandit 或复杂约束下的决策优化；\n- 大语言模型、RAG、Agent 系统或智能自动化，具备业务落地与效果评测经验。\n\n4、具备优秀的业务理解和问题抽象能力，能够在目标尚不清晰、约束较多的场景下识别关键问题、定义指标并确定技术路径；能够综合判断模型效果、工程成本与业务收益，推动方案落地并持续拿到结果。\n\n5、理解大模型与 Agent 的能力边界，对其在商家经营场景中的应用有明确思考，并有相关实践或原型探索经验。能够结合业务问题选择合适的技术方案，推动模型能力与业务数据、工具及流程有效结合。\n\n6、具备技术影响力和跨团队推动能力，能够组织技术讨论、推进关键决策，协同不同角色解决复杂问题；具备较强的自驱力、好奇心与结果意识。","description":"部门介绍\n美团核心本地商业下业务研发平台，基于公司“零售+科技”的战略导向，通过从底层架构到应用系统、从软件到硬件、从传统算法到GenAI的全方位技术研究，以及开发、运维、安全等全流程能力建设，致力于推动美团核心本地商业下需求侧与供给侧的数字化和智能化升级，助力业务实现高质量增长，优化用户使用体验，提升商户经营水平，促进行业生态伙伴关系的持续健康发展。团队秉持务实、自驱、开放以及追求卓越的工程师文化，一方面通过系统和技术体系的持续迭代升级，帮助业务高质量增长；另一方面，密切关注前沿技术趋势变化，积极创新技术能力，为业务未来发展创造新的可能性。期待优秀的你加入我们，在夯实专业、深耕平台的基础上与业务携手同行，一起用技术 “帮大家吃得更好，生活更好”。\n\n岗位职责\n1、面向外卖商家经营增长，参与业务策略与技术方向规划，识别值得通过算法和 AI 解决的关键经营问题，主导核心方向的技术建设与落地，对商家经营改善、策略增量收益及经营效率等业务结果负责。\n\n2、主导以下一个或多个方向的算法体系建设，建立从经营洞察到策略决策、效果验证的完整闭环：\n- 经营理解与机会发现： 基于海量交易、经营及用户行为数据，建设需求预测、商家与门店刻画、经营诊断等能力，识别不同城市、商圈、品类和经营阶段下的增长机会。\n- 经营策略与资源优化： 建设经营潜力、策略响应及增量价值预估能力，结合因果推断、策略学习和优化技术，解决“什么策略适合什么商家、有限资源如何分配”等问题，提升策略收益与资源效率。\n- 大模型与经营 Agent： 建设面向商家的智能经营助手，推动大模型从经营问答、分析诊断走向策略生成与执行协同，解决真实经营场景中的推理、工具调用、效果评测与可靠性问题。\n\n3、负责所主导方向从问题定义、技术方案到线上验证和规模化应用的全链路工作。建立与业务目标一致的评测和数据反馈机制，通过在线实验与因果评估验证真实增量，持续提升算法及 Agent 在复杂经营场景中的有效性、稳定性与成本效率。\n\n4、作为核心技术骨干，协同产品、工程、数据科学及业务团队推进跨团队项目，牵引技术方案与关键问题攻关，指导团队成员成长；推动 AI 工具在研发、实验分析及迭代流程中的应用，提升团队研发效率。\n\n岗位基本要求\n1、计算机、人工智能、数学、统计学、运筹学等相关专业本科及以上学历，具备扎实的机器学习、概率统计或优化理论基础，以及良好的工程实现能力。\n\n2、具备独立负责复杂算法项目的经验，曾主导核心项目从问题定义、方案设计到上线迭代的完整过程，能够清晰说明关键技术决策、效果验证方法及取得的业务收益。\n\n3、在以下至少一个方向具有深入实践和持续迭代经验，能够承担该方向的技术主导职责：\n- 因果推断、Uplift Modeling、策略学习或营销资源优化；\n- 推荐、广告、搜索中的召回、排序或多目标建模；\n- 需求预测、时空建模、图学习或大规模数据挖掘；\n- 运筹优化、强化学习、Contextual Bandit 或复杂约束下的决策优化；\n- 大语言模型、RAG、Agent 系统或智能自动化，具备业务落地与效果评测经验。\n\n4、具备优秀的业务理解和问题抽象能力，能够在目标尚不清晰、约束较多的场景下识别关键问题、定义指标并确定技术路径；能够综合判断模型效果、工程成本与业务收益，推动方案落地并持续拿到结果。\n\n5、理解大模型与 Agent 的能力边界，对其在商家经营场景中的应用有明确思考，并有相关实践或原型探索经验。能够结合业务问题选择合适的技术方案，推动模型能力与业务数据、工具及流程有效结合。\n\n6、具备技术影响力和跨团队推动能力，能够组织技术讨论、推进关键决策，协同不同角色解决复杂问题；具备较强的自驱力、好奇心与结果意识。\n\n具备以下条件优先\n1. 有本地生活、电商、广告、推荐、营销增长、定价或商业策略算法经验。\n2. 有大规模在线算法系统建设经验，能够独立推动算法从原型验证到线上落地。\n3. 熟悉 A/B 实验、反事实评估、增量收益评估及长期价值建模。\n4. 有复杂业务约束下的策略优化、多目标优化或大规模资源配置经验。\n5. 在 KDD、WWW、SIGIR、RecSys、NeurIPS、ICML、AAAI 等会议发表过相关论文，或在高水平算法竞赛中取得优秀成绩。\n\n岗位亮点\n团队面向美团外卖的复杂经营场景，建设数据驱动的业务决策与经营智能能力。我们基于海量交易、经营及时空数据，综合运用机器学习、因果推断、运筹优化和强化学习等技术，提升经营机会识别、供需匹配与资源使用效率，帮助商家提升经营水平，推动平台生态长期健康发展。\n这里既有复杂经营场景下的预测、挖掘和效果评估问题，也有多目标、多约束、长期价值决策等算法挑战。期待你和我们一起，将前沿算法应用到大规模本地生活业务中。\n\n岗位亮点：\n1. 业务体量大、数据维度丰富，算法结果能够直接作用于真实经营场景。\n2. 技术方向综合，既包括预测、挖掘和排序，也包括因果推断、运筹优化及序列决策。\n3. 面向多主体、多目标、多约束的复杂决策问题，具有较强的技术挑战和长期研究价值。\n4. 算法距离业务结果近，可以完整参与从问题定义到效果落地的全过程。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4675951563","sourceKey":"meituan_social","company":"美团","title":"IT物资供应链策略","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4675951563&jobShareType=1","duty":"1、IT资产供应链策略与优化\n - 负责 IT 资产端到端供应链体系建设，覆盖需求预测、采购、库存、仓储物流、资产流转及逆向处置等环节，提升供应保障能力和运营效率。\n - 制定成本优化及库存策略，平衡供应、成本与风险，提升资产投入产出效率。\n - 推动供应链数字化建设，结合数据分析、自动化及 AI 等技术提升管理效率和决策能力。\n2、IT资产生命周期管理\n - 建立并优化 IT 资产全生命周期管理体系，推动采购、使用、运维、回收、报废等环节标准化、规范化和合规化。\n - 基于资产数据分析识别优化机会，提升资产利用率和管理精细化水平。\n3、供应生态与风险治理\n - 建立供应生态管理体系，持续优化供应模式、服务能力和合作机制，提升供应链韧性和业务支撑能力。\n - 识别供应链关键风险，建立风险预警、应急保障及持续改进机制，保障业务连续性。\n4、AI驱动的智能化建设\n - 探索与推动 AI 在 IT 资产与供应链场景中的应用，覆盖需求预测、库存优化、资产盘点、异常识别及流程自动化等方向，提升管理效率和决策质量。\n - 结合业务需求建设知识库、智能体（Agent）及自动化能力，推动资产管理和供应链运营智能化升级。","requirements":"1、5年以上 IT 资产管理或供应链管理相关经验，具备跨区域或跨国企业工作经验者优先。熟悉 IT 硬件、软件许可及云服务采购流程，具备端到端供应链管理及 IT 资产全生命周期管理经验。\n2、具备较强的数据分析和业务洞察能力，能够从业务和组织视角识别真实问题，围绕成本、效率、风险等维度制定策略并推动落地；具备供应商管理经验，能够搭建评估体系并持续优化合作模式。\n3、具备复杂问题解决和创新能力，能够突破现状、推动业务改进；善于借助 AI 等新技术提升问题分析、方案设计和流程优化效率，理解生成式 AI 应用场景及边界，具备数据安全和合规意识。\n4、具备优秀的跨部门协同和项目推动能力，能够整合全球团队、业务部门及供应商资源，建立深度合作关系并赢得信任，推动复杂项目落地。\n5、具备战略思维、结果导向和组织建设意识，能够明确方向、推动执行，并持续培养团队能力；坚持正直、利他的原则，在复杂场景下做出正确判断。\n6、英语流利，能够与全球团队及供应商进行高效沟通。","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n1、IT资产供应链策略与优化\n - 负责 IT 资产端到端供应链体系建设，覆盖需求预测、采购、库存、仓储物流、资产流转及逆向处置等环节，提升供应保障能力和运营效率。\n - 制定成本优化及库存策略，平衡供应、成本与风险，提升资产投入产出效率。\n - 推动供应链数字化建设，结合数据分析、自动化及 AI 等技术提升管理效率和决策能力。\n2、IT资产生命周期管理\n - 建立并优化 IT 资产全生命周期管理体系，推动采购、使用、运维、回收、报废等环节标准化、规范化和合规化。\n - 基于资产数据分析识别优化机会，提升资产利用率和管理精细化水平。\n3、供应生态与风险治理\n - 建立供应生态管理体系，持续优化供应模式、服务能力和合作机制，提升供应链韧性和业务支撑能力。\n - 识别供应链关键风险，建立风险预警、应急保障及持续改进机制，保障业务连续性。\n4、AI驱动的智能化建设\n - 探索与推动 AI 在 IT 资产与供应链场景中的应用，覆盖需求预测、库存优化、资产盘点、异常识别及流程自动化等方向，提升管理效率和决策质量。\n - 结合业务需求建设知识库、智能体（Agent）及自动化能力，推动资产管理和供应链运营智能化升级。\n\n岗位基本要求\n1、5年以上 IT 资产管理或供应链管理相关经验，具备跨区域或跨国企业工作经验者优先。熟悉 IT 硬件、软件许可及云服务采购流程，具备端到端供应链管理及 IT 资产全生命周期管理经验。\n2、具备较强的数据分析和业务洞察能力，能够从业务和组织视角识别真实问题，围绕成本、效率、风险等维度制定策略并推动落地；具备供应商管理经验，能够搭建评估体系并持续优化合作模式。\n3、具备复杂问题解决和创新能力，能够突破现状、推动业务改进；善于借助 AI 等新技术提升问题分析、方案设计和流程优化效率，理解生成式 AI 应用场景及边界，具备数据安全和合规意识。\n4、具备优秀的跨部门协同和项目推动能力，能够整合全球团队、业务部门及供应商资源，建立深度合作关系并赢得信任，推动复杂项目落地。\n5、具备战略思维、结果导向和组织建设意识，能够明确方向、推动执行，并持续培养团队能力；坚持正直、利他的原则，在复杂场景下做出正确判断。\n6、英语流利，能够与全球团队及供应商进行高效沟通。\n\n具备以下条件优先\n1、具备 CSCP、PMP、ITIL 等相关专业认证者优先。 \n2、具备大型跨国企业或 IT 服务行业经验，熟悉全球化运营环境及相关合规要求者优先。 \n3、具备 AI 在 IT 资产管理或供应链场景中的实践经验者优先，包括知识库、智能体（Agent）、自动化流程、AI Coding 等应用实践，并能够结合业务场景说明实际价值和效率提升。\n\n岗位亮点\n1、战略影响力：参与 IT 资产管理与供应链体系建设，推动资产管理模式、供应链策略及数字化能力升级，提升组织运营效率和业务支撑能力。 \n2、全球化视野与资源整合：协同全球业务、供应商及合作伙伴，参与跨区域供应链管理实践，积累全球化 IT 资产运营和资源整合经验。 \n3、创新驱动与能力成长：鼓励探索数字化、自动化及 AI 等新技术在 IT 资产与供应链场景中的应用，推动管理模式创新和效率提升。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:2921551247","sourceKey":"meituan_social","company":"美团","title":"充电宝财务运营","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=2921551247&jobShareType=1","duty":"1、业务支持：负责对接充电宝海外业务需求，结合会计准则，结算规则，合规要求等，识别和判断业务活动对财务的影响，出具相应的财务方案，为业务部门的发展及商业决策提供积极的财务支持；\n2、提升财务信息化能力：结合对业务场景及业财系统的深入理解，与各方产研配合推进财务信息化建设，包括业务场景的线上计费结算、线上化传账及业财数据校验、财务系统优化升级等；\n3、业财流程优化：通过专项梳理推进财务运营流程、信息化进程等优化，发现并解决各类财务问题，提高财务结果的效率和准确性；\n4、其他：与财务其他团队积极协调，完成其他指定任务。","requirements":"1. 大学本科及以上学历，财务、会计或相关专业背景。  \n2. 具备3年以上财务运营或相关工作经验，有互联网或共享经济行业经验优先。  \n3. 熟悉财务核算流程，熟练使用AI等相关工具。  \n4. 具备良好的沟通能力和团队协作精神，工作细致认真。","description":"部门介绍\n财务平台负责公司整体和各业务层面的财务管理工作，通过建设专业、全面、复合的财务管理能力和与业务经营的紧密结合来支持公司健康发展。目前财务平台拥有财务会计、财务报告、资金管理、税务管理、财务共享、财务系统、规划分析、财务BP和内控内审等主要工作方向。我们的目标是建设业界一流的财务管理能力和经营支持体系，为公司战略的正确落地、投入效率的持续提升、业务价值的不断增长保驾护航。欢迎加入财务平台，携手一起向未来！\n\n岗位职责\n1、业务支持：负责对接充电宝海外业务需求，结合会计准则，结算规则，合规要求等，识别和判断业务活动对财务的影响，出具相应的财务方案，为业务部门的发展及商业决策提供积极的财务支持；\n2、提升财务信息化能力：结合对业务场景及业财系统的深入理解，与各方产研配合推进财务信息化建设，包括业务场景的线上计费结算、线上化传账及业财数据校验、财务系统优化升级等；\n3、业财流程优化：通过专项梳理推进财务运营流程、信息化进程等优化，发现并解决各类财务问题，提高财务结果的效率和准确性；\n4、其他：与财务其他团队积极协调，完成其他指定任务。\n\n岗位基本要求\n1. 大学本科及以上学历，财务、会计或相关专业背景。  \n2. 具备3年以上财务运营或相关工作经验，有互联网或共享经济行业经验优先。  \n3. 熟悉财务核算流程，熟练使用AI等相关工具。  \n4. 具备良好的沟通能力和团队协作精神，工作细致认真。\n\n岗位亮点\n1. 加入快速发展的共享充电宝行业，参与核心业务运营。  \n2. 与业务团队紧密协作，提升财务与业务融合能力。  \n3. 提供完善的培训体系与职业发展通道。  \n4. 工作地点位于北京，办公环境优良，团队氛围积极。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4634018137","sourceKey":"meituan_social","company":"美团","title":"小象超市-选址拓展经理-线下店","city":"武汉市/长沙市/广州市/深圳市/成都市/南宁市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4634018137&jobShareType=1","duty":"1.负责小象超市的选址工作，对所管辖区域的新店选址做现场考察、商圈评估及市场调研工作；\n2.根据本地市场的特点以及公司开店的要求制定战区规划与开店策略；\n3.负责项目的商务谈判、合同谈判、基本工程条件的谈判以及风险预估；\n4.利用相关工具对预选址进行详细分析，做出逻辑清晰、条理分明的选址报告；\n5.负责与公司内部相关团队沟通协作；\n6.负责跟进项目签约、接场、开业的流程，具备处理门店开业前施工过程中遇到的各种问题的能力。","requirements":"1.大专以上学历；\n2.5年及以上零售拓展行业的相关工作经验，购物中心开店经验者优先；\n3.较强的专业能力，能够独立完成项目的评估、选址、谈判、签约及进场工作，具备制定战区图的能力；\n4.熟悉所负责区域的商业地产及房产市场，有一定的人脉资源；\n5.掌握与租赁合同相关的基本法律、法规问题，与房东洽谈时能够辨别和规避法律风险、保障公司权益；\n6.掌握基本的工程常识，做选址评估时能够辨别较为明显的工程隐患；\n7.较强的沟通、谈判、协调能力，具备一定的谈判技巧及处理公共关系的能力；\n8. 有较强的自我驱动力、学习能力，对新零售有一定了解。\n9.因业务需求，本岗位需要出差，具体由公司统一安排。\n10.掌握基本的AI工具，使用工具提升工作流程效率。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1.负责小象超市的选址工作，对所管辖区域的新店选址做现场考察、商圈评估及市场调研工作；\n2.根据本地市场的特点以及公司开店的要求制定战区规划与开店策略；\n3.负责项目的商务谈判、合同谈判、基本工程条件的谈判以及风险预估；\n4.利用相关工具对预选址进行详细分析，做出逻辑清晰、条理分明的选址报告；\n5.负责与公司内部相关团队沟通协作；\n6.负责跟进项目签约、接场、开业的流程，具备处理门店开业前施工过程中遇到的各种问题的能力。\n\n岗位基本要求\n1.大专以上学历；\n2.5年及以上零售拓展行业的相关工作经验，购物中心开店经验者优先；\n3.较强的专业能力，能够独立完成项目的评估、选址、谈判、签约及进场工作，具备制定战区图的能力；\n4.熟悉所负责区域的商业地产及房产市场，有一定的人脉资源；\n5.掌握与租赁合同相关的基本法律、法规问题，与房东洽谈时能够辨别和规避法律风险、保障公司权益；\n6.掌握基本的工程常识，做选址评估时能够辨别较为明显的工程隐患；\n7.较强的沟通、谈判、协调能力，具备一定的谈判技巧及处理公共关系的能力；\n8. 有较强的自我驱动力、学习能力，对新零售有一定了解。\n9.因业务需求，本岗位需要出差，具体由公司统一安排。\n10.掌握基本的AI工具，使用工具提升工作流程效率。\n\n岗位亮点\n1.线下购物中心门店拓展；\n2.能够和做事、目标感、使命感强的优秀团队合作，一起拿结果；","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4627118509","sourceKey":"meituan_social","company":"美团","title":"Quality Assurance Specialist","city":"开罗","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4627118509&jobShareType=1","duty":"- Lead the systematic monitoring and evaluation of agent interactions across email, chat, and voice channels, ensuring adherence to established quality standards, process requirements, and performance KPIs.\n\n-Oversee the end-to-end governance of quality metrics, including accuracy, fatal error rates, compliance scores, CSAT/DSAT drivers, and adoption performance.\n\n-Identify failures and potential risks; recommend and drive preventive and corrective actions with internal teams and vendor partners through structured governance routines.\n\n-Conduct detailed root-cause analyses on quality gaps, DSAT trends, and complaints to drive sustainable improvements in customer experience.\n\n-Manage and oversee the quality performance of all BPO/vendor partners to ensure consistent delivery aligned with CX, operational, and compliance standards.\n\n-Lead vendor performance reviews, quality-focused WBRs, calibration alignment, and post-audit accuracy assessments to ensure accountability and continuous improvement.\n\n-Drive vendor improvement initiatives focused on reducing errors, improving efficiency, enhancing compliance, and optimizing cost-to-serve.\n\n-Guide vendors in implementing action plans, ensuring adherence to governance structures, timelines, and performance expectations.\n\n-Lead internal and external calibrations, including DSAT-specific calibration sessions, ensuring aligned scoring, consistent interpretation of criteria, and evaluation accuracy.\n\n-Provide structured, objective feedback to agents and vendor teams, highlighting strengths, gaps, and developmental priorities.\n\n-Work closely with operations to support coaching strategies, floor readiness, and performance uplift initiatives.\n\n-Identify performance patterns and quality trends, proposing systemic improvements and process optimization opportunities.\n\n-Develop and present comprehensive reports on quality metrics, fatal error rates, DSAT insights, and agent/vendor performance trends.\n\n-Deliver actionable, data-driven recommendations to leadership and cross-functional stakeholders.\n\n-Track and document the progress of quality initiatives, ensuring timely execution and measurable impact.\n\n-Act as a subject matter expert on QA standards and customer experience best practices. Complete monthly login hours for handling live customer interactions","requirements":"-A minimum of 5 years of solid experience in Quality Assurance, ideally acquired in a team leader or supervisory capacity within a contact center or BPO setting, preferably within the food delivery or food services industry.  \n-Demonstrated exposure to vendor quality performance and broader, higher-level quality oversight\n-Fluency in Arabic and English.\n-Strong understanding of QA methodologies, evaluation frameworks, and customer experience quality standards.\n-Prior experience evaluating email, chat, and voice interactions; ability to develop and enhance scorecards based on business needs.\n-Strong analytical capabilities with demonstrated experience in conducting root-cause analysis, preparing and delivering clear presentations, identifying systemic improvement opportunities, and generating comprehensive reporting.\n-Strong communication, stakeholder management, and vendor engagement skills.\n-Willingness to move as per client sites across EG.\n-Ability to work independently, prioritize effectively, and operate within a fast-paced, performance-driven environment. Ability to move to vendor sites as per business needs","description":"部门介绍\nKeeta是全球领先外卖平台美团旗下的独立品牌，肩负着“帮大家吃得更好，生活更好”的使命。依托美团深耕中国市场15年的技术与运营积淀，我们正引领全球餐饮与商品即时配送服务的创新与发展。\n\n自2023年成立以来，Keeta始终扎根社区并创造价值。我们为用户提供可靠的外卖体验，以智慧技术助餐厅提升经营效率，在为骑手拓宽收入来源的同时，也充分提供安全保障措施。基于这份多方共赢、共同成长的理念，我们的业务已从中国香港稳步拓展至中东及巴西，并持续向世界迈进。\n\n岗位职责\n- Lead the systematic monitoring and evaluation of agent interactions across email, chat, and voice channels, ensuring adherence to established quality standards, process requirements, and performance KPIs.\n\n-Oversee the end-to-end governance of quality metrics, including accuracy, fatal error rates, compliance scores, CSAT/DSAT drivers, and adoption performance.\n\n-Identify failures and potential risks; recommend and drive preventive and corrective actions with internal teams and vendor partners through structured governance routines.\n\n-Conduct detailed root-cause analyses on quality gaps, DSAT trends, and complaints to drive sustainable improvements in customer experience.\n\n-Manage and oversee the quality performance of all BPO/vendor partners to ensure consistent delivery aligned with CX, operational, and compliance standards.\n\n-Lead vendor performance reviews, quality-focused WBRs, calibration alignment, and post-audit accuracy assessments to ensure accountability and continuous improvement.\n\n-Drive vendor improvement initiatives focused on reducing errors, improving efficiency, enhancing compliance, and optimizing cost-to-serve.\n\n-Guide vendors in implementing action plans, ensuring adherence to governance structures, timelines, and performance expectations.\n\n-Lead internal and external calibrations, including DSAT-specific calibration sessions, ensuring aligned scoring, consistent interpretation of criteria, and evaluation accuracy.\n\n-Provide structured, objective feedback to agents and vendor teams, highlighting strengths, gaps, and developmental priorities.\n\n-Work closely with operations to support coaching strategies, floor readiness, and performance uplift initiatives.\n\n-Identify performance patterns and quality trends, proposing systemic improvements and process optimization opportunities.\n\n-Develop and present comprehensive reports on quality metrics, fatal error rates, DSAT insights, and agent/vendor performance trends.\n\n-Deliver actionable, data-driven recommendations to leadership and cross-functional stakeholders.\n\n-Track and document the progress of quality initiatives, ensuring timely execution and measurable impact.\n\n-Act as a subject matter expert on QA standards and customer experience best practices. Complete monthly login hours for handling live customer interactions\n\n岗位基本要求\n-A minimum of 5 years of solid experience in Quality Assurance, ideally acquired in a team leader or supervisory capacity within a contact center or BPO setting, preferably within the food delivery or food services industry.  \n-Demonstrated exposure to vendor quality performance and broader, higher-level quality oversight\n-Fluency in Arabic and English.\n-Strong understanding of QA methodologies, evaluation frameworks, and customer experience quality standards.\n-Prior experience evaluating email, chat, and voice interactions; ability to develop and enhance scorecards based on business needs.\n-Strong analytical capabilities with demonstrated experience in conducting root-cause analysis, preparing and delivering clear presentations, identifying systemic improvement opportunities, and generating comprehensive reporting.\n-Strong communication, stakeholder management, and vendor engagement skills.\n-Willingness to move as per client sites across EG.\n-Ability to work independently, prioritize effectively, and operate within a fast-paced, performance-driven environment. Ability to move to vendor sites as per business needs\n\n具备以下条件优先\nSix Sigma\n\n岗位亮点\nAccelerated professional growth, Continuous learning culture, Purpose-Driven impact","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4470625828","sourceKey":"meituan_social","company":"美团","title":"小象超市-物料运营专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4470625828&jobShareType=1","duty":"负责物料的统筹管理，作为设计团队、供应商、采购及业务方之间的核心协调角色，确保各类物料、广告点位从需求确认到落地上刊的全流程高效推进。\n1、收集、梳理各业务方物料需求，制定物料排期计划，把控整体节奏；建立并维护物料需求清单及进度跟踪台账，确保各节点按时交付；提前识别风险节点，推动跨团队协作解决阻塞问题；\n2、负责各项广告点位的盘点、规划与分配；结合活动节奏与业务优先级，制定点位排期方案；\n3、向设计团队准确传达物料需求，提供清晰的Brief，组织物料设计稿的多轮审核，协调业务方、合规、品牌等相关方完成确认，把控设计质量与品牌规范，确保最终物料符合上刊标准；\n4、对接物料制作供应商，跟踪生产进度，管控交期与质量；配合采购完成下单、验收等流程，确保物料按时按质交付；\n5、梳理并优化物料全链路SOP，提升跨团队协作效率；建立物料档案库，沉淀历史物料资产，支持复用。","requirements":"1、本科及以上学历，有项目管理、物料管理或市场执行相关工作经验优先。有零售、快消、商业地产行业背景者优先；\n2、善于发挥视觉创意和表现力，具备良好团队合作精神，能够与上下游良好沟通，顺畅合作。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n负责物料的统筹管理，作为设计团队、供应商、采购及业务方之间的核心协调角色，确保各类物料、广告点位从需求确认到落地上刊的全流程高效推进。\n1、收集、梳理各业务方物料需求，制定物料排期计划，把控整体节奏；建立并维护物料需求清单及进度跟踪台账，确保各节点按时交付；提前识别风险节点，推动跨团队协作解决阻塞问题；\n2、负责各项广告点位的盘点、规划与分配；结合活动节奏与业务优先级，制定点位排期方案；\n3、向设计团队准确传达物料需求，提供清晰的Brief，组织物料设计稿的多轮审核，协调业务方、合规、品牌等相关方完成确认，把控设计质量与品牌规范，确保最终物料符合上刊标准；\n4、对接物料制作供应商，跟踪生产进度，管控交期与质量；配合采购完成下单、验收等流程，确保物料按时按质交付；\n5、梳理并优化物料全链路SOP，提升跨团队协作效率；建立物料档案库，沉淀历史物料资产，支持复用。\n\n岗位基本要求\n1、本科及以上学历，有项目管理、物料管理或市场执行相关工作经验优先。有零售、快消、商业地产行业背景者优先；\n2、善于发挥视觉创意和表现力，具备良好团队合作精神，能够与上下游良好沟通，顺畅合作。\n\n岗位亮点\n1、公司重点项目，个人成长锻炼机会佳；\n2、团队氛围好，协同顺畅，高效推动落地；\n3、职责范围广，未来成长空间足。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4279128271","sourceKey":"meituan_social","company":"美团","title":"渠道经理（景点游玩方向）","city":"太原市/沈阳市/郑州市/武汉市/长沙市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4279128271&jobShareType=1","duty":"1. 精准招商与生态构建：根据业务战略与区域供需缺口，制定服务商招募画像与拓新策略；负责寻找、沟通、引入具备强景区客情关系、丰富行业资源或强代运营能力的高质量服务商；\n2. 深度赋能与过程运营：为入驻服务商提供系统化的运营培训与落地方案，对其业绩负责，过程中盯紧服务商核心关键动作的落地，形成可复制的SOP并向全国推广；\n3. 政策落地与激励管理：推进平台服务商激励政策在负责区域的落地，确保“以利驱动，导向结果”，监控大盘数据，针对尾部服务商进行诊断纠偏或清退。","requirements":"1. 3年以上互联网OTA旅游、本地生活等行业的渠道管理、服务商运营经验；有酒旅门票相关背景者优先。\n2. 出色的人际沟通能力、团队协作精神与团队建设能力；\n3. 有强大的自驱力和执行力，渴望成功；\n3. 能接受区域内长期出差。","description":"部门介绍\n美团酒店旅行业务涵盖酒店、民宿、机票、火车票、旅游度假、景点门票等各类住行游品类，通过与产业上下游的深度合作，为用户提供美好的旅游旅行体验。我们积极打造AI友好型组织，使用AI等新技术提升旅游服务的供需匹配效率，更好满足用户个性化、多样化的出游需求。我们持续深耕产业链，用数字化服务助力实体商家高质量经营，探索自有品牌等供给新模式，打造健康的商家生态，保障用户服务体验。为满足用户日益增长的跨境旅行需求，我们将聚焦亚太区域，打造高品质的住宿、交通、游玩等服务矩阵。\n这里有多元的业务布局、持续的成长空间，无论是向往的远方还是眼前的工作，一路都是风景相伴。加入我们，共同为用户创造旅游旅行中的高光时刻！\n\n岗位职责\n1. 精准招商与生态构建：根据业务战略与区域供需缺口，制定服务商招募画像与拓新策略；负责寻找、沟通、引入具备强景区客情关系、丰富行业资源或强代运营能力的高质量服务商；\n2. 深度赋能与过程运营：为入驻服务商提供系统化的运营培训与落地方案，对其业绩负责，过程中盯紧服务商核心关键动作的落地，形成可复制的SOP并向全国推广；\n3. 政策落地与激励管理：推进平台服务商激励政策在负责区域的落地，确保“以利驱动，导向结果”，监控大盘数据，针对尾部服务商进行诊断纠偏或清退。\n\n岗位基本要求\n1. 3年以上互联网OTA旅游、本地生活等行业的渠道管理、服务商运营经验；有酒旅门票相关背景者优先。\n2. 出色的人际沟通能力、团队协作精神与团队建设能力；\n3. 有强大的自驱力和执行力，渴望成功；\n3. 能接受区域内长期出差。\n\n岗位亮点\n参与从0到1的生态体系建设，发展空间大\n团队氛围好，鼓励创新和互相分享","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4662939415","sourceKey":"meituan_social","company":"美团","title":"渠道经理（晋蒙区域）","city":"太原市/呼和浩特市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4662939415&jobShareType=1","duty":"1. 负责晋蒙区域渠道合作伙伴的开发、维护与管理，推动渠道销售目标的达成。  \n2. 制定并执行区域渠道拓展计划，挖掘潜在合作机会，提升渠道覆盖率和销售效率。  \n3. 协调内外部资源，为渠道伙伴提供产品培训、市场支持及销售工具，提升其业务能力。  \n4. 定期收集市场信息和渠道反馈，分析渠道运营数据，提出优化建议并推动落地。  \n5. 协助完成区域渠道政策、激励方案的宣导与执行，确保渠道生态健康发展。","requirements":"1. 大学本科及以上学历，专业不限。  \n2. 具备良好的沟通协调能力和商务谈判技巧。  \n3. 具备较强的学习能力和执行力，能够适应长期出差工作。  \n4. 有渠道管理、销售支持或相关实习经验者优先考虑。  \n5. 熟练使用办公软件，具备基础数据分析能力。\n6.有外卖、履约、零售、团购、广告销售等经验优先。","description":"部门介绍\n美团核心本地商业-下沉市场发展部于2015年成立，通过招募优质的合作商伙伴并对其业务经营能力、组织能力等赋能，以期为下沉城市提供一站式的本地生活服务。\n下沉市场发展部的业务场景涵盖了外卖餐饮、团购、拼好饭、闪购、医药等多元化的生活服务领域，同时搭建了一套稳定、高效的即时配送网络，为更多本地用户提供品质化、多样化、便捷高效的生活服务体验，为当地商户提供数字化发展机遇、提升数字化水平，为社会创造更多的就地就业机会。\n截至2024年6月，下沉市场发展部已开拓全国4000+县区市，帮助百万商户实现本地生活服务数字化，日订单量突破千万，为数十万名骑手提供就业岗位，让本地生活服务逐渐成长为地方新基建，实现美团“帮助大家吃得更好，生活更好”的使命！\n\n岗位职责\n1. 负责晋蒙区域渠道合作伙伴的开发、维护与管理，推动渠道销售目标的达成。  \n2. 制定并执行区域渠道拓展计划，挖掘潜在合作机会，提升渠道覆盖率和销售效率。  \n3. 协调内外部资源，为渠道伙伴提供产品培训、市场支持及销售工具，提升其业务能力。  \n4. 定期收集市场信息和渠道反馈，分析渠道运营数据，提出优化建议并推动落地。  \n5. 协助完成区域渠道政策、激励方案的宣导与执行，确保渠道生态健康发展。\n\n岗位基本要求\n1. 大学本科及以上学历，专业不限。  \n2. 具备良好的沟通协调能力和商务谈判技巧。  \n3. 具备较强的学习能力和执行力，能够适应长期出差工作。  \n4. 有渠道管理、销售支持或相关实习经验者优先考虑。  \n5. 熟练使用办公软件，具备基础数据分析能力。\n6.有外卖、履约、零售、团购、广告销售等经验优先。\n\n具备以下条件优先\n有外卖、履约、零售、团购、广告销售等经验优先。\n\n岗位亮点\n1. 提供完善的培训体系和职业发展通道。    \n2. 团队氛围开放包容，注重员工成长与能力提升。  \n3. 表现优异者有机会参与跨区域项目，拓展职业视野。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4674803176","sourceKey":"meituan_social","company":"美团","title":"训练系统专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4674803176&jobShareType=1","duty":"1. 负责自动驾驶模型训练效率与算法迭代效率方向的技术规划和团队管理，持续优化从实验提交、训练执行到评测结果产出的端到端周期；\n2. 负责大规模分布式训练性能优化，围绕计算、显存、通信、数据加载、存储等环节定位瓶颈，持续提升训练吞吐、GPU 利用率、扩展效率和训练产出；\n3. 建设和优化统一训练能力，包括但不限于分布式训练框架、训练 Profiling、故障诊断、Checkpoint/容错恢复、实验管理及性能回归分析等工具和平台能力；\n4. 深入感知、端到端、世界模型等算法研发流程，与算法、数据、存储和算力平台团队协作，推动重点模型训练效率专项并沉淀为通用能力；\n5. 建立训练效率和研发迭代效率指标体系，以训练耗时、任务成功率、资源利用率、实验迭代周期等指标衡量并持续改善平台效果；","requirements":"1. 计算机、人工智能、软件工程等相关专业本科及以上学历，具有机器学习系统、分布式训练或相关工程经验，有 Tech Lead 或小团队管理经验；\n2. 深入理解 PyTorch 等主流深度学习框架及分布式训练机制，熟悉 DDP、FSDP、DeepSpeed、Megatron-LM 等技术中的一种或多种；\n3. 熟悉 Linux、Python，并具备良好的系统开发能力；理解 CUDA、NCCL、RDMA、InfiniBand/RoCE、GPU 架构等相关技术；\n4. 具备较强的训练性能分析与系统优化能力、技术判断和跨团队推动能力，能够将单点性能问题抽象并沉淀为可复用的平台能力，对最终算法研发效率负责；","description":"部门介绍\n无人车业务部成立于2016年，旨在用无人驾驶技术提升物流配送的效率和体验。美团无人车以自研L4级自动驾驶软硬件技术为核心，与美团即时零售业务结合，形成满足公开道路、社区、工业园区等室外全场景下的无人配送整体解决方案。自2020年起，无人车已在北京、深圳等多地进入常态化试运营阶段，在城市复杂场景下提供针对餐饮外卖、生鲜食杂等货物的即时配送服务。2025年，美团无人车又踏上了同城货运的新探索，并在2026年持续扩大运营范围和车队数量，为更多城市带来智能配送服务。\n欢迎加入美团无人车团队，与我们一起用科技推动即时零售再升级！\n\n岗位职责\n1. 负责自动驾驶模型训练效率与算法迭代效率方向的技术规划和团队管理，持续优化从实验提交、训练执行到评测结果产出的端到端周期；\n2. 负责大规模分布式训练性能优化，围绕计算、显存、通信、数据加载、存储等环节定位瓶颈，持续提升训练吞吐、GPU 利用率、扩展效率和训练产出；\n3. 建设和优化统一训练能力，包括但不限于分布式训练框架、训练 Profiling、故障诊断、Checkpoint/容错恢复、实验管理及性能回归分析等工具和平台能力；\n4. 深入感知、端到端、世界模型等算法研发流程，与算法、数据、存储和算力平台团队协作，推动重点模型训练效率专项并沉淀为通用能力；\n5. 建立训练效率和研发迭代效率指标体系，以训练耗时、任务成功率、资源利用率、实验迭代周期等指标衡量并持续改善平台效果；\n\n岗位基本要求\n1. 计算机、人工智能、软件工程等相关专业本科及以上学历，具有机器学习系统、分布式训练或相关工程经验，有 Tech Lead 或小团队管理经验；\n2. 深入理解 PyTorch 等主流深度学习框架及分布式训练机制，熟悉 DDP、FSDP、DeepSpeed、Megatron-LM 等技术中的一种或多种；\n3. 熟悉 Linux、Python，并具备良好的系统开发能力；理解 CUDA、NCCL、RDMA、InfiniBand/RoCE、GPU 架构等相关技术；\n4. 具备较强的训练性能分析与系统优化能力、技术判断和跨团队推动能力，能够将单点性能问题抽象并沉淀为可复用的平台能力，对最终算法研发效率负责；\n\n具备以下条件优先\n1. 自动驾驶、机器人、具身智能、端到端驾驶、世界模型或大规模多模态模型训练经验；\n2. 有千卡级及以上 GPU 分布式训练、模型并行、低精度训练或大规模训练稳定性优化经验；\n3. 有 CUDA Kernel、Triton、自定义算子、编译优化或通信优化相关经验；\n\n岗位亮点\n1. 深度参与下一代自动驾驶基础模型（Foundation Model）与 AI Native 自动驾驶体系建设，探索多模态大模型、世界模型（World Model）、强化学习与生成式 AI 在真实复杂场景中的产业化落地；\n2. 面向千万级数据规模与超大规模算力集群，建设业界一流的 ML Infra 平台，覆盖数据闭环、分布式训练、仿真验证、模型部署与持续迭代全链路；\n3. 与自动驾驶算法、系统软件、芯片及云计算团队协同工作，在多学科交叉环境中解决真实世界复杂工程问题；","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4220546211","sourceKey":"meituan_social","company":"美团","title":"小象超市-数据分析专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4220546211&jobShareType=1","duty":"1.业务分析：深入参与并理解业务，根据业务发展需求，跟进重点策略专题，为时效、效率、体验、绩效考核等核心方向提供及时有效的分析结果和策略方案，推动业务发展及目标达成。\n2.复杂数据处理：负责配送业务相关数据提取、分析、以及数据产品的需求对接，包括考核核算、站点难度模型、补贴奖励及其他临时数据分析需求。\n3.指标体系完善：基于对业务及核心策略理解的深入性及全面性，协同业务团队持续迭代业务指标体系，保证指标体系的完整、有效、准确。\n4.数据体系建设：基于各方数据需求调研，建设数据报表体系，满足业务看书需求；基于业务调研，推动数据产品建设匹配管理体系的线上化数据产品，提升管理的及时性","requirements":"1.本科及以上学历，3年及以上策略运营、数据分析、商业分析经验。\n2.具备良好的逻辑分析能力和系统性思维能力，沟通表达能力优秀。\n3.具备扎实的数据处理及分析能力，具备数据可视化能力，熟练掌握sql/python/R等数据分析工具。\n4.自我驱动，对工作结果交付有高度责任心，积极主动且善于团队合作。\n5.有零售、配送、物流行业经验者优先。\n6.掌握基本的AI工具，使用工具提升工作流程效率。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1.业务分析：深入参与并理解业务，根据业务发展需求，跟进重点策略专题，为时效、效率、体验、绩效考核等核心方向提供及时有效的分析结果和策略方案，推动业务发展及目标达成。\n2.复杂数据处理：负责配送业务相关数据提取、分析、以及数据产品的需求对接，包括考核核算、站点难度模型、补贴奖励及其他临时数据分析需求。\n3.指标体系完善：基于对业务及核心策略理解的深入性及全面性，协同业务团队持续迭代业务指标体系，保证指标体系的完整、有效、准确。\n4.数据体系建设：基于各方数据需求调研，建设数据报表体系，满足业务看书需求；基于业务调研，推动数据产品建设匹配管理体系的线上化数据产品，提升管理的及时性\n\n岗位基本要求\n1.本科及以上学历，3年及以上策略运营、数据分析、商业分析经验。\n2.具备良好的逻辑分析能力和系统性思维能力，沟通表达能力优秀。\n3.具备扎实的数据处理及分析能力，具备数据可视化能力，熟练掌握sql/python/R等数据分析工具。\n4.自我驱动，对工作结果交付有高度责任心，积极主动且善于团队合作。\n5.有零售、配送、物流行业经验者优先。\n6.掌握基本的AI工具，使用工具提升工作流程效率。\n\n具备以下条件优先\n具备SQL/python//R等数据分析技能者优先\n\n岗位亮点\n接触前置仓、即时配两端数据及策略工作。当前业务运营策略化、精细化进程加快，与一线高频互动场景，具备足够的做事与认知升级空间。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3246787138","sourceKey":"meituan_social","company":"美团","title":"技术社区运营（大模型评测方向）","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3246787138&jobShareType=1","duty":"1. 围绕评测社区开展相关社群活动，负责活跃社群用户增加社群的粘性，同时对大模型有相关了解，可通过课程及文档撰写提升用户数据产出质量\n2. 参与全平台自媒体运营，做用户稿件的筛选和优化，增加平台的媒体声量创造更大的流量池\n3. 负责和知名教授，机构，企业沟通，邀请评测方案贡献和参与模型评测，负责相关的线下高校宣传，并挖掘更多高校合作和宣传资源，促成资源合作完成用户转化\n4. 总结和分析平台的粉丝锚点数据，分析用户流量来源并完成方法论及迭代策略\n5. 可根据要求独立完成稿件文案及图片创作，并且可以创作高质量视频内容","requirements":"1.本科及以上学历，3年以上产品运营/用户运营相关经验\n2. 有社群运营经验，通过不同媒体渠道能实现用户转化，基于用户兴趣和各类创新玩法，带动用户留存和活跃\n3. 对内容社区有热情，内容灵敏度高善于挖掘高热度内容，文案能力强，可创造破圈内容和玩法\n4. 熟练掌握图像、视频编辑软件，可通过AI产品提升内容创作效率","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n1. 围绕评测社区开展相关社群活动，负责活跃社群用户增加社群的粘性，同时对大模型有相关了解，可通过课程及文档撰写提升用户数据产出质量\n2. 参与全平台自媒体运营，做用户稿件的筛选和优化，增加平台的媒体声量创造更大的流量池\n3. 负责和知名教授，机构，企业沟通，邀请评测方案贡献和参与模型评测，负责相关的线下高校宣传，并挖掘更多高校合作和宣传资源，促成资源合作完成用户转化\n4. 总结和分析平台的粉丝锚点数据，分析用户流量来源并完成方法论及迭代策略\n5. 可根据要求独立完成稿件文案及图片创作，并且可以创作高质量视频内容\n\n岗位基本要求\n1.本科及以上学历，3年以上产品运营/用户运营相关经验\n2. 有社群运营经验，通过不同媒体渠道能实现用户转化，基于用户兴趣和各类创新玩法，带动用户留存和活跃\n3. 对内容社区有热情，内容灵敏度高善于挖掘高热度内容，文案能力强，可创造破圈内容和玩法\n4. 熟练掌握图像、视频编辑软件，可通过AI产品提升内容创作效率\n\n具备以下条件优先\n对大模型有深入了解、成功应用者优先\n有AI领域自媒体高质量内容创作或账号孵化经验优先\n\n岗位亮点\n1. 紧跟人工智能行业的前沿进展，接触到新的技术和行业趋势，磨练出对人工智能的独到见解\n2. 参与AI模型评测流程，了解从理论到工程实践的全面技能\n3. 与一流的人工智能团队合作，快速成长，提升自身能力\n4. 有机会参与公司的创新项目，跨足不同领域，拓宽人工智能技术的应用范围","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3287465663","sourceKey":"meituan_social","company":"美团","title":"交易系统平台-商品中心-Agent研发工程师","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3287465663&jobShareType=1","duty":"1. 参与商品标准化业务的迭代与创新，支撑闪购、外卖、医药等业务线的同品识别、品码一致性判别、类目治理等核心能力建设。  \n2. 参与 AI Agent 工作流的工程化落地，推动 AI 能力在商品治理场景的规模化应用。  \n3. 参与商品平台化系统的设计开发，抽象沉淀领域模型与平台能力，承担核心模块开发工作。  \n4. 解决各类系统技术风险，保障大促高并发场景下的系统稳定性。  \n5. 持续以自动化、系统化方式提升效率和质量。","requirements":"1. 大学本科及以上学历，计算机相关专业，2年以上Java开发经验。  \n2. 对 AI 感兴趣，愿意积极学习 AI 和 Agent 相关技术。  \n3. 熟悉DDD、微服务设计、服务治理等方法论，有互联网高并发处理和性能优化经验。  \n4. 能独立负责业务模块设计与开发，有定位和处理线上问题的丰富经验。  \n5. 有较强的逻辑思维和问题拆解能力，善于分析、归纳和沟通。","description":"部门介绍\n美团核心本地商业下业务研发平台，基于公司“零售+科技”的战略导向，通过从底层架构到应用系统、从软件到硬件、从传统算法到GenAI的全方位技术研究，以及开发、运维、安全等全流程能力建设，致力于推动美团核心本地商业下需求侧与供给侧的数字化和智能化升级，助力业务实现高质量增长，优化用户使用体验，提升商户经营水平，促进行业生态伙伴关系的持续健康发展。团队秉持务实、自驱、开放以及追求卓越的工程师文化，一方面通过系统和技术体系的持续迭代升级，帮助业务高质量增长；另一方面，密切关注前沿技术趋势变化，积极创新技术能力，为业务未来发展创造新的可能性。期待优秀的你加入我们，在夯实专业、深耕平台的基础上与业务携手同行，一起用技术 “帮大家吃得更好，生活更好”。\n\n岗位职责\n1. 参与商品标准化业务的迭代与创新，支撑闪购、外卖、医药等业务线的同品识别、品码一致性判别、类目治理等核心能力建设。  \n2. 参与 AI Agent 工作流的工程化落地，推动 AI 能力在商品治理场景的规模化应用。  \n3. 参与商品平台化系统的设计开发，抽象沉淀领域模型与平台能力，承担核心模块开发工作。  \n4. 解决各类系统技术风险，保障大促高并发场景下的系统稳定性。  \n5. 持续以自动化、系统化方式提升效率和质量。\n\n岗位基本要求\n1. 大学本科及以上学历，计算机相关专业，2年以上Java开发经验。  \n2. 对 AI 感兴趣，愿意积极学习 AI 和 Agent 相关技术。  \n3. 熟悉DDD、微服务设计、服务治理等方法论，有互联网高并发处理和性能优化经验。  \n4. 能独立负责业务模块设计与开发，有定位和处理线上问题的丰富经验。  \n5. 有较强的逻辑思维和问题拆解能力，善于分析、归纳和沟通。\n\n具备以下条件优先\n具备大模型、Agent相关项目经验者优先\n\n岗位亮点\n1. AI深度落地场景，直接参与从AI实验到规模化生产的全过程。  \n2. 业务价值直观，优化直接影响大促限购拦截、资损防控等核心业务指标。  \n3. 海量数据与高并发挑战，午高峰QPS近百万，日均订单量过千万。  \n4. 有机会全身心参与本地商业商品标准化的演进，体验AI重塑传统业务流程的全过程。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4661181620","sourceKey":"meituan_social","company":"美团","title":"廉正监察调查专家","city":"北京市/深圳市/广州市/成都市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4661181620&jobShareType=1","duty":"1.识别廉正领域的风险，及时发现问题线索。\n2.通过现场调查和桌面调查等方式，详尽还原事实细节，全面揭示问题本质。\n3.与其他协同部门紧密合作，共同推动企业廉正风险的有效治理。","requirements":"1.人品正直，行为公正，能够严守职业道德。\n2.在现场调查或桌面调查方面具备扎实的专业技能和丰富的实践经验。","description":"部门介绍\n美团廉正监察团队致力于维护公司的廉正准则，和大家一起培育包容、简单、可信的职场环境及合作生态。为进一步强化我们的团队，我们诚邀优秀人才加入，共同打造企业廉正监察领域的TOP Team —— 可靠（Trustworthy）、客观（Objective）、专业（Professional）的团队。\n\n岗位职责\n1.识别廉正领域的风险，及时发现问题线索。\n2.通过现场调查和桌面调查等方式，详尽还原事实细节，全面揭示问题本质。\n3.与其他协同部门紧密合作，共同推动企业廉正风险的有效治理。\n\n岗位基本要求\n1.人品正直，行为公正，能够严守职业道德。\n2.在现场调查或桌面调查方面具备扎实的专业技能和丰富的实践经验。\n\n具备以下条件优先\n具有5年以上在财务审计、数据分析、社会调查或商业调查等相关领域的工作经验者优先。\n\n岗位亮点\n1.有价值：参与大型企业治理，成为行业紧缺的ESG人才。\n2.有成长：团队管理扁平，鼓励个人学习成长，工作氛围开放包容。\n3.有机会：可与多个关键部门合作，拓展职业网络。\n4.有意义：通过促进大型企业廉正水平提升，对社会产生积极影响。\n团队积极拥抱AI工具，鼓励用AI提升工作效率，你将有机会在工作中探索AI应用的边界","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4631784833","sourceKey":"meituan_social","company":"美团","title":"KA大客户经理","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4631784833&jobShareType=1","duty":"1.负责制定和执行大客户业务拓展计划，完成销售目标。\n2.负责管理大客户关系，维护客户忠诚度，提高客户满意度。\n3.负责团队的日常管理和指导，确保团队业绩达标。\n4.负责与内部各部门协作，保障项目顺利推进。","requirements":"1.大学本科及以上学历，市场营销、商务管理等相关专业优先。\n2.具备3年以上大客户销售、业务拓展经验，有团队管理经验者优先。\n3.具备出色的沟通能力、谈判技巧和团队协作能力。\n4.对行业市场有深刻理解，具备较强的市场洞察力和商业敏感度。","description":"部门介绍\n美团服务零售事业部下设乐生活业务部、易生活业务部、进场零售业务部以及中小城市发展部四大业务部门，旨在通过提供丰富、可靠、实惠的服务与商品满足用户各类生活需求。我们所处的服务零售行业是一个具有万亿规模的市场，覆盖足疗洗浴、酒吧KTV、运动健身、美发美甲、教育培训、亲子游乐、家政洗涤维修、摄影写真等数十个服务消费细分领域，同时延伸至超市便利、美妆个护、3C数码、服饰珠宝、运动户外、商场购物中心等实体零售到店消费场景，连接数十万品牌商户与线下门店。作为商家和行业的小帮手，我们持续深入服务零售与实体零售产业链，用AI等技术推动行业变革，帮助商家提升经营效率、实现高效的线上化经营与到店转化，优化消费者服务体验，提供安心、放心的履约保障。这里有着多元的业务布局，有着富有挑战和影响力的工作内容，为你提供丰富的视野、持续的成长和发展机会，引领你发现更多可能。期待和你在“随时随地，美好生活”的愿景指引下，共建美好的生活服务体验、健康的商家生态与高质量的经营结果。\n\n岗位职责\n1.负责制定和执行大客户业务拓展计划，完成销售目标。\n2.负责管理大客户关系，维护客户忠诚度，提高客户满意度。\n3.负责团队的日常管理和指导，确保团队业绩达标。\n4.负责与内部各部门协作，保障项目顺利推进。\n\n岗位基本要求\n1.大学本科及以上学历，市场营销、商务管理等相关专业优先。\n2.具备3年以上大客户销售、业务拓展经验，有团队管理经验者优先。\n3.具备出色的沟通能力、谈判技巧和团队协作能力。\n4.对行业市场有深刻理解，具备较强的市场洞察力和商业敏感度。\n\n岗位亮点\n1.有机会挑战高级职级，发展空间大。\n2.可以接触到各种大型客户，拓展人脉关系。\n3.团队氛围好，工作氛围轻松活泼。","jdComplete":true,"sourceStatus":"000"}];
